def _diff_file_summary(diff: str) -> tuple[int, list[tuple[str, int, int]]]:
    """Return (total_lines, per_file_stats) from a unified diff.

    ``per_file_stats`` is a list of ``(filename, added, deleted)`` tuples.
    ``total_lines`` counts content lines (not diff headers/meta lines).
    """
    files: list[tuple[str, int, int]] = []
    current_file = ""
    added = 0
    deleted = 0
    total = 0
    for line in diff.splitlines():
        if line.startswith("diff --git"):
            if current_file:
                files.append((current_file, added, deleted))
            current_file = ""
            added = 0
            deleted = 0
        elif line.startswith("+++ "):
            current_file = line[4:].strip()
            if current_file == "/dev/null":
                current_file = ""
        elif line.startswith("--- "):
            # Use the source file if the dest is /dev/null (deletion)
            if not current_file:
                current_file = line[4:].strip()
                if current_file == "/dev/null":
                    current_file = ""
        elif line.startswith("+") and not line.startswith("+++"):
            added += 1
            total += 1
        elif line.startswith("-") and not line.startswith("---"):
            deleted += 1
            total += 1
    if current_file:
        files.append((current_file, added, deleted))
    return total, files


def _max_touched_file_line_count(diff: str, repo_root: Path) -> int:
    """Return the largest line count among files touched by ``diff`` (issue #1439).

    The review turn cap scales with the size of the files a diff touches, not
    the diff itself: a PR threading a 25k-line monolith costs the reviewer far
    more grep -> Read-window navigation than the diff's line count suggests.
    File sizes are read from ``repo_root`` (the orchestrator's checkout). For
    files not present there (e.g. newly added in the PR), the per-file added
    line count from the diff is used as the size -- a new file's size IS its
    added lines. Returns 0 for an empty diff.
    """
    _total, files = _diff_file_summary(diff)
    max_lines = 0
    for name, added, _deleted in files:
        if not name:
            continue
        candidate = name
        # Unified diff ``+++`` paths are prefixed with ``b/``; strip it so the
        # path resolves under ``repo_root``. A literal ``b/...`` file would be
        # vanishingly rare and only makes the lookup miss (falling back to the
        # added-line count), never reads the wrong file.
        if candidate.startswith("b/"):
            candidate = candidate[2:]
        path = repo_root / candidate
        line_count = 0
        if path.exists() and path.is_file():
            try:
                with path.open("r", encoding="utf-8", errors="replace") as handle:
                    line_count = sum(1 for _ in handle)
            except OSError:
                line_count = 0
        else:
            # New file (not present at repo_root): its size is the added lines.
            line_count = added
        if line_count > max_lines:
            max_lines = line_count
    return max_lines


@dataclass(frozen=True)
class OverCapFileFinding:
    """One file whose post-diff line count exceeds the repo size cap and whose
    diff adds code to it (issue #1445).

    ``line_count`` is the post-diff line count (base file at ``repo_root`` plus
    the diff's net added lines, or the added-line count for a new file).
    ``added_lines`` is the diff's gross added content lines for this file --
    the quantity the rubric flags as "new code added to an over-cap file".
    """

    filename: str
    line_count: int
    cap: int
    added_lines: int


def _over_cap_file_findings(
    diff: str, repo_root: Path, cap: int
) -> tuple[OverCapFileFinding, ...]:
    """Detect files this diff adds code to that are over the repo size cap.

    Returns findings only for files that (a) have at least one added content
    line in the diff and (b) whose post-diff line count exceeds ``cap``. A
    ``cap`` of 0 disables the check (returns ``()``) -- mirrors
    ``turn_cap_large_file_threshold``'s 0-disables convention.

    File sizes are read from ``repo_root`` (the orchestrator's checkout) plus
    the diff's net added lines, mirroring ``_max_touched_file_line_count``; a
    new file's size is its added lines. Best-effort: a file that cannot be read
    is skipped, never raises -- the same posture as the static probe and
    ``check_operator_containment``.
    """
    if cap <= 0:
        return ()
    _total, files = _diff_file_summary(diff)
    findings: list[OverCapFileFinding] = []
    for name, added, deleted in files:
        if not name or added <= 0:
            continue
        # Unified diff ``+++`` paths are prefixed with ``b/``; strip it so the
        # path resolves under ``repo_root`` and the reported filename is the
        # repo-relative path (not the diff's ``b/``-prefixed form). A literal
        # ``b/...`` file would be vanishingly rare and only makes the lookup
        # miss (falling back to the added-line count), never reads the wrong
        # file -- mirrors ``_max_touched_file_line_count``'s stance.
        filename = name[2:] if name.startswith("b/") else name
        path = repo_root / filename
        if path.exists() and path.is_file():
            try:
                with path.open("r", encoding="utf-8", errors="replace") as handle:
                    base = sum(1 for _ in handle)
            except OSError:
                continue
            line_count = base + added - deleted
        else:
            # New file (not present at repo_root): its size is the added lines.
            line_count = added
        if line_count > cap:
            findings.append(OverCapFileFinding(filename, line_count, cap, added))
    return tuple(findings)


def render_over_cap_section(findings: tuple[OverCapFileFinding, ...] | None) -> str:
    """Render the ``$over_cap_section`` packet block (issue #1445).

    Returns ``""`` when ``findings`` is ``None`` (cap disabled -- the caller in
    ``review()`` passes ``None`` when ``file_size_cap_lines`` is 0), mirroring
    ``render_static_probe_section``'s disabled contract. When enabled, this
    ALWAYS renders visible text -- even with zero findings -- rather than ``"``
    for a clean pass, mirroring ``render_static_probe_section``'s never-silent
    contract: an advisory probe that goes silent on a clean run is
    indistinguishable, from the rendered packet alone, from one that never ran.
    """
    if findings is None:
        return ""
    if not findings:
        return "File-size cap: no over-cap additions in this diff.\n"
    lines = ["**Over-cap file additions (issue #1445):**"]
    for finding in findings:
        lines.append(
            f"- `{finding.filename}`: {finding.line_count} lines "
            f"(cap {finding.cap}), +{finding.added_lines} added -- "
            "REPORTABLE FINDING. Suggested remedy: extract the new code to a "
            "domain module (facade re-export block in the monolith, "
            "implementation in the module), matching the #1283-era extractions."
        )
    return "\n".join(lines) + "\n"


def structure_turn_cap_multiplier(
    max_touched_file_lines: int, config: ReviewDispatchConfig
) -> int:
    """Structure-aware multiplier for the review turn cap (issue #1439).

    Returns ``turn_cap_large_file_multiplier`` (clamped to
    ``turn_cap_max_multiplier``) when ``max_touched_file_lines`` exceeds
    ``turn_cap_large_file_threshold``, else 1. A threshold of 0 disables the
    structure bonus (every diff uses the base cap).
    """
    threshold = config.turn_cap_large_file_threshold
    if threshold <= 0:
        return 1
    if max_touched_file_lines > threshold:
        return min(config.turn_cap_large_file_multiplier, config.turn_cap_max_multiplier)
    return 1


def resolve_review_turn_cap(
    base_max_turns: int,
    structure_multiplier: int,
    miss_streak: int,
    config: ReviewDispatchConfig,
) -> int:
    """Final reviewer turn cap after structure + miss-escalation (issue #1439).

    ``effective_multiplier = min(structure_multiplier + miss_streak,
    turn_cap_max_multiplier)``, clamped to a floor of 1.
    ``final_cap = base_max_turns * effective_multiplier``. A ``base_max_turns``
    of 0 (unlimited) stays 0.
    """
    if base_max_turns <= 0:
        return 0
    effective = min(
        max(structure_multiplier + miss_streak, 1),
        config.turn_cap_max_multiplier,
    )
    return base_max_turns * effective


def _diff_size_section(diff: str, threshold: int, diff_path: Path) -> str:
    """Return a prompt section warning about large diffs, or empty string.

    When the diff exceeds ``threshold`` content lines, this returns a Markdown
    section with a per-file summary and instructions to read the diff
    file-by-file rather than in one shot. When the diff is small or the
    threshold is 0, returns an empty string.
    """
    if threshold <= 0:
        return ""
    total, files = _diff_file_summary(diff)
    if total <= threshold:
        return ""
    lines = [
        "",
        "## Large diff guidance",
        "",
        f"This diff has {total} changed lines across {len(files)} file(s). "
        f"Do **not** read the entire diff in one pass — it will waste your "
        f"token budget. Instead, read `$diff_path` file-by-file, starting "
        f"with the files that have the most changes.",
        "",
        "| File | + | - |",
        "|------|---|---|",
    ]
    for name, add, dele in sorted(files, key=lambda x: x[1] + x[2], reverse=True):
        lines.append(f"| `{name}` | +{add} | -{dele} |")
    lines.append("")
    return "\n".join(lines)


# Fields the reviewer actually needs from pr.json. Excludes large fields that
# bloat the reviewer's context without aiding the review: ``comments`` (can be
# huge on active PRs), ``statusCheckRollup`` (separate checks.json is written),
# and ``createdAt``/``updatedAt`` (not used by the review rubric).
_PR_SLIM_FIELDS: frozenset[str] = frozenset(
    {
        "number",
        "title",
        "url",
        "body",
        "headRefOid",
        "baseRefName",
        "headRefName",
        "isDraft",
        "state",
        "labels",
        "author",
        "additions",
        "deletions",
        "mergeable",
        "mergeStateStatus",
        "isCrossRepository",
        "reviewDecision",
    }
)


def _slim_pr_json(pr: dict[str, Any]) -> dict[str, Any]:
    """Return a copy of ``pr`` with only the fields the reviewer needs.

    Strips ``comments``, ``statusCheckRollup``, ``createdAt``, ``updatedAt``
    and other large fields that inflate the reviewer's token budget without
    aiding the review. The full PR data is not needed by the reviewer prompt
    (which references the file path, not inline content), and the reviewer
    reads the diff from ``diff.patch`` and checks from ``checks.json``.
    """
    return {k: v for k, v in pr.items() if k in _PR_SLIM_FIELDS}


@dataclass(frozen=True)
class CommandResult:
    ok: bool
    message: str
    data: dict[str, Any]


def _state_lock_busy_result(message: str, **extra: Any) -> CommandResult:
    data: dict[str, Any] = {
        "pass_skipped": True,
        "reason": "state_lock_busy",
        "state_lock_busy": True,
    }
    data.update(extra)
    return CommandResult(True, message, data)


def _truncate_reason(reason: str, max_len: int = 200) -> str:
    if len(reason) <= max_len:
        return reason
    return reason[: max_len - 3] + "..."


def _dispatch_failure_reason(result: SessionDispatchResult) -> str:
    if result.error:
        return result.error
    if result.failure_kind:
        return f"dispatch failed: {result.failure_kind}"
    return "dispatch failed"


def _label_error_reason(label_error: dict[str, Any]) -> str:
    """Format a persisted label_error dict into a short, human-readable reason."""
    edge = label_error.get("edge", "unknown")
    outcome = label_error.get("outcome", "unknown")
    add_failures = label_error.get("add_failures") or []
    remove_failures = label_error.get("remove_failures") or []
    add_labels = [label for _issue, label in add_failures]
    remove_labels = [label for _issue, label in remove_failures]
    parts = [f"label transition '{edge}' {outcome}"]
    if add_labels:
        parts.append(f"add failures: {add_labels}")
    if remove_labels:
        parts.append(f"remove failures: {remove_labels}")
    return "; ".join(parts)


def _parse_iso_timestamp(value: Any) -> datetime | None:
    """Parse an ISO 8601 timestamp from state.json into a timezone-aware datetime."""
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.replace(tzinfo=UTC) if value.tzinfo is None else value
    if not isinstance(value, str):
        return None
    ts = value.replace("Z", "+00:00")
    try:
        parsed = datetime.fromisoformat(ts)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=UTC)
    return parsed


def _recent_dispatch_failed_attempts(
    entry: dict[str, Any], now: datetime, window_minutes: int
) -> list[str]:
    """Return ``dispatch_failed_at`` entries inside the redispatch window."""
    attempts = entry.get("dispatch_failed_at") or []
    if not isinstance(attempts, (list, tuple)):
        return []
    window_start = now - timedelta(minutes=window_minutes)
    recent: list[str] = []
    for value in attempts:
        ts = _parse_iso_timestamp(value)
        if ts is not None and ts >= window_start:
            recent.append(value)
    return recent


# No leading underscore: this is a deliberate cross-module wire contract
# with fleet_dispatch._add_launch_failures, which matches this prefix to
# exclude concurrency-deferred issues from launch-failure attention events.
# Matching the reason string (rather than cross-referencing the
# `deferred_by_concurrency` list) is deliberate: that list is truncated to
# _MAX_DEFERRED_CONCURRENCY_EXAMPLES entries in the persisted payload
# (issue #1005), but this `failures` map is not -- a set-membership check
# against the truncated list would silently re-report the 6th+ deferred
# issue as a genuine launch failure.
DEFERRED_BY_CONCURRENCY_REASON_PREFIX = "deferred by concurrency cap"


def _build_failure_map(
    dispatch_results: Sequence[SessionDispatchResult],
    failed_issue_numbers: Iterable[int],
    deferred_by_concurrency: Iterable[int],
    limit: int,
    extra_failures: Mapping[int, str] | None = None,
) -> dict[int, str]:
    failures: dict[int, str] = {}
    for issue_number in deferred_by_concurrency:
        failures[issue_number] = _truncate_reason(
            f"{DEFERRED_BY_CONCURRENCY_REASON_PREFIX} (limit: {limit})"
        )
    for result in dispatch_results:
        if result.issue_number in failed_issue_numbers:
            failures[result.issue_number] = _truncate_reason(_dispatch_failure_reason(result))
    for issue_number, reason in (extra_failures or {}).items():
        failures[issue_number] = _truncate_reason(reason)
    return failures


def _guard_state_lock(func: Any) -> Any:
    """Decorator that turns StateLockBusy into a skipped CommandResult."""

    @functools.wraps(func)
    def wrapper(self: Any, *args: Any, **kwargs: Any) -> CommandResult:
        try:
            return func(self, *args, **kwargs)
        except StateLockBusy:
            return _state_lock_busy_result("state lock held, skipped")

    return wrapper


@dataclass(frozen=True)
class ConcurrencyGovernorResult:
    """Result of applying concurrency governor to a dispatch limit.

    This encapsulates the concurrency limiting logic and ensures all related
    fields are bound together, eliminating Pyright's reportPossiblyUnbound
    warnings for live_count.
    """

    clamped: bool
    max_concurrent: int
    live_count: int
    available_slots: int
    dispatch_limit: int
    fleet_live_count: int = 0
    fleet_max: int = 0
    # Issue #1129: open-PR backpressure fields. Populated only when the
    # governor was called with ``apply_open_pr_backpressure=True`` (fresh-issue
    # dispatch) and ``dispatch.max_open_agent_prs`` is > 0. Left at 0 for
    # rework/recovery/loop paths, which are exempt from this clamp.
    open_pr_count: int = 0
    open_pr_max: int = 0

    @property
    def enabled(self) -> bool:
        """Return True if the governor is enabled (max_concurrent > 0)."""
        return self.max_concurrent > 0

    @property
    def fleet_enabled(self) -> bool:
        """Return True if the fleet governor is enabled (fleet_max > 0)."""
        return self.fleet_max > 0

    @property
    def open_pr_enabled(self) -> bool:
        """Return True if the open-PR backpressure clamp is enabled (open_pr_max > 0)."""
        return self.open_pr_max > 0

    def report_fields(self) -> dict[str, int]:
        """Return the fields to include in CommandResult.data when clamped."""
        fields = {
            "concurrency_limit": self.max_concurrent,
            "live_session_count": self.live_count,
            "available_slots": self.available_slots,
        }
        if self.fleet_enabled:
            fields["fleet_concurrency_limit"] = self.fleet_max
            fields["fleet_live_session_count"] = self.fleet_live_count
        if self.open_pr_enabled:
            fields["open_pr_count"] = self.open_pr_count
            fields["open_pr_max"] = self.open_pr_max
        return fields


@dataclass(frozen=True)
class CarryForwardCheck:
    """Result of comparing a recorded review verdict's content against the
    live PR diff (issues #411/#412 tier 1, #414 tier 2).

    ``tier`` is ``"patch-id"`` when the live diff's stable patch-id matches
    the recorded ``reviewed_patch_id`` outright (issue #412's fast path),
    ``"line-content"`` when the patch-ids differed — which happens on every
    ordinary main advance, since the merge-base moves — but the ordered
    ``+``/``-`` line stream and changed-file set are identical to what was
    recorded at review time (issue #414), or ``None`` when neither tier
    establishes content identity: the caller must treat the verdict as
    stale. ``live_patch_id``/``live_signature`` are always populated (when
    the live diff was fetched) so a carrying-forward caller can persist the
    freshly computed baseline against the new head without recomputing it.
    """

    tier: str | None
    live_patch_id: str
    live_signature: DiffContentSignature

    @property
    def carry_forward(self) -> bool:
        return self.tier is not None


def _summary_is_vacuous(summary: str) -> bool:
    """True when ``summary`` carries no reviewer content.

    Covers a blank/whitespace-only string, and the historical
    ``LEGACY_VACUOUS_SUMMARY`` placeholder (issue #784) that pre-#784
    cross-family code emitted for a verdict that was, in fact, content-free.
    This is the single definition of "there is nothing here to act on",
    shared by two different callers at two different times:

    - ``_is_carry_forward_eligible`` (read-time): should an old, already-
      recorded verdict be reused across a content-identical head?
    - ``record_review`` (write-time, issue #792): is there anything to
      derive from ``summary`` into ``required_changes`` when the caller
      didn't supply a structured list?

    Deliberately does *not* do anything smarter than an equality check
    against one known, exported constant -- a referent/keyword classifier
    over free-form reviewer prose was evaluated and rejected (issue #792)
    because it misclassified genuine, specific findings (e.g. architectural
    gaps with no file/line reference, or "CI failed on Lint; push a fix")
    as content-free. The only text this function is entitled to call
    vacuous is text our *own* code emitted as a known placeholder, not text
    a reviewer wrote that merely looks terse or unstructured.
    """
    stripped = summary.strip()
    return not stripped or stripped == LEGACY_VACUOUS_SUMMARY


def _is_carry_forward_eligible(decision: dict[str, Any]) -> bool:
    """Reject carry-forward for a content-free cross-family verdict (issue #784, AC-8).

    ``review_queue`` reads recorded verdicts as plain dicts straight off
    ``review-decision.json`` (never through the ``CrossFamilyVerdict``
    constructor -- see ``_review_decision``), so this is a data-shape check,
    not a dataclass reconstruction: it must never raise on the 8 pre-#784
    on-disk records this predicate exists to catch, which is exactly the
    deserialization hazard flagged during this fix's design.

    A verdict is ineligible only when it is unmistakably a product of the
    pre-#784 bug: ``decision == "request_changes"`` with no itemized
    ``required_changes`` AND a vacuous summary (see ``_summary_is_vacuous``).
    A primary reviewer's ``request_changes`` verdict always has a non-empty,
    non-placeholder summary (``record_review`` rejects an empty one
    outright), so this predicate cannot mistake a legitimate primary-review
    decision -- one that simply chose prose over an itemized list -- for a
    vacuous one. Everything else (``approved``, ``blocked``, populated
    ``required_changes``, or a real summary) is eligible, unchanged from
    before this fix.
    """
    if decision.get("decision") != "request_changes":
        return True
    if decision.get("required_changes"):
        return True
    return not _summary_is_vacuous(str(decision.get("summary") or ""))


# Statuses that mean an issue already has a rework routed (or an equivalent
# gate) in flight, or is otherwise spoken for -- shared by every "should I
# route this PR to rework_requested" check so they cannot drift apart.
# Originally the cross-PR-revert gate in ``merge_ready`` (below); issue #784
# AC-8 Case 2 reuses it verbatim for ``review_queue``'s stranded-verdict
# check rather than inventing a second list.
_REWORK_ALREADY_ROUTED_STATUSES = (
    "escalated",
    "blocked",
    "dispatched",
    "dispatch_pending",
    "manifest_written",
    "rework_requested",
)


def _janitor_section(warnings: tuple[str, ...]) -> str:
    if not warnings:
        return ""
    lines = "\n".join(f"- {warning}" for warning in warnings)
    return (
        "\n## Janitor warnings (non-blocking)\n\n"
        f"{lines}\n\n"
        "These deterministic pre-checks passed the gate but deserve reviewer attention.\n"
    )


def render_test_adequacy_section(
    facts: TestAdequacyFacts | None, warnings: tuple[str, ...]
) -> str:
    """Render the $test_adequacy_section packet block from Tier-1 facts.

    Returns "" when facts is None (gate disabled — caller in review() passes
    None in that case) or when there is nothing to report. Mirrors the
    _janitor_section pattern: plain function, no I/O, safe to call every pass.
    """
    if facts is None:
        return ""
    lines = [
        "## Test-adequacy facts (Tier 1, deterministic)",
        "",
        f"- Added product LOC: {facts.added_product_loc}",
        f"- Added test LOC: {facts.added_test_loc}",
        f"- Assertion-bearing added test lines: {facts.assertion_count}",
        f"- Test files changed: {facts.test_files_changed}",
    ]
    if facts.untested_product_files:
        lines.append("- Untested product files: " + ", ".join(facts.untested_product_files))
    if facts.exempt:
        lines.append(f'- Test-exempt claim: "{facts.exempt_reason}" (verify against the diff)')
    if warnings:
        lines.append("")
        lines.extend(f"- {warning}" for warning in warnings)
    lines.append("")
    return "\n".join(lines)


def render_test_adequacy_summary(verdict: TestAdequacyVerdict, exempt_marker: str) -> str:
    """Render a test-adequacy hard-fail verdict as actionable reviewer feedback.

    This summary is passed to record_review as the review summary, which is
    rendered into rework.md. It must read as actionable feedback, not a raw
    dataclass dump.

    Args:
        verdict: The hard-fail TestAdequacyVerdict (ok=False).
        exempt_marker: The exempt marker string from config (e.g., "Test-exempt:").

    Returns:
        A non-empty templated string with untested product files and exemption
        instruction.
    """
    facts = verdict.facts
    untested_files = facts.untested_product_files
    added_loc = facts.added_product_loc

    # Build file list with LOC counts
    file_list = "\n".join(f"  - {file}" for file in untested_files)

    return (
        f"Test adequacy check failed: {added_loc} lines of product code added "
        f"but no test files changed.\n\n"
        f"Untested product files:\n{file_list}\n\n"
        f"To exempt this PR from the test-adequacy gate, add "
        f"'{exempt_marker} <reason>' to the PR body with a clear justification."
    )


def render_static_probe_section(verdict: StaticProbeVerdict | None) -> str:
    """Render the $static_probe_section packet block from a StaticProbeVerdict.

    Returns "" when ``verdict`` is None (probe disabled -- the caller in
    review() passes None in that case), mirroring
    ``render_test_adequacy_section``'s disabled contract.

    When enabled, this ALWAYS renders visible text -- even with zero findings
    and zero warnings -- rather than "" for a clean pass. This mirrors
    render_test_adequacy_section's own behavior of never going silent once
    its gate is enabled (that function always shows its facts block
    regardless of whether there is a problem to report): an advisory probe
    that goes silent on a clean run is indistinguishable, from the rendered
    packet alone, from one that never ran at all (issue #1260/#1261 design
    item 7's "zero-reads-as-green" concern applies to the clean case too,
    not only to internal errors).
    """
    if verdict is None:
        return ""

    lines: list[str] = []
    if verdict.warnings:
        lines.extend(f"- {warning}" for warning in verdict.warnings)

    if verdict.branch_findings:
        if lines:
            lines.append("")
        lines.append("**Branch-coverage heuristic (W3):**")
        for finding in verdict.branch_findings:
            reason = (
                "no added test/assertion lines in this diff"
                if finding.reason == "no_test_adds"
                else f"branch:test-add ratio high ({finding.branch_adds}:{finding.test_adds})"
            )
            lines.append(f"- `{finding.filename}`: {finding.branch_adds} branch-adds, {reason}")

    if verdict.unwired_findings:
        if lines:
            lines.append("")
        lines.append("**Unwired-symbol probe (W20):**")
        for finding in verdict.unwired_findings:
            lines.append(
                f"- `{finding.symbol}` ({finding.kind}) in `{finding.filename}`: referenced "
                "only from tests/, no src/ caller found"
            )

    if not lines:
        return "Static probe: no findings.\n"

    return "\n".join(lines) + "\n"


def slugify(value: str, *, max_length: int = 48) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
    slug = re.sub(r"-+", "-", slug)
    return slug[:max_length].rstrip("-") or "work"


# Maximum per-worktree skip entries carried in the persisted
# `worktrees_reclaimed` event payload. Same idiom as
# `_MAX_DEFERRED_CONCURRENCY_EXAMPLES`: a full count (`skipped_count`) alongside a
# truncated example list (`skipped_examples`), so a standing backlog of
# stuck worktrees doesn't re-emit the full list into events.db every
# interval, while a normal-sized backlog still carries every reason string
# through (issue #1012 -- clean_worktrees computes a distinct `reason` per
# skip but the event used to keep only `skipped_count`).
_MAX_SKIPPED_WORKTREE_EXAMPLES = 20

# Bound on concurrent `gh` subprocesses spawned by _prefetch_blocker_data() to
# warm the dependency cache across every ready issue. I/O-bound fan-out width,
# not a CPU budget; kept modest to stay clear of GitHub's secondary rate
# limits. See issue #870.
_MAX_PREFETCH_WORKERS = 8


# state.json key holding the one-time record of worker-PR merges that predate the
# #502 post-merge tripwire. Named here rather than inlined so the arming logic and
# the tests that pre-arm it cannot drift apart on a string literal.
UNAUTHORIZED_MERGE_BASELINE_KEY = "unauthorized_merge_baseline"

# state.json key holding the ongoing acknowledgment set for post-arming
# unauthorized-merge findings (issue #673). The baseline (#510) suppresses
# *pre-arming* history once; this set suppresses *post-arming* findings that a
# human or automated remediation has explicitly triaged, so a confirmed,
# already-actioned finding stops pinning ok=False on every subsequent pass.
# Like the baseline it is an explicit set of PR numbers (never a high-water
# mark) and is only ever populated by an explicit `charlie tripwire ack` action
# — the tripwire never auto-acknowledges, or it would defeat itself.
UNAUTHORIZED_MERGE_ACK_KEY = "unauthorized_merge_acknowledged"

# state.json key holding the durable first-detection record for post-arming
# unauthorized-merge findings (issue #933). A `{pr_number: {detected_at, head,
# issue, decision, ...}}` map, written the first time a finding is reported and
# not rewritten while the finding stays open, so the
# `unauthorized_merge_detected` event fires exactly once per PR instead of once
# per pass. `ack_unauthorized_merge` deletes the entry, so the map holds
# *currently-open announced findings* — bounded by the open set, not growing
# with every PR ever found, and a finding re-detected after its ack is withdrawn
# announces again instead of returning silently.
#
# Once-per-PR is the whole point. The tripwire re-detects the same unacked
# finding on every pass — that is the 21-pass ok=False streak #933 was filed on
# — so a per-pass event would be a second unbounded stream restating one fact
# indefinitely, which is the "a control that can never go quiet is not a
# control" failure the baseline and the ack set both exist to prevent.
#
# This is a *record*, not a suppressor: unlike the baseline and the ack set it
# is never consulted by `_apply_unauthorized_merge_baseline`, so a finding
# stays reported (and keeps pinning ok=False) until it is explicitly acked.
# Presence here silences the event, never the finding.
UNAUTHORIZED_MERGE_DETECTED_KEY = "unauthorized_merge_detected"


# Issue #934: an operator who legitimately adjudicates and merges a worker PR
# whose recorded review decision is stale, absent, or pending has no way to
# record that adjudication, so every legitimate operator merge becomes a
# tripwire finding. ``merge_authorize`` writes an ``authorized_override`` into
# the PR's ``review-decision.json``; the tripwire and ``merge-check`` treat an
# override whose ``authorized_sha`` matches the live head as explicit
# authorization. This helper extracts and validates that override from a
# decision dict so both consumers share one enforcement point.
#
# An override that does not name a non-empty SHA or a non-empty reason is not a
# valid override — it is treated as absent so the control never reads a
# malformed record as authorization. A control that can be silenced with an
# empty reason is no control, and an authorization that does not name the SHA
# it authorizes reintroduces the exact hole (#802/#804: rebase moved the head
# after the decision was recorded) the SHA-binding exists to close.


def _authorized_override_matches(decision: dict[str, Any], live_head_sha: str | None) -> bool:
    """Return ``True`` if ``decision`` carries a valid override for ``live_head_sha``.

    Shared by ``_detect_unauthorized_merges`` (the post-merge tripwire) and
    ``merge_check`` (the pre-merge preflight) so the two paths cannot drift on
    what counts as authorization. Both must answer the same question — "is
    there an explicit, SHA-bound, reason-bearing authorization for this head?"
    — or a merge that passes the preflight still trips the post-merge control.
    """
    override = decision.get("authorized_override")
    if not isinstance(override, dict):
        return False
    authorized_sha = override.get("authorized_sha")
    reason = override.get("reason")
    return (
        isinstance(authorized_sha, str)
        and bool(authorized_sha)
        and authorized_sha == live_head_sha
        and isinstance(reason, str)
        and bool(reason.strip())
    )


# Caps for the error detail carried in the `loop_completed` payload. The
# loop-body `errors` list is unbounded by construction — one entry per PR that
# raised — and this payload lands in both the capped 200-entry `events` array in
# state.json and the unlimited events.db, so a single bad pass could otherwise
# push dozens of full exception strings through both.
_LOOP_ERROR_MAX_PRS = 20
_LOOP_ERROR_MAX_DETAILS = 5
_LOOP_ERROR_DETAIL_CHARS = 300

# Cap for the issue-number list in the ``rework_issue_fetch_skipped`` event.
# A repo-wide gh outage can make every rework candidate's ``issue_view``
# fail in one pass; the list is capped so one such pass cannot push an
# unbounded payload through the 200-entry event ring.
_REWORK_ISSUE_FETCH_SKIPPED_MAX_ISSUES = 20
_REWORK_ISSUE_FETCH_SKIPPED_REASON_CHARS = 300
# Cap for the distinct-reason set. A single pass can mix failure modes that
# want opposite operator responses -- one issue 404'd because it was deleted
# (stop retrying), another timed out transiently (retry). Keeping only the
# first exception as ``reason`` (issue #970) collapses those into one
# representative and loses the distinction. This mirrors ``summarize_loop_errors``'
# ``max_details`` idiom: a small distinct set, capped with an explicit
# ``reasons_truncated`` count rather than silently dropped.
_REWORK_ISSUE_FETCH_SKIPPED_MAX_REASONS = 5


def _build_rework_issue_fetch_skip_payload(
    failures: list[tuple[int, Exception]],
    *,
    max_issue_numbers: int = _REWORK_ISSUE_FETCH_SKIPPED_MAX_ISSUES,
    reason_chars: int = _REWORK_ISSUE_FETCH_SKIPPED_REASON_CHARS,
    max_reasons: int = _REWORK_ISSUE_FETCH_SKIPPED_MAX_REASONS,
) -> dict[str, Any]:
    """Summarize per-issue ``gh.issue_view`` failures into a bounded payload.

    ``rework_issue_fetch_skipped`` is intentionally one event per pass, not
    one per issue, so a repo-wide ``gh`` outage does not emit N events for
    the same root cause. The issue list is capped with an explicit
    ``issue_numbers_truncated`` count so the record does not understate the
    number of affected issues. The reason uses the first exception as a
    representative root cause.

    ``reasons`` keeps up to ``max_reasons`` *distinct* ``(reason, error_type)``
    pairs (issue #970). A single pass can mix failure modes that want opposite
    operator responses -- one issue 404'd because it was deleted (stop
    retrying), another timed out transiently (retry) -- and a single
    representative ``reason`` collapses that distinction. Dedup is by
    ``(reason, error_type)`` so a repeated identical outage does not crowd out
    a rarer distinct one, matching ``summarize_loop_errors``' ``error_details``
    shape. ``reason``/``error_type`` are retained as the first representative
    for backward compatibility with the #940-style consumer that reads a
    single ``reason``.
    """
    if not failures:
        return {
            "issue_numbers": [],
            "issue_numbers_truncated": 0,
            "reason": "",
            "error_type": "",
            "reasons": [],
            "reasons_truncated": 0,
        }

    issue_numbers = sorted({issue for issue, _ in failures})
    representative = failures[0][1]
    reason = str(representative) or representative.__class__.__name__
    if len(reason) > reason_chars:
        reason = reason[: reason_chars - 3] + "..."

    # Distinct (reason, error_type) pairs, preserving first-seen order so the
    # representative above is always ``reasons[0]``. Dedup is on the truncated
    # reason text + class name, not the raw exception, so two exceptions with
    # the same message and class count as one root cause.
    seen: set[tuple[str, str]] = set()
    distinct: list[dict[str, Any]] = []
    for _, exc in failures:
        text = str(exc) or exc.__class__.__name__
        if len(text) > reason_chars:
            text = text[: reason_chars - 3] + "..."
        cls = exc.__class__.__name__
        key = (text, cls)
        if key in seen:
            continue
        seen.add(key)
        distinct.append({"reason": text, "error_type": cls})

    return {
        "issue_numbers": issue_numbers[:max_issue_numbers],
        "issue_numbers_truncated": max(0, len(issue_numbers) - max_issue_numbers),
        "reason": reason,
        "error_type": representative.__class__.__name__,
        "reasons": distinct[:max_reasons],
        "reasons_truncated": max(0, len(distinct) - max_reasons),
    }


def summarize_loop_errors(
    errors: list[dict[str, Any]],
    *,
    max_prs: int = _LOOP_ERROR_MAX_PRS,
    max_details: int = _LOOP_ERROR_MAX_DETAILS,
    detail_chars: int = _LOOP_ERROR_DETAIL_CHARS,
) -> dict[str, Any]:
    """Summarize `_loop_body`'s `errors` list into a bounded event payload.

    `loop_completed` previously kept only `error_count`, so a pass that reported
    ``"loop completed with 1 PR error(s)"`` left no stored artifact naming *which*
    PR — diagnosing a live finding meant reading the detector source and
    re-deriving the candidate set by hand (issue #933).

    PR numbers are the cheap, high-value half and are emitted first and most
    generously; free-text detail is the expensive half and is truncated hard.
    Both are capped with an explicit ``*_truncated`` count rather than silently
    dropped, so a reader can always tell a complete list from an elided one — a
    silent cap would reproduce the same "the record understates the problem"
    failure this function exists to fix.

    The two ``*_truncated`` counts are over **different populations**, which the
    similar names hide: ``error_prs_truncated`` counts elided *distinct PRs*
    (deduped), while ``error_details_truncated`` counts elided *error entries*
    (not deduped — several entries can share one PR). So ``error_prs_truncated:
    6`` alongside ``error_details_truncated: 23`` is consistent, not a
    contradiction; they answer "how many more PRs" and "how many more failures".
    """
    pr_numbers: list[int] = []
    for entry in errors:
        raw = entry.get("pr")
        if isinstance(raw, bool) or not isinstance(raw, int):
            continue
        if raw not in pr_numbers:
            pr_numbers.append(raw)

    details: list[str] = []
    for entry in errors[:max_details]:
        text = str(entry.get("error") or "")
        if len(text) > detail_chars:
            text = text[: detail_chars - 3] + "..."
        details.append(text)

    return {
        "error_prs": pr_numbers[:max_prs],
        "error_prs_truncated": max(0, len(pr_numbers) - max_prs),
        "error_details": details,
        "error_details_truncated": max(0, len(errors) - max_details),
    }


# The two statuses that mark an issue as parked in the ``agent:human-needed``
# sink. Every escalation transition (``_escalate_issue``) sets one of these;
# the de-escalation sweep selects on the same pair (``_maybe_deescalate_mechanical``).
# Centralized so the sink census and the sweep cannot drift apart on what
# "in the sink" means. Issue #1083.
_SINK_STATUSES: frozenset[str] = frozenset({"escalated", "blocked"})

# Issue #1383: cross-pass infra_blocked escalation tracking. The
# OrchestratorApp instance is rebuilt per repo per pass (fleet_loop), so
# instance-level state cannot track "persistence across N passes." This
# module-level dict, keyed by repo_root string, survives across passes
# within the same supervisor process -- exactly the scope AC3 needs:
# "one operator escalation per window, not one per PR per pass." Each
# entry records the consecutive-pass count of infra_blocked observations,
# the datetime of the last ``infra_blocked_escalated`` emission (or None
# if none has been emitted yet), and the correlation_id of the pass that
# last incremented the counter (so multiple infra-blocked PRs encountered
# within the same ``review()`` pass increment the counter at most once).
# Reset to zero/None/None when a pass observes no infra_blocked PRs (the
# infra condition cleared).
_infra_blocked_window: dict[str, dict[str, Any]] = {}


def sink_census(state: dict[str, Any]) -> set[int]:
    """Return the set of issue numbers currently parked in the sink.

    The sink is the set of issues whose state entry carries a terminal
    ``status`` of ``"escalated"`` or ``"blocked"`` -- the in-state mirror of
    the escalation GitHub labels (``agent:human-needed`` for a judgment
    escalation, ``agent:operator-queue`` for a mechanical one since issue
    #1266; both share the same ``status`` value, so this census counts both
    without needing to know which). This is a point-in-time census read
    directly from ``state.json``'s ``issues`` map, deliberately not a
    GitHub-label query: it is cheap, deterministic, and matches the same
    source of truth the orchestrator's own de-escalation sweep selects
    candidates from, so the metric and the sweep agree on the population.

    Used by ``_loop_impl`` to compute the issue #1083 sink metric: a
    before/after diff around ``_loop_body`` yields arrivals
    (``after - before``), and the after-set size is the population.
    """
    issues = state.get("issues", {})
    if not isinstance(issues, dict):
        return set()
    parked: set[int] = set()
    for num, entry in issues.items():
        if not isinstance(entry, dict):
            continue
        if entry.get("status") in _SINK_STATUSES and str(num).isdigit():
            parked.add(int(num))
    return parked


def operator_queue_depth(state: dict[str, Any]) -> set[int]:
    """Return the set of issue numbers currently parked on the operator queue.

    Issue #1314 item 3. The operator queue is the subset of the sink
    (``sink_census``) whose entries carry ``reason_class == "mechanical"`` --
    the in-state mirror of the ``agent:operator-queue`` GitHub label (issue
    #1266). ``status == "blocked"`` is never mechanical (``blocked`` is a
    reviewer verdict, always ``reason_class == "judgment"``), so only
    ``status == "escalated"`` entries with the mechanical class are counted.

    This is a point-in-time census read directly from ``state.json``'s
    ``issues`` map, deliberately not a GitHub-label query: it is cheap,
    deterministic, and matches the same source of truth the de-escalation
    sweep selects candidates from, so the gauge and the sweep agree on the
    population.
    """
    issues = state.get("issues", {})
    if not isinstance(issues, dict):
        return set()
    queued: set[int] = set()
    for num, entry in issues.items():
        if not isinstance(entry, dict):
            continue
        if (
            entry.get("status") == "escalated"
            and entry.get("reason_class") == "mechanical"
            and str(num).isdigit()
        ):
            queued.add(int(num))
    return queued


def _detect_and_handle_orphaned_workers(
    sessions_dir: Path,
    state_file: Path,
    config: OrchestratorConfig,
    gh: GitHubLike,
    *,
    write_gate: WriteGate,
    review_callback: Callable[[int], Any] | None = None,
    fleet_dir_override: str | None = None,
) -> None:
    """Detect and handle orphaned workers using state.json PID records.

    This is a fallback for issue #207: when session sidecar files are orphaned
    (e.g., by session-limit reset), the session-file-based stall-reaper cannot
    detect dead workers. This function reads worker PIDs from state.json and
    checks liveness directly, allowing recovery even without session files.

    For issues with status "dispatched" and a recorded worker_pid:
    - If the PID is dead, check the linked PR's last review decision
    - If last decision was "request_changes" and head unchanged, reset to "rework_requested"
    - If last decision was "request_changes" and head advanced, route to the
      review-pending path by calling ``review_callback`` and then flipping the
      issue status to "reviewing"
    - If last decision was "approved" and the PR state carries
      ``status="rework_requested"`` (evidence the post-approval rework lane
      dispatched this worker) and head is unchanged since review, reset to
      "rework_requested" -- same as the request_changes branch (issue #1109)
    - Otherwise, surface as drift for human triage (once per unchanged finding)
    - Do NOT clear worker_pid from state.json after handling (issue #282: the
      recovery path needs the fingerprint to verify the worktree is safe to reset).

    Issue #417: for the no-open-PR case, this is the ONE lane that revisits a
    dead session's GitHub labels independent of its sidecar file -- it is
    keyed entirely off state.json (``status == "dispatched"`` + a dead
    ``worker_pid``), so it runs every pass whether or not a sidecar exists.
    ``_classify_dead_sessions_and_update_throttle_state``'s own no-open-PR
    reclaim (the "issue #118" lane) is a single best-effort attempt per dead
    session: if it is interrupted (process crash/reboot) between writing
    ``redispatch_at`` and swapping the GitHub labels, or if the label API
    calls themselves fail, the sidecar is already reaped and that lane has no
    way to revisit the issue. This sweep closes that gap by re-deriving
    "does this issue still need its labels fixed" from GitHub's *live* label
    state every pass (not from any one-shot flag), so a half-finished reclaim
    -- or one stranded before this fix ever existed -- gets completed here
    without a human needing to notice.

    Issue #1122: this sweep is NOT gated on ``watchdog.enabled``. The watchdog
    flag controls log-mtime stall detection (``_detect_stalled_sessions`` /
    ``_detect_and_handle_stalled_sessions``), which is unrelated to this
    function's dead-pid state-keyed recovery. A deployment that disables
    watchdog (e.g. to work around a shim log-mtime blindness) must not lose
    the #935 pushed-branch salvage backstop, the #417 ground-truth label
    reclaim, or the orphan drift diagnostics -- all of which are keyed off
    state.json PID records, not log mtimes.
    """
    write_gate = require_write_gate(write_gate)

    def _drift_fingerprint(**parts: Any) -> str:
        """Stable fingerprint for an orphaned-worker drift finding."""
        return json.dumps(parts, sort_keys=True, default=str)

    with state_lock(state_file):
        state = load_state(state_file)

    orphaned_issues: list[int] = []
    for issue_number_str, entry in state.get("issues", {}).items():
        if not isinstance(entry, dict):
            continue
        if entry.get("status") != "dispatched":
            continue

        if not _worker_pid_alive(entry):
            orphaned_issues.append(int(issue_number_str))

    if not orphaned_issues:
        return

    # Fetch PRs once before acquiring the lock (avoid network I/O under lock)
    prs = gh.pr_list()
    pr_by_issue: dict[int, dict[str, Any]] = {}
    for pr in prs:
        linked = linked_issue_number(
            pr,
            is_cross_repository=pr.get("isCrossRepository"),
            branch_prefix=config.dispatch.branch_prefix,
        )
        if linked is not None:
            pr_by_issue[linked] = pr

    # Issue #417: ground-truth label reclaim for the no-open-PR orphans, done
    # OUTSIDE the state lock (network I/O) and with a single bulk issue-list
    # call rather than one gh.issue_view per orphan -- this sweep's GitHub
    # cost must stay bounded regardless of how many stale "dispatched" entries
    # have accumulated in state.json over time.
    no_pr_orphans = [n for n in orphaned_issues if n not in pr_by_issue]
    reclaim_results: dict[int, dict[str, Any]] = {}
    # Issue #1153: issues escalated to ``agent:human-needed`` by the
    # zero-artifact dispatch loop guard, instead of being relabeled to
    # ``automated-ready`` for another fruitless redispatch. Keyed by issue
    # number; each value carries the label-write outcome and the attempt
    # count that triggered the escalation.
    zero_artifact_escalations: dict[int, dict[str, Any]] = {}
    # Issue #1244: issues escalated to ``agent:human-needed`` by the
    # cross-repo scope tripwire, instead of being relabeled to
    # ``automated-ready`` for another fruitless redispatch.  A dead worker
    # whose issue title names another managed repo hopped to that repo's
    # worktree; redispatching repeats the hop forever.  Keyed by issue
    # number; each value carries the label-write outcome and the scope
    # gate's reason.
    cross_repo_scope_escalations: dict[int, dict[str, Any]] = {}
    # Issue #1453: issues escalated to the operator queue because the worker
    # itself declared the task structurally impossible (a ``blocked`` outcome
    # in ``.worker-outcome.json``).  The worker deliberately concluded it
    # cannot do the task (e.g. cross-repo scope, missing dependency); without
    # this channel the orphan sweep would redispatch to another worker that
    # hits the identical wall, burning the full redispatch cap.  Keyed by
    # issue number; each value carries the label-write outcome and the
    # worker's ``reason_kind`` / ``detail`` so the operator queue entry is
    # actionable without reading the worktree.
    worker_declared_blocked_escalations: dict[int, dict[str, Any]] = {}
    # Issue #1453: pre-computed worker outcomes for all no-PR orphans, read
    # once before the first pre-lock loop so the blocked-outcome check can
    # fire before reclaim adds ``automated-ready``.  Reused by the second
    # loop (pushed-branch candidates) without re-reading.
    worker_outcomes: dict[int, dict[str, Any] | None] = {}
    issues_by_number: dict[int, dict[str, Any]] = {}
    # Issue #935 / #1453: compute repo_root and worktrees_dir once, before any
    # of the pre-lock loops, so the first loop (reclaim/escalation) can read
    # worker outcomes for the blocked-outcome check and the second loop
    # (pushed-branch candidates) can reuse the same pre-computed outcomes.
    repo_root = getattr(gh, "repo_root", None)
    worktrees_dir = None
    if repo_root is not None:
        worktrees_dir = resolved_layout(config, repo_root).worktrees

    if no_pr_orphans:
        for issue in gh.issue_list(state="open"):
            number = issue.get("number")
            if number is not None:
                issues_by_number[int(number)] = issue
        # Issue #1244: pre-compute the fleet's managed repo names and the
        # dispatching repo name once for the whole loop — the fleet registry
        # is read from disk and gh.name_with_owner() is a network call.
        sweep_repo_root = repo_root
        sweep_fleet_repos = managed_repo_names(fleet_dir_override)
        sweep_dispatching_repo_name = (
            _dispatching_repo_name(gh, sweep_repo_root) if sweep_repo_root is not None else ""
        )

        # Issue #1453: pre-read worker outcomes for all no-PR orphans so the
        # first loop (reclaim/escalation) can detect a ``blocked`` outcome
        # BEFORE reclaiming (which would add ``automated-ready`` and trigger a
        # fruitless redispatch). The durable terminal status is authoritative
        # because it is written after the worker exits and survives worktree
        # removal; the worktree file is the live fallback. Stored for the
        # second loop to reuse without re-reading.
        for issue_number in no_pr_orphans:
            issue = issues_by_number.get(issue_number)
            if issue is None:
                continue
            entry = state.get("issues", {}).get(str(issue_number), {})
            branch = entry.get("branch_name") if isinstance(entry, dict) else None
            if not branch:
                branch = (
                    f"{config.dispatch.branch_prefix}-{issue_number}-"
                    f"{slugify(str(issue.get('title') or 'work'))}"
                )
            worktree_path = None
            if repo_root is not None and worktrees_dir is not None:
                worktree_path = worktree_path_for_branch(repo_root, branch, worktrees_dir)
            terminal = find_worker_terminal_status(sessions_dir, issue_number)
            terminal_outcome = terminal.get("worker_outcome") if terminal else None
            worktree_outcome = read_worker_outcome(worktree_path) if worktree_path else None
            worker_outcomes[issue_number] = terminal_outcome or worktree_outcome

        for issue_number in no_pr_orphans:
            issue = issues_by_number.get(issue_number)
            if issue is None:
                # Issue not found in the open snapshot (closed, deleted, or
                # inaccessible) -- nothing safe to reclaim; leave it to the
                # existing diagnostic drift path below.
                continue
            issue_labels = label_names(issue)
            active_labels = issue_labels & config.labels.active
            # Gate the WHOLE reclaim on an active label actually being
            # present, matching reconcile.py's issue_active_label_no_open_pr
            # pattern (~536-580) so all three sites agree. An issue with no
            # active label -- e.g. one carrying only a terminal label like
            # agent:human-needed/agent:done/agent:blocked -- has nothing here
            # to reclaim. A prior `if not active_labels and not needs_ready`
            # gate proceeded whenever EITHER half was false, which wrongly
            # added `ready` back onto a terminal-only issue that also had a
            # stale dispatched/dead-worker/no-PR state.json entry (already
            # fully reconciled issues, or terminal-only ones, both correctly
            # fall through here without any GitHub call).
            if not active_labels:
                continue

            # Issue #1453: a worker that deliberately concluded it CANNOT do
            # the task writes a ``blocked`` outcome in
            # ``.worker-outcome.json`` instead of exiting PR-less with no
            # signal.  Without this channel the orphan sweep classifies the
            # dead worker as ``dead_worker_no_open_pr`` and redispatches --
            # to another worker that hits the identical wall, burning the
            # full redispatch cap.  The worker's own declaration is the most
            # authoritative signal: check it FIRST, before the zero-artifact
            # and cross-repo heuristic escalations, and route directly to the
            # operator queue with zero redispatches.  The pre-lock label
            # relabeling (remove active, add human-needed as fallback) mirrors
            # the zero-artifact / cross-repo scope pattern; the post-lock
            # ``reap_escalations`` transition applies the operator-queue
            # label edge.
            worker_outcome = worker_outcomes.get(issue_number)
            if isinstance(worker_outcome, dict) and worker_outcome.get("outcome") == "blocked":
                label_write_ok = True
                for label in sorted(active_labels):
                    if not gh.remove_issue_label(issue_number, label):
                        label_write_ok = False
                if config.labels.human_needed not in issue_labels:
                    if not gh.add_issue_label(issue_number, config.labels.human_needed):
                        label_write_ok = False
                worker_declared_blocked_escalations[issue_number] = {
                    "removed_labels": sorted(active_labels),
                    "label_write_ok": label_write_ok,
                    "reason_kind": str(worker_outcome.get("reason_kind") or "unknown"),
                    "detail": str(worker_outcome.get("detail") or ""),
                }
                continue

            # Issue #1153: before relabeling to ``automated-ready`` for
            # another redispatch, check whether prior attempts all produced
            # zero artifacts (``ahead_of_main == 0``). A repeated
            # zero-artifact dispatch loop means each worker session ran,
            # determined the fix belongs in a sibling repo, hopped to its
            # worktree, did the work there, and exited with ``ahead_of_main:
            # 0`` in *this* repo's tree -- swept as a dead worker with no
            # open PR, relabeled, redispatched, forever. Escalate to
            # ``agent:human-needed`` instead of burning another dispatch.
            if _is_zero_artifact_dispatch_loop(sessions_dir, issue_number):
                label_write_ok = True
                for label in sorted(active_labels):
                    if not gh.remove_issue_label(issue_number, label):
                        label_write_ok = False
                if config.labels.human_needed not in issue_labels:
                    if not gh.add_issue_label(issue_number, config.labels.human_needed):
                        label_write_ok = False
                zero_artifact_escalations[issue_number] = {
                    "removed_labels": sorted(active_labels),
                    "label_write_ok": label_write_ok,
                }
                continue

            # Issue #1244: cross-repo scope tripwire. Before relabeling to
            # ``automated-ready`` for another redispatch, check whether the
            # issue's title names another managed repo in the fleet. A dead
            # worker whose issue scope targets a sibling repo hopped to that
            # repo's worktree; redispatching repeats the hop forever. Escalate
            # to ``agent:human-needed`` instead of burning another dispatch.
            # This is the transition tripwire (Option 2): catches issues
            # dispatched before the intake-time scope gate (Option 1) existed.
            scope_result = cross_repo_scope_gate(
                str(issue.get("title") or ""),
                str(issue.get("body") or ""),
                sweep_dispatching_repo_name,
                sweep_fleet_repos,
            )
            if not scope_result.passed:
                label_write_ok = True
                for label in sorted(active_labels):
                    if not gh.remove_issue_label(issue_number, label):
                        label_write_ok = False
                if config.labels.human_needed not in issue_labels:
                    if not gh.add_issue_label(issue_number, config.labels.human_needed):
                        label_write_ok = False
                cross_repo_scope_escalations[issue_number] = {
                    "removed_labels": sorted(active_labels),
                    "label_write_ok": label_write_ok,
                    "reason": scope_result.reason,
                }
                continue

            needs_ready = config.labels.ready not in issue_labels
            label_write_ok = True
            for label in sorted(active_labels):
                if not gh.remove_issue_label(issue_number, label):
                    label_write_ok = False
            if needs_ready:
                if not gh.add_issue_label(issue_number, config.labels.ready):
                    label_write_ok = False
            reclaim_results[issue_number] = {
                "removed_labels": sorted(active_labels),
                "added_ready": needs_ready,
                "label_write_ok": label_write_ok,
            }

    # Issue #935: for the no-open-PR orphans, determine whether the worker
    # pushed a branch and reported push-succeeded-but-PR-failed. This is done
    # outside the state lock because it can touch origin. The second lock below
    # will use these pre-computed candidates to decide whether to open the PR
    # itself instead of re-dispatching.
    # ``repo_root`` / ``worktrees_dir`` were computed above, before the first
    # pre-lock loop, so the blocked-outcome check could read worker outcomes.

    # Issue #1248: salvage-push committed-but-unpushed work from dead workers'
    # worktrees BEFORE anything below classifies them. A worker that finished
    # its work locally but died at the final push produces zero remote delta,
    # so every downstream branch -- request_changes auto-reset, the no-op
    # rework detector, the #935 pushed-branch lane -- reads it as "did
    # nothing" and redispatches (or caps out) on work that is already done.
    # ``salvage_push_stranded_commits`` publishes the work only when it is a
    # pure fast-forward of the remote tip (never force; diverged worktrees
    # fall through to the existing ``dead_worker_unsafe_to_auto_reset``
    # handling untouched). After a successful push the PR snapshot's
    # ``headRefOid`` is refreshed so the in-lock classification sees the head
    # advance and routes to review instead of counting a death, and the #935
    # candidate detection below sees the branch on origin and opens a PR for
    # it. Runs pre-lock: it is network I/O.
    salvage_pushes: dict[int, dict[str, Any]] = {}
    if repo_root is not None and worktrees_dir is not None:
        for issue_number in orphaned_issues:
            pr_data = pr_by_issue.get(issue_number)
            if pr_data is not None and pr_data.get("isCrossRepository"):
                # The head branch lives in a fork; this checkout cannot (and
                # must not) push there.
                continue
            entry = state.get("issues", {}).get(str(issue_number), {})
            branch = pr_data.get("headRefName") if pr_data is not None else None
            if not branch and isinstance(entry, dict):
                branch = entry.get("branch_name")
            if not branch:
                # No recorded branch: never guess a ref name to push to.
                continue
            worktree_path = worktree_path_for_branch(repo_root, branch, worktrees_dir)
            result = salvage_push_stranded_commits(
                repo_root,
                branch,
                worktree_path,
                base_ref=config.dispatch.base_ref,
                dry_run=write_gate.dry_run,
            )
            if result.pushed:
                salvage_pushes[issue_number] = {
                    "issue_number": issue_number,
                    "pr_number": int(pr_data["number"]) if pr_data is not None else None,
                    "branch": branch,
                    "old_remote_sha": result.old_remote_sha,
                    "new_remote_sha": result.new_remote_sha,
                    "commit_count": result.commit_count,
                }
                if pr_data is not None and result.new_remote_sha:
                    # Refresh the snapshot so classification below compares
                    # against the salvaged head, not the pre-push one.
                    pr_data["headRefOid"] = result.new_remote_sha
            elif result.error:
                salvage_pushes[issue_number] = {
                    "issue_number": issue_number,
                    "pr_number": int(pr_data["number"]) if pr_data is not None else None,
                    "branch": branch,
                    "old_remote_sha": result.old_remote_sha,
                    "commit_count": result.commit_count,
                    "error": result.error,
                }
            # skip_reason outcomes are silent by design: "up_to_date" /
            # "no_worktree" / "no_stranded_commits" describe the overwhelming
            # majority of dead workers and would flood events.db every pass.

    no_pr_issue_details: dict[int, dict[str, Any]] = {}
    pushed_branch_candidates: dict[int, dict[str, Any]] = {}
    state_snapshot = state
    for issue_number in no_pr_orphans:
        issue = issues_by_number.get(issue_number)
        if issue is None:
            # Issue not open/visible: we cannot safely mutate labels, and a
            # closed issue should not get a new PR.
            continue
        issue_labels = label_names(issue)
        active_labels = issue_labels & config.labels.active
        no_pr_issue_details[issue_number] = {
            "issue": issue,
            "issue_labels": issue_labels,
            "active_labels": active_labels,
        }

        entry = state_snapshot.get("issues", {}).get(str(issue_number), {})
        branch = entry.get("branch_name")
        if not branch:
            branch = (
                f"{config.dispatch.branch_prefix}-{issue_number}-"
                f"{slugify(str(issue.get('title') or 'work'))}"
            )

        worktree_path = None
        if repo_root is not None and worktrees_dir is not None:
            worktree_path = worktree_path_for_branch(repo_root, branch, worktrees_dir)

        # Issue #1453: reuse the outcome pre-computed above (before the first
        # pre-lock loop) instead of re-reading the terminal status and
        # worktree file.  The blocked-outcome check already ran in the first
        # loop; here we only need the outcome for the push/PR-failure signal.
        worker_outcome = worker_outcomes.get(issue_number)

        reported_push = (
            isinstance(worker_outcome, dict)
            and worker_outcome.get("push_succeeded") is True
            and worker_outcome.get("pr_created") is False
        )

        ahead_count = None
        ahead_error = None
        if repo_root is not None:
            ahead_count, ahead_error = remote_branch_ahead_count(
                repo_root, branch, config.dispatch.base_ref
            )

        # Issue #1243: compute the branch head SHA (remote + local worktree)
        # for the no-open-PR redispatch cap. An unchanged head across attempts
        # is the "no progress" signal that increments toward the cap; a moving
        # head (remote push or local stranded commits) resets it. Done here,
        # outside the state lock, because both probes touch git/network.
        remote_head_sha = None
        local_head_sha = None
        if repo_root is not None:
            remote_head_sha = remote_branch_head_sha(repo_root, branch)
        if worktree_path is not None:
            local_head_sha = worktree_head_sha(worktree_path)
        no_pr_issue_details.setdefault(issue_number, {}).update(
            {
                "branch": branch,
                "remote_head_sha": remote_head_sha,
                "local_head_sha": local_head_sha,
            }
        )

        # Treat a branch as a PR-open candidate when:
        # - the worker itself reported a successful push with a failed PR, OR
        # - the branch exists on origin and is ahead of the base (has commits).
        if reported_push or (ahead_count is not None and ahead_count > 0):
            pushed_branch_candidates[issue_number] = {
                "branch": branch,
                "worktree_path": worktree_path,
                "worker_outcome": worker_outcome,
                "reported_push": reported_push,
                "ahead_count": ahead_count,
                "ahead_error": ahead_error,
            }

    # Issue #439: route dead workers with stuck pre-review PRs to rework before
    # the state-update sweep. PR views are fetched outside the state lock; the
    # route helper updates state/labels in its own critical section. The second
    # lock below will then skip issues that have already moved to
    # rework_requested/escalated.
    pre_review_routed: set[int] = set()
    state_snapshot = state
    now = datetime.now(UTC)
    for issue_number in orphaned_issues:
        pr_data = pr_by_issue.get(issue_number)
        if not pr_data:
            continue
        pr_number = int(pr_data["number"])
        # Issue #1362 Stage 1: read through the single review-decision
        # reader (flat file, falling back to the highest archived round)
        # rather than state.json's ``decision``/``reviewed_head_sha``
        # fields, which can lag a concurrent record_review/void.
        resolved_decision = review_decision(
            state_file.parent / "prs" / f"pr-{pr_number}", None, pr_data.get("headRefOid")
        )
        if resolved_decision.decision == "request_changes" and not resolved_decision.stale:
            # Let the second-lock request_changes restoration path handle this;
            # do not overwrite an existing review feedback prompt.
            continue
        try:
            pr_view = gh.pr_view(pr_number)
        except Exception:
            pr_view = None
        enriched = pr_view if pr_view else pr_data
        is_candidate, reason = _is_pre_review_rework_candidate(enriched, config, now)
        if is_candidate:
            route_result = _route_dead_worker_to_pre_review_rework(
                state_file,
                gh,
                config,
                enriched,
                issue_number,
                reason,
                failure_kind=None,
                write_gate=write_gate,
            )
            if route_result is not None:
                pre_review_routed.add(issue_number)

    # Issue #1128: for dead workers that already have an OPEN PR with no
    # review verdict yet (``last_decision`` is null/absent), pre-compute the
    # issue's live GitHub labels outside the state lock. The second-lock
    # sweep uses these to transition the issue from ``agent:in-progress`` to
    # ``agent:pr-open`` -- the same LabelConfig-driven swap the
    # ``orphaned_worker_opened_pr`` lane uses -- so review dispatch can claim
    # the salvage PR. Without this, the ``dead_worker_unsafe_to_auto_reset``
    # branch advanced no label and the issue sat on ``agent:in-progress``
    # indefinitely, asserting a live worker the reconciler had just confirmed
    # dead. ``pr_by_issue`` only contains OPEN PRs (``gh pr list --state
    # open``), so presence there is the "PR is OPEN" precondition.
    pr_orphan_unreviewed_details: dict[int, dict[str, Any]] = {}

    def _has_no_review_verdict_yet(issue_number: int) -> bool:
        """True when the PR carries no terminal review verdict yet.

        Issue #1362 Stage 1 fix: the old state-based predicate
        (``not pr_state.get("decision")``) was true for both "no decision
        file at all" and "a pending placeholder decision" -- both count as
        "no verdict yet" per this lane's #1128 intent (see the comment
        above). Checking only ``.missing`` narrowed that: a dead-worker
        orphan PR that reached a pending packet would be silently excluded
        from the ``agent:in-progress`` -> ``agent:pr-open`` advance,
        re-stranding the issue exactly like the original #1128 bug.
        """
        resolved = review_decision(
            state_file.parent / "prs" / f"pr-{int(pr_by_issue[issue_number]['number'])}",
            None,
            pr_by_issue[issue_number].get("headRefOid"),
        )
        return resolved.missing or resolved.decision == "pending"

    pr_orphans_unreviewed = [
        n for n in orphaned_issues if n in pr_by_issue and _has_no_review_verdict_yet(n)
    ]
    if pr_orphans_unreviewed:
        # ``issues_by_number`` is only populated above when there were
        # no-open-PR orphans; build it here when this lane is the sole
        # consumer so the label read stays a single bulk ``issue_list`` call.
        if not issues_by_number:
            for issue in gh.issue_list(state="open"):
                number = issue.get("number")
                if number is not None:
                    issues_by_number[int(number)] = issue
        for issue_number in pr_orphans_unreviewed:
            issue = issues_by_number.get(issue_number)
            if issue is None:
                # Issue not open/visible -- cannot safely mutate labels;
                # the conservative drift path below handles it.
                continue
            issue_labels = label_names(issue)
            active_labels = issue_labels & config.labels.active
            pr_orphan_unreviewed_details[issue_number] = {
                "issue_labels": issue_labels,
                "active_labels": active_labels,
            }

    # Handle orphaned workers. Head-advanced request_changes findings are
    # collected and routed to the review lane outside the state lock (review()
    # itself acquires the lock and may call transition()).
    review_routes: list[tuple[int, int, str, str, str]] = []
    # Issue #654: dead dispatched workers time-escalated inside the lock
    # collected here for the post-lock transition() call (network I/O).
    reap_escalations: list[int] = []
    with state_lock(state_file):
        state = load_state(state_file)
        sweep_events: list[tuple[str, dict[str, Any]]] = []
        # Issue #1248: record the pre-lock salvage pushes (and push failures)
        # in the same event stream as the classification they feed, so a
        # ``dead_worker_with_head_change`` routed below is attributable to its
        # salvage rather than looking like a spontaneous worker push.
        for salvage_payload in salvage_pushes.values():
            if salvage_payload.get("error"):
                sweep_events.append(("salvage_push_failed", salvage_payload))
            else:
                sweep_events.append(("salvage_pushed_stranded_commits", salvage_payload))
        for issue_number in orphaned_issues:
            entry = state["issues"].get(str(issue_number), {})
            if not isinstance(entry, dict):
                continue

            # Re-verify status (state may have changed between lock windows)
            if entry.get("status") != "dispatched":
                continue

            # Issue #654: time-based escape for a dead dispatched worker whose
            # drift was already surfaced on a prior pass (``orphan_drift_at`` is
            # set) but whose PR state did not qualify for auto-reset -- a clean
            # exit with no push (issue #773's ``dead_worker_clean_exit_no_op``
            # branch), a non-request_changes decision, a head change without a
            # review callback, or a PR-create failure on a pushed branch. In all
            # of these the specific sub-branch below emits drift once, sets
            # ``orphan_drift_at``, then on every subsequent pass the fingerprint
            # match short-circuits to ``continue`` -- so the dispatch label
            # (``agent:in-progress``) holds indefinitely. The label is the
            # one-writer-per-branch mutex, so no re-dispatch can proceed on that
            # branch until a worker that no longer exists reports back. After
            # ``dead_dispatched_reap_minutes`` since the drift was first
            # surfaced, escalate to ``agent:human-needed`` so a human can inspect
            # the worktree for unpushed commits and decide whether to salvage or
            # re-dispatch. This runs BEFORE the specific sub-branches so it is a
            # pure backstop: on the first pass ``orphan_drift_at`` is not yet set
            # and the specific sub-branch runs normally (either resetting
            # immediately or emitting the first drift). Only issues that already
            # have drift recorded and have exceeded the grace period are
            # escalated here. 0 disables the escape (pre-#654 hold-forever).
            orphan_drift_at = entry.get("orphan_drift_at")
            if orphan_drift_at is not None and config.watchdog.dead_dispatched_reap_minutes > 0:
                drift_dt = _parse_iso_timestamp(orphan_drift_at)
                if (
                    drift_dt is not None
                    and (now - drift_dt).total_seconds() / 60
                    >= config.watchdog.dead_dispatched_reap_minutes
                ):
                    pr_data_for_reap = pr_by_issue.get(issue_number)
                    pr_number_for_reap = (
                        int(pr_data_for_reap["number"]) if pr_data_for_reap else None
                    )
                    terminal = find_worker_terminal_status(sessions_dir, issue_number)
                    terminal_exit_code = terminal.get("exit_code") if terminal else None
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="dead_dispatched_worker_reap",
                        reason_class="mechanical",
                        pr_number=pr_number_for_reap,
                        issue_extra={
                            "dispatched_at": None,
                            "orphan_drift_fingerprint": None,
                            "orphan_drift_at": None,
                        },
                    )
                    sweep_events.append(
                        (
                            "dead_dispatched_worker_reaped",
                            {
                                "issue_number": issue_number,
                                "pr_number": pr_number_for_reap,
                                "previous_status": "dispatched",
                                "reason": "dead_dispatched_worker_reap",
                                "orphan_drift_at": orphan_drift_at,
                                "reap_minutes": (config.watchdog.dead_dispatched_reap_minutes),
                                "exit_code": terminal_exit_code,
                            },
                        )
                    )
                    reap_escalations.append(issue_number)
                    continue

            # Issue #282: do not clear the liveness fingerprint here. The worker
            # is dead (``_worker_pid_alive`` returned False), but the PID record
            # may still be needed by the recovery path to decide whether the
            # worktree is safe to reset.

            pr_data = pr_by_issue.get(issue_number)

            if pr_data:
                pr_number = int(pr_data["number"])
                pr_state = state.get("prs", {}).get(str(pr_number), {})
                live_head_sha = pr_data.get("headRefOid")
                # Issue #1362 Stage 1: read the last review decision through
                # the single file-first reader (flat file, falling back to
                # the highest archived round) instead of state.json's
                # decision/reviewed_head_sha fields, which can lag a
                # concurrent record_review/void -- the #1340 divergence
                # class AC1 exists to eliminate.
                resolved_decision = review_decision(
                    state_file.parent / "prs" / f"pr-{pr_number}", None, live_head_sha
                )
                last_decision = resolved_decision.decision
                reviewed_head_sha = resolved_decision.reviewed_head_sha

                # Issue #773: measurement-first payload enrichment. A dead PID
                # alone cannot distinguish a worker that crashed from one that
                # exited 0 having pushed nothing -- both present identically
                # to `_worker_pid_alive`. `find_worker_terminal_status` reads
                # the durable record `start_terminal_status_watcher`
                # (process_utils.py) writes at the moment a claude-code worker
                # actually exits; it returns None for legacy sessions, sessions
                # from adapters that don't write one (e.g. devin-shell), or
                # any session whose watcher never got to run (e.g. orchestrator
                # restart mid-session). `terminal_exit_code` is deliberately
                # left as None in all of those cases rather than guessed at --
                # every event below records it as-is so the two populations
                # (confirmed clean exit vs. everything else) are queryable
                # retrospectively even before they're fully separable.
                terminal = find_worker_terminal_status(sessions_dir, issue_number)
                terminal_pid = entry.get("worker_pid")
                terminal_exit_code = terminal.get("exit_code") if terminal else None
                terminal_duration_seconds = terminal.get("duration_seconds") if terminal else None

                if last_decision == "request_changes" and reviewed_head_sha and live_head_sha:
                    if reviewed_head_sha == live_head_sha:
                        if terminal_exit_code == 0:
                            # The worker exited cleanly (exit code 0) rather
                            # than crashing -- e.g. it was handed an empty
                            # rework brief with nothing left to act on. Do NOT
                            # auto-reset to rework_requested: that would spend
                            # one of max_auto_redispatch's attempts on a
                            # worker that never had anything to change,
                            # eventually escalating a benign no-op to
                            # agent:human-needed (issue #773). Surface it once
                            # instead, via the same fingerprinted
                            # surface-once convergence the other drift
                            # branches below already use, so a human/janitor
                            # can decide whether the review itself needs
                            # revisiting -- retrying a dispatch that already
                            # proved it produces no change on this exact head
                            # would just repeat the no-op.
                            fingerprint = _drift_fingerprint(
                                reason="dead_worker_clean_exit_no_op",
                                reviewed_head_sha=reviewed_head_sha,
                            )
                            if entry.get("orphan_drift_fingerprint") == fingerprint:
                                state["issues"][str(issue_number)] = entry
                                continue
                            entry["orphan_drift_fingerprint"] = fingerprint
                            entry["orphan_drift_at"] = utc_now()
                            sweep_events.append(
                                (
                                    "orphaned_worker_drift",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "reason": "dead_worker_clean_exit_no_op",
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                    },
                                )
                            )
                        else:
                            # No terminal record, or a non-zero/None exit code:
                            # unchanged from pre-#773 behavior -- safe to reset
                            # to rework_requested (PR head unchanged since
                            # request_changes).
                            entry["status"] = "rework_requested"
                            entry["dispatched_at"] = None
                            # Issue #1134: record this as a worker death, not
                            # a no-op.  A death redispatch must not count
                            # against the no-op rework cap — the worker may
                            # have completed its work but died before pushing
                            # (salvageable stranded commits).  A separate
                            # death counter with its own escalation reason
                            # (worker_death_loop) lets the operator triage
                            # "check the worktree" vs. "worker is spinning."
                            death_ts = utc_now()
                            prior_deaths = entry.get("worker_death_at")
                            if not isinstance(prior_deaths, list):
                                prior_deaths = []
                            entry["worker_death_at"] = prior_deaths + [death_ts]
                            sweep_events.append(
                                (
                                    "orphaned_worker_recovered",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "new_status": "rework_requested",
                                        "reason": "dead_worker_with_request_changes",
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                        "worker_death_at": death_ts,
                                    },
                                )
                            )
                    else:
                        # PR head has changed - route to review if possible,
                        # otherwise surface as a drift finding (once per fingerprint).
                        fingerprint = _drift_fingerprint(
                            reason="dead_worker_with_head_change",
                            reviewed_head_sha=reviewed_head_sha,
                            live_head_sha=live_head_sha,
                        )
                        if entry.get("orphan_drift_fingerprint") == fingerprint:
                            # Already handled/failed for this exact head advance;
                            # don't re-emit or retry.
                            state["issues"][str(issue_number)] = entry
                            continue
                        if review_callback is not None:
                            review_routes.append(
                                (
                                    issue_number,
                                    pr_number,
                                    reviewed_head_sha,
                                    live_head_sha,
                                    fingerprint,
                                )
                            )
                        else:
                            entry["orphan_drift_fingerprint"] = fingerprint
                            entry["orphan_drift_at"] = utc_now()
                            sweep_events.append(
                                (
                                    "orphaned_worker_drift",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "last_decision": last_decision,
                                        "reviewed_head_sha": reviewed_head_sha,
                                        "live_head_sha": live_head_sha,
                                        "reason": "dead_worker_with_head_change",
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                    },
                                )
                            )
                else:
                    # Not a simple request_changes case.
                    # Issue #1109: a dead worker on an approved PR is not
                    # unclassifiable when the post-approval rework lane
                    # (#674 -> PR #685, plus the merge-conflict and no-op
                    # rework lanes that share ``_route_to_rework``) dispatched
                    # it. Those lanes set the PR state status to
                    # ``rework_requested`` while preserving
                    # ``decision="approved"``, and the worker is dispatched to
                    # fix CI/a conflict without re-litigating the review. If
                    # that worker dies before pushing (head unchanged since
                    # review), the issue previously wedged in ``dispatched``
                    # forever because this sweep refused to auto-reset on a
                    # non-``request_changes`` decision -- no redispatch, no
                    # cap consumption, invisible to every downstream lane.
                    # Treat ``decision="approved"`` + PR-state
                    # ``rework_requested`` + head unchanged as safe to
                    # auto-reset, mirroring the request_changes branch above
                    # (including the #773 clean-exit-no-op sub-case so a
                    # benign exit-0 worker does not burn redispatch attempts).
                    # ``dead_worker_unsafe_to_auto_reset`` is kept only for
                    # genuinely unclassifiable decisions -- an approved PR
                    # whose PR state does not carry ``rework_requested`` has
                    # no evidence a post-approval rework lane dispatched this
                    # worker, so auto-resetting would be a guess.
                    #
                    # Issue #1128: when the dead worker has an OPEN PR with no
                    # review verdict yet (``last_decision`` is null/absent),
                    # the "unsafe to auto-reset" judgment stays -- the PR
                    # carries the work, so re-dispatching would duplicate it --
                    # but leaving the issue on ``agent:in-progress`` makes the
                    # state machine assert a live worker the reconciler just
                    # confirmed dead, and review dispatch (which keys off
                    # ``agent:pr-open``) never sees the salvage PR. Transition
                    # to ``pr-open`` via the same LabelConfig-driven swap the
                    # ``orphaned_worker_opened_pr`` lane uses. On label write
                    # failure, fall through to the conservative drift path so
                    # the next pass re-attempts rather than resetting the
                    # worker.
                    pr_state_status = pr_state.get("status")
                    if (
                        last_decision == "approved"
                        and pr_state_status == "rework_requested"
                        and reviewed_head_sha
                        and live_head_sha
                        and reviewed_head_sha == live_head_sha
                    ):
                        if terminal_exit_code == 0:
                            # Clean exit with no push -- same #773 rationale
                            # as the request_changes branch: do not spend a
                            # redispatch attempt on a worker that produced no
                            # change on this exact head.
                            fingerprint = _drift_fingerprint(
                                reason="dead_worker_clean_exit_no_op",
                                reviewed_head_sha=reviewed_head_sha,
                            )
                            if entry.get("orphan_drift_fingerprint") == fingerprint:
                                state["issues"][str(issue_number)] = entry
                                continue
                            entry["orphan_drift_fingerprint"] = fingerprint
                            entry["orphan_drift_at"] = utc_now()
                            sweep_events.append(
                                (
                                    "orphaned_worker_drift",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "reason": "dead_worker_clean_exit_no_op",
                                        "decision": "approved",
                                        "pr_state_status": pr_state_status,
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                    },
                                )
                            )
                        else:
                            # No terminal record, or a non-zero/None exit
                            # code: safe to reset to rework_requested (PR head
                            # unchanged since the approved review, and the
                            # post-approval rework lane dispatched this
                            # worker). Records this as a worker death with a
                            # distinct reason so the death counter (issue
                            # #1134) and the redispatch cap (issue #165) apply
                            # exactly as they do for request_changes.
                            entry["status"] = "rework_requested"
                            entry["dispatched_at"] = None
                            death_ts = utc_now()
                            prior_deaths = entry.get("worker_death_at")
                            if not isinstance(prior_deaths, list):
                                prior_deaths = []
                            entry["worker_death_at"] = prior_deaths + [death_ts]
                            sweep_events.append(
                                (
                                    "orphaned_worker_recovered",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "new_status": "rework_requested",
                                        "reason": "dead_worker_with_approved_rework",
                                        "decision": "approved",
                                        "pr_state_status": pr_state_status,
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                        "worker_death_at": death_ts,
                                    },
                                )
                            )
                    else:
                        # Not the #1109 approved+rework_requested classified
                        # case. This branch covers two populations that share
                        # one fingerprinted drift fallback below:
                        #   (a) #1128: ``last_decision`` is None or "pending"
                        #       (open PR, no terminal review verdict yet) --
                        #       try advancing to ``pr-open``; on label-write
                        #       failure or missing details, fall through to
                        #       the shared drift. Issue #1362 Stage 1: this
                        #       must match ``_has_no_review_verdict_yet``'s
                        #       predicate above (``.missing or .decision ==
                        #       "pending"``) or a pending-packet PR would be
                        #       precomputed into ``pr_orphan_unreviewed_details``
                        #       but never consulted here, re-stranding the
                        #       issue on ``agent:in-progress``.
                        #   (b) genuinely unclassifiable decisions -- fall
                        #       through to the shared drift directly.
                        if last_decision is None or last_decision == "pending":
                            details = pr_orphan_unreviewed_details.get(issue_number)
                            if details is not None:
                                active_labels = details["active_labels"]
                                issue_labels = details["issue_labels"]
                                label_write_ok = True
                                for label in sorted(active_labels):
                                    if not gh.remove_issue_label(issue_number, label):
                                        label_write_ok = False
                                if config.labels.pr_open not in issue_labels:
                                    if not gh.add_issue_label(issue_number, config.labels.pr_open):
                                        label_write_ok = False
                                if label_write_ok:
                                    entry["status"] = PASSIVE_OPEN_STATUS
                                    entry["dispatched_at"] = None
                                    # Clear any prior drift fingerprint so a
                                    # later regression on this issue re-surfaces.
                                    entry["orphan_drift_fingerprint"] = None
                                    entry["orphan_drift_at"] = None
                                    sweep_events.append(
                                        (
                                            "orphaned_worker_advanced_to_pr_open",
                                            {
                                                "issue_number": issue_number,
                                                "pr_number": pr_number,
                                                "previous_status": "dispatched",
                                                "new_status": PASSIVE_OPEN_STATUS,
                                                "reason": "dead_worker_unsafe_to_auto_reset_open_unreviewed_pr",
                                                "removed_labels": sorted(active_labels),
                                                "pid": terminal_pid,
                                                "exit_code": terminal_exit_code,
                                                "duration_seconds": terminal_duration_seconds,
                                                "label_write_ok": True,
                                            },
                                        )
                                    )
                                    state["issues"][str(issue_number)] = entry
                                    continue
                                # Label write failed -- fall through to the
                                # fingerprinted drift path so the next pass
                                # re-attempts the transition (the drift
                                # fingerprint gates only re-emission of the
                                # diagnostic, not the transition retry above,
                                # which runs first on every pass).
                        # Genuinely unclassifiable decision, or #1128 label-
                        # write failure -- surface as drift once. One shared
                        # fingerprinted fallback for both lanes (#1109 keeps
                        # its own classified branch above; this covers
                        # everything else).
                        fingerprint = _drift_fingerprint(
                            reason="dead_worker_unsafe_to_auto_reset",
                            last_decision=last_decision or "",
                            pr_number=pr_number,
                        )
                        if entry.get("orphan_drift_fingerprint") != fingerprint:
                            entry["orphan_drift_fingerprint"] = fingerprint
                            entry["orphan_drift_at"] = utc_now()
                            sweep_events.append(
                                (
                                    "orphaned_worker_drift",
                                    {
                                        "issue_number": issue_number,
                                        "pr_number": pr_number,
                                        "previous_status": "dispatched",
                                        "last_decision": last_decision,
                                        "reason": "dead_worker_unsafe_to_auto_reset",
                                        "pid": terminal_pid,
                                        "exit_code": terminal_exit_code,
                                        "duration_seconds": terminal_duration_seconds,
                                    },
                                )
                            )
            else:
                # Issue #935: before reclaim/drift, try to open a PR for a branch
                # that the worker pushed but could not create a PR for.
                candidate = pushed_branch_candidates.get(issue_number)
                if candidate is not None:
                    details = no_pr_issue_details.get(issue_number, {})
                    # ``getattr(gh, "repo_root", None)`` is not statically typed,
                    # so it could in principle be any non-``Path`` value. Narrow
                    # it to ``Path | None`` before passing it to the salvage
                    # helper; ``None`` is a value the helper already handles by
                    # returning an error, which preserves the existing drift/hold
                    # behavior for no-repo-root orphans.
                    salvage_repo_root = repo_root if isinstance(repo_root, Path) else None
                    pr_number, pr_error, _closing_ref = _open_pr_for_orphaned_branch(
                        gh=gh,
                        config=config,
                        repo_root=salvage_repo_root,
                        branch=candidate["branch"],
                        base_ref=config.dispatch.base_ref,
                        issue_number=issue_number,
                        active_labels=details.get("active_labels", set()),
                        issue_labels=details.get("issue_labels", set()),
                        issue_title=(details.get("issue") or {}).get("title"),
                        state_file=state_file,
                    )
                    if pr_number is not None:
                        entry["status"] = PASSIVE_OPEN_STATUS
                        entry["pr_number"] = pr_number
                        sweep_events.append(
                            (
                                "orphaned_worker_opened_pr",
                                {
                                    "issue_number": issue_number,
                                    "pr_number": pr_number,
                                    "branch_name": candidate["branch"],
                                    "worker_reported": candidate["reported_push"],
                                    "ahead_count": candidate["ahead_count"],
                                    "previous_status": "dispatched",
                                    "reason": "dead_worker_branch_pushed_no_pr",
                                    "label_write_ok": pr_error is None,
                                    "pr_error": pr_error,
                                },
                            )
                        )
                        state["issues"][str(issue_number)] = entry
                        continue

                    # PR creation failed after the bounded outer retry
                    # (pr_create_retry.py) and the duplicate-PR guard both
                    # exhausted -- the branch is pushed and stranded (cw#1273).
                    # Reuses this sweep's existing _drift_fingerprint dedup
                    # path rather than inventing a parallel one; the "reason"
                    # value is preserved unchanged from before cw#1273 so the
                    # fingerprint (and any existing dedup state already on
                    # disk from before this change) stays stable.
                    fingerprint = _drift_fingerprint(
                        reason="dead_worker_branch_pushed_pr_create_failed",
                        branch_name=candidate["branch"],
                        error=pr_error or "unknown",
                    )
                    if entry.get("orphan_drift_fingerprint") == fingerprint:
                        state["issues"][str(issue_number)] = entry
                        continue
                    entry["orphan_drift_fingerprint"] = fingerprint
                    entry["orphan_drift_at"] = utc_now()
                    sweep_events.append(
                        (
                            "pr_create_failed_branch_stranded",
                            {
                                "issue_number": issue_number,
                                "branch_name": candidate["branch"],
                                "previous_status": "dispatched",
                                "reason": "dead_worker_branch_pushed_pr_create_failed",
                                "pr_create_error": pr_error,
                                "worker_reported": candidate["reported_push"],
                                "ahead_count": candidate["ahead_count"],
                            },
                        )
                    )
                    state["issues"][str(issue_number)] = entry
                    continue

                # Issue #1453: check whether the worker itself declared the
                # task structurally impossible (a ``blocked`` outcome in
                # ``.worker-outcome.json``, computed above, outside the state
                # lock).  The worker's own declaration is the most
                # authoritative signal -- check it FIRST, before the
                # zero-artifact and cross-repo heuristic escalations, so a
                # deliberate blocked analysis routes directly to the operator
                # queue with zero redispatches instead of burning the full
                # redispatch cap re-dispatching structurally impossible tasks.
                # The event payload carries ``reason_kind`` and ``detail`` so
                # the operator queue entry is actionable without reading the
                # worktree.
                blocked_escalation = worker_declared_blocked_escalations.get(issue_number)
                if blocked_escalation is not None:
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="worker_declared_blocked",
                        reason_class="mechanical",
                    )
                    escalated_entry = state["issues"][str(issue_number)]
                    escalated_entry["orphan_flagged_at"] = utc_now()
                    state["issues"][str(issue_number)] = escalated_entry
                    sweep_events.append(
                        (
                            "worker_declared_blocked",
                            {
                                "issue_number": issue_number,
                                "previous_status": "dispatched",
                                "reason": "worker_declared_blocked",
                                "reason_kind": blocked_escalation["reason_kind"],
                                "detail": blocked_escalation["detail"],
                                "removed_labels": blocked_escalation["removed_labels"],
                                "label_write_ok": blocked_escalation["label_write_ok"],
                            },
                        )
                    )
                    reap_escalations.append(issue_number)
                    continue

                # Issue #1153: check whether this issue was escalated to
                # ``agent:human-needed`` by the zero-artifact dispatch loop
                # guard (computed above, outside the state lock). If so,
                # record the escalation in state and emit a visible event --
                # do NOT fall through to the reclaim path (which would
                # re-add ``automated-ready`` and trigger another fruitless
                # redispatch).
                escalation = zero_artifact_escalations.get(issue_number)
                if escalation is not None:
                    # Route through ``_escalate_issue`` so the paired
                    # ``escalation_reason`` / ``reason_class`` /
                    # ``terminal_since`` fields are written atomically and
                    # the #750 structural guard (status="escalated" only
                    # inside the helper) continues to hold.
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="zero_artifact_dispatch_loop",
                        reason_class="mechanical",
                    )
                    escalated_entry = state["issues"][str(issue_number)]
                    escalated_entry["orphan_flagged_at"] = utc_now()
                    state["issues"][str(issue_number)] = escalated_entry
                    sweep_events.append(
                        (
                            "session_failed_escalated",
                            _session_failed_relabeled_payload(
                                issue_number=issue_number,
                                reason="zero_artifact_dispatch_loop",
                                removed_labels=escalation["removed_labels"],
                                added_ready=False,
                                label_write_ok=escalation["label_write_ok"],
                            ),
                        )
                    )
                    continue

                # Issue #1244: check whether this issue was escalated to
                # ``agent:human-needed`` by the cross-repo scope tripwire
                # (computed above, outside the state lock). If so, record the
                # escalation in state and emit a visible event — do NOT fall
                # through to the reclaim path (which would re-add
                # ``automated-ready`` and trigger another fruitless
                # redispatch that hops to the sibling repo again).
                scope_escalation = cross_repo_scope_escalations.get(issue_number)
                if scope_escalation is not None:
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="cross_repo_hop",
                        reason_class="mechanical",
                    )
                    escalated_entry = state["issues"][str(issue_number)]
                    escalated_entry["orphan_flagged_at"] = utc_now()
                    state["issues"][str(issue_number)] = escalated_entry
                    sweep_events.append(
                        (
                            "session_failed_escalated",
                            _session_failed_relabeled_payload(
                                issue_number=issue_number,
                                reason="cross_repo_hop",
                                removed_labels=scope_escalation["removed_labels"],
                                added_ready=False,
                                label_write_ok=scope_escalation["label_write_ok"],
                            ),
                        )
                    )
                    continue

                # Issue #1243: per-issue redispatch cap with stall detection.
                # The no-open-PR orphan-sweep redispatch path is the only
                # redispatch loop without a bound -- without this cap, a
                # persistent post-exit condition that leaves no open PR
                # reproduces the #709 infinite loop (worker exits -> sweep
                # strips agent:in-progress -> issue returns to the dispatchable
                # pool -> next pass redispatches -> repeat). The cap counts
                # dead *dispatches* via a timestamp list
                # (``orphan_redispatch_at``) deduplicated on dispatch identity,
                # mirroring the ``redispatch_at``/``worker_death_at`` pattern
                # used by the parallel worker_death_loop cap elsewhere in this
                # module.
                # The previous implementation derived the count from
                # ``len(adapter_history)``, but that list only grows when
                # ``api_worker.enabled`` is ``True`` (via
                # ``routing.record_adapter_choice``) -- so in the default
                # (non-API-routed) configuration the counter never incremented
                # and the cap never fired, leaving the #709 infinite loop
                # unbounded in production. The timestamp list is appended on
                # every sweep pass through this code, regardless of adapter
                # routing mode.
                # "No progress" is measured, not assumed: the branch head SHA
                # (remote ls-remote + local worktree) is compared across
                # attempts. A moving head is the salvage path's job, not
                # escalation. Parallel to the rework lane's worker_death_loop
                # (fires at death_count > max_auto_redispatch).
                head_details = no_pr_issue_details.get(issue_number, {})
                current_head = _orphan_head_fingerprint(
                    head_details.get("remote_head_sha"),
                    head_details.get("local_head_sha"),
                )
                prior_head = entry.get("orphan_redispatch_head_sha")
                now_ts = utc_now()

                head_changed = prior_head is not None and current_head != prior_head
                first_observation = prior_head is None
                # Identity of the dispatch whose dead worker this pass is
                # observing. The #417 reclaim deliberately leaves the entry's
                # status/worker_pid untouched (issue #282 fingerprint
                # preservation), so the same dead entry is re-discovered by
                # every subsequent sweep pass until a real redispatch replaces
                # dispatched_at/worker_pid. Counting passes would therefore
                # escalate after a few sweeps with zero actual redispatch
                # attempts (e.g. during fleet-capacity dispatch delays);
                # instead, each dead dispatch is counted exactly once, keyed
                # by this identity.
                dispatch_identity = (
                    f"{entry.get('dispatched_at') or 'none'}:{entry.get('worker_pid') or 'none'}"
                )
                prior_dispatch = entry.get("orphan_redispatch_counted_dispatch")
                # Read the windowed timestamp list. On progress or first
                # observation, reset it to [now] so only attempts after this
                # point count toward the cap. Otherwise, append this pass's
                # timestamp only when it observes a dispatch not yet counted
                # -- re-observing the same dead dispatch on a later sweep
                # pass is not a redispatch attempt. (The timestamp list, not
                # adapter_history, is still what the count derives from:
                # adapter_history only grows when api_worker.enabled is True.)
                orphan_redispatch_at = _windowed_orphan_redispatch_at(
                    entry, window_minutes=config.watchdog.redispatch_window_minutes
                )
                if head_changed or first_observation:
                    orphan_redispatch_at = [now_ts]
                elif dispatch_identity != prior_dispatch:
                    orphan_redispatch_at = orphan_redispatch_at + [now_ts]

                redispatch_count = len(orphan_redispatch_at)

                if redispatch_count > config.watchdog.max_auto_redispatch and not head_changed:
                    # Cap exceeded with no progress -- escalate instead of
                    # recording the relabel event that would return the issue
                    # to the dispatchable pool. The labels were already
                    # stripped in the pre-lock reclaim, but the post-lock
                    # transition() call (via reap_escalations) will change
                    # them to agent:human-needed.
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="orphan_sweep_redispatch_cap_exceeded",
                        reason_class="mechanical",
                        issue_extra={
                            "dispatched_at": None,
                            "orphan_redispatch_head_sha": current_head,
                            "orphan_redispatch_at": orphan_redispatch_at,
                            "orphan_redispatch_counted_dispatch": None,
                            "orphan_flagged_at": None,
                            "orphan_drift_fingerprint": None,
                            "orphan_drift_at": None,
                        },
                    )
                    sweep_events.append(
                        (
                            "orphan_sweep_redispatch_escalated",
                            {
                                "issue_number": issue_number,
                                "previous_status": "dispatched",
                                "reason": "orphan_sweep_redispatch_cap_exceeded",
                                "redispatch_count": redispatch_count,
                                "branch_head_sha": head_details.get("remote_head_sha"),
                                "worktree_head_sha": head_details.get("local_head_sha"),
                                "orphan_redispatch_at_len": len(orphan_redispatch_at),
                            },
                        )
                    )
                    reap_escalations.append(issue_number)
                    continue

                # Cap not exceeded (or progress detected): persist the head
                # fingerprint, timestamp list, and counted dispatch identity
                # so the next orphan-sweep pass can compare against them. On
                # progress or first observation, the list was just (re)seeded
                # above; this persists it.
                entry["orphan_redispatch_head_sha"] = current_head
                entry["orphan_redispatch_at"] = orphan_redispatch_at
                entry["orphan_redispatch_counted_dispatch"] = dispatch_identity

                # Issue #417: report (and, on success, resolve) the ground-truth
                # label reclaim computed above before falling back to the
                # unresolved-drift diagnostic. This is what makes the reap
                # convergent -- an interrupted or partially-failed attempt by
                # the sidecar-based lane is finished here, and a genuinely
                # failed label write is retried again next pass (this reclaim
                # never gates on orphan_flagged_at, only the diagnostic below
                # does).
                reclaim = reclaim_results.get(issue_number)
                if reclaim is not None:
                    sweep_events.append(
                        (
                            "session_failed_relabeled",
                            _session_failed_relabeled_payload(
                                issue_number=issue_number,
                                reason="dead_worker_no_open_pr_orphan_sweep",
                                **reclaim,
                            ),
                        )
                    )
                    if reclaim["label_write_ok"]:
                        # Fully reclaimed: labels are correct, nothing left to
                        # flag as unresolved drift. `status` deliberately stays
                        # "dispatched" here (matching the sidecar-based lane's
                        # own issue #282 fingerprint-preservation choice), so
                        # this same entry would otherwise be re-discovered by
                        # this sweep's very next pass and, having no more
                        # labels left to touch, fall through to the
                        # orphan_flagged_at diagnostic below and emit a
                        # spurious orphaned_worker_drift for an issue that is
                        # already fixed. Mark it flagged now so that never
                        # happens -- this lane's reclaim retry above never
                        # gates on this flag, only the diagnostic does.
                        entry["orphan_flagged_at"] = utc_now()
                        state["issues"][str(issue_number)] = entry
                        continue

                # No open PR - emit drift event, leave (further) recovery to
                # this same sweep's next pass, which re-attempts the ground-
                # truth label reclaim above unconditionally regardless of the
                # flag set here (issue #118 mop-up remains a manual fallback).
                # Issue #259: mark the entry so it is not re-flagged every pass.
                # Suppress ONLY the duplicate no-open-PR event; with-PR recovery
                # paths must run regardless of the flag.
                # Issue #1230: ``orphan_drift_at`` arms the
                # ``dead_dispatched_reap_minutes`` time-based backstop checked
                # at the top of this loop.  It must be backfilled whenever it
                # is missing, INDEPENDENTLY of the ``orphan_flagged_at``
                # duplicate-event guard below.  An entry that was flagged
                # before this stamp existed (pre-#1230 builds set only
                # ``orphan_flagged_at``) or via the reclaim-success branch
                # above (which deliberately omits ``orphan_drift_at``) has
                # ``orphan_flagged_at`` set but ``orphan_drift_at`` absent, so
                # the guard's early-return permanently blocks the backstop
                # from ever arming.  That is the wedge: the issue is not
                # re-dispatchable (a terminal label like ``agent:human-needed``
                # excludes it from the dispatchable pool), not sweepable
                # (status is not ``escalated``), and the backstop never fires
                # because ``orphan_drift_at`` was never set.  Backfill from
                # ``orphan_flagged_at`` so the grace period is measured from
                # when the drift was first observed -- an already-wedged entry
                # (e.g. jc #1421, flagged 4+ days ago) converges on the very
                # next sweep pass instead of waiting another full grace window.
                # The reclaim-success branch above deliberately does NOT set
                # ``orphan_drift_at`` -- that path leaves the issue ``ready``
                # and re-dispatchable, so the backstop should not fire on the
                # pass that reclaimed it.  This backfill only arms the backstop
                # for entries that reach THIS drift branch (nothing to reclaim
                # or reclaim failed), which means the issue is not on the
                # normal re-dispatch path and the backstop is the correct
                # convergence mechanism.
                if (
                    entry.get("orphan_drift_at") is None
                    and entry.get("orphan_flagged_at") is not None
                ):
                    entry["orphan_drift_at"] = entry["orphan_flagged_at"]
                if entry.get("orphan_flagged_at"):
                    state["issues"][str(issue_number)] = entry
                    continue
                drift_ts = utc_now()
                entry["orphan_flagged_at"] = drift_ts
                entry["orphan_drift_at"] = drift_ts
                sweep_events.append(
                    (
                        "orphaned_worker_drift",
                        {
                            "issue_number": issue_number,
                            "previous_status": "dispatched",
                            "reason": "dead_worker_no_open_pr",
                        },
                    )
                )

            state["issues"][str(issue_number)] = entry

        state = _append_sweep_events(
            state,
            sweep_events,
            max_size=config.runtime.event_ring_size,
            state_file=state_file,
            write_gate=write_gate,
        )
        write_gate.save_state(state)

    # Route head-advanced request_changes findings to the review lane outside
    # the state lock. review() generates the packet, fires the review_started
    # label transition, and returns ok when a fresh packet is produced. We then
    # flip the issue status to "reviewing" so it is not re-detected as an orphan
    # on every subsequent pass. If review() fails, we record a drift fingerprint
    # so the identical finding is not re-emitted every pass.
    for (
        issue_number,
        pr_number,
        reviewed_head_sha_before,
        live_head_sha,
        fingerprint,
    ) in review_routes:
        if review_callback is None:
            continue
        review_result = review_callback(pr_number)
        routed = False
        # See _route_rework_candidate_to_review's matching comment: review()
        # can return ok=True for the janitor-gate conflict/no-op-rework route
        # (no packet, no review_started transition) as well as for a real
        # packet. Only a real packet should flip this orphaned-but-dispatched
        # issue to "reviewing".
        routed_to_rework = bool(review_result.data.get("routed_to_rework"))
        # Issue #558: review() also returns ok=True when it converges a
        # CLOSED-unmerged PR's state entry to "closed" at the janitor gate.
        # That is not a fresh packet -- the PR is dead, not transiently
        # blocked -- so it must NOT flip this issue to "reviewing" (an
        # ACTIVE_STATE_STATUS no reconcile rule clears while the GitHub
        # issue itself stays open: issue_active_label_no_open_pr sees the
        # closed PR still links to the issue, issue_active_label_with_open_pr
        # sees no OPEN PR, and the unknown-status recompute sweep skips
        # "reviewing" because it is a VALID_ISSUE_STATUSES member). The
        # issue's disposition is left to the existing closed-unmerged
        # issue-side handling (closed_unmerged_pr_active_labels). Neither
        # the "reviewing" flip nor the transient-block drift fingerprint
        # below applies to a permanently-dead PR.
        closed_unmerged_converged = bool(review_result.data.get("closed_unmerged_converged"))
        with state_lock(state_file):
            state = load_state(state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            entry = state["issues"].get(str(issue_number), {})
            decision_unchanged = pr_state.get("reviewed_head_sha") == reviewed_head_sha_before
            if (
                review_result.ok
                and not routed_to_rework
                and not closed_unmerged_converged
                and decision_unchanged
                and isinstance(entry, dict)
                and entry.get("status") == "dispatched"
            ):
                state["issues"][str(issue_number)] = {**entry, "status": "reviewing"}
                routed = True
            elif (
                not review_result.ok
                and not routed_to_rework
                and isinstance(entry, dict)
                and entry.get("status") == "dispatched"
            ):
                # Review failed: mark the drift fingerprint so the next pass
                # does not retry/re-emit for this unchanged head.
                state["issues"][str(issue_number)] = {
                    **entry,
                    "orphan_drift_fingerprint": fingerprint,
                    "orphan_drift_at": utc_now(),
                }
            state = write_gate.append_event(
                state,
                "orphaned_worker_routed_to_review"
                if review_result.ok
                else "orphaned_worker_drift",
                {
                    "issue_number": issue_number,
                    "pr_number": pr_number,
                    "review_ok": review_result.ok,
                    "routed": routed,
                    "live_head_sha": live_head_sha,
                    "reviewed_head_sha": reviewed_head_sha_before,
                    "reason": "dead_worker_with_head_change",
                },
            )
            write_gate.save_state(state)

    # Issue #654: apply the ``escalated`` label edge for dead dispatched
    # workers that exceeded the reap grace period. The state.json update
    # (``_escalate_issue``) was done inside the lock above; ``transition``
    # does network I/O (GitHub label API) so it runs here, outside the lock,
    # matching the pattern ``_check_janitor_rework_stall`` uses. A failed
    # transition leaves the issue escalated in state.json with a stale label
    # -- the next pass's ``_detect_and_handle_orphaned_workers`` will not
    # re-escalate (status is no longer ``dispatched``), but reconcile's
    # ground-truth label sweep will eventually converge the label.
    for issue_number in reap_escalations:
        write_gate.transition(
            gh, config.labels, issue_number, _escalation_edge("escalated", "mechanical")
        )


# Issue #713: canonical key sets each prompt writer supplies to
# ``render_prompt`` -- the explicit ``values`` dict, excluding the dynamic
# ``$section_*`` partials ``section_variables`` discovers on disk. Used by
# ``check_prompt_template_drift`` to fail fast -- at supervisor startup and
# in CI -- when a repo-local flat whole-file override references a
# placeholder the writer no longer provides. This is the durable,
# structural fix for the bug class where job-cannon's flat ``rework.md``
# override kept ``$review_summary`` after commit 5844c34 (PR #661) renamed
# the writer's slot to ``$dispatch_note`` / ``$required_changes_section``:
# ``render_prompt``'s strict mode catches the crash at dispatch time, but
# nothing caught it *before* dispatch, so it stayed live-armed on a running
# process until the next rework dispatch actually fired.
#
# The subset direction is deliberate: an override legitimately uses fewer
# placeholders than the writer supplies (job-cannon's ``worker.md`` uses 6
# of these 8 worker keys), so the check fails only when the template reaches
# for a placeholder the writer never provides -- never when it merely
# ignores one the writer does. The reverse direction (every supplied key
# used) is not an error; at most a lint.
#
# Kept honest against the real writers by the registry-drift guard in
# ``tests/test_prompt_template_drift_check.py``, which monkeypatches
# ``render_prompt`` to capture the keys the writer actually passes and
# asserts these frozensets match exactly.
WORKER_PROMPT_KEYS: frozenset[str] = frozenset(
    # OrchestratorApp._write_worker_prompt -- the literal ``values`` dict
    # passed to ``self._render`` (see the writer below in this file).
    {
        "issue_number",
        "issue_title",
        "issue_url",
        "issue_body",
        "issue_body_block",
        "issue_comments",
        "branch_name",
        "worker_model_tier",
        # Issue #1444: the module-map section, derived from the live tree at
        # packet build time by ``build_module_map``. Empty string when the map
        # could not be derived (fail-soft: omitted section + a
        # ``worker_module_map_failed`` warning event), never a dispatch
        # failure.
        "module_map",
        # Issue #1460: the attachment-point placement clause, gated on
        # `.attachment-budgets.json` presence. Empty string when the marker
        # is absent or fails to load (fail-soft: omitted clause + a
        # ``worker_attachment_budget_failed`` warning event), never a
        # dispatch failure. Deliberately NOT added to REWORK_PROMPT_KEYS --
        # the rework lane receives budget findings via the review packet's
        # `$attachment_budget_section` instead.
        "attachment_budget",
    }
)
REWORK_PROMPT_KEYS: frozenset[str] = frozenset(
    # _render_rework_prompt -- the literal ``values`` dict passed to
    # ``render_prompt`` (see the writer below in this file).
    {
        "pr_number",
        "pr_title",
        "pr_url",
        "issue_number",
        "dispatch_note",
        "dispatch_note_block",
        "required_changes_section",
        "branch_name",
    }
)

# Issue #1265: every writer of a review-decision verdict must say WHERE the
# decision came from. This is a distinct field from the pre-existing
# ``session_metrics.verdict_source`` (set in ``_reap_review_verdicts``,
# meaning "which parser found the reviewer's fenced verdict block" --
# log/events/file:{source}). ``verdict_provenance`` instead means "which
# mechanism produced this verdict at all" and is required (no default,
# anywhere) on every ``record_review`` call and on the two writers that
# bypass ``record_review`` entirely (``_update_approval_head``'s carry-
# forward patch, and the pending-reset template). Follows the same
# plain-string-checked-against-a-set convention ``record_review`` already
# uses for ``decision`` -- deliberately not an Enum type.
#
# Mapping (one call site can share a value; a value need not have exactly
# one call site -- ``carried_forward`` has none in ``record_review`` at all,
# it is stamped directly by ``_update_approval_head``):
#   ci_gate_auto_reject       -- review()'s CI-gate reject (sole failing
#                                check, and the co-occurring-janitor-failure
#                                variant added by #1258/#1286)
#   test_adequacy_auto_reject -- review()'s test-adequacy hard-gate reject
#                                (issue #179; a distinct mechanism from the
#                                CI gate, not folded into it)
#   fresh_llm_review          -- _reap_review_verdicts (a live reviewer's
#                                parsed verdict)
#   stranded_reconciliation   -- _reconcile_stranded_verdicts (issue #736: a
#                                completed on-disk verdict whose state write
#                                was lost, re-ingested from review-
#                                decision.json -- not a fresh decision)
#   cross_family_review       -- _record_cross_family_verdicts
#   unparseable_exhausted     -- _handle_malformed_cross_family_verdict's
#                                bound-exhaustion synthetic approve
#   rescue_review             -- rescue-tier review's approve
#   operator_manual           -- cli.py's ``charlie verdict`` command
#   carried_forward           -- _update_approval_head (never via
#                                record_review; stamped directly on the
#                                decision-file patch and all three
#                                verdict_carried_forward_* event payloads)
VERDICT_PROVENANCE_VALUES: frozenset[str] = frozenset(
    {
        "ci_gate_auto_reject",
        "test_adequacy_auto_reject",
        "fresh_llm_review",
        "stranded_reconciliation",
        "cross_family_review",
        "unparseable_exhausted",
        "rescue_review",
        "operator_manual",
        "carried_forward",
    }
)


class PromptOverrideDriftError(RuntimeError):
    """One or more configured prompt templates reference placeholders their
    writer does not supply (issue #713).

    Raised at supervisor startup (and asserted in CI) by
    :func:`check_prompt_template_drift` so a repo-local flat whole-file
    override that drifted out of sync with the orchestrator's writer -- e.g.
    a flat ``rework.md`` still referencing ``$review_summary`` after the
    writer renamed it to ``$dispatch_note`` -- fails fast before any
    dispatch, instead of staying live-armed until the next dispatch crashes
    with an uncaught :class:`PromptTemplateError`.
    """

    def __init__(self, errors: Sequence["PromptTemplateError"]) -> None:
        self.errors = tuple(errors)
        details = "; ".join(str(error) for error in self.errors)
        super().__init__(
            f"prompt template drift detected (issue #713); refusing to start: {details}"
        )


def check_prompt_template_drift(
    config: OrchestratorConfig, *, search_dirs: Sequence[Path] = ()
) -> list[PromptTemplateError]:
    """Static placeholder-subset check for every configured prompt template.

    For each template dispatch will render -- the configured worker/rework
    templates from ``DispatchConfig`` and ``ApiWorkerConfig`` -- resolve it the
    way dispatch would (repo-local override first, then the package default)
    and assert every ``$placeholder`` it references (after expanding the
    ``$section_*`` partials it pulls in) is a subset of the key set the
    corresponding writer supplies together with the section variables
    discovered on disk. Returns a list of :class:`PromptTemplateError` values,
    one per drifting template; an empty list means every configured template
    is safe to render.

    Pure static check: no dispatch, no worker, no network. It reads template
    and section files off disk only, so it runs at supervisor startup
    (``OrchestratorApp.__init__``) and in CI -- catching the #713 bug class
    (a flat override armed with a stale placeholder) before it can crash a
    live dispatch.

    A configured template name that resolves to no file (a typo, or a custom
    name neither the override nor the package ships) is skipped here: that is
    a separate config error dispatch surfaces as a ``FileNotFoundError``, not
    placeholder drift, and conflating the two would muddy the drift report.
    """
    pairs: list[tuple[str, frozenset[str]]] = [
        (config.dispatch.worker_template, WORKER_PROMPT_KEYS),
        (config.dispatch.rework_template, REWORK_PROMPT_KEYS),
        (config.api_worker.worker_template, WORKER_PROMPT_KEYS),
        (config.api_worker.rework_template, REWORK_PROMPT_KEYS),
    ]
    errors: list[PromptTemplateError] = []
    seen: set[str] = set()
    for template_name, keys in pairs:
        if template_name in seen:
            continue
        seen.add(template_name)
        resolved = resolve_template(template_name, search_dirs)
        if not resolved.is_file():
            continue
        missing = unsupplied_placeholders(template_name, keys, search_dirs=search_dirs)
        if missing:
            errors.append(PromptTemplateError(resolved, missing))
    return errors


ORCHESTRATOR_COMMENT_MARKER = "<!-- charlie-work:orchestrator-generated -->"
"""Provenance marker stamped into every PR comment the orchestrator writes.

Issue #950's external-findings ingestion cannot use author identity to tell its
own output apart from a human's: the orchestrator authenticates with a *user*
token, so ``gh api user`` reports ``type=User`` and its comments are
indistinguishable from genuine review comments by the same person. Filtering on
the login would suppress exactly the human findings the feature exists to
capture.

So provenance travels in the body instead. ``_comment_pr`` stamps this marker;
``_is_orchestrator_comment`` skips anything carrying it. An HTML comment is
invisible in rendered markdown, so the posted comment is unchanged for readers.

Note this covers only comments written by *this* process. A worker's own rework
reply is machine-generated too and is not stamped here -- it is excluded from
ingestion by a *temporal* cutoff instead (issue #998): ``_collect_external_findings``
drops any comment posted after the reviewed head commit's committer date, and a
worker's reply is by construction posted after the rework commit it describes.
"""


def _is_orchestrator_comment(item: dict[str, Any]) -> bool:
    """Return True if a comment body *begins* with the orchestrator's provenance marker.

    Deliberately a prefix test, not a substring test. ``_comment_pr`` writes the
    marker as the literal first line, so a prefix check catches every comment this
    process posts -- and a substring check would catch strictly more than that, in
    the one direction that costs real findings.

    The extra case a substring check would swallow: GitHub's "Quote reply" inserts
    the *raw markdown* of the quoted comment, HTML comments included, as a
    blockquote above the reply. Quote-replying to one of our ``request_changes``
    comments is a natural way for a human to respond point by point, and the
    resulting body contains the marker without starting with it. Under a substring
    test that whole comment -- quote plus whatever new finding the human wrote
    below it -- is dropped from ``required_changes`` silently.

    Dropping a genuine human finding is worse than ingesting one of our own
    comments, so this predicate is written to fail toward ingestion.
    """
    body = item.get("body")
    return isinstance(body, str) and body.lstrip().startswith(ORCHESTRATOR_COMMENT_MARKER)


def _is_bot_comment(item: dict[str, Any]) -> bool:
    """Return True if a comment/review author is a GitHub App/bot account.

    Uses the API-supplied ``user.type``/``author.type`` or ``author.is_bot``
    discriminator. Does not rely on a hardcoded login list.

    This catches genuine GitHub Apps (Aviator, dependabot, ...) but *not* the
    orchestrator itself, which posts under a user token -- see
    ``ORCHESTRATOR_COMMENT_MARKER``.
    """
    user = item.get("user")
    if isinstance(user, dict) and user.get("type") == "Bot":
        return True
    author = item.get("author")
    if isinstance(author, dict):
        if author.get("type") == "Bot" or author.get("is_bot") is True:
            return True
    return False


def _gh_api_list(gh: GitHubLike, path: str) -> list[dict[str, Any]]:
    """Call ``gh api --paginate <path>`` and return a list, swallowing errors."""
    result = gh.run(
        ["api", "--paginate", path],
        json_output=True,
        allow_failure=True,
    )
    if isinstance(result, GitHubRunResult):
        if not result.ok or not isinstance(result.value, list):
            return []
        return result.value
    if isinstance(result, list):
        return [item for item in result if isinstance(item, dict)]
    return []


def _commit_timestamp(gh: GitHubLike, sha: str | None) -> str | None:
    """Return the committer-date ISO 8601 timestamp of commit ``sha``, or None.

    Wraps ``gh.commit(sha)`` (``gh api repos/{owner}/{repo}/commits/{sha}``) and
    reads ``commit.committer.date`` -- the moment the commit landed on the
    branch, which is what the external-findings upper bound (issue #998) needs
    to compare against comment timestamps. The author date is user-settable and
    can be backdated, so it is *not* used as the cutoff; the committer date is
    the GitHub-recorded landing time.

    Errors are returned as ``None``, never raised -- consistent with this
    repo's errors-as-values invariant. A ``None`` return tells
    ``_collect_external_findings`` to skip the upper bound entirely (fail
    toward ingestion): losing a genuine human finding is the expensive
    direction of this filter, and a missing commit timestamp must not silently
    drop comments.
    """
    if not sha:
        return None
    result = gh.commit(sha)
    value = result.value if isinstance(result, GitHubRunResult) and result.ok else None
    if not isinstance(value, dict):
        return None
    commit = value.get("commit")
    if not isinstance(commit, dict):
        return None
    committer = commit.get("committer")
    if isinstance(committer, dict):
        date = committer.get("date")
        if isinstance(date, str) and date:
            return date
    # Fall back to the author date only if the committer date is entirely
    # absent -- rare, but a squash with a crafted author/committer split could
    # leave committer empty. Author date is less authoritative (settable) but
    # still bounds the comment window better than no cutoff at all.
    author = commit.get("author")
    if isinstance(author, dict):
        date = author.get("date")
        if isinstance(date, str) and date:
            return date
    return None


def _collect_external_findings(
    gh: GitHubLike,
    pr_number: int,
    *,
    since: str | None = None,
    before: str | None = None,
) -> list[str]:
    """Collect non-bot human feedback from the three external PR surfaces.

    Fetches issue-level comments, review bodies, and inline review comments.
    Returns a flat list of markdown bodies ready to be folded into
    ``review-decision.json`` at record time.

    Three provenance/content filters apply, and they are deliberately
    different in kind:

    * **Bots** are excluded by author (``user.type == "Bot"``) -- GitHub Apps
      such as Aviator have their own identity, so identity is a sound
      discriminator for them.
    * **The orchestrator's own comments** are excluded by *body marker*, not by
      author. The orchestrator posts through a user token, so its comments are
      indistinguishable by identity from a genuine human review by the same
      person, and filtering on that login would drop exactly the findings #950
      exists to ingest. See ``ORCHESTRATOR_COMMENT_MARKER``.
    * **Reviewer-session crash summaries** are excluded by *body content*
      (issue #1269, W12): ``_extract_review_session_summary`` posts these
      when a reviewer dies without a verdict, and every one predating the
      ``ORCHESTRATOR_COMMENT_MARKER`` stamp (added #1242/55cecd9) carries no
      marker for the filter above to catch -- they were ingested as if they
      were genuine human findings. See ``body_has_crash_signature``. This
      filter only stops *new* ingestion; already-persisted poisoned records
      are cleaned separately, at render time, by
      ``rework_prompts._render_required_changes_section``.

    ``since``, when given, is the previous round's *upper* bound -- the
    ``before`` timestamp that round persisted in ``review-decision.json``
    (falling back to that round's ``reviewed_at`` only when no ``before`` was
    recorded; see ``record_review``'s contiguity note). An item timestamped
    at or before ``since`` was already visible -- either surfaced in a prior
    round's ``required_changes`` or predating review entirely -- so it is
    skipped. This is what stops a rework loop from re-ingesting the same stale
    findings on every round: without it, ``_write_rework_prompt`` buries the
    one new finding under the full comment history every time.

    ``before``, when given, is the *current* round's ``reviewed_head_sha``
    committer-date timestamp (see ``_commit_timestamp``). An item timestamped
    strictly after ``before`` is skipped. This is the upper bound that closes
    issue #998: a worker's own rework reply ("Reworked in <sha>, here is what
    I changed") is machine-generated, posted through the worker's path (no
    ``ORCHESTRATOR_COMMENT_MARKER``), and -- critically -- posted *after* the
    rework commit it describes, which is exactly the head the reviewer is now
    reading. Cutting ingestion off at that head's commit time drops the reply
    without any cooperation from the worker's posting path, and it also stops
    findings the worker has already addressed from being re-presented every
    round. The same account/``type=User`` constraint that defeated an
    identity-based fix in #997 applies here too, so the cutoff is temporal,
    not by author: a genuine human comment posted *before* the reviewed head
    is still ingested (asserted positively by
    ``test_worker_rework_reply_is_not_ingested_as_external_finding``).

    Contiguity contract: ``since`` and ``before`` together partition the
    comment timeline into per-round half-open windows ``(since, before]``, and
    the next round's ``since`` is this round's persisted ``before``. A comment
    in the gap ``(before, reviewed_at]`` -- posted after the reviewed head
    landed but before the verdict was written -- is excluded by ``before``
    this round and recovered by ``since`` next round. Deriving ``since`` from
    ``reviewed_at`` instead would drop such a comment forever (it satisfies
    ``item_dt <= reviewed_at``), violating the fail-toward-ingestion
    invariant. This is pinned by
    ``test_human_comment_in_before_to_reviewed_at_gap_surfaces_next_round``.

    GitHub's list endpoints disagree on which field carries the timestamp --
    issue comments and inline review comments use ``created_at``, top-level
    review bodies use ``submitted_at`` -- so both are checked per item. An
    item with neither field (or an unparsable one) is never skipped by either
    bound: losing a genuine finding is the expensive direction of this filter
    (see ``test_human_quote_reply_to_orchestrator_comment_is_still_ingested``).
    Likewise, if ``before`` cannot be parsed (or the commit timestamp could
    not be resolved at the call site) the upper bound is not applied -- the
    filter fails toward ingestion, never toward silent suppression.

    Issue #1269 (W12): the three surfaces are walked and combined into one
    list first, and *that* combined list is deduplicated by exact-string
    equality (``dict.fromkeys``, first-occurrence order preserved) at the
    end -- the end-position dedup is required precisely because duplicates
    are cross-surface, not just within one: a reviewer-session crash summary
    is frequently reposted byte-for-byte across issue comments and review
    bodies within the same round (the crash-recovery path posts to more
    than one surface), so deduplicating each surface independently before
    combining would miss exactly the duplicates this exists to catch. Exact
    equality only, no whitespace normalization beyond the existing
    ``.strip()`` above: two genuinely different findings that happen to
    share a substring must stay distinct.
    """
    bodies: list[str] = []
    owner_repo = "{owner}/{repo}"

    surfaces = (
        # A PR is also an issue, so issue-level comments live here.
        f"repos/{owner_repo}/issues/{pr_number}/comments",
        # Top-level PR review bodies.
        f"repos/{owner_repo}/pulls/{pr_number}/reviews",
        # Inline review comments on specific diff lines.
        f"repos/{owner_repo}/pulls/{pr_number}/comments",
    )

    since_dt = _parse_iso_timestamp(since) if since else None
    before_dt = _parse_iso_timestamp(before) if before else None

    for path in surfaces:
        for item in _gh_api_list(gh, path):
            if _is_bot_comment(item) or _is_orchestrator_comment(item):
                continue
            item_dt = _parse_iso_timestamp(item.get("created_at") or item.get("submitted_at"))
            if item_dt is not None:
                if since_dt is not None and item_dt <= since_dt:
                    continue
                if before_dt is not None and item_dt > before_dt:
                    continue
            body_value = item.get("body")
            if not isinstance(body_value, str):
                continue
            body = body_value.strip()
            if body and not body_has_crash_signature(body):
                bodies.append(body)

    # Issue #1269 (W12): collapse exact-duplicate bodies (see docstring
    # above). dict.fromkeys preserves first-occurrence order in O(n).
    return list(dict.fromkeys(bodies))


# Issue #1268 (W11), item 2: bound how much verdict prose a single
# ``record_review`` events.db row can carry. events.db is append-only and
# unbounded (unlike the capped in-memory events ring), so unbounded reviewer
# prose would grow the DB file without limit; the round-K archive (above) is
# the full-text source of truth, this is an observability-only copy. A
# distinct helper from ``_truncate_reason`` deliberately: that one has
# existing callers depending on its 200-char/``"..."`` contract, and
# retuning it for a 16KB/``"...truncated"`` use would risk their behavior.
_EVENT_TEXT_MAX_BYTES = 16 * 1024
_EVENT_TRUNCATE_MARKER = "...truncated"


def _truncate_for_event(text: str, max_bytes: int = _EVENT_TEXT_MAX_BYTES) -> str:
    """Truncate ``text`` to at most ``max_bytes`` UTF-8 bytes for an event payload.

    Byte-based, not character-based -- the budget is a DB-row-size concern,
    and reviewer prose is not guaranteed ASCII. ``errors="ignore"`` on the
    final decode can drop a partial multi-byte character sitting exactly at
    the cut boundary, so the truncated result's encoded length is only
    guaranteed to be ``<= max_bytes``, not exactly equal to it.
    """
    encoded = text.encode("utf-8")
    if len(encoded) <= max_bytes:
        return text
    marker_bytes = _EVENT_TRUNCATE_MARKER.encode("utf-8")
    keep = max(0, max_bytes - len(marker_bytes))
    return encoded[:keep].decode("utf-8", errors="ignore") + _EVENT_TRUNCATE_MARKER


def _is_readiness_no_ci_stall(
    pr: dict[str, Any],
    checks: list[dict[str, Any]],
    config: AutoMergeConfig,
    now: datetime,
) -> bool:
    """Detect an approved PR whose required checks have never started.

    Returns True when:
      * ``pr_checks`` returned a parseable (non-None) list;
      * none of the configured ``required_checks`` appear in that list;
      * the PR's ``updatedAt`` is older than ``readiness_no_ci_minutes``.

    The required check names come from ``config.required_checks``; no names are
    hard-coded. ``updatedAt`` is the best available proxy for "head SHA pushed"
    in the ``gh pr view`` JSON field list.
    """
    no_ci_minutes = config.readiness_no_ci_minutes
    if no_ci_minutes <= 0:
        return False
    required = config.required_checks
    if not required:
        return False
    seen = {str(check.get("name") or "") for check in checks}
    if any(name in seen for name in required):
        return False
    return _is_pr_updated_at_older_than(pr, now, no_ci_minutes)


def _build_attention_digest(
    state_file: Path,
    health_transitions: dict[int, dict[str, Any]],
    repo: str,
    state_field: str = "health",
) -> AttentionDigest | None:
    """Build an AttentionDigest from health transitions observed in a pass.

    Args:
        state_file: Path to state.json for reading/writing per-issue health baseline
        health_transitions: Dict mapping issue_number to transition data:
            {
                issue_number: {
                    "adapter_kind": str,
                    "health": str,  # current health (e.g., "STALLED", "RUNAWAY", "DEAD")
                    "last_log_line": str | None,
                    "pid": int | None,
                    "terminal_tool": str | None,  # issue #261: post-mortem terminal tool (DEAD only)
                    "terminal_reason": str | None,  # issue #261: one-line terminal cause
                }
            }
        repo: Repository name for the digest
        state_field: The state["issues"][n] field to read/write for transition
            comparison. Defaults to "health"; callers tracking a separate alert
            dimension (e.g. merge_alert) can pass their own field name.

    Returns:
        AttentionDigest if there are transitions, None otherwise. Updates per-issue
        health field in state.json to the current health for transition comparison
        on the next pass.
    """
    if not health_transitions:
        return None

    from .state import load_state, save_state, state_lock
    from .state import utc_now

    entries: list[AttentionEntry] = []

    with state_lock(state_file):
        state = load_state(state_file)

        for issue_number, transition in health_transitions.items():
            current_health = transition["health"]

            # Read the last persisted health for this issue
            issue_key = str(issue_number)
            issue_entry = state.get("issues", {}).get(issue_key, {})
            last_health = issue_entry.get(state_field)

            # Only include if health changed (or no previous health persisted)
            if last_health != current_health:
                entries.append(
                    AttentionEntry(
                        issue_number=issue_number,
                        adapter_kind=transition["adapter_kind"],
                        health=current_health,
                        previous_health=last_health,
                        last_log_line=transition.get("last_log_line"),
                        pid=transition.get("pid"),
                        terminal_tool=transition.get("terminal_tool"),
                        terminal_reason=transition.get("terminal_reason"),
                    )
                )

                # Update the persisted health for this issue
                state["issues"][issue_key] = {
                    **issue_entry,
                    state_field: current_health,
                }

        # Save the updated health baselines
        if entries:
            save_state(state_file, state)

    if not entries:
        return None

    return AttentionDigest(
        generated_at=utc_now(),
        repo=repo,
        transitions=tuple(entries),
    )


def _is_pending_only(summary: CheckSummary) -> bool:
    """Return True if the only reason the PR cannot merge is in-flight checks.

    A summary whose only defect is pending checks is not a structural merge
    failure; it should not arm the failed-attempt alarm.
    """
    return (
        bool(summary.pending)
        and not summary.failed
        and not summary.missing
        and not summary.infra_failed
        and not summary.infra_blocked
        and not summary.unavailable
    )


def _format_merge_attempt_alarm_message(
    pr_number: int,
    attempts: int,
    summary: CheckSummary,
    mergeable: str | None = None,
    merge_state_status: str | None = None,
) -> str:
    """Human-readable alarm message for an approved PR that cannot merge.

    The message is surfaced in pass warnings, the merge_failed_attempt_alarm
    state event, and the notify digest terminal_reason.
    """
    buckets: list[str] = []
    if summary.missing:
        # Issue #253 signature: required checks missing while the PR is still open
        buckets.append("required checks missing while GitHub shows the PR open")
    if summary.pending:
        buckets.append(f"pending: {', '.join(summary.pending)}")
    if summary.failed:
        buckets.append(f"failed: {', '.join(summary.failed)}")
    if summary.infra_failed:
        buckets.append(f"infra_failed: {', '.join(summary.infra_failed)}")
    if summary.infra_blocked:
        buckets.append(f"infra_blocked: {', '.join(summary.infra_blocked)}")
    if summary.unavailable:
        # gh reported no parseable check list at all (see summarize_checks'
        # `checks is None` branch) — distinct from "all required checks
        # passed", so it must not fall into the passed-but-unmergeable
        # bucket below.
        buckets.append(f"unavailable: {', '.join(summary.unavailable)}")
    if not buckets:
        # Issue #751: every check-summary bucket above is empty, which means
        # the checks the bot tracks are not why this PR is stuck — GitHub's
        # own mergeability signal is (a lagging/absent CONFLICTING reading, a
        # BLOCKED merge state, branch protection, or a merge-base freshness
        # result that isn't one of the explicitly modelled branches above).
        # Surface what `pr_view` already fetched instead of discarding it;
        # only fall back to the generic "unknown" text when GitHub hasn't
        # reported anything usable either, so that case stays distinguishable.
        norm_mergeable = str(mergeable or "").upper()
        norm_merge_state = str(merge_state_status or "").upper()
        known_mergeable = bool(norm_mergeable) and norm_mergeable != "UNKNOWN"
        known_merge_state = bool(norm_merge_state) and norm_merge_state != "UNKNOWN"
        if known_mergeable or known_merge_state:
            buckets.append(
                f"mergeable={norm_mergeable or 'UNKNOWN'}, "
                f"mergeStateStatus={norm_merge_state or 'UNKNOWN'}, "
                "all required checks passed"
            )
        else:
            buckets.append("check summary unknown")
    checks_str = "; ".join(buckets)
    pass_str = "pass" if attempts == 1 else "passes"
    return f"PR #{pr_number} approved but unmergeable for {attempts} {pass_str}: {checks_str}"


def _format_stale_base_alarm_message(pr_number: int, attempts: int, reason: str) -> str:
    """Human-readable alarm message for an approved PR whose base is not current."""
    pass_str = "pass" if attempts == 1 else "passes"
    if reason == "base_stale":
        detail = "base is stale"
    elif reason == "compare_unavailable":
        detail = "base freshness comparison unavailable"
    else:
        detail = f"base is not current (reason: {reason})"
    return f"PR #{pr_number} approved but {detail} for {attempts} consecutive {pass_str}"


# Sentinel used to distinguish "no base-current signal was supplied" from
# an explicit ``None`` (compare API unavailable) in _should_update_pr_branch.
class _BaseCurrentUnset:
    __slots__ = ()


_BASE_CURRENT_UNSET = _BaseCurrentUnset()


@dataclass(frozen=True)
class _MergedPRListOutcome:
    items: list[dict[str, Any]] = field(default_factory=list)
    error: GitHubError | None = None
    called: bool = False


def _is_rerun_already_running_error(error: str) -> bool:
    """Return True if a ``gh run rerun`` error means the run is still in progress.

    GitHub refuses to rerun a workflow while any job in the run is still
    running. The CLI surfaces this with the phrase ``already running`` in the
    error, e.g. ``run <id> cannot be rerun; This workflow is already running``
    or ``The workflow run containing this job is already running``. Other
    refusal reasons (expired run, broken workflow file, missing permissions,
    ...) do not contain this phrase and should not be treated as retryable.
    """
    return "already running" in error.lower()


def _try_reap_blocked_foreign_writer(
    failed_result: Any,
    config: OrchestratorConfig,
    state_file: Path,
    issue_number: int,
    sessions_dir: Path,
) -> bool:
    """Attempt to reap an idle foreign writer at the blocked-environment cap.

    Issue #1423: when the ``blocked_environment_at`` counter exhausts the
    ``max_auto_redispatch`` cap for a ``worktree_foreign_writer`` failure,
    the default action is to escalate the issue to a human. But a writer that
    was active on earlier passes and has since gone idle is a zombie the fleet
    itself launched and forgot — escalating it wastes a human's attention on
    a process the stall detector would have reaped if it could see it.

    This helper reads the marker from the failed dispatch's worktree path and
    delegates to ``_reap_idle_foreign_writer`` (the single enforcement point
    for every reap-candidate guard + the activity probe + kill path). When the
    writer is idle past the threshold, it is reaped and the caller resets the
    counter instead of escalating. When the writer is still active, the caller
    escalates as before — escalation is reserved for a writer that is alive
    *and* active.

    Issue #1443 finding 2: the pid is no longer read from ``failed_result``.
    ``_reap_idle_foreign_writer`` derives it from the marker (single source of
    truth) so the pid can never disagree with the ``process_start_time``
    fingerprint passed to ``kill_process_tree``. ``failed_result`` is used
    only to locate the worktree path and confirm the failure kind.

    Issue #1443 review: ``sessions_dir`` is a required parameter (no default).
    Every production caller passes it explicitly; removing the default converts
    a silently-disabled own-live-session guard into an immediate ``TypeError``
    if a future call site drops or reorders the argument — the exact bug shape
    #1443 was filed to fix.

    Returns ``True`` when the writer was reaped, ``False`` otherwise (including
    when the failed result is not a foreign-writer block or the marker is gone).
    """
    if failed_result is None:
        return False
    failure_kind = getattr(failed_result, "failure_kind", None)
    if failure_kind != "worktree_foreign_writer":
        return False
    worktree_path_str = getattr(failed_result, "worktree_path", None)
    if not worktree_path_str:
        return False
    worktree_path = Path(worktree_path_str)
    marker = read_worktree_marker(worktree_path)
    if marker is None:
        return False
    return _reap_idle_foreign_writer(
        worktree_path,
        marker,
        config,
        sessions_dir,
        state_file=state_file,
        issue_number=issue_number,
    )


def _has_other_open_pr(
    state: dict[str, Any], issue_number: int | None, exclude_pr_number: int | None
) -> bool:
    """Return True if any PR for ``issue_number`` is open besides ``exclude_pr_number``.

    Used by ``unescalate`` to decide whether a terminal PR on GitHub is the
    *only* PR for the issue (issue #1391): when it is, the issue can be
    dropped to baseline in the same call instead of requiring a second
    ``unescalate --issue N`` to take the no-live-PR path. "Open" here means
    the state.json status is not ``merged`` or ``closed`` — the same
    predicate the PR resolution at the top of ``unescalate`` uses.
    """
    if issue_number is None:
        return False
    for k, v in state.get("prs", {}).items():
        if not isinstance(v, dict) or not k.isdigit():
            continue
        if v.get("issue_number") != issue_number:
            continue
        if exclude_pr_number is not None and int(k) == exclude_pr_number:
            continue
        if v.get("status") not in ("merged", "closed"):
            return True
    return False


class OrchestratorApp:
    def __init__(
        self,
        repo_root: Path,
        paths: RuntimePaths,
        config: OrchestratorConfig,
        gh: GitHubLike,
        *,
        dry_run: bool = False,
        fleet_dir_override: str | None = None,
    ):
        self.repo_root = repo_root
        self.paths = paths
        self.config = config
        # Single resolved view of every sentinel-style state-child config
        # value (devin.sessions_dir/session_manifest/session_results,
        # review_dispatch.reviews_dir, notify.file_path, claude_code.worktrees_dir)
        # -- see paths.resolved_layout. Safe to cache once: self.config is
        # assigned only here, never reassigned on a live instance.
        self._layout = resolved_layout(config, repo_root)
        self.gh = gh
        self.dry_run = dry_run
        self.write_gate = WriteGate(
            dry_run=self.dry_run, state_path=self.paths.state_file, repo=self.repo_root.name
        )
        self.fleet_dir_override = fleet_dir_override
        # Issue #1363: config_freshness's "exactly once per change" semantics
        # need a mtime cache that outlives a single pass but not the process
        # -- an in-memory dict on the (per-process, per-repo) app instance is
        # exactly that. Fresh at supervisor startup by design: an edit that
        # landed before this instance's first pass is not "stale since load"
        # for THIS instance, only an edit after.
        self._preflight_config_mtimes: dict[str, float] = {}
        # Issue #1001: same-instance once-only escalation flag for the
        # worker-github-token gate. A missing token is a standing condition;
        # the gate must not emit an event every loop pass. The cross-instance
        # source of truth is the durable ``worker_token_escalated`` marker in
        # state.json (fleet_loop rebuilds this app per repo per pass, so an
        # instance flag alone resets every pass). This in-memory flag is a
        # same-instance optimization that also suppresses re-entry under
        # dry-run, where the durable marker is never written. It is cleared
        # when the condition resolves (all findings ok) alongside the marker.
        self._worker_token_escalated = False
        # Make the event ring cap config-driven (issue #525).
        _state.EVENT_RING_SIZE = config.runtime.event_ring_size
        prompts_dir = config.runtime.prompts_dir
        if prompts_dir:
            override = Path(prompts_dir)
            if not override.is_absolute():
                override = repo_root / override
            self.prompt_dirs: tuple[Path, ...] = (override,)
        else:
            self.prompt_dirs = ()
        self.paths.ensure()

        # Issue #713: fail fast at startup if any configured prompt template
        # (repo-local override or package default) references a placeholder its
        # writer does not supply. A flat whole-file override that drifted out of
        # sync -- e.g. a stale ``$review_summary`` after the writer renamed it to
        # ``$dispatch_note`` -- would otherwise stay live-armed until the next
        # dispatch crashes with an uncaught PromptTemplateError (which is not
        # caught anywhere in src/). This mirrors the gh field-list self-check
        # below: a pure static gate that runs before any dispatch/review work.
        drift_errors = check_prompt_template_drift(self.config, search_dirs=self.prompt_dirs)
        if drift_errors:
            raise PromptOverrideDriftError(drift_errors)

        # Startup self-check: validate gh --json field lists against the
        # installed CLI. Fail fast before any dispatch/review/merge work.
        if isinstance(self.gh, GitHub):
            self.gh.validate_field_lists()

    @property
    def layout(self) -> ResolvedLayout:
        """Public, read-only view of the resolved state-child layout.

        This is the contract module-level helpers (e.g. ``supervise.run_supervised``)
        that take an ``app`` argument should use, mirroring the existing public
        ``paths`` attribute -- callers outside this class should never reach into
        the private ``self._layout`` cache directly.
        """
        return self._layout

    def _render(self, template_name: str, values: dict[str, Any]) -> str:
        return render_prompt(template_name, values, search_dirs=self.prompt_dirs)

    def _record_event(
        self,
        state: dict[str, Any],
        kind: str,
        payload: dict[str, Any],
        *,
        level: str | None = None,
    ) -> dict[str, Any]:
        """Append an event to state.json and the unlimited events.db log.

        This is the single instrumentation entry point for OrchestratorApp
        methods. It wraps ``append_event`` with ``self.paths.state_file`` and
        the repo name so every event is dual-written: once to the bounded
        convenience cache in ``state.json`` (``EVENT_RING_SIZE``, default 2000)
        and once to the append-only ``events.db`` audit log.

        ``level`` is forwarded to ``append_event`` so the emit site can declare
        the level explicitly instead of relying on the central registry.
        """
        return append_event(
            state,
            kind,
            payload,
            state_path=self.paths.state_file,
            repo=self.repo_root.name,
            level=level,
        )

    def _resolve(self, value: str) -> Path:
        # pathlib keeps an absolute right-hand side as-is, so this handles
        # both repo-relative and absolute config paths.
        return self.repo_root / value

    def _adapter_settings(self, *, adapter: str | None = None) -> AdapterSettings:
        claude = self.config.claude_code
        devin = self.config.devin
        api_worker = self.config.api_worker
        resolved_adapter = adapter if adapter is not None else devin.adapter
        # Use adapter-specific venv_source and worker_env
        if resolved_adapter == "devin-shell":
            venv_source = self._resolve(devin.venv_source) if devin.venv_source else None
            worker_env = devin.worker_env
        elif resolved_adapter == "claude-code":
            venv_source = self._resolve(claude.venv_source) if claude.venv_source else None
            worker_env = claude.worker_env
        elif resolved_adapter == "api":
            # api workers are Claude Code CLI processes with provider env
            # injected, so they reuse the claude-code venv/env resolution
            # (shared venv junction, worker_env overrides). The provider
            # routing vars (ANTHROPIC_BASE_URL/AUTH_TOKEN/MODEL) are merged
            # inside launch_api_worker, over any worker_env values, so an
            # operator's worker_env cannot accidentally override the provider.
            venv_source = self._resolve(claude.venv_source) if claude.venv_source else None
            worker_env = claude.worker_env
        else:
            venv_source = None
            worker_env = {}
        return AdapterSettings(
            adapter=resolved_adapter,
            dispatch_command=devin.dispatch_command,
            command_timeout_seconds=devin.command_timeout_seconds,
            sessions_dir=self._layout.sessions_dir,
            shell_command=devin.shell_command,
            claude_command=claude.command,
            worktrees_dir=self._layout.worktrees,
            venv_source=venv_source,
            worker_env=worker_env,
            worker_model=devin.worker_model,
            materialize_dirs=self.config.dispatch.materialize_dirs,
            dry_run=self.dry_run,
            base_ref=self.config.dispatch.base_ref,
            tee_stream_json=claude.tee_stream_json,
            launch_stagger_seconds=self.config.dispatch.launch_stagger_seconds,
            api_worker_config=api_worker if resolved_adapter == "api" else None,
            config=self.config,
        )

    def _routing_inputs(self) -> tuple[Any, bool, bool, list[int]]:
        """Compute pass-level routing inputs shared across all issues (issue #482).

        Returns ``(budget, api_key_present, provider_in_cooldown,
        live_api_sessions)`` — the inputs to ``routing.select_adapter`` for one
        dispatch pass. Per-issue inputs (``rework``, ``issue_labels``) are
        supplied by the caller.

        * ``budget``: ``routing.BudgetStatus`` from ``api_budget.budget_status``
          over the loaded ledger.
        * ``api_key_present``: whether the active provider's ``api_key_env``
          names a non-empty environment variable.
        * ``provider_in_cooldown``: from the existing ``throttled_until`` state
          mechanism (``state.is_throttled``). The dispatch-level throttle gate
          already defers when this is True, so this is defense-in-depth for the
          future api-specific cooldown (issue ⑦ in the design decomposition).
        * ``live_api_sessions``: a **mutable** one-element list ``[count]``
          holding the number of in-flight api workers (alive workers with
          ``adapter_kind == "api"`` counted via ``worker.iter_workers``). The
          list is mutated in place by ``_select_adapter_for_issue``: each issue
          routed to the api adapter increments ``live_api_sessions[0]`` so that
          subsequent issues in the same pass see the updated in-flight count and
          fall back when ``max_concurrent_sessions`` is reached. Without this
          running increment, every api-eligible issue in a batch would see the
          same stale count and all bypass the concurrency cap simultaneously.
        """
        api_config = self.config.api_worker
        # Budget status from the on-disk spend ledger (atomic load with
        # corrupt-file recovery; missing file = empty ledger).
        #
        # Known asymmetry (issue #626, part 2): unlike ``live_api_sessions``
        # below, ``budget`` is computed once per pass and read unchanged for
        # every issue. A batch can collectively commit past the daily cap
        # because each issue's preflight sees the same stale snapshot. This is
        # accepted rather than fixed inline because per-session cost is not
        # knowable up front (unlike concurrency, where a simple in-place
        # increment works). The in-flight budget kill (#484/#582) bounds the
        # overshoot after the fact. A per-pass cap on api routes when remaining
        # budget is below a multiple of typical session cost is the recorded
        # follow-up if the overshoot becomes a problem in practice.
        ledger = _api_load_ledger(_api_ledger_path(self.paths.state_file.parent))
        today = datetime.now(UTC).strftime("%Y-%m-%d")
        budget = _api_budget_status(ledger, api_config.budget, today)
        # API key present from the environment (name from the active provider).
        provider = api_config.providers.get(api_config.provider)
        api_key_present = bool(provider and os.environ.get(provider.api_key_env))
        # Provider in cooldown from the existing throttle-cooldown state.
        state = load_state_locked(self.paths.state_file)
        provider_in_cooldown = is_throttled(state)
        # Live api sessions counted via iter_workers filtered to adapter_kind == "api".
        # Wrapped in a mutable list so _select_adapter_for_issue can increment it
        # as issues are routed to api within the same pass (concurrency cap fix).
        sessions_dir = self._layout.sessions_dir
        live_api_sessions = sum(
            1 for w in iter_workers(sessions_dir) if w.adapter_kind == "api" and w.is_alive()
        )
        return budget, api_key_present, provider_in_cooldown, [live_api_sessions]

    def _select_adapter_for_issue(
        self,
        *,
        rework: bool,
        issue_labels: set[str],
        routing_inputs: tuple[Any, bool, bool, list[int]],
    ) -> AdapterChoice:
        """Call ``routing.select_adapter`` for one issue (issue #482).

        The single point of adapter routing enforcement: no inline
        adapter-choice conditionals live in workflow.py. Per-issue inputs
        (``rework``, ``issue_labels``) are passed in; pass-level inputs come
        from ``_routing_inputs``.

        When the choice resolves to the api adapter, the mutable
        ``live_api_sessions`` counter inside ``routing_inputs`` is incremented
        in place so the next issue in the same pass sees the updated in-flight
        count. This prevents a whole batch of api-eligible issues from all
        passing the concurrency preflight against a stale count and exceeding
        ``max_concurrent_sessions``.
        """
        budget, api_key_present, provider_in_cooldown, live_api_sessions = routing_inputs
        choice = select_adapter(
            rework=rework,
            issue_labels=issue_labels,
            complexity_high_label=self.config.labels.complexity_high,
            api_config=self.config.api_worker,
            budget=budget,
            api_key_present=api_key_present,
            provider_in_cooldown=provider_in_cooldown,
            live_api_sessions=live_api_sessions[0],
            default_adapter=self.config.devin.adapter,
        )
        if choice.kind == "api":
            live_api_sessions[0] += 1
        return choice

    def _dispatch_partitioned(
        self,
        session_requests: list[SessionRequest],
        adapter_choices: dict[int, AdapterChoice],
    ) -> list[SessionDispatchResult]:
        """Partition requests by ``AdapterChoice.kind`` and dispatch per group (issue #482).

        When ``adapter_choices`` is empty (api disabled), dispatches all
        requests as a single group with the default ``AdapterSettings`` —
        byte-identical to the pre-#482 behavior. When non-empty, partitions
        by kind and invokes ``dispatch_sessions`` once per non-empty group
        with that group's ``AdapterSettings`` (built via ``_adapter_settings``
        parameterized by kind). ``launch_stagger_seconds`` applies within each
        group as today.

        After all groups are dispatched, a combined session manifest and
        results file are written to the standard paths so the on-disk
        artifacts reflect every session in the pass (per-group calls each
        overwrite these files; the combined write at the end is authoritative).
        """
        manifest_path = self._layout.session_manifest
        results_path = self._layout.session_results

        if not adapter_choices:
            # No routing (api disabled) — single group, today's behavior.
            return dispatch_sessions(
                self.repo_root,
                manifest_path,
                results_path,
                self._adapter_settings(),
                session_requests,
            )

        # Partition by adapter kind, preserving the original request order
        # within each group (stable partition).
        groups: dict[str, list[SessionRequest]] = {}
        for req in session_requests:
            kind = adapter_choices[req.issue_number].kind
            groups.setdefault(kind, []).append(req)

        all_results: list[SessionDispatchResult] = []
        for kind, group_requests in groups.items():
            group_results = dispatch_sessions(
                self.repo_root,
                manifest_path,
                results_path,
                self._adapter_settings(adapter=kind),
                group_requests,
            )
            all_results.extend(group_results)

        # Write combined manifest and results reflecting all sessions in the
        # pass. Per-group dispatch_sessions calls each overwrite these files;
        # this final write is the authoritative on-disk artifact. The adapter
        # label is derived from the actual partition: a homogeneous batch is
        # labeled with its single kind, not "mixed" (issue #626).
        label = manifest_adapter_label(set(groups))
        write_session_manifest(manifest_path, session_requests, adapter=label)
        write_session_results(results_path, all_results)
        return all_results

    def _rescue_adapter_settings(self) -> AdapterSettings:
        """AdapterSettings for a rescue-tier rework dispatch (issue #555).

        Mirrors the "claude-code" branch of ``_adapter_settings()`` exactly
        (same venv/worker_env/command resolution), but forces
        ``adapter="claude-code"`` regardless of the primary configured
        ``devin.adapter`` — the rescue tier always uses the claude-code
        adapter — and overrides ``claude_code.model`` to
        ``rescue.worker_model`` via a one-off config copy. This is the
        "adapter/model overridden from RescueConfig" the rescue rework
        reuses the existing rework-dispatch path with, never a parallel
        launch path.
        """
        claude = self.config.claude_code
        rescue_config = dataclasses_replace(
            self.config,
            claude_code=dataclasses_replace(claude, model=self.config.rescue.worker_model),
        )
        return AdapterSettings(
            adapter="claude-code",
            sessions_dir=self._layout.sessions_dir,
            claude_command=claude.command,
            worktrees_dir=self._layout.worktrees,
            venv_source=self._resolve(claude.venv_source) if claude.venv_source else None,
            worker_env=claude.worker_env,
            materialize_dirs=self.config.dispatch.materialize_dirs,
            dry_run=self.dry_run,
            base_ref=self.config.dispatch.base_ref,
            tee_stream_json=claude.tee_stream_json,
            launch_stagger_seconds=self.config.dispatch.launch_stagger_seconds,
            config=rescue_config,
        )

    def _apply_concurrency_governor(
        self,
        dispatch_limit: int,
        *,
        live_count: int | None = None,
        apply_open_pr_backpressure: bool = False,
    ) -> ConcurrencyGovernorResult:
        """Apply global concurrency governor cap to a dispatch limit.

        Returns a ConcurrencyGovernorResult with the potentially-clamped limit
        and all related fields. This eliminates Pyright's reportPossiblyUnbound
        warnings by ensuring live_count is always bound together with the
        clamped flag.

        Args:
            dispatch_limit: The requested dispatch limit
            live_count: Optional pre-computed live worker count. If None and
                max_concurrent > 0, this will compute it via _count_live_sessions.
            apply_open_pr_backpressure: When True (fresh-issue dispatch only),
                also clamp to ``max(0, max_open_agent_prs - open_pr_count)``
                where ``open_pr_count`` is the number of open agent PRs whose
                head ref matches ``dispatch.branch_prefix``. Rework, recovery,
                and loop-level callers leave this False -- they reduce
                verification debt rather than adding to it (issue #1129).
        """
        max_concurrent = self.config.dispatch.max_concurrent_sessions
        fleet_max = self.config.fleet.global_max_concurrent_sessions
        open_pr_max = self.config.dispatch.max_open_agent_prs if apply_open_pr_backpressure else 0
        available_slots = dispatch_limit
        clamped = False
        fleet_live_count = 0
        open_pr_count = 0

        if max_concurrent > 0:
            if live_count is None:
                sessions_dir = self._layout.sessions_dir
                live_count = _count_live_sessions(sessions_dir, self.paths.state_file)
            available_slots = max(0, max_concurrent - live_count)
            if available_slots < dispatch_limit:
                dispatch_limit = available_slots
                clamped = True

        if fleet_max > 0:
            fleet_live_count, _skipped_repos = count_fleet_live_sessions(self.fleet_dir_override)
            fleet_available = max(0, fleet_max - fleet_live_count)
            if fleet_available < dispatch_limit:
                dispatch_limit = fleet_available
                clamped = True

        if open_pr_max > 0:
            # Issue #1129: count open agent PRs from live GitHub state (the
            # same pr_list() + branch_prefix derivation _merge_train_candidates
            # and the reconciler use). No new state; the count is recomputed
            # each pass and self-corrects after merges/closes.
            branch_prefix = self.config.dispatch.branch_prefix
            open_pr_count = sum(
                1
                for pr in self.gh.pr_list()
                if str(pr.get("headRefName") or "").startswith(branch_prefix)
            )
            open_pr_available = max(0, open_pr_max - open_pr_count)
            if open_pr_available < dispatch_limit:
                # Record a dispatch_backpressure event so "0 dispatched with N
                # dispatchable" is diagnosable from events.db rather than
                # reading as idleness (same discipline as #1091's de-escalation
                # skip attribution). The governor runs outside the state lock,
                # so log_event (the low-level write primitive for events
                # outside state-lock contexts) is used directly.
                #
                # Dry-run never writes the event: log_event is a durable
                # events.db mutation, and a dry-run preview must not record
                # instrumentation (the same write-suppression discipline as the
                # worker_token_escalated marker above -- the escalation event
                # and durable marker stay behind ``not self.dry_run``). The
                # clamp itself (dispatch_limit/clamped below) is NOT dry-run
                # gated: a dry-run preview must report the same clamped
                # selected_count a live pass would, matching the
                # worker_token_missing refusal precedent in _dispatch_impl.
                if not self.dry_run:
                    log_event(
                        self.paths.state_file,
                        "dispatch_backpressure",
                        {
                            "open_pr_count": open_pr_count,
                            "max_open_agent_prs": open_pr_max,
                            "requested_limit": dispatch_limit,
                            "clamped_limit": open_pr_available,
                        },
                        repo=self.repo_root.name,
                    )
                dispatch_limit = open_pr_available
                clamped = True

        return ConcurrencyGovernorResult(
            clamped=clamped,
            max_concurrent=max_concurrent,
            live_count=live_count or 0,
            available_slots=available_slots,
            dispatch_limit=dispatch_limit,
            fleet_live_count=fleet_live_count,
            fleet_max=fleet_max,
            open_pr_count=open_pr_count,
            open_pr_max=open_pr_max,
        )

    @_guard_state_lock
    def status(self) -> CommandResult:
        issues = self.gh.issue_list(self.config.labels.ready)
        prs = self.gh.pr_list()
        state = load_state_locked(self.paths.state_file)
        operator_claimed = operator_claimed_issues(state)
        stale_claims = stale_operator_claims(state)
        active_issues = [
            issue for issue in issues if label_names(issue) & self.config.labels.active
        ]
        available_issues = [
            issue for issue in issues if self._is_dispatchable(issue, operator_claimed)
        ]

        # Warm the blocker/dependency cache for every ready issue concurrently
        # before the serial per-issue lookups below run. See
        # _prefetch_blocker_data's docstring and issue #870: this is what
        # turns O(N) serial `gh` calls into one parallel batch.
        self._prefetch_blocker_data(issues)

        # Check for blocked issues (dependency gate)
        truly_available, blocked_issues, _open_blockers_by_issue = self._filter_blocked_issues(
            available_issues
        )

        # Check for stalled sessions (read-only for status/roll-call)
        sessions_dir = self._layout.sessions_dir
        stalled_entries = _detect_stalled_sessions(sessions_dir, self.config)

        # Build workers list with health classification
        from .worker import classify_worker_health, iter_workers, real_activity_probe_for

        worker_views = list(iter_workers(sessions_dir))
        now = datetime.now(UTC)
        workers = []
        for view in worker_views:
            if not view.is_alive():
                continue
            probe = real_activity_probe_for(view, self.config, now)
            workers.append(
                self._summarize_worker(
                    view,
                    classify_worker_health(view, self.config, now, probe),
                    probe=probe,
                )
            )

        # Observe runner pool if feature is enabled
        runners_data = None
        if self.config.runner_scaling.enabled:
            from ci_fleet.charlie_work_adapter import format_runner_pool_state, observe_runner_pool

            try:
                # No state_dir here, so nothing is written either way today --
                # threaded anyway so the call site stays honest if one is ever
                # added, and so the dry-run call-site guard stays a bright line.
                pool_state = observe_runner_pool(
                    self.gh, self.config.runner_scaling, dry_run=self.gh.dry_run
                )
                runners_data = format_runner_pool_state(pool_state)
            except Exception:
                # Don't fail status() if runner observation fails
                runners_data = None

        linked_prs = [
            self._summarize_pr(pr)
            for pr in prs
            if linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            is not None
        ]
        data = {
            "ready_issue_count": len(issues),
            "available_issue_count": len(truly_available),
            "active_issue_count": len(active_issues),
            "open_linked_pr_count": len(linked_prs),
            "state_file": str(self.paths.state_file),
            "auto_merge_enabled": self.config.auto_merge.enabled,
            "issues": [self._summarize_issue(issue) for issue in issues],
            "prs": linked_prs,
            "last_generated_at": state.get("generated_at"),
            "blocked": [
                {"issue": issue_number, "blockers": blockers}
                for issue_number, blockers in sorted(blocked_issues.items())
            ],
            "stalled": stalled_entries,
            "workers": workers,
            "operator_claimed": sorted(operator_claimed),
            "stale_claims": sorted(stale_claims),
            # Issue #944: ready_issue_count above is the ready-FILTERED count,
            # so "0 ready issues" and "0 issues at all" print identically. This
            # is the unfiltered view: how big the backlog really is and which
            # gate is rejecting it.
            # len(issues) with no OPEN filter is correct HERE and would be a bug
            # in _dispatch_impl: this method's query (above) is
            # issue_list(labels.ready) with no state, and GitHubClient defaults
            # to state="open" (github.py: `effective_state = state or "open"`),
            # so `issues` is already open-only. _dispatch_impl passes
            # state="all" and must therefore count OPEN itself, or closed
            # ready-labelled issues would inflate the count and report
            # consistent=False on every healthy pass.
            "backlog_reachability": classify_backlog_reachability(
                self.gh,
                self.config,
                operator_claimed,
                ready_open_count=len(issues),
            ),
        }

        # Add runners section if feature is enabled and observation succeeded
        if runners_data is not None:
            data["runners"] = runners_data

        return CommandResult(True, "status complete", data)

    def claim(self, issue_number: int, release: bool = False) -> CommandResult:
        """Record or release an operator claim on an issue.

        A claimed issue is excluded from fresh dispatch and rework dispatch
        regardless of its labels. When a worktree for the issue already
        exists, a ``.charlie-writer.json`` marker is written or removed so the
        protection is mutual: the orchestrator refuses to dispatch into a
        worktree with a live foreign writer marker.
        """
        try:
            issue = self.gh.issue_view(issue_number)
        except GitHubError as exc:
            return CommandResult(
                False, f"issue #{issue_number} not found: {exc}", {"issue_number": issue_number}
            )

        branch_name = self._branch_name(issue)
        worktree_path = worktree_path_for_branch(
            self.repo_root, branch_name, self._layout.worktrees
        )

        marker_written = False
        if not release and worktree_path.is_dir():
            # Operator markers intentionally do not encode the CLI's transient
            # PID; liveness is keyed off operator_claimed_at in state.json.
            try:
                write_worktree_marker(
                    worktree_path,
                    0,
                    OPERATOR_MARKER_SESSION_ID,
                    kind=OPERATOR_MARKER_KIND,
                )
                marker_written = True
            except OSError:
                # Marker write failure is not fatal, but record it in the result.
                pass
        elif release:
            # Best-effort marker removal; state release is what matters. Only
            # remove a marker that belongs to this operator claim, never a
            # worker marker from an active session.
            try:
                remove_worktree_marker(worktree_path, session_id=OPERATOR_MARKER_SESSION_ID)
            except OSError:
                pass

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            if release:
                state = release_operator_claimed(state, issue_number)
            else:
                state = set_operator_claimed(state, issue_number)
            state = self._record_event(
                state,
                "operator_claim_released" if release else "operator_claim",
                {
                    "issue_number": issue_number,
                    "branch_name": branch_name,
                    "worktree_path": str(worktree_path),
                    "marker_written": marker_written,
                },
            )
            save_state(self.paths.state_file, state)

        message = (
            f"operator claim released for issue #{issue_number}"
            if release
            else f"operator claim recorded for issue #{issue_number}"
        )
        return CommandResult(
            True,
            message,
            {
                "issue_number": issue_number,
                "branch_name": branch_name,
                "worktree_path": str(worktree_path),
                "released": release,
                "marker_written": marker_written,
            },
        )

    def _label_descriptions(self) -> dict[str, str]:
        """Human-readable description for every LabelConfig-derived label.

        Single source for the descriptions used by both the explicit
        ``charlie bootstrap-labels`` command and the automatic startup
        ensure (issue #1339). Keyed by the resolved label string from
        ``self.config.labels``, never a hard-coded literal.
        """
        labels = self.config.labels
        return {
            labels.ready: "Issue is ready for deterministic agentic automation.",
            labels.queued: "Issue is queued by the orchestrator.",
            labels.in_progress: "A worker is implementing this issue.",
            labels.pr_open: "A worker PR exists for this issue.",
            labels.reviewing: "The orchestrator is adversarially reviewing the worker PR.",
            labels.needs_rework: "The worker PR needs another implementation cycle.",
            labels.blocked: "Automation is blocked and needs intervention.",
            labels.done: "Automation completed and the issue was merged or resolved.",
            labels.human_needed: "A human product or security decision is needed.",
            labels.operator_queue: "A mechanical failure exhausted its automated retries; needs operator triage.",
            labels.prose_only_deps: "Issue has prose-only dependencies that need structured blocker declarations.",
            labels.merge_hold: "Approved PR is held out of the merge queue by operator request.",
            labels.complexity_high: (
                "Routing hint: route to the api worker (multi-module, "
                "cross-cutting invariant, or prior escalation)."
            ),
        }

    def _label_color(self, label: str) -> str:
        """Color for a label, derived from LabelConfig fields (no hard-coded names)."""
        labels = self.config.labels
        # The ready marker is green; the complexity routing hint gets a
        # distinct amber so it is visually separable from workflow state.
        if label == labels.ready:
            return "0E8A16"
        if label == labels.complexity_high:
            return "BFD4F2"
        return "5319E7"

    def _ensure_labels_core(self) -> CommandResult:
        """Idempotent ensure of every LabelConfig-derived label on the repo.

        Creates/updates each label in ``self.config.labels.all`` via
        ``gh.label_create`` (``--force`` → update-or-create, so colour and
        description drift is repaired on existing labels too), then verifies
        via ``gh.label_list``. The ensure set is derived entirely from
        ``LabelConfig`` fields — never a hard-coded list — so a new field
        ships its label with no extra wiring (issue #1339).

        Returns a ``CommandResult`` and never raises: a ``GitHubError`` from
        verification is reported in the result, not propagated. The CLI
        ``bootstrap-labels`` command and the automatic startup ensure both
        route through here.
        """
        labels = self.config.labels
        desired = list(labels.all)
        descriptions = self._label_descriptions()
        for label in desired:
            # A brand-new LabelConfig field may ship before its entry in
            # ``_label_descriptions`` is added; fall back to a generic
            # description so the label is still created (issue #1339 AC #3).
            # Never block the ensure on a missing description.
            description = descriptions.get(label, "Orchestrator-managed label.")
            self.gh.label_create(label, self._label_color(label), description)
        # Verify: check which labels actually exist after creation attempts.
        # label_create uses allow_failure=True, so silent failures are possible
        # (e.g. no auth, wrong repo). Don't report success we can't vouch for.
        try:
            live = {
                str(item.get("name") or "")
                for item in self.gh.label_list()
                if isinstance(item, dict)
            }
            missing = [name for name in desired if name not in live]
        except GitHubError as exc:
            return CommandResult(
                False,
                f"labels created but verification failed: {exc}",
                {"labels": desired, "missing": None},
            )
        if missing:
            return CommandResult(
                False,
                f"bootstrap incomplete — {len(missing)} label(s) still missing: {missing}",
                {"labels": desired, "missing": missing},
            )
        return CommandResult(True, "labels ensured", {"labels": desired, "missing": []})

    def bootstrap_labels(self) -> CommandResult:
        return self._ensure_labels_core()

    def ensure_labels(self) -> CommandResult:
        """Automatic startup label ensure (issue #1339).

        Runs the same idempotent LabelConfig-derived ensure as
        ``bootstrap_labels``, but records the outcome as an event so a
        missing-label drift surfaces in ``events.db`` without an operator
        having to run ``charlie bootstrap-labels`` by hand. Never raises:
        any unexpected exception is recorded as an event and swallowed, so a
        label-ensure failure can never block the supervisor/loop startup it
        runs from.
        """
        try:
            result = self._ensure_labels_core()
        except Exception as exc:  # noqa: BLE001 — ensure must never block startup
            # _ensure_labels_core itself does not raise, but a GitHub
            # implementation that raises from label_create/label_list would
            # otherwise crash the caller. Record and degrade to a failure
            # result instead of propagating.
            log_event(
                self.paths.state_file,
                "label_ensure_failed",
                {"error": f"{type(exc).__name__}: {exc}", "labels": list(self.config.labels.all)},
                repo=self.repo_root.name,
                level="error",
            )
            return CommandResult(
                False,
                f"label ensure error: {exc}",
                {"labels": list(self.config.labels.all), "missing": None},
            )
        missing = result.data.get("missing")
        if result.ok:
            log_event(
                self.paths.state_file,
                "label_ensure_ok",
                {"labels": result.data.get("labels", []), "missing": []},
                repo=self.repo_root.name,
                level="info",
            )
        elif missing is None:
            # Verification itself failed (e.g. label_list raised); the ensure
            # could not be confirmed. Surface as an error event.
            log_event(
                self.paths.state_file,
                "label_ensure_failed",
                {"message": result.message, "labels": result.data.get("labels", [])},
                repo=self.repo_root.name,
                level="error",
            )
        else:
            log_event(
                self.paths.state_file,
                "label_ensure_incomplete",
                {"missing": missing, "message": result.message},
                repo=self.repo_root.name,
                level="warning",
            )
        return result

    @_guard_state_lock
    def intake(self) -> CommandResult:
        issues = self.gh.issue_list(self.config.labels.ready)
        written: list[dict[str, Any]] = []
        failed: list[dict[str, Any]] = []
        prose_only_deps_issues: list[int] = []
        # Gather all network results and write files outside the lock
        for issue in issues:
            issue_number = int(issue["number"])
            try:
                full_issue = self.gh.issue_view(issue_number)
            except GitHubError as exc:
                failed.append({"issue": issue_number, "error": str(exc)})
                continue
            issue_dir = self.paths.issues / f"issue-{issue_number}"
            issue_json = issue_dir / "issue.json"
            # Issue #618: in dry-run, skip all file mutations (issue dir,
            # issue.json, worker-prompt.md) — the preview must not touch disk.
            if not self.dry_run:
                issue_dir.mkdir(parents=True, exist_ok=True)
                self._write_json(issue_json, full_issue)
            prompt_path = self._write_worker_prompt(full_issue, dry_run=self.dry_run)

            # Check for prose-only dependencies (issue #225)
            body_text = full_issue.get("body", "")
            has_prose_deps = detect_prose_only_dependencies(body_text)
            has_structured_blockers = bool(parse_blockers(body_text))

            # If prose-only dependencies exist without structured blockers, label for human attention
            if has_prose_deps and not has_structured_blockers:
                prose_only_deps_issues.append(issue_number)
                if not self.dry_run:
                    try:
                        self.gh.add_issue_label(issue_number, self.config.labels.prose_only_deps)
                    except Exception:
                        # Label add failure is non-blocking for intake
                        pass

            written.append(
                {
                    "issue": issue_number,
                    "prompt_path": str(prompt_path),
                    "title": full_issue.get("title"),
                    "url": full_issue.get("url"),
                    "labels": sorted(label_names(full_issue)),
                    "updated_at": full_issue.get("updatedAt"),
                }
            )
        # Single lock for all state updates — skipped in dry-run (issue #618)
        if not self.dry_run:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for entry in written:
                    issue_number = entry["issue"]
                    # Merge-update, never replace: intake used to clobber dispatch
                    # status recorded by earlier passes (production-confirmed).
                    state["issues"][str(issue_number)] = {
                        **state["issues"].get(str(issue_number), {}),
                        "number": issue_number,
                        "title": entry["title"],
                        "url": entry["url"],
                        "labels": entry["labels"],
                        "prompt_path": entry["prompt_path"],
                        "updated_at": entry["updated_at"],
                    }
                for failure in failed:
                    state = self._record_event(
                        state,
                        "intake_failed",
                        {"issue_number": failure["issue"], "error": failure["error"]},
                    )
                if prose_only_deps_issues:
                    state = self._record_event(
                        state,
                        "intake_prose_only_deps",
                        {"issue_numbers": sorted(prose_only_deps_issues)},
                    )
                state = self._record_event(
                    state, "intake", {"issue_count": len(issues), "failed_count": len(failed)}
                )
                save_state(self.paths.state_file, state)
        message = "intake complete"
        if self.dry_run:
            message = f"dry-run: would intake {len(written)} issue(s)"
        elif failed:
            message = f"intake completed with {len(failed)} failure(s)"
        if prose_only_deps_issues:
            message += (
                f", {len(prose_only_deps_issues)} issue(s) labeled with prose-only dependencies"
            )
        return CommandResult(
            not failed,
            message,
            {
                "issues": written,
                "failed": failed,
                "prose_only_deps_issues": prose_only_deps_issues,
            },
        )

    def _finalize_externally_merged_issues(
        self,
        ready_issues: list[dict[str, Any]] | None = None,
    ) -> tuple[set[int], list[dict[str, Any]], _MergedPRListOutcome]:
        """Finalize closed ready-labeled issues whose linked PR merged externally,
        and strip the ready/active labels from closed ready issues that have no
        merged PR binding them (issue #429/#433).

        Runs before dispatch capacity guards (fleet lock, GraphQL budget, provider
        throttle) so a pass that defers new work still drains the backlog of
        externally-merged issues (e.g. Aviator MergeQueue handoffs).  It first
        binds candidates against the cheap most-recent-500 ``merged_pr_list()``;
        only issues whose merged PR falls outside that window incur a per-issue
        ``gh pr list --search`` lookup.

        Per-issue lookups are capped at ``dispatch.finalize_limit`` and processed
        oldest-first (by ``createdAt``, then issue number). A consecutive-failure
        circuit breaker stops the pass after 3 failed lookups so a transient
        Search API rate limit does not monopolize the shared token.
        """
        if ready_issues is None:
            ready_issues = self.gh.issue_list(
                labels=[self.config.labels.ready],
                state="all",
            )
        closed_ready = [
            issue
            for issue in ready_issues
            if str(issue.get("state") or "OPEN").upper() == "CLOSED"
        ]
        if not closed_ready:
            return set(), ready_issues, _MergedPRListOutcome()

        finalize_limit = self.config.dispatch.finalize_limit
        if finalize_limit <= 0:
            return set(), ready_issues, _MergedPRListOutcome()

        # Try the cheap 500-window binding first; if the GraphQL-budget guard
        # refuses the call, fall back to per-issue search for all candidates.
        bound_issue_numbers: set[int] = set()
        mention_only_issue_numbers: set[int] = set()
        merged_pr_outcome = _MergedPRListOutcome()
        try:
            merged_prs = self.gh.merged_pr_list()
        except GitHubError as exc:
            merged_pr_outcome = _MergedPRListOutcome([], exc, called=True)
            merged_prs = []
        else:
            merged_pr_outcome = _MergedPRListOutcome(merged_prs, called=True)
        for pr in merged_prs:
            if str(pr.get("state") or "").upper() != "MERGED":
                continue
            bound = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if bound is not None:
                bound_issue_numbers.add(bound)
            # isCrossRepository describes the PR's own head-branch provenance
            # (fork vs. same-repo). It cannot fully guard a cross-repo mention
            # collision, but it does guard the common case of a fork PR's text
            # being trusted at all.
            if pr.get("isCrossRepository") is False:
                for mentioned in issue_numbers_mentioned_by_pr(pr):
                    mention_only_issue_numbers.add(mentioned)

        # Mention-only references are advisory; they are not a binding, but
        # they also must not be stripped as "unmerged" — dispatch() will flag
        # them for a human decision.
        mention_only_issue_numbers -= bound_issue_numbers

        # Only unbound closed issues are candidates for per-issue search or strip.
        unbound_issues = [
            issue for issue in closed_ready if int(issue["number"]) not in bound_issue_numbers
        ]

        def _finalization_order(issue: dict[str, Any]) -> tuple[str, int]:
            return (str(issue.get("createdAt") or ""), int(issue["number"]))

        # Slice BEFORE any per-issue lookup so a large backlog cannot exhaust
        # the GitHub Search API bucket in a single pass.
        candidates = sorted(unbound_issues, key=_finalization_order)[:finalize_limit]

        issue_pr_map: dict[int, list[dict[str, Any]]] = {}
        closed_unmerged_ready_issues: set[int] = set()
        consecutive_failures = 0
        for issue in candidates:
            if consecutive_failures >= 3:
                break
            issue_number = int(issue["number"])
            merged_prs = self.gh.merged_prs_for_issue(
                issue_number,
                self.config.dispatch.branch_prefix,
            )
            if not getattr(merged_prs, "ok", True):
                consecutive_failures += 1
                continue
            consecutive_failures = 0
            if merged_prs:
                issue_pr_map[issue_number] = list(merged_prs)
            elif issue_number not in mention_only_issue_numbers:
                # Confirmed closed ready issue with no merged PR binding it.
                closed_unmerged_ready_issues.add(issue_number)

        # Persist state first, then apply labels outside the lock.
        if issue_pr_map or closed_unmerged_ready_issues:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for issue_number, prs in issue_pr_map.items():
                    issue_key = str(issue_number)
                    issue_entry = state["issues"].get(issue_key, {})
                    state["issues"][issue_key] = {
                        **issue_entry,
                        "number": issue_number,
                        "status": "closed",
                    }
                    for pr in prs:
                        pr_number = int(pr["number"])
                        pr_key = str(pr_number)
                        pr_entry = state["prs"].get(pr_key, {})
                        _new_pr_state = {
                            **pr_entry,
                            "number": pr_number,
                            "status": "merged",
                            "merged": True,
                            "issue_number": issue_number,
                        }
                        # Issue #747: stamp ``merged_at`` only on a genuine
                        # non-merged -> merged transition so the original
                        # observation time is preserved across re-finalization
                        # passes and existing entries are never back-dated.
                        if pr_entry.get("status") != "merged":
                            _new_pr_state["merged_at"] = utc_now()
                        state["prs"][pr_key] = _new_pr_state
                if issue_pr_map:
                    state = self._record_event(
                        state,
                        # event-consumer: audit-only -- records the PR-status "merged"
                        # finalization already applied inline above; no separate consumer needed
                        "finalize_externally_merged",
                        {
                            "issue_numbers": sorted(issue_pr_map.keys()),
                            "pr_numbers": sorted(
                                {int(pr["number"]) for prs in issue_pr_map.values() for pr in prs}
                            ),
                        },
                    )
                for issue_number in closed_unmerged_ready_issues:
                    issue_key = str(issue_number)
                    issue_entry = state["issues"].get(issue_key, {})
                    state["issues"][issue_key] = {
                        **issue_entry,
                        "number": issue_number,
                        "status": "closed",
                    }
                if closed_unmerged_ready_issues:
                    state = self._record_event(
                        state,
                        "dispatch_closed_unmerged_ready_stripped",
                        {"issue_numbers": sorted(closed_unmerged_ready_issues)},
                    )
                save_state(self.paths.state_file, state)

        for issue_number in issue_pr_map:
            transition(self.gh, self.config.labels, issue_number, "merged")
            self.gh.close_issue(issue_number)

        for issue_number in closed_unmerged_ready_issues:
            transition(self.gh, self.config.labels, issue_number, "closed_unmerged")

        finalized: set[int] = set(issue_pr_map.keys())
        removed = finalized | closed_unmerged_ready_issues
        remaining = [issue for issue in ready_issues if int(issue["number"]) not in removed]
        return finalized, remaining, merged_pr_outcome

    def dispatch(
        self,
        limit: int | None = None,
        *,
        only_issues: str | None = None,
        stalled_entries: list[dict[str, int]] | None = None,
    ) -> CommandResult:
        """Dispatch fresh workers for ready issues.

        ``stalled_entries``: pass the result of an already-completed
        ``_detect_and_handle_stalled_sessions`` sweep to reuse it instead of
        re-running the sweep inside this call. ``loop()`` does this because it
        runs the sweep itself at the top of each pass; the sweep is the sole
        writer of Signal-1's inconclusive-probe deferral counter, so re-running
        it here would advance that counter more than once per pass and erode
        the ``max_inconclusive_probe_deferrals`` grace period (issue #343
        Finding 2). Standalone callers leave this as None and the sweep runs
        inside this call as before.
        """
        # Issue #646: unconditional census of every alive worker, logged before
        # any guard below can short-circuit (state lock busy, fleet lock held,
        # GraphQL budget deferred) -- this is the one chokepoint every dispatch
        # path funnels through, whether invoked standalone (`work`/`fleet work`)
        # or from inside a supervised pass (`loop()` -> `_loop_body()` ->
        # `dispatch()`), so it answers "how many suites were running at <time>,
        # from which worktrees, at what cap" regardless of which command
        # launched them. Purely read-only, but explicitly guarded: per-file
        # read errors are already swallowed inside read_worker_records/
        # read_session_records, but this diagnostic must never be the reason a
        # whole dispatch pass aborts, so any other unexpected failure here
        # (formatting, directory-listing races, etc.) is logged and swallowed
        # rather than propagated -- a torn sidecar read is *more* likely, not
        # less, during the exact high-concurrency moment this census exists to
        # diagnose.
        try:
            _log_worker_census(self._layout.sessions_dir)
        except Exception:
            import logging

            logging.getLogger(__name__).warning("worker census failed", exc_info=True)
        # Finalize closed ready-labeled issues whose linked PR merged externally.
        # This runs before fleet lock / GraphQL budget / provider throttle guards
        # so a pass that defers new dispatch still drains the Aviator-merge backlog.
        finalized: set[int] = set()
        merged_pr_outcome: _MergedPRListOutcome = _MergedPRListOutcome()
        try:
            finalized, ready_issues, merged_pr_outcome = self._finalize_externally_merged_issues()
        except StateLockBusy:
            return _state_lock_busy_result(
                "dispatch deferred: state lock held",
                selected_count=0,
                deferred_reason="state_lock_busy",
            )

        # Reuse the merged PR list already fetched by _finalize_externally_merged_issues
        # so the post-merge tripwire in loop() can avoid a second GraphQL call.
        merged_prs_for_result: list[dict[str, Any]] | None = (
            merged_pr_outcome.items
            if merged_pr_outcome.called and merged_pr_outcome.error is None
            else None
        )

        fleet_lock = None
        if self.config.fleet.global_max_concurrent_sessions > 0:
            fleet_lock = try_acquire_fleet_lock(self.fleet_dir_override)
            if fleet_lock is None:
                return CommandResult(
                    True,
                    "dispatch deferred: fleet lock held",
                    {
                        "selected_count": 0,
                        "deferred_reason": "fleet_lock_held",
                        "merged_prs": merged_prs_for_result,
                        "merged_pr_closed_issue_numbers": sorted(finalized),
                        "merged_pr_referenced_issue_numbers": sorted(finalized),
                    },
                )
        try:
            result = self._dispatch_impl(
                limit,
                only_issues=only_issues,
                stalled_entries=stalled_entries,
                ready_issues=ready_issues,
                merged_prs=merged_pr_outcome,
            )
            data = dict(result.data)
            if finalized:
                data["merged_pr_closed_issue_numbers"] = sorted(
                    set(data.get("merged_pr_closed_issue_numbers", [])) | finalized
                )
                data["merged_pr_referenced_issue_numbers"] = sorted(
                    set(data.get("merged_pr_referenced_issue_numbers", [])) | finalized
                )
            return CommandResult(result.ok, result.message, data)
        except StateLockBusy:
            return _state_lock_busy_result(
                "dispatch deferred: state lock held",
                selected_count=0,
                deferred_reason="state_lock_busy",
                merged_prs=merged_prs_for_result,
                merged_pr_closed_issue_numbers=sorted(finalized),
                merged_pr_referenced_issue_numbers=sorted(finalized),
            )
        except GraphQLBudgetError as exc:
            return CommandResult(
                True,
                "dispatch deferred: GraphQL rate limit below threshold",
                {
                    "selected_count": 0,
                    "deferred_reason": "graphql_rate_limit",
                    "graphql_remaining": exc.remaining,
                    "graphql_reset": exc.reset_at,
                    "graphql_threshold": exc.threshold,
                    "merged_prs": merged_prs_for_result,
                    "merged_pr_closed_issue_numbers": sorted(finalized),
                    "merged_pr_referenced_issue_numbers": sorted(finalized),
                },
            )
        except GitHubError as exc:
            # A GitHubError from _dispatch_impl means a GitHub API call
            # needed for reliable dispatch failed. The two known sources are
            # merged_pr_list() (raised on unusable responses — empty stdout,
            # non-zero exit, unparseable JSON — per #633) and pr_list(); both
            # are fetched before any issue is claimed or worker launched, so
            # deferring here cannot leave a partial claim. Earlier
            # _finalize_externally_merged_issues already recorded its own
            # merged_pr_list failure in merged_pr_outcome, and
            # _resolve_merged_prs re-raises that stored error (branch 2) so
            # this handler covers BOTH the direct-fallback fetch (branch 1,
            # the common case when there are open ready issues but no
            # closed-ready issues this pass) and the finalize-errored re-raise
            # (branch 2). Deferring is the correct response: proceeding with
            # an empty merged-PR set would re-dispatch issues a merged PR
            # already covered (the silent-empty path #633 closed), and letting
            # the error propagate crashes the supervised loop daemon on a
            # transient gh failure. Any claim written before a later
            # GitHubError (e.g. issue_view mid-launch) is recovered by the
            # existing stale-claim sweep on the next pass.
            return CommandResult(
                True,
                f"dispatch deferred: GitHub API error ({exc})",
                {
                    "selected_count": 0,
                    "deferred_reason": "github_error",
                    "github_error": str(exc),
                    "merged_prs": merged_prs_for_result,
                    "merged_pr_closed_issue_numbers": sorted(finalized),
                    "merged_pr_referenced_issue_numbers": sorted(finalized),
                },
            )
        finally:
            if fleet_lock is not None:
                fleet_lock.release()

    def _dispatch_impl(
        self,
        limit: int | None = None,
        *,
        only_issues: str | None = None,
        stalled_entries: list[dict[str, int]] | None = None,
        ready_issues: list[dict[str, Any]] | None = None,
        merged_prs: _MergedPRListOutcome | None = None,
    ) -> CommandResult:
        # Issue #1001: worker GitHub token gate. Before dispatching to an
        # adapter family that routes through sanitize_env's merge, consult the
        # same predicate doctor._check_worker_github_token uses. If no
        # worker_env token is configured, escalate once (not per pass) and
        # either refuse (when dispatch.require_worker_github_token is True) or
        # warn and proceed (the default, so the gate does not take the fleet
        # down on a config that has not yet been provisioned — see the issue
        # #1001 sequencing hazard comment in config.py).
        #
        # The once-only guarantee must hold across OrchestratorApp
        # reconstruction: fleet_dispatch.fleet_loop builds a fresh app per
        # repo per pass, so an instance-level flag alone resets every pass
        # and re-escalates indefinitely. The durable marker
        # ``worker_token_escalated`` in state.json is the cross-instance
        # source of truth; the instance-level ``_worker_token_escalated``
        # flag (initialized in __init__) is a same-instance optimization
        # that also covers dry-run, where the durable marker is never
        # written. The marker is cleared when the condition resolves (all
        # findings ok), so a future regression re-escalates.
        token_findings = worker_github_token_findings(self.config)
        missing_findings = [f for f in token_findings if not f.ok]
        if missing_findings:
            if not self._worker_token_escalated:
                self._worker_token_escalated = True
                # Record the escalation event once. Payload carries only
                # config_key names and adapter contexts — never a token
                # value or prefix (issue #1001 acceptance criterion).
                #
                # Dry-run never writes: the escalation event and the
                # durable marker are state mutations (state_lock +
                # save_state), so they are gated on ``not self.dry_run``
                # — the same read-only contract documented at the
                # merge_ready dry-run gate (~line 15452, "Dry-run never
                # writes") and modelled on this function's own
                # top-of-body dry-run short-circuit. The in-memory
                # once-only flag is still set under dry-run so a dry-run
                # pass does not re-enter this block on the next pass;
                # the event and marker are emitted on the first real
                # (non-dry-run) dispatch. ``self.dry_run`` is fixed at
                # construction, so a dry-run instance cannot later
                # "forget" the flag and skip a real write.
                #
                # The durable marker is read inside the lock (not before it)
                # so the cross-instance once-only guarantee holds without an
                # unlocked load_state — issue #310's
                # test_no_unlocked_load_state_in_production_code lint forbids
                # any load_state outside a state_lock block. The in-memory
                # ``_worker_token_escalated`` flag is the first gate
                # (same-instance), so the lock is entered at most once per
                # instance lifetime (the flag's False→True transition); the
                # inner ``if not state.get(...)`` re-check is the
                # authoritative cross-instance gate and no-ops when a prior
                # instance already set the marker.
                if not self.dry_run:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        if not state.get("worker_token_escalated", False):
                            state = self._record_event(
                                state,
                                "worker_token_missing",
                                {
                                    "findings": [
                                        {
                                            "config_key": f.config_key,
                                            "context": f.context,
                                        }
                                        for f in missing_findings
                                    ],
                                },
                                level="warning",
                            )
                            state["worker_token_escalated"] = True
                            save_state(self.paths.state_file, state)
            # The refusal itself is NOT dry-run-gated: a dry-run preview must
            # report the same deferral a live pass would take (matching the
            # fleet_lock_held / graphql_rate_limit deferral precedent in this
            # function). Only the escalation event / durable marker writes
            # above stay behind ``not self.dry_run``.
            if self.config.dispatch.require_worker_github_token:
                return CommandResult(
                    True,
                    "dispatch deferred: no sanctioned worker GitHub token "
                    "(set devin.worker_env / claude_code.worker_env "
                    "{'GH_TOKEN': '<scoped-PAT>'}; see issue #1001)",
                    {
                        "selected_count": 0,
                        "attempted_count": 0,
                        "failed_count": 0,
                        "skipped_issue_numbers": [],
                        "label_errors": [],
                        "sessions": [],
                        "dispatch_results": [],
                        "deferred_reason": "worker_token_missing",
                        "missing_config_keys": [f.config_key for f in missing_findings],
                    },
                )
        else:
            self._worker_token_escalated = False
            # Condition resolved: clear the durable marker so a future
            # regression re-escalates. Dry-run never writes — a dry-run pass
            # that observes a now-healthy config must not mutate the marker
            # set by a prior real pass (and cannot have set it itself).
            if not self.dry_run:
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    if state.get("worker_token_escalated", False):
                        state["worker_token_escalated"] = False
                        save_state(self.paths.state_file, state)

        # Issue #427: include closed ready-labeled issues so externally-merged PRs
        # (e.g. Aviator MergeQueue) can be finalized even after GitHub closes the issue.
        if ready_issues is None:
            issues = self.gh.issue_list(
                labels=[self.config.labels.ready],
                state="all",
            )
        else:
            issues = ready_issues
        dispatch_limit = limit if limit is not None else self.config.dispatch.default_limit
        operator_claimed_ready: list[int] = []

        # Issue #1110 rework: classify_backlog_reachability now runs the same
        # per-issue blocker check the dispatch candidate filter runs (issue
        # #1110 wired _get_open_blockers_for_issue into its else-branch). That
        # check calls get_github_issue_dependencies + are_issues_open per issue
        # -- exactly the N+1 serial `gh` pattern issue #870 built
        # _prefetch_blocker_data to eliminate. Warm the pass-scoped cache for
        # every ready issue once, *before* reachability's serial per-issue
        # lookups run, mirroring how status() warms the cache before its own
        # classify_backlog_reachability call. ``issues`` here is the
        # ready-labelled state="all" set; reachability fetches its own open
        # list, but its blocker check only runs on ready-labelled OPEN issues,
        # which are a subset of this set, so this warm-up covers every
        # dependency lookup reachability will make. The later
        # _filter_blocked_issues(candidates) call below benefits too:
        # candidates are a further subset, so the cache is already warm for
        # them as well. Harmless to call twice (second call is a cache hit).
        self._prefetch_blocker_data(issues)

        # Issue #944: observe the UNFILTERED backlog alongside the filtered
        # candidate query above. This does not participate in selection and
        # must not change dispatch behaviour -- it exists so that a zero
        # dispatch count carries a reason. Done here, outside the state lock,
        # because it is network I/O.
        backlog_reachability = classify_backlog_reachability(
            self.gh,
            self.config,
            operator_claimed_issues(load_state_locked(self.paths.state_file)),
            ready_open_count=sum(
                1 for issue in issues if str(issue.get("state") or "OPEN").upper() == "OPEN"
            ),
        )

        # Gather sessions_dir for stall detection and live worker counting
        sessions_dir = self._layout.sessions_dir
        # Issue #1393: clean up stranded .json.tmp session sidecar files from
        # interrupted atomic writes before this pass writes new ones.
        cleanup_stale_session_tmp_files(sessions_dir)

        # Detect and handle stalled sessions before applying concurrency governor.
        # This must run exactly once per pass, not twice (was duplicated in the
        # governor). When the caller already ran the sweep this pass (loop()'s
        # unconditional reaper at the top of its pass), it hands the result down
        # via ``stalled_entries`` and the sweep is NOT re-run here — see
        # dispatch()'s docstring for why re-running it corrupts the Signal-1
        # deferral counter.
        if stalled_entries is None:
            stalled_entries = _detect_and_handle_stalled_sessions(
                sessions_dir,
                self.paths.state_file,
                self.config,
                write_gate=self.write_gate,
            )

        # Count live workers after stall handling (stalled workers are killed).
        # Corroborated against state.json (issue #343) so a ghost -- a live
        # worker_pid whose sidecar was removed -- cannot silently free a slot.
        live_count = _count_live_sessions(sessions_dir, self.paths.state_file)

        # Apply global concurrency governor cap with pre-computed live_count.
        # Issue #1129: fresh-issue dispatch also applies open-PR backpressure
        # (max_open_agent_prs), pacing new PR creation to the review/merge lane.
        gov = self._apply_concurrency_governor(
            dispatch_limit,
            live_count=live_count,
            apply_open_pr_backpressure=True,
        )
        dispatch_limit = gov.dispatch_limit

        # Compute the merged PR list (if already fetched) for the tripwire so
        # loop() can reuse it and avoid a second GraphQL call per pass.
        merged_prs_for_tripwire: list[dict[str, Any]] | None = (
            merged_prs.items
            if merged_prs is not None and merged_prs.called and merged_prs.error is None
            else None
        )

        # Apply provider throttle cooldown check
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            if is_throttled(state):
                throttled_until = state.get("throttled_until")
                # Return immediately with deferral reason
                data = {
                    "selected_count": 0,
                    "attempted_count": 0,
                    "failed_count": 0,
                    "skipped_issue_numbers": [],
                    "label_errors": [],
                    "sessions": [],
                    "dispatch_results": [],
                    "merged_prs": merged_prs_for_tripwire,
                    "deferred_reason": "provider_throttled",
                    "throttled_until": throttled_until,
                }
                if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                    data.update(gov.report_fields())
                return CommandResult(
                    False,
                    f"dispatch deferred: provider throttled until {throttled_until}",
                    data,
                )

        def _resolve_merged_prs(
            outcome: _MergedPRListOutcome | None,
        ) -> list[dict[str, Any]]:
            # Both raising branches (the direct fallback below and the
            # outcome.error re-raise) propagate GitHubError to dispatch()'s
            # ``except GitHubError`` handler, which defers the pass. This is
            # deliberate: proceeding with [] would re-dispatch issues a merged
            # PR already covered (the silent-empty path #633 closed). The
            # direct fallback is the COMMON case — it runs whenever there are
            # open ready issues but no closed-ready issues this pass, because
            # _finalize_externally_merged_issues skips the merged_pr_list()
            # fetch entirely when closed_ready is empty (returning an outcome
            # with called=False).
            if outcome is None or not outcome.called:
                return self.gh.merged_pr_list() if issues else []
            if outcome.error is not None and issues:
                raise outcome.error
            return outcome.items if issues else []

        # Dry-run: read-only planning — compute selection and would-be SessionRequests,
        # but skip all state writes, label transitions, and file mutations.
        if self.dry_run:
            selected_issue_numbers: list[int] = []
            skipped_issue_numbers: list[int] = []
            # Detect stalled sessions (read-only for dry-run)
            stalled_entries = _detect_stalled_sessions(sessions_dir, self.config)
            stalled_issues = {entry["issue"] for entry in stalled_entries}
            live_worker_issues = _issues_with_live_workers(sessions_dir)
            prs = self.gh.pr_list()
            # No ready issues means _merged_pr_referenced_issue_numbers() would
            # return empty sets regardless of what merged_pr_list() returns
            # (it intersects against the ready-issue-number set) — skip the
            # expensive listing query entirely rather than fetch-and-discard
            # (issue #361).
            resolved_merged_prs = _resolve_merged_prs(merged_prs)
            (
                merged_pr_bound_issue_numbers,
                merged_pr_mention_only_issue_numbers,
                _,
            ) = self._merged_pr_referenced_issue_numbers(issues, resolved_merged_prs)
            merged_pr_issue_numbers = (
                merged_pr_bound_issue_numbers | merged_pr_mention_only_issue_numbers
            )
            pr_by_issue = {}
            for pr in prs:
                issue_number = linked_issue_number(
                    pr,
                    is_cross_repository=pr.get("isCrossRepository"),
                    branch_prefix=self.config.dispatch.branch_prefix,
                )
                if issue_number is not None:
                    # If multiple PRs link to the same issue, keep the lowest PR number
                    if issue_number not in pr_by_issue or int(pr["number"]) < int(
                        pr_by_issue[issue_number]["number"]
                    ):
                        pr_by_issue[issue_number] = pr

            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                # Same dispatchability logic as the real dispatch, but read-only
                # Issue #5: also check worker liveness for "dispatched" status
                live_dispatched = set()
                for number, entry in state.get("issues", {}).items():
                    if not isinstance(entry, dict):
                        continue
                    status = entry.get("status")
                    if status == "dispatch_pending" and not is_claim_stale(
                        entry.get("dispatch_pending_at")
                    ):
                        live_dispatched.add(int(number))
                    elif status == "dispatched":
                        # Issue #5: only exclude if the worker is alive OR there's an open PR.
                        # A dead worker with no open PR is recoverable (crashed before PR opened).
                        # A dead worker with an open PR is mid-review and must not be re-dispatched.
                        # Issue #207: also check state.json worker_pid for liveness when session files are orphaned
                        issue_number = int(number)
                        worker_alive = _worker_pid_alive(entry)
                        if (
                            issue_number in live_worker_issues
                            or worker_alive
                            or issue_number in pr_by_issue
                        ):
                            live_dispatched.add(issue_number)
                issues_with_open_tracked_prs = set(pr_by_issue.keys())
                # Issue #1336: lift the mention-only exclusion for re-armed
                # issues (read-only detection for dry-run parity with the
                # real dispatch path -- never stamps state).
                _already_flagged_dry = {
                    int(num)
                    for num, entry in state.get("issues", {}).items()
                    if isinstance(entry, dict) and entry.get("merged_pr_mention_flagged_at")
                }
                rearmed_mention_issues, _ = self._mention_rearmed_issue_numbers(
                    merged_pr_mention_only_issue_numbers,
                    issues,
                    state,
                    _already_flagged_dry,
                )
                merged_pr_issue_numbers = merged_pr_bound_issue_numbers | (
                    merged_pr_mention_only_issue_numbers - rearmed_mention_issues
                )
            candidates = [
                issue
                for issue in issues
                if self._is_dispatchable(issue)
                and int(issue["number"]) not in live_dispatched
                and int(issue["number"]) not in stalled_issues
                and int(issue["number"]) not in issues_with_open_tracked_prs
                and int(issue["number"]) not in merged_pr_issue_numbers
            ]

            # Apply dependency gate: skip issues with open blockers (dry-run)
            # Done outside the lock to avoid holding it during GitHub API calls
            candidates, blocked_issues, _open_blockers_by_issue = self._filter_blocked_issues(
                candidates
            )

            # Sort candidates by dispatch order
            # Default (oldest) uses dependency-aware ordering; explicit newest uses creation date
            if self.config.dispatch.order == "newest":
                candidates = self._sort_by_dispatch_order(candidates)
            else:
                # Default: use dependency-aware ordering (out-degree) with oldest-first tiebreaker
                candidates = self._sort_by_dependency_depth(candidates)

            # Fill fresh candidates first; recovery retries only get leftover slots
            # and are capped at one per pass (issue #506).
            (
                selected,
                skipped_issue_numbers,
                deferred_by_concurrency_full,
                deferred_by_concurrency_count,
            ) = _select_dispatch_candidates(
                candidates,
                dispatch_limit,
                state,
                self._branch_name,
                only_issues=only_issues,
            )
            # Issue #1005 review: this dry-run branch never persists an event
            # or calls _build_failure_map, but truncate for display parity
            # with the real-dispatch payload below -- keep the untruncated
            # list around under its own name so nothing downstream mistakes
            # it for complete.
            deferred_by_concurrency = deferred_by_concurrency_full[
                :_MAX_DEFERRED_CONCURRENCY_EXAMPLES
            ]
            selected_issue_numbers = [int(issue["number"]) for issue in selected]

            # Compute would-be SessionRequests without state mutation
            session_requests: list[SessionRequest] = []
            full_issues: dict[int, dict[str, Any]] = {}
            # Issue #482: compute would-be adapter choices (read-only).
            adapter_choices: dict[int, AdapterChoice] = {}
            api_enabled = self.config.api_worker.enabled
            routing_inputs = self._routing_inputs() if api_enabled else None
            # Issue #1010: dry-run cross-repo gate — report which issues would
            # be escalated without mutating state or labels.
            # Issue #1244: dry-run cross-repo *scope* gate — report issues whose
            # title names another managed repo.
            dry_run_cross_repo_escalated: dict[int, str] = {}
            fleet_repos = managed_repo_names(self.fleet_dir_override)
            dispatching_repo_name = _dispatching_repo_name(self.gh, self.repo_root)
            for issue_number in selected_issue_numbers:
                full_issue = self.gh.issue_view(issue_number)
                full_issues[issue_number] = full_issue
                branch_name = self._branch_name(full_issue)

                # Pre-flight gate: report cross-repo targets without escalating.
                gate_result = cross_repo_gate(str(full_issue.get("body") or ""), self.repo_root)
                if not gate_result.passed:
                    dry_run_cross_repo_escalated[issue_number] = gate_result.reason
                    continue

                # Pre-flight scope gate: report cross-repo scope targets.
                scope_result = cross_repo_scope_gate(
                    str(full_issue.get("title") or ""),
                    str(full_issue.get("body") or ""),
                    dispatching_repo_name,
                    fleet_repos,
                )
                if not scope_result.passed:
                    dry_run_cross_repo_escalated[issue_number] = scope_result.reason
                    continue

                template: str | None = None
                if api_enabled and routing_inputs is not None:
                    issue_labels = {label["name"] for label in full_issue.get("labels", [])}
                    choice = self._select_adapter_for_issue(
                        rework=False,
                        issue_labels=issue_labels,
                        routing_inputs=routing_inputs,
                    )
                    adapter_choices[issue_number] = choice
                    if choice.kind == "api":
                        template = self.config.api_worker.worker_template

                prompt_path = self._write_worker_prompt(
                    full_issue, template=template, dry_run=True
                )

                # Check if this is a dead-worker recovery (same logic as real dispatch)
                recovery_record: dict[str, Any] | None = None
                prev_entry = state.get("issues", {}).get(str(issue_number), {})
                prev_branch = prev_entry.get("branch_name")
                if prev_branch == branch_name and prev_entry.get("status") == "dispatched":
                    recovery_record = prev_entry

                session_requests.append(
                    SessionRequest(
                        issue_number=issue_number,
                        issue_title=str(full_issue.get("title") or ""),
                        prompt_path=prompt_path,
                        branch_name=branch_name,
                        recovery=recovery_record,
                    )
                )

            # Return planning data without touching state, labels, or manifest/results files
            data = {
                "selected_count": len(session_requests),
                "attempted_count": len(session_requests),
                "failed_count": 0,
                "skipped_issue_numbers": skipped_issue_numbers,
                "deferred_by_concurrency": deferred_by_concurrency,
                "deferred_by_concurrency_count": deferred_by_concurrency_count,
                "merged_prs": resolved_merged_prs,
                "merged_pr_referenced_issue_numbers": sorted(merged_pr_issue_numbers),
                "merged_pr_mention_only_issue_numbers": sorted(
                    merged_pr_mention_only_issue_numbers
                ),
                "merged_pr_mention_rearmed_issue_numbers": sorted(rearmed_mention_issues),
                "label_errors": [],
                "cross_repo_escalated_issue_numbers": sorted(dry_run_cross_repo_escalated),
                "sessions": [asdict(request) for request in session_requests],
                "adapter_choices": {
                    str(n): {"kind": c.kind, "provider": c.provider, "reason": c.reason}
                    for n, c in sorted(adapter_choices.items())
                },
                "dispatch_results": [],
                "blocked": [
                    {"issue": issue_number, "blockers": blockers}
                    for issue_number, blockers in sorted(blocked_issues.items())
                ],
                "stalled": stalled_entries,
            }
            if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                data.update(gov.report_fields())
            return CommandResult(
                True,
                f"dry-run: would dispatch {len(session_requests)} issue(s)",
                data,
            )

        # Real dispatch: claim issues, launch workers, update state and labels
        # First lock: claim issues by marking them as dispatch_pending
        selected_issue_numbers: list[int] = []
        skipped_issue_numbers: list[int] = []
        # Use pre-computed stalled_entries from the stall detection above
        stalled_issues = {entry["issue"] for entry in stalled_entries}
        live_worker_issues = _issues_with_live_workers(sessions_dir)
        prs = self.gh.pr_list()
        # No ready issues means _merged_pr_referenced_issue_numbers() would
        # return empty sets regardless of what merged_pr_list() returns (it
        # intersects against the ready-issue-number set) — skip the expensive
        # listing query entirely rather than fetch-and-discard (issue #361).
        resolved_merged_prs = _resolve_merged_prs(merged_prs)
        (
            merged_pr_bound_issue_numbers,
            merged_pr_mention_only_issue_numbers,
            merged_pr_bound_pr_numbers,
        ) = self._merged_pr_referenced_issue_numbers(issues, resolved_merged_prs)
        merged_pr_issue_numbers = (
            merged_pr_bound_issue_numbers | merged_pr_mention_only_issue_numbers
        )

        # Issue #432: cap merge-finalization per pass so a large backlog cannot
        # monopolize the pass budget. Oldest first (by creation date, then issue
        # number) drains the backlog deterministically.
        issue_by_number = {int(issue["number"]): issue for issue in issues}
        finalize_limit = self.config.dispatch.finalize_limit

        def _finalization_order(issue_numbers: set[int]) -> list[int]:
            return sorted(
                issue_numbers,
                key=lambda n: (issue_by_number.get(n, {}).get("createdAt", ""), n),
            )

        finalizable_bound_issue_numbers = _finalization_order(merged_pr_bound_issue_numbers)[
            :finalize_limit
        ]
        finalizable_mention_issue_numbers = _finalization_order(
            merged_pr_mention_only_issue_numbers
        )[:finalize_limit]

        pr_by_issue = {}
        for pr in prs:
            issue_number = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if issue_number is not None:
                # If multiple PRs link to the same issue, keep the lowest PR number
                if issue_number not in pr_by_issue or int(pr["number"]) < int(
                    pr_by_issue[issue_number]["number"]
                ):
                    pr_by_issue[issue_number] = pr

        # Close ready issues whose merged PR safely binds to them (hijack-safe:
        # same-repo branch-prefix or closing-action verb — the same trust
        # level issue #220 uses to close at merge time). This is
        # belt-and-suspenders in case #220's merge-time close hasn't landed
        # yet. These are network calls, so they run outside the state lock;
        # the successful closures are persisted to state.json inside the lock
        # below, and the issue numbers are excluded from dispatch candidates
        # regardless of closure success. Issue #432: only the oldest
        # finalize_limit issues are processed per pass, so a one-time backlog
        # cannot monopolize the pass budget.
        closed_merged_pr_issues: set[int] = set()
        for issue_number in finalizable_bound_issue_numbers:
            # Best-effort label transition and issue close. A failure here is
            # non-fatal; the issue is still excluded from dispatch because the
            # merged PR reference exists, and the next pass will retry.
            transition(self.gh, self.config.labels, issue_number, "merged")
            if self.gh.close_issue(issue_number):
                closed_merged_pr_issues.add(issue_number)

        # Issue #203 (redesigned per review): a merged PR that only
        # *mentions* the issue in free text has no hijack-safe binding and
        # must never authorize a close. Flag it for a human instead — the
        # issue is excluded from this pass's candidates (via
        # merged_pr_issue_numbers below) and left OPEN for the operator to
        # decide whether to close it, wire up a proper closing reference, or
        # redispatch it. Issue #432: capped to finalize_limit per pass.
        #
        # Issue #564: one-shot flagging. The flag must fire once per issue,
        # not every pass — otherwise the operator's removal of
        # agent:human-needed is overridden on the next pass and the event
        # stream is spammed with one dispatch_merged_pr_mention_flagged event
        # per pass while the mention persists. Skip issues whose state entry
        # already records merged_pr_mention_flagged_at (set the first time
        # this path flagged them). This follows the emit-on-change dedup
        # pattern established in #556 for dispatch_skip_blocked/janitor_gate.
        #
        # Re-flag semantics: keyed on the timestamp's absence — once flagged,
        # an issue is never re-flagged, even if a NEW merged PR mentions it.
        # The simplest acceptable semantics per issue #564; pinned by
        # test_dispatch_merged_pr_mention_flag_is_one_shot.
        #
        # Issue #1336 follow-up to #564 point 2: the mention-only *dispatch
        # exclusion* previously keyed off the raw mention scan
        # (merged_pr_issue_numbers below) alone, so an operator who removed
        # agent:human-needed to re-arm automation could NOT re-enter dispatch
        # -- the scan-based exclusion kept blocking the issue until it closed
        # or the mentioning PRs were no longer merged/referenced. The
        # exclusion now lifts for an issue once it was flagged in a prior pass
        # and the operator has removed agent:human-needed: the re-arm is
        # detected from the already-loaded issue labels (no new per-pass API
        # call) and recorded durably in state.json as ``mention_rearmed_at``,
        # so the candidate filter keys the lift off the state signal rather
        # than a per-pass label read -- the blast-radius concern the original
        # comment raised. ``bound`` exclusions stay scan-based; the safe
        # default (never-flagged or still-carries-human-needed stays
        # excluded) is preserved. See ``_mention_rearmed_issue_numbers`` and
        # the re-arm block inside the state lock below.
        # load_state_locked (not raw load_state) so the read holds the
        # advisory state lock — required by the invariant enforced in
        # test_no_unlocked_load_state_in_production_code. The authoritative
        # timestamp write below is a separate locked critical section; this
        # read is best-effort relative to it but must still hold the lock to
        # avoid racing a concurrent tmp+replace writer (issue #310).
        mention_state = load_state_locked(self.paths.state_file)
        already_flagged_mention_issues = {
            int(num)
            for num, entry in mention_state.get("issues", {}).items()
            if isinstance(entry, dict) and entry.get("merged_pr_mention_flagged_at")
        }
        newly_flagged_mention_issues = [
            n for n in finalizable_mention_issue_numbers if n not in already_flagged_mention_issues
        ]
        # Capture the transition outcome per issue so the dedup marker below
        # is only stamped for issues whose label edge actually took effect.
        # Stamping unconditionally (the pre-fix behavior) meant a
        # PARTIAL_FAILURE label write still recorded
        # merged_pr_mention_flagged_at, permanently suppressing retry (the
        # one-shot guard above keys off the timestamp's presence) with no
        # diagnostic beyond transition()'s own log line. NOTHING_CHANGED is
        # treated the same as APPLIED: per labels.py's _edges(),
        # "merged_pr_mention_flagged" always has a non-empty add tuple, so
        # NOTHING_CHANGED is unreachable for this event today, but it is
        # handled here defensively since a retry would recompute the exact
        # same static edge and produce the same NOTHING_CHANGED outcome again.
        mention_flag_outcomes: list[tuple[int, TransitionOutcome]] = [
            (
                issue_number,
                transition(
                    self.gh, self.config.labels, issue_number, "merged_pr_mention_flagged"
                ).outcome,
            )
            for issue_number in newly_flagged_mention_issues
        ]
        stamped_mention_issues = [
            issue_number
            for issue_number, outcome in mention_flag_outcomes
            if outcome != TransitionOutcome.PARTIAL_FAILURE
        ]

        # Issue #429/#433: closed-unmerged stripping is handled by
        # _finalize_externally_merged_issues, which already performs the
        # capped per-issue merged-PR lookup and removes stale ready/active labels.

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            # Persist the fact that merged PRs already covered these ready issues.
            # This keeps state.json consistent with the closed GitHub issue and lets
            # reconcile skip the active-status-on-closed-issue drift sweep.
            for issue_number in closed_merged_pr_issues:
                _issue_key = str(issue_number)
                _issue_entry = state["issues"].get(_issue_key, {})
                state["issues"][_issue_key] = {
                    **_issue_entry,
                    "number": issue_number,
                    "status": "closed",
                }
            if closed_merged_pr_issues:
                state = append_event(
                    state,
                    # event-consumer: audit-only -- records the issue-status "closed" mutation
                    # already applied inline above; no downstream consumer needed
                    "dispatch_merged_pr_references_closed",
                    {"issue_numbers": sorted(closed_merged_pr_issues)},
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)
            # Issue #427: finalize state.json entries for the merged PRs so
            # externally-merged PRs (Aviator mergequeue handoff) do not leave
            # stale prs[...].status == "mergequeue" behind.
            for pr_number in merged_pr_bound_pr_numbers:
                _pr_key = str(pr_number)
                _pr_entry = state["prs"].get(_pr_key, {})
                _bound_pr_state = {
                    **_pr_entry,
                    "status": "merged",
                    "merged": True,
                }
                # Issue #747: stamp ``merged_at`` only on a genuine non-merged
                # -> merged transition; preserve the original observation time
                # on entries already recorded as merged.
                if _pr_entry.get("status") != "merged":
                    _bound_pr_state["merged_at"] = utc_now()
                state["prs"][_pr_key] = _bound_pr_state
            if merged_pr_bound_pr_numbers:
                save_state(self.paths.state_file, state)
            # Record a flag timestamp so operators/tooling (e.g. a doctor
            # check) can surface mention-only coverage without re-deriving
            # the mention scan. "status" is deliberately untouched — the
            # issue stays open and its normal state machine intact.
            # Issue #564: only record/emit for issues flagged *this* pass
            # (newly_flagged_mention_issues); already-flagged issues are
            # skipped so the event fires once and the operator's label
            # removal is not overridden on the next pass.
            # Only issues whose transition() outcome was not PARTIAL_FAILURE
            # (stamped_mention_issues, computed above) get the dedup marker —
            # a failed label write must leave it unset so the next pass
            # retries instead of silently leaving the wrong labels forever.
            for issue_number in stamped_mention_issues:
                _issue_key = str(issue_number)
                _issue_entry = state["issues"].get(_issue_key, {})
                state["issues"][_issue_key] = {
                    **_issue_entry,
                    "number": issue_number,
                    "merged_pr_mention_flagged_at": utc_now(),
                    # Issue #783: a merged PR that only mentions the issue in
                    # free text is a hijack-safety judgment call, not a
                    # process failure -- never auto-de-escalated. "status" is
                    # deliberately untouched (see above), so this reason_class
                    # is carried for completeness/consistency even though the
                    # de-escalation sweep never visits this issue via status.
                    "reason_class": escalation_reason_class("judgment"),
                }
            if stamped_mention_issues:
                state = append_event(
                    state,
                    "dispatch_merged_pr_mention_flagged",
                    {"issue_numbers": stamped_mention_issues},
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)
            # Issue #1336: lift the mention-only dispatch exclusion once the
            # operator has re-armed a previously-flagged issue (removed
            # agent:human-needed). The re-arm is recorded durably as
            # ``mention_rearmed_at`` so the exclusion keys off a state.json
            # signal rather than a per-pass GitHub label read in the
            # candidate filter -- the blast-radius concern the #564 point-2
            # comment raised when it documented this as out of scope.
            #
            # Safe default preserved: an issue never flagged, flagged this
            # pass, or flagged and still carrying agent:human-needed stays
            # excluded. ``bound`` exclusions are never lifted -- those PRs
            # genuinely bound to the issue by a hijack-safe signal.
            #
            # The durable stamp + event emission is routed through
            # ``_stamp_mention_rearm`` (Convention A: ``self.write_gate.*``)
            # rather than raw ``append_event``/``save_state`` so the R9
            # shrink-only ratchet on workflow.py's raw-primitive count
            # (issue #1264 W6 PR4) is not increased -- the re-arm writes are
            # new territory this wave does not convert, and a raw
            # ``append_event``+``save_state`` pair would trip the ratchet
            # (baseline 266). The existing flag block above stays raw (it is
            # part of the ratchet's baseline); only the NEW re-arm writes go
            # through the gate.
            rearmed_mention_issues, newly_rearmed_mention_issues = (
                self._mention_rearmed_issue_numbers(
                    merged_pr_mention_only_issue_numbers,
                    issues,
                    state,
                    already_flagged_mention_issues,
                )
            )
            state = self._stamp_mention_rearm(state, newly_rearmed_mention_issues)
            # Recompute the exclusion set so the candidate filter below and
            # the result payload reflect the lifted mention-only exclusions.
            # ``bound`` exclusions are never lifted.
            merged_pr_issue_numbers = merged_pr_bound_issue_numbers | (
                merged_pr_mention_only_issue_numbers - rearmed_mention_issues
            )
            # Defence-in-depth against double-dispatch: an issue whose state records
            # a live launched worker (status "dispatched") or a fresh pending claim
            # (status "dispatch_pending" not yet stale) is not re-dispatchable even
            # if its GitHub label write failed after the worker launched.
            # _is_dispatchable is label-only; this closes the launched-but-unlabeled
            # window that would otherwise spawn a second worker on the same issue.
            # Stale claims (crashed phase-2) are excluded to allow re-dispatch.
            # Issue #5: also check worker liveness for "dispatched" status to recover
            # from crashed workers before PR opens.
            live_dispatched = set()
            dispatch_blocked = set()
            now = datetime.now(UTC)
            for number, entry in state.get("issues", {}).items():
                if not isinstance(entry, dict):
                    continue
                status = entry.get("status")
                if status == "dispatch_pending" and not is_claim_stale(
                    entry.get("dispatch_pending_at")
                ):
                    live_dispatched.add(int(number))
                elif status == "dispatched":
                    # Issue #5: only exclude if the worker is alive OR there's an open PR.
                    # A dead worker with no open PR is recoverable (crashed before PR opened).
                    # A dead worker with an open PR is mid-review and must not be re-dispatched.
                    # Issue #207: also check state.json worker_pid for liveness when session files are orphaned
                    issue_number = int(number)
                    worker_alive = _worker_pid_alive(entry)
                    if (
                        issue_number in live_worker_issues
                        or worker_alive
                        or issue_number in pr_by_issue
                    ):
                        live_dispatched.add(issue_number)
                elif status in ("dispatch_failed", "escalated"):
                    # Issue #461: bound dispatch_failed retries using the same
                    # redispatch-window cap that rework uses. A status already
                    # marked ``escalated`` should also drop out of dispatch.
                    issue_number = int(number)
                    if status == "escalated":
                        dispatch_blocked.add(issue_number)
                    else:
                        recent = _recent_dispatch_failed_attempts(
                            entry,
                            now,
                            self.config.watchdog.redispatch_window_minutes,
                        )
                        if len(recent) > self.config.watchdog.max_auto_redispatch:
                            dispatch_blocked.add(issue_number)
            operator_claimed = operator_claimed_issues(state)
            ready_issue_numbers = {int(issue["number"]) for issue in issues}
            operator_claimed_ready = sorted(operator_claimed & ready_issue_numbers)
            issues_with_open_tracked_prs = set(pr_by_issue.keys())
            candidates = [
                issue
                for issue in issues
                if self._is_dispatchable(issue, operator_claimed)
                and int(issue["number"]) not in live_dispatched
                and int(issue["number"]) not in stalled_issues
                and int(issue["number"]) not in issues_with_open_tracked_prs
                and int(issue["number"]) not in merged_pr_issue_numbers
                and int(issue["number"]) not in dispatch_blocked
            ]
            if operator_claimed_ready:
                state = append_event(
                    state,
                    # event-consumer: audit-only -- records a skip already enforced by the
                    # `candidates` filter above; the skip itself already happened
                    "dispatch_skip_operator_claimed",
                    {"issue_numbers": operator_claimed_ready},
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)

        # Apply dependency gate: skip issues with open blockers
        # Done outside the lock to avoid holding it during GitHub API calls
        candidates, blocked_issues, open_blockers_by_issue = self._filter_blocked_issues(
            candidates
        )

        # Sort candidates by dispatch order
        # Default (oldest) uses dependency-aware ordering; explicit newest uses creation date
        if self.config.dispatch.order == "newest":
            candidates = self._sort_by_dispatch_order(candidates)
        else:
            # Default: use dependency-aware ordering (out-degree) with oldest-first tiebreaker
            candidates = self._sort_by_dependency_depth(candidates)

        # Re-enter lock to log events and claim issues
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)

            # Log dispatch_skip_blocked events for blocked issues. Dedup
            # (cost-spirals.md Finding 3): a still-blocked issue re-selects
            # every pass with the identical blocker list -- 784 byte-identical
            # events over 18h in the investigated window -- so only emit when
            # the (issue, blockers) content actually changed since the last
            # emission, tracked via a compact snapshot on the issue record.
            if blocked_issues:
                for issue_number, blockers in blocked_issues.items():
                    issue_key = str(issue_number)
                    issue_entry = state["issues"].get(issue_key, {})
                    if not isinstance(issue_entry, dict):
                        issue_entry = {}
                    if issue_entry.get("last_skip_blocked_blockers") != blockers:
                        issue_entry = {
                            **issue_entry,
                            "number": issue_number,
                            "last_skip_blocked_blockers": blockers,
                        }
                        state["issues"][issue_key] = issue_entry
                        state = self._record_event(
                            state,
                            "dispatch_skip_blocked",
                            {"issue": issue_number, "blockers": blockers},
                        )

                    # Blocked-chain attention (pr-lifecycle.md/cost-spirals.md
                    # Finding 3/4): an issue whose every currently-open
                    # blocker is itself dead (escalated, or its tracked PR is
                    # escalated/janitor_blocked) can never unblock through any
                    # automated path. Alert once on transition into that
                    # state -- no label changes, diagnostic only -- instead
                    # of silently re-skipping forever (observed: 4+ days
                    # stuck with zero signal).
                    open_blockers = open_blockers_by_issue.get(issue_number, [])
                    dead_blockers = sorted(
                        b for b in open_blockers if self._is_dead_blocker(b, state, pr_by_issue)
                    )
                    chain_dead = bool(open_blockers) and dead_blockers == sorted(open_blockers)
                    previously_alerted = issue_entry.get("chain_dead_alerted_blockers")
                    if chain_dead and previously_alerted != dead_blockers:
                        state["issues"][issue_key] = {
                            **issue_entry,
                            "number": issue_number,
                            "chain_dead_alerted_blockers": dead_blockers,
                        }
                        state = self._record_event(
                            state,
                            "dispatch_blocked_chain_dead",
                            {"issue": issue_number, "chain_root": dead_blockers},
                        )
                    elif not chain_dead and previously_alerted is not None:
                        # Recovered (or the dead set changed) -- clear the
                        # marker so a future transition back into all-dead
                        # alerts again instead of staying silent forever.
                        state["issues"][issue_key] = {
                            **issue_entry,
                            "number": issue_number,
                            "chain_dead_alerted_blockers": None,
                        }
                save_state(self.paths.state_file, state)

            # Fill fresh candidates first; recovery retries only get leftover slots
            # and are capped at one per pass (issue #506).
            (
                selected,
                skipped_issue_numbers,
                deferred_by_concurrency_full,
                deferred_by_concurrency_count,
            ) = _select_dispatch_candidates(
                candidates,
                dispatch_limit,
                state,
                self._branch_name,
                only_issues=only_issues,
            )
            # Issue #1005 review: _build_failure_map must see every deferred
            # issue (deferred_by_concurrency_full) so each one keeps its
            # per-issue "failures" entry -- only the persisted event and
            # CommandResult.data payloads truncate, via
            # deferred_by_concurrency below. Truncating before
            # _build_failure_map silently dropped failures entries for the
            # 6th+ deferred issue; caught in review before merge.
            deferred_by_concurrency = deferred_by_concurrency_full[
                :_MAX_DEFERRED_CONCURRENCY_EXAMPLES
            ]
            selected_issue_numbers = [int(issue["number"]) for issue in selected]
            # Capture previous entries for recovery detection BEFORE overwriting status
            # Issue #81: we need to know if an issue was previously "dispatched" on the same branch
            # to recover from a crashed worker. This snapshot must be taken before we overwrite
            # the status to "dispatch_pending".
            previous_entries: dict[int, dict[str, Any]] = {}
            for issue_number in selected_issue_numbers:
                previous_entries[issue_number] = state["issues"].get(str(issue_number), {})
            # Mark selected issues as "dispatch_pending" to claim them before launching
            for issue_number in selected_issue_numbers:
                entry = {
                    **state["issues"].get(str(issue_number), {}),
                    "number": issue_number,
                    "status": "dispatch_pending",
                    "dispatch_pending_at": utc_now(),
                }
                # A fresh dispatch supersedes any previous orphan flag.
                entry.pop("orphan_flagged_at", None)
                entry.pop("orphan_drift_fingerprint", None)
                entry.pop("orphan_drift_at", None)
                state["issues"][str(issue_number)] = entry
            save_state(self.paths.state_file, state)
        # Do all network calls, file writes, and worker launches outside the lock
        session_requests: list[SessionRequest] = []
        full_issues: dict[int, dict[str, Any]] = {}
        # Issue #482: per-issue adapter routing. When api_worker is enabled,
        # select_adapter is called once per issue to route it to the api or
        # fallback adapter. When disabled, adapter_choices stays empty and
        # _dispatch_partitioned falls back to a single-group dispatch
        # byte-identical to the pre-#482 behavior.
        adapter_choices: dict[int, AdapterChoice] = {}
        api_enabled = self.config.api_worker.enabled
        routing_inputs = self._routing_inputs() if api_enabled else None
        # Issue #1000: per-issue citation-drift verdicts and the fingerprint that
        # dedups the flag-comment across passes. Populated in the loop below;
        # consumed in the second state-lock section to stamp the issue record and
        # emit one ``dispatch_citation_drift_flagged`` event per drift change.
        citation_drift_stamps: dict[int, tuple[str, list[CitationVerdict]]] = {}
        # Issue #1010: pre-flight cross-repo gate. Issues whose referenced
        # file paths are all absent from the target repo are escalated to
        # human-needed instead of dispatching a worker that will wander to a
        # sibling repo's shared checkout.
        # Issue #1244: pre-flight cross-repo *scope* gate. Issues whose title
        # names another managed repo in the fleet (e.g. "job-cannon: ...") are
        # escalated too — their deliverables live in that repo, not this one,
        # so the dispatching lane can never finalize them.  The managed-repo
        # set is derived from the fleet registry, never a hardcoded list.
        cross_repo_escalated: dict[int, str] = {}
        fleet_repos = managed_repo_names(self.fleet_dir_override)
        dispatching_repo_name = _dispatching_repo_name(self.gh, self.repo_root)
        for issue_number in selected_issue_numbers:
            full_issue = self.gh.issue_view(issue_number)
            full_issues[issue_number] = full_issue
            branch_name = self._branch_name(full_issue)

            # Pre-flight gate: refuse to dispatch when the issue's referenced
            # code does not exist in this repo (issue #1010).
            gate_result = cross_repo_gate(str(full_issue.get("body") or ""), self.repo_root)
            if not gate_result.passed:
                cross_repo_escalated[issue_number] = gate_result.reason
                continue

            # Pre-flight scope gate: refuse to dispatch when the issue's title
            # names another managed repo (issue #1244).
            scope_result = cross_repo_scope_gate(
                str(full_issue.get("title") or ""),
                str(full_issue.get("body") or ""),
                dispatching_repo_name,
                fleet_repos,
            )
            if not scope_result.passed:
                cross_repo_escalated[issue_number] = scope_result.reason
                continue

            # Determine the adapter for this issue (single point of enforcement:
            # routing.select_adapter). The prompt template follows the choice
            # so the api worker gets the claude-code-flavored prompt.
            template: str | None = None
            if api_enabled and routing_inputs is not None:
                issue_labels = {label["name"] for label in full_issue.get("labels", [])}
                choice = self._select_adapter_for_issue(
                    rework=False,
                    issue_labels=issue_labels,
                    routing_inputs=routing_inputs,
                )
                adapter_choices[issue_number] = choice
                if choice.kind == "api":
                    template = self.config.api_worker.worker_template

            prompt_path = self._write_worker_prompt(full_issue, template=template)

            # Issue #1000: verify path:line citations in the issue body against
            # the working tree before a worker is sent to them. Drift is flagged
            # (a comment on the issue, which the worker sees via $issue_comments)
            # rather than auto-edited -- the correction needs judgment. The flag
            # is deduped by fingerprint so a still-stale issue is not re-commented
            # every pass, and a newly-stale citation re-alerts. Non-blocking: a
            # verification failure never aborts dispatch, and dispatch itself is
            # not gated on drift -- the comment is the signal, not a hold.
            citation_drift_stamps.update(
                self._check_issue_citations(issue_number, full_issue, previous_entries)
            )

            # Check if this is a dead-worker recovery: the issue has a previous
            # dispatch record with the same branch name (i.e., our own crashed attempt)
            # Use the snapshot captured before status overwrite (Issue #81 fix)
            recovery_record: dict[str, Any] | None = None
            prev_entry = previous_entries.get(issue_number, {})
            prev_branch = prev_entry.get("branch_name")
            if prev_branch == branch_name and prev_entry.get("status") == "dispatched":
                # This is our own crashed attempt - pass the record for recovery
                recovery_record = prev_entry

            session_requests.append(
                SessionRequest(
                    issue_number=issue_number,
                    issue_title=str(full_issue.get("title") or ""),
                    prompt_path=prompt_path,
                    branch_name=branch_name,
                    recovery=recovery_record,
                )
            )
        dispatch_results = self._dispatch_partitioned(session_requests, adapter_choices)
        manifest_path = self._layout.session_manifest
        results_path = self._layout.session_results
        successful_issue_numbers = {
            result.issue_number for result in dispatch_results if result.ok
        }
        # Issue #523: a live_worker_redispatch_averted result claims the prior
        # worker is still alive, but the adapter's probe (_probe_recovery_liveness)
        # can fail closed on an inconclusive real-activity signal (probe_error) or
        # report fresh sessions.db activity even when the recorded wrapper PID is
        # dead/recycled. Verify the PID against the OS (with start-time identity)
        # at the single point where live worker slots are counted — the same
        # is_pid_alive + process_start_time check the review lane uses via
        # _reviewer_pid_alive. A session whose recorded PID is dead is a phantom
        # slot and is routed through the dead-session path below (sidecar reap,
        # label repair) instead of starving fresh dispatch.
        live_worker_issue_numbers: set[int] = set()
        phantom_live_worker_issue_numbers: set[int] = set()
        for result in dispatch_results:
            if result.ok or result.failure_kind != "live_worker_redispatch_averted":
                continue
            if (
                result.pid is not None
                and result.pid > 0
                and is_pid_alive(result.pid, result.process_start_time)
            ):
                live_worker_issue_numbers.add(result.issue_number)
            else:
                phantom_live_worker_issue_numbers.add(result.issue_number)
        failed_issue_numbers = {
            result.issue_number
            for result in dispatch_results
            if not result.ok
            and result.issue_number not in live_worker_issue_numbers
            and result.issue_number not in phantom_live_worker_issue_numbers
        }
        foreign_writer_issue_numbers = {
            result.issue_number
            for result in dispatch_results
            if not result.ok and result.failure_kind == "worktree_foreign_writer"
        }
        # Second lock: upgrade claim from dispatch_pending to dispatched/dispatch_failed
        manual = self.config.devin.adapter == "manual"
        label_errors: list[int] = []
        label_error_failures: dict[int, str] = {}
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            for request in session_requests:
                full_issue = full_issues[request.issue_number]
                ok = request.issue_number in successful_issue_numbers
                is_live_worker = request.issue_number in live_worker_issue_numbers
                is_phantom_live_worker = request.issue_number in phantom_live_worker_issue_numbers
                prev_entry = state["issues"].get(str(request.issue_number), {})
                # Issues #837 / #779: the dispatch outcome (status/dispatched_at)
                # and its escalation bookkeeping (dispatch_failed_at /
                # escalation_reason / reason_class) used to be decided in two
                # textually separate if/elif chains keyed on the same four
                # predicates (ok / is_live_worker / is_phantom_live_worker /
                # else) -- one chain bound all_attempts/failed_result/
                # terminal_failure only in its `else`, a second chain ~70 lines
                # down read them only in its matching `elif`/`else`. That was
                # safe only because the two enumerations happened to agree;
                # nothing enforced it, and pyright could not prove it (reported
                # possibly-unbound). Collapsed into one chain below so each
                # branch binds and consumes its own locals -- there is no
                # second enumeration left to drift out of sync with the first.
                # status/dispatched_at are the only values that still cross out
                # of this chain (applied once, after it); every arm binds them
                # unconditionally, so a future arm that forgets to set one is a
                # possibly-unbound error at type-check time, not a silently
                # stale value copied from prev_entry.
                entry = {
                    **prev_entry,
                    "number": request.issue_number,
                    "title": full_issue.get("title"),
                    "url": full_issue.get("url"),
                    "branch_name": request.branch_name,
                    "prompt_path": str(request.prompt_path),
                }
                # Clear the claim timestamp on successful upgrade
                entry.pop("dispatch_pending_at", None)
                entry.pop("label_error", None)
                if ok:
                    status = "manifest_written" if manual else "dispatched"
                    dispatched_at = utc_now()
                    # A successful recovery supersedes any previous orphan flag.
                    entry.pop("orphan_flagged_at", None)
                    entry.pop("orphan_drift_fingerprint", None)
                    entry.pop("orphan_drift_at", None)
                    entry.pop("dispatch_failed_at", None)
                    clear_escalation(entry)
                    clear_escalation_on_issue_prs(state, request.issue_number)
                elif is_live_worker:
                    status = "dispatched"
                    dispatched_at = prev_entry.get("dispatched_at") or utc_now()
                    # A live-worker recovery supersedes any previous orphan flag.
                    entry.pop("orphan_flagged_at", None)
                    entry.pop("orphan_drift_fingerprint", None)
                    entry.pop("orphan_drift_at", None)
                    entry.pop("dispatch_failed_at", None)
                    clear_escalation(entry)
                    clear_escalation_on_issue_prs(state, request.issue_number)
                elif is_phantom_live_worker:
                    # Issue #523: the adapter reported a live worker, but the
                    # recorded PID failed the OS-level liveness + identity
                    # check. Route through the dead-session path (sidecar reap,
                    # label repair) instead of keeping the phantom slot
                    # occupied. The slot is freed and the issue becomes
                    # dispatchable again without burning a redispatch attempt.
                    # A dispatched request's issue can never have an open
                    # tracked PR -- candidate selection excludes every issue in
                    # pr_by_issue -- so the rework-routing case is handled by
                    # the dead-session reaper lane, not here.
                    status, dispatched_at, state = self._route_phantom_live_worker(
                        state,
                        request,
                        full_issue,
                        sessions_dir,
                    )
                    # A phantom live worker is being routed as dead; do not
                    # preserve a stale worker_pid that would keep the slot
                    # occupied, and do not burn a redispatch attempt (the launch
                    # was averted, not failed).
                    entry.pop("orphan_flagged_at", None)
                    entry.pop("orphan_drift_fingerprint", None)
                    entry.pop("orphan_drift_at", None)
                    entry.pop("dispatch_failed_at", None)
                    clear_escalation(entry)
                    clear_escalation_on_issue_prs(state, request.issue_number)
                    entry.pop("worker_pid", None)
                    entry.pop("worker_process_start_time", None)
                else:
                    # Issue #461: bound dispatch_failed retries with the same
                    # redispatch-window cap used for rework.
                    now = datetime.now(UTC)
                    failed_result = next(
                        (r for r in dispatch_results if r.issue_number == request.issue_number),
                        None,
                    )
                    failure_kind = (
                        failed_result.failure_kind if failed_result is not None else None
                    )
                    # Issue #1393: a pre-launch environment block (e.g.
                    # worktree_foreign_writer) never started a worker session,
                    # so it must NOT count against the dispatch_failed cap
                    # (which measures worker output, not environment hygiene).
                    # Use a separate blocked_environment_at counter and
                    # escalate with the correct reason + blocking path after
                    # the same cap.
                    blocked_environment = (
                        failure_kind in PRE_LAUNCH_BLOCKED_ENVIRONMENT_FAILURE_KINDS
                    )
                    if blocked_environment:
                        blocked_environment_at = _windowed_blocked_environment_at(
                            entry,
                            window_minutes=self.config.watchdog.redispatch_window_minutes,
                        ) + [now.isoformat().replace("+00:00", "Z")]
                        blocking_error = failed_result.error if failed_result else None
                        entry["blocked_environment_at"] = blocked_environment_at
                        if len(blocked_environment_at) > self.config.watchdog.max_auto_redispatch:
                            # Issue #1423: before escalating a blocked-environment
                            # cap exhaustion for a foreign writer, attempt to reap
                            # it one more time. A writer that was active on earlier
                            # passes but has since gone idle is reaped here instead
                            # of escalating a zombie to a human. Escalation is
                            # reserved for a writer that is alive *and* active.
                            #
                            # Review finding: bound the number of auto-reaps per
                            # issue before falling back to escalation. Each
                            # successful reap resets ``blocked_environment_at`` to
                            # ``[]``, so without a separate cross-pass cap a
                            # persistently-blocked worktree loops forever between
                            # reap and redispatch. ``foreign_writer_reaps`` is a
                            # windowed counter that survives the reset; once it
                            # reaches ``max_foreign_writer_reaps`` the issue
                            # escalates instead of reaping again.
                            max_reaps = self.config.watchdog.max_foreign_writer_reaps
                            prior_reaps = _windowed_foreign_writer_reaps(
                                entry,
                                window_minutes=self.config.watchdog.redispatch_window_minutes,
                            )
                            if len(prior_reaps) < max_reaps and _try_reap_blocked_foreign_writer(
                                failed_result,
                                self.config,
                                self.paths.state_file,
                                request.issue_number,
                                sessions_dir,
                            ):
                                entry["blocked_environment_at"] = []
                                entry["foreign_writer_reaps"] = prior_reaps + [
                                    now.isoformat().replace("+00:00", "Z")
                                ]
                                status = "dispatch_failed"
                                dispatched_at = None
                                clear_escalation(entry)
                                clear_escalation_on_issue_prs(state, request.issue_number)
                                state = self._record_event(  # event-consumer: audit-only -- records a foreign-writer reap (issue #1423) already enforced by the blocked_environment_at reset and foreign_writer_reaps counter; consumed by tests/test_charlie_work.py regression tests.
                                    state,
                                    "dispatch_blocked_environment_reaped",
                                    {
                                        "issue_number": request.issue_number,
                                        "failure_kind": failure_kind,
                                        "pid": failed_result.pid if failed_result else None,
                                        "blocked_environment_count": len(blocked_environment_at),
                                        "foreign_writer_reap_count": len(prior_reaps) + 1,
                                    },
                                )
                            else:
                                status = "escalated"
                                dispatched_at = None
                                reason_class = "mechanical"
                                state = _escalate_issue(
                                    state,
                                    request.issue_number,
                                    reason="dispatch_blocked_environment",
                                    reason_class=reason_class,
                                    issue_extra=entry,
                                )
                                entry = dict(state["issues"][str(request.issue_number)])
                                state = self._record_event(
                                    state,
                                    "session_failed_escalated",
                                    {
                                        "issue_number": request.issue_number,
                                        "previous_status": "dispatch_pending",
                                        "reason": "dispatch_blocked_environment",
                                        "failure_kind": failure_kind,
                                        "blocking_error": blocking_error,
                                        "blocked_environment_count": len(blocked_environment_at),
                                    },
                                )
                        else:
                            status = "dispatch_failed"
                            dispatched_at = None
                            clear_escalation(entry)
                            clear_escalation_on_issue_prs(state, request.issue_number)
                            state = self._record_event(  # event-consumer: audit-only -- records a pre-launch environment block (issue #1393) already enforced by the blocked_environment_at counter and the dispatch_blocked_environment escalation; consumed by tests/test_charlie_work.py regression tests.
                                state,
                                "dispatch_blocked_environment",
                                {
                                    "issue_number": request.issue_number,
                                    "failure_kind": failure_kind,
                                    "blocking_error": blocking_error,
                                    "blocked_environment_count": len(blocked_environment_at),
                                },
                            )
                    else:
                        all_attempts = list(prev_entry.get("dispatch_failed_at") or [])
                        if not isinstance(all_attempts, list):
                            all_attempts = []
                        all_attempts.append(now.isoformat())
                        recent = _recent_dispatch_failed_attempts(
                            {"dispatch_failed_at": all_attempts},
                            now,
                            self.config.watchdog.redispatch_window_minutes,
                        )
                        # Deterministic launch failures escalate immediately,
                        # mirroring dispatch_rework's post-#550 behavior — fresh
                        # dispatch previously only consulted the redispatch-window
                        # cap, so e.g. a worktree_unsafe failure burned every
                        # capped retry before a human ever heard about it.
                        terminal_failure = (
                            failed_result is not None
                            and failed_result.failure_kind
                            in DETERMINISTIC_ESCALATION_FAILURE_KINDS
                        )
                        # Issue #807: a deterministic judgment failure escalates
                        # immediately but as ``reason_class="judgment"``.
                        deterministic_judgment = (
                            failed_result is not None
                            and failed_result.failure_kind
                            in DETERMINISTIC_JUDGMENT_ESCALATION_FAILURE_KINDS
                        )
                        immediate_escalation = terminal_failure or deterministic_judgment
                        entry["dispatch_failed_at"] = all_attempts
                        if (
                            immediate_escalation
                            or len(recent) > self.config.watchdog.max_auto_redispatch
                        ):
                            status = "escalated"
                            dispatched_at = None
                            reason_class = "judgment" if deterministic_judgment else "mechanical"
                            state = _escalate_issue(
                                state,
                                request.issue_number,
                                reason=(
                                    failed_result.failure_kind
                                    if (
                                        immediate_escalation
                                        and failed_result is not None
                                        and failed_result.failure_kind is not None
                                    )
                                    else "dispatch_failed_cap_exceeded"
                                ),
                                reason_class=reason_class,
                                issue_extra=entry,
                            )
                            # Re-read the escalation fields _escalate_issue merged in,
                            # but keep ``entry`` a decoupled copy: the mutations below
                            # must not reach state until the single atomic write at the
                            # end of this block.
                            entry = dict(state["issues"][str(request.issue_number)])
                        else:
                            status = "dispatch_failed"
                            dispatched_at = None
                            clear_escalation(entry)
                            clear_escalation_on_issue_prs(state, request.issue_number)
                entry["status"] = status
                entry["dispatched_at"] = dispatched_at
                # Store worker PID and process start time for state-based liveness detection
                # This allows recovery even when session sidecar files are orphaned (issue #207)
                if ok:
                    result = next(
                        (r for r in dispatch_results if r.issue_number == request.issue_number),
                        None,
                    )
                    if result and result.pid is not None:
                        entry["worker_pid"] = result.pid
                        entry["worker_process_start_time"] = result.process_start_time
                # Issue #1000: stamp the citation-drift fingerprint computed in
                # the outside-lock loop. The comment was already posted there
                # (best-effort); this persists the dedup marker so a still-stale
                # issue is not re-commented next pass, and emits one event per
                # drift change. ``citation_drift_flagged_at`` records the last
                # time drift was observed, not the first -- it moves with every
                # newly-detected drift state, matching the fingerprint's
                # re-alert semantics.
                drift_stamp = citation_drift_stamps.get(request.issue_number)
                if drift_stamp is not None:
                    fp, drift_verdicts = drift_stamp
                    entry["citation_drift_fingerprint"] = fp
                    if fp:
                        entry["citation_drift_flagged_at"] = utc_now()
                        state = self._record_event(
                            state,
                            "dispatch_citation_drift_flagged",
                            {
                                "issue": request.issue_number,
                                "drifted_citations": [
                                    {
                                        "citation": v.citation.raw,
                                        "path": v.citation.path,
                                        "line": v.citation.line,
                                        "end_line": v.citation.end_line,
                                        "status": v.status.value,
                                        "resolved_path": v.resolved_path.replace("\\", "/")
                                        if v.resolved_path
                                        else None,
                                        "candidates": list(v.candidates) if v.candidates else None,
                                    }
                                    for v in drift_verdicts
                                ],
                            },
                        )
                    else:
                        # Drift resolved since the last pass: clear the marker
                        # so a future regression re-alerts. No event -- the
                        # interesting transition is into drift, not out of it.
                        entry.pop("citation_drift_flagged_at", None)
                state["issues"][str(request.issue_number)] = entry
                # Issue #482: record the adapter choice (including fallback
                # choices) into adapter_history so every routing decision is
                # auditable. record_adapter_choice returns a new state dict
                # (immutable helper); chain it before the atomic save.
                choice = adapter_choices.get(request.issue_number)
                if choice is not None:
                    state = record_adapter_choice(state, request.issue_number, choice, utc_now())
                # Persist the launched worker BEFORE touching GitHub labels: a
                # transient label-write failure (or crash) must never leave a live
                # worker unrecorded and therefore re-dispatchable next wave. The
                # transition is isolated per-issue so one failure never aborts the
                # rest of the batch (orphaning already-launched workers).
                save_state(self.paths.state_file, state)
                # This re-tests the same four predicates as the outcome chain
                # above for a fourth time (label transitions), rather than
                # branching on the outcome directly. It cannot be folded into
                # that chain: GitHub labels must only be touched after
                # save_state has persisted the launched worker (comment above),
                # so this enumeration is structurally separated from the one
                # that decides status/escalation. It does not read
                # all_attempts/failed_result/terminal_failure (issues #837,
                # #779 do not apply here), only the already-bound ok /
                # is_live_worker / status locals, so there is no possibly-
                # unbound hazard -- just a fourth place that must be kept in
                # sync with the outcome predicates if a new outcome is added.
                if ok or is_live_worker:
                    target = "queued" if manual else "dispatched"
                    result = transition(
                        self.gh,
                        self.config.labels,
                        request.issue_number,
                        target,
                    )
                    if result.outcome != TransitionOutcome.APPLIED:
                        label_error = {
                            "edge": target,
                            "outcome": result.outcome.value,
                            "add_failures": result.add_failures,
                            "remove_failures": result.remove_failures,
                        }
                        entry["label_error"] = label_error
                        label_errors.append(request.issue_number)
                        label_error_failures[request.issue_number] = _label_error_reason(
                            label_error
                        )
                        save_state(self.paths.state_file, state)
                    if is_live_worker:
                        result = next(
                            (
                                r
                                for r in dispatch_results
                                if r.issue_number == request.issue_number
                            ),
                            None,
                        )
                        state = append_event(
                            state,
                            "live_worker_redispatch_averted",
                            {
                                "issue_number": request.issue_number,
                                "branch_name": request.branch_name,
                                "pid": result.pid if result else None,
                                "process_start_time": result.process_start_time
                                if result
                                else None,
                                "probe_result": result.error if result else None,
                            },
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, state)
                elif status == "escalated":
                    # Issue #461: dispatch-failed retry cap exceeded — or a
                    # deterministic launch failure that retrying cannot fix
                    # (escalation_reason carries the failure_kind) — escalate to
                    # human-needed and remove the issue from the dispatch pool.
                    # Issue #807: a deterministic judgment failure uses
                    # ``reason_class="judgment"`` so the label lands on
                    # human-needed, not operator_queued.
                    edge = _escalation_edge("redispatch_escalated", reason_class)
                    result = transition(
                        self.gh,
                        self.config.labels,
                        request.issue_number,
                        edge,
                    )
                    if result.outcome != TransitionOutcome.APPLIED:
                        label_error = {
                            "edge": edge,
                            "outcome": result.outcome.value,
                            "add_failures": result.add_failures,
                            "remove_failures": result.remove_failures,
                        }
                        entry["label_error"] = label_error
                        label_errors.append(request.issue_number)
                        label_error_failures[request.issue_number] = _label_error_reason(
                            label_error
                        )
                        save_state(self.paths.state_file, state)

            # Issue #1010: escalate issues blocked by the cross-repo pre-flight
            # gate. Their referenced file paths are all absent from the target
            # repo, so dispatching a worker would send it to a sibling repo's
            # shared checkout. Escalate to human-needed with a cross_repo_target
            # reason and record the event — the issue stays in the dispatch
            # pool's state as escalated, not dispatch_pending.
            for issue_number, reason in sorted(cross_repo_escalated.items()):
                prev_entry = state["issues"].get(str(issue_number), {})
                entry = {
                    **prev_entry,
                    "number": issue_number,
                    "title": full_issues.get(issue_number, {}).get("title"),
                    "url": full_issues.get(issue_number, {}).get("url"),
                }
                entry.pop("dispatch_pending_at", None)
                entry.pop("label_error", None)
                state = _escalate_issue(
                    state,
                    issue_number,
                    reason=reason,
                    reason_class="mechanical",
                    issue_extra=entry,
                )
                state = append_event(
                    state,
                    "dispatch_cross_repo_escalated",
                    {
                        "issue_number": issue_number,
                        "reason": reason,
                    },
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)
                # Transition labels (operator_queue for mechanical, following
                # the same pattern as the redispatch_escalated path above).
                edge = _escalation_edge("redispatch_escalated", "mechanical")
                result = transition(
                    self.gh,
                    self.config.labels,
                    issue_number,
                    edge,
                )
                if result.outcome != TransitionOutcome.APPLIED:
                    label_error = {
                        "edge": edge,
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    }
                    escalated_entry = state["issues"].get(str(issue_number), {})
                    escalated_entry["label_error"] = label_error
                    state["issues"][str(issue_number)] = escalated_entry
                    label_errors.append(issue_number)
                    label_error_failures[issue_number] = _label_error_reason(label_error)
                    save_state(self.paths.state_file, state)

            # Build dispatch-alert transitions for the notify digest. Averted
            # redispatches surface as DISPATCH_AVERTED; a later successful or
            # non-averted dispatch clears the alert back to OK.
            dispatch_alert_transitions: dict[int, dict[str, Any]] = {}
            live_worker_redispatch_averted: list[dict[str, Any]] = []
            for request in session_requests:
                prev_alert = previous_entries.get(request.issue_number, {}).get("dispatch_alert")
                result = next(
                    (r for r in dispatch_results if r.issue_number == request.issue_number),
                    None,
                )
                is_live_worker = request.issue_number in live_worker_issue_numbers
                if is_live_worker:
                    dispatch_alert_transitions[request.issue_number] = {
                        "adapter_kind": result.adapter if result else "unknown",
                        "health": "DISPATCH_AVERTED",
                        "last_log_line": None,
                        "pid": result.pid if result else None,
                        "terminal_tool": None,
                        "terminal_reason": result.error if result else None,
                    }
                    live_worker_redispatch_averted.append(
                        {
                            "issue_number": request.issue_number,
                            "branch_name": request.branch_name,
                            "pid": result.pid if result else None,
                            "process_start_time": result.process_start_time if result else None,
                            "probe_result": result.error if result else None,
                            "adapter_kind": result.adapter if result else "unknown",
                        }
                    )
                elif prev_alert == "DISPATCH_AVERTED":
                    dispatch_alert_transitions[request.issue_number] = {
                        "adapter_kind": result.adapter if result else "unknown",
                        "health": "OK",
                        "last_log_line": None,
                        "pid": result.pid if result else None,
                        "terminal_tool": None,
                        "terminal_reason": None,
                    }

            for issue_number in foreign_writer_issue_numbers:
                result = next(
                    (r for r in dispatch_results if r.issue_number == issue_number), None
                )
                branch_name = next(
                    (r.branch_name for r in session_requests if r.issue_number == issue_number),
                    None,
                )
                state = append_event(
                    state,
                    "worktree_foreign_writer",
                    {
                        "issue_number": issue_number,
                        "branch_name": branch_name,
                        "pid": result.pid if result else None,
                        "probe_result": result.error if result else None,
                    },
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)
            dispatch_failure_map = _build_failure_map(
                dispatch_results,
                failed_issue_numbers,
                deferred_by_concurrency_full,
                dispatch_limit,
                extra_failures=label_error_failures,
            )
            # Issue #946: warn when a non-empty backlog has not produced a
            # non-empty dispatch event for longer than the configured threshold.
            dispatch_staleness = check_dispatch_staleness(
                self.paths.state_file,
                self.config.dispatch,
                backlog_reachability,
                recent_issue_numbers=sorted(successful_issue_numbers),
                now=datetime.now(UTC),
            )
            if dispatch_staleness["stale"]:
                state = self._record_event(state, "dispatch_stale", dispatch_staleness)
            state = append_event(
                state,
                "dispatch",
                {
                    "issue_numbers": sorted(successful_issue_numbers),
                    "live_worker_issue_numbers": sorted(live_worker_issue_numbers),
                    "phantom_live_worker_issue_numbers": sorted(phantom_live_worker_issue_numbers),
                    "failed_issue_numbers": sorted(failed_issue_numbers),
                    "foreign_writer_issue_numbers": sorted(foreign_writer_issue_numbers),
                    "cross_repo_escalated_issue_numbers": sorted(cross_repo_escalated),
                    "label_errors": sorted(label_errors),
                    "skipped_issue_numbers": skipped_issue_numbers,
                    "deferred_by_concurrency": deferred_by_concurrency,
                    "deferred_by_concurrency_count": deferred_by_concurrency_count,
                    "merged_pr_referenced_issue_numbers": sorted(merged_pr_issue_numbers),
                    "merged_pr_closed_issue_numbers": sorted(closed_merged_pr_issues),
                    "merged_pr_flagged_issue_numbers": sorted(newly_flagged_mention_issues),
                    "merged_pr_mention_rearmed_issue_numbers": sorted(
                        newly_rearmed_mention_issues
                    ),
                    "failures": dispatch_failure_map,
                    # Issue #944: why zero, when it is zero. Every other field
                    # here describes issues the ready-filtered query returned;
                    # this one describes the backlog that query cannot see.
                    "backlog_reachability": backlog_reachability,
                    # Issue #946: cadence-staleness diagnostic, always present so
                    # the capped state.json ring carries the signal.
                    "dispatch_staleness": dispatch_staleness,
                    # Issue #1005: the capacity axis. backlog_reachability answers
                    # "why zero" for supply (which issues exist/are reachable);
                    # this answers it for capacity (whether there was a slot to put
                    # one in). Always present -- gov.report_fields() is safe to call
                    # unclamped -- and explicit about `clamped` so a reader does not
                    # have to redo the arithmetic (available_slots == 0 alone does
                    # not say whether the repo cap or the fleet cap was binding).
                    # `dispatch_limit` is included explicitly (report_fields() does
                    # not carry it) because it is the only field that reflects a
                    # fleet-cap clamp: `available_slots` is only recomputed when the
                    # repo governor itself is enabled, so a fleet-only clamp leaves
                    # `available_slots` at its pre-fleet value while `dispatch_limit`
                    # still shows the true (possibly zero) effective limit.
                    "concurrency_governor": {
                        "clamped": gov.clamped,
                        "dispatch_limit": gov.dispatch_limit,
                        **gov.report_fields(),
                    },
                },
                state_path=self.paths.state_file,
            )
            save_state(self.paths.state_file, state)
        result_dicts = [result.to_dict() for result in dispatch_results]
        message = "dispatch complete"
        if failed_issue_numbers:
            entries = ", ".join(
                f"#{issue} ({dispatch_failure_map[issue]})"
                for issue in sorted(failed_issue_numbers)
            )
            message = f"dispatch failures: {entries}"
        elif live_worker_issue_numbers:
            message = "dispatch completed with live worker redispatch averted"
        if skipped_issue_numbers:
            message += f" (skipped non-dispatchable: {skipped_issue_numbers})"
        if label_errors:
            message += f" (launched but label write failed: {sorted(label_errors)})"
        if phantom_live_worker_issue_numbers:
            message += (
                f" (reaped phantom live worker slots: {sorted(phantom_live_worker_issue_numbers)})"
            )
        if cross_repo_escalated:
            message += f" (cross-repo escalated: {sorted(cross_repo_escalated)})"
        data = {
            "selected_count": len(successful_issue_numbers),
            "attempted_count": len(session_requests),
            "failed_count": len(failed_issue_numbers),
            "failures": dispatch_failure_map,
            "live_worker_count": len(live_worker_issue_numbers),
            "phantom_live_worker_count": len(phantom_live_worker_issue_numbers),
            "phantom_live_worker_issue_numbers": sorted(phantom_live_worker_issue_numbers),
            "foreign_writer_count": len(foreign_writer_issue_numbers),
            "cross_repo_escalated_issue_numbers": sorted(cross_repo_escalated),
            "skipped_issue_numbers": skipped_issue_numbers,
            "deferred_by_concurrency": deferred_by_concurrency,
            "deferred_by_concurrency_count": deferred_by_concurrency_count,
            "merged_prs": resolved_merged_prs,
            "merged_pr_referenced_issue_numbers": sorted(merged_pr_issue_numbers),
            "merged_pr_closed_issue_numbers": sorted(closed_merged_pr_issues),
            "merged_pr_flagged_issue_numbers": sorted(newly_flagged_mention_issues),
            "merged_pr_mention_rearmed_issue_numbers": sorted(newly_rearmed_mention_issues),
            "label_errors": sorted(label_errors),
            "session_manifest": str(manifest_path),
            "session_results": str(results_path),
            "sessions": [asdict(request) for request in session_requests],
            "dispatch_results": result_dicts,
            "live_worker_redispatch_averted": live_worker_redispatch_averted,
            "stalled": stalled_entries,
            "blocked": [
                {"issue": issue_number, "blockers": blockers}
                for issue_number, blockers in sorted(blocked_issues.items())
            ],
            "operator_claimed_ready": sorted(operator_claimed_ready),
        }
        if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
            data.update(gov.report_fields())

        # Emit notification digest if there are health transitions (stalled sessions)
        # This will be enhanced by #165 to include RUNAWAY/DEAD/escalated transitions
        if stalled_entries and self.config.notify.enabled:
            health_transitions: dict[int, dict[str, Any]] = {}
            for entry in stalled_entries:
                health_transitions[entry["issue"]] = {
                    "adapter_kind": "unknown",  # Will be filled by #165's full supervisor
                    "health": entry.get("health", "STALLED"),
                    "last_log_line": None,
                    "pid": entry.get("pid"),
                    "terminal_tool": entry.get("terminal_tool"),
                    "terminal_reason": entry.get("terminal_reason"),
                }
            digest = _build_attention_digest(
                self.paths.state_file,
                health_transitions,
                repo=self.repo_root.name,
            )
            if digest:
                emit_digest(self._layout.notify, digest)

        # Emit dispatch-alert digest for live-worker redispatch averted outcomes.
        # This surfaces the silent-stall class of dispatch failures in the same
        # attention pipeline used for stalled workers (issue #506 / #497).
        if dispatch_alert_transitions and self.config.notify.enabled:
            dispatch_digest = _build_attention_digest(
                self.paths.state_file,
                dispatch_alert_transitions,
                repo=self.repo_root.name,
                state_field="dispatch_alert",
            )
            if dispatch_digest:
                emit_digest(self._layout.notify, dispatch_digest)

        return CommandResult(
            not failed_issue_numbers,
            message,
            data,
        )

    def _enrich_checks_infra_blocked(
        self, checks: list[dict[str, Any]] | None, required: tuple[str, ...]
    ) -> list[dict[str, Any]]:
        """Reclassify FAILURE required checks as ``INFRA_BLOCKED`` at the
        check-ingestion data boundary (issue #1383).

        Single point of enforcement for the infra_blocked classification: a
        required check whose FAILED job shows structural evidence of a
        non-started job (zero non-setup steps / instant-fail) or a
        config-listed billing annotation is rewritten to the
        ``INFRA_BLOCKED`` marker state before ``summarize_checks`` (and
        therefore the janitor gate / rework-routing decision) ever sees it.
        ``summarize_checks`` then routes it to ``CheckSummary.infra_blocked``
        rather than ``failed``, so it never enters the "required checks
        failed -> dispatch rework" path and never burns a rework attempt.

        Kept as an OrchestratorApp method (not a pure function in
        ``checks.py``) because the structural + annotation signals require
        two ``gh`` API calls per FAILURE check (``actions_job`` /
        ``check_run_annotations``) -- I/O that the pure
        ``summarize_checks``/``is_infra_blocked_check`` layer must not
        perform. Both API methods return safe empty values (``None`` / ``[]``)
        on any GitHub failure and never raise, so an unenrichable check
        degrades to ordinary ``failed`` routing rather than crashing
        ingestion -- mirroring the existing ``merge_ready`` enrichment this
        replaces.

        Called before the janitor gate in ``review()`` (the rework-routing
        path) and in ``merge_ready()`` (the merge-execution path) so both
        paths classify budget-failed checks identically.
        """
        if not checks or not required:
            return list(checks or [])
        cfg = self.config.auto_merge.infra_blocked
        if not cfg.enabled:
            return list(checks)
        required_set = set(required)
        enriched: list[dict[str, Any]] = []
        for check in checks:
            name = str(check.get("name") or "")
            if name in required_set and str(check.get("state") or "").upper() == "FAILURE":
                check_run_id = check.get("databaseId")
                if isinstance(check_run_id, int):
                    job = self.gh.actions_job(check_run_id)
                    annotations = self.gh.check_run_annotations(check_run_id)
                    if job is not None and is_infra_blocked_check(job, annotations, cfg):
                        check = {**check, "state": "INFRA_BLOCKED"}
            enriched.append(check)
        return enriched

    @_guard_state_lock
    def review(
        self,
        pr_number: int,
        *,
        cross_family: bool | None = None,
        enforce_regen_budget: bool = True,
    ) -> CommandResult:
        """Generate a review packet for a PR.

        ``enforce_regen_budget`` gates the per-head cross-family regeneration
        bound (issue #1099). It defaults to True -- the automated behaviour --
        so a caller added later inherits the bound instead of silently escaping
        it; the operator CLI (`charlie why-charlie-hate`) is the one caller that
        passes False. A human typing a command is not a loop, so the starvation
        the bound defends against (#1078) does not apply, and RUNBOOK.md's
        recovery procedure depends on that manual re-run getting a fresh attempt
        without hand-editing ``state.json``.

        When config.test_adequacy.enabled, this method may itself issue a
        request_changes verdict and advance/terminate the rework loop (previously
        only record_review/verdict did this). When disabled (default), the method
        never mutates decision state and always returns a packet.

        Args:
            pr_number: The PR number to review.
            cross_family: Whether to enable cross-family review (optional).

        Returns:
            CommandResult with ok=True if a packet was generated, or ok=False if
            the review was blocked (janitor gate, test-adequacy gate) or the PR
            was not found. Two ok=True returns carry NO packet and callers that
            gate a status->"reviewing" flip on ``ok`` must additionally exclude
            them via the data flags: ``routed_to_rework`` (the janitor-gate
            conflict/no-op-rework route re-requests rework with no packet) and
            ``closed_unmerged_converged`` (issue #558: a CLOSED-unmerged PR is
            converged to state status "closed" at the janitor gate -- the PR is
            dead, not a fresh-packet candidate). See
            ``_route_rework_candidate_to_review`` and the dead-worker orphan
            sweep for the canonical gating pattern.
        """
        pr = self.gh.pr_view(pr_number)
        if not pr:
            return CommandResult(False, f"PR #{pr_number} was not found", {})
        issue_number = linked_issue_number(
            pr,
            is_cross_repository=pr.get("isCrossRepository"),
            branch_prefix=self.config.dispatch.branch_prefix,
        )

        # Issue #617: dry-run must short-circuit before the escalation check,
        # the packet writes (pr.json, checks.json, diff.patch, review-prompt.md,
        # review-decision.json), and the rework-budget counter resets
        # (review_dispatch_attempt_count=0, no_op_rework_attempts=0,
        # status="reviewing") -- all of which mutate state.json or packet files
        # and were reachable because review() had no top-level dry_run gate (the
        # flag only reached the nested _cross_family_for_pr call). Mirror
        # _dispatch_impl's top-of-function dry-run short-circuit: return the
        # computed plan, touch nothing. A preview that overwrites a terminal
        # verdict with "pending" or silently extends a PR's retry budget is
        # worse than the bug it replaces, so this gate is a single early return
        # before any branch that has an escalation or state-write arm.
        if self.dry_run:
            return CommandResult(
                True,
                f"dry-run: would generate review packet for PR #{pr_number}",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "dry_run": True,
                    "checks_unavailable": False,
                },
            )

        # Escalation is terminal: once a PR or its linked issue is marked
        # escalated, no further review packet generation or label transitions should
        # occur until a human explicitly de-escalates. This prevents a later loop()
        # pass from clobbering the agent:human-needed label with a review_started
        # transition (issue #384), and it protects PRs that have no resolvable linked
        # issue (cross-repo/fork PRs or branches outside the configured prefix) from
        # falling through to the janitor gate and losing their escalated marker.
        state = load_state_locked(self.paths.state_file)
        pr_state = state.get("prs", {}).get(str(pr_number), {})
        issue_state = (
            state.get("issues", {}).get(str(issue_number), {})
            if issue_number is not None
            else None
        )
        pr_escalated, issue_escalated = _escalation_flags(pr_state, issue_state)
        if pr_escalated or issue_escalated:
            reason = (
                f"issue #{issue_number} is escalated; review skipped"
                if issue_number is not None and issue_escalated
                else f"PR #{pr_number} is escalated; review skipped"
            )
            # Refresh (but never act on) janitor diagnostics while escalated.
            # PRs #1397/#1443 (job-cannon, 2026-07-27) sat with janitor_ok/
            # janitor_failures frozen at hours-stale values because this early
            # return prevented run_janitor from ever re-running once the
            # LINKED ISSUE escalated -- caused there by an unrelated dead
            # rework-worker session, not by the janitor's own verdict. A
            # since-cleared merge conflict or a since-green CI run stayed
            # reported as failing until an operator ran unescalate(), because
            # nothing else re-observes reality for an escalated PR.
            # Escalation must stay terminal for every side effect --status,
            # labels, routing, attempt counters-- only unescalate() may re-arm
            # those (see its docstring) -- so this recomputes janitor_ok/
            # janitor_failures for visibility ONLY, reusing the same
            # dedup'd write/event pattern the janitor gate itself uses
            # (cost-spirals.md Finding 2) so an unrepaired PR doesn't
            # re-log identical failures every pass while escalated either.
            escalated_checks = self.gh.pr_checks(pr_number)
            escalated_diff = self.gh.pr_diff(pr_number)
            escalated_verdict = None
            known_ci_run_never_created_head = None
            with state_lock(self.paths.state_file):
                fresh_state = load_state(self.paths.state_file)
                existing_pr_state = fresh_state["prs"].get(str(pr_number))
                if existing_pr_state is not None:
                    known_ci_run_never_created_head = existing_pr_state.get(
                        "ci_run_never_created_head"
                    )
                    escalated_verdict = run_janitor(
                        pr,
                        escalated_checks,
                        self.config,
                        pr_state=existing_pr_state,
                        repo_root=self.repo_root,
                        pr_diff=escalated_diff,
                        review_decision=self._review_decision(pr_number),
                    )
                    failures_changed = existing_pr_state.get("janitor_failures") != list(
                        escalated_verdict.failures
                    )
                    fresh_state["prs"][str(pr_number)] = {
                        **existing_pr_state,
                        "janitor_ok": escalated_verdict.ok,
                        "janitor_failures": list(escalated_verdict.failures),
                        "is_missing_checks_only_block": escalated_verdict.is_missing_checks_only_block,
                    }
                    if failures_changed:
                        fresh_state = self._record_event(
                            fresh_state,
                            "janitor_gate",
                            {
                                "pr_number": pr_number,
                                "failures": list(escalated_verdict.failures),
                                "escalated": True,
                            },
                        )
                    save_state(self.paths.state_file, fresh_state)

            # job-cannon 2026-08-06/07: GitHub Actions silently created no
            # workflow run for pushed heads; detection added so the janitor
            # gate distinguishes "CI never started" from "CI failed". An
            # escalated PR returns from this early branch before the
            # non-escalated janitor-gate block below ever runs -- and a PR
            # stuck 4+ days behind a missing-checks failure (the exact
            # condition this detects) is itself a strong escalation
            # candidate, so the detector must be reachable from here too, not
            # only the non-escalated path. Deliberately called OUTSIDE the
            # state_lock above: it makes a `gh api` call, and the state lock
            # must never span external I/O (mopup-rate-limit-lock-contention)
            # -- a stalled/rate-limited call would otherwise hold the lock
            # against every other writer. `known_ci_run_never_created_head`
            # short-circuits the call once this exact head has already been
            # recorded, so a PR that stays escalated for days doesn't re-query
            # Actions every single pass forever.
            ci_run_never_created_head_sha = None
            if escalated_verdict is not None:
                ci_run_never_created_head_sha = self._detect_ci_run_never_created(
                    pr,
                    escalated_verdict,
                    known_head=known_ci_run_never_created_head,
                )
            # `escalated_verdict is not None` is runtime-redundant here (the
            # only way ci_run_never_created_head_sha is non-None is if it was
            # set above and that branch requires escalated_verdict to be set
            # too) but Pyright's narrowing doesn't carry across the two `if`
            # blocks, so escalated_verdict.missing_required_checks below reads
            # as reportOptionalMemberAccess without it. Spelling out the
            # correlation documents why the two are never non-None one
            # without the other.
            if ci_run_never_created_head_sha is not None and escalated_verdict is not None:
                with state_lock(self.paths.state_file):
                    fresh_state = load_state(self.paths.state_file)
                    existing_pr_state = fresh_state["prs"].get(str(pr_number))
                    if existing_pr_state is not None and (
                        existing_pr_state.get("ci_run_never_created_head")
                        != ci_run_never_created_head_sha
                    ):
                        fresh_state["prs"][str(pr_number)] = {
                            **existing_pr_state,
                            "ci_run_never_created_head": ci_run_never_created_head_sha,
                        }
                        fresh_state = self._record_event(
                            fresh_state,
                            "ci_run_never_created",
                            {
                                "pr_number": pr_number,
                                "issue_number": issue_number,
                                "head_sha": ci_run_never_created_head_sha,
                                "branch": pr.get("headRefName"),
                                "missing_checks": list(escalated_verdict.missing_required_checks),
                                "escalated": True,
                            },
                        )
                        save_state(self.paths.state_file, fresh_state)

            # Issue #776: escalation must stay terminal for the reason that
            # caused it, but must not become a one-way door that ALSO blocks
            # an unrelated, independently-capped remediation -- e.g. a dead
            # request-changes-fix worker exhausting the unrelated watchdog
            # redispatch cap used to permanently wall off a PR that
            # separately developed a merge conflict, with no path back short
            # of a human running `charlie unescalate` (real corpus: issues
            # #592/#648/#606). A merge-conflict or no-op-rework janitor
            # failure is routed through the SAME attempts_key-capped wrapper
            # the non-escalated janitor gate below uses
            # (_route_janitor_gate_failure_to_rework); that wrapper's own
            # rework_pending check does not treat "escalated" as in-flight,
            # so it re-derives its own dispatch/escalate decision from
            # conflict_rework_attempts/no_op_rework_attempts -- a cap that is
            # untouched by (and therefore still fresh after) an escalation
            # from a different lane, but already exhausted -- so still
            # correctly refused -- if THIS lane is what escalated the issue
            # previously. This never re-litigates the original verdict or
            # reason for escalation: only these two deterministic,
            # zero-token checks are attempted here; packet generation and the
            # LLM reviewer remain skipped below.
            if issue_number is not None and escalated_verdict is not None:
                is_merge_conflict_block = str(
                    pr.get("mergeable") or ""
                ).upper() == "CONFLICTING" or (
                    str(pr.get("mergeStateStatus") or "").upper() == "DIRTY"
                )
                # Issue #1111: mirror the non-escalated path's stale-CI-verdict
                # suppression — a request_changes verdict citing only required
                # checks that are green now must not burn no_op_rework_attempts
                # (the predicate itself refuses escalated decisions, so this is
                # a no-op for verdicts recorded as escalated).
                escalated_stale_ci = False
                if (
                    escalated_verdict.is_no_op_rework
                    and not escalated_verdict.failed_required_checks
                ):
                    required = self.config.auto_merge.required_checks
                    escalated_stale_ci = (
                        bool(required)
                        and escalated_checks is not None
                        and is_stale_ci_verdict(
                            self._review_decision(pr_number),
                            summarize_checks(escalated_checks, required),
                        )
                    )
                is_no_op_rework_block = (
                    escalated_verdict.is_no_op_rework
                    and not escalated_verdict.failed_required_checks
                    and not escalated_stale_ci
                )
                if is_merge_conflict_block or is_no_op_rework_block:
                    if is_merge_conflict_block:
                        routed = self._route_janitor_gate_failure_to_rework(
                            pr,
                            issue_number,
                            attempts_key="conflict_rework_attempts",
                            max_attempts=self.config.review.max_conflict_rework_attempts,
                            reason="merge_conflict",
                            router=self._request_merge_conflict_rework,
                        )
                    else:
                        routed = self._route_janitor_gate_failure_to_rework(
                            pr,
                            issue_number,
                            attempts_key="no_op_rework_attempts",
                            max_attempts=self.config.review.max_no_op_rework_attempts,
                            reason="no_op_rework",
                            router=self._request_no_op_rework_repair,
                        )
                    if routed is not None:
                        return routed

            return CommandResult(
                True,
                reason,
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "pass_skipped": True,
                    "checks_unavailable": escalated_checks is None,
                },
            )

        issue = self.gh.issue_view(issue_number) if issue_number is not None else {}
        checks = self.gh.pr_checks(pr_number)
        # Issue #1383: reclassify fleet-wide infra failures (Actions budget /
        # runner outage) as INFRA_BLOCKED at the data boundary, BEFORE the
        # janitor gate / rework-routing decision. A budget-failed check has a
        # FAILURE conclusion (not CANCELLED/INFRA_FAILURE), so without this
        # enrichment it lands in summary.failed and is routed to rework --
        # burning no-op rework caps on a healthy PR. Enriching here is the
        # single point of enforcement; the janitor and merge_ready both see
        # the reclassified checks.
        checks_unavailable = checks is None
        if not checks_unavailable:
            checks = self._enrich_checks_infra_blocked(
                checks, self.config.auto_merge.required_checks
            )

        # Load PR state for no-op rework detection (only if PR has verdict history)
        pr_state = None
        if str(pr_number) in state.get("prs", {}):
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                pr_state = state["prs"].get(str(pr_number), {})

        # Fetch diff for patch-id based no-op rework detection (issue #222)
        # This is needed before the janitor gate to detect actual content changes
        diff = self.gh.pr_diff(pr_number)

        # Deterministic janitor gate BEFORE any packet/cross-family spend: an
        # obviously-not-ready PR (draft, conflicting, red CI, no issue link)
        # must cost zero review tokens. Most failures don't move labels — they
        # are the worker's/CI's to fix. A definitive required-check failure on
        # a linked-issue PR is routed to rework so the worker can push a fix.
        verdict = run_janitor(
            pr,
            checks,
            self.config,
            pr_state=pr_state,
            repo_root=self.repo_root,
            pr_diff=diff,
            review_decision=self._review_decision(pr_number),
        )

        # Issue #1116: the stale-CI skip let a reworked-but-unchanged PR
        # through the gate it was permanently wedged behind. Record it so the
        # packet-rebuild -> fresh-review sequence that follows is attributable
        # to the skip rather than looking like a spontaneous unblock. Dedup on
        # the head sha (mirroring the failures_changed / draft_hold_reason
        # pattern elsewhere in this function): the gate re-passes on every
        # poll while the PR waits on review-dispatch capacity, and only the
        # first pass per head is signal (cost-spirals.md Finding 2).
        if verdict.ok and verdict.no_op_check_skipped_stale_ci and not self.dry_run:
            gate_pass_head = str(pr.get("headRefOid") or "") or None
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                existing_pr_state = state["prs"].get(str(pr_number), {})
                if existing_pr_state.get("stale_ci_gate_pass_head") != gate_pass_head:
                    state["prs"][str(pr_number)] = {
                        **existing_pr_state,
                        "stale_ci_gate_pass_head": gate_pass_head,
                    }
                    state = self._record_event(
                        state,
                        "stale_ci_verdict_gate_pass",
                        {"pr_number": pr_number, "head_sha": gate_pass_head},
                    )
                    save_state(self.paths.state_file, state)

        # Issue #820: reconcile the operator merge-hold marker for the #818
        # draft-auto-ready actuator unconditionally, on every review() pass
        # for this PR -- not only when we're about to act on it below --
        # so the stored reason can never go stale from a *different*
        # branch (packet success further down, a co-occurring second
        # failure routed to the general janitor_blocked path, a merge-
        # conflict/no-op-rework/flake-rerun branch, ...) that doesn't
        # revisit the held branch and therefore wouldn't otherwise touch
        # this field. A marker only cleared by its own branch needs a
        # clear-site at every other exit from review() -- miss one and the
        # dedup below silently stops re-firing after a lift/re-park cycle
        # that passed through one of those other branches in between.
        # Reconciling here once, unconditionally, is the single point of
        # truth instead.
        #
        # Semantics mirror merge_ready's mergequeue-handoff hold check:
        # PR-label-or-issue-label, with an unavailable/degraded check
        # failing safe (treated the same as "held", never as "no hold").
        # `issue` was already fetched unconditionally above for packet
        # building, so this adds no extra `gh` calls.
        merge_hold = self.config.labels.merge_hold in label_names(pr)
        merge_hold_check_unavailable = False
        if not merge_hold and issue_number is not None:
            if not isinstance(issue, dict) or "labels" not in issue:
                merge_hold_check_unavailable = True
            else:
                merge_hold = self.config.labels.merge_hold in label_names(issue)
        draft_hold_reason = (
            ("operator_merge_hold" if merge_hold else "merge_hold_check_unavailable")
            if verdict.is_draft_only_block and (merge_hold or merge_hold_check_unavailable)
            else None
        )
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            existing_pr_state = state["prs"].get(str(pr_number), {})
            draft_hold_reason_changed = (
                existing_pr_state.get("draft_ready_held_reason") != draft_hold_reason
            )
            if draft_hold_reason_changed:
                state["prs"][str(pr_number)] = {
                    **existing_pr_state,
                    "draft_ready_held_reason": draft_hold_reason,
                }
                save_state(self.paths.state_file, state)

        if not verdict.ok:
            # Issue #558: a PR that is CLOSED (unmerged) on GitHub is dead --
            # every other janitor failure is moot. Converge the state PR
            # entry to "closed" at this boundary (single-point-of-enforcement)
            # so the janitor stops re-fetching and re-evaluating it every
            # pass. The reconcile rule (closed_unmerged_pr_state_converged)
            # is the idempotent backstop for entries the janitor gate never
            # observes (e.g. a PR that closed between passes, or one never
            # routed through review()). MERGED PRs are left to
            # merged_outside_orchestrator's reconcile rule. The linked
            # issue's disposition is left to the existing closed-unmerged
            # issue-side handling.
            if str(pr.get("state") or "").upper() == "CLOSED":
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    existing_pr_state = state["prs"].get(str(pr_number), {})
                    if existing_pr_state.get("status") != "closed":
                        state["prs"][str(pr_number)] = {
                            **without_review_dispatch_claim(existing_pr_state),
                            "number": pr_number,
                            "issue_number": issue_number,
                            "status": "closed",
                        }
                        state = self._record_event(
                            state,
                            "closed_unmerged_pr_state_converged",
                            {"pr_number": pr_number, "issue_number": issue_number},
                        )
                        save_state(self.paths.state_file, state)
                return CommandResult(
                    True,
                    f"PR #{pr_number} is CLOSED (unmerged) on GitHub; "
                    f"converged state status to 'closed'",
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "closed_unmerged_converged": True,
                    },
                )

            # Auto-ready otherwise-mergeable draft PRs (issue #818): a draft
            # is an externally-imposed state like any other the fleet
            # reconciles (base movement, flaky checks, ...). When draft is
            # the ONLY janitor failure -- every other gate already passed --
            # call `gh pr ready` and defer the actual review to the next
            # poll, mirroring the flake-rerun debounce below: trigger a
            # cheap, idempotent, self-correcting actuator rather than
            # mutating this frozen verdict and continuing same-pass. Errors
            # come back as values (GitHubRunResult.ok/.error), never
            # exceptions, so a failed `gh pr ready` must NOT be treated as
            # success -- the PR stays janitor_blocked and is not routed
            # toward merge.
            if verdict.is_draft_only_block:
                # Issue #820: an operator can park a PR by drafting it, which
                # is indistinguishable from the externally-imposed draft state
                # #818 was written to auto-clear. `draft_hold_reason` /
                # `draft_hold_reason_changed` were already computed and
                # reconciled into state unconditionally above (single point
                # of truth -- see the comment there for why a branch-local
                # clear was insufficient); this only decides whether to act
                # on the already-current value.
                if draft_hold_reason is not None:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        existing_pr_state = state["prs"].get(str(pr_number), {})
                        state["prs"][str(pr_number)] = {
                            **existing_pr_state,
                            "number": pr_number,
                            "issue_number": issue_number,
                            "status": "janitor_blocked",
                            "janitor_ok": False,
                            "janitor_failures": list(verdict.failures),
                            "is_missing_checks_only_block": verdict.is_missing_checks_only_block,
                        }
                        if draft_hold_reason_changed:
                            state = self._record_event(
                                state,
                                "draft_pr_ready_held",
                                {
                                    "pr_number": pr_number,
                                    "issue_number": issue_number,
                                    "reason": draft_hold_reason,
                                },
                            )
                        save_state(self.paths.state_file, state)
                    return CommandResult(
                        False,
                        f"PR #{pr_number} is a draft; auto-ready held ({draft_hold_reason})",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "draft_ready_held": True,
                            "draft_ready_held_reason": draft_hold_reason,
                            "checks_unavailable": checks is None,
                        },
                    )

                ready_result = self.gh.pr_ready(pr_number)
                if ready_result.ok:
                    log_event(
                        self.paths.state_file,
                        "draft_pr_ready_triggered",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "head_sha": pr.get("headRefOid"),
                        },
                        repo=self.repo_root.name,
                    )
                    return CommandResult(
                        False,
                        f"PR #{pr_number} was a draft; marked ready for review "
                        "(deferring to next pass)",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "draft_readied": True,
                            "checks_unavailable": checks is None,
                        },
                    )
                # `gh pr ready` failed: park as janitor_blocked (same as the
                # pre-fix behavior) plus a dedicated error field so repeated
                # identical failures dedupe instead of re-firing the event
                # every pass -- the underlying `verdict.failures` is constant
                # ("PR is a draft") regardless of the actuator's outcome, so
                # the existing failures_changed dedup below would never fire
                # on its own for this class of park.
                draft_ready_error = (
                    ready_result.error or f"gh pr ready exited {ready_result.returncode}"
                )
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    existing_pr_state = state["prs"].get(str(pr_number), {})
                    error_changed = existing_pr_state.get("draft_ready_error") != draft_ready_error
                    state["prs"][str(pr_number)] = {
                        **existing_pr_state,
                        "number": pr_number,
                        "issue_number": issue_number,
                        "status": "janitor_blocked",
                        "janitor_ok": False,
                        "janitor_failures": list(verdict.failures),
                        "draft_ready_error": draft_ready_error,
                        "is_missing_checks_only_block": verdict.is_missing_checks_only_block,
                    }
                    if error_changed:
                        state = append_event(
                            state,
                            "draft_pr_ready_failed",
                            {
                                "pr_number": pr_number,
                                "issue_number": issue_number,
                                "error": draft_ready_error,
                            },
                            state_path=self.paths.state_file,
                        )
                    save_state(self.paths.state_file, state)
                return CommandResult(
                    False,
                    f"PR #{pr_number} is a draft and `gh pr ready` failed: {draft_ready_error}",
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "draft_ready_failed": True,
                        "checks_unavailable": checks is None,
                    },
                )

            # Flake-aware debounce (issue #391): if the only blocker is a failed
            # required check and we have not yet retried the Actions run for this
            # head, trigger one automatic `gh run rerun --failed` and defer rework
            # routing until the next poll. Any rerun-API error is surfaced as an
            # event and we fall through to the existing rework/janitor-block path.
            if verdict.rerun_run_ids:
                rerun_errors: list[str] = []
                triggered_run_ids: list[int] = []
                for run_id in verdict.rerun_run_ids:
                    result = self.gh.run(
                        ["run", "rerun", str(run_id), "--failed"], allow_failure=True
                    )
                    if isinstance(result, GitHubRunResult):
                        if result.ok:
                            triggered_run_ids.append(run_id)
                        else:
                            rerun_errors.append(
                                result.error or f"gh run rerun {run_id} exited {result.returncode}"
                            )
                    elif isinstance(result, str):
                        # Dry-run returns a descriptive string; treat as success.
                        triggered_run_ids.append(run_id)
                    else:
                        rerun_errors.append(
                            f"unexpected result from gh run rerun {run_id}: {result!r}"
                        )

                if triggered_run_ids and not rerun_errors:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state["prs"][str(pr_number)] = {
                            **state["prs"].get(str(pr_number), {}),
                            "number": pr_number,
                            "issue_number": issue_number,
                            "check_rerun_attempts": verdict.check_rerun_attempts,
                        }
                        state = append_event(
                            state,
                            # event-consumer: audit-only -- records a successfully-triggered
                            # rerun (the action already happened); flake_rerun_failed/escalated
                            # are the actionable siblings and are separately consumed
                            "flake_rerun_triggered",
                            {
                                "pr_number": pr_number,
                                "run_ids": triggered_run_ids,
                                "head_sha": pr.get("headRefOid"),
                            },
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, state)
                    return CommandResult(
                        False,
                        f"flake rerun triggered for PR #{pr_number}: run(s) "
                        + ", ".join(str(rid) for rid in triggered_run_ids),
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "rerun_run_ids": triggered_run_ids,
                            "checks_unavailable": checks is None,
                        },
                    )

                # Rerun API error: record it, but do not consume the attempt.
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state = append_event(
                        state,
                        "flake_rerun_failed",
                        {
                            "pr_number": pr_number,
                            "run_ids": list(verdict.rerun_run_ids),
                            "errors": rerun_errors,
                        },
                        state_path=self.paths.state_file,
                    )
                    save_state(self.paths.state_file, state)

                # Issue #992: a refusal because the containing run is still in
                # progress is a retry-later signal, not a reason to route the
                # PR to rework. The attempt stays unconsumed (we did not write
                # check_rerun_attempts above), so a later pass can retry once
                # the run completes.
                if (
                    not triggered_run_ids
                    and rerun_errors
                    and all(_is_rerun_already_running_error(e) for e in rerun_errors)
                ):
                    return CommandResult(
                        False,
                        f"flake rerun for PR #{pr_number} refused: "
                        + "workflow run(s) still in progress",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "rerun_run_ids": list(verdict.rerun_run_ids),
                            "rerun_errors": rerun_errors,
                            "already_running": True,
                            "checks_unavailable": checks is None,
                        },
                    )

            # Infra-failure auto-rerun + escalation (issue #841): a job-level
            # `timeout-minutes` kill on this repo's self-hosted runners reports
            # CANCELLED (not TIMED_OUT), which summarize_checks correctly
            # buckets into infra_failed (blocks merge via CheckSummary.ready),
            # but nothing before this retried or escalated it --
            # classify_check_failures only iterates summary.failed (a code push
            # can't fix an infra kill), so an infra-failed PR sat blocked
            # forever behind only a diagnostic merge_failed_attempt_alarm
            # event. `gh run rerun RUN_ID` is dispatched WITHOUT --failed: the
            # job never completed (cancelled/timed out, not failed), so
            # --failed's "rerun the failed jobs in this run" semantics do not
            # apply -- omitting it reruns the whole run, which is the correct
            # behavior for a run that never produced a completed job to target.
            if verdict.infra_rerun_run_ids:
                infra_rerun_errors: list[str] = []
                infra_triggered_run_ids: list[int] = []
                for run_id in verdict.infra_rerun_run_ids:
                    result = self.gh.run(["run", "rerun", str(run_id)], allow_failure=True)
                    if isinstance(result, GitHubRunResult):
                        if result.ok:
                            infra_triggered_run_ids.append(run_id)
                        else:
                            infra_rerun_errors.append(
                                result.error or f"gh run rerun {run_id} exited {result.returncode}"
                            )
                    elif isinstance(result, str):
                        # Dry-run returns a descriptive string; treat as success.
                        infra_triggered_run_ids.append(run_id)
                    else:
                        infra_rerun_errors.append(
                            f"unexpected result from gh run rerun {run_id}: {result!r}"
                        )

                if infra_triggered_run_ids and not infra_rerun_errors:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state["prs"][str(pr_number)] = {
                            **state["prs"].get(str(pr_number), {}),
                            "number": pr_number,
                            "issue_number": issue_number,
                            "infra_rerun_attempts": verdict.infra_rerun_attempts,
                        }
                        state = append_event(
                            state,
                            "infra_rerun_triggered",
                            {
                                "pr_number": pr_number,
                                "run_ids": infra_triggered_run_ids,
                                "head_sha": pr.get("headRefOid"),
                            },
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, state)
                    return CommandResult(
                        False,
                        f"infra rerun triggered for PR #{pr_number}: run(s) "
                        + ", ".join(str(rid) for rid in infra_triggered_run_ids),
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "infra_rerun_run_ids": infra_triggered_run_ids,
                            "checks_unavailable": checks is None,
                        },
                    )

                # Rerun API error: record it, but do not consume the attempt.
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state = append_event(
                        state,
                        "infra_rerun_failed",
                        {
                            "pr_number": pr_number,
                            "run_ids": list(verdict.infra_rerun_run_ids),
                            "errors": infra_rerun_errors,
                        },
                        state_path=self.paths.state_file,
                    )
                    save_state(self.paths.state_file, state)

            if (
                issue_number is not None
                and verdict.is_infra_failure_block
                and verdict.infra_definitive_failed
            ):
                # Attempt cap exhausted (or no parseable run id at all): there
                # is no code-fix rework path for an infra failure, so escalate
                # straight to a human instead of looping forever on a PR that
                # can never clear the gate on its own -- this is the bug
                # issue #841 fixes (previously: a diagnostic
                # merge_failed_attempt_alarm event and nothing else).
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="infra_rerun_cap_exceeded",
                        reason_class="mechanical",
                        pr_number=pr_number,
                        pr_extra={"infra_rerun_attempts": verdict.infra_rerun_attempts},
                    )
                    state = append_event(
                        state,
                        "infra_rerun_escalated",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "checks": list(verdict.infra_definitive_failed),
                        },
                        state_path=self.paths.state_file,
                    )
                    save_state(self.paths.state_file, state)
                edge = _escalation_edge("escalated", "mechanical")
                result = transition(self.gh, self.config.labels, issue_number, edge)
                label_error = None
                if result.outcome != TransitionOutcome.APPLIED:
                    label_error = {
                        "edge": edge,
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    }
                return CommandResult(
                    False,
                    f"PR #{pr_number} infra-failed check(s) exhausted rerun cap: "
                    + ", ".join(verdict.infra_definitive_failed),
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "infra_escalated": True,
                        "label_error": label_error,
                    },
                )

            # Issue #1383: infra_blocked required checks (fleet-wide Actions
            # budget/runner outage) are held without dispatching rework and
            # without burning rework/no-op attempt counters. The PR is not
            # transitioned to review_started (there is nothing for the worker
            # to fix), no request_changes verdict is recorded, and the
            # check-failure rework route below is skipped entirely. A distinct
            # ``check_infra_blocked`` warning event is emitted per affected PR
            # so the heartbeat consumer (AC4) and the cross-pass escalation
            # tracker can see it. The operator-facing
            # ``infra_blocked_escalated`` error event is emitted at most once
            # per ``escalation_window_minutes`` window across ALL affected PRs
            # (AC3), not once per PR per pass -- tracked in the module-level
            # ``_infra_blocked_window`` dict because the app instance is
            # rebuilt per pass.
            if verdict.is_infra_blocked_block:
                log_event(
                    self.paths.state_file,
                    "check_infra_blocked",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "checks": list(verdict.infra_blocked_checks),
                    },
                    repo=self.repo_root.name,
                    level="warning",
                )
                # Cross-pass persistence tracking + windowed escalation.
                cfg = self.config.auto_merge.infra_blocked
                repo_key = str(self.repo_root)
                window = _infra_blocked_window.setdefault(
                    repo_key,
                    {
                        "consecutive_passes": 0,
                        "last_escalation": None,
                        "last_pass_cid": None,
                    },
                )
                # Issue #1383: increment at most once per loop pass (per
                # correlation_id), not once per infra-blocked PR encountered
                # within review(). Without this gate, N concurrent
                # infra-blocked PRs in one pass would reach
                # persistence_passes=N in a single pass and fire
                # ``infra_blocked_escalated`` immediately, contradicting AC3
                # ("persistence across N passes, not per PR per pass"). The
                # same correlation_id-dedup pattern is used by the
                # reset-on-clear logic in ``_loop_impl``. When no correlation
                # context is active (direct ``review()`` calls outside
                # ``loop()``, e.g. in tests), ``cid`` is None and each call
                # increments -- matching the pre-fix direct-call behavior.
                cid = current_correlation_id()
                if cid is None or window.get("last_pass_cid") != cid:
                    window["consecutive_passes"] = window.get("consecutive_passes", 0) + 1
                    window["last_pass_cid"] = cid
                last_esc = window.get("last_escalation")
                now_dt = datetime.now(UTC)
                should_escalate = window["consecutive_passes"] >= cfg.persistence_passes
                if should_escalate and (
                    last_esc is None
                    or (now_dt - last_esc).total_seconds() >= cfg.escalation_window_minutes * 60
                ):
                    log_event(
                        self.paths.state_file,
                        "infra_blocked_escalated",
                        {
                            "consecutive_passes": window["consecutive_passes"],
                            "persistence_passes": cfg.persistence_passes,
                            "window_minutes": cfg.escalation_window_minutes,
                        },
                        repo=self.repo_root.name,
                        level="error",
                    )
                    window["last_escalation"] = now_dt
                return CommandResult(
                    False,
                    f"PR #{pr_number} infra-blocked (billing/runner outage): "
                    + ", ".join(verdict.infra_blocked_checks),
                    {
                        "infra_blocked": True,
                        "checks": list(verdict.infra_blocked_checks),
                        "checks_unavailable": False,
                    },
                )

            if issue_number is not None and verdict.is_check_failure_block:
                transition(self.gh, self.config.labels, issue_number, "review_started")
                summary = f"CI failed on {', '.join(verdict.failed_required_checks)}; push a fix"
                # Issue #771: name the failure, not just the check. Populated
                # from the failing check run(s)' GitHub annotations when
                # available, falling back to the check's own run link when
                # there are no annotations; degrades all the way to [] only
                # when GitHub gave us neither, in which case record_review's
                # summary-only fallback still renders the message above via
                # _render_required_changes_section.
                required_changes = _required_changes_from_checks(
                    checks, verdict.failed_required_checks, self.gh.check_run_annotations
                )
                # Issue #1258: dedicated provenance for the CI-red
                # short-circuit -- record_review() itself only logs a
                # decision-agnostic "record_review" event, with nothing
                # naming this as the deterministic janitor gate rather than
                # a human/LLM verdict. Additive: the short-circuit's own
                # return/routing above is unchanged.
                log_event(
                    self.paths.state_file,
                    "review_dispatch_skipped_ci_red",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "failed_required_checks": list(verdict.failed_required_checks),
                        "co_occurring_failures": [],
                        "co_occurring": False,
                    },
                    repo=self.repo_root.name,
                )
                return self.record_review(
                    pr_number,
                    "request_changes",
                    summary=summary,
                    reviewed_head=pr.get("headRefOid"),
                    required_changes=required_changes,
                    verdict_provenance="ci_gate_auto_reject",
                )

            # Merge-conflict and no-op-rework janitor failures used to have no
            # remediation path at all: only is_check_failure_block (above)
            # routed to rework, so a conflicting or diff-unchanged PR fell
            # straight through to the janitor_blocked branch below, which has
            # zero readers anywhere in the codebase (pr-lifecycle.md
            # "janitor_blocked zero readers" finding) -- it just re-logged the
            # identical failure every pass, forever (cost-spirals.md Finding
            # 1: ~700 identical events across 5 PRs in a 19h window). Route
            # both into the same rework machinery the check-failure path
            # uses, decision-agnostic -- the existing merge_ready conflict
            # rework route requires an approved decision (a conflicting
            # branch needs a rebase regardless of its review verdict) -- each
            # bounded by its own small attempt cap so a PR whose rework keeps
            # failing to make progress escalates to a human instead of
            # looping forever.
            is_merge_conflict_block = str(pr.get("mergeable") or "").upper() == "CONFLICTING" or (
                str(pr.get("mergeStateStatus") or "").upper() == "DIRTY"
            )
            # Excludes the case where a required check is ALSO still failing:
            # that combination already has an established, deliberate
            # non-routing behavior (test_janitor_required_check_failure_noop_
            # does_not_reroute, issue #376) -- re-requesting a rework whose
            # only signal is "same diff as last time" while CI is still red
            # is not obviously more productive than waiting, and changing
            # that existing invariant is out of this fix's scope. This only
            # newly routes the PURE no-op-rework case (no co-occurring check
            # failure), which previously had no consumer at all.
            #
            # Issue #1111: ALSO excluded is the stale-CI-verdict case — the
            # request_changes verdict's only findings cite required checks
            # that are all green right now (a transient failure the reviewer
            # saw has recovered on the same content). Routing rework there is
            # a guaranteed no-op that burns no_op_rework_attempts toward a
            # manufactured human escalation; review_queue() re-queues the PR
            # for a fresh review instead, so this pass just waits.
            stale_ci_verdict = False
            if verdict.is_no_op_rework and not verdict.failed_required_checks:
                required = self.config.auto_merge.required_checks
                stale_ci_verdict = (
                    bool(required)
                    and checks is not None
                    and is_stale_ci_verdict(
                        self._review_decision(pr_number),
                        summarize_checks(checks, required),
                    )
                )
            is_no_op_rework_block = (
                verdict.is_no_op_rework
                and not verdict.failed_required_checks
                and not stale_ci_verdict
            )
            if issue_number is not None and (is_merge_conflict_block or is_no_op_rework_block):
                if is_merge_conflict_block:
                    routed = self._route_janitor_gate_failure_to_rework(
                        pr,
                        issue_number,
                        attempts_key="conflict_rework_attempts",
                        max_attempts=self.config.review.max_conflict_rework_attempts,
                        reason="merge_conflict",
                        router=self._request_merge_conflict_rework,
                    )
                else:
                    routed = self._route_janitor_gate_failure_to_rework(
                        pr,
                        issue_number,
                        attempts_key="no_op_rework_attempts",
                        max_attempts=self.config.review.max_no_op_rework_attempts,
                        reason="no_op_rework",
                        router=self._request_no_op_rework_repair,
                    )
                if routed is not None:
                    return routed
                # None: a rework for this issue is already pending, so there is
                # nothing to route -- fall through to the janitor_blocked
                # bookkeeping below and wait for the pending cycle.

            # Issue #1258: a required check can fail alongside a janitor
            # failure that is neither the sole failure (is_check_failure_block
            # above already routes that) nor a bare merge conflict (already
            # routed above via _route_janitor_gate_failure_to_rework). That
            # combination used to fall straight through to the passive
            # janitor_blocked bookkeeping below -- neither reviewed nor
            # routed to rework, silently re-logging the same failure set
            # forever (the same "zero readers" dead end issue #765/#776 fixed
            # for the merge-conflict/no-op-rework cases). Route it through
            # the same record_review(request_changes) machinery the
            # sole-failure short-circuit above uses, decision-agnostic, with
            # required_changes/summary naming BOTH the failing check(s) and
            # the co-occurring janitor failure(s) so a rework worker sees the
            # whole picture in one pass.
            #
            # is_merge_conflict_block is excluded: without it, a
            # conflict+red-check PR whose merge-conflict rework is already
            # pending (routed returned None just above) would ALSO get
            # routed through here -- a double-dispatch regression, not a
            # fix.
            #
            # verdict.is_no_op_rework (the raw flag, NOT is_no_op_rework_block)
            # is also excluded, and this exclusion is load-bearing, not
            # redundant with is_no_op_rework_block above: is_no_op_rework_block
            # itself structurally requires `not verdict.failed_required_checks`
            # and so can never be True here -- but the underlying
            # `verdict.is_no_op_rework` flag CAN still be True with a
            # co-occurring required-check failure (same diff pushed again
            # while CI is still red), and that exact combination is
            # test_janitor_required_check_failure_noop_does_not_reroute's
            # issue #376 invariant: re-requesting a rework whose only signal
            # is "same diff as last time" is not productive while CI is
            # still red, and changing that is out of this fix's scope. A
            # PR in that state still stalls in janitor_blocked below after
            # this diff -- an accepted carve-out, not an oversight.
            #
            # verdict.infra_definitive_failed is also excluded: an
            # infra-failed required check (CANCELLED/TIMED_OUT job-level
            # kill, issue #841) co-occurring with a genuine required-check
            # failure has its OWN dedicated remediation path (infra-rerun +
            # escalation, above) that this branch must not shadow or
            # double-dispatch against -- there is no code-fix rework for an
            # infra kill, so routing it through record_review(request_
            # changes) as if a code push could fix it would be a
            # mis-classification, not a fix.
            # test_janitor_mixed_genuine_failure_and_infra_failure_routes_to_rework_not_infra_rerun
            # (issue #847, pre-existing) pins this exact combination falling
            # through to janitor_blocked untouched, unchanged by this diff.
            # infra_definitive_failed is populated here whenever an
            # infra_failed required check co-occurs with a genuine
            # failed_required_checks entry, regardless of whether the infra
            # check's run id is parseable: is_infra_failure_block requires
            # `not failed_required_checks`, so it is always False in that
            # combination, which forces classify_infra_failures'
            # record_attempts=False path -- every infra_failed name lands in
            # definitive_failed (never rerun_run_ids) on this pass. Checking
            # infra_definitive_failed alone is therefore sufficient; it is
            # never empty here while infra_rerun_run_ids is non-empty.
            is_co_occurring_check_failure_block = (
                bool(verdict.failed_required_checks)
                and not verdict.is_check_failure_block
                and not is_merge_conflict_block
                and not verdict.is_no_op_rework
                and not verdict.infra_definitive_failed
            )
            if issue_number is not None and is_co_occurring_check_failure_block:
                transition(self.gh, self.config.labels, issue_number, "review_started")
                # verdict.failures always ends with the "Required check(s)
                # failed: ..." message when failed_required_checks is
                # truthy (janitor.run_janitor appends it last, nothing after
                # it) -- so failures[:-1] is exactly the co-occurring
                # janitor failure text(s), independent of which check(s)
                # _check_body/_check_title_conventional/etc. produced.
                co_occurring_failures = list(verdict.failures[:-1])
                summary = (
                    f"CI failed on {', '.join(verdict.failed_required_checks)}; push a fix. "
                    f"Also blocked by: {'; '.join(co_occurring_failures)}"
                )
                required_changes = (
                    _required_changes_from_checks(
                        checks, verdict.failed_required_checks, self.gh.check_run_annotations
                    )
                    + co_occurring_failures
                )
                log_event(
                    self.paths.state_file,
                    "review_dispatch_skipped_ci_red",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "failed_required_checks": list(verdict.failed_required_checks),
                        "co_occurring_failures": co_occurring_failures,
                        "co_occurring": True,
                    },
                    repo=self.repo_root.name,
                )
                return self.record_review(
                    pr_number,
                    "request_changes",
                    summary=summary,
                    reviewed_head=pr.get("headRefOid"),
                    required_changes=required_changes,
                    verdict_provenance="ci_gate_auto_reject",
                )

            # See _detect_ci_run_never_created for why this check exists
            # (job-cannon measured 11 PRs stuck 4+ days behind an ambiguous
            # "Required check(s) missing" janitor failure). Detection lives
            # entirely in that method; the retrigger policy below (issue
            # #1274, W17) is this method's follow-up.
            ci_run_never_created_head_sha = self._detect_ci_run_never_created(
                pr,
                verdict,
                known_head=(pr_state or {}).get("ci_run_never_created_head"),
            )
            ci_run_never_created = ci_run_never_created_head_sha is not None

            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                existing_pr_state = state["prs"].get(str(pr_number), {})
                # Dedup (cost-spirals.md Finding 2): the janitor gate re-runs
                # every pass and an unrepaired PR produces byte-identical
                # failures for many hours (699 identical events for 5 PRs in
                # a 19h window) -- only log a fresh event when the failure
                # set actually changes from what's already on record.
                failures_changed = existing_pr_state.get("janitor_failures") != list(
                    verdict.failures
                )
                pr_state_update = {
                    **existing_pr_state,
                    "number": pr_number,
                    "issue_number": issue_number,
                    "status": "janitor_blocked",
                    "janitor_ok": False,
                    "janitor_failures": list(verdict.failures),
                    "check_rerun_attempts": verdict.check_rerun_attempts,
                    # Issue #1133: structured flag so _is_dead_blocker can
                    # distinguish the transient "checks not reported yet"
                    # population from durably-stuck janitor_blocked PRs without
                    # parsing failure-message text.
                    "is_missing_checks_only_block": verdict.is_missing_checks_only_block,
                }
                # At most once per (pr, head_sha): only emit when this head
                # hasn't already been flagged as never-created.
                ci_run_never_created_new_head = (
                    ci_run_never_created
                    and existing_pr_state.get("ci_run_never_created_head")
                    != ci_run_never_created_head_sha
                )
                if ci_run_never_created:
                    pr_state_update["ci_run_never_created_head"] = ci_run_never_created_head_sha
                state["prs"][str(pr_number)] = pr_state_update
                if ci_run_never_created_new_head:
                    state = self._record_event(
                        state,
                        "ci_run_never_created",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "head_sha": ci_run_never_created_head_sha,
                            "branch": pr.get("headRefName"),
                            "missing_checks": list(verdict.missing_required_checks),
                        },
                    )
                if failures_changed:
                    # Issue #818: a draft co-occurring with another real
                    # failure (e.g. draft + empty body) is not auto-readied
                    # -- `is_draft_only_block` is False -- but the park is
                    # still worth distinguishing from routine janitor_gate
                    # bookkeeping so it's greppable via
                    # query_events(kind="draft_pr_blocked") rather than a
                    # manual `gh pr list` sweep.
                    event_kind = "draft_pr_blocked" if verdict.is_draft else "janitor_gate"
                    state = self._record_event(
                        state,
                        # event-consumer: pending #1366 -- draft_pr_blocked has no automated
                        # consumer yet, only the query_events(kind=...) grep the comment above
                        # names; janitor_gate (the other branch) is separately consumed
                        event_kind,
                        {"pr_number": pr_number, "failures": list(verdict.failures)},
                    )
                save_state(self.paths.state_file, state)

            # Issue #1274 (W17): follow-up retrigger policy for the detection
            # above. `_detect_ci_run_never_created` dedupes per (pr, head_sha)
            # -- once a head is recorded (`pr_state_update["ci_run_never_created_head"]`
            # just above, which carries forward across passes via its
            # `**existing_pr_state` spread regardless of whether THIS pass's
            # own detector call fired), it returns None on every later pass
            # for that SAME head -- the ordinary steady state (no new
            # commits, checks still absent). Gating retrigger eligibility on
            # this pass's live detector return alone would make the feature
            # inert after its first pass, so read the marker that was just
            # persisted above (which already reflects either this pass's own
            # fresh positive or an earlier pass's) instead. Combine it with
            # the LIVE "still missing" signal (`verdict.missing_required_checks`,
            # recomputed fresh every pass by `run_janitor` regardless of the
            # detector's own dedup) to decide whether a retrigger is in scope
            # at all this pass. Deliberately NOT gated on
            # `is_missing_checks_only_block` (binding comment item 5 on issue
            # #1274): a retriggered run is harmless alongside an unrelated
            # co-occurring janitor failure (merge conflict, empty body, ...)
            # and gives the rework loop real signal -- the three PRs this
            # item exists to fix (#1186/#1192/#1214) all carry a co-occurring
            # failure.
            stale_checks_head_sha = str(pr.get("headRefOid") or "") or None
            stale_checks_retrigger_in_scope = (
                issue_number is not None
                and stale_checks_head_sha is not None
                and pr_state_update.get("ci_run_never_created_head") == stale_checks_head_sha
                and bool(verdict.missing_required_checks)
            )
            if stale_checks_retrigger_in_scope:
                stale_checks_retrigger_result = self._attempt_stale_checks_retrigger(
                    pr,
                    pr_number=pr_number,
                    issue_number=issue_number,
                    head_sha=stale_checks_head_sha,
                    existing_pr_state=pr_state_update,
                )
                if stale_checks_retrigger_result is not None:
                    return stale_checks_retrigger_result

            return CommandResult(
                False,
                f"janitor gate blocked PR #{pr_number}: " + "; ".join(verdict.failures),
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "janitor_ok": False,
                    "janitor_failures": list(verdict.failures),
                    "janitor_warnings": list(verdict.warnings),
                    "checks_unavailable": checks is None,
                },
            )
        pr_dir = self.paths.prs / f"pr-{pr_number}"
        pr_dir.mkdir(parents=True, exist_ok=True)
        # Issue #592: stamp the digest of the resolved review template +
        # referenced section partials into pr.json so a future template edit
        # is detectable as packet staleness alongside a head-SHA change.
        # Without this, a static-head PR keeps being handed a packet rendered
        # from the old template indefinitely -- the orchestrator never
        # regenerates because headRefOid is treated as the packet's only input.
        pr_json = _slim_pr_json(pr)
        pr_json["prompt_template_sha"] = self._review_template_sha()
        # Issue #1439: stamp the structure-aware turn-cap multiplier into the
        # packet so the reviewer launch reads a structure-aware budget instead
        # of the flat ``review_max_turns``. The multiplier (not the absolute
        # cap) is stored so the dispatch path can re-derive the final cap from
        # the live ``review_max_turns`` config + the per-PR miss streak at
        # launch time -- a packet may outlive a config edit, and the base cap
        # is config's to own.
        _max_touched_lines = _max_touched_file_line_count(diff, self.repo_root)
        pr_json["review_turn_cap_structure_multiplier"] = structure_turn_cap_multiplier(
            _max_touched_lines, self.config.review_dispatch
        )
        pr_json["review_turn_cap_max_touched_lines"] = _max_touched_lines
        self._write_json(pr_dir / "pr.json", pr_json)
        self._write_json(pr_dir / "checks.json", checks)
        diff_path = pr_dir / "diff.patch"
        diff_path.write_text(diff, encoding="utf-8")

        # Tier 1 test-adequacy hard gate (issue #179)
        test_adequacy_section = ""
        test_adequacy_verdict = None
        if self.config.test_adequacy.enabled:
            test_adequacy_verdict = check_test_adequacy(diff, pr, self.config.test_adequacy)
            if not test_adequacy_verdict.ok:
                # Same terminal label set as an LLM request_changes:
                # {in_progress} -> review_started -> {in_progress,pr_open,reviewing}
                #               -> rework_requested (inside record_review) -> {in_progress,pr_open,needs_rework}
                if issue_number is not None:
                    transition(self.gh, self.config.labels, issue_number, "review_started")
                summary = render_test_adequacy_summary(
                    test_adequacy_verdict, self.config.test_adequacy.exempt_marker
                )
                return self.record_review(
                    pr_number,
                    "request_changes",
                    summary=summary,
                    reviewed_head=pr.get("headRefOid"),
                    verdict_provenance="test_adequacy_auto_reject",
                )
            # Gate passed while enabled: add Tier-2 packet section (issue #180)
            test_adequacy_section = render_test_adequacy_section(
                test_adequacy_verdict.facts, test_adequacy_verdict.warnings
            )

        # Static diff-coverage / unwired-symbol probe (issues #1260/#1261).
        # Advisory-only, never blocking -- see CoverageProbeConfig's docstring.
        # Computed in the same packet-build phase as the Tier-1/2 test-adequacy
        # gate above, on the same diff text already in hand; no PR-branch
        # checkout is created for this (see diff_coverage_probe module docstring).
        static_probe_section = ""
        if self.config.coverage_probe.enabled:
            static_probe_verdict = run_static_probe(
                diff, self.repo_root, self.config.coverage_probe
            )
            static_probe_section = render_static_probe_section(static_probe_verdict)
            if static_probe_verdict.branch_findings or static_probe_verdict.unwired_findings:
                # These two kinds are the substrate for the 2-week
                # false-positive measurement window -- a flag that isn't
                # logged can't be measured.
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    if static_probe_verdict.branch_findings:
                        state = self._record_event(
                            state,
                            # event-consumer: audit-only -- measurement-window telemetry for the
                            # false-positive rate (see comment above), not consumed downstream by design
                            "coverage_probe_flagged",
                            {
                                "pr_number": pr_number,
                                "issue_number": issue_number,
                                "flagged_files": [
                                    f.filename for f in static_probe_verdict.branch_findings
                                ],
                            },
                            level="warning",
                        )
                    if static_probe_verdict.unwired_findings:
                        state = self._record_event(
                            state,
                            # event-consumer: audit-only -- measurement-window telemetry for the
                            # false-positive rate (see comment above), not consumed downstream by design
                            "unwired_symbol",
                            {
                                "pr_number": pr_number,
                                "issue_number": issue_number,
                                "symbols": [
                                    f.symbol for f in static_probe_verdict.unwired_findings
                                ],
                            },
                            level="warning",
                        )
                    save_state(self.paths.state_file, state)

        # Run containment check for worker edits leaked into operator checkout
        containment_warnings = check_operator_containment(self.repo_root, diff, pr_number)
        # Merge containment warnings with janitor warnings
        merged_warnings = tuple(list(verdict.warnings) + list(containment_warnings))
        # If test-adequacy gate is enabled and passed, merge its warnings too
        if test_adequacy_verdict is not None:
            merged_warnings = tuple(list(merged_warnings) + list(test_adequacy_verdict.warnings))
        cross_family_section, cf_result = self._cross_family_for_pr(
            pr=pr,
            issue=issue,
            pr_dir=pr_dir,
            pr_number=pr_number,
            issue_number=issue_number,
            diff_path=diff_path,
            enabled=cross_family,
            enforce_regen_budget=enforce_regen_budget,
        )
        # Issue #1078: when the cross-family review is pending (launched async
        # but not yet reaped), the review packet must NOT go out — the cross-
        # family section is empty and the reviewer would make a verdict without
        # the adversarial findings. Defer the packet write to a later pass when
        # the review is reaped. This returns ok=True (not a failure) with a
        # ``cross_family_pending`` data flag so ``loop()`` can skip the
        # not-reached charge and the merge check.
        if cf_result is not None and cf_result.pending:
            return CommandResult(
                True,
                f"PR #{pr_number}: cross-family review pending, deferring packet",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "cross_family_pending": True,
                    "ok": True,
                },
            )
        prompt_path = pr_dir / "review-prompt.md"
        decision_path = pr_dir / "review-decision.json"
        diff_size_section = _diff_size_section(
            diff, self.config.review_dispatch.diff_line_threshold, diff_path
        )
        ci_status_section = _ci_status_section(
            checks, self.config.auto_merge.required_checks, pr_dir / "checks.json"
        )
        # Issue #1445: over-cap file-addition finding. Advisory-only, never
        # blocking -- the rubric line in review.md flags an over-cap addition
        # as a REPORTABLE FINDING and this probe surfaces the concrete files.
        # ``file_size_cap_lines`` of 0 (default) disables the probe: the section
        # renders "" (rubric prose stays present), mirroring the
        # ``coverage_probe.enabled=False`` disabled contract.
        _file_size_cap = self.config.review_dispatch.file_size_cap_lines
        over_cap_section = render_over_cap_section(
            _over_cap_file_findings(diff, self.repo_root, _file_size_cap)
            if _file_size_cap > 0
            else None
        )

        # Issue #1460: attachment-budget review-packet section. Cheap gate
        # first -- most PRs touch neither `.attachment-budgets.json` nor a
        # baselined host file, so the reconstruct/build path below is
        # skipped for them entirely (section renders "").
        attachment_budget_section = self._build_attachment_budget_section(diff, pr_number)

        # Issue #1036: compare-and-swap the head immediately before committing
        # this packet's outputs (prompt + decision). ``pr`` was snapshotted
        # once, at the top of this method, and everything since -- diff
        # fetch, janitor, containment check, cross-family review -- can take
        # minutes (385s observed in production). The stale-verdict reset a
        # few lines below used to compare a recorded verdict's pinned head
        # against that same build-start snapshot with `!=`, which is
        # symmetric and has the wrong sign whenever the SNAPSHOT is the
        # stale side: a verdict recorded mid-build at the genuinely current
        # head was voided because it disagreed with an old snapshot, not
        # because it was actually behind.
        #
        # A directional (ancestry) fix on the reset alone is not enough --
        # verified against this same method's control flow: ``pr`` also
        # feeds ``_build_prior_review_section`` and the ``review.md`` render
        # below, so sparing only the reset would commit a current-head
        # verdict next to a prompt describing an older diff, with nothing in
        # state recording that mismatch. So this re-reads the live head and,
        # if it no longer matches the snapshot (or can't be read at all --
        # fail closed), discards the WHOLE packet: neither the prompt nor
        # the decision reset is written, no label/status transition fires,
        # and the existing verdict (if any) is left exactly as it was. The
        # next pass rebuilds the packet against the then-current head. A
        # verdict pinned to the (unchanged) live head is therefore never
        # touched by this method in the same pass that would otherwise have
        # voided it -- which is what "preserve a verdict pinned to a
        # descendant of the snapshot" reduces to once the snapshot itself is
        # kept fresh at commit time.
        #
        # Issue #1072: this guard covers ONLY the packet-commit tail exit
        # (the prompt + decision write below). The two earlier verdict-
        # writing exits -- the CI-required-check-failure block and the
        # Tier-1 test-adequacy hard gate -- return through record_review()
        # before reaching this point. The same head-moved invariant is now
        # enforced for those exits (and every other record_review() caller)
        # by the compare-and-swap guard pushed into record_review() itself,
        # so the invariant holds by construction for all verdict writes from
        # this method, not just the one this guard happens to sit on.
        live_pr_for_commit = self.gh.pr_view(pr_number)
        live_head_for_commit = live_pr_for_commit.get("headRefOid")
        snapshot_head_for_commit = pr.get("headRefOid")
        if live_head_for_commit is None or live_head_for_commit != snapshot_head_for_commit:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state = self._record_event(
                    state,
                    "review_packet_discarded_head_moved",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "snapshot_head_sha": snapshot_head_for_commit,
                        "live_head_sha": live_head_for_commit,
                    },
                    level="warning",
                )
                save_state(self.paths.state_file, state)
            return CommandResult(
                False,
                f"PR #{pr_number}: head moved during packet build "
                f"({snapshot_head_for_commit} -> {live_head_for_commit!r}); "
                "discarding packet, will rebuild next pass",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "reason": "head_moved_during_build",
                    "snapshot_head_sha": snapshot_head_for_commit,
                    "live_head_sha": live_head_for_commit,
                },
            )

        # Single read of review-decision.json, BEFORE rendering: used to build
        # the round-2 $prior_review_section below. The stale-verdict reset a
        # few lines down re-reads the file inside the state lock (issue #1340:
        # the outside-lock read here may be stale w.r.t. a concurrent
        # record_review, and the reset write must be atomic with the state
        # write). Previously that reset was the only reader, and it ran after
        # the prompt was already rendered — so a prior round's
        # verdict/summary/required_changes were on disk at render time but
        # never surfaced to the reviewer.
        existing_decision = self._review_decision(pr_number)
        prior_reviewed_head_sha = existing_decision.get("reviewed_head_sha")
        # Issue #632 defect 3: a terminal verdict on disk must reach the
        # reviewer even when the head has NOT moved (a PR parked on
        # agent:human-needed, or an operator-corrected verdict). The old gate
        # required prior_reviewed_head_sha != headRefOid, so a same-head
        # re-review rendered an empty $prior_review_section and the corrected
        # findings were invisible. _build_prior_review_section adapts its
        # wording to the same-head vs moved-head case.
        is_round2_review = existing_decision.get("decision") not in (
            "pending",
            None,
            "missing",
        ) and bool(prior_reviewed_head_sha)
        prior_review_section = (
            self._build_prior_review_section(pr_dir, existing_decision, pr.get("headRefOid"))
            if is_round2_review
            else ""
        )

        prompt = self._render(
            "review.md",
            {
                "pr_number": pr_number,
                "pr_title": pr.get("title", ""),
                "pr_url": pr.get("url", ""),
                "issue_number": issue_number or "UNKNOWN",
                "issue_title": issue.get("title", "UNKNOWN"),
                "issue_url": issue.get("url", ""),
                "pr_json_path": pr_dir / "pr.json",
                "diff_path": pr_dir / "diff.patch",
                "cross_family_section": cross_family_section,
                "janitor_section": _janitor_section(merged_warnings),
                "test_adequacy_section": test_adequacy_section,
                "static_probe_section": static_probe_section,
                "diff_size_section": diff_size_section,
                "ci_status_section": ci_status_section,
                "over_cap_section": over_cap_section,
                "attachment_budget_section": attachment_budget_section,
                "prior_review_section": prior_review_section,
            },
        )
        prompt_path.write_text(prompt, encoding="utf-8")
        decision_template = {
            "pr_number": pr_number,
            "issue_number": issue_number,
            "decision": "pending",
            "summary": "",
            "required_changes": [],
            "reviewed_at": None,
            # Issue #1265: an explicit None sentinel, not an omitted key --
            # "pending" is not a verdict yet, so it has no provenance to
            # report, but the key's presence keeps the no-default contract
            # structurally checkable (a bypass writer that forgets the key
            # entirely looks identical to one that never considered it).
            "verdict_provenance": None,
        }
        # Issue #868: review_dispatch.enabled gates whether landing this PR in
        # "reviewing" is safe. Disabled means dispatch_reviews()'s launch+reap
        # machinery never services this state (its own internal gate skips
        # it too), so stamping "reviewing"/agent:reviewing here would strand
        # the PR under a label nothing runs to clear. The packet itself is
        # still written either way — only the state/label transition is
        # gated, so a human can still read the prompt manually.
        dispatch_disabled = not self.config.review_dispatch.enabled
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            # Issue #1351: the dispatch attempt counter is reset only for a
            # genuinely new head, not on every packet write. ``review()`` is
            # called every loop pass for a PR stuck on a stale
            # ``decision``/``reviewed_head_sha`` pair (the ``already_approved``
            # branch with ``head_matches=False``), so an unconditional reset
            # raced with ``dispatch_reviews()``'s claim-time increment and the
            # counter oscillated 1->0->1->0... never reaching
            # ``max_review_dispatch_attempts`` -- the cap was silently inert and
            # reviewers re-dispatched indefinitely with no escalation.
            # ``review_dispatch_attempt_last_head`` baselines the head the
            # current attempt count is counting against, mirroring the
            # ``no_op_rework_attempts_last_head`` /
            # ``conflict_rework_attempts_last_head`` pattern: the counter resets
            # only when the packetized head advances past it.
            _existing_pr_state = state["prs"].get(str(pr_number), {})
            _packet_head = pr.get("headRefOid")
            _prior_attempt_last_head = _existing_pr_state.get("review_dispatch_attempt_last_head")
            _fresh_dispatch_cycle = (
                _prior_attempt_last_head is None or _prior_attempt_last_head != _packet_head
            )
            _preserved_attempt_count = int(
                _existing_pr_state.get("review_dispatch_attempt_count", 0)
            )
            # Issue #1340: the pending-reset decision-file write is inside the
            # state lock, and when a stale-head terminal verdict is voided the
            # state.json ``decision`` field is cleared in the same locked
            # section, so the file and state can never diverge (file "pending"
            # while state carries the stale decision).
            # The ``existing_decision`` read at line ~9429 was outside any lock
            # and may be stale w.r.t. a concurrent record_review; re-read the
            # on-disk decision here, inside the lock. The #1036 compare-and-swap
            # above already proved the PR head is stable, so the only concurrent
            # writer of this file is record_review, which holds this same lock.
            live_decision = self._review_decision(pr_number)
            live_decision_value = live_decision.get("decision")
            live_reviewed_head_sha = live_decision.get("reviewed_head_sha")
            # A verdict is pinned to a specific head. If the PR has moved on,
            # the old verdict is void and must not survive into the new packet.
            # This applies to all terminal decisions (approved, request_changes,
            # blocked), not just approvals: a request_changes on an old head is
            # equally stale when the head has advanced, and carrying forward its
            # summary/required_changes misleads the reviewer into re-issuing the
            # same verdict without examining the new diff.
            #
            # Only a real terminal decision (approved/request_changes/blocked)
            # on disk can be voided. ``_review_decision`` returns
            # ``{"decision": "missing"}`` for both a missing file and a
            # corrupt/unreadable one (issue #1362's ``review_decision``
            # collapses both into one sentinel) -- that is not a terminal
            # verdict, so it never triggers the void path -- the fresh-
            # template write below handles the missing-file case, and a
            # corrupt file is left for a human rather than silently
            # overwritten (mirroring the original code's ``else`` branch,
            # which only reset on a real terminal decision).
            voided_stale_verdict = live_decision_value in (
                "approved",
                "request_changes",
                "blocked",
            ) and (
                live_reviewed_head_sha is None or live_reviewed_head_sha != pr.get("headRefOid")
            )
            if not decision_path.exists() or voided_stale_verdict:
                # Issue #1362 Stage 2: routed through the single writer so the
                # placeholder is head-stamped like every other verdict --
                # ``reviewed_head_sha`` lets a "pending" that is actually
                # pinned to a dead head be told apart from a genuinely
                # unreviewed current head (the mechanism the issue exists
                # for). ``pr`` is the head snapshot already validated
                # unchanged by the compare-and-swap guard above this block.
                # ``archive_round=False``: a pending placeholder is not a
                # reviewer round -- it carries no decision/summary content,
                # so archiving it would mint a content-free round ahead of
                # the first real verdict (and, on the rework path, before
                # every subsequent verdict whenever the head moves and the
                # packet is rebuilt), shifting round numbers and polluting
                # ``_build_prior_review_section``'s rendered history with
                # phantom "Round N (decision: pending)" entries that never
                # came from a reviewer. This is the flat-file head-stamp
                # only; the reader still resolves it correctly since it
                # reads the flat file first.
                record_decision(
                    pr_dir, decision_template, pr.get("headRefOid"), archive_round=False
                )
            # Merge-update, never replace: wholesale assignment here used to erase
            # recorded review decisions on repeated review()/loop() passes
            # (production-confirmed, pr-497).
            state["prs"][str(pr_number)] = {
                **state["prs"].get(str(pr_number), {}),
                "number": pr_number,
                "url": pr.get("url"),
                "issue_number": issue_number,
                "prompt_path": str(prompt_path),
                "decision_path": str(decision_path),
                # Issue #1340: when the decision file was just voided back to
                # "pending" (stale head), mirror that into state.json so the two
                # stores agree on the decision. Without this, state.json
                # retained the stale ``decision`` while the file said
                # "pending" -- a file-trusting consumer (the packet-current skip
                # in loop()) saw "pending" while state-trusting paths acted on
                # the stale verdict. ``reviewed_head_sha`` is intentionally
                # NOT cleared: ``_route_rework_candidate_to_review`` uses it
                # to detect whether ``review()`` recorded a new decision vs.
                # just wrote a fresh pending packet, and clearing it would
                # break that detection (issue #339).
                **({"decision": "pending"} if voided_stale_verdict else {}),
                **({} if dispatch_disabled else {"status": "reviewing"}),
                "janitor_ok": True,
                "janitor_failures": [],
                "is_missing_checks_only_block": False,
                "janitor_warnings": list(merged_warnings),
                "cross_family_report": cf_result.report_path if cf_result else None,
                "cross_family_ok": cf_result.ok if cf_result else None,
                "consecutive_failed_merge_attempts": 0,
                "check_rerun_attempts": verdict.check_rerun_attempts,
                # Issue #1351: reset the dispatch attempt counter only when
                # the packet is for a genuinely new head. Rebuilding the
                # packet for the same head (e.g. a stale already_approved /
                # head_matches=False loop that calls review() every pass) must
                # NOT zero the counter -- otherwise review()'s reset races
                # with dispatch_reviews()'s claim-time increment and
                # max_review_dispatch_attempts never fires. The companion
                # ``review_dispatch_attempt_last_head`` baselines the head the
                # count is against (mirroring no_op/conflict_rework_attempts_
                # last_head); the counter resets only when the head advances.
                "review_dispatch_attempt_count": (
                    0 if _fresh_dispatch_cycle else _preserved_attempt_count
                ),
                "review_dispatch_attempt_last_head": _packet_head,
                # Reset the unreadable-log streak: a new packet is a new
                # review cycle, so a prior persistent-unreadable condition
                # must not carry forward and immediately count against the
                # fresh attempt budget (issue #1069).
                "review_log_unreadable_streak": 0,
                # Issue #1439: reset the turn-limit miss streak on a fresh
                # dispatch cycle (new head). A same-head rebuild must NOT zero
                # it -- mirroring review_dispatch_attempt_count's same-head
                # preservation (issue #1351) -- or the cap-aware backstop
                # never converges and a PR that keeps hitting the turn limit
                # on the same head redispatches forever at the base cap.
                "review_turn_limit_miss_streak": (
                    0
                    if _fresh_dispatch_cycle
                    else int(_existing_pr_state.get("review_turn_limit_miss_streak", 0))
                ),
                # A clean janitor pass ends the no-op-rework epoch (the
                # janitor's no-op check passing means content actually
                # moved): without this reset, attempts consumed by a long-
                # resolved stall would count against a genuinely new,
                # unrelated one weeks later and escalate it prematurely (the
                # counters are merge-carried forward by every other write to
                # this record).
                "no_op_rework_attempts": 0,
                "no_op_rework_attempts_last_head": None,
                # The conflict epoch resets only on an AFFIRMATIVE mergeable
                # signal: GitHub reports mergeable UNKNOWN/null for a window
                # after every push while it recomputes, and the janitor's
                # conflict check only fails on CONFLICTING/DIRTY -- so a
                # clean pass during that window is not evidence the conflict
                # was resolved, and resetting on it would let a flapping PR
                # relitigate its attempt cap forever.
                **(
                    {
                        "conflict_rework_attempts": 0,
                        "conflict_rework_attempts_last_head": None,
                    }
                    if str(pr.get("mergeable") or "").upper() == "MERGEABLE"
                    else {}
                ),
            }
            if issue_number is not None:
                _issue_key = str(issue_number)
                _issue_entry = state["issues"].get(_issue_key, {})
                state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
            state = append_event(
                state,
                "review_packet",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "cross_family_ok": cf_result.ok if cf_result else None,
                    "cross_family_reused": cf_result.reused if cf_result else None,
                    # Issue #1439: structure-aware turn cap stamped into the
                    # packet, mirrored into the event for auditability.
                    "review_turn_cap_structure_multiplier": pr_json.get(
                        "review_turn_cap_structure_multiplier", 1
                    ),
                    "review_turn_cap_max_touched_lines": pr_json.get(
                        "review_turn_cap_max_touched_lines", 0
                    ),
                },
                state_path=self.paths.state_file,
            )
            save_state(self.paths.state_file, state)
        # GitHub label side effects are best-effort and isolated: the durable
        # packet above is the authority; a label failure is reported, not fatal.
        label_error: dict[str, Any] | None = None
        if issue_number is not None:
            # Optimization: skip review_started transition if the PR has an unaddressed
            # request_changes decision and the head SHA hasn't changed (nothing new to review).
            # This avoids pointless packet churn and prevents the transition from stripping
            # the needs_rework label from budget-deferred rework candidates.
            should_skip_transition = False
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                pr_state = state["prs"].get(str(pr_number), {})
                # Issue #1362 Stage 1: single review-decision reader instead
                # of state.json's decision/reviewed_head_sha fields.
                resolved_decision = review_decision(pr_dir, None, pr.get("headRefOid"))
                if resolved_decision.decision == "request_changes" and not resolved_decision.stale:
                    should_skip_transition = True
                # Issue #384, re-checked here and not only at the top of
                # review(): the `review_started` edge removes every workflow
                # label it is not adding, `human_needed` included. The guard at
                # the head of this method reads state before any of review()'s
                # own work, so it cannot see an escalation applied *during* this
                # pass -- and since issue #1099
                # `_escalate_cross_family_regen_exhausted` does exactly that,
                # from `_cross_family_for_pr` a few hundred lines above.
                # Without this re-read the escalating pass would apply
                # `human_needed` and then strip it moments later, leaving the
                # issue escalated in state with no label on GitHub: the
                # #586/#594 escalated-without-label shape, reintroduced from
                # inside the pass rather than from the next one.
                #
                # The sibling mid-review escalation (the infra-rerun cap) avoids
                # this by returning immediately. This path cannot -- the model
                # already ran and its packet is worth writing -- so it suppresses
                # the label edge instead. Enforced at the boundary for *any*
                # escalation, not just the cross-family one, so the next
                # mid-review escalation added here inherits the fix.
                issue_state_now = (
                    state.get("issues", {}).get(str(issue_number), {})
                    if issue_number is not None
                    else None
                )
                if any(_escalation_flags(pr_state, issue_state_now)):
                    should_skip_transition = True

            if not should_skip_transition and not dispatch_disabled:
                result = transition(self.gh, self.config.labels, issue_number, "review_started")
                if result.outcome != TransitionOutcome.APPLIED:
                    label_error = {
                        "edge": "review_started",
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    }
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state["prs"][str(pr_number)]["label_error"] = label_error
                        save_state(self.paths.state_file, state)
        message = "review packet generated"
        if label_error:
            message += f" (label update failed: {label_error.get('outcome', label_error)})"
        return CommandResult(
            True,
            message,
            {
                "pr": pr_number,
                "issue": issue_number,
                "prompt_path": str(prompt_path),
                "decision_path": str(decision_path),
                "cross_family_report": cf_result.report_path if cf_result else None,
                "cross_family_ok": cf_result.ok if cf_result else None,
                "cross_family_reused": cf_result.reused if cf_result else None,
                "label_error": label_error,
                "checks_unavailable": False,
            },
        )

    def _sort_review_queue_by_dependency_depth(
        self, queue: list[dict[str, Any]]
    ) -> list[dict[str, Any]]:
        """Sort review queue so PRs blocking the most downstream work come first.

        Builds the same blocker->dependents graph used by worker dispatch
        against the currently-blocked ready-labeled issues. PRs whose linked
        issue is a blocker for more downstream issues are dispatched first,
        with PR number as a stable tiebreaker.
        """
        import logging

        logger = logging.getLogger(__name__)
        if not queue:
            return queue

        try:
            ready_issues = self.gh.issue_list(
                labels=[self.config.labels.ready],
                state="OPEN",
            )
            blocker_to_dependents: dict[int, list[int]] = {}
            for issue in ready_issues:
                issue_number = int(issue["number"])
                declared_blockers, open_blockers = self._get_open_blockers(issue)
                if not open_blockers:
                    continue
                for blocker in declared_blockers:
                    blocker_to_dependents.setdefault(blocker, []).append(issue_number)

            def sort_key(entry: dict[str, Any]) -> tuple[int, int]:
                return (
                    -len(blocker_to_dependents.get(entry["issue"], [])),
                    entry["pr"],
                )

            return sorted(queue, key=sort_key)
        except Exception:
            logger.warning(
                "Dependency depth sort failed; returning unsorted review queue",
                exc_info=True,
            )
            return queue

    def _emit_stale_ci_verdict_requeued(
        self,
        pr_number: int,
        issue_number: int | None,
        reviewed_head_sha: str | None,
        live_head_sha: str,
        required_changes: Sequence[str] | None,
    ) -> None:
        """Emit ``stale_ci_verdict_requeued`` once per PR/head transition.

        Issue #1120: ``review_queue()`` is called multiple times per loop pass
        (once by ``dispatch_reviews()``, once by
        ``_record_cross_family_verdicts()``), so without dedup the event
        double-fires for the same PR within a single pass -- ~30s apart, the
        second emission landing after review_dispatch has already claimed and
        launched the PR. The dispatch itself is deduped by
        ``review_dispatch_claim``, so the only impact is log noise, but the
        pattern is the same missing-dedup family as the PR #1117 round-1
        review finding on ``stale_ci_verdict_gate_pass``.

        Mirrors the ``stale_ci_gate_pass_head`` fix: key the emission on a
        stored head field (``stale_ci_verdict_requeued_head`` in the PR state
        entry) so only the first queue evaluation per head transition emits,
        rather than every evaluation that sees the stale verdict.
        """
        if self.dry_run:
            return
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            existing_pr_state = state["prs"].get(str(pr_number), {})
            if existing_pr_state.get("stale_ci_verdict_requeued_head") == live_head_sha:
                return
            state["prs"][str(pr_number)] = {
                **existing_pr_state,
                "stale_ci_verdict_requeued_head": live_head_sha,
            }
            state = self._record_event(
                state,
                "stale_ci_verdict_requeued",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "reviewed_head_sha": reviewed_head_sha,
                    "required_changes": list(required_changes or []),
                },
            )
            save_state(self.paths.state_file, state)

    def review_queue(self) -> CommandResult:
        """Enumerate open agent PRs whose review packet is current and awaiting a verdict.

        When a recorded verdict (``approved``, ``request_changes``, or
        ``blocked``) was made against an older head, this method computes the
        live head's stable patch-id. If it matches the recorded
        ``reviewed_patch_id``, the verdict is carried forward to the new head
        (atomic decision-file + state update) and the PR is not queued as
        stale. In dry-run mode the carry-forward write is skipped; the patch-id
        check still runs so the queue reflects real content changes.

        A PR is queued when:

        - It has a linked issue (same as ``review()``).
        - ``prs/pr-N/review-prompt.md`` exists.
        - The recorded decision is ``missing``/``pending`` and the stored packet
          head OID matches the PR's live ``headRefOid``.
        - The recorded decision is a stale ``request_changes``/``blocked``/
          ``approved`` verdict whose patch-id genuinely differs from the live
          head and the packet head is still current.
        - The recorded decision is a content-free ``request_changes`` verdict
          (issue #784 AC-8, ``_is_carry_forward_eligible``) and the packet
          head is current -- queued as ``"vacuous"`` regardless of whether
          the head moved, since carry-forward and the head-unchanged
          shortcut must never re-confirm a verdict with nothing for a
          rework brief to act on.

        A PR is NOT queued, but has a side-effecting repair applied instead,
        when the recorded decision is an actionable (non-content-free),
        non-escalated ``request_changes`` verdict at the live head whose
        linked issue status does not show it was ever routed to rework
        (issue #784 AC-8, Case 2, ``_reroute_stranded_request_changes``) --
        this re-applies the SAME ``rework_requested`` transition
        ``record_review`` already decided, so it is a repair of a dropped
        transition, not a new decision, and is a no-op once the issue is at
        ``rework_requested`` (or otherwise already spoken for).

        Returns:
            CommandResult with a sorted ``queue`` list keyed by repo. Each
            candidate dict carries ``mergeable`` and ``mergeStateStatus`` from
            ``pr_list()`` so callers (e.g. ``dispatch_reviews``) can detect
            merge-conflicting PRs without an extra ``pr_view`` call (issue #1497).
        """
        prs = self.gh.pr_list()
        queue: list[dict[str, Any]] = []

        for pr in prs:
            issue_number = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if issue_number is None:
                continue

            pr_number = int(pr["number"])
            pr_dir = self.paths.prs / f"pr-{pr_number}"
            prompt_path = pr_dir / "review-prompt.md"
            if not prompt_path.exists():
                continue

            packet_head_sha = self._read_packet_head_oid(pr_number)
            live_head_sha = pr.get("headRefOid")
            if live_head_sha is None:
                continue

            decision = self._review_decision(pr_number)
            decision_value = decision.get("decision")
            reviewed_head_sha = decision.get("reviewed_head_sha")

            if decision_value in ("approved", "request_changes", "blocked"):
                if not _is_carry_forward_eligible(decision):
                    # Issue #784 AC-8: a content-free request_changes verdict
                    # must never be silently re-confirmed. This check runs
                    # BEFORE the head-unchanged shortcut below on purpose --
                    # that shortcut is the dominant case (a label-strip
                    # requeue never moves the head), and the whole point of
                    # AC-8 is that "head unchanged" must stop meaning
                    # "verdict re-affirmed" for exactly this content-free
                    # shape. Queue it as "vacuous" (packet permitting) so
                    # _record_cross_family_verdicts can force a *bounded*
                    # number of regeneration attempts
                    # (cross_family.max_parse_failures) rather than looping
                    # or re-confirming forever.
                    if packet_head_sha is None or packet_head_sha != live_head_sha:
                        continue
                    # Issue #592: a template edit makes a same-head packet
                    # stale for this path too. dispatch_reviews() does not
                    # filter its normal (non-cross-family) dispatch by
                    # decision value -- _is_review_dispatchable ignores the
                    # candidate payload entirely -- so an un-gated "vacuous"
                    # entry here could still reach a fresh reviewer as a
                    # packet rendered from the old template: the exact
                    # failure this issue fixed for the "stale" and
                    # "pending"/"missing"/"invalid" branches below. loop()
                    # regenerates the packet from the current template
                    # first; the next pass re-queues it once fresh.
                    if not self._packet_template_current(pr_number):
                        continue
                    queue.append(
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "packet_head_sha": packet_head_sha,
                            "decision": "vacuous",
                            "reviewed_head_sha": reviewed_head_sha,
                            "mergeable": pr.get("mergeable"),
                            "mergeStateStatus": pr.get("mergeStateStatus"),
                        }
                    )
                    continue

                if reviewed_head_sha == live_head_sha:
                    if decision_value == "request_changes" and self._is_stale_ci_request_changes(
                        pr_number, decision
                    ):
                        # Issue #1111: the verdict's only findings cite
                        # required checks that are all green on this same head
                        # — the failure it describes no longer exists (the
                        # check flipped transiently mid-review, or a rerun
                        # recovered it). Re-driving rework here is a
                        # guaranteed no-op that burns no_op_rework_attempts
                        # toward a manufactured escalation, so instead queue
                        # the PR for a FRESH review despite the unchanged
                        # head. The stale verdict is only ever superseded by
                        # a new recorded verdict, never auto-approved;
                        # repeated request_changes re-verdicts stay bounded
                        # by max_rework_cycles in record_review.
                        if packet_head_sha == live_head_sha and self._packet_template_current(
                            pr_number
                        ):
                            self._emit_stale_ci_verdict_requeued(
                                pr_number,
                                issue_number,
                                reviewed_head_sha,
                                live_head_sha,
                                decision.get("required_changes"),
                            )
                            queue.append(
                                {
                                    "pr": pr_number,
                                    "issue": issue_number,
                                    "packet_head_sha": packet_head_sha,
                                    "decision": "stale",
                                    "reviewed_head_sha": reviewed_head_sha,
                                    "mergeable": pr.get("mergeable"),
                                    "mergeStateStatus": pr.get("mergeStateStatus"),
                                }
                            )
                        continue
                    # Issue #784 AC-8 (Case 2): "reviewed at live head" only
                    # means "nothing to do" if the recorded verdict was
                    # actually actioned. A request_changes verdict that
                    # record_review decided is within the rework-cycle
                    # budget (``escalated`` falsy) must have routed its
                    # issue to rework_requested in that same call; if the
                    # issue status doesn't show that -- e.g. issue #789's
                    # reconcile one-way "closed" gate clobbered it -- re-
                    # drive the same target here rather than silently
                    # re-confirming a verdict nobody ever acted on.
                    if (
                        not self.dry_run
                        and decision_value == "request_changes"
                        and not decision.get("escalated")
                    ):
                        self._reroute_stranded_request_changes(pr, issue_number, decision)
                    continue

                check = self._check_carry_forward(pr_number, decision)
                if (
                    check.carry_forward
                    and decision_value == "request_changes"
                    and self._is_stale_ci_request_changes(pr_number, decision)
                ):
                    # Issue #1111 (head-advanced variant): the diff content is
                    # unchanged (carry-forward matched), but the verdict's only
                    # findings cite required checks that are all green on the
                    # live head — e.g. a no-op rework push after a transient CI
                    # failure recovered. Carrying the request_changes verdict
                    # forward would re-apply a failure that no longer exists,
                    # so skip the carry-forward and fall through to the
                    # stale-queue path below: a fresh review supersedes the
                    # verdict (never auto-approved).
                    self._emit_stale_ci_verdict_requeued(
                        pr_number,
                        issue_number,
                        reviewed_head_sha,
                        live_head_sha,
                        decision.get("required_changes"),
                    )
                elif check.carry_forward:
                    # In dry-run mode we still run the content check so the queue
                    # reflects real changes, but we skip the durable head update.
                    if not self.dry_run:
                        try:
                            self._update_approval_head(
                                pr_number,
                                decision,
                                live_head_sha,
                                old_head=reviewed_head_sha,
                                issue_number=issue_number,
                                tier=check.tier or "patch-id",
                                new_patch_id=check.live_patch_id,
                                new_signature=check.live_signature,
                            )
                        except StateLockBusy:
                            # Could not mirror the carry-forward into state.json,
                            # but the decision-file update is the durable source
                            # of truth; proceed as carried-forward.
                            pass
                    continue

                # If the packet is stale, we cannot dispatch a new reviewer from
                # it; the merge gate will route the issue to re-review. Only
                # surface as stale when the packet head is still current.
                if packet_head_sha is None or packet_head_sha != live_head_sha:
                    continue
                # Issue #592: a template edit makes a same-head packet stale
                # too. Don't queue it for dispatch -- loop() will regenerate it
                # from the current template first, and the next pass queues it.
                if not self._packet_template_current(pr_number):
                    continue

                queue.append(
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "packet_head_sha": packet_head_sha,
                        "decision": "stale",
                        "reviewed_head_sha": reviewed_head_sha,
                        "mergeable": pr.get("mergeable"),
                        "mergeStateStatus": pr.get("mergeStateStatus"),
                    }
                )
            elif decision_value in ("pending", "missing"):
                if packet_head_sha is None or packet_head_sha != live_head_sha:
                    continue
                # Issue #592: a template-stale packet must be regenerated by
                # loop() before it is dispatched, not handed to a reviewer as-is.
                if not self._packet_template_current(pr_number):
                    continue

                queue.append(
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "packet_head_sha": packet_head_sha,
                        "decision": decision_value
                        if decision_value in ("pending", "missing")
                        else "missing",
                        "reviewed_head_sha": None,
                        "mergeable": pr.get("mergeable"),
                        "mergeStateStatus": pr.get("mergeStateStatus"),
                    }
                )

        queue = self._sort_review_queue_by_dependency_depth(queue)
        return CommandResult(
            True,
            f"review queue: {len(queue)} PR(s) awaiting verdict",
            {"queue": queue},
        )

    def operator_queue(self) -> CommandResult:
        """List issues currently parked on ``agent:operator-queue`` (issue #1314 item 1).

        An operator-facing inspection command that joins three data sources
        so the queue is workable without hand-rolling ``gh`` queries:

        - GitHub issues carrying the ``operator_queue`` label (via
          ``gh.issue_list``), for title/URL/label context.
        - ``state.json``'s ``issues`` map, for ``reason_class`` provenance,
          ``escalation_reason``, ``terminal_since`` (age), and the
          de-escalation cap marker (``deescalation_cap_notified_at``).
        - ``events.db``, for the last escalation-transition event per issue
          (the ``kind`` and ``ts`` of the most recent event whose kind is in
          ``ESCALATION_REASON_CLASS_BY_EVENT_KIND`` or
          ``DELIBERATELY_UNCLASSIFIED_ESCALATION_EVENT_KINDS``), so an
          operator can see *when* and *why* the issue was parked.

        Issues on the label but missing from state (a manual label add with
        no escalation event) are included with ``reason_class: null`` and
        ``age_days: null`` so they are visible rather than silently dropped.
        Issues in state but missing from the GitHub label query (a label
        transition that has not yet propagated) are included from state
        alone.

        Returns a ``CommandResult`` with a ``queue`` list sorted by
        ``terminal_since`` ascending (oldest first), each entry carrying
        ``number``, ``title``, ``url``, ``labels``, ``reason_class``,
        ``escalation_reason``, ``terminal_since``, ``age_days``,
        ``deescalation_cap_notified_at``, and ``last_escalation_event``.
        """
        operator_queue_label = self.config.labels.operator_queue
        issues = self.gh.issue_list(operator_queue_label)
        state = load_state_locked(self.paths.state_file)
        state_issues = state.get("issues", {})
        if not isinstance(state_issues, dict):
            state_issues = {}

        now = datetime.now(UTC)
        escalation_kinds = (
            frozenset(ESCALATION_REASON_CLASS_BY_EVENT_KIND)
            | DELIBERATELY_UNCLASSIFIED_ESCALATION_EVENT_KINDS
        )

        # Build a set of issue numbers from the GitHub label query.
        gh_numbers: set[int] = set()
        issues_by_number: dict[int, dict[str, Any]] = {}
        for issue in issues:
            num = issue.get("number")
            if num is not None:
                gh_numbers.add(int(num))
                issues_by_number[int(num)] = issue

        # Build a set of issue numbers from state that match the operator-queue
        # criteria (status == "escalated", reason_class == "mechanical").
        state_numbers: set[int] = set()
        for num_str, entry in state_issues.items():
            if not isinstance(entry, dict):
                continue
            if (
                entry.get("status") == "escalated"
                and entry.get("reason_class") == "mechanical"
                and str(num_str).isdigit()
            ):
                state_numbers.add(int(num_str))

        all_numbers = sorted(gh_numbers | state_numbers)

        queue: list[dict[str, Any]] = []
        for issue_number in all_numbers:
            tracked_entry = state_issues.get(str(issue_number))
            if not isinstance(tracked_entry, dict):
                tracked_entry = {}

            gh_issue = issues_by_number.get(issue_number, {})

            terminal_since = tracked_entry.get("terminal_since")
            age_days: float | None = None
            if terminal_since:
                try:
                    since_dt = datetime.fromisoformat(str(terminal_since).replace("Z", "+00:00"))
                    age_days = round((now - since_dt).total_seconds() / 86400.0, 2)
                except (ValueError, TypeError):
                    age_days = None

            # Query events.db for the last escalation-transition event.
            last_escalation_event: dict[str, Any] | None = None
            events = query_events(
                self.paths.state_file,
                issue_number=issue_number,
            )
            escalation_events = [e for e in events if e.get("kind") in escalation_kinds]
            if escalation_events:
                last_escalation_event = {
                    "kind": escalation_events[-1].get("kind"),
                    "ts": escalation_events[-1].get("ts"),
                }

            queue.append(
                {
                    "number": issue_number,
                    "title": gh_issue.get("title"),
                    "url": gh_issue.get("url"),
                    "labels": sorted(label_names(gh_issue)) if gh_issue else [],
                    "reason_class": tracked_entry.get("reason_class"),
                    "escalation_reason": tracked_entry.get("escalation_reason"),
                    "terminal_since": terminal_since,
                    "age_days": age_days,
                    "deescalation_cap_notified_at": tracked_entry.get(
                        "deescalation_cap_notified_at"
                    ),
                    "last_escalation_event": last_escalation_event,
                }
            )

        # Sort by terminal_since ascending (oldest first); issues with no
        # terminal_since sort last.
        queue.sort(key=lambda e: (e["terminal_since"] is None, e["terminal_since"] or ""))

        return CommandResult(
            True,
            f"operator queue: {len(queue)} issue(s) parked on {operator_queue_label}",
            {"queue": queue, "depth": len(queue)},
        )

    def _reap_review_verdicts(self, reviews_dir: Path) -> dict[str, Any]:
        """Record verdicts for dead reviewers whose sidecar log contains a valid
        fenced JSON verdict block.

        Iterates claude-code review sidecars. For each reviewer that is no
        longer alive and still has a ``review_dispatch_dispatched`` claim, parse
        the log. If a valid verdict block is found, call ``record_review``
        in-process with the packet head pinned as ``reviewed_head`` so the
        verdict is attributed to the diff the reviewer actually read. On
        success ``record_review`` moves the PR to
        ``review_dispatch_completed``. If parsing fails or the verdict is
        malformed, the PR is left for ``_detect_and_handle_stalled_reviews`` to
        retry/backoff using the existing stale-claim path.

        Returns a dict with ``recorded`` and ``missed`` verdict info lists for
        the dispatch result and the fleet attention digest.
        """
        recorded: list[dict[str, Any]] = []
        missed: list[dict[str, Any]] = []

        for w in iter_workers(reviews_dir):
            if w.adapter_kind != "claude-code":
                continue
            if w.is_alive():
                continue

            pr_number = w.issue_number
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                pr_state = state["prs"].get(str(pr_number), {})
                if pr_state.get("review_dispatch_status") != "review_dispatch_dispatched":
                    continue
                issue_number = pr_state.get("issue_number")

            verdict_source = "log"
            verdict = _parse_review_verdict_from_log(Path(w.log_path))
            if verdict is None:
                # Fallback: parse the structured events.jsonl. The plaintext log
                # may be truncated or the verdict block split across tee buffer
                # boundaries, but the stream-json events contain the assistant's
                # message text in discrete JSONL lines.
                events_path = _events_path(reviews_dir, pr_number, review=True)
                verdict_source = "events"
                verdict = _parse_review_verdict_from_events(events_path)
            if verdict is None:
                # Last resort (issue #566): the reviewer may have written its
                # verdict to a Markdown file it referenced in final output
                # instead of re-emitting the fenced block. mtime-gated to this
                # session's started_at so stale files never resurrect old
                # verdicts.
                file_hit = _parse_review_verdict_from_files(
                    Path(w.log_path),
                    self.paths.prs / f"pr-{pr_number}",
                    w.started_at,
                )
                if file_hit is not None:
                    verdict, file_source = file_hit
                    verdict_source = f"file:{file_source}"
            if verdict is None:
                # No structured verdict found. Before discarding this reviewer's
                # work, check if it did substantial analysis (e.g. hit the
                # --max-turns limit) and post a summary PR comment so the work
                # is not silently lost. Only post once per dispatch lifecycle.
                pr_state_dict = pr_state
                # One-shot guard. ``review_miss_summary_posted`` covers every
                # miss reason; the legacy turn-limit key is still honoured so
                # PRs mid-lifecycle when this shipped don't get a second
                # comment.
                already_posted = pr_state_dict.get(
                    "review_miss_summary_posted"
                ) or pr_state_dict.get("review_turn_limit_summary_posted")
                if not already_posted:
                    events_path = _events_path(reviews_dir, pr_number, review=True)
                    max_turns = self.config.review_dispatch.review_max_turns
                    # Issue #1354: read the reviewer's exit code from the
                    # durable terminal-status record (written by
                    # ``start_terminal_status_watcher`` in
                    # ``launch_claude_worker``) so the terminating-cause
                    # extractor can fold it into the ``cause`` field of the
                    # ``review_verdict_missed`` payload. The terminal-status
                    # watcher is now started for review launches too (see
                    # ``claude_code.launch_claude_worker``); for sessions
                    # that died before that change landed, the record is
                    # absent and ``exit_code`` stays ``None``, in which case
                    # ``_extract_terminating_cause`` falls back to the
                    # stream-json result event or the explicit
                    # ``{"cause": "unknown"}`` sentinel.
                    #
                    # The reviewer's terminal-status file is written under
                    # ``reviews_dir`` keyed by ``pr_number`` -- the review
                    # launch site (``dispatch_reviews``) calls
                    # ``launch_claude_worker(sessions_dir=reviews_dir,
                    # issue_number=pr_number, review=True)``, and
                    # ``start_terminal_status_watcher`` writes to
                    # ``worker_terminal_status_path(sessions_dir,
                    # issue_number, ...)``. Reading from the layout's default
                    # sessions dir keyed by the linked issue number would
                    # return the original coding worker's stale exit code,
                    # not the reviewer's.
                    terminal = find_worker_terminal_status(reviews_dir, pr_number)
                    exit_code = terminal.get("exit_code") if terminal else None
                    outcome = _extract_review_session_summary(
                        events_path,
                        Path(w.log_path),
                        max_turns,
                        session_limit_markers=self.config.runtime.session_limit_markers,
                        exit_code=exit_code,
                    )
                    if outcome is not None:
                        try:
                            self._comment_pr(pr_number, outcome.text)
                        except Exception:
                            pass
                        with state_lock(self.paths.state_file):
                            state = load_state(self.paths.state_file)
                            ps = state["prs"].get(str(pr_number), {})
                            # The turn-limit key means "this dispatch
                            # lifecycle's session did substantial work then
                            # died". The provider-throttle sweep reads it to
                            # deny a rollback (#583) and #584 counts it as a
                            # turn-limit death, so a session that never
                            # reached turn 1 must not set it -- that death is
                            # environmental and says nothing about this PR.
                            # Issue #1439: a turn-limit death increments the
                            # per-PR miss streak so the NEXT dispatch's cap
                            # escalates one step instead of relaunching with
                            # the identical flat budget. Non-turn-limit deaths
                            # (launch_failed, died_mid_session) do NOT
                            # increment -- those have disjoint remediations and
                            # counting them here would conflate a quota/launch
                            # outage with a genuine "reviewer ran out of
                            # navigation budget" signal.
                            _is_turn_limit_miss = outcome.reason == REVIEW_MISS_TURN_LIMIT
                            _prior_streak = int(ps.get("review_turn_limit_miss_streak", 0))
                            _new_streak = (
                                _prior_streak + 1 if _is_turn_limit_miss else _prior_streak
                            )
                            state["prs"][str(pr_number)] = {
                                **ps,
                                "review_miss_summary_posted": True,
                                "review_turn_limit_summary_posted": (outcome.did_substantial_work),
                                "review_turn_limit_miss_streak": _new_streak,
                            }
                            state = append_event(
                                state,
                                "review_verdict_missed",
                                {
                                    "pr_number": pr_number,
                                    "issue_number": issue_number,
                                    "reason": outcome.reason,
                                    "turn_count": outcome.turn_count,
                                    "tool_call_count": outcome.tool_call_count,
                                    # Issue #1354: the terminating-cause
                                    # dict (exit code, stream-json result
                                    # event fields, or ``{"cause": "unknown"}``
                                    # when nothing could be captured). Always
                                    # present so a downstream query can
                                    # distinguish "no cause captured" from
                                    # "cause field absent".
                                    "cause": outcome.terminating_cause,
                                    # Issue #1439: mirror the post-increment
                                    # streak into the event so a downstream
                                    # query can reconstruct the cap escalation
                                    # history without a join back to state.
                                    "turn_limit_miss_streak": _new_streak,
                                },
                                state_path=self.paths.state_file,
                            )
                            save_state(self.paths.state_file, state)
                        missed.append(
                            {
                                "pr": pr_number,
                                "issue": issue_number,
                                "reason": outcome.reason,
                                "cause": outcome.terminating_cause,
                            }
                        )
                        # Issue #1354: release this dead reviewer's isolated
                        # review checkout in the SAME pass that detected the
                        # death, rather than waiting for
                        # ``_detect_and_handle_stalled_reviews``'s 5-minute
                        # stale-claim timeout. The reviewer is already dead
                        # (``w.is_alive()`` returned False at the top of this
                        # loop) and no verdict was found, so the checkout is
                        # pure overhead -- a detached-HEAD git worktree that
                        # holds no recoverable work. Releasing it here means
                        # the claim directory does not linger for a full
                        # stale-claim interval.
                        #
                        # The sidecar is deliberately NOT reaped here: the
                        # stalled-review sweep (which runs immediately after
                        # this function in ``dispatch_reviews``) reads the
                        # sidecar's log tail to classify provider-throttle
                        # signatures and arm fleet-wide backoff. Reaping the
                        # sidecar here would prevent that classification,
                        # silently disarming the quota-exhaustion backoff for
                        # a death that may have been caused by exactly that
                        # condition. The stalled sweep reaps the sidecar
                        # itself after classification (or on its next pass
                        # once the stale timeout elapses).
                        remove_review_checkout(self.repo_root, pr_number, reviews_dir=reviews_dir)
                continue

            packet_head_sha = self._read_packet_head_oid(pr_number)
            session_metrics = _reviewer_session_metrics(
                _events_path(reviews_dir, pr_number, review=True), verdict_source
            )
            # Fold the review_effort experiment's arm/effort assignment (set
            # at claim time in dispatch_reviews) into session_metrics so the
            # record_review event alone is enough to split spend/quality by
            # arm, without a join back to the dispatch event.
            review_effort_arm = pr_state.get("review_effort_arm")
            review_effort_used = pr_state.get("review_effort_used")
            if review_effort_arm is not None or review_effort_used is not None:
                session_metrics = {
                    **(session_metrics or {}),
                    "review_effort_arm": review_effort_arm,
                    "review_effort_used": review_effort_used,
                }
            result = self.record_review(
                pr_number,
                verdict["decision"],
                summary=verdict["summary"],
                reviewed_head=packet_head_sha,
                required_changes=verdict["required_changes"],
                session_metrics=session_metrics,
                verdict_provenance="fresh_llm_review",
                # Issue #1340: thread the parser-level provenance into the
                # decision file so a later reader can distinguish a
                # log-extracted verdict (dead reviewer) from a clean
                # structured completion. ``verdict_source`` is the same value
                # already threaded into ``session_metrics`` above.
                verdict_source=verdict_source,
            )
            if result.ok:
                recorded.append(
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "decision": verdict["decision"],
                        "verdict_source": verdict_source,
                    }
                )
            else:
                reason = result.message or "record_review failed"
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state = append_event(
                        state,
                        "review_verdict_missed",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "reason": reason,
                        },
                        state_path=self.paths.state_file,
                    )
                    save_state(self.paths.state_file, state)
                missed.append(
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "reason": reason,
                    }
                )

        return {"recorded": recorded, "missed": missed}

    def _reconcile_stranded_verdicts(self) -> list[dict[str, Any]]:
        """Ingest completed on-disk verdicts that were never recorded into state.

        Issue #736: a PR may have a complete ``review-decision.json`` on disk
        (written by ``record_review``) but no ``decision`` key in its state
        record -- the state update was lost (e.g. a concurrent writer clobbered
        it, or the verdict file was written by a path that didn't update
        state). Without this reconciliation, the verdict is stranded: the PR
        stays in ``status=reviewing`` forever because the only ingestion path
        that reads ``review-decision.json`` (``_reap_review_verdicts``) requires
        a live reviewer sidecar, and the stale-claim recovery branch in
        ``_detect_and_handle_stalled_reviews`` explicitly *skips* PRs whose
        on-disk verdict is already completed (issue #734's
        ``decision_already_recorded`` skip). That skip is correct for the
        stale-claim sweep -- a completed verdict is not a stale claim -- but
        it leaves the PR with no path to ingest the verdict at all.

        This method closes that gap by scanning every non-terminal PR record
        for a ``decision_path`` pointing to an existing file with a completed
        verdict (``approved``/``request_changes``/``blocked``) that is not
        reflected in ``state.decision``, and ingesting it via
        ``record_review`` so the normal verdict → rework/merge/blocked route
        can take over. It runs in ``dispatch_reviews`` ahead of the
        ``review_dispatch.enabled`` gate (issue #868), so it executes even
        when review dispatch is disabled fleet-wide -- the exact condition
        that stranded PR 1343.

        Returns a list of per-PR result dicts for diagnostics.
        """
        if self.dry_run:
            return []
        results: list[dict[str, Any]] = []
        state = load_state_locked(self.paths.state_file)
        for pr_key, pr_state in list(state.get("prs", {}).items()):
            if not isinstance(pr_state, dict) or not pr_key.isdigit():
                continue
            pr_status = pr_state.get("status")
            # Skip lifecycle-terminal PRs -- a merged/closed PR needs no
            # verdict ingestion.
            if pr_status in ("merged", "closed"):
                continue
            decision_path_str = pr_state.get("decision_path")
            if not decision_path_str:
                continue
            decision_path = Path(decision_path_str)
            if not decision_path.exists():
                continue
            try:
                with decision_path.open("r", encoding="utf-8") as handle:
                    decision_data = json.load(handle)
            except (OSError, json.JSONDecodeError):
                continue
            if not isinstance(decision_data, dict):
                continue
            on_disk_decision = decision_data.get("decision")
            if on_disk_decision not in ("approved", "request_changes", "blocked"):
                continue
            on_disk_reviewed_head_sha = decision_data.get("reviewed_head_sha")
            # Skip only if state already ingested THIS on-disk verdict -- the
            # same decision recorded against the same reviewed head. A
            # prior-round terminal decision with a DIFFERENT
            # reviewed_head_sha than the on-disk file means a later round's
            # verdict was written to disk but never ingested into state (the
            # #736 stranded shape re-opened for round-2+); it must still be
            # reconciled. Skipping solely because ``state.decision`` holds
            # any terminal value from a prior round would strand every
            # round-2+ verdict whose state write was lost.
            #
            # ``record_review``'s own #467/#1072 head-drift guard is the
            # safety net for stale heads: it refuses to pin a verdict to a
            # head that no longer matches the packet/live head for automated
            # callers (``allow_stale_head`` defaults to ``False``). So this
            # skip's job is only to avoid re-processing a verdict already
            # ingested for the SAME on-disk decision, not to skip every PR
            # that has ever had a decision recorded.
            recorded_decision = pr_state.get("decision")
            recorded_reviewed_head_sha = pr_state.get("reviewed_head_sha")
            if (
                recorded_decision in ("approved", "request_changes", "blocked")
                and recorded_decision == on_disk_decision
                and recorded_reviewed_head_sha == on_disk_reviewed_head_sha
            ):
                continue
            # Stranded verdict found: the on-disk file carries a completed
            # decision not reflected in state -- either state has no
            # ``decision`` key at all, or it carries a prior-round decision
            # recorded against a different ``reviewed_head_sha``. Ingest it
            # via ``record_review`` so the full state-machine transition (PR
            # status, issue status, rework prompt, label transition) runs
            # exactly as if the verdict were freshly rendered.
            #
            # ``allow_stale_head`` is left at its default ``False``. In the
            # actual #736 bug scenario (state write lost, head unchanged),
            # ``record_review``'s #467/#1072 guard never fires — the packet
            # head and live head agree — so the flag would be a no-op there.
            # The flag only changes behavior when the live PR head has
            # advanced past the packet head (new commits landed while the PR
            # sat 'reviewing'), which is exactly the case where the verdict
            # is legitimately stale and must NOT be silently pinned to the
            # old diff. ``allow_stale_head=True`` is reserved for the
            # operator ``charlie verdict`` CLI (issue #467's explicit-choice
            # design); this is an automated caller and uses the default.
            # A head-drifted stranded verdict is correctly refused this pass
            # and left for the stale-claim sweep / a fresh review dispatch.
            pr_number = int(pr_key)
            record_result = self.record_review(
                pr_number,
                on_disk_decision,
                summary=decision_data.get("summary", ""),
                reviewed_head=decision_data.get("reviewed_head_sha"),
                required_changes=decision_data.get("required_changes"),
                verdict_provenance="stranded_reconciliation",
            )
            entry: dict[str, Any] = {
                "pr_number": pr_number,
                "decision": on_disk_decision,
                "ok": record_result.ok,
                "message": record_result.message,
            }
            results.append(entry)
            if record_result.ok:
                log_event(
                    self.paths.state_file,
                    "review_verdict_reconciled",
                    {
                        "pr_number": pr_number,
                        "issue_number": decision_data.get("issue_number"),
                        "decision": on_disk_decision,
                    },
                )
            else:
                log_event(
                    self.paths.state_file,
                    "review_verdict_reconcile_failed",
                    {
                        "pr_number": pr_number,
                        "decision": on_disk_decision,
                        "reason": record_result.message,
                    },
                    level="warning",
                )
        return results

    def _record_cross_family_verdicts(self) -> list[dict[str, Any]]:
        """Parse cross-family reports and record verdicts for pending PRs.

        When ``cross_family.auto_verdict`` is enabled and
        ``review_dispatch`` is disabled (the cross-family pass is the sole
        automated review), this scans the review queue for PRs whose
        ``review-decision.json`` is still ``pending`` -- or whose recorded
        verdict was rejected as content-free and re-queued as ``"vacuous"``
        (issue #784 AC-8) -- but whose ``cross-family-review.md`` report is
        valid and non-stale. It parses the report into an approved/
        request_changes verdict and records it via ``record_review()``,
        unblocking the merge lane.

        A report that fails to parse into a real verdict
        (``MalformedCrossFamilyVerdict``) is never recorded -- issue #784
        AC-3: it must not increment ``request_changes_count`` or dispatch
        rework. See ``_handle_malformed_cross_family_verdict`` for how that
        outcome is bounded so it cannot repeat forever.

        Returns a list of per-PR result dicts for logging/diagnostics.
        """
        if not self.config.cross_family.auto_verdict:
            return []
        results: list[dict[str, Any]] = []
        queue_result = self.review_queue()
        candidates = queue_result.data.get("queue", [])
        for candidate in candidates:
            pr_number = candidate["pr"]
            decision = candidate.get("decision")
            if decision not in ("pending", "vacuous"):
                continue
            pr_dir = self.paths.prs / f"pr-{pr_number}"
            report_path = pr_dir / "cross-family-review.md"
            if not report_path.exists():
                continue
            try:
                report_text = report_path.read_text(encoding="utf-8")
            except OSError:
                continue
            # Skip stale reports: the head SHA in the report must match the
            # packet head SHA so we don't record a verdict for an old diff.
            # Require BOTH shas on positive confirmation -- an indeterminate
            # comparison (either side unknown) must not fall through to the
            # permissive branch. That fail-open let an unverifiable head
            # authorize a merge.
            report_head = extract_head_ref_oid(report_text)
            packet_head = candidate.get("packet_head_sha")
            if report_head is None or packet_head is None:
                # The skip this fix *adds*: neither the mismatch case below
                # (already skipped before, and self-healing -- a head move
                # regenerates the report) nor the malformed-verdict case
                # (bounded by max_parse_failures). Nothing regenerates a
                # report whose head is simply absent, so this PR can sit
                # here every pass forever. Emit once so it is visible
                # instead of silently stalling -- the exact failure shape
                # this whole guard exists to stop being invisible.
                self._note_cross_family_head_indeterminate(
                    pr_number, candidate.get("issue"), report_head, packet_head
                )
                continue
            if report_head != packet_head:
                continue
            parsed = parse_cross_family_verdict(report_text)
            if parsed is None:
                continue
            if isinstance(parsed, MalformedCrossFamilyVerdict):
                results.append(
                    self._handle_malformed_cross_family_verdict(
                        pr_number, candidate.get("issue"), packet_head, parsed
                    )
                )
                continue
            verdict_decision = parsed.decision
            record_result = self.record_review(
                pr_number,
                verdict_decision,
                summary=parsed.summary,
                reviewed_head=packet_head,
                required_changes=parsed.required_changes,
                verdict_provenance="cross_family_review",
            )
            results.append(
                {
                    "pr_number": pr_number,
                    "decision": verdict_decision,
                    "ok": record_result.ok,
                    "message": record_result.message,
                }
            )
        return results

    def _note_cross_family_head_indeterminate(
        self,
        pr_number: int,
        issue_number: int | None,
        report_head: str | None,
        packet_head: str | None,
    ) -> None:
        """Record, once per PR, that the head-SHA guard could not adjudicate.

        The guard skips when either side is unknown, which is correct -- an
        unverifiable head must not authorize a merge. But that skip re-runs
        every ``_record_cross_family_verdicts`` pass with the same inputs and
        nothing regenerates the report, so without a signal the PR stalls in
        ``reviewing`` invisibly. This is deliberately *not* bounded the way
        ``max_parse_failures`` bounds the malformed path: that bound ends in a
        caveated ``approved``, and approving on an unconfirmed head is exactly
        the fail-open this guard closes. Visibility is the remedy here, not an
        eventual auto-approve.

        The durable ``cross_family_head_indeterminate`` marker keeps this to
        one event per PR rather than one per loop pass, which would flush the
        capped ``events`` ring in ``state.json``.
        """
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            if pr_state.get("cross_family_head_indeterminate"):
                return
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "cross_family_head_indeterminate": True,
            }
            state = self._record_event(
                state,
                "cross_family_verdict_head_indeterminate",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "report_head_sha": report_head,
                    "packet_head_sha": packet_head,
                    "reason": "report head SHA missing"
                    if report_head is None
                    else "packet head SHA missing",
                },
            )
            save_state(self.paths.state_file, state)

    def _handle_malformed_cross_family_verdict(
        self,
        pr_number: int,
        issue_number: int | None,
        packet_head: str | None,
        parsed: MalformedCrossFamilyVerdict,
    ) -> dict[str, Any]:
        """Bound the malformed-verdict cycle for one PR (issue #784 AC-8 bound).

        Never calls ``record_review`` with the malformed outcome itself
        (AC-3: no ``request_changes_count`` increment, no rework dispatch).
        Tracks a *separate* durable counter,
        ``cross_family_parse_failure_count``, so the "content-free verdict
        -> AC-8 forces regeneration -> still content-free" cycle cannot
        repeat forever: without a bound of its own, removing the
        request_changes-cycle counter from this path (as AC-3 requires)
        would leave nothing capping how many times a PR re-enters this
        branch, one ``_record_cross_family_verdicts`` invocation per loop
        pass.

        Past ``cross_family.max_parse_failures`` observations, cross-family
        review is abandoned for this PR: recorded as a caveated, non-
        blocking ``approved`` (never ``agent:human-needed``, and never a
        ``request_changes`` verdict that blocks indefinitely -- both of
        which would recreate the original bug with better provenance). This
        is deliberately asymmetric: a reviewer this pipeline cannot parse is
        a failure of the pipeline, not evidence against the PR, so the PR
        does not pay for it.
        """
        cap = self.config.cross_family.max_parse_failures
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            failure_count = int(pr_state.get("cross_family_parse_failure_count", 0)) + 1
            abandon = failure_count > cap
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "cross_family_parse_failure_count": failure_count,
            }
            state = self._record_event(
                state,
                "cross_family_verdict_abandoned"
                if abandon
                # event-consumer: audit-only -- intermediate attempt-counter bump before the
                # abandon threshold; only the terminal cross_family_verdict_abandoned (consumed)
                # is actionable
                else "cross_family_verdict_unparseable",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "reason": parsed.reason,
                    "attempt": failure_count,
                    "max_parse_failures": cap,
                },
            )
            save_state(self.paths.state_file, state)
        if not abandon:
            return {
                "pr_number": pr_number,
                "decision": "unparseable",
                "ok": False,
                "message": (
                    f"cross-family verdict unparseable ({parsed.reason}), "
                    f"attempt {failure_count}/{cap}"
                ),
            }
        record_result = self.record_review(
            pr_number,
            "approved",
            summary=(
                "Cross-family review could not produce a parseable verdict "
                f"after {failure_count} attempts ({parsed.reason}); treated "
                "as non-blocking per its advisory-only design (issue #784). "
                f"A human should inspect prs/pr-{pr_number}/cross-family-review.md "
                "directly."
            ),
            reviewed_head=packet_head,
            required_changes=(),
            verdict_provenance="unparseable_exhausted",
        )
        return {
            "pr_number": pr_number,
            "decision": "approved",
            "ok": record_result.ok,
            "message": (
                f"cross-family review abandoned after {failure_count} parse "
                f"failures: {record_result.message}"
            ),
        }

    # Deliberately NOT @_guard_state_lock: that decorator returns a CommandResult
    # on StateLockBusy, and this method returns a plain dict that gets embedded in
    # dispatch_reviews' payload. Its only caller IS @_guard_state_lock-decorated,
    # so a busy lock here propagates up and skips the whole pass -- which is the
    # right granularity anyway.
    def _repair_escalated_labels(self) -> dict[str, Any]:
        """Re-apply the ``agent:human-needed`` edge for escalated issues that lack it.

        Issue #586 established this self-heal: the edge is applied once at
        escalation time, and if that ``transition()`` failed -- or the issue was
        escalated by a path predating the edge -- the issue sits ``escalated`` in
        ``state.json`` and invisible on GitHub, permanently excluded from dispatch
        with no human-visible signal that operator action is required.

        Issue #1088 is that the sweep is unreachable whenever review dispatch is
        off. Its subject set was built inside ``dispatch_reviews``'
        candidate-filter loop, below the ``review_dispatch.enabled`` early
        return, and both deployed fleets run that flag false -- so the set is
        empty and the loop a no-op for as long as the flag stays off, which at
        the time of the fix was ~8 days and counting. It is not dead code in the
        absolute sense: it fired once (job-cannon 2026-07-28) and repaired 10
        issues, which is exactly why the inertness matters.
        Deriving the subjects from ``state`` (see
        ``_collect_escalated_label_subjects``) is what makes the guarantee real,
        and this method is called *above* that early return.

        Two properties worth preserving:

        - **Steady state costs nothing.** Once an edge verifies, ``label_error``
          is ``None`` and ``_escalated_label_needs_repair`` answers with a dict
          lookup and no GitHub call. Without that, the sweep would re-apply every
          label on every pass forever.
        - **The per-pass cap is mandatory, not defensive.** Every subject in the
          absent-key arm costs a live ``issue_view``, and when this was written
          *every* escalated subject was in that arm (8 in charlie-work, 49 in
          job-cannon). Sweeping all 57 in one pass would add that many sequential
          ``gh`` calls to a loop shared sequentially between both repos, which is
          #1078's starvation mechanism. The cap converges over a few passes
          instead; subjects are visited in issue order so progress is monotonic
          rather than re-rolling the same head of the list.
        """
        empty: dict[str, Any] = {
            "issue_numbers": [],
            "failures": [],
            "errored": [],
            "deferred": 0,
        }
        # --dry-run must not perform live GitHub label mutations or state.json
        # writes (review finding on PR #670).
        if self.dry_run:
            return empty
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            subjects = [
                (pr_number, issue_number)
                for pr_number, issue_number in _collect_escalated_label_subjects(state)
                if _escalated_label_needs_repair(
                    state, pr_number=pr_number, issue_number=issue_number
                )
            ]
        if not subjects:
            return empty
        cap = self.config.runtime.escalated_label_repair_max_per_pass
        deferred = 0
        if cap > 0 and len(subjects) > cap:
            deferred = len(subjects) - cap
            subjects = subjects[:cap]

        outcomes: list[tuple[int, dict[str, Any] | None]] = []
        # Subjects whose GitHub call raised. Tracked separately from `failures`
        # (a transition() that returned non-APPLIED) because they are a different
        # operational state: nothing was written for them, so they retry next
        # pass. They MUST still be reported -- see the summary construction below.
        errored: list[int] = []
        for pr_number, issue_number in subjects:
            # Re-evaluate per item, immediately before touching GitHub, rather
            # than trusting the batch read above. #586 did this for a reason: a
            # concurrent unescalate() can free the issue at any point, and it
            # clears label_error, so the freed issue lands in the absent-key
            # ("never attempted") arm and would be silently re-escalated. Doing
            # the check once for the whole batch would widen that window from
            # "immediately before the call" to "up to `cap` GitHub round-trips
            # earlier" -- which is a real regression, and the existing race test
            # catches it.
            with state_lock(self.paths.state_file):
                fresh = load_state(self.paths.state_file)
            if not _escalated_label_needs_repair(
                fresh, pr_number=pr_number, issue_number=issue_number
            ):
                continue
            # issue_view/transition make GitHub API calls that can raise on
            # transient errors; a failure to verify one escalated issue must not
            # abort the pass. Skip it and retry next pass -- the escalated status
            # is already durable in state, so deferring loses no ground truth.
            try:
                # Issue #1266: a mechanical escalation's correct label is
                # operator_queue, not human_needed -- re-deriving from the
                # issue's reason_class (rather than hardcoding "escalated"
                # here) is what stops this sweep from clobbering a correctly
                # operator-queued issue back to human_needed every pass.
                fresh_issue_entry = fresh.get("issues", {}).get(str(issue_number), {})
                repair_reason_class = _repair_reason_class(fresh_issue_entry)
                edge = _escalation_edge("escalated", repair_reason_class)
                expected_label = _escalation_label(self.config.labels, edge)
                issue_view = self.gh.issue_view(int(issue_number))
                if expected_label is not None and expected_label in label_names(issue_view):
                    outcomes.append((int(issue_number), None))
                    continue
                result = transition(self.gh, self.config.labels, int(issue_number), edge)
            except Exception:
                logging.getLogger(__name__).warning(
                    "escalated label repair for issue %s deferred (GitHub fetch "
                    "failed); will retry next pass",
                    issue_number,
                    exc_info=True,
                )
                errored.append(int(issue_number))
                continue
            if result.outcome == TransitionOutcome.APPLIED:
                outcomes.append((int(issue_number), None))
            else:
                outcomes.append(
                    (
                        int(issue_number),
                        {
                            "edge": edge,
                            "outcome": result.outcome.value,
                            "add_failures": result.add_failures,
                            "remove_failures": result.remove_failures,
                        },
                    )
                )
        # `errored` gates this too, not just `outcomes`. If every subject's
        # GitHub call raised, `outcomes` is empty -- and returning `empty` here
        # would hand back {"issue_numbers": [], "failures": [], "deferred": 0},
        # byte-identical to "there was nothing to repair", while emitting no
        # event at all. An operator could then not tell a healthy quiet fleet
        # from N subjects failing on every single pass, and events.db (the audit
        # trail) would show nothing either. The logger.warning above is real but
        # log-only; the reported summary has to carry it as well.
        if not outcomes and not errored:
            return {**empty, "deferred": deferred}
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            for issue_number, label_error in outcomes:
                entry = state["issues"].get(str(issue_number), {})
                state["issues"][str(issue_number)] = {
                    **(entry if isinstance(entry, dict) else {}),
                    "number": issue_number,
                    "label_error": label_error,
                }
            summary = {
                "issue_numbers": [i for i, _ in outcomes],
                # transition() ran and did not fully apply -- label_error IS
                # written for these, so they are diagnosable from state.
                "failures": [i for i, e in outcomes if e is not None],
                # The GitHub call raised -- nothing was written, so these retry
                # next pass and are invisible in state. This list is the only
                # durable record that they were attempted at all.
                "errored": errored,
                "deferred": deferred,
            }
            state = append_event(
                state,
                "escalated_label_repaired",
                summary,
                state_path=self.paths.state_file,
                # A pass that repaired cleanly is routine, and the registry's
                # default ("info") is right for it. A pass that could not reach
                # GitHub, or whose transition() did not apply, is precisely what
                # an operator filters for with query_events(level="warning") --
                # and for an all-errored pass this event is the ONLY durable
                # record, since nothing is written to state for those subjects.
                # Leaving it at "info" would bury it among every routine pass.
                # None falls back to the registry (log_event's contract).
                level="warning" if (errored or summary["failures"]) else None,
            )
            save_state(self.paths.state_file, state)
        return summary

    @_guard_state_lock
    def dispatch_reviews(
        self, limit: int | None = None, *, now: datetime | None = None
    ) -> CommandResult:
        """Launch Claude Code reviewer sessions concurrently for queued PRs.

        Issue #370: a deterministic loop stage that turns ``review_queue()```
        into launched, sidecar-tracked reviewer processes. Reviewers are
        ``claude_code.launch_claude_worker`` sessions; there is no provider-
        rate-limit governor here — only an optional local-only process cap
        (``max_local_review_processes``) to protect the host from too many
        concurrent reviewer worktrees.

        The double-dispatch protection is a two-phase claim on
        ``state["prs"][pr]``: this method writes ``review_dispatch_pending``,
        launches outside the lock, then upgrades to ``review_dispatch_dispatched``
        or ``review_dispatch_failed``. Overlapping passes see the pending claim
        and skip until it goes stale. A reviewer that dies without a verdict is
        freed by ``_detect_and_handle_stalled_reviews`` after the stale-claim
        timeout, making the PR re-dispatchable.

        ``now`` (issue #828) is the injectable clock for this entire pass: it
        is resolved once below and forwarded to every ``is_claim_stale`` check
        this method drives, directly (via ``_is_review_dispatchable``) and
        indirectly (via ``_detect_and_handle_stalled_reviews``), instead of
        each one independently racing the wall clock. Defaults to
        ``datetime.now(UTC)`` when omitted, so production behavior is
        byte-identical; tests can freeze it and assert exact equality instead
        of a wall-clock-tolerance proximity check.
        """
        resolved_now = now if now is not None else datetime.now(UTC)
        reviews_dir = self._layout.reviews_dir

        # Run the verdict-reaper and orphan/stalled sweeps BEFORE the quota
        # gate so dead reviewers are reaped and stale claims are freed even
        # during throttle periods. Without this ordering, a quota deferral
        # returns early and leaves dead reviewer claims stuck — blocking
        # re-dispatch after the quota resets. In dry-run mode we skip
        # these sweeps to stay read-only.
        #
        # Issue #868: these sweeps must ALSO run ahead of the
        # ``review_dispatch.enabled`` gate below, for the same reason —
        # disabling dispatch must not disable the cleanup a *previously*
        # dispatched (or previously stamped-reviewing) claim still needs. A
        # dead reviewer's claim that goes stale while the flag happens to be
        # off must still be freed, or it stays stuck even after the flag is
        # re-enabled (the reap is what makes it re-dispatchable). Before this
        # fix these sweeps sat below the ``enabled`` early return and were
        # unreachable whenever dispatch was disabled.
        verdict_result = {"recorded": [], "missed": []}
        reconciled_verdicts: list[dict[str, Any]] = []
        if not self.dry_run:
            verdict_result = self._reap_review_verdicts(reviews_dir)
            # Issue #736: ingest completed on-disk verdicts that were never
            # recorded into state. This runs BEFORE the stale-claim sweep so
            # the sweep's ``decision_already_recorded`` skip (issue #734)
            # never fires for a PR this reconciliation just ingested -- after
            # ``record_review`` the PR's ``review_dispatch_status`` is
            # ``review_dispatch_completed`` and the stale-claim branch (which
            # only matches ``review_dispatch_status is None``) no longer
            # applies. Like the other sweeps here, this runs ahead of the
            # ``review_dispatch.enabled`` gate (issue #868) so a stranded
            # verdict is ingested even when dispatch is disabled fleet-wide.
            reconciled_verdicts = self._reconcile_stranded_verdicts()
            _detect_and_handle_stalled_reviews(
                reviews_dir,
                self.paths.state_file,
                self.config,
                self.repo_root,
                write_gate=self.write_gate,
                now=resolved_now,
            )
            _reap_completed_review_checkouts(self.repo_root, reviews_dir, self.paths.state_file)
            _reap_orphaned_review_checkouts(
                self.gh,
                self.repo_root,
                reviews_dir,
                self.paths.state_file,
                self.config,
                write_gate=self.write_gate,
            )
        recorded_verdicts = verdict_result.get("recorded", [])
        missed_verdicts = verdict_result.get("missed", [])

        # Issue #1088: this MUST stay above the ``review_dispatch.enabled`` early
        # return below. The sweep it drives is #586's, and #586's whole purpose is
        # that an escalated PR cannot sit invisible on GitHub -- a guarantee that
        # has nothing to do with whether new reviewers are being launched. Placing
        # it below the gate (where its input set used to be built) is what made it
        # dead code in every deployed fleet. The reaper sweeps immediately above
        # are the existing precedent for real work happening on this side of the
        # gate.
        repaired_labels = self._repair_escalated_labels()

        if not self.config.review_dispatch.enabled:
            # Issue #868 part 3: this is a real no-op for LAUNCHING new
            # reviewers, but the reaper sweeps above may still have done real
            # work (freeing a stale claim). Carry that through explicitly
            # instead of returning a bare ``ok=True`` that reads identically
            # to "nothing happened at all" — and mark ``disabled`` so a
            # caller doesn't have to string-match the message to tell this
            # apart from a real dispatch pass.
            return CommandResult(
                True,
                "review dispatch disabled",
                {
                    "selected_count": 0,
                    "attempted_count": 0,
                    "failed_count": 0,
                    "launched_count": 0,
                    "disabled": True,
                    "recorded_verdicts": recorded_verdicts,
                    "missed_verdicts": missed_verdicts,
                    # Issue #736: stranded-verdict reconciliation runs above
                    # the gate, so its results are reported on the disabled
                    # path for the same reason #868 reports the reaper results
                    # here -- this is the ONLY path the reconciliation runs on
                    # in a deployed fleet with dispatch disabled.
                    "reconciled_verdicts": reconciled_verdicts,
                    # Issue #1088: reported on the disabled path for the same
                    # reason #868 reports the reaper results here -- this is the
                    # ONLY path the sweep runs on in a deployed fleet, so a
                    # payload that omitted it would make the fix unobservable
                    # from the outside and indistinguishable from the dead code
                    # it replaces.
                    "escalated_labels_repaired": repaired_labels,
                },
            )

        # Issue #617: dry-run must short-circuit BEFORE the quota-alert marker
        # write, the rescue partition, and the attempt-cap escalation block --
        # all of which mutate state.json (or fire a real emit_digest) and sat
        # strictly before the old dry-run gate at the bottom of this method.
        # Mirror _dispatch_impl's top-of-function dry-run short-circuit: compute
        # the would-be selection read-only and return the plan, touching
        # nothing. A preview that escalates or writes a quota-alert marker is
        # worse than the bug it replaces, so this gate is a single early return,
        # not a branch inside the escalation arm.
        if self.dry_run:
            quota_state = load_state_locked(self.paths.state_file)
            if is_reviewer_quota_exhausted(quota_state) and not is_reviewer_probe_ready(
                quota_state
            ):
                return CommandResult(
                    True,
                    "review dispatch deferred: reviewer quota exhausted, probe not ready",
                    {
                        "selected_count": 0,
                        "attempted_count": 0,
                        "failed_count": 0,
                        "launched_count": 0,
                        "deferred_reason": "reviewer_quota_probe_backoff",
                        "recorded_verdicts": recorded_verdicts,
                        "missed_verdicts": missed_verdicts,
                        "reconciled_verdicts": reconciled_verdicts,
                    },
                )
            probe_mode_dry = bool(
                is_reviewer_quota_exhausted(quota_state) and is_reviewer_probe_ready(quota_state)
            )
            queue_result = self.review_queue()
            all_candidates = queue_result.data.get("queue", [])
            # Issue #617 rework: exclude rescue-marked PRs from the dry-run
            # candidate computation via a read-only state check, NOT a call
            # to _partition_rescue_candidates (which has real side effects:
            # it runs cross-family reviews, records verdicts, and escalates).
            # A rescue-marked PR must never appear in the preview as a normal
            # dispatch/escalation candidate — the real branch routes it
            # through _process_rescue_review instead.
            rescue_marked_dry: list[dict[str, Any]] = []
            candidates_dry: list[dict[str, Any]] = []
            for c in all_candidates:
                if quota_state.get("prs", {}).get(str(c["pr"]), {}).get("rescue_attempted"):
                    rescue_marked_dry.append(c)
                else:
                    candidates_dry.append(c)
            selection = _select_review_dispatch_candidates(
                candidates_dry,
                quota_state,
                self.config.review_dispatch,
                reviews_dir,
                self.paths.state_file,
                resolved_now,
                limit,
                probe_mode_dry,
            )
            # Issue #1251: mirror the real path's empty-diff pre-flight gate
            # in the dry-run preview so the two cannot diverge. Read-only:
            # no events emitted, no state mutation.
            dry_selected: list[dict[str, Any]] = []
            dry_skipped_empty_diff: list[int] = []
            for c in selection.selected:
                diff_text = self._read_packet_diff(c["pr"])
                if diff_text is not None and not diff_text.strip():
                    dry_skipped_empty_diff.append(c["pr"])
                else:
                    dry_selected.append(c)
            # Issue #1131: mirror the real path's already-approved pre-claim
            # gate in the dry-run preview so the two cannot diverge. Read-only:
            # no events emitted, no state mutation.
            dry_skipped_already_approved: list[int] = []
            dry_selected_after_approval: list[dict[str, Any]] = []
            for c in dry_selected:
                pr_dir = self.paths.prs / f"pr-{c['pr']}"
                resolved = review_decision(pr_dir, None, c.get("packet_head_sha"))
                if resolved.decision == "approved" and not resolved.stale and not resolved.missing:
                    dry_skipped_already_approved.append(c["pr"])
                else:
                    dry_selected_after_approval.append(c)
            dry_selected = dry_selected_after_approval
            return CommandResult(
                True,
                f"dry-run: would dispatch {len(dry_selected)} reviewer(s)",
                {
                    "selected_count": len(dry_selected),
                    "attempted_count": len(dry_selected),
                    "failed_count": 0,
                    "launched_count": 0,
                    "deferred_count": len(all_candidates) - len(dry_selected),
                    "escalated_skipped": selection.escalated_skipped,
                    "skipped_empty_diff": dry_skipped_empty_diff,
                    "skipped_already_approved": dry_skipped_already_approved,
                    "merge_conflict_routed": [c["pr"] for c in selection.merge_conflict_routed],
                    "rescue_marked_excluded": [c["pr"] for c in rescue_marked_dry],
                    "recorded_verdicts": recorded_verdicts,
                    "missed_verdicts": missed_verdicts,
                    "reconciled_verdicts": reconciled_verdicts,
                    **selection.local_cap.report_fields(),
                },
            )

        # Clear the reviewer quota if any verdicts were recorded from dead
        # reviewers. This is the only proof the quota window is actually open:
        # a process that merely *started* can still die seconds later from an
        # asynchronous session-limit kill. Run before the quota gate so a
        # successful reap clears the throttle and lets the pass proceed.
        # (recorded_verdicts/missed_verdicts are computed above, ahead of the
        # disabled-gate return, so issue #868's disabled payload can report
        # them too.)
        if not self.dry_run and recorded_verdicts:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                if is_reviewer_quota_exhausted(state):
                    state = clear_reviewer_quota(state)
                    # A recorded verdict is proof the provider let a real
                    # review through -- reset the probe backoff so the next
                    # outage starts from the configured base interval again
                    # instead of carrying forward an exponentially-grown one.
                    # Stamp the same recovery marker a green flat probe would,
                    # so a later dead-reviewer reap sweep can suppress backoff
                    # from a throttle signature that predates this recovery
                    # (issue #662). Use microsecond precision for sub-second
                    # comparisons against a dead session's log mtime.
                    state = {
                        **state,
                        "reviewer_quota": {
                            **(state.get("reviewer_quota") or {}),
                            "consecutive_probe_failures": 0,
                            "last_probe_cleared_at": datetime.now(UTC)
                            .isoformat()
                            .replace("+00:00", "Z"),
                        },
                    }
                    self.write_gate.save_state(state)

        # System-wide reviewer quota gate. If the quota is exhausted and we are
        # not yet due to probe again, defer without touching any PR state.
        # When the probe window opens, only one reviewer is launched until the
        # probe succeeds, at which point the global quota is cleared.
        quota_alert: dict[str, Any] | None = None
        deferred = False
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            if is_reviewer_quota_exhausted(state):
                if not is_reviewer_probe_ready(state):
                    deferred = True
                    # Quota deferral is by design, but it must never be silent:
                    # an exhaustion episode that outlives its probe window
                    # stalls the review lane fleet-wide. Alert once per
                    # episode (marker cleared with the quota record on probe
                    # success). The digest is emitted after the lock releases —
                    # sinks may do network I/O.
                    quota = state.get("reviewer_quota") or {}
                    if not quota.get("alerted_at") and self.config.notify.enabled:
                        self.write_gate.save_state(mark_reviewer_quota_alerted(state))
                        quota_alert = dict(quota)
                    probe_mode = False
                else:
                    probe_mode = True
            else:
                probe_mode = False
        if deferred:
            if quota_alert is not None:
                emit_digest(
                    self._layout.notify,
                    AttentionDigest(
                        generated_at=utc_now(),
                        repo=self.repo_root.name,
                        transitions=(
                            AttentionEntry(
                                issue_number=0,
                                adapter_kind="reviewer",
                                health="REVIEWER_QUOTA_EXHAUSTED",
                                previous_health=None,
                                last_log_line=(
                                    f"throttled_until={quota_alert.get('throttled_until')} "
                                    f"probe_after={quota_alert.get('probe_after')}"
                                ),
                                pid=None,
                                terminal_tool=None,
                                terminal_reason=(
                                    "all reviewer launches deferred until the quota probe succeeds"
                                ),
                            ),
                        ),
                    ),
                )
            # Rescue tier (issue #555): the quota gate above governs Claude-
            # family reviewer launches only. Rescue reviews run on the
            # cross-family (Devin) adapter via _process_rescue_review and do
            # not consume Claude quota, so a Claude quota deferral must not
            # freeze them. Still compute the queue and process the rescue
            # partition here; the deferred result below covers normal
            # candidates only, unchanged from before this fix.
            deferred_queue_result = self.review_queue()
            deferred_candidates = deferred_queue_result.data.get("queue", [])
            _deferred_normal, deferred_rescue_results = self._partition_rescue_candidates(
                deferred_candidates
            )
            return CommandResult(
                True,
                "review dispatch deferred: reviewer quota exhausted, probe not ready",
                {
                    "selected_count": 0,
                    "attempted_count": 0,
                    "failed_count": 0,
                    "launched_count": 0,
                    "deferred_reason": "reviewer_quota_probe_backoff",
                    "recorded_verdicts": recorded_verdicts,
                    "missed_verdicts": missed_verdicts,
                    "reconciled_verdicts": reconciled_verdicts,
                    "rescue_review_results": deferred_rescue_results,
                },
            )

        queue_result = self.review_queue()
        candidates = queue_result.data.get("queue", [])
        if not candidates:
            return CommandResult(
                True,
                "review dispatch: no candidates",
                {
                    "selected_count": 0,
                    "attempted_count": 0,
                    "failed_count": 0,
                    "launched_count": 0,
                    "recorded_verdicts": recorded_verdicts,
                    "missed_verdicts": missed_verdicts,
                    "reconciled_verdicts": reconciled_verdicts,
                },
            )

        # Rescue tier (issue #555): a rescue-marked PR's review must run
        # through the cross-family rescue reviewer (_process_rescue_review),
        # never a normal same-family Claude reviewer -- the exit-to-human-on-
        # request_changes rule only holds if this replaces, rather than
        # precedes, the normal dispatch below. Partitioned out here, before
        # any of the normal claim/quota machinery runs on these PRs. Routing
        # keys on the durable rescue_attempted marker alone (never on
        # self.config.rescue.enabled -- see _partition_rescue_candidates).
        candidates, rescue_review_results = self._partition_rescue_candidates(candidates)
        if not candidates:
            return CommandResult(
                True,
                f"review dispatch: {len(rescue_review_results)} rescue review(s) "
                "processed, no normal candidates",
                {
                    "selected_count": 0,
                    "attempted_count": 0,
                    "failed_count": 0,
                    "launched_count": 0,
                    "recorded_verdicts": recorded_verdicts,
                    "missed_verdicts": missed_verdicts,
                    "reconciled_verdicts": reconciled_verdicts,
                    "rescue_review_results": rescue_review_results,
                },
            )

        # Issue #617 rework: the PR-selection logic (escalated-skip,
        # merge-conflict routing, dispatchable-list construction,
        # local/concurrent cap computation) is shared with the dry-run branch
        # via _select_review_dispatch_candidates, so the two copies cannot
        # diverge. The read-only selection runs first; the attempt-cap
        # escalation (which mutates state) runs separately below. At-cap PRs
        # are filtered by _is_review_dispatchable regardless of whether they
        # have already been escalated, so the dispatchable list is stable
        # across the escalation mutation.
        #
        # Route merge-conflicting PRs to rework instead of dispatching a
        # reviewer (issue #1497): a CONFLICTING PR sitting in
        # ``agent:reviewing`` with a current packet would otherwise be
        # dispatched every pass, but the reviewer's verdict cannot merge —
        # and if the PR never reaches the merge lane (e.g. no verdict is
        # ever recorded), ``review()``'s own janitor-gate conflict route
        # never runs either, so the PR sits in ``agent:reviewing`` forever
        # with zero dispatch events. Routing here mirrors ``review()``'s
        # janitor-gate merge-conflict path
        # (``_route_janitor_gate_failure_to_rework`` with
        # ``reason="merge_conflict"``), including the same attempt cap and
        # escalation to ``agent:human-needed``.
        max_attempts = self.config.review_dispatch.max_review_dispatch_attempts
        # Issue #1439: backstop cap on consecutive turn-limit misses.
        max_turn_limit_misses = self.config.review_dispatch.max_consecutive_turn_limit_misses
        # Issue #586's repair set used to be collected here, from the PRs this
        # candidate loop skipped. Issue #1088: that made the sweep unreachable,
        # because this loop runs below the ``review_dispatch.enabled`` early
        # return and both deployed fleets run that flag false -- the set was
        # always empty. The repair now derives its own subjects from state in
        # ``_repair_escalated_labels()``, called above that early return.
        selection_state = load_state_locked(self.paths.state_file)
        selection = _select_review_dispatch_candidates(
            candidates,
            selection_state,
            self.config.review_dispatch,
            reviews_dir,
            self.paths.state_file,
            resolved_now,
            limit,
            probe_mode,
        )
        escalated_skipped = selection.escalated_skipped
        merge_conflict_routed = selection.merge_conflict_routed
        dispatchable = selection.dispatchable
        local_cap = selection.local_cap
        selected = selection.selected

        # Issue #1251: pre-flight empty-diff gate. A PR whose diff.patch is
        # empty (zero-file diff vs base) must not burn a paid reviewer
        # session reviewing nothing. The packet build (review()) already
        # fetches and writes diff.patch; an empty patch is the signal. Skip
        # dispatch for these PRs and emit review_dispatch_skipped_empty_diff
        # instead of claiming. review_dispatch_attempt_count is NOT incremented --
        # an empty diff is not a review attempt and must not walk toward
        # escalation. Do not auto-close the PR from this path; closing is a
        # separate judgment (the #1221 fix owns the duplicate-PR lifecycle).
        # A missing diff.patch is NOT treated as empty -- that is a missing
        # packet (a different problem), not a zero-delta PR.
        skipped_empty_diff: list[int] = []
        skipped_empty_diff_issues: dict[int, int | None] = {}
        selected_with_diff: list[dict[str, Any]] = []
        for c in selected:
            diff_text = self._read_packet_diff(c["pr"])
            if diff_text is not None and not diff_text.strip():
                skipped_empty_diff.append(c["pr"])
                skipped_empty_diff_issues[c["pr"]] = c.get("issue")
            else:
                selected_with_diff.append(c)
        selected = selected_with_diff
        if skipped_empty_diff:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for pr_number in skipped_empty_diff:
                    state = self.write_gate.record_event(
                        state,
                        "review_dispatch_skipped_empty_diff",
                        {
                            "pr_number": pr_number,
                            "issue_number": skipped_empty_diff_issues.get(pr_number),
                        },
                        level="warning",
                    )
                self.write_gate.save_state(state)

        # Issue #1131: re-check the decision file at claim time. review_queue's
        # snapshot can be stale when a dispatch pass interleaves with an
        # operator unescalate->approve->merge: the queue was built before the
        # approved verdict was recorded, so an already-approved PR reaches
        # claim time looking reviewable (unescalation cleared
        # ``review_dispatch_status`` and removed ``agent:human-needed``, and
        # ``_is_review_dispatchable`` keys off those, not the decision file).
        # Skip any PR whose decision file now records an approval for the head
        # this pass would review -- launching a fresh paid reviewer is
        # redundant, and a late request_changes from that reviewer clobbers
        # the merge-authorizing decision file (issue #1131). Mirrors the
        # empty-diff gate above: a read-only pre-claim filter that emits an
        # event and never increments ``review_dispatch_attempt_count`` (an
        # already-approved PR is not a review attempt). ``packet_head_sha`` is
        # the head the reviewer would read; for every queued candidate
        # review_queue already verified it equals the live head, so an
        # approval pinned to it is an approval for the live head.
        skipped_already_approved: list[int] = []
        skipped_already_approved_issues: dict[int, int | None] = {}
        skipped_already_approved_heads: dict[int, str | None] = {}
        selected_not_approved: list[dict[str, Any]] = []
        for c in selected:
            pr_number = c["pr"]
            packet_head = c.get("packet_head_sha")
            pr_dir = self.paths.prs / f"pr-{pr_number}"
            resolved = review_decision(pr_dir, None, packet_head)
            if resolved.decision == "approved" and not resolved.stale and not resolved.missing:
                skipped_already_approved.append(pr_number)
                skipped_already_approved_issues[pr_number] = c.get("issue")
                skipped_already_approved_heads[pr_number] = packet_head
            else:
                selected_not_approved.append(c)
        selected = selected_not_approved
        if skipped_already_approved:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for pr_number in skipped_already_approved:
                    state = self.write_gate.record_event(
                        state,
                        "review_dispatch_skipped_already_approved",
                        {
                            "pr_number": pr_number,
                            "issue_number": skipped_already_approved_issues.get(pr_number),
                            "reviewed_head_sha": skipped_already_approved_heads.get(pr_number),
                        },
                        level="warning",
                    )
                self.write_gate.save_state(state)

        # Escalate PRs whose dispatch attempt count has reached the cap.
        # These PRs are stuck (every reviewer died without a verdict) and
        # must not be re-dispatched indefinitely. Mark them escalated so a
        # human can intervene, mirroring the rework-cycle escalation pattern.
        # The shared helper already classified escalated-skip and
        # merge-conflict-routed PRs read-only; this loop only considers the
        # remaining candidates, skipping live in-flight reviewers (issue
        # #573) so a mid-session verdict is not orphaned. Escalation gate
        # (issue #575): an already-escalated PR is in ``escalated_skipped``
        # and skipped here too, so an issue escalated by an independent path
        # does not get a second bogus "max_review_dispatch_attempts_exceeded"
        # escalation on top of it.
        escalated_for_labels: list[tuple[int, int | None]] = []
        escalated_skipped_set = set(escalated_skipped)
        merge_conflict_pr_set = {c["pr"] for c in merge_conflict_routed}
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            changed = False
            for c in candidates:
                if c["pr"] in escalated_skipped_set or c["pr"] in merge_conflict_pr_set:
                    continue
                pr_key = str(c["pr"])
                pr_state = state["prs"].get(pr_key, {})
                if pr_state.get(
                    "review_dispatch_status"
                ) == "review_dispatch_dispatched" and _reviewer_pid_alive(pr_state):
                    # Never escalate over a LIVE in-flight reviewer (issue
                    # #573): the cap can be reached by attempts that predate
                    # the current launch (e.g. quota deaths whose rollback
                    # decrement was bypassed), and killing the claim
                    # mid-review orphans the imminent verdict — the reaper
                    # only records verdicts for dispatched claims. Let the
                    # review finish: a recorded verdict resets the counter;
                    # a death is dispositioned by the stalled sweep, after
                    # which the cap escalates honestly on a dead claim.
                    continue
                attempt_count = int(pr_state.get("review_dispatch_attempt_count", 0))
                # Issue #1439: a PR whose consecutive turn-limit miss streak
                # has reached the backstop cap escalates with a distinct
                # reason so the diagnosis points at "reviewer ran out of
                # navigation budget on a monolith" rather than the generic
                # "every reviewer died without a verdict". Both reasons route
                # to ``agent:human-needed`` via the same mechanical edge below.
                _turn_limit_streak = int(pr_state.get("review_turn_limit_miss_streak", 0))
                _escalation_reason: str | None = None
                if (
                    max_turn_limit_misses > 0
                    and _turn_limit_streak >= max_turn_limit_misses
                    and pr_state.get("status") != "escalated"
                ):
                    _escalation_reason = "max_consecutive_turn_limit_misses_exceeded"
                elif attempt_count >= max_attempts and pr_state.get("status") != "escalated":
                    _escalation_reason = "max_review_dispatch_attempts_exceeded"
                if _escalation_reason is not None:
                    issue_num = pr_state.get("issue_number") or c.get("issue")
                    state = _escalate_issue(
                        state,
                        issue_num,
                        reason=_escalation_reason,
                        reason_class="mechanical",
                        pr_number=int(c["pr"]),
                        pr_extra={
                            "review_dispatch_status": "review_dispatch_failed",
                            "review_dispatch_failed_at": utc_now(),
                            "review_dispatch_pending_at": None,
                            "review_dispatched_at": None,
                            "reviewer_pid": None,
                            "reviewer_process_start_time": None,
                        },
                    )
                    state = self.write_gate.append_event(
                        state,
                        "review_dispatch_escalated",
                        {
                            "pr_number": c["pr"],
                            "issue_number": issue_num,
                            "attempt_count": attempt_count,
                            "reason": _escalation_reason,
                            # Issue #1439: surface the streak that drove the
                            # turn-limit backstop escalation for diagnosis.
                            "turn_limit_miss_streak": _turn_limit_streak,
                        },
                    )
                    changed = True
                    escalated_for_labels.append((int(c["pr"]), issue_num))
            if changed:
                self.write_gate.save_state(state)

        # Apply the human-needed label edge for each fresh escalation, outside
        # the state lock (transition() makes GitHub API calls). This was the
        # one escalation call site that skipped the label edge entirely,
        # leaving PRs escalated in state.json but invisible on GitHub
        # (pr-lifecycle.md: PRs 548/540/531 live escalated-without-label).
        # Mirrors the dead-rework-session sibling: label_error is recorded on
        # the issue entry when the transition does not fully apply. On success
        # label_error is explicitly set to None so the self-heal loop below
        # can distinguish "edge applied and verified" from "edge never
        # attempted" (absent key, e.g. a pre-#556 escalation).
        # Gated by dry_run: --dry-run must not perform live GitHub label
        # mutations or state.json writes (review finding on PR #670).
        if not self.dry_run:
            # Issue #1266: every producer feeding escalated_for_labels above
            # escalates with reason_class="mechanical" (max_review_dispatch_
            # attempts_exceeded is a process-attempt-cap limit, never a
            # judgment call), so the edge is resolved once for the batch.
            escalated_edge = _escalation_edge("escalated", "mechanical")
            escalated_label_outcomes: list[tuple[int, dict[str, Any] | None]] = []
            for _pr_num, issue_num in escalated_for_labels:
                if issue_num is None:
                    continue
                result = self.write_gate.transition(
                    self.gh, self.config.labels, int(issue_num), escalated_edge
                )
                if result.outcome != TransitionOutcome.APPLIED:
                    escalated_label_outcomes.append(
                        (
                            int(issue_num),
                            {
                                "edge": escalated_edge,
                                "outcome": result.outcome.value,
                                "add_failures": result.add_failures,
                                "remove_failures": result.remove_failures,
                            },
                        )
                    )
                else:
                    escalated_label_outcomes.append((int(issue_num), None))
            if escalated_label_outcomes:
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    for issue_num, label_error in escalated_label_outcomes:
                        entry = state["issues"].get(str(issue_num), {})
                        state["issues"][str(issue_num)] = {
                            **(entry if isinstance(entry, dict) else {}),
                            "number": issue_num,
                            "label_error": label_error,
                        }
                    self.write_gate.save_state(state)

        # Issue #1497: route merge-conflicting candidates to rework outside the
        # state lock. ``_route_janitor_gate_failure_to_rework`` acquires its own
        # ``state_lock`` and calls ``transition()`` (GitHub API), so it cannot
        # run inside the critical section above. This mirrors ``review()``'s
        # janitor-gate merge-conflict path exactly — same ``reason``,
        # same ``attempts_key``, same ``max_attempts`` cap, same escalation to
        # ``agent:human-needed`` when the cap is exceeded — so a CONFLICTING PR
        # discovered by either path converges to the same state. The method is
        # idempotent: if a rework is already pending it returns ``None`` (no-op),
        # and if the lane's own cap already escalated it returns ``None`` too.
        # Gated by dry_run: --dry-run must not perform live GitHub label
        # mutations or state.json writes (same gate as the escalation label
        # edge above).
        merge_conflict_results: list[dict[str, Any]] = []
        if merge_conflict_routed and not self.dry_run:
            for c in merge_conflict_routed:
                pr_number = int(c["pr"])
                issue_num = c.get("issue")
                if issue_num is None:
                    continue
                pr = self.gh.pr_view(pr_number)
                if pr is None:
                    continue
                # Re-check mergeable from the fresh pr_view: pr_list's
                # ``mergeable`` can be UNKNOWN (GitHub computes it
                # asynchronously), and the conflict may have resolved between
                # the queue build and now. ``mergeStateStatus == "DIRTY"`` from
                # pr_list is already a reliable signal, but pr_view's
                # ``mergeable`` is the authoritative reading.
                if not self._is_merge_conflict(pr):
                    continue
                routed = self._route_janitor_gate_failure_to_rework(
                    pr,
                    issue_num,
                    attempts_key="conflict_rework_attempts",
                    max_attempts=self.config.review.max_conflict_rework_attempts,
                    reason="merge_conflict",
                    router=self._request_merge_conflict_rework,
                )
                if routed is not None:
                    merge_conflict_results.append(
                        {
                            "pr": pr_number,
                            "issue": issue_num,
                            "routed_to_rework": routed.data.get("routed_to_rework", False),
                            "escalated": routed.data.get("escalated", False),
                            "rescue_dispatched": routed.data.get("rescue_dispatched", False),
                        }
                    )

        # Claim the selected PRs as pending before launching. This is the only
        # place that writes review_dispatch_pending; the upgrade happens after
        # each launch so a crash between claim and upgrade is recoverable via
        # the stale-claim timeout. Named distinctly from `now`/`resolved_now`
        # above (issue #828's injectable clock) -- this is a write-time stamp,
        # not a staleness-comparison read, and utc_now() returns a formatted
        # string rather than a datetime.
        claim_stamp = utc_now()
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            review_effort_assignments: list[dict[str, Any]] = []
            # Single source of truth for the review_effort experiment arm:
            # resolved ONCE here at claim time and threaded through to the
            # launch call below via resolved_review_effort, so the launch
            # uses exactly this value instead of re-deriving it (agreement
            # by construction, not by convention).
            resolved_review_efforts: dict[int, str] = {}
            # Issue #1439: resolve the structure-aware turn cap ONCE here at
            # claim time (mirroring resolved_review_efforts) and thread it
            # through to the launch call below, so the cap the reviewer runs
            # with is the cap recorded on the claim -- not a re-derivation that
            # could diverge if the miss streak changes between claim and launch.
            resolved_review_turn_caps: dict[int, int] = {}
            for candidate in selected:
                pr_number = candidate["pr"]
                pr_state = state["prs"].get(str(pr_number), {})
                attempt_count = int(pr_state.get("review_dispatch_attempt_count", 0))
                review_effort_used, review_effort_arm = resolve_review_effort(
                    pr_number, self.config.review_dispatch, self.config.claude_code
                )
                resolved_review_efforts[pr_number] = review_effort_used
                # Issue #1439: read the structure multiplier stamped into the
                # packet at build time (review()) and the per-PR turn-limit
                # miss streak, then resolve the final cap. A missing packet
                # (e.g. a pre-#1439 packet) yields multiplier 1 -- the base
                # cap, preserving the pre-fix flat budget.
                _structure_mult = self._read_packet_turn_cap_multiplier(pr_number)
                _miss_streak = int(pr_state.get("review_turn_limit_miss_streak", 0))
                _resolved_cap = resolve_review_turn_cap(
                    self.config.review_dispatch.review_max_turns,
                    _structure_mult,
                    _miss_streak,
                    self.config.review_dispatch,
                )
                resolved_review_turn_caps[pr_number] = _resolved_cap
                state["prs"][str(pr_number)] = {
                    **pr_state,
                    "number": pr_number,
                    "issue_number": candidate["issue"],
                    "review_dispatch_status": "review_dispatch_pending",
                    "review_dispatch_pending_at": claim_stamp,
                    "review_dispatched_at": None,
                    "review_dispatch_failed_at": None,
                    "reviewer_pid": None,
                    "reviewer_process_start_time": None,
                    "review_dispatch_attempt_count": attempt_count + 1,
                    "review_turn_limit_summary_posted": False,
                    "review_miss_summary_posted": False,
                    "review_effort_arm": review_effort_arm,
                    "review_effort_used": review_effort_used,
                    # Issue #1439: record the resolved cap on the dispatch
                    # record so the launch and any post-mortem read the same
                    # value without re-deriving it.
                    "review_turn_cap": _resolved_cap,
                }
                review_effort_assignments.append(
                    {
                        "pr_number": pr_number,
                        "review_effort_arm": review_effort_arm,
                        "review_effort_used": review_effort_used,
                        "review_turn_cap": _resolved_cap,
                    }
                )
            if selected:
                state = self.write_gate.append_event(
                    state,
                    "review_dispatch_claim",
                    {
                        "pr_numbers": [c["pr"] for c in selected],
                        "count": len(selected),
                        "review_effort_assignments": review_effort_assignments,
                    },
                )
            self.write_gate.save_state(state)

        # Launch reviewers concurrently: each launch is non-blocking (subprocess.Popen),
        # so this loop quickly spawns all selected processes. Worktree creation
        # is synchronous per-PR but independent across PRs.
        launched: list[dict[str, Any]] = []
        failed: list[dict[str, Any]] = []
        quota_hit = False
        # Captured at the moment a launch-time quota hit is detected so the
        # provider's named reset time (issue #612) can be parsed from it
        # after the loop and used for the fleet-wide backoff target.
        quota_hit_error: str | None = None
        for candidate in selected:
            pr_number = candidate["pr"]
            issue_number = candidate["issue"]
            pr_dir = self.paths.prs / f"pr-{pr_number}"
            prompt_path = pr_dir / "review-prompt.md"
            try:
                if not prompt_path.exists():
                    failed.append(
                        {
                            "pr": pr_number,
                            "error": "review-prompt.md not found",
                        }
                    )
                    continue

                pr = self.gh.pr_view(pr_number)
                if not pr:
                    failed.append({"pr": pr_number, "error": f"PR #{pr_number} not found"})
                    continue

                branch = str(pr.get("headRefName", ""))
                if not branch:
                    failed.append({"pr": pr_number, "error": "PR headRefName missing"})
                    continue

                head_sha = pr.get("headRefOid")
                if not head_sha:
                    failed.append({"pr": pr_number, "error": "PR headRefOid missing"})
                    continue

                # Cross-repo PRs are never linked for lifecycle purposes by
                # linked_issue_number, so the only way we see one here is an
                # unexpected state; strip an owner prefix defensively.
                if ":" in branch:
                    branch = branch.split(":", 1)[1]

                prompt_text = prompt_path.read_text(encoding="utf-8")
                claude_cfg = self.config.claude_code
                # Reviewers never use worktrees_dir/venv_source — those key
                # the worker's branch-slug worktree, which create_review_checkout
                # (routed to via review=True + head_sha) never touches. Only
                # repo_root/sessions_dir/env/materialize_dirs/review/head_sha
                # are meaningful for a reviewer launch. `claude_cfg.command`
                # is deliberately NOT forwarded here: it is a worker-tuning
                # field, and launch_claude_worker(review=True, ...) hard-pins
                # the read-only command template regardless of what is passed
                # for command_template, so passing it through would be
                # misleading dead code (PR #397 round-2 review).
                #
                # `config` IS forwarded (unlike the above): launch_claude_worker
                # falls back to a bare default OrchestratorConfig() whenever
                # config is omitted, which was silently discarding every
                # review-only pin (review_effort, review_max_turns, and the
                # review_effort experiment) at the one real dispatch_reviews()
                # launch site — the effort/max-turns pins only ever worked in
                # direct launch_claude_worker(config=...) unit tests, never in
                # an actual dispatch pass. adapters.py's worker-dispatch path
                # (_run_claude_code_adapter) already forwards config the same
                # way.
                launch_kwargs: dict[str, Any] = {
                    "repo_root": self.repo_root,
                    "sessions_dir": reviews_dir,
                    "config": self.config,
                    "env": claude_cfg.worker_env,
                    "materialize_dirs": self.config.dispatch.materialize_dirs,
                    "review": True,
                    "head_sha": head_sha,
                    # Force-enabled for reviewers: the structured events.jsonl
                    # is needed for verdict fallback parsing (issue #540) and
                    # token/turn monitoring. Unlike workers, reviewers always
                    # benefit from the structured output because their verdict
                    # extraction depends on it.
                    "tee_stream_json": True,
                    # The review_effort experiment arm was already resolved
                    # once, above, at claim time (and persisted to state/
                    # telemetry) -- pass it through so launch_claude_worker
                    # uses this value directly instead of re-resolving it.
                    "resolved_review_effort": resolved_review_efforts.get(pr_number),
                    # Issue #1439: structure-aware turn cap resolved at claim
                    # time from the packet's structure multiplier + the per-PR
                    # miss streak. Overrides the flat ``review_max_turns`` so a
                    # PR threading a monolith gets a raised budget and a
                    # turn-limit miss escalates the next dispatch's cap.
                    "max_turns_override": resolved_review_turn_caps.get(pr_number),
                }

                record = launch_claude_worker(
                    issue_number=pr_number,
                    branch=branch,
                    prompt_text=prompt_text,
                    **launch_kwargs,
                )
                if record.error or record.pid is None:
                    error_text = record.error or "launch returned no pid"
                    # A quota failure is a global condition, not a per-PR
                    # failure. Stop the pass immediately so the next probe can
                    # retry once the usage window resets.
                    if (
                        record.error
                        and match_throttle_tail(
                            record.error,
                            self.config.runtime.throttle_error_markers,
                        )[0]
                    ):
                        quota_hit = True
                        quota_hit_error = record.error
                        break
                    failed.append({"pr": pr_number, "error": error_text})
                else:
                    launched.append(
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "pid": record.pid,
                            "process_start_time": record.process_start_time,
                        }
                    )
            except (OSError, GitHubError, ValueError) as exc:
                failed.append({"pr": pr_number, "error": f"{type(exc).__name__}: {exc}"})

        # Upgrade claims outside the launch loop. Successful launches become
        # review_dispatch_dispatched. A quota failure rolls back the claim so
        # the PR is not wedged by a global condition; it remains dispatchable
        # once quota is available. Non-quota failures become
        # review_dispatch_failed.
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            launched_prs = {x["pr"] for x in launched}
            failed_prs = {x["pr"] for x in failed}
            for candidate in selected:
                pr_number = candidate["pr"]
                issue_number = candidate["issue"]
                pr_state = state["prs"].get(str(pr_number), {})
                if pr_number in launched_prs:
                    launch_info = next(x for x in launched if x["pr"] == pr_number)
                    state["prs"][str(pr_number)] = {
                        **pr_state,
                        "number": pr_number,
                        "issue_number": issue_number,
                        "review_dispatch_status": "review_dispatch_dispatched",
                        "review_dispatched_at": utc_now(),
                        "review_dispatch_pending_at": None,
                        "review_dispatch_failed_at": None,
                        # A successful launch supersedes any earlier failure:
                        # without this reset the last error string is carried
                        # forward verbatim by the **pr_state spread forever.
                        "review_dispatch_error": None,
                        "reviewer_pid": launch_info["pid"],
                        "reviewer_process_start_time": launch_info["process_start_time"],
                    }
                elif pr_number in failed_prs:
                    fail_info = next(x for x in failed if x["pr"] == pr_number)
                    failed_state = {
                        **pr_state,
                        "number": pr_number,
                        "issue_number": issue_number,
                        "review_dispatch_status": "review_dispatch_failed",
                        "review_dispatch_failed_at": utc_now(),
                        "review_dispatch_pending_at": None,
                        "review_dispatched_at": None,
                        "reviewer_pid": None,
                        "reviewer_process_start_time": None,
                    }
                    failed_state["review_dispatch_error"] = fail_info["error"]
                    state["prs"][str(pr_number)] = failed_state
                else:
                    # Quota failure (or not reached due to break) — roll back
                    # the pending claim so the PR stays dispatchable. Also
                    # decrement the attempt counter: no reviewer actually ran,
                    # so this global condition must not consume the per-PR
                    # dispatch attempt budget (3 quota hits would otherwise
                    # escalate a PR that was never reviewed).
                    rolled_back = without_review_dispatch_claim(pr_state)
                    attempt_count = int(pr_state.get("review_dispatch_attempt_count", 0))
                    if attempt_count > 0:
                        rolled_back["review_dispatch_attempt_count"] = attempt_count - 1
                    state["prs"][str(pr_number)] = rolled_back

            if quota_hit:
                now_dt = datetime.now(UTC)
                # Issue #612: parse the provider's named reset clock time
                # from the launch error (e.g. "resets 1:20am
                # (America/Los_Angeles)") so the backoff targets the stated
                # reset instead of a fixed quota_reset_hours guess.
                reset_at = (
                    parse_reset_clock_time(quota_hit_error, now_dt) if quota_hit_error else None
                )
                state, quota_record = _set_reviewer_quota_exhausted_with_backoff(
                    state, self.config, now_dt, reset_at=reset_at
                )
                # Distinct, queryable event for a launch-time quota hit
                # (issue #612): mirrors the stalled-sweep event so a quota
                # exhaustion is diagnosable from either detection path.
                #
                # Routed through self.write_gate (issue #1264, W6 PR2) rather
                # than a bare append_event: this whole block sits under
                # ``with state_lock(...)`` with no local dry_run check of its
                # own -- the only thing keeping it from running under
                # dry_run=True today is the exhaustive early return several
                # hundred lines above, in a different branch of this same
                # method. Gate-internal checking makes that protection
                # structural instead of relying on the distant guard staying
                # correct (R7).
                state = self.write_gate.append_event(
                    state,
                    "review_quota_exhausted",
                    {
                        "throttled_until": quota_record.get("throttled_until"),
                        "probe_after": quota_record.get("probe_after"),
                        "reset_at": quota_record.get("reset_at"),
                        "consecutive_probe_failures": quota_record.get(
                            "consecutive_probe_failures"
                        ),
                        "source": "launch_quota_hit",
                    },
                )

            state = self.write_gate.append_event(
                state,
                "review_dispatch",
                {
                    "launched": [x["pr"] for x in launched],
                    "failed": [x["pr"] for x in failed],
                    "quota_hit": quota_hit,
                },
            )
            self.write_gate.save_state(state)

        ok = not failed and not quota_hit

        message = f"review dispatch: {len(launched)} launched, {len(failed)} failed"
        if recorded_verdicts or missed_verdicts:
            message += (
                f"; {len(recorded_verdicts)} verdict(s) recorded, {len(missed_verdicts)} missed"
            )
        if quota_hit:
            message = (
                f"review dispatch: reviewer quota hit after {len(launched)} "
                f"launched; will probe again later"
            )
        elif failed:
            message = (
                f"review dispatch completed with {len(failed)} failure(s): "
                f"{len(launched)} launched"
            )

        data: dict[str, Any] = {
            "selected_count": len(selected),
            "attempted_count": len(selected),
            "launched_count": len(launched),
            "failed_count": len(failed),
            "failed": failed,
            "quota_hit": quota_hit,
            "probe_mode": probe_mode,
            "skipped_count": len(dispatchable) - len(selected),
            "deferred_count": len(candidates) - len(dispatchable),
            "escalated_skipped": escalated_skipped,
            "skipped_empty_diff": skipped_empty_diff,
            "skipped_already_approved": skipped_already_approved,
            "merge_conflict_results": merge_conflict_results,
            "recorded_verdicts": recorded_verdicts,
            "missed_verdicts": missed_verdicts,
            "reconciled_verdicts": reconciled_verdicts,
            "rescue_review_results": rescue_review_results,
            "escalated_labels_repaired": repaired_labels,
        }
        data.update(local_cap.report_fields())
        return CommandResult(ok, message, data)

    def _partition_rescue_candidates(
        self, candidates: list[dict[str, Any]]
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """Split ``review_queue()`` candidates into normal vs rescue-marked
        (issue #555), and process the rescue ones via ``_process_rescue_review``.

        Routing keys on the durable ``rescue_attempted`` marker ALONE, never
        on ``self.config.rescue.enabled``: an operator flipping ``enabled``
        off while a rescue is in flight must not cause an already-marked PR
        to fall through to a normal same-family reviewer, or (on a later
        request_changes) to the legacy escalation path without the two
        rescue artifacts. ``enabled`` only gates NEW rescue entry at the
        three cap sites (record_review / _route_janitor_gate_failure_to_
        rework) — routing of PRs that already carry the marker is
        unconditional.

        A rescue-marked PR whose ``pr_state["status"] == "escalated"`` is
        dropped entirely — not processed again, not returned as a normal
        candidate either. ``_process_rescue_review``'s escalation write does
        not advance the review packet's recorded decision, so
        ``review_queue()`` would otherwise keep requeuing it every pass,
        re-running the (blocking, up to ``reviewer_timeout_seconds``)
        cross-family review, reposting the escalation PR comment, and
        re-firing ``rescue_review_escalated`` forever.
        """
        rescue_snapshot = load_state_locked(self.paths.state_file)
        normal_candidates: list[dict[str, Any]] = []
        rescue_review_results: list[dict[str, Any]] = []
        for c in candidates:
            pr_state = rescue_snapshot.get("prs", {}).get(str(c["pr"]), {})
            if not pr_state.get("rescue_attempted"):
                normal_candidates.append(c)
                continue
            if pr_state.get("status") == "escalated":
                continue
            result = self._process_rescue_review(c)
            rescue_review_results.append({"pr": c["pr"], **result.data})
        return normal_candidates, rescue_review_results

    def _process_rescue_review(self, candidate: dict[str, Any]) -> CommandResult:
        """Run the cross-family rescue review for one rescue-marked PR
        (issue #555) and apply the rescue tier's exit semantics.

        Called from ``dispatch_reviews()`` INSTEAD of the normal Claude
        reviewer dispatch for any candidate whose PR record already carries
        ``rescue_attempted`` — i.e. its rescue rework was already dispatched
        (via the normal rework-dispatch path, just adapter/model-overridden;
        see ``_rescue_adapter_settings``) and has since pushed a new head.

        Synchronous and one-shot (mirrors ``run_cross_family_review``'s own
        contract): no new polling/reaping machinery is introduced. Exit
        semantics per the issue spec:

        - ``approved`` -> recorded through the SAME entry point normal
          reviews use (``record_review``), so the existing ship-it/merge
          path takes over exactly as it would for a normal approval.
        - ``request_changes``/``blocked``/unparseable report -> escalates to
          a human immediately (never loops back into another rework cycle):
          both artifacts (the rescue PR/diff — this PR's current branch and
          head SHA, since the rescue worker pushed directly to it — and the
          cross-family report path) are attached to the escalation event
          payload and posted as a PR comment.
        """
        pr_number = int(candidate["pr"])
        issue_number = candidate.get("issue")

        # Issue #618: short-circuit in dry-run BEFORE any writes or mutations.
        # Threading dry_run to run_cross_family_review alone is actively
        # harmful here: the dry-run branch returns a synthetic failure
        # (ok=False), which drives this function into its escalation arm and
        # would mark a PR escalated during a preview. The short-circuit
        # avoids the mkdir, the cross-family subprocess, the state/label
        # escalation write, and the PR comment entirely.
        if self.dry_run:
            return CommandResult(
                True,
                f"dry-run: would run rescue review for PR #{pr_number}",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "rescue_review_decision": "dry-run",
                    "dry_run": True,
                },
            )

        pr = self.gh.pr_view(pr_number)
        head_sha = str(pr.get("headRefOid") or "")
        branch = str(pr.get("headRefName") or "")
        pr_state = load_state_locked(self.paths.state_file).get("prs", {}).get(str(pr_number), {})
        cause = str(pr_state.get("rescue_cause") or "unknown")

        pr_dir = self.paths.prs / f"pr-{pr_number}"
        pr_dir.mkdir(parents=True, exist_ok=True)
        diff_text = self.gh.pr_diff(pr_number) or ""
        prompt_text = rescue_helpers.build_rescue_review_prompt(
            pr_number=pr_number,
            issue_number=issue_number,
            branch=branch,
            diff_text=diff_text,
            cause=cause,
        )
        prompt_path = pr_dir / "rescue-review-prompt.md"
        report_path = pr_dir / "rescue-review-report.md"
        cfg = self.config.rescue
        cf_result = run_cross_family_review(
            model=cfg.reviewer_model,
            command=cfg.reviewer_command or self.config.cross_family.command,
            repo_root=self.repo_root,
            prompt_text=prompt_text,
            prompt_path=prompt_path,
            report_path=report_path,
            timeout_seconds=cfg.reviewer_timeout_seconds,
            head_ref_oid=head_sha,
        )

        verdict: dict[str, Any] | None = None
        if cf_result.ok and report_path.exists():
            report_text = extract_report_body(report_path.read_text(encoding="utf-8"))
            verdict = _extract_verdict_from_text(report_text)

        if verdict is not None and verdict["decision"] == "approved":
            result = self.record_review(
                pr_number,
                "approved",
                summary=verdict["summary"],
                reviewed_head=head_sha,
                required_changes=verdict["required_changes"],
                verdict_provenance="rescue_review",
            )
            return CommandResult(
                True,
                f"PR #{pr_number} rescue review approved — {result.message}",
                {
                    "rescue_review_decision": "approved",
                    "cross_family_report": str(report_path),
                    "record_review": result.data,
                },
            )

        # request_changes / blocked / unparseable report -> escalate to a
        # human immediately. Never re-enter the rework loop: this PR already
        # spent its one rescue attempt (rescue_attempted stays durably set).
        verdict_summary = verdict["summary"] if verdict else (cf_result.error or "")
        comment_body = rescue_helpers.build_rescue_escalation_comment(
            cause=cause,
            rescue_branch=branch,
            rescue_head_sha=head_sha,
            cross_family_report_path=str(report_path),
            verdict_summary=verdict_summary,
        )
        label_error: dict[str, Any] | None = None
        # Issue #783: an explicit "blocked" rescue verdict is the same kind of
        # human product/security decision as record_review's "blocked" path
        # -- judgment, never auto-cleared. "request_changes" and an
        # unparseable/failed cross-family report both escalate only because
        # the rescue tier structurally cannot loop again (one-shot, no
        # further rework cycle) -- that is a process limit, not a judgment
        # call, so it is mechanical and eligible for re-evaluation.
        rescue_reason_class = (
            "judgment"
            if verdict is not None and verdict["decision"] == "blocked"
            else "mechanical"
        )
        rescue_escalation_reason = f"rescue_review_{cause}"
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            state = _escalate_issue(
                state,
                issue_number,
                reason=rescue_escalation_reason,
                reason_class=rescue_reason_class,
                pr_number=pr_number,
            )
            state = self._record_event(
                state,
                "rescue_review_escalated",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "cause": cause,
                    "rescue_branch": branch,
                    "rescue_head_sha": head_sha,
                    "cross_family_report": str(report_path),
                    "cross_family_ok": cf_result.ok,
                    "verdict_decision": verdict["decision"] if verdict else None,
                },
            )
            save_state(self.paths.state_file, state)
        if issue_number is not None:
            rescue_edge = _escalation_edge("escalated", rescue_reason_class)
            result = transition(self.gh, self.config.labels, int(issue_number), rescue_edge)
            if result.outcome != TransitionOutcome.APPLIED:
                label_error = {
                    "edge": rescue_edge,
                    "outcome": result.outcome.value,
                    "add_failures": result.add_failures,
                    "remove_failures": result.remove_failures,
                }
        try:
            self._comment_pr(pr_number, comment_body)
        except GitHubError as exc:
            label_error = {**(label_error or {}), "comment_error": str(exc)}
        return CommandResult(
            True,
            f"PR #{pr_number} rescue review did not approve — escalated to human",
            {
                "rescue_review_decision": verdict["decision"] if verdict else "unparseable",
                "cross_family_report": str(report_path),
                "cross_family_ok": cf_result.ok,
                "escalated": True,
                "label_error": label_error,
            },
        )

    def record_review(
        self,
        pr_number: int,
        decision: str,
        summary: str = "",
        summary_file: Path | None = None,
        comment: bool = False,
        reviewed_head: str | None = None,
        required_changes: Sequence[str] | None = None,
        session_metrics: dict[str, Any] | None = None,
        *,
        verdict_provenance: str,
        allow_stale_head: bool = False,
        verdict_source: str | None = None,
    ) -> CommandResult:
        if decision not in {"approved", "request_changes", "blocked"}:
            return CommandResult(
                False, "decision must be approved, request_changes, or blocked", {}
            )
        # Issue #1265: no default above -- every caller must say where the
        # verdict came from. This membership check catches a garbage/typo'd
        # literal (a missing argument is already caught earlier, at the call
        # boundary, by the keyword-only parameter having no default).
        if verdict_provenance not in VERDICT_PROVENANCE_VALUES:
            return CommandResult(
                False,
                "verdict_provenance must be one of: "
                + ", ".join(sorted(VERDICT_PROVENANCE_VALUES)),
                {},
            )
        summary_text = summary_file.read_text(encoding="utf-8") if summary_file else summary
        # Issue #11: reject empty summary for request_changes/blocked decisions
        # before any state/label mutation
        if decision in {"request_changes", "blocked"} and not summary_text.strip():
            return CommandResult(
                False,
                f"--summary or --summary-file is required for decision '{decision}'",
                {},
            )

        # Issue #792: required_changes has a near-0% fill rate because
        # prompts/review.md historically documented it as optional, so
        # reviewers reliably fill in `summary` and skip the structured list.
        # `_render_required_changes_section` used to paper over this at
        # *render* time, falling back to `summary` when the list was empty --
        # but that runs long after the reviewer is gone and the verdict is
        # frozen, so a bad or missing derivation there can never be
        # corrected. Derive here instead, at the point of record, so
        # whatever `required_changes` lands on disk is exactly what a
        # worker's rework brief will show.
        #
        # This step never *rejects* a verdict for an empty required_changes
        # -- see test_record_review_never_rejects_for_empty_required_changes.
        # A reject path here is the tempting wrong fix and that test is what
        # stops a future session from "tightening" it: a False return writes
        # no review-decision.json, the caller logs review_verdict_missed and
        # moves on, the next pass still sees the PR as pending, and it gets
        # re-dispatched to a fresh reviewer -- an unbounded re-review loop
        # with no cap and no escalation. Contrast with issue #597's reject
        # gate on a contentless *approved* verdict in
        # `_validate_review_verdict`: that gate is safe because rejecting an
        # approval just means "not merged yet", not an infinite loop.
        effective_required_changes = list(required_changes) if required_changes else []
        findings_channel: str | None = None
        if decision in {"request_changes", "blocked"} and not effective_required_changes:
            if _summary_is_vacuous(summary_text):
                # Nothing derivable. Persist the empty list anyway (never
                # reject) with an explicit marker so
                # `_render_required_changes_section` can tell "genuinely
                # nothing was recorded" apart from "the reviewer wrote
                # prose instead of a list" and render its loud tier-3
                # warning instead of silently treating this the same as a
                # real derivation.
                findings_channel = "vacuous"
            else:
                # The F1 extractor: `_render_required_changes_section`'s own
                # tier-2 fallback, lifted here unchanged (issue #792) so the
                # producer -- not a consumer with no way to correct a bad
                # call -- makes this decision. `findings_channel = "derived"`
                # tells the renderer this single item is reviewer prose, not
                # an itemized list, so it renders as prose (tier 2) rather
                # than a one-item bullet list built from a multi-paragraph
                # summary.
                effective_required_changes = [summary_text.strip()]
                findings_channel = "derived"

        pr = self.gh.pr_view(pr_number)
        issue_number = (
            linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if pr
            else None
        )

        # Issue #1131: a terminal-state PR (MERGED or CLOSED) must never have
        # its decision file overwritten or rework routed. The observed race:
        # an operator unescalate->approve->merge interleaved with a dispatch
        # pass, so a reviewer's request_changes landed ~8 minutes after the
        # merge and clobbered ``review-decision.json`` (approved ->
        # request_changes), destroying the audit record that authorized the
        # merge, firing a false unauthorized-merge tripwire, and applying
        # ``agent:needs-rework`` to an already-CLOSED issue. Refuse here --
        # the durable verdict that authorized the merge is preserved, and the
        # late verdict is dropped (the caller logs ``review_verdict_missed``,
        # same as any refused verdict). This is unconditional (not gated on
        # ``allow_stale_head``): even the operator CLI must not overwrite a
        # merge-authorizing decision file. GitHub's PR ``state`` is the
        # authoritative terminal-state signal; ``pr`` is falsy only when
        # ``pr_view`` itself failed, in which case the existing head-resolution
        # logic below fails safe on its own and this guard correctly does not
        # fire on missing data.
        pr_github_state = str(pr.get("state") or "").upper() if pr else ""
        if pr and pr_github_state in ("MERGED", "CLOSED"):
            return CommandResult(
                False,
                f"PR #{pr_number} is {pr_github_state}; verdict not recorded "
                f"(terminal-state PR decision file is preserved)",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "terminal_state": pr_github_state,
                },
            )

        # Escalation is terminal for verdict recording too, mirroring review()'s
        # guard: without this, a late-arriving verdict (a reviewer that finished
        # after the attempt-cap escalation fired, or a stale reap) silently
        # overwrites status="escalated" and re-enters the PR into the pipeline,
        # which is exactly how escalated PRs were observed re-escalating 2-3x
        # (pr-lifecycle.md: non-durable escalation). A human re-arms the PR with
        # `charlie unescalate`, after which verdicts record normally again.
        guard_state = load_state_locked(self.paths.state_file)
        guard_pr_state = guard_state.get("prs", {}).get(str(pr_number), {})
        guard_issue_state = (
            guard_state.get("issues", {}).get(str(issue_number), {})
            if issue_number is not None
            else {}
        )
        if (
            guard_pr_state.get("status") == "escalated"
            or guard_issue_state.get("status") == "escalated"
        ):
            return CommandResult(
                False,
                f"PR #{pr_number} is escalated; verdict not recorded "
                f"(run `charlie unescalate --pr {pr_number}` to re-arm it first)",
                {"pr": pr_number, "issue": issue_number, "escalated": True},
            )

        pr_dir = self.paths.prs / f"pr-{pr_number}"
        pr_dir.mkdir(parents=True, exist_ok=True)

        # reviewed_head_sha/reviewed_patch_id must reflect the packet the reviewer
        # actually read (review()'s pr.json/diff.patch), not a fresh fetch made
        # here at verdict time: a commit landing between packet generation and
        # verdict recording would otherwise silently reattribute the decision to
        # a head/diff that was never reviewed. Fall back to a live fetch only
        # when no packet exists (e.g. a decision recorded without a prior
        # review() call).
        packet_head_sha = self._read_packet_head_oid(pr_number)
        live_head_sha = pr.get("headRefOid") if pr else None

        # Issue #467: do not silently pin a verdict to a stale packet when the PR
        # head has advanced since the packet was generated. If the packet head
        # disagrees with the live PR head, require an explicit --reviewed-head
        # choice. When they agree (or no packet exists), preserve the existing
        # packet-first / live-fallback semantics and record where the SHA came from.
        #
        # Issue #1072: the #467 check only fired when *no* --reviewed-head was
        # passed. When an automated caller (review()'s CI-failure exit,
        # test-adequacy exit, dispatch_reviews, cross-family) passed
        # --reviewed-head matching the packet head, the check was bypassed and
        # the verdict was pinned to a head that had moved mid-build. The
        # compare-and-swap guard added by #1036 covered only review()'s
        # packet-commit tail exit; the two earlier exits returned through
        # record_review() and bypassed it. Pushing the guard here — into the
        # single choke point every verdict write passes through — makes the
        # invariant hold by construction for every caller, not just the one
        # exit #1036 happened to guard. The operator CLI (``charlie verdict``)
        # is the one caller that may legitimately pin to a superseded head
        # (issue #467's explicit-choice design), so it passes
        # ``allow_stale_head=True``; every automated caller uses the default
        # ``False`` and is refused. The failure direction is toward redundant
        # work (the PR is re-reviewed next pass), never toward authorizing a
        # merge on the wrong head — ``reviewed_head_sha`` is compared against
        # the current head by every downstream consumer.
        if reviewed_head is not None:
            if packet_head_sha is not None and reviewed_head == packet_head_sha:
                if (
                    not allow_stale_head
                    and live_head_sha is not None
                    and packet_head_sha != live_head_sha
                ):
                    return CommandResult(
                        False,
                        f"reviewed head ({reviewed_head}) matches packet head "
                        f"({packet_head_sha}) but live PR head has moved to "
                        f"({live_head_sha}); verdict not recorded — head moved "
                        "during build, will re-review next pass",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "reason": "head_moved_during_build",
                            "packet_head_sha": packet_head_sha,
                            "live_head_sha": live_head_sha,
                        },
                    )
                reviewed_head_sha = reviewed_head
                reviewed_head_source = "packet"
            elif live_head_sha is not None and reviewed_head == live_head_sha:
                reviewed_head_sha = reviewed_head
                reviewed_head_source = "live"
            else:
                options: list[str] = []
                if packet_head_sha is not None:
                    options.append(f"packet head {packet_head_sha}")
                if live_head_sha is not None:
                    options.append(f"live head {live_head_sha}")
                options_str = " or ".join(options) if options else "any available head"
                return CommandResult(
                    False,
                    f"--reviewed-head {reviewed_head} does not match {options_str}",
                    {},
                )
        elif (
            packet_head_sha is not None
            and live_head_sha is not None
            and packet_head_sha != live_head_sha
        ):
            return CommandResult(
                False,
                f"review packet head ({packet_head_sha}) differs from live PR head ({live_head_sha}); "
                "use --reviewed-head to choose the head the verdict applies to",
                {},
            )
        elif packet_head_sha is not None:
            reviewed_head_sha = packet_head_sha
            reviewed_head_source = "packet"
        elif live_head_sha is not None:
            reviewed_head_sha = live_head_sha
            reviewed_head_source = "live"
        else:
            return CommandResult(False, "no packet or live PR head available", {})

        # Calculate patch-id for the PR diff to detect actual content changes
        # (issue #222: base-update merges can advance head SHA without changing diff content).
        # All terminal decisions (approved/request_changes/blocked) persist reviewed_patch_id
        # so the review-queue enumerator can carry them forward on content-identical heads.
        # Also record the tier-2 content signature (issue #414): patch-id is
        # unstable across every main advance (the merge-base moves), so the
        # ordered +/- line stream and changed-file set are persisted here,
        # at the moment the diff is freshly known, so a later carry-forward
        # check never needs to reconstruct this historical diff.
        reviewed_patch_id = ""
        reviewed_signature = DiffContentSignature((), frozenset())
        diff: str | None = None
        if pr:
            if reviewed_head_source == "packet":
                diff = self._read_packet_diff(pr_number)
                if diff is None:
                    diff = self.gh.pr_diff(pr_number)
            else:
                diff = self.gh.pr_diff(pr_number)
            reviewed_patch_id = _calculate_patch_id(diff)
            if diff:
                reviewed_signature = _diff_content_signature(diff)

        # Issue #950 / #998: fold non-bot findings from the PR's own external
        # review surfaces into the verdict at write time. This is a live fetch
        # at record_review time, not at render time, so _render_rework_prompt
        # stays a pure function of the durable verdict file.
        #
        # The ingestion window is bounded on both sides by *time*, not by
        # author identity (the orchestrator and workers both post through user
        # tokens, so identity cannot separate their output from a genuine
        # human's -- see ORCHESTRATOR_COMMENT_MARKER and issue #998):
        #   * lower bound ``since``  = the previous round's *upper* bound
        #     (``before``), falling back to its ``reviewed_at`` only when no
        #     ``before`` was recorded -- see the contiguity note below;
        #   * upper bound ``before`` = the current reviewed_head_sha's committer
        #     date -- a worker's own rework reply is posted *after* the rework
        #     commit it describes (which is the head the reviewer is now
        #     reading), so it falls outside the window and is not fed back to
        #     the worker as a "required change". This also closes the
        #     pre-ORCHESTRATOR_COMMENT_MARKER comment gap (#998 comment): those
        #     comments predate every future reviewed_head_sha and are excluded
        #     by the lower bound from the second round on.
        # Both bounds fail toward ingestion when their timestamp is missing or
        # unparsable: losing a genuine human finding is the expensive direction.
        # This block runs after reviewed_head_sha is resolved (and after the
        # --reviewed-head validation that can return early), so the upper bound
        # always reflects the exact head the verdict is pinned to.
        #
        # Contiguity across rounds (issue #998 rework): the next round's
        # ``since`` MUST be this round's ``before``, not this round's
        # ``reviewed_at``. A genuine human comment posted in the gap
        # ``(before, reviewed_at]`` -- between the reviewed head commit landing
        # and the verdict being written -- is excluded by ``before`` this round
        # (item_dt > before). If the next round used ``reviewed_at`` as its
        # ``since``, that comment would satisfy ``item_dt <= reviewed_at`` and
        # be dropped by the lower bound *forever* -- a silent hole in the
        # window that violates the "fail toward ingestion" invariant above.
        # Deriving ``since`` from the previous round's persisted ``before``
        # makes the per-round windows contiguous: every comment falls in
        # exactly one round's ``(since, before]`` window, so nothing is
        # permanently lost. The ``reviewed_at`` fallback is only taken when no
        # ``before`` was recorded -- which happens precisely when the upper
        # bound was not applied (the commit timestamp could not be resolved),
        # so nothing was excluded by ``before`` and ``reviewed_at`` remains the
        # correct lower bound.
        ingestion_before: str | None = None
        # Issue #999: external findings no longer merge into
        # ``required_changes``. They ride in their own ``external_findings``
        # field so ``findings_channel`` keeps describing *only* the reviewer's
        # list -- ``"derived"`` is never overwritten and keeps its tier-2
        # verbatim rendering. The one exception is ``"vacuous"``: a
        # content-free reviewer summary has nothing worth rendering above the
        # external items, so that case still *replaces* ``required_changes``
        # (flipping the channel to ``"external"``) exactly as before #999 --
        # no ``external_findings`` field is written, and the renderer's
        # old-shape ``"external"`` path handles it unchanged.
        recorded_external_findings: list[str] | None = None
        if decision in {"request_changes", "blocked"}:
            previous_decision = self._review_decision(pr_number)
            previous_before = previous_decision.get("before")
            previous_reviewed_at = previous_decision.get("reviewed_at")
            since = (
                previous_before
                if isinstance(previous_before, str) and previous_before
                else (previous_reviewed_at if isinstance(previous_reviewed_at, str) else None)
            )
            before = _commit_timestamp(self.gh, reviewed_head_sha)
            ingestion_before = before
            external_findings = _collect_external_findings(
                self.gh, pr_number, since=since, before=before
            )
            if external_findings:
                if findings_channel == "vacuous":
                    effective_required_changes = list(external_findings)
                    findings_channel = "external"
                else:
                    recorded_external_findings = list(external_findings)
        decision_payload = {
            "pr_number": pr_number,
            "issue_number": issue_number,
            "decision": decision,
            "summary": summary_text,
            "required_changes": effective_required_changes,
            # Issue #1265: unconditional -- every record_review call already
            # requires this argument (no default, see the keyword-only
            # parameter above), so it is always present, never a
            # conditionally-added key the way findings_channel/
            # external_findings are.
            "verdict_provenance": verdict_provenance,
            "reviewed_head_sha": reviewed_head_sha,
            "reviewed_head_source": reviewed_head_source,
            "reviewed_patch_id": reviewed_patch_id,
            "reviewed_changed_lines": list(reviewed_signature.changed_lines),
            "reviewed_changed_files": sorted(reviewed_signature.changed_files),
            "reviewed_has_binary": reviewed_signature.has_binary,
            "carried_forward_from": [],
            "reviewed_at": utc_now(),
        }
        # Only present when the derivation above ran (issue #792): a verdict
        # that already carried a populated required_changes, or an
        # `approved` verdict, passes through with no new key at all.
        if findings_channel is not None:
            decision_payload["findings_channel"] = findings_channel
        # Issue #999: external findings live in their own field, separate
        # from the reviewer's required_changes. Absent on old-shape records
        # (pre-#999, or the vacuous-replace case) -- the renderer treats
        # absence as old-shape and renders exactly as before.
        if recorded_external_findings is not None:
            decision_payload["external_findings"] = recorded_external_findings
        # Persist the ingestion upper bound so the next round's ``since`` can
        # be derived from it (issue #998 rework: contiguous windowing across
        # rounds -- see the contiguity note above). Only present when ingestion
        # actually ran AND the upper bound was resolved; an ``approved`` verdict
        # has no next ingestion round, and a None ``before`` means the upper
        # bound was not applied (so there is nothing for the next round's
        # ``since`` to recover -- it falls back to ``reviewed_at``).
        if ingestion_before is not None:
            decision_payload["before"] = ingestion_before
        # Issue #1340: persist the parser-level provenance (which extractor
        # found the verdict block: "log", "events", "file:<source>") into the
        # decision file so a later reader can distinguish a log-extracted
        # verdict (the reviewer process died before emitting a structured
        # result) from a clean structured completion. Distinct from
        # ``verdict_provenance`` (the mechanism that produced the verdict --
        # "fresh_llm_review", "ci_gate_auto_reject", ...). Only present when a
        # caller supplied it; the reap path threads ``session_metrics``'s
        # ``verdict_source`` here, while direct operator/CI-gate callers leave
        # it absent (no parser was involved).
        if verdict_source is not None:
            decision_payload["verdict_source"] = verdict_source
        decision_path = pr_dir / "review-decision.json"
        # Issue #1268 (W11): per-round archive directory. ``round_number`` is
        # declared here (rather than inside the lock below) so it survives
        # past the lock for later use -- e.g. a comment header rendered after
        # the lock releases needs to reference the same round this call
        # recorded. It is always reassigned inside the lock before use; the
        # 0 default is never observed downstream.
        rounds_dir = pr_dir / "rounds"
        round_number: int = 0
        # Merge-update (never in-place assignment) and persist BEFORE any GitHub
        # label mutation: a label-write failure or crash must not desync the
        # durable decision/counter from what actually happened.
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            rework_path: str | None = None
            # str, not str | None: unlike rework_path (used as-is, Optional,
            # in the returned CommandResult payload), rework_summary is only
            # ever consumed at the _write_rework_prompt call below, whose
            # dispatch_note parameter is a bare `str` (issue #782). A None
            # default would relocate reportPossiblyUnboundVariable into a
            # reportArgumentType mismatch instead of eliminating it. This
            # default is unreachable dead code on every path (see #782):
            # rework_summary is always rebound before use because the
            # binding guard (`if not escalated:`, above the write) and the
            # use guard (`decision == "request_changes" and not escalated`,
            # at the write) are the same conjunction and `escalated` is not
            # reassigned between them.
            rework_summary: str = ""
            escalated = False
            rescue_dispatched = False
            # Durable per-PR rework counter — NOT derived from the global events
            # log, which append_event truncates to the last 200 entries: on a busy
            # repo that eviction silently reset the count and defeated the cap
            # (a PR could rework forever instead of escalating to a human).
            request_changes_count = int(pr_state.get("request_changes_count", 0))
            if decision == "request_changes":
                # Only count a rework cycle when the PR head has actually advanced.
                # If the head is unchanged, the prior cycle's attempt was never
                # delivered (e.g., worker died orphaned), so re-issuing
                # request_changes should not consume the escalation budget. See
                # issue #208.
                #
                # Issue #1210: the head_advanced guard previously protected only
                # the counter increment below — the escalation check ran
                # unconditionally and fired on an at-cap verdict even when the
                # head was unchanged. Gate the escalation evaluation (and the
                # rescue tier, which is itself gated on cap exceedance) on
                # head_advanced as well, so an at-cap verdict on an unchanged
                # head re-issues request_changes without escalating, mirroring
                # what already happens below-cap. Keep the existing behavior for
                # advanced heads.
                head_advanced = reviewed_head_sha != pr_state.get("reviewed_head_sha")
                if head_advanced:
                    # Rework cap: past max_rework_cycles the evidence says
                    # iteration thrashes (wrong brief or unimplementable
                    # criteria) — escalate to a human instead of dispatching
                    # another cycle.
                    escalated = request_changes_count >= self.config.review.max_rework_cycles
                    # Rescue tier (issue #555): a cap exceedance here is one of
                    # the three verdict-driven ("cheap model wasn't good
                    # enough") causes the rescue tier is gated on. If enabled
                    # and this PR has not already spent its one rescue attempt,
                    # route to a bounded Opus rework instead of escalating —
                    # never a second rescue for the same PR (rescue_attempted
                    # is durable, cleared only by `charlie unescalate`).
                    if (
                        escalated
                        and self.config.rescue.enabled
                        and not pr_state.get("rescue_attempted")
                    ):
                        escalated = False
                        rescue_dispatched = True
                    if not escalated:
                        request_changes_count += 1
                if not escalated:
                    rework_summary = (
                        rescue_helpers.build_rescue_rework_summary(
                            "rework_cycle_cap", summary_text
                        )
                        if rescue_dispatched
                        else summary_text
                    )
            decision_payload["escalated"] = escalated
            pr_escalation_reason = (
                "max_rework_cycles_exceeded"
                if (decision == "request_changes" and escalated)
                else ("review_blocked" if decision == "blocked" else None)
            )
            # Persist the verdict BEFORE rendering the rework brief: the brief
            # reads review-decision.json itself (issue #632, single point of
            # enforcement) to surface required_changes, so the decision file
            # must be on disk first. A label-write failure or crash after this
            # point leaves a durable verdict and a brief consistent with it.
            #
            # Issue #934: ``decision_payload`` is a fresh dict that would
            # silently discard an ``authorized_override`` written by
            # ``merge_authorize``. The read-modify-write here is inside the
            # ``state_lock`` (which ``merge_authorize`` also holds), so re-reading
            # the file at this point is atomic against concurrent writers. Carry
            # the override forward so a subsequent ``record_review`` for the same
            # PR does not resurrect the false-positive tripwire finding this PR
            # exists to eliminate.
            if decision_path.exists():
                try:
                    with decision_path.open("r", encoding="utf-8") as _handle:
                        _existing_decision = json.load(_handle)
                    if isinstance(_existing_decision, dict) and isinstance(
                        _existing_decision.get("authorized_override"), dict
                    ):
                        decision_payload["authorized_override"] = _existing_decision[
                            "authorized_override"
                        ]
                except (OSError, json.JSONDecodeError):
                    pass
            # Issue #1268 (W11): archive this round's artifacts before a
            # later round's call can overwrite the live files above in
            # place. round_number is derived from the archive already on
            # disk -- never from pr_state or request_changes_count (see
            # _next_round_number's docstring) -- so a crash between this
            # write and save_state() below cannot desync the round this call
            # recorded from what is actually on disk. Computed here (not just
            # inside record_decision) because round_dir is also the archive
            # target for the rework-prompt/dispatch-note siblings below;
            # record_decision (issue #1362 Stage 2) derives the identical
            # number from the same rounds_dir/decision_payload pair, so the
            # two never disagree.
            round_number = _next_round_number(rounds_dir, decision_payload)
            round_dir = rounds_dir / f"round-{round_number}"
            # Single writer (issue #1362 Stage 2): round-file-then-flat, so a
            # crash between the two writes still leaves a durable, readable
            # verdict via review_decision()'s round-fallback. head_sha=None:
            # decision_payload["reviewed_head_sha"] is already resolved above.
            record_decision(pr_dir, decision_payload, None)
            if decision == "request_changes" and not escalated:
                rework_path = str(self._write_rework_prompt(pr, issue_number, rework_summary))
                # Archived alongside the decision above, same round_dir: this
                # branch is the only one that produces these two live files
                # (an approved/blocked round has no rework brief), so only
                # archive them here. Read back the just-written live files
                # rather than re-deriving the rendered text, so the archive
                # copy is guaranteed byte-identical to what actually shipped.
                _write_text_atomic(
                    round_dir / "rework-prompt.md",
                    Path(rework_path).read_text(encoding="utf-8"),
                )
                _write_text_atomic(
                    round_dir / "rework-dispatch-note.txt",
                    (pr_dir / "rework-dispatch-note.txt").read_text(encoding="utf-8"),
                )
            rescue_fields = (
                rescue_helpers.build_rescue_dataclass_kwargs("rework_cycle_cap")
                if rescue_dispatched
                else {}
            )
            if rescue_dispatched:
                rescue_fields["rescue_dispatched_at"] = utc_now()
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "issue_number": issue_number,
                "decision": decision,
                "decision_path": str(decision_path),
                "reviewed_head_sha": reviewed_head_sha,
                "reviewed_patch_id": reviewed_patch_id,
                "carried_forward_from": [],
                "request_changes_count": request_changes_count,
                "status": "escalated" if escalated else decision,
                "consecutive_failed_merge_attempts": 0,
                **rescue_fields,
                # The reviewer agent has recorded its verdict. The hub no longer
                # needs to treat this PR as having an in-flight reviewer; the next
                # stale-head review-queue entry will re-dispatch cleanly.
                "review_dispatch_status": "review_dispatch_completed",
                "reviewer_pid": None,
                "reviewer_process_start_time": None,
                # Reset the dispatch attempt counter: a verdict was produced, so
                # the PR is not stuck. If the head later advances and triggers a
                # new review cycle, the counter starts fresh.
                "review_dispatch_attempt_count": 0,
                # Reset the unreadable-log streak: a verdict proves the
                # reviewer pipeline is healthy, so any prior
                # persistent-unreadable condition is resolved (issue #1069).
                "review_log_unreadable_streak": 0,
                # Issue #1439: a recorded verdict ends the turn-limit miss
                # streak -- the reviewer reached a conclusion, so any prior
                # turn-limit deaths no longer count toward the cap-aware
                # backstop on a future review cycle.
                "review_turn_limit_miss_streak": 0,
                # Reset the cross-family parse-failure bound (issue #784
                # AC-8): a real verdict was just recorded -- whether a
                # genuine parse or this method's own "abandon" call from
                # _handle_malformed_cross_family_verdict -- so a future
                # review cycle (new head, new content) gets a fresh budget
                # rather than inheriting an exhausted one.
                "cross_family_parse_failure_count": 0,
                # Reviewer session token/cost telemetry (best-effort): merge-update
                # so a call without metrics (e.g. a manual `charlie verdict`)
                # never clobbers metrics recorded by an earlier automated reap.
                "review_session_metrics": (
                    session_metrics
                    if session_metrics is not None
                    else pr_state.get("review_session_metrics")
                ),
                **(
                    {"escalation_reason": pr_escalation_reason}
                    if pr_escalation_reason is not None
                    else {}
                ),
            }
            # Update the linked issue's status to reconcile out of rework_requested:
            # the previous worker session is definitionally finished, so the issue
            # status must reflect the actual decision. This prevents state-driven
            # dispatch_rework from selecting approved/blocked PRs for duplicate work.
            if issue_number is not None:
                if decision == "request_changes":
                    if not escalated:
                        issue_entry = {
                            **state["issues"].get(str(issue_number), {}),
                            "number": issue_number,
                            "status": "rework_requested",
                            "merge_alert": "OK",
                        }
                        clear_escalation(issue_entry)
                        clear_escalation_on_issue_prs(state, issue_number)
                        state["issues"][str(issue_number)] = issue_entry
                    else:
                        # Clear rework_requested status when escalated to prevent selection
                        # Issue #783: rework-cycle cap reached is a
                        # process limit, not a judgment call --
                        # mechanical.
                        state = _escalate_issue(
                            state,
                            issue_number,
                            reason="max_rework_cycles_exceeded",
                            reason_class="mechanical",
                        )
                elif decision == "approved":
                    issue_entry = {
                        **state["issues"].get(str(issue_number), {}),
                        "number": issue_number,
                        "status": "approved",
                        "merge_alert": "OK",
                    }
                    clear_escalation(issue_entry)
                    clear_escalation_on_issue_prs(state, issue_number)
                    state["issues"][str(issue_number)] = issue_entry
                    # Clear worker PID when issue is approved (worker is done)
                    state["issues"][str(issue_number)].pop("worker_pid", None)
                    state["issues"][str(issue_number)].pop("worker_process_start_time", None)
                elif decision == "blocked":
                    # Issue #783: an explicit "blocked" review decision is
                    # a human product/security judgment call, never
                    # auto-cleared.
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="review_blocked",
                        reason_class="judgment",
                        status="blocked",
                    )
                    # Clear worker PID when issue is blocked (worker is done)
                    state["issues"][str(issue_number)].pop("worker_pid", None)
                    state["issues"][str(issue_number)].pop("worker_process_start_time", None)
            event_payload: dict[str, Any] = {
                "pr_number": pr_number,
                "issue_number": issue_number,
                "decision": decision,
                "escalated": escalated,
                # Issue #1265: top-level and unconditional, distinct from
                # (and a sibling of, not nested inside) the pre-existing
                # session_metrics.verdict_source added conditionally below --
                # that field means "which parser found the fenced verdict
                # block"; this one means "which mechanism produced the
                # verdict at all".
                "verdict_provenance": verdict_provenance,
                # Issue #1268 (W11), item 2: previously never assigned at all
                # (confirmed live: 0 non-null across every existing
                # record_review row) -- events.db carried no verdict text.
                # These are an observability-only, size-bounded copy; the
                # round-K archive (`rounds/round-K/review-decision.json`,
                # above) is the untruncated source of truth W13 reads from.
                # ``required_changes`` is a list on ``decision_payload``, so
                # it is newline-joined into a single string before the same
                # byte-budget truncation applies to it. ``str(item)`` guards
                # every assignment site of ``effective_required_changes`` --
                # most are already ``list[str]``, but the #999 external-
                # findings path (``effective_required_changes =
                # list(external_findings)``) is never itself read as
                # strings elsewhere, so this join must not assume str
                # elements there. Coercing costs nothing for the str case
                # (round-trips identically) and makes this key correct for
                # every present and future assignment site rather than
                # only the ones exercised by today's tests.
                "summary": _truncate_for_event(summary_text),
                "required_changes": _truncate_for_event(
                    "\n".join(str(item) for item in effective_required_changes)
                ),
            }
            if session_metrics is not None:
                event_payload["session_metrics"] = session_metrics
            if findings_channel is not None:
                event_payload["findings_channel"] = findings_channel
            if recorded_external_findings is not None:
                event_payload["external_findings_count"] = len(recorded_external_findings)
            state = self._record_event(state, "record_review", event_payload)
            if findings_channel == "vacuous":
                # Distinct from the general "record_review" event (issue
                # #792): this is the signal that a request_changes/blocked
                # verdict arrived with nothing to act on -- neither an
                # itemized required_changes nor derivable prose -- so it can
                # be queried/alerted on independently of every other verdict.
                state = self._record_event(
                    state,
                    "required_changes_vacuous",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "decision": decision,
                    },
                )
            if rescue_dispatched:
                state = self._record_event(
                    state,
                    "rescue_dispatched",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "cause": "rework_cycle_cap",
                    },
                )
            save_state(self.paths.state_file, state)
        # GitHub label side effects are best-effort and isolated: the durable
        # decision above is the authority; a label failure is reported, not fatal.
        label_error: dict[str, Any] | None = None
        if issue_number is not None:
            if decision == "request_changes":
                # Issue #1131: never route rework onto a CLOSED issue. The
                # observed race applied ``agent:needs-rework`` to an issue
                # that was already closed by the merge this verdict chased,
                # polluting roll-call/metrics and requiring a manual label
                # strip. GitHub's issue ``state`` is the authoritative
                # closed signal (state.json's workflow ``status`` can lag or
                # be clobbered). Fetch is best-effort: on lookup failure,
                # proceed with the transition (label application is already
                # best-effort and reported, not fatal) -- the same fail-open
                # posture as the stranded-request_changes restorer's
                # issue_view call. ``terminal_state`` on the PR (fix #1131
                # above) already refuses the whole call for a merged/closed
                # PR; this guard covers the residual case where the PR is
                # still OPEN but its linked issue is independently CLOSED.
                issue_is_closed = False
                try:
                    linked_issue = self.gh.issue_view(issue_number)
                    issue_is_closed = str(linked_issue.get("state") or "OPEN").upper() == "CLOSED"
                except Exception:
                    pass
                if issue_is_closed:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state = self._record_event(
                            state,
                            "rework_label_skipped_issue_closed",
                            {
                                "pr_number": pr_number,
                                "issue_number": issue_number,
                                "decision": decision,
                                "escalated": escalated,
                            },
                            level="warning",
                        )
                        save_state(self.paths.state_file, state)
                else:
                    # Issue #1266: escalated here is always max_rework_cycles_
                    # exceeded (mechanical) -- see the _escalate_issue call above.
                    target = (
                        _escalation_edge("escalated", "mechanical")
                        if escalated
                        else "rework_requested"
                    )
                    result = transition(
                        self.gh,
                        self.config.labels,
                        issue_number,
                        target,
                    )
                    if result.outcome != TransitionOutcome.APPLIED:
                        label_error = {
                            "edge": target,
                            "outcome": result.outcome.value,
                            "add_failures": result.add_failures,
                            "remove_failures": result.remove_failures,
                        }
            elif decision == "blocked":
                # Issue #1266: "blocked" has no operator-queue counterpart --
                # a reviewer-blocked verdict is judgment-only by
                # construction -- so this is an inert pass-through, kept
                # here for uniformity with every other escalation-label
                # call site now routing through the same helper.
                result = transition(
                    self.gh,
                    self.config.labels,
                    issue_number,
                    _escalation_edge("blocked", "judgment"),
                )
                if result.outcome != TransitionOutcome.APPLIED:
                    label_error = {
                        "edge": "blocked",
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    }
            elif decision == "approved":
                result = transition(self.gh, self.config.labels, issue_number, "review_approved")
                if result.outcome != TransitionOutcome.APPLIED:
                    label_error = {
                        "edge": "review_approved",
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    }
        # Issue #1268 (W11), item 3: was `decision == "request_changes" and
        # comment and summary_text` -- request_changes-only, and silent
        # unless a caller explicitly passed comment=True. Widened to fire
        # for every terminal decision this call actually recorded
        # (approved/request_changes/blocked), gated on the config default
        # (`review.post_verdict_comment`, True) OR the existing `comment`
        # force-on override -- the CLI's `--comment` flag stays a strict
        # superset of the config default, never replaced by it. Still
        # excludes `escalated`: that is the SAME in-call local flipped by
        # the rework-cap logic above (not the early state-guard escalated
        # return at the top of this function, which never reaches this far)
        # -- the rescue tier and the rework-cap escalation path already post
        # their own comment for that case (_process_rescue_review,
        # rescue_helpers), so leaving this gate open on escalated=True would
        # double-post. `summary_text` is no longer required to be truthy:
        # it is guaranteed non-empty for request_changes/blocked (the reject
        # gate near the top of this function), but NOT for approved (no
        # validation requires it) -- dropping the clause means an
        # empty-summary approval still gets its header + required-changes
        # section posted rather than silently skipping the comment for a
        # decision type this gate previously never even reached.
        if not escalated and (comment or self.config.review.post_verdict_comment):
            header = f"## Fleet review - round {round_number} - {decision}"
            body_parts = [header]
            if summary_text:
                body_parts.append(summary_text)
            # Issue #792's `findings_channel == "derived"` marker (set above,
            # ~15326) means `effective_required_changes` is not a real
            # structured list -- it is `[summary_text.strip()]`, the exact
            # same text just appended above as the summary paragraph.
            # `_render_required_changes_section` (the rework-brief renderer)
            # already treats this case specially for that reason -- tier-2
            # prose, never a one-item bullet wrapping a whole paragraph
            # (see its docstring) -- and this gate must honor the same
            # invariant for the same reason: rendering both here would post
            # the reviewer's entire summary twice in one comment. Every
            # other channel (a real structured list, or `"external"``'s
            # replacement list) is unaffected -- only `"derived"` is ever a
            # verbatim copy of `summary_text`.
            if effective_required_changes and findings_channel != "derived":
                body_parts.append(
                    "### Required changes\n"
                    + "\n".join(f"- {rc}" for rc in effective_required_changes)
                )
            comment_body = "\n\n".join(body_parts)
            try:
                self._comment_pr(pr_number, comment_body)
            except GitHubError as exc:
                # Comment failure is separate from label transition failure
                if label_error is None:
                    label_error = {"comment_error": str(exc)}
                else:
                    label_error["comment_error"] = str(exc)
        source_note = f"head from {reviewed_head_source}"
        if rescue_dispatched:
            message = (
                f"review recorded — rework cap ({self.config.review.max_rework_cycles}) "
                f"reached, rescue tier dispatched instead of escalating ({source_note})"
            )
        elif escalated:
            message = (
                f"review recorded — rework cap ({self.config.review.max_rework_cycles}) reached, "
                f"escalated to human ({source_note})"
            )
        else:
            message = f"review recorded ({source_note})"
        if label_error:
            message += f" (label update failed: {label_error.get('outcome', label_error)})"
        return CommandResult(
            True,
            message,
            {
                "pr": pr_number,
                "decision": decision,
                "decision_path": str(decision_path),
                "reviewed_head_sha": reviewed_head_sha,
                "reviewed_head_source": reviewed_head_source,
                "live_head_sha": live_head_sha,
                "packet_head_sha": packet_head_sha,
                "rework_path": rework_path,
                "escalated": escalated,
                "rescue_dispatched": rescue_dispatched,
                "request_changes_count": request_changes_count,
                "label_error": label_error,
            },
        )

    # Re-arm field sets live in unescalate_reset_fields.py (extracted under the
    # #1442 ratchet); the aliases keep ``self._...`` call sites and tests intact.
    _UNESCALATE_PR_RESET_FIELDS = UNESCALATE_PR_RESET_FIELDS
    _UNESCALATE_ISSUE_RESET_FIELDS = UNESCALATE_ISSUE_RESET_FIELDS
    _REWORK_BUDGET_RESET_BY_ESCALATION_REASON = REWORK_BUDGET_RESET_BY_ESCALATION_REASON

    def _worktree_still_unsafe(self, issue_number: int, state: dict[str, Any]) -> str | None:
        """Re-run the worktree safety check for an issue (issue #849).

        Returns a reason string if the issue's worktree is still unsafe to
        reset, or ``None`` if the worktree is safe (or does not exist). Used
        by both de-escalation paths (``unescalate`` and
        ``_deescalate_mechanical_issue``) to refuse clearing a
        ``worktree_unsafe`` escalation while the underlying cause — a set of
        bytes on disk — still persists. Without this check, clearing the
        label reports success for an operation that changed nothing causal,
        and the next rework dispatch reproduces the escalation deterministically.

        Fails closed: a probe failure (``WorktreeProbeFailedError``) is
        treated as "still unsafe" so a transient index lock cannot clear a
        real blocker.
        """
        issue_entry = state.get("issues", {}).get(str(issue_number), {})
        if not isinstance(issue_entry, dict):
            return None
        branch = issue_entry.get("branch_name")
        if not branch or not isinstance(branch, str):
            return None
        wt_path = worktree_path_for_branch(self.repo_root, branch, self._layout.worktrees)
        if not wt_path.is_dir():
            # No worktree on disk — the blocker is gone (or was never this
            # issue's worktree). Clearing is safe.
            return None
        try:
            return _worktree_refuse_to_reset_reason(
                self.repo_root,
                branch,
                self.config.dispatch.base_ref,
                wt_path,
                self.config.dispatch.injected_paths,
                self.config.dispatch.materialize_dirs,
            )
        except (WorktreeProbeFailedError, RuntimeError):
            # Fail closed: a probe failure means we cannot confirm safety,
            # so treat the worktree as still unsafe.
            return "worktree safety probe failed; cannot confirm clean"

    def unescalate(
        self,
        pr_number: int | None = None,
        issue_number: int | None = None,
        *,
        dry_run: bool = False,
    ) -> CommandResult:
        """Operator re-arm for an escalated (or janitor-blocked) PR/issue.

        Escalation is deliberately terminal for every automated path (review()
        and record_review() both hard-stop on it); until this command existed
        the only recovery was hand-editing state.json and labels, which is
        exactly how the status/label desyncs this repair sweep keeps finding
        were produced. This is the sanctioned door back into the pipeline:

        - PR merged/closed on GitHub: normalize the record to that terminal
          state (finalization/reconcile handle the rest); no label changes.
        - PR open: reset status to the passive pr-open state, zero every
          attempt counter and frozen janitor/review cache, and apply the
          ``unescalated_pr_open`` label edge so the next pass re-reviews it
          from scratch.
        - Issue with no live PR: drop the issue back to the never-dispatched
          baseline and strip workflow labels (``unescalated_requeued``) so
          dispatch treats it as fresh.

        Idempotent: a record that is not escalated/janitor_blocked is a no-op
        (ok=True). ``dry_run`` computes and reports the full transition map
        without touching state, labels, or events.
        """
        if pr_number is None and issue_number is None:
            return CommandResult(False, "unescalate requires --pr and/or --issue", {})

        state = load_state_locked(self.paths.state_file)

        # Resolve the PR/issue pair from whichever side was given.
        if pr_number is None and issue_number is not None:
            open_pr_numbers = sorted(
                int(k)
                for k, v in state.get("prs", {}).items()
                if isinstance(v, dict)
                and v.get("issue_number") == issue_number
                and v.get("status") not in ("merged", "closed")
                and k.isdigit()
            )
            if open_pr_numbers:
                pr_number = open_pr_numbers[0]
        pr_state = state.get("prs", {}).get(str(pr_number), {}) if pr_number is not None else {}
        if issue_number is None and pr_number is not None:
            issue_number = pr_state.get("issue_number")
        issue_state = (
            state.get("issues", {}).get(str(issue_number), {}) if issue_number is not None else {}
        )

        pr_stuck = pr_state.get("status") in ("escalated", "janitor_blocked")
        issue_stuck = issue_state.get("status") == "escalated"
        if not pr_stuck and not issue_stuck:
            return CommandResult(
                True,
                f"nothing to unescalate (pr={pr_number} status="
                f"{pr_state.get('status')!r}, issue={issue_number} status="
                f"{issue_state.get('status')!r})",
                {"pr": pr_number, "issue": issue_number, "changed": False},
            )

        # Ground truth decides the re-entry point.
        live_pr = self.gh.pr_view(pr_number) if pr_number is not None else {}
        live_pr_state = str((live_pr or {}).get("state") or "").upper()

        # Issue #214 precedent (reconcile's live_session_issue_numbers guard):
        # a verifiably live worker session means nothing here is stuck, it is
        # IN USE -- refuse entirely rather than re-arm around a running
        # process. Popping issue-side worker_pid/dispatched_at would blind
        # orphan-worker detection; resetting the PR side would zero the
        # conflict/no-op attempt counters for a rework cycle still in flight
        # (defeating the caps) and flip the PR to the passive reviewing
        # status, inviting a concurrent review() against the worker's
        # in-progress push. PR "janitor_blocked" + issue "dispatched" is the
        # NORMAL mid-rework steady state, not a wedge.
        #
        # Issue #625: "live" is no longer just "is the PID alive?". Both the
        # sidecar-based and state.json-based checks route through one
        # predicate (``issue_worker_liveness``) that bounds the state-side
        # check with the watchdog's stall standard -- an alive-but-silent
        # session (no real activity for > stall_minutes, or past the
        # wall-clock deadline with an inconclusive probe) is wedged, not
        # live, and unescalate may proceed. The refusal carries session age
        # and last-activity diagnostics so an operator can tell a wedged
        # worker from a working one.
        if issue_number is not None:
            from datetime import UTC

            from .worker import issue_worker_liveness

            sessions_dir = self._layout.sessions_dir
            verdict = issue_worker_liveness(
                issue_number, issue_state, sessions_dir, self.config, datetime.now(UTC)
            )
        else:
            verdict = None
        if verdict is not None and verdict.live:
            return CommandResult(
                True,
                f"issue #{issue_number} has a live worker session; nothing to "
                f"unescalate (pr={pr_number} left untouched) -- {verdict.reason}",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "issue_worker_alive": True,
                    "issue_worker_last_activity_at": verdict.last_activity_at,
                    "issue_worker_last_activity_source": verdict.last_activity_source,
                    "issue_worker_session_started_at": verdict.session_started_at,
                    "issue_worker_pid": verdict.pid,
                    "issue_worker_source": verdict.source,
                    "changed": False,
                },
            )

        # Issue #849: a ``worktree_unsafe`` escalation is caused by bytes on
        # disk, not by a label or a PR state. Clearing the label without
        # inspecting the worktree reports success for an operation that
        # changed nothing causal — the next rework dispatch reproduces the
        # escalation deterministically. Re-run the safety check and refuse to
        # clear while the worktree still fails it.
        # Issue #807: ``worktree_unsafe`` is split into
        # ``worktree_unsafe_shim_dirt`` and ``worktree_unsafe_local_commits``;
        # both are covered by ``WORKTREE_UNSAFE_KINDS`` so the safety re-check
        # fires for either kind.
        if (
            issue_number is not None
            and issue_stuck
            and issue_state.get("escalation_reason") in WORKTREE_UNSAFE_KINDS
        ):
            unsafe_reason = self._worktree_still_unsafe(issue_number, state)
            if unsafe_reason:
                return CommandResult(
                    True,
                    f"issue #{issue_number} escalated as worktree_unsafe; "
                    f"worktree is still unsafe ({unsafe_reason}) — clearing "
                    f"the label would change nothing causal. Remove or "
                    f"commit the worktree work before re-arming.",
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "worktree_still_unsafe": True,
                        "worktree_unsafe_reason": unsafe_reason,
                        "changed": False,
                    },
                )

        # Compute the TRANSFORMATION from the pre-fetch snapshot (for dry_run
        # reporting), then re-apply it to freshly-loaded entries inside the
        # write lock below -- gh.pr_view has real latency, and writing this
        # snapshot's dicts wholesale would clobber any field a concurrent
        # writer (e.g. a reconcile pass) touched in the meantime.
        transitions: dict[str, list[Any]] = {}
        label_edge: str | None = None

        pr_status_target: str | None = None
        if pr_number is not None and pr_stuck:
            if live_pr_state == "MERGED":
                pr_status_target = "merged"
            elif live_pr_state == "CLOSED":
                pr_status_target = "closed"
            else:
                pr_status_target = PASSIVE_OPEN_STATUS

        def _apply_pr_reset(entry: dict[str, Any]) -> dict[str, Any]:
            updated = dict(entry)
            updated["status"] = pr_status_target
            if pr_status_target == PASSIVE_OPEN_STATUS:
                updated["review_dispatch_attempt_count"] = 0
                updated["request_changes_count"] = 0
                for field_name in self._UNESCALATE_PR_RESET_FIELDS:
                    if field_name in ("review_dispatch_attempt_count", "request_changes_count"):
                        continue
                    updated.pop(field_name, None)
            elif pr_status_target == "merged":
                # Issue #747: stamp ``merged_at`` only on a genuine non-merged
                # -> merged transition (the same pattern as the other five
                # merged_at sites) so an unescalate that re-observes a PR
                # already recorded as merged does not back-date the original
                # observation time. ``entry`` is the pre-reset entry, so its
                # ``status`` is the prior state, not the target just assigned.
                if entry.get("status") != "merged":
                    updated["merged_at"] = utc_now()
            return updated

        issue_status_action: str = "leave"
        if issue_number is not None:
            if live_pr_state == "OPEN" and pr_number is not None:
                issue_status_action = "passive"
                label_edge = "unescalated_pr_open"
            elif live_pr_state in ("MERGED", "CLOSED"):
                # Terminal PR on GitHub. If the issue is still escalated and
                # no other open PR references it, drop the issue to baseline
                # in the same call — reconcile deliberately never rewrites an
                # open escalated issue's status (D-2), so leaving it would
                # require a second identical ``unescalate --issue N`` call to
                # take the no-live-PR path (issue #1391). When another open PR
                # exists, or the issue is not stuck, leave the issue to
                # finalization/reconcile as before.
                if issue_stuck and not _has_other_open_pr(state, issue_number, pr_number):
                    issue_status_action = "drop"
                    label_edge = "unescalated_requeued"
                else:
                    label_edge = None
            elif issue_stuck:
                # No live PR at all — back to the never-dispatched baseline
                # (a status literal no dispatch selector reads would just
                # recreate the orphan gap reconcile now repairs).
                issue_status_action = "drop"
                label_edge = "unescalated_requeued"

        def _apply_issue_reset(entry: dict[str, Any]) -> dict[str, Any]:
            updated = dict(entry)
            if issue_status_action == "passive":
                updated["status"] = PASSIVE_OPEN_STATUS
            elif issue_status_action == "drop":
                updated.pop("status", None)
            for field_name in self._UNESCALATE_ISSUE_RESET_FIELDS:
                updated.pop(field_name, None)
            return updated

        if pr_number is not None and pr_stuck:
            snapshot_new_pr = _apply_pr_reset(pr_state)
            if snapshot_new_pr.get("status") != pr_state.get("status"):
                transitions["pr.status"] = [pr_state.get("status"), snapshot_new_pr["status"]]
        if issue_number is not None:
            snapshot_new_issue = _apply_issue_reset(issue_state)
            if snapshot_new_issue.get("status") != issue_state.get("status"):
                transitions["issue.status"] = [
                    issue_state.get("status"),
                    snapshot_new_issue.get("status"),
                ]

        if dry_run:
            return CommandResult(
                True,
                f"dry-run: would unescalate pr={pr_number} issue={issue_number} "
                f"(label edge: {label_edge})",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "transitions": transitions,
                    "label_edge": label_edge,
                    "changed": False,
                },
            )

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            if pr_number is not None and pr_stuck:
                fresh_pr = state["prs"].get(str(pr_number), {})
                state["prs"][str(pr_number)] = {
                    **_apply_pr_reset(fresh_pr if isinstance(fresh_pr, dict) else {}),
                    "number": pr_number,
                }
            if issue_number is not None:
                fresh_issue = state["issues"].get(str(issue_number), {})
                state["issues"][str(issue_number)] = {
                    **_apply_issue_reset(fresh_issue if isinstance(fresh_issue, dict) else {}),
                    "number": issue_number,
                }
            state = self._record_event(
                state,
                "unescalate",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "transitions": transitions,
                    "label_edge": label_edge,
                },
            )
            save_state(self.paths.state_file, state)

        label_error = None
        if label_edge is not None and issue_number is not None:
            result = transition(self.gh, self.config.labels, int(issue_number), label_edge)
            if result.outcome != TransitionOutcome.APPLIED:
                label_error = {
                    "edge": label_edge,
                    "outcome": result.outcome.value,
                    "add_failures": result.add_failures,
                    "remove_failures": result.remove_failures,
                }
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    entry = state["issues"].get(str(issue_number), {})
                    state["issues"][str(issue_number)] = {
                        **(entry if isinstance(entry, dict) else {}),
                        "number": issue_number,
                        "label_error": label_error,
                    }
                    save_state(self.paths.state_file, state)

        summary = ", ".join(f"{k}: {old!r} -> {new!r}" for k, (old, new) in transitions.items())
        message = f"unescalated pr={pr_number} issue={issue_number}"
        if summary:
            message += f" ({summary})"
        if label_error:
            message += f" (label update failed: {label_error['outcome']})"
        return CommandResult(
            True,
            message,
            {
                "pr": pr_number,
                "issue": issue_number,
                "transitions": transitions,
                "label_edge": label_edge,
                "label_error": label_error,
                "changed": True,
            },
        )

    # Deliberately NOT @_guard_state_lock: merge_check takes no state lock, and
    # the guard's contract is to return a *successful* skip (ok=True) when the
    # lock is held. On an authorization preflight that would be fail-open —
    # "cannot tell" rendered as "yes". Keep this method lock-free and pure.
    def merge_check(self, pr_number: int) -> CommandResult:
        """Answer "is this PR merge-authorized *right now*?" without merging it.

        Issue #894. Merge authorization was enforced only on the paths that
        merge through this codebase -- ``merge_ready`` (``ship-it``) and, for
        the Aviator re-queue, ``reconcile._pr_review_approved_at_head``. A raw
        ``gh pr merge`` bypassed both, and the #502 tripwire only reports the
        bypass *after* the merge is irreversible. That is what happened to PR
        #759, whose merge was justified from GitHub's review state while
        ``review-decision.json`` recorded ``request_changes``.

        This is the preflight those paths never exposed: same invariant, no
        side effects, callable before the merge rather than after it. It is
        the single command a ``PreToolUse`` hook can shell out to, so the
        interception logic stays in the repo (versioned, CI-covered) instead
        of in unversioned agent configuration.

        **Fails closed.** Every unreadable, absent, malformed, or ambiguous
        input yields ``ok=False``. An authorization preflight that answers
        "yes" when it cannot tell is worse than no preflight, because it
        launders uncertainty into permission. ``data["reason"]`` names which
        condition fired so the caller can act on it; the distinction between
        ``not_approved`` and ``head_moved`` is the difference between "get a
        review" and "get a re-review".

        Deliberately does *not* reuse ``merge_ready``'s inline gate: that one
        may **mutate** state via approval carry-forward (``_update_approval_head``).
        A preflight must be a pure question. The shared invariant is the pair
        ``decision == "approved"`` and ``reviewed_head_sha == headRefOid``,
        asserted identically here and in ``_pr_review_approved_at_head``.
        """
        pr = self.gh.pr_view(pr_number)
        if not isinstance(pr, dict) or not pr:
            return CommandResult(
                False,
                f"PR #{pr_number}: cannot read PR from GitHub — refusing to authorize",
                {"pr": pr_number, "authorized": False, "reason": "pr_unreadable"},
            )
        if str(pr.get("state", "")).upper() == "MERGED":
            return CommandResult(
                False,
                f"PR #{pr_number} is already merged — nothing to authorize",
                {"pr": pr_number, "authorized": False, "reason": "already_merged"},
            )

        live_head_sha = pr.get("headRefOid")
        decision = self._review_decision(pr_number)
        decision_value = decision.get("decision")
        reviewed_head_sha = decision.get("reviewed_head_sha")
        base = {
            "pr": pr_number,
            "decision": decision_value,
            "reviewed_head_sha": reviewed_head_sha,
            "live_head_sha": live_head_sha,
        }

        if not live_head_sha:
            return CommandResult(
                False,
                f"PR #{pr_number}: no live head sha — refusing to authorize",
                {**base, "authorized": False, "reason": "no_live_head"},
            )
        # Issue #934: an explicit operator authorization recorded via
        # ``merge_authorize`` is as authoritative as an approved review
        # decision. Checked before the missing/invalid/not-approved/head-moved
        # gates so a valid override authorizes regardless of the recorded
        # review verdict — that is the whole point, since the override exists
        # for PRs whose verdict is stale, absent, or pending. A malformed or
        # SHA-mismatched override falls through to the existing fail-closed
        # checks below, so this adds a way to record authorization without
        # adding a way to skip the control.
        if _authorized_override_matches(decision, live_head_sha):
            override = decision["authorized_override"]
            return CommandResult(
                True,
                f"PR #{pr_number}: authorized by operator override at head "
                f"{live_head_sha} (by {override.get('by') or 'unknown'})",
                {
                    **base,
                    "authorized": True,
                    "reason": "authorized_override",
                    "authorized_by": override.get("by"),
                    "authorized_at": override.get("authorized_at"),
                    "authorized_sha": override.get("authorized_sha"),
                },
            )
        if decision_value == "missing":
            # Issue #1362 Stage 1: resolve_decision_payload collapses both
            # "no decision file at all" and "flat file corrupt, no round
            # fallback" into this same "missing" sentinel (the old distinct
            # "invalid" sentinel no longer exists) -- both are equally
            # non-terminal for authorization purposes, so this one reason
            # covers what used to be two.
            return CommandResult(
                False,
                f"PR #{pr_number}: no readable review-decision.json — not authorized",
                {**base, "authorized": False, "reason": "no_decision"},
            )
        if decision_value != "approved":
            return CommandResult(
                False,
                f"PR #{pr_number}: recorded decision is {decision_value!r}, not 'approved'",
                {**base, "authorized": False, "reason": "not_approved"},
            )
        if reviewed_head_sha != live_head_sha:
            return CommandResult(
                False,
                (
                    f"PR #{pr_number}: approved at {reviewed_head_sha} but head is now "
                    f"{live_head_sha} — re-review required"
                ),
                {**base, "authorized": False, "reason": "head_moved"},
            )
        return CommandResult(
            True,
            f"PR #{pr_number}: approved at current head {live_head_sha}",
            {**base, "authorized": True, "reason": "approved_at_head"},
        )

    def merge_authorize(
        self,
        pr_number: int,
        reason: str,
        *,
        by: str | None = None,
        sha: str | None = None,
    ) -> CommandResult:
        """Record an operator's explicit authorization to merge a worker PR (issue #934).

        The unauthorized-merge tripwire (#673) and the ``merge-check`` preflight
        (#894) both infer authorization from ``decision == "approved"`` and
        ``reviewed_head_sha == live_head_sha``. An operator who legitimately
        adjudicates a PR whose recorded decision is stale, absent, or pending —
        and merges it — has no way to record that adjudication, so every
        legitimate operator merge becomes a tripwire finding that pins
        ``ok=False`` on every subsequent pass until someone writes a
        retrospective ack. The authorized path and the unauthorized path are
        indistinguishable by construction.

        This writes an ``authorized_override`` into the PR's
        ``review-decision.json``: ``{by, reason, authorized_sha,
        authorized_at}``. The tripwire and ``merge-check`` treat an override
        whose ``authorized_sha`` matches the live head as explicit
        authorization (via ``_authorized_override_matches``), so the control
        reads a **recorded** authorization rather than inferring one.

        Properties (from #934):

        - **Does not weaken the control.** This adds a way to *record*
          authorization; it must not add a way to *skip* the check. An
          unrecorded merge is still a finding. The override is a field in the
          decision record, not a bypass — both ``_detect_unauthorized_merges``
          and ``merge_check`` still run their full logic; they just gain an
          additional authorization source.
        - **The reason stays mandatory**, matching ``tripwire ack`` — "a
          tripwire that can be silenced silently is no control" applies at
          least as strongly before the merge as after it.
        - **Bind to the SHA.** Two of the four Class B cases (#802, #804) were
          flagged specifically because a rebase moved the head after the
          decision was recorded. The override names the exact SHA it
          authorizes; a rebase after authorization moves the head and
          invalidates the override, exactly as it invalidates an approved
          decision.

        The override is merge-updated into the existing decision record (not a
        fresh file), so the reviewer's original verdict is preserved alongside
        the operator's authorization. If no decision file exists, one is
        created with just the override — the reviewer verdict is absent, and
        the override is the authorization.
        """
        if not reason.strip():
            return CommandResult(
                False,
                "a non-empty --reason is required to record a merge authorization "
                "(a tripwire that can be silenced silently is no control)",
                {"pr": pr_number},
            )

        pr = self.gh.pr_view(pr_number)
        if not isinstance(pr, dict) or not pr:
            return CommandResult(
                False,
                f"PR #{pr_number}: cannot read PR from GitHub — refusing to authorize",
                {"pr": pr_number, "authorized": False, "reason": "pr_unreadable"},
            )

        authorized_sha = sha if sha is not None else pr.get("headRefOid")
        if not authorized_sha or not isinstance(authorized_sha, str):
            return CommandResult(
                False,
                f"PR #{pr_number}: no head SHA to bind the authorization to "
                "— refusing to record an unbound override",
                {"pr": pr_number, "authorized": False, "reason": "no_head_sha"},
            )

        decision_path = self.paths.prs / f"pr-{pr_number}" / "review-decision.json"
        override_payload = {
            "by": by,
            "reason": reason,
            "authorized_sha": authorized_sha,
            "authorized_at": utc_now(),
        }

        with state_lock(self.paths.state_file):
            # Merge-update the override into the existing decision record. If
            # the file is absent or unparseable, start from an empty base — the
            # override is the authorization, and the reviewer verdict (if any)
            # is preserved when it exists. The read is inside the ``state_lock``
            # (which ``record_review`` also holds) so the read-modify-write is
            # genuinely atomic against concurrent writers — a TOCTOU where
            # ``record_review`` overwrites the file between this read and the
            # write below would silently discard the override (issue #934
            # review finding).
            if decision_path.exists():
                try:
                    with decision_path.open("r", encoding="utf-8") as handle:
                        existing = json.load(handle)
                    if not isinstance(existing, dict):
                        existing = {}
                except (OSError, json.JSONDecodeError):
                    existing = {}
            else:
                existing = {}
            updated = {**existing, "authorized_override": override_payload}
            # Single writer (issue #1362 Stage 2): ``archive_round=False`` --
            # this patch only adds ``authorized_override``, not a new
            # reviewer verdict, so it must never mint a round itself. Before
            # the F1 fix above, the packet-build placeholder guaranteed a
            # round-1 always existed by the time an override could land, so
            # this patch merely deduped onto that round; now that the
            # placeholder no longer archives, a PR with no reviewer verdict
            # yet has zero archived rounds, and without this flag the
            # override patch would become the round-1 minter -- a phantom
            # "reviewer round" containing only an operator override.
            # head_sha=None: any ``reviewed_head_sha`` already on ``existing``
            # passes through unchanged.
            record_decision(decision_path.parent, updated, None, archive_round=False)
            state = load_state(self.paths.state_file)
            state = self._record_event(
                state,
                "merge_authorized",
                {
                    "pr": pr_number,
                    "by": by,
                    "reason": reason,
                    "authorized_sha": authorized_sha,
                },
            )
            save_state(self.paths.state_file, state)

        return CommandResult(
            True,
            f"PR #{pr_number}: recorded operator authorization to merge at head "
            f"{authorized_sha} (by {by or 'unknown'})",
            {
                "pr": pr_number,
                "authorized": True,
                "authorized_sha": authorized_sha,
                "authorized_by": by,
                "reason": reason,
                "decision_path": str(decision_path),
                "state_file": str(self.paths.state_file),
            },
        )

    @_guard_state_lock
    def merge_ready(
        self,
        pr_number: int,
        *,
        merge: bool | None = None,
        merge_train_head: int | None = None,
    ) -> CommandResult:
        # Issue #614: dry-run short-circuit. Under --dry-run the GitHub
        # client's synthetic stubs make ``merge_pr`` / ``add_pr_label`` appear
        # to succeed without raising, which the real path below interprets as
        # proof of a merge and durably records to state.json — stranding the PR
        # in a terminal "merged" or "mergequeue" status that never actually
        # happened. The gate must sit above the ``state_lock`` (the idempotency
        # short-circuit below conditionally writes) and return the computed
        # readiness verdict without persisting, mirroring ``_dispatch_impl``'s
        # dry-run gate. Gating lower — after the idempotency block but before
        # the merge — would drop into the shared failed-attempt-alarm block
        # and increment ``consecutive_failed_merge_attempts``, advancing the
        # state machine instead of merely previewing it.
        if self.dry_run:
            return self._merge_ready_dry_run(
                pr_number, merge=merge, merge_train_head=merge_train_head
            )
        # Idempotence: if state already records this PR as merged, short-circuit
        # to a success no-op. Re-running `ship-it` on a completed PR must not
        # re-attempt `gh pr merge` (which fails on an already-merged PR and
        # propagates GitHubError → exit 2).
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            existing_pr_state = state["prs"].get(str(pr_number), {})
            if existing_pr_state.get("status") == "merged":
                # Clear any stale merge alert so a reopened issue can re-alert.
                _issue_number = existing_pr_state.get("issue_number")
                if _issue_number is not None:
                    _issue_key = str(_issue_number)
                    _issue_entry = state["issues"].get(_issue_key, {})
                    if _issue_entry.get("merge_alert") != "OK":
                        state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
                        save_state(self.paths.state_file, state)
                return CommandResult(
                    True,
                    f"PR #{pr_number} already merged",
                    {
                        "pr": pr_number,
                        "issue": existing_pr_state.get("issue_number"),
                        "already_merged": True,
                        "merged": True,
                    },
                )
        pr = self.gh.pr_view(pr_number)
        if not pr:
            return CommandResult(False, f"PR #{pr_number} was not found", {})
        # Aviator MergeQueue silent-revert detector (issue #823): add_pr_label's
        # boolean return only proves the POST succeeded, not that the label
        # survived -- Aviator can accept the mergequeue label and then
        # asynchronously strip it 2-3 seconds later (draft PR, a failing
        # required check, base mismatch, paused queue, ...), and every such
        # rejection was previously indistinguishable from success. Detected
        # cross-pass, never same-pass: existing_pr_state is the PRIOR pass's
        # persisted status (loaded above, before this pass's live fetch) and
        # label_names(pr) is THIS pass's live labels. A same-pass re-read
        # would race Aviator's 2-3s revert window and could still observe the
        # label present.
        mergequeue_label_reverted = bool(
            self.config.auto_merge.mergequeue_label
            and existing_pr_state.get("status") == "mergequeue"
            and self.config.auto_merge.mergequeue_label not in label_names(pr)
        )
        # Issue #1402: distinguish reconcile's own cooperative self-revocation
        # (stale-head approval, pending carry-forward re-validation -- the #819
        # gap fix) from Aviator's #823 silent rejection. reconcile records
        # ``mergequeue_revoked_reason`` in ``state["prs"][n]`` when IT removes
        # the label; its absence means the label disappeared for some other
        # reason (Aviator stripped it, or a pre-#1402 reconcile pass that did
        # not record the reason). Only ``"stale_head_pending_carry_forward"``
        # is a self-revocation -- ``"not_approved"`` is a genuine revocation
        # whose counter-increment path is already suppressed by ``can_merge``
        # being False (the decision is not ``"approved"``), so it does not
        # need the same exclusion.
        mergequeue_self_revoked_stale_head = bool(
            mergequeue_label_reverted
            and existing_pr_state.get("mergequeue_revoked_reason")
            == "stale_head_pending_carry_forward"
        )
        issue_number = linked_issue_number(
            pr,
            is_cross_repository=pr.get("isCrossRepository"),
            branch_prefix=self.config.dispatch.branch_prefix,
        )
        decision = self._review_decision(pr_number)
        approved = decision.get("decision") == "approved"
        sync_failed = False
        merge_conflict = False
        merge_conflict_routed = False
        merge_conflict_escalated = False
        check_failure_routed = False
        cross_pr_revert_detected = False
        cross_pr_revert_routed = False
        cross_pr_revert_reason: str | None = None
        issue_status: str | None = None
        label_error: dict[str, Any] | None = None
        rework_label_error: dict[str, Any] | None = None
        if approved:
            reviewed_head_sha = decision.get("reviewed_head_sha")
            live_head_sha = pr.get("headRefOid")
            head_moved = reviewed_head_sha is None or live_head_sha != reviewed_head_sha
            carried_forward = False
            if head_moved and live_head_sha:
                old_reviewed_head_sha = reviewed_head_sha
                check = self._check_carry_forward(pr_number, decision)
                if check.carry_forward:
                    self._update_approval_head(
                        pr_number,
                        decision,
                        live_head_sha,
                        old_head=old_reviewed_head_sha,
                        issue_number=issue_number,
                        tier=check.tier or "patch-id",
                        new_patch_id=check.live_patch_id,
                        new_signature=check.live_signature,
                    )
                    pr = self.gh.pr_view(pr_number) or pr
                    decision = self._review_decision(pr_number)
                    reviewed_head_sha = decision.get("reviewed_head_sha")
                    live_head_sha = pr.get("headRefOid")
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state["prs"][str(pr_number)] = {
                            **state["prs"].get(str(pr_number), {}),
                            "number": pr_number,
                            "issue_number": issue_number,
                            "status": "approved",
                            "head_moved": False,
                            "reviewed_head_sha": reviewed_head_sha,
                            "reviewed_patch_id": check.live_patch_id,
                            "carry_forward_tier": check.tier,
                            "carried_forward_from": decision.get("carried_forward_from", []),
                            "live_head_sha": live_head_sha,
                            "consecutive_failed_merge_attempts": 0,
                            "consecutive_stale_base_deferrals": 0,
                        }
                        # The carry-forward event itself is recorded inside
                        # _update_approval_head (issue #638) so every call
                        # site is instrumented uniformly; do NOT re-record
                        # here or the transition is double-counted.
                        save_state(self.paths.state_file, state)
                    carried_forward = True
            if head_moved and not carried_forward:
                message = "PR head moved since approval — re-review required"
                label_error: dict[str, Any] | None = None
                # Escalation gate (issue #833). merge_ready()'s escalation
                # handling is per-route by design, not a single top-of-function
                # gate: the readiness-no-CI-stall (below), check-failure, and
                # cross-PR-revert lanes already exclude "escalated"; the
                # merge-conflict-rework lane deliberately does NOT (issue #776
                # -- an unrelated-cause escalation must not permanently wall
                # off a PR from its own capped remediation; real corpus:
                # issues #592/#648/#606). This head_moved branch had NO
                # escalation awareness at all: it unconditionally re-applied
                # the "review_started" label transition and rewrote status to
                # "reviewing" on every ~30 min loop pass, even for a PR
                # already flagged agent:human-needed -- a livelock, not a
                # remediation, because nothing was waiting on the re-review it
                # kept re-requesting (real corpus: issue #602 / PR #679).
                # Mirrors review()'s entry gate (which uses the same
                # ``_escalation_flags`` predicate) but scoped to just these two
                # mutations, not the whole function, so the merge-conflict-
                # rework lane a few lines below keeps working.
                #
                # State is re-read here rather than reusing a flag computed at
                # function entry: ``_check_carry_forward``/
                # ``_update_approval_head`` above, and the merge-conflict-
                # rework dispatch further below, can each write a new status
                # for this PR/issue mid-call, so only a read taken at this
                # exact point is trustworthy.
                escalation_state = load_state_locked(self.paths.state_file)
                pr_escalated, issue_escalated = _escalation_flags(
                    escalation_state.get("prs", {}).get(str(pr_number), {}),
                    escalation_state.get("issues", {}).get(str(issue_number), {})
                    if issue_number is not None
                    else None,
                )
                escalated = pr_escalated or issue_escalated
                # Issue #868: a second, independent call site that stamps
                # "reviewing"/agent:reviewing — separate from review()'s own
                # packet-generation path, which gates the same way. Disabled
                # dispatch means nothing services "reviewing" here either, so
                # the state/label stamp is gated on the same flag. The
                # head_moved bookkeeping below (state field + event) stays
                # unconditional: it's read only by this function's own next
                # pass (via _check_carry_forward/reviewed_head_sha
                # comparisons), never jointly with status=="reviewing", so
                # gating just the reviewing stamp doesn't orphan it.
                dispatch_disabled = not self.config.review_dispatch.enabled
                if not escalated:
                    if issue_number is not None and not dispatch_disabled:
                        result = transition(
                            self.gh, self.config.labels, issue_number, "review_started"
                        )
                        if result.outcome != TransitionOutcome.APPLIED:
                            label_error = {
                                "edge": "review_started",
                                "outcome": result.outcome.value,
                                "add_failures": result.add_failures,
                                "remove_failures": result.remove_failures,
                            }
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        state["prs"][str(pr_number)] = {
                            **state["prs"].get(str(pr_number), {}),
                            "number": pr_number,
                            "issue_number": issue_number,
                            **({} if dispatch_disabled else {"status": "reviewing"}),
                            "head_moved": True,
                            "reviewed_head_sha": reviewed_head_sha,
                            "live_head_sha": live_head_sha,
                            "consecutive_failed_merge_attempts": 0,
                            "consecutive_stale_base_deferrals": 0,
                        }
                        if issue_number is not None:
                            _issue_key = str(issue_number)
                            _issue_entry = state["issues"].get(_issue_key, {})
                            state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
                        state = self._record_event(
                            state,
                            "head_moved",
                            {
                                "pr_number": pr_number,
                                "reviewed_head_sha": reviewed_head_sha,
                                "live_head_sha": live_head_sha,
                            },
                        )
                        save_state(self.paths.state_file, state)
                return CommandResult(
                    False,
                    message,
                    {
                        "pr": pr_number,
                        "issue": issue_number,
                        "can_merge": False,
                        "merged": False,
                        "head_moved": True,
                        "reviewed_head_sha": reviewed_head_sha,
                        "live_head_sha": live_head_sha,
                        "review_decision": decision,
                        "label_error": label_error,
                        "escalated": escalated,
                    },
                )
            # Genuine merge conflict: gh pr update-branch cannot resolve this.
            # Record the conflict and let the failed-attempt alarm decide when
            # to route the linked issue to rework_requested for a worker to resolve.
            if self._is_merge_conflict(pr):
                state = load_state_locked(self.paths.state_file)
                issue_state = (
                    state["issues"].get(str(issue_number), {}) if issue_number is not None else {}
                )
                issue_status = issue_state.get("status")
                if issue_status in (
                    "dispatched",
                    "dispatch_pending",
                    "manifest_written",
                ):
                    return CommandResult(
                        True,
                        f"PR #{pr_number} merge conflict is being resolved by a rework worker",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "can_merge": False,
                            "merged": False,
                            "review_decision": decision,
                            "merge_conflict": True,
                            "consecutive_failed_merge_attempts": existing_pr_state.get(
                                "consecutive_failed_merge_attempts", 0
                            ),
                            "merge_attempt_alarm": False,
                            "merge_attempt_warning": None,
                        },
                    )
                # "blocked" is a human reviewer verdict (record_review's
                # decision == "blocked"), not a cap escalation: transition()
                # has no source-state validation, so rerouting it to
                # rework_requested would silently strip that verdict and hand
                # the issue back into the automated pipeline behind the
                # human's back. Leave it alone; a human must move it out.
                #
                # "escalated" is deliberately NOT excluded here (issue #776):
                # it used to be, which let an escalation for ANY reason --
                # e.g. a dead request-changes-fix worker exhausting the
                # unrelated watchdog redispatch cap -- permanently wall off a
                # PR that separately develops a merge conflict, with no path
                # back short of a human running `charlie unescalate` (real
                # corpus: issues #592/#648/#606). The unified conflict-rework
                # dispatch below (_route_janitor_gate_failure_to_rework)
                # re-derives its own decision from conflict_rework_attempts,
                # a cap left untouched by an escalation from a different lane
                # -- but already exhausted, so still correctly refused, if
                # THIS lane is what escalated the issue previously. Falling
                # through is safe: it is the same merge_conflict=True /
                # sync_failed=True path already taken today by a fresh,
                # not-yet-escalated conflict before the failed-attempt-alarm
                # threshold below is reached.
                if issue_status == "blocked":
                    return CommandResult(
                        True,
                        f"PR #{pr_number} merge conflict on issue #{issue_number} "
                        f"awaiting human decision ({issue_status}); not rerouted",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "can_merge": False,
                            "merged": False,
                            "review_decision": decision,
                            "merge_conflict": True,
                            "consecutive_failed_merge_attempts": existing_pr_state.get(
                                "consecutive_failed_merge_attempts", 0
                            ),
                            "merge_attempt_alarm": False,
                            "merge_attempt_warning": None,
                        },
                    )
                merge_conflict = True
                sync_failed = True
                # Conflict-rework dispatch is deferred until the consecutive
                # failed-merge-attempt alarm threshold is reached (below). This
                # debounces transient/stale CONFLICTING readings and keeps the
                # approved verdict intact for the rework push's carry-forward.
            # Head matches the approved SHA. In front-of-train mode, only the
            # head of the approved queue is allowed to proceed, and it must be
            # up-to-date with main before checks are evaluated.
            update_branch_strategy = self.config.auto_merge.update_branch_strategy
            if update_branch_strategy == "front_of_train":
                if merge_train_head is not None and merge_train_head != pr_number:
                    return self._merge_not_ready_result(
                        pr_number,
                        issue_number,
                        decision,
                        existing_pr_state,
                    )
                if merge_train_head is None:
                    try:
                        prs = self.gh.pr_list()
                    except GitHubError:
                        sync_failed = True
                    else:
                        head = self._merge_train_head(prs)
                        if head is not None and head != pr_number:
                            return self._merge_not_ready_result(
                                pr_number,
                                issue_number,
                                decision,
                                existing_pr_state,
                            )
            # Single point of enforcement: derive base freshness from the GitHub
            # compare API once and use it for both the pre-merge sync decision
            # and the merge-base gate. mergeStateStatus can lag and report CLEAN
            # while the branch is actually stale, so it is no longer authoritative.
            #
            # Whether base currency gates THIS merge is `require_current_base OR
            # protection.strict` -- protection may raise the requirement, never
            # lower it below what the operator configured (issue #875). Issue
            # #812 made this purely protection-derived, which meant a repo
            # running `strict: false` (as this one does, deliberately: two
            # self-hosted runners cannot sustain strict mode) disabled its own
            # merge gate and merged stale-base PRs whose merged tree was never
            # tested. The broadcast sweep still uses the protection-only
            # `_is_base_freshness_required` -- that write costs N CI cycles
            # across every open PR, where this one costs a single cycle for the
            # PR actually merging. See _is_base_currency_gated.
            #
            # This single flag intentionally drives BOTH the pr_update_branch
            # write below and the deferral gate further down. Decoupling them --
            # gating merges while leaving the write suppressed -- would deadlock:
            # a stale PR would defer forever with nothing to make it current.
            # `update_branch_strategy == "off"` forces the whole thing off
            # regardless: with no sync mechanism at all, requiring currency would
            # be that same inescapable deadlock -- the hazard __post_init__
            # already blocks for the config-only case (require_current_base=True
            # + strategy=off).
            base_current: bool | None = None
            base_currency_gated = False
            if not sync_failed and update_branch_strategy != "off":
                base_currency_gated = self._is_base_currency_gated(
                    pr.get("baseRefName") or self.config.runners.default_branch
                )
            if (
                not sync_failed
                and base_currency_gated
                and update_branch_strategy in {"front_of_train", "broadcast"}
            ):
                base_current = self._is_base_current(pr)
                # Aviator MergeQueue handoff (task #10): once this PR has
                # already been parked in Aviator's queue (state status
                # "mergequeue" from a prior merge_ready pass), Aviator owns
                # rebasing it. Calling pr_update_branch here on every
                # subsequent poll would race Aviator's own rebase as a second
                # writer on the same ref — this repo's live config is
                # broadcast, so every poll would otherwise attempt it. The
                # base-freshness *read* above still runs (it only feeds the
                # deferral gate below); only the write is skipped. See the
                # merge-train exclusion in _merge_train_candidates for the
                # sibling half of this fix.
                already_in_mergequeue = existing_pr_state.get("status") == "mergequeue"
                if not already_in_mergequeue and self._should_update_pr_branch(pr, base_current):
                    if self.gh.pr_update_branch(pr_number):
                        new_head = self._verify_synced_head(pr_number, live_head_sha)
                        if new_head is None:
                            sync_failed = True
                        elif new_head != live_head_sha:
                            self._update_approval_head(
                                pr_number,
                                decision,
                                new_head,
                                old_head=live_head_sha,
                                issue_number=issue_number,
                            )
                            pr = self.gh.pr_view(pr_number) or pr
                            decision = self._review_decision(pr_number)
                        else:
                            # Already up-to-date; nothing to do.
                            pass
                    else:
                        sync_failed = True
            # merge-base freshness gate: mergeStateStatus can lag, so verify
            # ancestry with the GitHub compare API before merging. Skipped
            # entirely when base freshness is not required (issue #812).
            if not sync_failed and base_currency_gated:
                if base_current is None and update_branch_strategy not in {
                    "front_of_train",
                    "broadcast",
                }:
                    base_current = self._is_base_current(pr)
                elif pr.get("headRefOid") != live_head_sha:
                    base_current = self._is_base_current(pr)
                if base_current is not True:
                    base_ref = pr.get("baseRefName")
                    head_sha = pr.get("headRefOid")
                    reason = "compare_unavailable" if base_current is None else "base_stale"
                    return self._merge_deferred_stale_base_result(
                        pr_number,
                        issue_number,
                        decision,
                        base_ref,
                        head_sha,
                        reason,
                    )

            # Cross-PR revert gate: a branch that merges a base commit and then
            # reverts it has a clean PR diff but would silently undo the base
            # change when squash-merged. Detect by enumerating branch commits not
            # on base and matching `Revert "..."` subjects against base commits.
            if not sync_failed:
                cross_pr_revert_reason = detect_cross_pr_revert(pr, self.repo_root)
                if cross_pr_revert_reason:
                    cross_pr_revert_detected = True
                    sync_failed = True
                    if issue_number is not None:
                        state = load_state_locked(self.paths.state_file)
                        issue_state = state["issues"].get(str(issue_number), {})
                        issue_status = issue_state.get("status")
                        if issue_status not in _REWORK_ALREADY_ROUTED_STATUSES:
                            cross_pr_revert_routed = True
                            rework_label_error = self._request_cross_pr_revert_rework(
                                pr, issue_number, decision, cross_pr_revert_reason
                            )
        checks = self.gh.pr_checks(pr_number)
        checks_unavailable = checks is None

        if checks_unavailable:
            # gh pr checks command itself failed. Treat every required check as
            # unavailable (not missing) and do not merge; callers/loop will count
            # this as an infrastructure error.
            summary = summarize_checks(None, self.config.auto_merge.required_checks)
            enriched_checks: list[dict[str, Any]] = []
        else:
            # Issue #1383: use the shared data-boundary enrichment so the
            # merge path classifies infra_blocked checks identically to the
            # review path. The old inline enrichment reclassified a FAILURE
            # check with an infra signature to ``INFRA_FAILURE`` (routing it
            # to ``CheckSummary.infra_failed``); the shared helper rewrites
            # the same population to ``INFRA_BLOCKED`` instead, so those
            # checks now land in ``CheckSummary.infra_blocked`` rather than
            # ``infra_failed``. Both buckets block merge (``CheckSummary.ready``
            # is False for either), so the merge gate is unchanged -- only the
            # bucket/failure-message differs. ``infra_failed`` is NOT emptied
            # for its original population: ``_enrich_checks_infra_blocked``
            # only touches ``FAILURE``-conclusion checks, so genuine
            # ``CANCELLED``/``INFRA_FAILURE``/``TIMED_OUT`` checks still route
            # to ``infra_failed`` exactly as before (the #841 auto-rerun path
            # in ``review()`` is fed by ``run_janitor``, which sees raw checks
            # -- it never enriched FAILURE to INFRA_FAILURE pre-#1383, so the
            # #1383 change reroutes zero-step FAILURE from
            # ``is_check_failure_block`` (rework) to ``is_infra_blocked_block``
            # (hold), not from ``is_infra_failure_block``).
            enriched_checks = self._enrich_checks_infra_blocked(
                checks, self.config.auto_merge.required_checks
            )
            summary = summarize_checks(enriched_checks, self.config.auto_merge.required_checks)
        # Run containment check for worker edits leaked into operator checkout
        diff = self.gh.pr_diff(pr_number)
        containment_warnings = check_operator_containment(self.repo_root, diff, pr_number)
        if containment_warnings:
            # Log containment warnings as a pre-merge gate warning
            # This is report-only, not blocking (per issue directive)
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state = self._record_event(
                    state,
                    "containment_check",  # event-consumer: audit-only -- report-only per issue directive, not a blocking gate
                    {
                        "pr_number": pr_number,
                        "warnings": list(containment_warnings),
                    },
                )
                save_state(self.paths.state_file, state)
        # Readiness no-CI stall gate (issue #474): an approved PR whose required
        # checks have not appeared within ``readiness_no_ci_minutes`` is routed to
        # rework instead of waiting forever for CI that will never start.
        if (
            not checks_unavailable
            and approved
            and not sync_failed
            and not summary.ready
            and not _is_pending_only(summary)
            and issue_number is not None
        ):
            now = datetime.now(UTC)
            if _is_readiness_no_ci_stall(pr, enriched_checks, self.config.auto_merge, now):
                state = load_state_locked(self.paths.state_file)
                issue_state = state["issues"].get(str(issue_number), {})
                issue_status = issue_state.get("status")
                if issue_status not in (
                    "dispatched",
                    "dispatch_pending",
                    "manifest_written",
                    "escalated",
                    "blocked",
                    "rework_requested",
                ):
                    label_error = self._request_readiness_no_ci_rework(
                        pr, issue_number, decision, summary.missing
                    )
                    return CommandResult(
                        True,
                        f"PR #{pr_number} has not started required CI checks; rework requested",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "can_merge": False,
                            "merged": False,
                            "review_decision": decision,
                            "checks": asdict(summary),
                            "checks_unavailable": False,
                            "label_error": label_error,
                            "readiness_no_ci_stall": True,
                            "merge_conflict": merge_conflict,
                            "merge_attempt_alarm": False,
                            "merge_attempt_warning": None,
                        },
                    )

        # Issue #1060: derive ``can_merge`` from a single dict of gate inputs
        # and persist that same dict in the ``merge_ready`` event below. The
        # gate and the record now read from one source, so a future added
        # condition cannot silently fall out of the persisted payload the way
        # ``mergequeue_label_applied`` did (it existed only in the in-memory
        # return dict, never in events.db, so a query for it was vacuously 0
        # for every PR that has ever existed). A hand-maintained list of keys
        # drifts from the expression it describes; this dict *is* the
        # expression.
        merge_gate_inputs = {
            "summary_ready": summary.ready,
            "approved": approved,
            "require_approved_review": self.config.auto_merge.require_approved_review,
            "sync_failed": sync_failed,
        }
        can_merge = (
            merge_gate_inputs["summary_ready"]
            and (merge_gate_inputs["approved"] or not merge_gate_inputs["require_approved_review"])
            and not merge_gate_inputs["sync_failed"]
        )
        # Issue #840: escalation gate on the merge-execution block. An
        # approved, green, conflict-free PR whose linked issue (or the PR
        # itself) is escalated (status == "escalated", i.e. a human has been
        # asked to intervene via agent:human-needed) must NOT be actually
        # merged while that flag is up -- even when the specific reason for
        # escalation is unrelated to mergeability (e.g. a dead request-
        # changes-fix worker exhausting the watchdog's redispatch cap; real
        # corpus: issues #592/#648/#606). Silently completing an irreversible
        # merge while escalated defeats the purpose of raising the flag.
        #
        # This is a plain gate on the merge-execution block ONLY -- it does
        # NOT modify ``can_merge``, so the failed-attempt-alarm counter block
        # below still sees ``can_merge`` True and zeroes the streak via the
        # ``elif can_merge:`` branch (a green pass held by escalation is not
        # a failed pass). Modifying ``can_merge`` itself would make
        # ``approved and not can_merge`` true, incrementing the counter every
        # pass and eventually firing a spurious merge_attempt_alarm for a PR
        # that isn't failing to merge for a mergeability reason -- a
        # diagnostic regression in the same spirit as the unbounded-counter
        # bug issue #777(b) fixed for PR #679.
        #
        # State is re-read here rather than reusing a flag computed at
        # function entry: the carry-forward / head_moved / merge-conflict
        # branches above can each write a new status for this PR/issue
        # mid-call, so only a read taken at this exact point is trustworthy
        # (same pattern as the head_moved branch's escalation read above).
        _escalation_snap = load_state_locked(self.paths.state_file)
        _pr_escalated, _issue_escalated = _escalation_flags(
            _escalation_snap.get("prs", {}).get(str(pr_number), {}),
            _escalation_snap.get("issues", {}).get(str(issue_number), {})
            if issue_number is not None
            else None,
        )
        escalated_merge_hold = can_merge and (_pr_escalated or _issue_escalated)
        should_merge = self.config.auto_merge.enabled if merge is None else merge
        merge_output: str | None = None
        # Issue #747: timestamp of the fleet's own merge_pr success (None until
        # the direct-merge branch runs and succeeds). Used for the
        # ``merge_succeeded`` event payload and the ``merged_at`` state field.
        _merged_at: str | None = None
        branch_deleted: bool | None = None
        update_results: list[dict[str, Any]] | None = None
        cancel_results: dict[str, Any] | None = None
        mergequeue_label_applied: bool | None = None
        merge_hold: bool = False
        merge_hold_check_unavailable: bool = False
        if can_merge and should_merge and not escalated_merge_hold:
            mergequeue_label = self.config.auto_merge.mergequeue_label
            if mergequeue_label:
                # Aviator MergeQueue handoff (task #10): apply the trigger
                # label instead of self-merging. add_pr_label is PR-scoped
                # (issue_number may be None for cross-repo PRs) and idempotent.
                # State records status="mergequeue" (never "merged"), so the
                # idempotency short-circuit at the top of this method does not
                # fire — a re-run of `ship-it` while the queue merge is still
                # pending safely re-applies the (no-op) label. Aviator does
                # its own queue rebase (replacing _update_open_agent_prs) and
                # GitHub auto-closes the linked issue via the PR's "Closes #N"
                # body; branch deletion is configured on the Aviator side.
                # cancel_superseded_runs is the one accepted residual gap (see
                # PR description). Once GitHub reports the PR merged,
                # reconcile.py's merged_outside_orchestrator drift path
                # reconciles status to "merged" and runs the "merged" label
                # transition — no new post-merge bookkeeping is added here.
                #
                # Issue #496: an operator can park an approved PR by adding the
                # configured merge-hold label to the PR or its linked issue.
                # When the hold is present, skip the mergequeue re-add entirely.
                # Scope note: this hold check runs only in mergequeue mode
                # (when ``mergequeue_label`` is set). In direct-merge mode the
                # hold label has no effect — the issue title scopes this to
                # "the mergequeue re-add," so the self-merge branch is unchanged.
                merge_hold = self.config.labels.merge_hold in label_names(pr)
                if not merge_hold and issue_number is not None:
                    try:
                        issue = self.gh.issue_view(issue_number)
                    except (GitHubError, ValueError):
                        merge_hold_check_unavailable = True
                        issue = None
                    if not merge_hold_check_unavailable and (
                        not isinstance(issue, dict) or "labels" not in issue
                    ):
                        merge_hold_check_unavailable = True
                        issue = None
                    if not merge_hold_check_unavailable:
                        issue_labels = label_names(issue) if issue else set()
                        merge_hold = self.config.labels.merge_hold in issue_labels
                if not merge_hold and not merge_hold_check_unavailable:
                    mergequeue_label_applied = self.gh.add_pr_label(pr_number, mergequeue_label)
                if mergequeue_label_applied:
                    with state_lock(self.paths.state_file):
                        state = load_state(self.paths.state_file)
                        _existing_pr_entry = state["prs"].get(str(pr_number), {})
                        _pr_update: dict[str, Any] = {
                            **_existing_pr_entry,
                            "number": pr_number,
                            "issue_number": issue_number,
                            "status": "mergequeue",
                            # Issue #1402: clear the self-revocation reason now
                            # that the label has been re-applied (carry-forward
                            # re-validated the approval), so a subsequent
                            # Aviator #823 silent rejection is not misread as a
                            # stale self-revocation. Setting to None (rather
                            # than deleting the key) keeps the entry shape
                            # stable for callers that .get() it defensively.
                            "mergequeue_revoked_reason": None,
                        }
                        # Issue #823 ordering hazard: do NOT zero the counter
                        # when this re-add is recovering from a cross-pass
                        # revert (mergequeue_label_reverted). This write runs
                        # BEFORE mergequeue_handoff_failed is computed and its
                        # increment is persisted further down in this same
                        # pass -- unconditionally zeroing here would hand that
                        # later increment a false 0 baseline every single
                        # reverted pass, so the counter would land on 1
                        # forever instead of accumulating, making the
                        # escalation this issue adds permanently unreachable
                        # for any threshold > 1. Verified empirically: without
                        # this guard a 3-pass simulation (revert, revert,
                        # revert) produces 1, 1, 1; with it, 1, 2, 3.
                        if not mergequeue_label_reverted:
                            _pr_update["consecutive_failed_merge_attempts"] = 0
                        state["prs"][str(pr_number)] = _pr_update
                        if issue_number is not None:
                            _issue_key = str(issue_number)
                            _issue_entry = state["issues"].get(_issue_key, {})
                            state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
                        save_state(self.paths.state_file, state)
                # else: add_pr_label failed. The label IS the handoff, so a
                # failure here must not advance status to "mergequeue" —
                # treating a failed label add as success would silently
                # orphan the PR (never self-merged, never picked up by
                # Aviator, and nothing would ever look wrong to state). Leave
                # status/counters untouched; the shared failed-attempt-alarm
                # block below (mergequeue_handoff_failed) increments
                # consecutive_failed_merge_attempts on every retry and can
                # escalate exactly like an unmergeable approved PR.
            else:
                # Merge, then labels, then best-effort branch deletion — in that
                # order. merge_pr is the irreversible step: persist status="merged"
                # to state IMMEDIATELY after it succeeds and BEFORE the label
                # transition, so a transition failure or Ctrl+C can't leave GitHub
                # merged while state.json still shows "reviewing" — which made
                # reconcile false-positive on every clean auto-merge and lost the
                # merged fact entirely on a crash between merge and save.
                merge_output = self.gh.merge_pr(
                    pr_number,
                    self.config.auto_merge.strategy,
                    admin=self.config.auto_merge.admin,
                    merge_flags=self.config.auto_merge.merge_flags,
                )
                # Issue #747: stamp ``merged_at`` at the irreversible step so
                # merge throughput/latency are computable from state.json.
                # Existing merged entries are not back-dated — this only fires
                # on a genuine non-merged -> merged transition (merge_pr just
                # succeeded), so the timestamp is the real merge time.
                _merged_at = utc_now()
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state["prs"][str(pr_number)] = {
                        **state["prs"].get(str(pr_number), {}),
                        "number": pr_number,
                        "issue_number": issue_number,
                        "status": "merged",
                        "merged": True,
                        "merged_at": _merged_at,
                        "consecutive_failed_merge_attempts": 0,
                    }
                    if issue_number is not None:
                        _issue_key = str(issue_number)
                        _issue_entry = state["issues"].get(_issue_key, {})
                        state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
                    save_state(self.paths.state_file, state)
                # Label + branch cleanup are best-effort; the merged fact is already
                # durable. A branch-deletion failure (head branch checked out in a
                # worktree) or label failure must never un-record the merge.
                if issue_number is not None:
                    result = transition(self.gh, self.config.labels, issue_number, "merged")
                    if result.outcome != TransitionOutcome.APPLIED:
                        label_error = {
                            "edge": "merged",
                            "outcome": result.outcome.value,
                            "add_failures": result.add_failures,
                            "remove_failures": result.remove_failures,
                        }
                    # Close the linked issue explicitly — idempotent if already closed
                    # via GitHub's keyword automation. This ensures the dependency gate
                    # sees the closure immediately, avoiding the agent:done+OPEN state.
                    self.gh.close_issue(issue_number)
                if self.config.auto_merge.delete_branch:
                    head_ref = str(pr.get("headRefName") or "")
                    branch_deleted = self.gh.delete_branch(head_ref) if head_ref else False
                # Update remaining open agent PRs after successful merge (if configured)
                if self.config.auto_merge.update_branch_strategy in {
                    "broadcast",
                    "front_of_train",
                }:
                    update_results = self._update_open_agent_prs(pr_number)
                # Cancel superseded queued runs on default branch after successful merge (if configured)
                if self.config.runners.enabled and self.config.runners.cancel_superseded_main_runs:
                    cancel_results = cancel_superseded_runs(
                        self.gh,
                        self.config.runners.default_branch,
                        self.config.runners.workflow_name,
                    )
        # Aviator MergeQueue handoff (task #10): the label add IS the handoff
        # — a failed add_pr_label must be treated as a genuine unmergeable
        # pass (like an unmet check or a merge conflict), not silently
        # swallowed as best-effort cleanup. can_merge is True here (checks
        # green, approved), so the "approved and not can_merge" alarm gate
        # below would otherwise never fire for this failure mode.
        #
        # Issue #823: folded into the SAME signal (rather than a parallel
        # mechanism) is mergequeue_label_reverted -- an outright POST failure
        # and a POST that succeeded but was silently reverted by Aviator by
        # the next pass are the same underlying failure (the PR never
        # actually made it into Aviator's queue) and must share the same
        # counter-increment/escalation path.
        #
        # The revert term is additionally gated on can_merge: a revert can
        # also be Aviator declining the PR for a genuine reason (e.g. a
        # required check went red), in which case can_merge is False on this
        # pass and the failure is a check failure, not a handoff failure. If
        # mergequeue_handoff_failed were True here it would shadow the
        # check-failure-rework dispatch gate below (`not
        # mergequeue_handoff_failed`), permanently blocking rework for a
        # fixable check failure. The counter still increments in that case
        # via the pre-existing "approved and not can_merge" disjunct in the
        # final counter-persistence block, so escalation is unaffected --
        # only the handoff-specific attribution and the handoff-specific
        # (non-)dispatch of check-failure-rework are.
        mergequeue_handoff_failed = bool(
            self.config.auto_merge.mergequeue_label and mergequeue_label_applied is False
        ) or (mergequeue_label_reverted and can_merge and not mergequeue_self_revoked_stale_head)
        # Conflict-rework dispatch is debounced to the failed-attempt alarm
        # threshold so a single transient/stale CONFLICTING reading does not
        # clobber an approved verdict. Re-read the issue status and the PR
        # attempt counter immediately before dispatch: the preceding checks,
        # diff, and containment work are network-I/O windows long enough for a
        # concurrent pass to have moved the issue into an in-flight or
        # human-terminal state, and the stale `existing_pr_state` snapshot can
        # diverge from the counter the final persistence block will reload
        # (e.g. a carry-forward reset in this same pass). Dispatch outside the
        # final state-lock because _route_janitor_gate_failure_to_rework
        # acquires its own lock.
        #
        # Issues #776/#777: this used to call _request_merge_conflict_rework
        # directly, bypassing conflict_rework_attempts entirely -- the only
        # gate was this threshold check, so a PR could be re-dispatched to
        # rework on every pass forever with no cap, and consecutive_failed_
        # merge_attempts (a diagnostic-only alarm counter, see
        # AutoMergeConfig.failed_attempt_alarm) was the only "cap" a human
        # could point to. It is now routed through the SAME
        # attempts_key-capped wrapper review()'s janitor gate uses, so there
        # is exactly one place in the codebase that increments
        # conflict_rework_attempts and decides dispatch vs. rescue vs.
        # escalation for this lane -- and the attempt is counted (line
        # `attempts = ... + 1` inside that wrapper) BEFORE any subsequent
        # worker-launch failure (e.g. a deterministic worktree_unsafe at
        # actual dispatch time, real corpus: PR #679/issue #602) can
        # escalate, so a launch failure no longer bypasses the cap.
        # "manifest_written"/"blocked" remain pre-checked here because they
        # are merge_ready()-specific concerns the shared wrapper does not
        # know about: manifest_written means an unrelated worker is being
        # launched for this issue right now (preempting it would race that
        # launch), and blocked is a human reviewer verdict that must never be
        # silently routed around. "dispatched"/"dispatch_pending"/
        # "rework_requested" and "escalated" are deliberately NOT
        # pre-excluded any more: the wrapper's own rework_pending check
        # already treats the first three as in-flight (returning None, a
        # no-op here), and its own attempts_key cap -- untouched by an
        # escalation from an unrelated lane, already exhausted if this lane
        # is what escalated the issue -- is what correctly decides
        # "escalated" (issue #776's fix; real corpus: issues #592/#648/#606).
        if (
            merge_conflict
            and approved
            and not can_merge
            and not _is_pending_only(summary)
            and issue_number is not None
        ):
            state = load_state_locked(self.paths.state_file)
            issue_state = state["issues"].get(str(issue_number), {})
            issue_status = issue_state.get("status")
            existing_for_route = state["prs"].get(str(pr_number), {})
            if issue_status not in ("manifest_written", "blocked"):
                new_attempts_for_route = (
                    int(existing_for_route.get("consecutive_failed_merge_attempts", 0)) + 1
                )
                threshold = self.config.auto_merge.failed_attempt_alarm
                if threshold > 0 and new_attempts_for_route >= threshold:
                    routed = self._route_janitor_gate_failure_to_rework(
                        pr,
                        issue_number,
                        attempts_key="conflict_rework_attempts",
                        max_attempts=self.config.review.max_conflict_rework_attempts,
                        reason="merge_conflict",
                        router=self._request_merge_conflict_rework,
                    )
                    if routed is not None:
                        merge_conflict_routed = bool(routed.data.get("routed_to_rework"))
                        merge_conflict_escalated = bool(routed.data.get("escalated"))
                        rework_label_error = routed.data.get("label_error")
        # Check-failure rework dispatch (issue #674): an approved PR whose
        # required checks have genuinely failed (a completed FAILURE
        # conclusion, not merely pending/missing/infra_failed/unavailable)
        # never re-enters review()'s janitor gate once approved -- the
        # already_approved fast path in loop() routes straight to
        # merge_ready as long as the head hasn't moved, so nothing else in
        # the orchestrator ever pushes it back to rework. Debounced to the
        # same failed-attempt-alarm threshold as merge-conflict rework
        # (above) so a transient failure or the mergequeue's own
        # speculative-merge retry gets a chance to self-heal first.
        # Deliberately scoped to `summary.failed` only: `missing`/
        # `infra_failed`/`unavailable` checks are not something a code push
        # can reliably fix and are left to the existing warning-only alarm.
        if (
            not merge_conflict
            and not cross_pr_revert_detected
            and not mergequeue_handoff_failed
            and approved
            and not can_merge
            and bool(summary.failed)
            and issue_number is not None
        ):
            state = load_state_locked(self.paths.state_file)
            issue_state = state["issues"].get(str(issue_number), {})
            issue_status = issue_state.get("status")
            existing_for_route = state["prs"].get(str(pr_number), {})
            if issue_status not in (
                "dispatched",
                "dispatch_pending",
                "manifest_written",
                "escalated",
                "blocked",
                "rework_requested",
            ):
                new_attempts_for_route = (
                    int(existing_for_route.get("consecutive_failed_merge_attempts", 0)) + 1
                )
                threshold = self.config.auto_merge.failed_attempt_alarm
                if threshold > 0 and new_attempts_for_route >= threshold:
                    check_failure_routed = True
                    rework_label_error = self._request_check_failure_rework(
                        pr, issue_number, decision, summary
                    )
        if rework_label_error is not None:
            label_error = rework_label_error
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            existing = state["prs"].get(str(pr_number), {})
            # Issue #861: default to PRESERVING the prior count, not resetting
            # to 0. A pending-only pass (checks still in flight) falls through
            # both branches below and previously clobbered an accumulated
            # count with 0 every time, defeating the threshold debounce.
            # Indeterminate passes must leave the counter untouched; only a
            # genuine-success pass (the `elif can_merge:` below) or an
            # explicit merge (handled earlier, before this block re-reads
            # `existing`) may zero it.
            new_attempts = int(existing.get("consecutive_failed_merge_attempts", 0))
            new_stale_base_deferrals = 0
            merge_attempt_alarm = False
            merge_attempt_warning: str | None = None
            if (
                approved and not can_merge and not _is_pending_only(summary)
            ) or mergequeue_handoff_failed:
                new_attempts = int(existing.get("consecutive_failed_merge_attempts", 0)) + 1
                threshold = self.config.auto_merge.failed_attempt_alarm
                # Issue #777(b): this counter previously had no ceiling and
                # grew unbounded across passes (real corpus: PR #679 reached
                # 12 and climbing) because nothing ever reset it once a
                # rework was dispatched and pending. It is not purely
                # diagnostic -- the merge-conflict rework-dispatch block
                # above and the check-failure rework-dispatch block above
                # both read this same counter as a `>= threshold` debounce
                # gating *first*-dispatch timing -- but it does not bound
                # *repeat* dispatch; that functional bound is
                # conflict_rework_attempts/no_op_rework_attempts, enforced by
                # _route_janitor_gate_failure_to_rework above. Clamp at
                # threshold + 1 (not at threshold): clamping AT threshold
                # would make `merge_attempt_alarm` below re-fire every pass
                # once clamped, turning a one-time alarm into a cost spiral;
                # threshold + 1 keeps the alarm's "== threshold" one-shot
                # semantics intact while still giving every trigger sharing
                # this counter (check-failure, cross-PR-revert, mergequeue
                # handoff) a stable ">= threshold" debounce reading forever
                # after the first alarm fires, instead of an ever-growing one.
                if threshold > 0:
                    new_attempts = min(new_attempts, threshold + 1)
                merge_attempt_alarm = threshold > 0 and new_attempts == threshold
                if merge_attempt_alarm:
                    if merge_conflict:
                        pass_str = "pass" if new_attempts == 1 else "passes"
                        if issue_number is None:
                            conflict_detail = "no linked issue, cannot route to rework"
                        elif merge_conflict_escalated:
                            conflict_detail = "conflict-rework cap exhausted; escalated to a human"
                        elif merge_conflict_routed:
                            if rework_label_error:
                                outcome = rework_label_error.get("outcome", rework_label_error)
                                conflict_detail = (
                                    f"rework dispatch attempted (label update failed: {outcome})"
                                )
                            else:
                                conflict_detail = "rework dispatched"
                        elif issue_status == "rework_requested":
                            conflict_detail = "rework already requested"
                        else:
                            conflict_detail = "rework not routed"
                        merge_attempt_warning = (
                            f"PR #{pr_number} approved but unmergeable for {new_attempts} {pass_str}: "
                            f"merge conflict — {conflict_detail}"
                        )
                    elif cross_pr_revert_detected:
                        pass_str = "pass" if new_attempts == 1 else "passes"
                        if issue_number is None:
                            revert_detail = "no linked issue, cannot route to rework"
                        elif cross_pr_revert_routed:
                            if rework_label_error:
                                outcome = rework_label_error.get("outcome", rework_label_error)
                                revert_detail = (
                                    f"rework dispatch attempted (label update failed: {outcome})"
                                )
                            else:
                                revert_detail = "rework dispatched"
                        elif issue_status == "rework_requested":
                            revert_detail = "rework already requested"
                        else:
                            revert_detail = "rework not routed"
                        merge_attempt_warning = (
                            f"PR #{pr_number} approved but unmergeable for {new_attempts} {pass_str}: "
                            f"cross-PR revert — {revert_detail}"
                        )
                    elif mergequeue_handoff_failed:
                        pass_str = "pass" if new_attempts == 1 else "passes"
                        merge_attempt_warning = (
                            f"PR #{pr_number} approved and checks green but the mergequeue "
                            f"label {self.config.auto_merge.mergequeue_label!r} failed to "
                            f"apply for {new_attempts} {pass_str} — never handed off to "
                            "Aviator"
                        )
                    elif bool(summary.failed):
                        pass_str = "pass" if new_attempts == 1 else "passes"
                        if issue_number is None:
                            check_detail = "no linked issue, cannot route to rework"
                        elif check_failure_routed:
                            if rework_label_error:
                                outcome = rework_label_error.get("outcome", rework_label_error)
                                check_detail = (
                                    f"rework dispatch attempted (label update failed: {outcome})"
                                )
                            else:
                                check_detail = "rework dispatched"
                        elif issue_status == "rework_requested":
                            check_detail = "rework already requested"
                        else:
                            check_detail = "rework not routed"
                        failed_str = ", ".join(summary.failed)
                        merge_attempt_warning = (
                            f"PR #{pr_number} approved but unmergeable for {new_attempts} {pass_str}: "
                            f"required check(s) failed ({failed_str}) — {check_detail}"
                        )
                    else:
                        merge_attempt_warning = _format_merge_attempt_alarm_message(
                            pr_number,
                            new_attempts,
                            summary,
                            mergeable=pr.get("mergeable"),
                            merge_state_status=pr.get("mergeStateStatus"),
                        )
                    state = self._record_event(
                        state,
                        "merge_failed_attempt_alarm",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "attempts": new_attempts,
                            "threshold": threshold,
                            "checks_summary": asdict(summary),
                            # Issue #751: carry GitHub's own mergeability signal
                            # alongside checks_summary so the event is
                            # diagnosable without re-deriving state that has
                            # since changed (mergeable/mergeStateStatus are
                            # already fetched by pr_view — see field list at
                            # _PR_SLIM_FIELDS).
                            "mergeable": pr.get("mergeable"),
                            "merge_state_status": pr.get("mergeStateStatus"),
                            "message": merge_attempt_warning,
                        },
                    )
            elif can_merge:
                # Genuine success: checks are ready (or an explicit merge/
                # mergequeue-handoff already reset the persisted value above,
                # which this re-read of `existing` picked up) and this is not
                # a mergequeue-handoff failure (guaranteed by the `if` above:
                # mergequeue_handoff_failed can only be True when can_merge is
                # True, so if it were True this branch would not be reached).
                # A confirmed-mergeable pass is real positive information, so
                # it is safe -- and correct -- to zero the streak here, unlike
                # the pending-only case above which conveys no information.
                new_attempts = 0
            if (
                approved
                and can_merge
                and merge_output is None
                and not mergequeue_handoff_failed
                and not merge_hold_check_unavailable
            ):
                # merge=False / auto_merge.enabled=False: can_merge recovered but no
                # merge was attempted. Clear the merge alert so a subsequent
                # degradation can re-fire the digest (last_health == current_health
                # dedup would otherwise drop it). Excluded when the mergequeue
                # handoff itself failed or the merge-hold issue check was
                # unavailable — both are genuine problems, not benign
                # evaluation-only passes, and must not be masked as OK.
                if issue_number is not None:
                    _issue_key = str(issue_number)
                    _issue_entry = state["issues"].get(_issue_key, {})
                    if _issue_entry.get("merge_alert") != "OK":
                        state["issues"][_issue_key] = {**_issue_entry, "merge_alert": "OK"}
            prs_entry: dict[str, Any] = {
                **existing,
                "number": pr_number,
                "issue_number": issue_number,
                "consecutive_failed_merge_attempts": new_attempts,
                "consecutive_stale_base_deferrals": new_stale_base_deferrals,
            }
            if merge_output:
                prs_entry["status"] = "merged"
                prs_entry["merged"] = True
            # Issue #1401: track time-in-mergequeue for the wedge watchdog.
            # ``mergequeue_since`` is the moment the PR entered Aviator's queue
            # at its current head; ``mergequeue_head_sha`` is that head. A head
            # advance (Aviator rebase) resets both, so the watchdog's
            # time-in-queue trigger measures true no-progress dwell, not wall
            # time since the first handoff. Cleared whenever the PR is not
            # currently in mergequeue so a later re-entry starts a fresh window.
            _current_head = pr.get("headRefOid")
            if prs_entry.get("status") == "mergequeue" and _current_head:
                if existing.get("mergequeue_head_sha") == _current_head and existing.get(
                    "mergequeue_since"
                ):
                    prs_entry["mergequeue_since"] = existing["mergequeue_since"]
                    prs_entry["mergequeue_head_sha"] = existing["mergequeue_head_sha"]
                else:
                    prs_entry["mergequeue_since"] = utc_now()
                    prs_entry["mergequeue_head_sha"] = _current_head
            else:
                prs_entry.pop("mergequeue_since", None)
                prs_entry.pop("mergequeue_head_sha", None)
            state["prs"][str(pr_number)] = prs_entry
            state = self._record_event(
                state,
                "merge_ready",
                {
                    "pr_number": pr_number,
                    "can_merge": can_merge,
                    "merged": bool(merge_output),
                    "merge_hold": merge_hold,
                    "merge_hold_check_unavailable": merge_hold_check_unavailable,
                    "cancel_superseded_runs_results": cancel_results,
                    # Issue #1060: persist the Aviator handoff outcome so a
                    # query for it is no longer vacuously 0 for every PR. This
                    # key previously existed only in the in-memory return dict
                    # below, never in events.db.
                    "mergequeue_label_applied": mergequeue_label_applied,
                    # Issue #1060: persist the three gate inputs alongside the
                    # conclusion so a ``can_merge=False`` can be diagnosed from
                    # events.db alone. Spread from the same dict the gate reads
                    # (``merge_gate_inputs`` above) so a future added condition
                    # cannot silently fall out of the record.
                    **merge_gate_inputs,
                },
            )
            # Issue #747: emit a dedicated terminal success event on the
            # fleet's own direct-merge path. ``merge_output`` is truthy only
            # when ``merge_pr`` actually ran and succeeded (it stays None for
            # mergequeue handoffs, deferrals, conflicts, and skipped/deferred
            # passes), so this fires exactly once per real fleet merge and is
            # silent on every other outcome — the negative control the issue
            # requires. ``actor="fleet"`` distinguishes these from
            # externally-merged PRs, which are recorded by
            # ``finalize_externally_merged`` / ``merged_outside_orchestrator``
            # and never emit this kind.
            if merge_output:
                state = self._record_event(
                    state,
                    "merge_succeeded",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "actor": "fleet",
                        "merge_method": self.config.auto_merge.strategy,
                        "merged_at": _merged_at,
                    },
                )
            save_state(self.paths.state_file, state)
        data = {
            "pr": pr_number,
            "issue": issue_number,
            "can_merge": can_merge,
            "auto_merge_enabled": self.config.auto_merge.enabled,
            "merged": bool(merge_output),
            "merge_output": merge_output,
            "branch_deleted": branch_deleted,
            "review_decision": decision,
            "checks": asdict(summary),
            "checks_unavailable": checks_unavailable,
            "label_error": label_error,
            "update_open_prs_results": update_results,
            "cancel_superseded_runs_results": cancel_results,
            "containment_warnings": list(containment_warnings),
            "consecutive_failed_merge_attempts": new_attempts,
            "consecutive_stale_base_deferrals": new_stale_base_deferrals,
            "merge_attempt_alarm": merge_attempt_alarm,
            "merge_attempt_warning": merge_attempt_warning,
            "merge_conflict": merge_conflict,
            "cross_pr_revert_detected": cross_pr_revert_detected,
            "cross_pr_revert_reason": cross_pr_revert_reason,
            "cross_pr_revert_routed": cross_pr_revert_routed,
            "mergequeue_label_applied": mergequeue_label_applied,
            "merge_hold": merge_hold,
            "merge_hold_check_unavailable": merge_hold_check_unavailable,
            "escalated_merge_hold": escalated_merge_hold,
            # Issue #1060: surface the gate inputs in the in-memory verdict
            # too, for diagnostic parity with the persisted event.
            **merge_gate_inputs,
        }
        message = "merge readiness evaluated"
        if cross_pr_revert_detected:
            message = f"cross-PR revert detected: {cross_pr_revert_reason}"
        elif checks_unavailable:
            message = "checks unavailable (gh failure)"
        elif escalated_merge_hold:
            message += " (escalated — merge held while agent:human-needed is up)"
        elif merge_hold_check_unavailable:
            message += f" (merge-hold check unavailable for issue #{issue_number} — not handed off to Aviator)"
        elif merge_hold:
            message += (
                f" (merge-hold label {self.config.labels.merge_hold!r} present — left alone)"
            )
        elif mergequeue_label_applied is False:
            message += (
                f" (mergequeue label {self.config.auto_merge.mergequeue_label!r} FAILED to "
                f"apply — not handed off to Aviator; will retry, attempt {new_attempts})"
            )
        elif mergequeue_label_applied is True:
            message += (
                f" (handed off to mergequeue label {self.config.auto_merge.mergequeue_label!r})"
            )
        elif merge_output and label_error:
            message += f" (merged; post-merge label/branch cleanup failed: {label_error})"
        elif label_error:
            message += f" (label update failed: {label_error.get('outcome', label_error)})"
        return CommandResult(
            not (checks_unavailable or merge_hold_check_unavailable), message, data
        )

    def _merge_ready_dry_run(
        self,
        pr_number: int,
        *,
        merge: bool | None = None,
        merge_train_head: int | None = None,
    ) -> CommandResult:
        """Dry-run readiness evaluation for ``merge_ready`` (issue #614).

        Mirrors the read-only prefix of :meth:`merge_ready` — fetching the PR,
        review decision, checks, diff, and computing ``can_merge`` — but skips
        every state write, label transition, branch update, merge, and
        mergequeue label add.  Returns the computed readiness verdict so a
        preview can report what *would* happen without fabricating a merge or
        stranding the PR in a terminal state.

        The gate in :meth:`merge_ready` sits above its ``state_lock`` (the
        idempotency short-circuit conditionally writes) and touches nothing,
        mirroring ``_dispatch_impl``'s dry-run gate.  Gating lower would drop
        into the shared failed-attempt-alarm block and increment
        ``consecutive_failed_merge_attempts``, advancing the state machine
        instead of merely previewing it.
        """
        # Read-only state snapshot.  Dry-run never writes, but the locked
        # read helper is still required: ``load_state_locked`` is the single
        # point of enforcement for read-only ``load_state`` calls outside an
        # explicit ``state_lock`` block (issue #310, enforced by
        # ``test_no_unlocked_load_state_in_production_code``).  Holding the
        # advisory lock during the read also prevents a concurrent writer's
        # tmp+replace from racing this read.  The idempotency short-circuit's
        # conditional merge_alert clear is a write and is skipped; the verdict
        # is still accurate because "already merged" is a read-only fact.
        state = load_state_locked(self.paths.state_file)
        existing_pr_state = state["prs"].get(str(pr_number), {})
        if existing_pr_state.get("status") == "merged":
            return CommandResult(
                True,
                f"PR #{pr_number} already merged",
                {
                    "pr": pr_number,
                    "issue": existing_pr_state.get("issue_number"),
                    "already_merged": True,
                    "merged": True,
                    "dry_run": True,
                },
            )

        pr = self.gh.pr_view(pr_number)
        if not pr:
            return CommandResult(False, f"PR #{pr_number} was not found", {})

        issue_number = linked_issue_number(
            pr,
            is_cross_repository=pr.get("isCrossRepository"),
            branch_prefix=self.config.dispatch.branch_prefix,
        )
        decision = self._review_decision(pr_number)
        approved = decision.get("decision") == "approved"
        sync_failed = False
        merge_conflict = False
        cross_pr_revert_detected = False
        cross_pr_revert_reason: str | None = None

        if approved:
            reviewed_head_sha = decision.get("reviewed_head_sha")
            live_head_sha = pr.get("headRefOid")
            head_moved = reviewed_head_sha is None or live_head_sha != reviewed_head_sha
            if head_moved and live_head_sha:
                check = self._check_carry_forward(pr_number, decision)
                if not check.carry_forward:
                    # Under dry-run the head-moved re-review transition
                    # (state write + label transition) is skipped; return the
                    # verdict without persisting.
                    return CommandResult(
                        False,
                        "PR head moved since approval — re-review required",
                        {
                            "pr": pr_number,
                            "issue": issue_number,
                            "can_merge": False,
                            "merged": False,
                            "head_moved": True,
                            "reviewed_head_sha": reviewed_head_sha,
                            "live_head_sha": live_head_sha,
                            "review_decision": decision,
                            "dry_run": True,
                        },
                    )
                # Carry-forward would apply; continue with read-only checks.
                # The approval-head write (_update_approval_head) is skipped
                # under dry-run, so reviewed_head_sha stays stale — but
                # ``approved`` is still True and ``can_merge`` depends on
                # checks/sync_failed, not on the head SHA directly.

            # Genuine merge conflict detection (read-only).
            if self._is_merge_conflict(pr):
                merge_conflict = True
                sync_failed = True

            update_branch_strategy = self.config.auto_merge.update_branch_strategy
            if update_branch_strategy == "front_of_train":
                if merge_train_head is not None and merge_train_head != pr_number:
                    return self._merge_not_ready_result(
                        pr_number, issue_number, decision, existing_pr_state
                    )
                if merge_train_head is None:
                    try:
                        prs = self.gh.pr_list()
                    except GitHubError:
                        sync_failed = True
                    else:
                        head = self._merge_train_head(prs)
                        if head is not None and head != pr_number:
                            return self._merge_not_ready_result(
                                pr_number, issue_number, decision, existing_pr_state
                            )

            # Base freshness check (read-only). The ``pr_update_branch`` WRITE
            # is skipped under dry-run; if the base is stale, report the
            # deferral without persisting the counter increment or event.
            if not sync_failed and update_branch_strategy != "off":
                base_currency_gated = self._is_base_currency_gated(
                    pr.get("baseRefName") or self.config.runners.default_branch
                )
                if base_currency_gated and update_branch_strategy in {
                    "front_of_train",
                    "broadcast",
                }:
                    base_current = self._is_base_current(pr)
                    if base_current is not True:
                        return CommandResult(
                            True,
                            f"PR #{pr_number} base is stale; merge deferred until base is current",
                            {
                                "pr": pr_number,
                                "issue": issue_number,
                                "can_merge": False,
                                "auto_merge_enabled": self.config.auto_merge.enabled,
                                "merged": False,
                                "merge_output": None,
                                "branch_deleted": None,
                                "review_decision": decision,
                                "checks": asdict(
                                    summarize_checks([], self.config.auto_merge.required_checks)
                                ),
                                "checks_unavailable": False,
                                "label_error": None,
                                "update_open_prs_results": None,
                                "cancel_superseded_runs_results": None,
                                "containment_warnings": [],
                                "stale_base": True,
                                "consecutive_failed_merge_attempts": (
                                    existing_pr_state.get("consecutive_failed_merge_attempts", 0)
                                ),
                                "consecutive_stale_base_deferrals": (
                                    existing_pr_state.get("consecutive_stale_base_deferrals", 0)
                                ),
                                "merge_attempt_alarm": False,
                                "merge_attempt_warning": None,
                                "merge_conflict": False,
                                "dry_run": True,
                            },
                        )

            # Cross-PR revert detection (read-only). The rework routing write
            # is skipped under dry-run.
            if not sync_failed:
                cross_pr_revert_reason = detect_cross_pr_revert(pr, self.repo_root)
                if cross_pr_revert_reason:
                    cross_pr_revert_detected = True
                    sync_failed = True

        checks = self.gh.pr_checks(pr_number)
        checks_unavailable = checks is None

        if checks_unavailable:
            summary = summarize_checks(None, self.config.auto_merge.required_checks)
            enriched_checks: list[dict[str, Any]] = []
        else:
            # Issue #1383: shared data-boundary enrichment, same as the real
            # merge_ready path -- see _enrich_checks_infra_blocked.
            enriched_checks = self._enrich_checks_infra_blocked(
                checks, self.config.auto_merge.required_checks
            )
            summary = summarize_checks(enriched_checks, self.config.auto_merge.required_checks)

        diff = self.gh.pr_diff(pr_number)
        containment_warnings = check_operator_containment(self.repo_root, diff, pr_number)

        # Issue #1060: mirror the real path's dict-based gate so the two
        # duplicated gates cannot drift -- a future condition added to one but
        # not the other would silently diverge the dry-run preview from the
        # real verdict.
        merge_gate_inputs = {
            "summary_ready": summary.ready,
            "approved": approved,
            "require_approved_review": self.config.auto_merge.require_approved_review,
            "sync_failed": sync_failed,
        }
        can_merge = (
            merge_gate_inputs["summary_ready"]
            and (merge_gate_inputs["approved"] or not merge_gate_inputs["require_approved_review"])
            and not merge_gate_inputs["sync_failed"]
        )
        # Issue #840: mirror the real path's escalation gate so the dry-run
        # preview accurately reports "would be held" instead of "would merge"
        # when the PR or its linked issue is escalated. Reuses the read-only
        # ``state`` snapshot loaded at the top of this dry-run (no mid-call
        # writes happen in dry-run, unlike the real path's re-read).
        _pr_escalated, _issue_escalated = _escalation_flags(
            existing_pr_state,
            state.get("issues", {}).get(str(issue_number), {})
            if issue_number is not None
            else None,
        )
        escalated_merge_hold = can_merge and (_pr_escalated or _issue_escalated)
        should_merge = self.config.auto_merge.enabled if merge is None else merge
        mergequeue_label = self.config.auto_merge.mergequeue_label

        # Read-only merge-hold check (same condition as the real path).
        merge_hold = False
        merge_hold_check_unavailable = False
        if can_merge and should_merge and not escalated_merge_hold:
            merge_hold = self.config.labels.merge_hold in label_names(pr)
            if not merge_hold and issue_number is not None:
                try:
                    issue = self.gh.issue_view(issue_number)
                except (GitHubError, ValueError):
                    merge_hold_check_unavailable = True
                    issue = None
                if not merge_hold_check_unavailable and (
                    not isinstance(issue, dict) or "labels" not in issue
                ):
                    merge_hold_check_unavailable = True
                    issue = None
                if not merge_hold_check_unavailable:
                    issue_labels = label_names(issue) if issue else set()
                    merge_hold = self.config.labels.merge_hold in issue_labels

        # Describe what *would* happen so the preview is actionable.
        message = "dry-run: merge readiness evaluated"
        if can_merge and should_merge and not merge_hold and not escalated_merge_hold:
            if mergequeue_label:
                message += f" (would hand off to mergequeue label {mergequeue_label!r})"
            else:
                message += " (would merge)"
        elif escalated_merge_hold:
            message += " (escalated — would hold merge while agent:human-needed is up)"
        elif merge_hold:
            message += (
                f" (merge-hold label {self.config.labels.merge_hold!r} present"
                f" — would be left alone)"
            )
        elif merge_conflict:
            message += " (merge conflict — would route to rework on threshold)"
        elif cross_pr_revert_detected:
            message += f" (cross-PR revert: {cross_pr_revert_reason})"
        elif checks_unavailable:
            message = "dry-run: checks unavailable (gh failure)"
        elif merge_hold_check_unavailable:
            message += f" (merge-hold check unavailable for issue #{issue_number})"

        return CommandResult(
            not (checks_unavailable or merge_hold_check_unavailable),
            message,
            {
                "pr": pr_number,
                "issue": issue_number,
                "can_merge": can_merge,
                "auto_merge_enabled": self.config.auto_merge.enabled,
                "merged": False,
                "merge_output": None,
                "branch_deleted": None,
                "review_decision": decision,
                "checks": asdict(summary),
                "checks_unavailable": checks_unavailable,
                "label_error": None,
                "update_open_prs_results": None,
                "cancel_superseded_runs_results": None,
                "containment_warnings": list(containment_warnings),
                "consecutive_failed_merge_attempts": existing_pr_state.get(
                    "consecutive_failed_merge_attempts", 0
                ),
                "consecutive_stale_base_deferrals": existing_pr_state.get(
                    "consecutive_stale_base_deferrals", 0
                ),
                "merge_attempt_alarm": False,
                "merge_attempt_warning": None,
                "merge_conflict": merge_conflict,
                "cross_pr_revert_detected": cross_pr_revert_detected,
                "cross_pr_revert_reason": cross_pr_revert_reason,
                "cross_pr_revert_routed": False,
                "mergequeue_label_applied": None,
                "merge_hold": merge_hold,
                "merge_hold_check_unavailable": merge_hold_check_unavailable,
                "escalated_merge_hold": escalated_merge_hold,
                # Issue #1060: surface the gate inputs in the dry-run preview
                # too, for diagnostic parity with the persisted event.
                **merge_gate_inputs,
                "dry_run": True,
            },
        )

    @_guard_state_lock
    def spec_review(self, artifact_path: Path) -> CommandResult:
        """Run an explicit cross-family adversarial pass over a spec/plan file.

        Independent of ``cross_family.enabled`` (that flag governs the PR-auto path);
        this command is the pre-execution spec slot and always runs when invoked.
        """
        path = Path(artifact_path)
        artifact_text = path.read_text(encoding="utf-8")
        cfg = self.config.cross_family
        reviews_dir = self.paths.cross_family
        # Issue #618: skip directory creation in dry-run — the cross-family
        # model is not invoked (dry_run=True below), so no prompt/report is
        # written into this directory.
        if not self.dry_run:
            reviews_dir.mkdir(parents=True, exist_ok=True)
        slug = slugify(path.stem)
        prompt_text = self._render(
            "cross_family_spec_review.md",
            {"artifact_label": f"`{path}`", "artifact_text": artifact_text},
        )
        result = run_cross_family_review(
            model=cfg.model,
            command=cfg.command,
            repo_root=self.repo_root,
            prompt_text=prompt_text,
            prompt_path=reviews_dir / f"spec-{slug}-prompt.md",
            report_path=reviews_dir / f"spec-{slug}-review.md",
            timeout_seconds=cfg.timeout_seconds,
            dry_run=self.dry_run,
        )
        # Issue #618: gate the state write — dry-run must not record events
        # or mutate state.json.
        if not self.dry_run:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state = self._record_event(
                    state,
                    "spec_review",
                    {"artifact": str(path), "ok": result.ok, "model": cfg.model},
                )
                save_state(self.paths.state_file, state)
        if self.dry_run:
            return CommandResult(
                True,
                f"dry-run: would run spec cross-family review for {path}",
                {
                    "artifact": str(path),
                    "report_path": result.report_path,
                    "model": cfg.model,
                    "ok": False,
                    "dry_run": True,
                },
            )
        return CommandResult(
            result.ok,
            "spec cross-family review complete"
            if result.ok
            else f"spec cross-family review failed: {result.error}",
            {
                "artifact": str(path),
                "report_path": result.report_path,
                "model": cfg.model,
                "ok": result.ok,
            },
        )

    def _cross_family_for_pr(
        self,
        *,
        pr: dict[str, Any],
        issue: dict[str, Any],
        pr_dir: Path,
        pr_number: int,
        issue_number: int | None,
        diff_path: Path,
        enabled: bool | None,
        enforce_regen_budget: bool = True,
    ) -> tuple[str, CrossFamilyResult | None]:
        cfg: CrossFamilyConfig = self.config.cross_family
        use = cfg.enabled if enabled is None else enabled
        if not use or pr.get("isDraft"):
            return "", None
        report_path = pr_dir / "cross-family-review.md"
        # Issue #1078: the cross-family review is now asynchronous. A previous
        # pass may have launched a review via ``launch_cross_family_review``
        # (Popen, non-blocking) and left a ``.pending.json`` marker. Reap it
        # before deciding whether to launch a new one. This is the single
        # collection point — the same PR's pending review is reaped here or not
        # at all.
        reaped = reap_cross_family_review(report_path=report_path)
        if reaped is not None:
            if reaped.pending:
                # Still running — the review packet must NOT go out yet. Return
                # a pending result so ``review()`` defers the packet write; the
                # next pass will reap again. This is what prevents one repo's
                # reviewer latency from blocking the other repo's lane: the
                # fleet pass returns from this PR immediately.
                return "", reaped
            # Reaped a completed result (ok or fail). The report file has been
            # written by ``reap_cross_family_review``. If ok, the section is
            # ready -- UNLESS the PR's live head has moved on since the review
            # was launched (the review ran against an earlier head while this
            # pass's ``pr`` reflects the current one). Re-validate against
            # ``pr.get("headRefOid")`` with the same predicate the adjacent
            # reuse path below uses (``report_is_reusable``), so the two
            # cannot disagree about what counts as stale (issue #1081's
            # single-definition rule applies here too). If failed, check
            # exhaustion and fall through to relaunch.
            if reaped.ok:
                reaped_text = ""
                if report_path.exists() and report_path.stat().st_size > 0:
                    reaped_text = report_path.read_text(encoding="utf-8")
                if report_is_reusable(reaped_text, pr.get("headRefOid")):
                    return self._cross_family_section(report_path), reaped
                # Stale: the head moved while the review was in flight. Do
                # NOT serve it — fall through to the idempotent reuse check
                # below, which reaches the same "unusable" conclusion via the
                # same predicate and continues on to budget claim + relaunch,
                # exactly as a failed/unusable report would.
            else:
                # Reaped a failure — the failure stub is already written.
                # Check exhaustion for the attempt that just completed, then
                # fall through to the budget claim + relaunch path below.
                if enforce_regen_budget:
                    self._escalate_cross_family_regen_exhausted(
                        pr_number=pr_number,
                        issue_number=issue_number,
                        head_sha=pr.get("headRefOid"),
                        report_path=report_path,
                    )
        # Idempotent: a non-empty, semantically valid SUCCESS report is reused,
        # so repeated review()/loop() passes don't re-burn the cross-family model
        # on the same PR. Failure stubs (headed "(UNAVAILABLE)") and exit-zero
        # but empty/blocked reports must NOT satisfy this check — reusing them
        # turned one codex timeout and one blocked refusal into a permanent
        # silent skip on every subsequent pass.
        # Additionally, reports are invalidated when the PR head SHA changes
        # to prevent reviewing stale code (issue #156).
        text = ""
        if report_path.exists() and report_path.stat().st_size > 0:
            text = report_path.read_text(encoding="utf-8")
            # The wrapper text itself contains bold markdown ("**leads, not
            # verdicts**"), so validation runs against the model body only —
            # see report_is_reusable, which is also what loop()'s same-head
            # packet skip consults so the two cannot disagree (issue #1081).
            if report_is_reusable(text, pr.get("headRefOid")):
                return self._cross_family_section(report_path), CrossFamilyResult(
                    ok=True, report_path=str(report_path), model=cfg.model, reused=True
                )
        # The report is unusable, so the regeneration below is the repair -- and
        # it is the thing the per-head budget exists to bound, because it runs
        # the cross-family model for up to timeout_seconds and unbounded would
        # starve the other repo in the shared sequential loop (#1078).
        #
        # The claim therefore lives HERE, at the model call it bounds, and not
        # at loop()'s staleness check where it used to (issue #1099). review()
        # reaches this line only once the janitor gate has passed; a PR with
        # merge conflicts or missing required checks returns thousands of lines
        # earlier. Charging at the staleness check spent the whole budget
        # without ever regenerating, then escalated
        # "cross_family_report_unusable" against a PR whose actual problem was
        # the conflict the janitor gate had already reported in that same pass.
        # An operation that does not run must not be able to spend its own
        # budget -- which is why this placement is correct regardless of *which*
        # of review()'s early returns fires.
        #
        # `enforce_regen_budget` is False only for `charlie why-charlie-hate`,
        # the operator's manual re-run. See review()'s docstring: a human typing
        # a command is not a loop, and RUNBOOK.md's recovery procedure for an
        # exhausted budget depends on that path getting a fresh attempt.
        if (
            enforce_regen_budget
            and not self.dry_run
            and not self._claim_cross_family_regen_attempt(
                pr_number=pr_number,
                issue_number=issue_number,
                head_sha=pr.get("headRefOid"),
                report_head=extract_head_ref_oid(text) if text.strip() else None,
            )
        ):
            # Budget spent for this head; the pass that spent it escalated to a
            # human. Return the same shape as the disabled/draft path so the
            # packet still goes out, just without a cross-family section -- and
            # no further model call is spent on this head.
            return "", None
        prompt_text = self._render(
            "cross_family_review.md",
            {
                "pr_number": pr_number,
                "pr_title": pr.get("title", ""),
                "pr_url": pr.get("url", ""),
                "issue_number": issue_number or "UNKNOWN",
                "issue_title": issue.get("title", "UNKNOWN"),
                "pr_json_path": pr_dir / "pr.json",
                "diff_path": diff_path,
            },
        )
        # Issue #1078: launch asynchronously (Popen, non-blocking) instead of
        # calling ``run_cross_family_review`` synchronously. The subprocess
        # runs in the background; a ``.pending.json`` marker is written so the
        # next pass can reap the result via ``reap_cross_family_review``. This
        # returns immediately with ``pending=True``, so the fleet pass moves on
        # to the next repo without waiting for the cross-family model.
        result = launch_cross_family_review(
            model=cfg.model,
            command=cfg.command,
            repo_root=self.repo_root,
            prompt_text=prompt_text,
            prompt_path=pr_dir / "cross-family-prompt.md",
            report_path=report_path,
            timeout_seconds=cfg.timeout_seconds,
            dry_run=self.dry_run,
            head_ref_oid=pr.get("headRefOid"),
        )
        # If the launch succeeded, the result is pending — the review packet
        # must not go out yet. If the launch failed immediately (e.g. OSError),
        # the failure stub is already written; check exhaustion and return the
        # section so the packet goes out without a cross-family section (same
        # behaviour as the old synchronous path on launch failure).
        if result.pending:
            return "", result
        # Exhaustion is decided HERE, immediately after the model call that
        # spends the budget, because this is the only point at which both facts
        # the escalation asserts are actually observed: the model ran, and the
        # report it left behind is still unusable. Before #1099 this lived
        # inside the claim, which runs *before* the model -- so it could only
        # ever assert that a counter had been incremented, and on a
        # janitor-blocked PR that counter was incremented by a pass that never
        # invoked the model at all.
        #
        # Gated on the same flag as the claim: an unbudgeted manual run charges
        # nothing, so it must not be able to exhaust anything either.
        if enforce_regen_budget:
            self._escalate_cross_family_regen_exhausted(
                pr_number=pr_number,
                issue_number=issue_number,
                head_sha=pr.get("headRefOid"),
                report_path=report_path,
            )
        return self._cross_family_section(result.report_path), result

    def _read_advisories_from_pr_comment(
        self, pr_number: int
    ) -> tuple[AdvisoryRecord, ...] | None:
        """Read worker-published advisories from the PR-comment channel (#1466).

        Scans the PR's issue-level comments (a PR is also an issue, so its
        top-level comments live at ``repos/{owner}/{repo}/issues/<n>/comments``)
        for the most recent one whose body starts with
        ``ADVISORY_COMMENT_MARKER`` and parses it via
        ``attachment_hook_entry.parse_advisories_comment``.

        Returns ``None`` when no marker comment is present (the caller falls
        back to the local advisories log), or a tuple (possibly ``()``) when
        one is -- a present marker with no parseable records is still a
        present channel, so the caller does NOT fall back and the review
        packet renders an empty redirects-not-taken list rather than the
        "log not available" NOTE.

        The most-recent marker comment wins: a worker re-posts the comment on
        each push, so the latest one reflects the current head's advisories
        and any older marker comment is stale. ``_gh_api_list`` returns
        comments in chronological order (GitHub's default for that endpoint),
        so the last match in the list is the newest.

        Fail-soft: any GitHub API error (``_gh_api_list`` swallows them and
        returns ``[]``) yields ``None`` -- a transient API failure degrades to
        the local-log fallback rather than blocking packet generation, since
        this section is advisory-only.
        """
        owner_repo = "{owner}/{repo}"
        comments = _gh_api_list(self.gh, f"repos/{owner_repo}/issues/{pr_number}/comments")
        marker_body: str | None = None
        for item in comments:
            body = item.get("body")
            if isinstance(body, str) and body.lstrip().startswith(
                attachment_hook_entry.ADVISORY_COMMENT_MARKER
            ):
                marker_body = body
        if marker_body is None:
            return None
        parsed = attachment_hook_entry.parse_advisories_comment(marker_body)
        # ``parse_advisories_comment`` returns ``None`` only for a body that
        # does not start with the marker -- which the loop above already
        # guaranteed -- so this is always a tuple here. Guard anyway so a
        # future change to the parser's contract cannot make this method
        # silently return ``None`` for a present-but-malformed marker comment
        # (which would wrongly trigger the local-log fallback).
        return parsed if parsed is not None else ()

    def _build_attachment_budget_section(self, diff: str, pr_number: int) -> str:
        """Build ``$attachment_budget_section`` for the review packet (#1460).

        Cheap gate first: if `.attachment-budgets.json` is absent, or this
        diff touches neither the baseline file itself nor any file that
        currently hosts a baselined attachment point, the section renders
        ``""`` -- the vast majority of PRs never approach this feature at
        all, so nothing past the gate (diff-hunk reconstruction, advisories
        read) runs for them.

        Once gated in: the base-commit baseline text is read best-effort
        (a ``TamperError``/``OSError`` degrades to "no entries", same as a
        missing file -- this section is advisory-only and must never raise);
        the PR-head text is reconstructed from the diff (or read straight off
        disk when the baseline file itself isn't part of this diff); a
        reconstruction failure sets ``head_unreadable`` rather than guessing.

        Advisories are read best-effort, with "log file doesn't exist"
        (``advisory_log_exists`` False) distinguished from "log exists but
        has nothing relevant" -- only the former sets
        ``advisories_unavailable``.

        Issue #1466: the advisories source is now a two-tier fallback. The
        PR-comment channel is tried FIRST -- the worker publishes a single
        machine-readable PR comment (marker ``ADVISORY_COMMENT_MARKER`` +
        fenced JSON array of its ``AdvisoryRecord`` entries) at PR-open time
        and on subsequent pushes, because the worker's worktree-local
        ``.var/attachment-contracts/advisories.jsonl`` is generally invisible
        to the orchestrator's ``repo_root``. When a marker comment is present
        (``parse_advisories_comment`` returns a tuple, even ``()``), that
        channel wins and the local log is not consulted. Only when NO marker
        comment exists does the builder fall back to the local advisories
        file; and only when NEITHER channel is available does
        ``advisories_unavailable`` fire the "log not available" NOTE.
        """
        marker_path = self.repo_root / attachment_baseline.BASELINE_FILENAME
        if not marker_path.is_file():
            return ""

        changed_files = _diff_content_signature(diff).changed_files
        baseline_touched = attachment_baseline.BASELINE_FILENAME in changed_files

        try:
            base_document = attachment_baseline.load(marker_path)
            base_entries = attachment_baseline.entries_of(base_document)
        except (attachment_baseline.TamperError, OSError):
            base_entries = ()
        hosts_baselined = changed_files & {entry.file for entry in base_entries}

        if not (baseline_touched or hosts_baselined):
            return ""

        try:
            base_baseline_text: str | None = marker_path.read_text(encoding="utf-8")
        except OSError:
            base_baseline_text = None

        if baseline_touched:
            file_diff_lines: list[str] = []
            is_new_baseline_file = False
            for name, is_new, hunks in iter_diff_files(diff):
                if name == attachment_baseline.BASELINE_FILENAME:
                    file_diff_lines = hunks
                    is_new_baseline_file = is_new
                    break
            head_baseline_text = reconstruct_baseline_head_text(
                None if is_new_baseline_file else base_baseline_text,
                "\n".join(file_diff_lines),
            )
        else:
            # Baseline file itself untouched by this diff: its head content
            # is its base content.
            head_baseline_text = base_baseline_text

        if baseline_touched and head_baseline_text is None:
            section = BudgetSection(
                bumps=(),
                blocking_bumps=(),
                saturated_touched=(),
                redirects_not_taken=(),
                head_unreadable=True,
                advisories_unavailable=False,
            )
        else:
            advisories: tuple[AdvisoryRecord, ...] | None
            # Issue #1466: prefer the worker-published PR-comment channel.
            # ``_read_advisories_from_pr_comment`` returns ``None`` when no
            # marker comment is present (fall back to the local log) and a
            # tuple (possibly ``()``) when one is (that channel wins, even
            # if empty -- a present marker with no records is a clean pass,
            # not an unavailable channel).
            pr_comment_advisories = self._read_advisories_from_pr_comment(pr_number)
            if pr_comment_advisories is not None:
                advisories = pr_comment_advisories
            elif attachment_hook_entry.advisory_log_exists(self.repo_root):
                advisories = attachment_hook_entry.read_advisories(self.repo_root)
            else:
                advisories = None
            section = build_budget_findings(
                base_baseline_text=base_baseline_text,
                head_baseline_text=head_baseline_text,
                changed_files=changed_files,
                baseline_touched=baseline_touched,
                advisories=advisories,
            )

        return render_attachment_budget_section(section)

    def _build_prior_review_section(
        self,
        pr_dir: Path,
        prior_decision: dict[str, Any],
        new_head_sha: str | None,
    ) -> str:
        """Render ``$prior_review_section`` for a round-2+ review packet.

        Called when the prior decision is a terminal, non-pending verdict
        with a recorded ``reviewed_head_sha``. Issue #1270 (W13): surfaces
        EVERY archived round, not only the single most recent one -- a
        finding raised in round 1, dropped in round 2, and reintroduced in
        round 3 must be visible as such, not silently collapsed into "the
        latest decision". Round content is read exclusively from the
        ``rounds/round-K`` archive W11 built (``_round_history_entries`` in
        ``rework_prompts.py``) -- never events.db, never
        ``request_changes_count`` -- per the binding decision on #1270.
        ``prior_decision`` (the flat, latest-verdict mirror the caller
        already read) is consulted only as a fallback when the archive is
        empty -- see ``_round_history_entries``'s docstring.

        Two cases, the same distinction the pre-W13 single-round renderer
        drew, now keyed off the MOST RECENT archived round instead of the
        one ``prior_decision`` argument (which, once at least one round is
        archived, is always exactly that round's own payload -- writer and
        flat mirror are the same ``record_review`` call):

        - **Moved head** (latest round's head != live head): a genuine
          rework round. Every prior round's findings are listed, oldest
          first, followed by an interdiff (latest reviewed head -> new
          head) so the reviewer has somewhere to start, without losing
          sight of the full diff: the interdiff is "start here," never
          "only look here" -- the full diff stays attached and remains
          authoritative for findings outside it.
        - **Same head** (latest round's head == live head, issue #632
          defect 3): a PR parked on ``agent:human-needed`` whose head has
          not advanced, or an operator-corrected verdict. The diff is
          identical, so no interdiff is generated; every round's findings
          are still surfaced so a re-review can verify whether they still
          apply or whether the verdict was corrected. Without this branch
          the corrected verdict was invisible to the reviewer (the #510
          case).

        Fail-safe posture mirrors janitor.py's patch-id carry-forward
        (``_calculate_patch_id``/``_check_no_op_rework``): every I/O call
        here (``compare_diff``) already returns errors as values (``None``),
        never raises, so a failed/unavailable comparison (404, GC'd SHA,
        rebase/divergence, gh failure) just omits the interdiff and says so
        -- it never blocks packet generation.
        """
        rounds_dir = pr_dir / "rounds"
        entries = _round_history_entries(rounds_dir, fallback_decision=prior_decision)
        if not entries:
            return ""

        latest_decision = entries[-1][1]
        prior_head_sha = latest_decision.get("reviewed_head_sha")
        same_head = bool(prior_head_sha) and prior_head_sha == new_head_sha
        round_word = "round" if len(entries) == 1 else "rounds"

        lines = ["", f"## Prior review{' (same head)' if same_head else ''}", ""]
        if same_head:
            lines.append(
                f"A prior review of this head (`{prior_head_sha}`) recorded decision "
                f"**{latest_decision.get('decision') or 'unknown'}**. The diff has not "
                "changed since that review. Findings from every prior "
                f"{round_word} are listed below, oldest first -- verify whether "
                "each still applies or whether the verdict was corrected (e.g. "
                "by an operator hand-edit)."
            )
        else:
            lines.append(
                f"This PR has {len(entries)} prior review {round_word}. Findings "
                "from EVERY round are listed below, oldest first -- a finding "
                "raised in an earlier round is still in scope even if a later "
                "round's summary did not repeat it."
            )
        lines.append("")

        for round_number, round_decision in entries:
            decision_label = round_decision.get("decision") or "unknown"
            round_head = round_decision.get("reviewed_head_sha") or "unknown"
            lines.append(
                f"### Round {round_number} (decision: {decision_label}, head `{round_head}`)"
            )
            lines.append("")
            findings = _render_round_findings(round_decision)
            lines.append(findings if findings else "_No findings recorded for this round._")
            lines.append("")

        # #1270 (W13): `_render_round_findings` strips
        # `_EXTERNAL_FINDINGS_POINTER` from each round's rendering -- its
        # wording is worker-brief-framed ("...none of which reach this
        # brief") and, unlike the brief (rendered once per PR), a
        # round-history section would otherwise repeat it once per round.
        # One reviewer-framed reminder for the whole section replaces it.
        lines.append(
            "The findings above come from the orchestrator's own reviewer, "
            "across every round. They are not necessarily the only ones -- "
            "a human or a peer agent may have posted verified findings as "
            "PR comments, review bodies, or inline review threads. Read the "
            "PR's review comments and review threads on GitHub before you "
            "start, and address what you find there too."
        )
        lines.append("")

        if same_head:
            lines.append(
                "No interdiff is needed -- the head is unchanged. Re-examine "
                "the full diff and confirm or overturn the prior verdict."
            )
            lines.append("")
            return "\n".join(lines)

        interdiff_text = None
        if prior_head_sha and new_head_sha:
            interdiff_text = self.gh.compare_diff(str(prior_head_sha), str(new_head_sha))
        if interdiff_text and interdiff_text.strip():
            interdiff_path = pr_dir / "interdiff.patch"
            interdiff_path.write_text(interdiff_text, encoding="utf-8")
            lines.append(
                f"Interdiff (most recent reviewed head to this head): `{interdiff_path}`. "
                "Verify the findings above are addressed there first -- but the "
                "full diff remains authoritative; findings outside the interdiff "
                "are still in scope."
            )
        else:
            lines.append(
                "Prior-head comparison was unavailable (rebase, divergence, or an "
                "API error) -- no interdiff could be generated. Review the full "
                "diff as usual, with the findings above in mind."
            )
        lines.append("")
        return "\n".join(lines)

    def reconcile(
        self,
        *,
        fix: bool = False,
        skip_dead_session_sweep: bool = False,
        dry_run: bool | None = None,
    ) -> CommandResult:
        """Detect (and optionally repair) drift between GitHub reality and the
        orchestrator's labels/state — e.g. a PR merged by hand outside
        merge-ready leaving `agent:in-progress` stale forever. Read-only unless
        ``fix`` is passed.

        ``mop-up --fix`` is a state writer and must be mutually exclusive with
        a supervised ``bash-rats``/fleet pass on the same repo. It acquires the
        same ``supervisor.lock`` used by fleet/supervise. If either the
        supervisor lock or the state lock is held, the call returns a skipped
        value result rather than blocking or writing unlocked.

        This is the public entry point: acquire ``supervisor.lock`` (only
        when ``fix``, matching today's behavior), then delegate everything
        else to ``_reconcile_locked``, which requires the lock already be
        held. Do not inline the body back here — the periodic in-loop caller
        (``_maybe_reconcile_drift``) already holds ``supervisor.lock`` via
        its own caller (``loop()``) and must call ``_reconcile_locked``
        directly; re-entering this method would always fail to reacquire the
        same non-reentrant lock and silently no-op (merge-lane-recovery D-8a).
        """
        if dry_run is None:
            dry_run = getattr(self, "dry_run", False)
        supervisor_lock = None
        if fix and not dry_run:
            supervisor_lock = try_acquire_byte_range_lock(
                layout.supervisor_lock_path(self.paths.root)
            )
            if supervisor_lock is None:
                return CommandResult(
                    True,
                    "reconcile deferred: supervisor lock held",
                    {"pass_skipped": True, "reason": "supervisor_lock_held"},
                )
        try:
            return self._reconcile_locked(
                fix=fix,
                skip_dead_session_sweep=skip_dead_session_sweep,
                dry_run=dry_run,
            )
        finally:
            if supervisor_lock is not None:
                supervisor_lock.release()

    def _reconcile_locked(
        self,
        *,
        fix: bool = False,
        skip_dead_session_sweep: bool = False,
        dry_run: bool = False,
    ) -> CommandResult:
        """Run drift detection (and optional repair) against GitHub/state.

        Precondition: the caller MUST already hold ``supervisor.lock`` — this
        method never acquires it itself. ``reconcile()`` is the only method
        that acquires the lock (and only when ``fix``); it delegates here
        immediately afterward. The periodic in-loop caller
        (``_maybe_reconcile_drift``) calls this directly, bypassing
        ``reconcile()``'s lock-acquisition entirely, because ``loop()``'s own
        caller already holds ``supervisor.lock`` for the whole pass —
        acquiring it a second time on the same non-reentrant byte-range lock
        would always fail and silently no-op (merge-lane-recovery D-8a).

        Extracted verbatim from ``reconcile()``'s former body — logic here is
        unchanged from before the split, including the GraphQL rate-limit
        deferral, so ``charlie mop-up --fix`` (which still goes through
        ``reconcile()``) is byte-for-byte unchanged in behaviour.
        """
        try:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                threshold = self.config.runtime.graphql_rate_limit_threshold
                sufficient, remaining, reset_at = self.gh.check_graphql_rate_limit(threshold)
                if not sufficient:
                    if not dry_run:
                        state = append_event(
                            state,
                            "graphql_rate_limit_deferred",
                            {
                                "remaining": remaining,
                                "reset": reset_at,
                                "threshold": threshold,
                                "phase": "reconcile",
                            },
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, state)
                    return CommandResult(
                        True,
                        "reconcile deferred: GraphQL rate limit below threshold",
                        {
                            "deferred": True,
                            "deferred_reason": "graphql_rate_limit",
                            "graphql_remaining": remaining,
                            "graphql_reset": reset_at,
                            "graphql_threshold": threshold,
                        },
                    )
                new_state = state
                try:
                    drift = (
                        detect_drift(
                            self.gh,
                            state,
                            self.config,
                            repo_root=self.repo_root,
                            skip_dead_session_sweep=skip_dead_session_sweep,
                            state_path=self.paths.state_file,
                        )
                        + detect_aviator_stale_blocked(
                            self.gh, self.config, repo_root=self.repo_root
                        )
                        + detect_mergequeue_not_approved(
                            self.gh, self.config, repo_root=self.repo_root
                        )
                        + detect_mergequeue_wedged(
                            self.gh, self.config, state, repo_root=self.repo_root
                        )
                    )
                    fixed = False
                    post_fix_drift: list[DriftItem] = []
                    if fix and not dry_run and drift:
                        new_state = apply_drift_fixes(
                            self.gh,
                            state,
                            drift,
                            self.config,
                            repo_root=self.repo_root,
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, new_state)
                        # Post-#134: transition() returns TransitionResult with PARTIAL_FAILURE
                        # for failed adds/removes, and apply_fixes records the outcome in the
                        # reconcile event. Re-detect against the new state to verify the repairs
                        # actually landed before reporting success.
                        post_fix_drift = (
                            detect_drift(
                                self.gh,
                                new_state,
                                self.config,
                                repo_root=self.repo_root,
                                skip_dead_session_sweep=skip_dead_session_sweep,
                                state_path=self.paths.state_file,
                            )
                            + detect_aviator_stale_blocked(
                                self.gh, self.config, repo_root=self.repo_root
                            )
                            + detect_mergequeue_not_approved(
                                self.gh, self.config, repo_root=self.repo_root
                            )
                            + detect_mergequeue_wedged(
                                self.gh, self.config, new_state, repo_root=self.repo_root
                            )
                        )
                        fixed = len(post_fix_drift) == 0
                    elif fix and dry_run and drift:
                        post_fix_drift = drift
                except GraphQLBudgetError as exc:
                    # Defensive: detect_drift re-checks the budget and may raise.
                    if not dry_run:
                        new_state = self._record_event(
                            new_state,
                            "reconcile_pass_deferred",
                            {
                                "remaining": exc.remaining,
                                "reset": exc.reset_at,
                                "threshold": exc.threshold,
                                "fix": fix,
                                "deferred_reason": "graphql_rate_limit",
                            },
                        )
                        save_state(self.paths.state_file, new_state)
                    return CommandResult(
                        True,
                        "reconcile deferred: GraphQL rate limit below threshold",
                        {
                            "deferred": True,
                            "deferred_reason": "graphql_rate_limit",
                            "graphql_remaining": exc.remaining,
                            "graphql_reset": exc.reset_at,
                            "graphql_threshold": exc.threshold,
                            "reconcile_pass_event_recorded": not dry_run,
                        },
                    )
            message = f"found {len(drift)} drift item(s)"
            if fixed:
                message += " — fixed"
            elif drift:
                if dry_run and fix:
                    message += " (dry-run; no changes applied)"
                elif fix and post_fix_drift:
                    message += f" — partially fixed — {len(post_fix_drift)} item(s) remain"
                else:
                    message += " (read-only; pass --fix to repair)"
            # ok=False when drift is present and not fixed: scripts and CI can gate
            # on exit code to detect unresolved drift, matching how `doctor` gates.
            ok = not drift or fixed or (dry_run and fix)
            return CommandResult(
                ok,
                message,
                {
                    "drift": [asdict(item) for item in drift],
                    "fixed": fixed,
                    "drift_before": len(drift),
                    "drift_after": len(post_fix_drift),
                    "remaining_drift": [asdict(item) for item in post_fix_drift],
                },
            )
        except StateLockBusy:
            return _state_lock_busy_result("reconcile deferred: state lock held")

    @staticmethod
    def _cross_family_section(report_path: str | Path) -> str:
        return (
            "\n## Cross-family adversarial pass\n\n"
            f"An automated non-Claude adversarial review is at `{report_path}`. Read it, but "
            "treat its findings as **leads, not verdicts** — that model over-escalates severity. "
            "Verify each against live code before folding it in, reject over-escalations with a "
            "reason, and never let it gate the merge on its own.\n"
        )

    def _update_open_agent_prs(self, merged_pr_number: int) -> list[dict[str, Any]]:
        """Update remaining open agent PRs after a successful merge.

        Behavior is controlled by ``auto_merge.update_branch_strategy``:

        - "front_of_train" (default): update only the head of the approved
          queue, so a single merge step causes at most one CI reset on a
          single-runner merge train.
        - "broadcast": update every eligible open tracked PR that is not
          approved-pending-ship and has no required checks in-flight. Intended
          for multi-runner setups. PRs whose current review decision is
          ``request_changes``, escalated, or blocked are skipped.
        - "off": do nothing.

        Per-PR failures (conflicts, network errors) are reported as values and
        never abort the batch operation. A GitHubError from pr_list is also
        reported as a value and never propagates.
        """
        results: list[dict[str, Any]] = []
        mode = self.config.auto_merge.update_branch_strategy
        if mode == "off":
            return results

        if mode == "front_of_train":
            try:
                candidates = self._merge_train_candidates(exclude_pr_number=merged_pr_number)
            except GitHubError as exc:
                return [{"error": f"pr_list failed: {exc}"}]

            if not candidates:
                return results

            # Only the head of the merge-train queue is synced.
            _, pr_number, pr, decision, head = candidates[0]
            base_current = self._is_base_current(pr)
            if base_current is None:
                # Compare API unavailable: report distinctly from "up-to-date" so
                # a GitHub compare-API degradation is visible in telemetry instead
                # of masquerading as every open PR being current.
                return [
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "compare_unavailable",
                    }
                ]
            if not self._should_update_pr_branch(pr, base_current):
                return [
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "up-to-date",
                    }
                ]

            old_head = pr.get("headRefOid")
            if not self.gh.pr_update_branch(pr_number):
                return [
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "error": "pr_update_branch failed",
                    }
                ]

            new_head = self._verify_synced_head(pr_number, old_head)
            if new_head is None:
                return [
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "error": "post-sync head verification failed",
                    }
                ]
            if new_head == old_head:
                return [
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "up-to-date",
                    }
                ]

            # Issue #1072: capture the bool return so telemetry does not
            # report success for a carry-forward write that was refused
            # (e.g. _update_approval_head's identity guard rejected a
            # concurrent verdict change). The branch WAS updated, but the
            # approval verdict was not carried forward to the new head —
            # the PR will need re-review. Telemetry-only, no state impact.
            approval_carried = self._update_approval_head(
                pr_number,
                decision,
                new_head,
                old_head=old_head,
                issue_number=linked_issue_number(
                    pr,
                    is_cross_repository=pr.get("isCrossRepository"),
                    branch_prefix=self.config.dispatch.branch_prefix,
                ),
            )
            return [
                {
                    "pr_number": pr_number,
                    "head_ref": head,
                    "updated": True,
                    "new_head": new_head,
                    "approval_carry_forward": approval_carried,
                }
            ]

        # mode == "broadcast": update every eligible PR.
        try:
            prs = self.gh.pr_list()
        except GitHubError as exc:
            # Report the pr_list failure as a value instead of raising
            return [{"error": f"pr_list failed: {exc}"}]
        branch_prefix = self.config.dispatch.branch_prefix
        required_checks = self.config.auto_merge.required_checks

        for pr in prs:
            pr_number = int(pr.get("number", 0))
            if pr_number == merged_pr_number:
                continue

            # Skip fork PRs
            if pr.get("isCrossRepository"):
                continue

            # Only update PRs with the configured branch prefix
            head = str(pr.get("headRefName") or "")
            if not head.startswith(branch_prefix):
                continue

            # Derive eligibility from the recorded review decision. Never
            # update-branch a PR whose current decision is request_changes,
            # escalated, or blocked — rework or human intervention will replace
            # the head, so the CI run would be guaranteed-wasted time.
            decision = self._review_decision(pr_number)
            decision_value = decision.get("decision")
            if decision_value in {"request_changes", "blocked"} or decision.get("escalated"):
                results.append(
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "not_approved",
                    }
                )
                continue

            # Skip approved-pending-ship PRs to avoid invalidating their approvals.
            # These will get base-updated when they themselves are merged (GitHub
            # merges handle base freshness) or by a later pass after they merge.
            if decision_value == "approved":
                reviewed_head_sha = decision.get("reviewed_head_sha")
                live_head_sha = pr.get("headRefOid")
                if reviewed_head_sha is not None and live_head_sha == reviewed_head_sha:
                    # PR is approved and head hasn't moved since approval — skip update
                    results.append(
                        {
                            "pr_number": pr_number,
                            "head_ref": head,
                            "updated": False,
                            "skipped_reason": "approved-pending-ship",
                        }
                    )
                    continue

            # Skip PRs with required checks in PENDING/IN_PROGRESS to avoid cancelling in-flight CI
            # This prevents the wedge described in issue #209 where update-branch cancels
            # matrix jobs and aggregate-gate checks permanently fail against the frozen CANCELLED state.
            status_rollup = pr.get("statusCheckRollup")
            if status_rollup and required_checks:
                # statusCheckRollup is a flat array of check objects (CheckRun or StatusContext)
                # CheckRun uses 'status' field, StatusContext uses 'state' field
                has_pending_required = False
                for check in status_rollup:
                    check_name = check.get("name") or check.get("context")
                    if check_name in required_checks:
                        # Check if this required check is in a pending/in-progress state
                        # For CheckRuns: status != COMPLETED means in-flight
                        # For StatusContext: state != SUCCESS/FAILURE/ERROR means in-flight
                        status = check.get("status") or check.get("state", "")
                        # Treat any non-terminal status as in-flight (safer than enumerating)
                        # Terminal states: COMPLETED (CheckRun), SUCCESS/FAILURE/ERROR (StatusContext)
                        if status.upper() != "COMPLETED" and status.upper() not in {
                            "SUCCESS",
                            "FAILURE",
                            "ERROR",
                        }:
                            has_pending_required = True
                            break

                if has_pending_required:
                    results.append(
                        {
                            "pr_number": pr_number,
                            "head_ref": head,
                            "updated": False,
                            "skipped_reason": "pending-required-checks",
                        }
                    )
                    continue

            # Whether base freshness is required at all is derived from GitHub
            # branch protection, cached per orchestrator pass (issue #812) --
            # see _is_base_freshness_required for the fail-closed contract.
            # When not required, skip the compare-API read and the
            # pr_update_branch write entirely: this is the update_open_prs
            # half of the churn issue #812 eliminates (merge_ready's own sync
            # block is the other half).
            base_ref = pr.get("baseRefName") or self.config.runners.default_branch
            if not self._is_base_freshness_required(base_ref):
                results.append(
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "base_freshness_not_required",
                    }
                )
                continue

            # Use the same compare-derived base-current signal as the front-of-train
            # path and merge_ready so broadcast mode also skips up-to-date PRs and
            # syncs stale ones even when mergeStateStatus is CLEAN.
            base_current = self._is_base_current(pr)
            if base_current is None:
                # Compare API unavailable: report distinctly from "up-to-date" so
                # a GitHub compare-API degradation is visible in telemetry instead
                # of masquerading as every open PR being current.
                results.append(
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "compare_unavailable",
                    }
                )
                continue
            if not self._should_update_pr_branch(pr, base_current):
                results.append(
                    {
                        "pr_number": pr_number,
                        "head_ref": head,
                        "updated": False,
                        "skipped_reason": "up-to-date",
                    }
                )
                continue

            # Attempt to update the branch
            success = self.gh.pr_update_branch(pr_number)
            results.append(
                {
                    "pr_number": pr_number,
                    "head_ref": head,
                    "updated": success,
                }
            )

        return results

    def _merge_not_ready_result(
        self,
        pr_number: int,
        issue_number: int | None,
        decision: dict[str, Any],
        existing_pr_state: dict[str, Any],
    ) -> CommandResult:
        """Return a non-mergeable result for an approved PR that is not the train head."""
        return CommandResult(
            True,
            f"PR #{pr_number} is not the head of the merge-train queue",
            {
                "pr": pr_number,
                "issue": issue_number,
                "can_merge": False,
                "auto_merge_enabled": self.config.auto_merge.enabled,
                "merged": False,
                "merge_output": None,
                "branch_deleted": None,
                "review_decision": decision,
                "checks": asdict(summarize_checks([], self.config.auto_merge.required_checks)),
                "checks_unavailable": False,
                "label_error": None,
                "update_open_prs_results": None,
                "cancel_superseded_runs_results": None,
                "containment_warnings": [],
                "consecutive_failed_merge_attempts": existing_pr_state.get(
                    "consecutive_failed_merge_attempts", 0
                ),
                "merge_attempt_alarm": False,
                "merge_attempt_warning": None,
                "merge_conflict": False,
            },
        )

    def _merge_deferred_stale_base_result(
        self,
        pr_number: int,
        issue_number: int | None,
        decision: dict[str, Any],
        base_ref: str | None,
        head_sha: str | None,
        reason: str = "base_stale",
    ) -> CommandResult:
        """Return a non-mergeable result for an approved PR whose base is stale.

        Records a ``merge_deferred_stale_base`` event so operators can see that
        the merge was deferred because the PR's merge-base is not the current
        base branch tip.
        """
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            existing = state["prs"].get(str(pr_number), {})
            new_stale_base_deferrals = int(existing.get("consecutive_stale_base_deferrals", 0)) + 1
            threshold = self.config.auto_merge.failed_attempt_alarm
            stale_base_alarm = threshold > 0 and new_stale_base_deferrals == threshold
            stale_base_warning: str | None = None
            if stale_base_alarm:
                stale_base_warning = _format_stale_base_alarm_message(
                    pr_number, new_stale_base_deferrals, reason
                )
                state = append_event(
                    state,
                    "merge_deferred_stale_base_alarm",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "base_ref": base_ref,
                        "head_sha": head_sha,
                        "reason": reason,
                        "attempts": new_stale_base_deferrals,
                        "threshold": threshold,
                        "message": stale_base_warning,
                    },
                    state_path=self.paths.state_file,
                )
            state = append_event(
                state,
                "merge_deferred_stale_base",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "base_ref": base_ref,
                    "head_sha": head_sha,
                    "reason": reason,
                },
                state_path=self.paths.state_file,
            )
            state["prs"][str(pr_number)] = {
                **existing,
                "number": pr_number,
                "issue_number": issue_number,
                "consecutive_stale_base_deferrals": new_stale_base_deferrals,
            }
            save_state(self.paths.state_file, state)
        return CommandResult(
            True,
            f"PR #{pr_number} base is stale; merge deferred until base is current",
            {
                "pr": pr_number,
                "issue": issue_number,
                "can_merge": False,
                "auto_merge_enabled": self.config.auto_merge.enabled,
                "merged": False,
                "merge_output": None,
                "branch_deleted": None,
                "review_decision": decision,
                "checks": asdict(summarize_checks([], self.config.auto_merge.required_checks)),
                "checks_unavailable": False,
                "label_error": None,
                "update_open_prs_results": None,
                "cancel_superseded_runs_results": None,
                "containment_warnings": [],
                "stale_base": True,
                "consecutive_failed_merge_attempts": existing.get(
                    "consecutive_failed_merge_attempts", 0
                ),
                "consecutive_stale_base_deferrals": new_stale_base_deferrals,
                "merge_attempt_alarm": stale_base_alarm,
                "merge_attempt_warning": stale_base_warning,
                "merge_conflict": False,
            },
        )

    def _is_merge_conflict(self, pr: dict[str, Any]) -> bool:
        """Detect a genuine content conflict that gh pr update-branch cannot resolve.

        GitHub exposes this through ``mergeable`` (CONFLICTING) and through
        ``mergeStateStatus`` (DIRTY). Both are already fetched by ``pr_view``.
        """
        return (
            str(pr.get("mergeable") or "").upper() == "CONFLICTING"
            or str(pr.get("mergeStateStatus") or "").upper() == "DIRTY"
        )

    def _rework_candidate_conflict_blocked(self, pr_data: dict[str, Any], pr_number: int) -> bool:
        """Issue #1349: a patch-id-advanced head on a CONFLICTING/DIRTY PR is
        still a legitimate launch candidate — the head advance did not resolve
        the conflict the rework was requested for. Routing such a PR to
        review() just bounces off the janitor gate's conflict check back to
        rework_requested, deadlocking the issue between dispatch_rework and
        review() forever (the only exit being the #765 stall escalation to a
        human, not a dispatch).

        Returns True when the candidate must be kept as a launch candidate
        (conflict-bypass applies). Shared by the dry-run and live paths so the
        two cannot drift.

        ``pr_list``'s ``mergeable`` can be UNKNOWN (GitHub computes it
        asynchronously); ``mergeStateStatus == "DIRTY"`` is reliable from
        ``pr_list``, but a CONFLICTING reading may only appear on a fresh
        ``pr_view``. When ``pr_list``'s signal is indeterminate (not a definite
        MERGEABLE and not a definite CONFLICTING), re-check with a fresh
        ``pr_view`` before routing to review so a persistently-conflicting PR
        is not misrouted back into the deadlock. A failed ``pr_view`` returns
        ``{}`` (production) which ``_is_merge_conflict`` reads as
        not-conflicting, falling through to the review lane — the same
        fail-closed behavior review() itself uses (issue #1349).
        """
        if self._is_merge_conflict(pr_data):
            return True
        live_mergeable = str(pr_data.get("mergeable") or "").upper()
        if live_mergeable not in ("MERGEABLE", "CONFLICTING"):
            fresh_pr = self.gh.pr_view(pr_number)
            if fresh_pr and self._is_merge_conflict(fresh_pr):
                return True
        return False

    def _route_to_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        summary: str,
        event_kind: str,
        extra_payload: dict[str, Any] | None = None,
        extra_state: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Route an approved PR to rework with a custom summary and event kind.

        Writes a rework prompt, transitions the linked issue to
        ``rework_requested`` (same label set as a non-escalated request_changes),
        and appends the requested state event. The PR's ``review-decision.json``
        is intentionally left untouched so the approved verdict is re-confirmed
        after the worker push moves the head. Any durable review fields already
        present in the PR state are preserved, and callers may pass additional
        keys to record without overwriting those verdict fields.
        """
        pr_number = int(pr["number"])
        self._write_rework_prompt(pr, issue_number, summary)

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            issue_key = str(issue_number)
            issue_entry = state["issues"].get(issue_key, {})
            state["issues"][issue_key] = {
                **issue_entry,
                "number": issue_number,
                "status": "rework_requested",
                "merge_alert": "OK",
            }
            pr_entry = state["prs"].get(str(pr_number), {})
            state["prs"][str(pr_number)] = {
                **pr_entry,
                "number": pr_number,
                "issue_number": issue_number,
                "status": "rework_requested",
                "decision": pr_entry.get("decision"),
                "reviewed_head_sha": pr_entry.get("reviewed_head_sha"),
                "reviewed_patch_id": pr_entry.get("reviewed_patch_id"),
                **(extra_state or {}),
            }
            payload = {
                "pr_number": pr_number,
                "issue_number": issue_number,
                "base_ref": pr.get("baseRefName"),
                "head_sha": pr.get("headRefOid"),
                "reviewed_head_sha": decision.get("reviewed_head_sha"),
            }
            if extra_payload:
                payload.update(extra_payload)
            state = self._record_event(state, event_kind, payload)
            save_state(self.paths.state_file, state)

        result = transition(self.gh, self.config.labels, issue_number, "rework_requested")
        if result.outcome == TransitionOutcome.APPLIED:
            return None
        return {
            "edge": "rework_requested",
            "outcome": result.outcome.value,
            "add_failures": result.add_failures,
            "remove_failures": result.remove_failures,
        }

    def _request_merge_conflict_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        *,
        extra_state: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Route a PR with a genuine merge conflict to rework.

        Called from two sites: merge_ready's approved+alarm-threshold path
        (the original use -- ``decision == "approved"`` is enforced by that
        caller, not here) and review()'s janitor gate
        (``_route_janitor_gate_failure_to_rework``), which is decision-
        agnostic -- a conflicting branch needs a rebase regardless of its
        review verdict -- and passes ``extra_state`` to thread its own
        attempt counter through the same state write.
        """
        summary = (
            "The PR branch has a merge conflict with the base branch after a base update. "
            "Merge the base branch into the PR branch, resolve the conflicts, and push."
        )
        if decision.get("decision") == "approved":
            summary += " The code changes are already approved; do not re-litigate the review."
        requested_at = utc_now()
        merged_extra_state = {"conflict_rework_requested_at": requested_at}
        if extra_state:
            merged_extra_state.update(extra_state)
        return self._route_to_rework(
            pr,
            issue_number,
            decision,
            summary,
            "merge_conflict_rework_requested",
            extra_payload={"conflict_rework_requested_at": requested_at},
            extra_state=merged_extra_state,
        )

    def _request_check_failure_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        summary: CheckSummary,
        *,
        extra_state: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Route an approved PR whose required checks have genuinely failed to rework.

        Called only from merge_ready's approved+alarm-threshold path (issue
        #674), mirroring ``_request_merge_conflict_rework``. Once a PR is
        approved and its head stops moving, loop()'s already_approved fast
        path never calls review() again -- it goes straight to merge_ready --
        so a required check that starts genuinely failing after approval
        (not merely pending/missing/infra_failed/unavailable) previously had
        no path back to rework at all. Debounced to the same
        failed-attempt-alarm threshold as merge-conflict rework so a
        transient failure or the mergequeue's own speculative-merge retry
        gets a chance to self-heal first.
        """
        failed_str = ", ".join(summary.failed)
        text = (
            f"CI failed on required check(s) after approval: {failed_str}. The code "
            "changes are already approved; do not re-litigate the review -- push a fix "
            "for the failing check(s)."
        )
        requested_at = utc_now()
        merged_extra_state = {"check_failure_rework_requested_at": requested_at}
        if extra_state:
            merged_extra_state.update(extra_state)
        return self._route_to_rework(
            pr,
            issue_number,
            decision,
            text,
            "check_failure_rework_requested",
            extra_payload={
                "check_failure_rework_requested_at": requested_at,
                "failed_checks": list(summary.failed),
            },
            extra_state=merged_extra_state,
        )

    def _request_no_op_rework_repair(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        *,
        extra_state: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Route a PR whose last rework cycle pushed no actual change to rework.

        The janitor's no-op-rework check (``janitor._check_no_op_rework``)
        only detects the condition (unchanged patch-id/head since the last
        request_changes verdict); nothing previously consumed it
        (pr-lifecycle.md Finding 1's "no-op-rework-never-escalated"
        sub-case). This is that consumer, called from
        ``_route_janitor_gate_failure_to_rework`` and shaped like
        ``_request_merge_conflict_rework``.
        """
        summary = (
            "The previous rework cycle produced no actual content change (the diff or head "
            "matches the last request_changes verdict). Check the branch worktree for "
            "unpushed commits and push the real fix, or explain in the PR body why no "
            "further change was needed."
        )
        return self._route_to_rework(
            pr,
            issue_number,
            decision,
            summary,
            # event-consumer: audit-only -- records a rework repair request already
            # routed to a worker via _route_to_rework (the dispatch IS the action)
            "no_op_rework_repair_requested",
            extra_state=extra_state,
        )

    def _attempt_stale_checks_retrigger(
        self,
        pr: dict[str, Any],
        *,
        pr_number: int,
        issue_number: int,
        head_sha: str,
        existing_pr_state: dict[str, Any],
    ) -> CommandResult | None:
        """Follow-up retrigger policy for ``_detect_ci_run_never_created``
        (issue #1274, W17).

        Called from ``review()``'s main (non-escalated) janitor-gate path
        only, once the caller has already established the current head is
        marked (persisted or freshly detected) as never having had an
        Actions run created for it, and that ``verdict.missing_required_checks``
        is still non-empty this pass. This method owns only the *policy*
        layer on top of that: the attempt cap, the post-retrigger grace
        wait, and the mechanical retrigger itself. It never re-derives the
        "never created" signal on its own -- that stays the sole
        responsibility of ``_detect_ci_run_never_created`` (binding comment
        item 2 on issue #1274: two independently-tuned grace periods gating
        the same underlying condition is the invalid-state smell this
        codebase's design explicitly avoids).

        Mechanism, in order (binding comment item 5): close then reopen the
        PR; an empty-commit push to its branch is a fallback used only when
        close/reopen does not mechanically succeed. Both paths increment the
        SAME ``stale_checks_retrigger_attempts`` counter -- one shared
        budget, not two. A transient ``gh`` API error consumes no attempt
        (mirrors the flake-rerun block's "record the error but do not
        consume the attempt" convention a few hundred lines up in
        ``review()``) -- it simply returns None so the caller falls through
        to the existing passive ``janitor_blocked`` bookkeeping, unchanged.

        NOTE (unverified -- see ``GitHub.pr_reopen``'s docstring, flagged
        per issue #1274's binding comment item 6): whether reopening a PR
        actually causes GitHub Actions to create a fresh check-suite run for
        the PR's CURRENT head has not been confirmed against a live
        repository; it cannot be verified with a real ``gh`` call inside a
        sandboxed/mocked test environment. The empty-commit fallback exists
        specifically because of that uncertainty.

        Makes GitHub calls (via ``self.gh``) only when eligibility (cap,
        grace wait) has already been decided with no lock held -- mirrors
        every other rerun/retrigger block in this method (flake-aware
        rerun, infra rerun): external I/O never happens while
        ``state_lock`` is held.

        Returns a ``CommandResult`` in two cases: a retrigger attempt was
        actually made (mechanically succeeded, bookkeeping persisted), or
        the attempt cap was already exhausted on entry and this call escalates
        to the W9 operator queue (issue #1274 item 7) instead. Returns None
        in every other case (still inside the post-retrigger grace wait, or a
        mechanical failure that consumed no attempt) so the caller falls
        through unchanged to the pre-existing janitor-gate bookkeeping below.

        Exhaustion -> escalation routing (issue #1274 item 7): once
        ``stale_checks_retrigger_attempts >= stale_checks_max_retriggers``
        AND the caller has already established the check suite is still
        missing this pass (a precondition of even being called -- see
        ``review()``'s ``stale_checks_retrigger_in_scope`` gate), escalate
        via ``_escalate_issue`` (``reason="stale_checks_retrigger_exhausted"``,
        ``reason_class="mechanical"``) followed by
        ``transition(..., "escalated")`` -- the same mechanism every other
        cap-exhaustion escalation in this file relies on to actually land
        ``agent:human-needed`` (mirrors the infra-rerun exhaustion block,
        a few hundred lines up in ``review()``: mechanical cap exceeded, no
        code-fix rework path, straight to a human instead of looping
        forever). Re-firing on a later pass is guarded explicitly below,
        although it is also structurally prevented: once escalated,
        ``review()``'s top-of-function escalated-visibility early return
        (``status == "escalated"``) makes this whole method unreachable on
        every subsequent pass, the same way it already does for the
        retrigger action itself (scope fence item 3/b on issue #1274).

        Issue #1451: the mergeable state of the PR is checked BEFORE any
        remedy is chosen -- single point of enforcement for the
        discrimination. On a CONFLICTING PR, close/reopen (and the
        empty-commit fallback) can never create a CI run: GitHub cannot
        build ``refs/pull/N/merge`` while the branch conflicts, so no
        ``pull_request`` workflow run is created for ANY event (opened,
        reopened, synchronize) until the conflict is resolved. Retriggering
        there burns a ``stale_checks_retrigger_attempts`` slot and a
        close/reopen notification cycle with zero possible effect. Route to
        the existing merge-conflict rework path instead -- the same
        ``_route_janitor_gate_failure_to_rework`` wrapper the janitor gate
        itself uses for ``is_merge_conflict_block`` -- recording a
        ``ci_retrigger_skipped_conflicting`` event (deduped per head) for
        diagnosability. ``UNKNOWN`` (GitHub still computing mergeable)
        defers to the next pass rather than retriggering blind -- a
        close/reopen on a PR whose mergeable state is not yet settled could
        either waste the attempt (if it resolves to CONFLICTING) or fire
        prematurely (if it resolves to MERGEABLE but GitHub has not yet
        created the run). ``MERGEABLE`` and any other value proceed with the
        current behavior below.
        """
        mergeable = str(pr.get("mergeable") or "").upper()
        if mergeable == "CONFLICTING":
            # Dedup per head: a CONFLICTING PR can sit for many passes while
            # the rework worker resolves the conflict; emit the skip event
            # only when the head changes (mirrors the ci_run_never_created
            # per-head dedup pattern) so events.db stays diagnosable without
            # a per-pass spam loop.
            last_skipped_head = existing_pr_state.get("ci_retrigger_skipped_conflicting_head")
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state["prs"][str(pr_number)] = {
                    **state["prs"].get(str(pr_number), {}),
                    "ci_retrigger_skipped_conflicting_head": head_sha,
                }
                if last_skipped_head != head_sha:
                    state = self._record_event(
                        state,
                        "ci_retrigger_skipped_conflicting",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            "head_sha": head_sha,
                        },
                    )
                save_state(self.paths.state_file, state)
            return self._route_janitor_gate_failure_to_rework(
                pr,
                issue_number,
                attempts_key="conflict_rework_attempts",
                max_attempts=self.config.review.max_conflict_rework_attempts,
                reason="merge_conflict",
                router=self._request_merge_conflict_rework,
            )
        if mergeable == "UNKNOWN":
            # GitHub is still computing mergeable -- defer to the next pass
            # rather than retriggering blind (issue #1451).
            return None

        raw_attempts = existing_pr_state.get("stale_checks_retrigger_attempts", 0)
        attempts = raw_attempts if isinstance(raw_attempts, int) else 0
        max_retriggers = self.config.review.stale_checks_max_retriggers
        if attempts >= max_retriggers:
            return self._escalate_stale_checks_exhaustion(
                pr_number=pr_number,
                issue_number=issue_number,
                head_sha=head_sha,
                attempts=attempts,
                max_retriggers=max_retriggers,
                existing_pr_state=existing_pr_state,
            )

        last_retrigger_at = existing_pr_state.get("stale_checks_last_retrigger_at")
        if last_retrigger_at:
            last_dt = _parse_iso_timestamp(str(last_retrigger_at))
            if last_dt is not None:
                grace_minutes = self.config.review.stale_checks_grace_minutes
                elapsed_minutes = (datetime.now(UTC) - last_dt).total_seconds() / 60.0
                if elapsed_minutes < grace_minutes:
                    # Still inside the post-retrigger grace wait: skip this
                    # pass silently -- no event, no bookkeeping change
                    # (binding comment item 5 on issue #1274).
                    return None

        close_result = self.gh.pr_close(pr_number)
        if close_result.ok:
            reopen_result = self.gh.pr_reopen(pr_number)
            mechanically_succeeded = reopen_result.ok
        else:
            mechanically_succeeded = False
        method = "close_reopen"
        if not mechanically_succeeded:
            method = "empty_commit"
            branch = str(pr.get("headRefName") or "")
            empty_commit_result = self.gh.push_empty_commit(branch) if branch else None
            mechanically_succeeded = empty_commit_result is not None and empty_commit_result.ok

        if not mechanically_succeeded:
            # Record it, but do not consume the attempt (same convention as
            # the flake-rerun / infra-rerun API-error branches above): a
            # transient gh error must not burn the bounded retrigger budget.
            return None

        new_attempts = attempts + 1
        now_iso = datetime.now(UTC).isoformat().replace("+00:00", "Z")
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            state["prs"][str(pr_number)] = {
                **state["prs"].get(str(pr_number), {}),
                "number": pr_number,
                "issue_number": issue_number,
                "stale_checks_retrigger_attempts": new_attempts,
                "stale_checks_last_retrigger_at": now_iso,
            }
            state = self._record_event(
                state,
                "ci_retriggered_stale_checks",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "head_sha": head_sha,
                    "method": method,
                    "attempt": new_attempts,
                },
            )
            save_state(self.paths.state_file, state)
        return CommandResult(
            False,
            f"CI retrigger attempted for PR #{pr_number} "
            f"(attempt {new_attempts}/{max_retriggers}, method={method})",
            {
                "pr": pr_number,
                "issue": issue_number,
                "stale_checks_retriggered": True,
                "stale_checks_retrigger_method": method,
                "stale_checks_retrigger_attempts": new_attempts,
            },
        )

    def _escalate_stale_checks_exhaustion(
        self,
        *,
        pr_number: int,
        issue_number: int,
        head_sha: str,
        attempts: int,
        max_retriggers: int,
        existing_pr_state: dict[str, Any],
    ) -> CommandResult | None:
        """Exhaustion -> escalation routing for the stale-checks retrigger
        lane (issue #1274 item 7, the W9 operator queue).

        Called only from ``_attempt_stale_checks_retrigger`` once
        ``attempts >= max_retriggers`` on entry, with the check suite
        confirmed still missing this pass by the caller's own
        ``stale_checks_retrigger_in_scope`` precondition. Escalates via
        ``_escalate_issue`` + ``transition(..., "escalated")`` -- the same
        pair every other ``reason_class="mechanical"`` cap-exhaustion
        escalation in this file (``dead_dispatched_worker_reap``,
        ``orphan_sweep_redispatch_cap_exceeded``, ``redispatch_cap_exceeded``,
        ``infra_rerun_cap_exceeded``) uses to actually land
        ``agent:human-needed`` -- never a second queue or a hardcoded label.

        Dedup guard: skips re-escalating once this PR/issue already carries
        ``escalation_reason == "stale_checks_retrigger_exhausted"``. This
        mirrors ``_route_janitor_gate_failure_to_rework``'s
        ``current_escalation_reasons`` dedup convention, but is
        belt-and-suspenders here rather than load-bearing: once escalated,
        ``status`` becomes ``"escalated"``, and ``review()``'s top-of-function
        escalated-visibility early return (``_escalation_flags``, matched on
        status alone) makes this entire method structurally unreachable on
        every later pass -- the same structural guarantee that already
        excludes the retrigger action itself from that branch (scope fence
        item 3/b). The explicit check here only matters if something resets
        ``status`` while ``escalation_reason`` survives; it is kept for
        readability parity with the rest of this file and because it is
        directly testable independent of that structural argument.

        Issue #1461: the check uses ``escalation_reasons_seen`` (the
        append-only list maintained by ``_escalate_issue``) instead of the
        single ``escalation_reason`` field, so a cross-lane clobber that
        overwrites the single field does not blind this guard.

        Returns None (never re-escalates, never emits a duplicate event) when
        the dedup guard trips; otherwise always returns a ``CommandResult``
        (``ok=False``) describing the escalation, mirroring the infra-rerun
        exhaustion block's return shape.
        """
        exhaustion_reason = "stale_checks_retrigger_exhausted"
        if exhaustion_reason in frozenset(existing_pr_state.get("escalation_reasons_seen") or []):
            return None

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            state = _escalate_issue(
                state,
                issue_number,
                reason=exhaustion_reason,
                reason_class="mechanical",
                pr_number=pr_number,
                pr_extra={"stale_checks_retrigger_attempts": attempts},
            )
            state = self._record_event(
                state,
                "stale_checks_retrigger_exhausted",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "head_sha": head_sha,
                    "attempts": attempts,
                    "max_retriggers": max_retriggers,
                },
            )
            save_state(self.paths.state_file, state)

        edge = _escalation_edge("escalated", "mechanical")
        result = transition(self.gh, self.config.labels, issue_number, edge)
        label_error = None
        if result.outcome != TransitionOutcome.APPLIED:
            label_error = {
                "edge": edge,
                "outcome": result.outcome.value,
                "add_failures": result.add_failures,
                "remove_failures": result.remove_failures,
            }
        return CommandResult(
            False,
            f"PR #{pr_number} exhausted stale-checks retrigger cap "
            f"({attempts}/{max_retriggers}); escalated to human",
            {
                "pr": pr_number,
                "issue": issue_number,
                "stale_checks_retrigger_exhausted": True,
                "label_error": label_error,
            },
        )

    def _detect_ci_run_never_created(
        self,
        pr: dict[str, Any],
        verdict: JanitorVerdict,
        *,
        known_head: str | None = None,
    ) -> str | None:
        """Return the head SHA when Actions never created a run for it, else None.

        A "Required check(s) missing" janitor failure is ambiguous between
        "still pending" and "GitHub never created a workflow run for this
        head at all" -- job-cannon measured 11 PRs stuck behind this exact
        failure for 4+ days: the webhook delivered (other check-suite apps
        registered) but no github-actions run object ever appeared, and
        nothing distinguished that from ordinary CI latency. This queries
        Actions directly, once the head has had a grace period to actually
        start CI, so the distinction is diagnosable via events.db instead of
        blending into the janitor gate's generic bookkeeping. Detection
        only -- no retry or retrigger here; that is follow-up policy.

        Shared by both the escalated-PR path (``review()``'s early-return
        branch, which recomputes janitor diagnostics for visibility only)
        and the normal janitor-gate path below it -- a PR stuck 4+ days is
        itself a strong escalation candidate, so the check must not be
        reachable only from the non-escalated branch.

        Does NOT take ``state_lock`` and must never be called while holding
        it -- it makes a ``gh api`` call, and this repo's state lock must
        never span external I/O (mopup-rate-limit-lock-contention). Callers
        take the lock only to persist the already-computed result.

        ``known_head`` is the previously-persisted ``ci_run_never_created_head``
        marker, if any. When it matches the PR's current head, the event has
        already fired for this exact head and would be deduped anyway, so the
        ``gh api`` call is skipped -- otherwise a PR that stays escalated for
        days would re-query Actions on every single pass forever (this is the
        same population the grace period targets).
        """
        if not verdict.missing_required_checks:
            return None
        grace_minutes = self.config.auto_merge.ci_run_never_created_grace_minutes
        if grace_minutes <= 0:
            return None
        raw_head_sha = str(pr.get("headRefOid") or "") or None
        if raw_head_sha is None:
            return None
        try:
            head_sha = require_valid_sha(
                raw_head_sha, context="_detect_ci_run_never_created head_sha"
            )
        except ValueError:
            return None
        if known_head is not None and known_head == head_sha:
            return None
        if not _is_pr_updated_at_older_than(pr, datetime.now(UTC), grace_minutes):
            return None
        head_runs = self.gh.workflow_runs_for_head(head_sha)
        # None means the query itself failed (rate limit, transient error) --
        # fail closed: only a successful, empty response is positive evidence
        # of "never created", never the absence of a successful response.
        if head_runs is not None and len(head_runs) == 0:
            return head_sha
        return None

    def _route_janitor_gate_failure_to_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        *,
        attempts_key: str,
        max_attempts: int,
        reason: str,
        router: Callable[..., dict[str, Any] | None],
    ) -> CommandResult | None:
        """Shared cap/escalation wrapper for janitor-gate rework routing.

        ``router`` is ``_request_merge_conflict_rework`` or
        ``_request_no_op_rework_repair`` -- both ultimately call
        ``_route_to_rework`` and return ``None`` on a clean label transition
        or a ``label_error`` dict on partial failure.

        Returns ``None`` (caller falls through to the passive janitor_blocked
        wait) when a rework for the issue is already pending
        (``rework_requested``, ``dispatched``, or the two-phase-claim crash
        window ``dispatch_pending``): the janitor re-detects the same
        conflict/no-op every pass, and review() is re-invoked every pass, so
        routing -- and burning an attempt -- on each detection would escalate
        a PR whose rework worker simply hasn't run yet within two loop
        passes. Attempts must count completed-but-still-failing rework
        CYCLES, not loop passes and not individual pushes. For
        ``merge_conflict`` the cycle signal is a SETTLED head change: the
        issue must be back in ``rework_requested`` (a live ``dispatched``
        session may push any number of intermediate WIP commits -- burning
        per push would escalate a PR whose worker is actively fixing it) and
        the head must differ from the recorded
        ``<attempts_key>_last_head`` baseline. A truthy baseline is
        required: with no baseline on record (the rework predates this
        bookkeeping, or the head was transiently unavailable at routing
        time) the head is recorded as the new baseline instead of guessing
        that a cycle completed. A qualifying settled change burns one
        attempt (bounding the push-conflicted-heads-forever loop) but does
        not re-route -- the issue is already queued and the worktree layer
        injects the conflict notice at (re)launch. For ``no_op_rework``,
        head unchanged is the detection signal itself, so pending cycles
        are instead bounded by dispatch_rework's dead-session redispatch
        cap.

        Once ``max_attempts`` is exceeded, escalate using the same
        ``transition()`` helper the other escalation call sites use so
        ``agent:human-needed`` actually lands. The review-dispatch attempt-cap
        escalation used to skip this step, writing ``escalated`` to state
        without applying the label edge and leaving the issue without
        ``agent:human-needed`` on GitHub. This call site must not repeat that
        failure mode.
        """
        pr_number = int(pr["number"])
        head_sha = str(pr.get("headRefOid") or "")
        last_head_key = f"{attempts_key}_last_head"
        stall_since_key = f"{attempts_key}_stall_since"
        stall_head_key = f"{attempts_key}_stall_head"
        # The attempt count is read here but persisted under a later, separate
        # lock (this write for the burn path, _route_to_rework's for the
        # routing path) -- a deliberate deviation from the single-lock RMW
        # pattern used elsewhere: two overlapping passes on the same PR can
        # at worst under-count by one, which only DELAYS escalation by one
        # cycle and self-corrects on the next pass. Making the routing path
        # atomic would mean threading a counter callback through
        # _route_to_rework's shared state write; not worth it for that
        # failure direction.
        snapshot = load_state_locked(self.paths.state_file)
        existing_pr_state = snapshot.get("prs", {}).get(str(pr_number), {})
        issue_state = snapshot.get("issues", {}).get(str(issue_number), {})
        issue_status = issue_state.get("status")
        # Issue #776: this wrapper is called on every pass for as long as the
        # underlying janitor failure persists (review()'s escalated-issue
        # early return re-attempts it every pass; merge_ready()'s conflict
        # trigger no longer pre-excludes "escalated" either, by design, so
        # unrelated remediation can proceed). Once THIS lane's own cap has
        # already escalated the pair, re-running the block below on an
        # unchanged verdict would re-burn attempts_key past the cap, re-fire
        # janitor_rework_escalated, and re-call transition() every single
        # pass forever. Match on the lane-specific escalation_reason (not
        # just issue_status == "escalated") so an escalation from a
        # DIFFERENT lane -- a different attempts_key, or the unrelated
        # watchdog redispatch cap -- does NOT match here and remediation of
        # that unrelated Y still proceeds below. Checking both records
        # covers the PR-only-escalated edge case.
        #
        # Both this lane's cap-exceeded escalation AND its stall escalation
        # (_check_janitor_rework_stall, issue #765/#774) must be recognized
        # here. Without the stall reason, an issue escalated for a stalled
        # rework (nobody working it -- the whole point of that escalation is
        # to get a human to look) would fall through: its status is
        # "escalated", not "rework_requested"/"dispatched"/"dispatch_pending",
        # so `rework_pending` below is False and the function would proceed
        # straight to the attempts-increment/dispatch logic and silently
        # redispatch a fresh rework attempt on the very next pass --
        # defeating the stall escalation the moment it fires.
        #
        # Issue #1461: the check uses ``escalation_reasons_seen`` (an
        # append-only list maintained by ``_escalate_issue``) instead of the
        # single ``escalation_reason`` field. A different lane's escalation
        # clobbers the single field, which used to blind this guard on the
        # next pass -- the lane re-proceeded, re-incremented attempts_key
        # past the cap, and re-fired ``janitor_rework_escalated``. The list
        # is stable across cross-lane clobbers, so the guard reliably
        # recognizes this lane's own prior escalation regardless of what the
        # current single field says.
        current_escalation_reasons = frozenset(
            {f"{attempts_key}_cap_exceeded", f"{attempts_key}_stall_exceeded"}
        )
        issue_seen = frozenset(issue_state.get("escalation_reasons_seen") or [])
        pr_seen = frozenset(existing_pr_state.get("escalation_reasons_seen") or [])
        if current_escalation_reasons & (issue_seen | pr_seen):
            return None
        rework_pending = issue_status in ("rework_requested", "dispatched", "dispatch_pending")
        counted_head = existing_pr_state.get(last_head_key)
        if rework_pending:
            settled_new_conflicted_head = (
                reason == "merge_conflict"
                and issue_status == "rework_requested"
                and bool(head_sha)
                and head_sha != counted_head
            )
            if not settled_new_conflicted_head:
                # Issue #765: "no progress at all" and "progress still in
                # flight" both land here (a live dispatched session's WIP
                # pushes, and a stalled rework_requested queue item with an
                # unmoved head, are indistinguishable from settled_new_
                # conflicted_head's point of view). The cap/rescue check
                # below is unreachable from here -- it only runs once a
                # cycle SETTLES -- so a PR that never settles can wait here
                # forever. _check_janitor_rework_stall separates the two
                # cases, but NOT by issue status alone -- reconcile's
                # issue_active_label_with_open_pr self-heal periodically
                # flips issue_status away from rework_requested without the
                # head moving, so status is only used to decide whether to
                # ADVANCE the clock; only a head change (or escalation)
                # clears it.
                stall_result = self._check_janitor_rework_stall(
                    pr_number=pr_number,
                    issue_number=issue_number,
                    issue_status=issue_status,
                    head_sha=head_sha,
                    reason=reason,
                    attempts_key=attempts_key,
                    stall_since_key=stall_since_key,
                    stall_head_key=stall_head_key,
                    stall_since=existing_pr_state.get(stall_since_key),
                    stall_head=existing_pr_state.get(stall_head_key),
                )
                if stall_result is not None:
                    return stall_result
                return None
            if not counted_head:
                with state_lock(self.paths.state_file):
                    state = load_state(self.paths.state_file)
                    state["prs"][str(pr_number)] = {
                        **state["prs"].get(str(pr_number), {}),
                        "number": pr_number,
                        "issue_number": issue_number,
                        last_head_key: head_sha,
                        # Defensive: the stall clock is only ever set from
                        # the not-settled branch above, so this should
                        # already be unset -- but a head that was
                        # transiently unavailable (see settled_new_
                        # conflicted_head's bool(head_sha) guard) could have
                        # started the clock before this baseline existed.
                        stall_since_key: None,
                        stall_head_key: None,
                    }
                    save_state(self.paths.state_file, state)
                return None
        # Issue #1106: if the previous rework session died at CLI startup
        # (before the worker's first tool action), this is NOT a no-op/conflict
        # rework attempt — requeue without touching the caps.  The cap counters
        # should only count sessions that *ran* and produced no useful change.
        #
        # ``head_settled`` is True only when ``rework_pending`` is True at this
        # point — the only ``rework_pending = True`` path that reaches here is
        # ``settled_new_conflicted_head = True`` (the head moved off the
        # recorded baseline), which means the worker DID push real content
        # before dying.  A startup death with no content change never reaches
        # here via the ``rework_pending = True`` branch (it returns None at the
        # stall check above), so the flag only matters on the
        # ``rework_pending = False`` path — the first detection or a re-detection
        # after the issue status left the pending set.
        head_settled = rework_pending
        if existing_pr_state.get("last_rework_was_startup_death") and not head_settled:
            decision = self._review_decision(pr_number)
            route_extra_state: dict[str, Any] = {
                "last_rework_failure_kind": None,
                "last_rework_was_startup_death": False,
            }
            if head_sha:
                route_extra_state[last_head_key] = head_sha
            label_error = router(pr, issue_number, decision, extra_state=route_extra_state)
            return CommandResult(
                True,
                f"PR #{pr_number} requeued after startup death "
                f"({existing_pr_state.get('last_rework_failure_kind')}); "
                f"{attempts_key} not incremented",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "routed_to_rework": True,
                    "rework_reason": reason,
                    "startup_death_requeue": True,
                    "label_error": label_error,
                },
            )
        attempts = int(existing_pr_state.get(attempts_key, 0)) + 1

        if (
            max_attempts > 0
            and attempts > max_attempts
            and self.config.rescue.enabled
            and not existing_pr_state.get("rescue_attempted")
        ):
            # Rescue tier (issue #555): conflict-rework and no-op-rework caps
            # are both eligible ("cheap model wasn't good enough") causes.
            # Route to a bounded Opus rework via the SAME router this
            # function already uses for the non-cap-exceeded routing path
            # below, instead of escalating — never a second rescue for the
            # same PR (rescue_attempted is durable, cleared only by
            # `charlie unescalate`).
            #
            # Ordering note (reviewed, deliberate): the marker is committed
            # under this lock BEFORE `router(...)` runs its own separate
            # state_lock write below. A crash in that narrow window leaves
            # `rescue_attempted=True` with no rework actually dispatched —
            # the PR's one rescue slot is spent for nothing and the NEXT cap
            # exceedance escalates straight to a human instead of retrying
            # the rescue. This is intentional, not an oversight: the
            # alternative (write the marker AFTER `router()` succeeds) fails
            # the other way — a crash between a successful `router()` write
            # and the marker write leaves the PR eligible for a SECOND
            # rescue attempt on the next cap exceedance, violating the "one
            # rescue per PR" invariant the whole feature is built around
            # (issue #555: "no upward-migrating cost spiral"). Under-rescue
            # (safe, wasteful) is a strictly better failure mode than
            # over-rescue (invariant violation) here, so marker-first is
            # kept. This mirrors this same function's pre-existing,
            # explicitly-accepted two-lock deviation for `attempts_key`
            # itself (see the docstring above and the comment at the
            # `snapshot = load_state_locked(...)` read a few lines up) —
            # not a new risk introduced by the rescue tier, the same
            # "self-corrects, at worst delays by one cycle" tradeoff this
            # function already makes elsewhere. Making this fully atomic
            # would require plumbing an extra_payload-style rescue-marker
            # parameter through `_request_merge_conflict_rework`/
            # `_request_no_op_rework_repair` (both also called from
            # merge_ready's approved+alarm-threshold path with no rescue
            # concept), which is a larger blast-radius change than this
            # fix-forward warrants; revisit only if the wasted-slot case is
            # ever observed live.
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state["prs"][str(pr_number)] = {
                    **state["prs"].get(str(pr_number), {}),
                    "number": pr_number,
                    "issue_number": issue_number,
                    attempts_key: attempts,
                    **rescue_helpers.build_rescue_dataclass_kwargs(reason),
                    "rescue_dispatched_at": utc_now(),
                    # Issue #1106: clear startup-death flags.
                    "last_rework_failure_kind": None,
                    "last_rework_was_startup_death": False,
                }
                state = self._record_event(
                    state,
                    "rescue_dispatched",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "cause": reason,
                        "attempts": attempts,
                    },
                )
                save_state(self.paths.state_file, state)
            decision = self._review_decision(pr_number)
            route_extra_state: dict[str, Any] = {attempts_key: attempts}
            if head_sha:
                route_extra_state[last_head_key] = head_sha
            # Issue #1106: clear startup-death flags.
            route_extra_state["last_rework_failure_kind"] = None
            route_extra_state["last_rework_was_startup_death"] = False
            label_error = router(pr, issue_number, decision, extra_state=route_extra_state)
            return CommandResult(
                True,
                f"PR #{pr_number} janitor {reason} rework cap exceeded "
                f"({attempts}/{max_attempts}); rescue tier dispatched instead of escalating",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "janitor_ok": False,
                    "routed_to_rework": True,
                    "rescue_dispatched": True,
                    "rework_reason": reason,
                    "label_error": label_error,
                },
            )

        if max_attempts > 0 and attempts > max_attempts:
            # Issue #776: record a structured, lane-specific escalation reason
            # (distinct from the generic "redispatch_cap_exceeded" other
            # escalation sites use for the unrelated worker-liveness
            # redispatch cap) so a human -- and any future reason-scoped
            # guard -- can tell THIS lane's cap is what's exhausted, as
            # opposed to an unrelated lane having escalated the issue. This
            # was the one escalation call site in the codebase that recorded
            # no reason at all.
            escalation_reason = f"{attempts_key}_cap_exceeded"
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                worker_launched = _worker_launched_before_cap_escalation(state, issue_number)
                state = _escalate_issue(
                    state,
                    issue_number,
                    reason=escalation_reason,
                    reason_class="mechanical",
                    pr_number=pr_number,
                    pr_extra=_cap_escalation_pr_extra(attempts_key, attempts, worker_launched),
                )
                state = self._record_event(
                    state,
                    "janitor_rework_escalated",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "reason": reason,
                        "escalation_reason": escalation_reason,
                        "attempts": attempts,
                        "worker_launched": worker_launched,
                    },
                )
                save_state(self.paths.state_file, state)
            edge = _escalation_edge("escalated", "mechanical")
            result = transition(self.gh, self.config.labels, issue_number, edge)
            label_error = None
            if result.outcome != TransitionOutcome.APPLIED:
                label_error = {
                    "edge": edge,
                    "outcome": result.outcome.value,
                    "add_failures": result.add_failures,
                    "remove_failures": result.remove_failures,
                }
            return CommandResult(
                False,
                f"PR #{pr_number} janitor {reason} rework cap exceeded "
                f"({attempts}/{max_attempts}); escalated",
                {
                    "pr": pr_number,
                    "issue": issue_number,
                    "janitor_ok": False,
                    "escalated": True,
                    "label_error": label_error,
                },
            )

        if rework_pending:
            # merge_conflict with a settled head that moved off the recorded
            # baseline: a rework cycle completed without clearing the
            # conflict. Burn the attempt so cycles stay bounded, but the
            # issue is already queued for rework -- record and fall through
            # to the passive janitor_blocked wait.
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state["prs"][str(pr_number)] = {
                    **state["prs"].get(str(pr_number), {}),
                    "number": pr_number,
                    "issue_number": issue_number,
                    attempts_key: attempts,
                    last_head_key: head_sha,
                    # Issue #765: the head moved -- real progress -- so any
                    # stall clock started while it was stuck no longer
                    # applies. A later re-stall must count from zero, not
                    # from a timestamp accumulated during unrelated history.
                    stall_since_key: None,
                    stall_head_key: None,
                    # Issue #1106: clear startup-death flags — the head
                    # settled, so the previous session's death (if any) is
                    # now accounted for by this attempt.
                    "last_rework_failure_kind": None,
                    "last_rework_was_startup_death": False,
                }
                state = self._record_event(
                    state,
                    "janitor_rework_cycle_failed",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "reason": reason,
                        "attempts": attempts,
                        "head_sha": head_sha,
                    },
                )
                save_state(self.paths.state_file, state)
            return None

        decision = self._review_decision(pr_number)
        # Issue #765: no unconditional stall_since_key/stall_head_key clear
        # here. A genuinely fresh rework request has no clock running yet, so
        # omitting the keys is a no-op; a reconcile-induced re-route (the
        # head is unchanged, only issue_status flipped and flipped back) must
        # NOT lose already-accumulated stall time, since that would let
        # reconcile's unrelated label self-heal silently defeat this bound.
        route_extra_state: dict[str, Any] = {attempts_key: attempts}
        if head_sha:
            route_extra_state[last_head_key] = head_sha
        # Issue #1106: clear startup-death flags — this attempt is being
        # counted, so the previous session's death is now accounted for.
        route_extra_state["last_rework_failure_kind"] = None
        route_extra_state["last_rework_was_startup_death"] = False
        label_error = router(pr, issue_number, decision, extra_state=route_extra_state)
        return CommandResult(
            True,
            f"PR #{pr_number} routed to rework ({reason}, attempt {attempts}/{max_attempts})",
            {
                "pr": pr_number,
                "issue": issue_number,
                "routed_to_rework": True,
                "rework_reason": reason,
                "label_error": label_error,
            },
        )

    def _check_janitor_rework_stall(
        self,
        *,
        pr_number: int,
        issue_number: int,
        issue_status: str | None,
        head_sha: str,
        reason: str,
        attempts_key: str,
        stall_since_key: str,
        stall_head_key: str,
        stall_since: Any,
        stall_head: Any,
    ) -> CommandResult | None:
        """Stall bound orthogonal to the settled-head signal (issue #765).

        Called only from ``_route_janitor_gate_failure_to_rework``'s
        not-settled branch, where a rework is pending but has not produced
        that function's own progress signal. That combination is ambiguous
        on its own -- it covers both a live ``dispatched``/``dispatch_
        pending`` session still doing real work (must NOT escalate here; a
        genuinely dead session is WatchdogConfig.stall_minutes's job, not
        this function's) and a PR that is queued with nobody working it at
        all (``rework_requested``, no progress). The latter can never reach
        the cap/rescue check in the caller, because that check only runs
        once a cycle SETTLES, and a stalled PR's cycle never settles -- so
        without this, it waits here forever (issue #765: PR #696, 55
        ``rework_already_pushed`` events, attempts already at cap, rescue
        never attempted).

        HOLD vs. RESET is deliberately split on two different signals:

        - Only a HEAD CHANGE since the clock started clears it. This is
          checked regardless of ``issue_status`` -- a live ``dispatched``
          session pushing WIP commits is real progress and must reset the
          clock even though it isn't the "stalled" status itself, and (the
          motivating case, found while building this fix) reconcile's
          ``issue_active_label_with_open_pr`` self-heal flips ``issue_status``
          away from ``rework_requested`` on its own periodic cadence
          *without touching the branch* -- an earlier draft keyed the clear
          on status alone, which reconcile would have reset roughly every
          reconcile pass, making the bound practically unreachable whenever
          reconcile is enabled (the common case). Head-only clearing makes
          the clock immune to that oscillation.
        - Only ``issue_status == "rework_requested"`` ADVANCES the clock
          (starts it, or lets elapsed time accrue toward the threshold). Any
          other pending status (``dispatched``, ``dispatch_pending``, or a
          transient reconcile-driven flip with the head unchanged) HOLDS --
          returns ``None`` without escalating and without touching the
          clock, so already-accumulated stall time survives status churn
          that isn't accompanied by real progress.

        Returns ``None`` while waiting/holding, or after clearing a clock
        whose head moved. Returns a terminal ``CommandResult`` --
        ``agent:human-needed`` applied via the same ``transition()`` helper
        the cap-exceeded path uses -- once the threshold is exceeded.
        """
        progressed = (
            stall_since is not None
            and stall_head is not None
            and bool(head_sha)
            and head_sha != stall_head
        )
        if progressed:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state["prs"][str(pr_number)] = {
                    **state["prs"].get(str(pr_number), {}),
                    "number": pr_number,
                    "issue_number": issue_number,
                    stall_since_key: None,
                    stall_head_key: None,
                }
                save_state(self.paths.state_file, state)
            stall_since = None
            stall_head = None

        stalled_candidate = issue_status == "rework_requested"
        if not stalled_candidate:
            # HOLD: do not clear. Only a head change (above) clears the
            # clock; a live worker or a transient status flip with the head
            # unchanged must not lose accumulated stall time.
            return None

        started = _parse_iso_timestamp(stall_since) if stall_since is not None else None
        if started is None or stall_head is None:
            # (Re)start the clock. Covers: no clock running yet; an
            # unparseable/corrupt timestamp; and a clock inherited from
            # before this bound had a head anchor at all (stall_since set,
            # stall_head missing -- pre-redesign state, or any other write
            # path that recorded one key without the other). In that last
            # case we cannot tell whether the head moved during the
            # already-elapsed time, so we discard it and re-anchor rather
            # than trust elapsed time of unknown provenance -- the safe
            # direction on rollout is one extra window before the bound can
            # fire, never a spurious escalation from state that never
            # actually observed a stalled head.
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state["prs"][str(pr_number)] = {
                    **state["prs"].get(str(pr_number), {}),
                    "number": pr_number,
                    "issue_number": issue_number,
                    stall_since_key: utc_now(),
                    stall_head_key: head_sha or None,
                }
                save_state(self.paths.state_file, state)
            return None

        threshold_minutes = self.config.review.rework_stall_minutes
        if threshold_minutes <= 0:
            return None
        elapsed_minutes = (datetime.now(UTC) - started).total_seconds() / 60
        if elapsed_minutes < threshold_minutes:
            return None

        # Issue #776 follow-up: record a lane-scoped escalation_reason here
        # too (parallel to the cap-exceeded branch above), not just a status
        # flip. Without it, _route_janitor_gate_failure_to_rework's same-lane
        # guard has nothing to match on the next pass -- the issue's status
        # is "escalated" (so rework_pending is False, skipping straight past
        # the not-settled branch) and the wrapper would silently redispatch a
        # fresh rework attempt (or re-escalate) immediately, undoing the stall
        # escalation's entire purpose the moment it fires.
        escalation_reason = f"{attempts_key}_stall_exceeded"

        # Surface ``rework_issue_fetch_skipped`` events from this stall window
        # in the escalation payload (issue #970). The stall escalation exists
        # to answer "why was this issue never dispatched for rework?", and
        # ``rework_issue_fetch_skipped`` (issue #939) is the event that records
        # exactly that -- but until this change the escalation's payload did
        # not correlate with it, so the signal lived in events.db and was
        # absent from the one report built to explain the very condition it
        # describes. Mirrors #940's wiring of ``unauthorized_merge_check_skipped``
        # into ``tripwire_status`` as ``last_skipped_reason``.
        #
        # The window bound is ``stall_since`` -- the stall clock start -- not a
        # fixed lookback, for the same reason #940 bounds by ``armed_at``: a
        # skip recorded before the stall began says nothing about why *this*
        # stall never progressed. Reading events.db here does not compromise
        # the state-lock section below -- it is local SQLite, independent of
        # state.json, and ``query_events`` takes no state lock.
        #
        # Scope to the escalating ``issue_number``. ``rework_issue_fetch_skipped``
        # is one event per dispatch pass and bundles every issue that failed to
        # fetch in that pass into one payload's ``issue_numbers`` list
        # (``_build_rework_issue_fetch_skip_payload`` collects all
        # ``failed_issue_fetches``). An unscoped ``kind``+``since`` query would
        # attribute a *different* PR's/issue's fetch failure to this PR's stall
        # escalation. The indexed ``issue_number`` column cannot be used for the
        # filter either: ``_extract_payload_refs`` backfills it with only the
        # *first* entry of ``issue_numbers``, so an event whose list contains
        # this issue but not as the first element would be silently missed.
        # Filter in Python on the full ``issue_numbers`` list instead.
        raw_skips = query_events(
            self.paths.state_file,
            kind="rework_issue_fetch_skipped",
            since=stall_since,
        )
        stall_skips = [
            e
            for e in raw_skips
            if isinstance(e, dict)
            and isinstance(e.get("payload"), dict)
            and issue_number in (e["payload"].get("issue_numbers") or [])
        ]
        last_skip = stall_skips[-1] if stall_skips else None
        last_skip_payload = last_skip.get("payload") if isinstance(last_skip, dict) else None
        last_skip_payload_dict = last_skip_payload if isinstance(last_skip_payload, dict) else {}
        last_skip_reason = last_skip_payload_dict.get("reason") or None
        last_skip_issue_numbers = last_skip_payload_dict.get("issue_numbers")
        last_skip_reasons = last_skip_payload_dict.get("reasons")
        last_skip_at = last_skip["ts"] if isinstance(last_skip, dict) else None
        stall_skip_summary = {
            "rework_fetch_skips": len(stall_skips),
            "last_rework_fetch_skip_at": last_skip_at,
            "last_rework_fetch_skip_reason": last_skip_reason,
            "last_rework_fetch_skip_issue_numbers": last_skip_issue_numbers,
            "last_rework_fetch_skip_reasons": last_skip_reasons,
        }

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            attempts_so_far = int(state["prs"].get(str(pr_number), {}).get(attempts_key, 0))
            state = _escalate_issue(
                state,
                issue_number,
                reason=escalation_reason,
                reason_class="mechanical",
                pr_number=pr_number,
                pr_extra={
                    stall_since_key: None,
                    stall_head_key: None,
                },
            )
            state = self._record_event(
                state,
                "janitor_rework_stalled",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "reason": reason,
                    "escalation_reason": escalation_reason,
                    "attempts": attempts_so_far,
                    "stalled_minutes": round(elapsed_minutes, 1),
                    "stall_since": stall_since,
                    "head_sha": head_sha,
                    **stall_skip_summary,
                },
            )
            save_state(self.paths.state_file, state)
        edge = _escalation_edge("escalated", "mechanical")
        result = transition(self.gh, self.config.labels, issue_number, edge)
        label_error = None
        if result.outcome != TransitionOutcome.APPLIED:
            label_error = {
                "edge": edge,
                "outcome": result.outcome.value,
                "add_failures": result.add_failures,
                "remove_failures": result.remove_failures,
            }
        message = (
            f"PR #{pr_number} janitor {reason} rework stalled "
            f"({round(elapsed_minutes)}m with no progress while {issue_status}); escalated"
        )
        # Appended, not substituted, so the base escalation text stays true --
        # the whole problem is that it reads as a self-contained explanation
        # on its own while a fetch skip is the actual root cause. Conditioned
        # on ``stall_skips`` so a stall with no fetch skips is not decorated
        # with a vacuous "0 passes" clause.
        if stall_skips:
            issue_list = last_skip_issue_numbers
            issue_clause = (
                f" issue(s) {issue_list}" if isinstance(issue_list, list) and issue_list else ""
            )
            message += (
                f" (warning: {len(stall_skips)} rework pass(es) since {stall_since}"
                f" could not fetch{issue_clause}; most recent {last_skip_at}"
                f", reason: {last_skip_reason})"
            )
        return CommandResult(
            False,
            message,
            {
                "pr": pr_number,
                "issue": issue_number,
                "janitor_ok": False,
                "escalated": True,
                "escalation_reason": "stalled",
                "label_error": label_error,
                **stall_skip_summary,
            },
        )

    def _request_readiness_no_ci_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        missing_checks: tuple[str, ...],
    ) -> dict[str, Any] | None:
        """Route an approved PR whose required CI checks have not started to rework."""
        summary = (
            "The PR was approved but the required CI checks have not started after the "
            f"configured readiness timeout ({self.config.auto_merge.readiness_no_ci_minutes} minutes). "
            f"Required checks: {', '.join(missing_checks)}. Push an empty commit or amend the head "
            "to re-trigger CI. The code changes are already approved; do not re-litigate the review."
        )
        requested_at = utc_now()
        return self._route_to_rework(
            pr,
            issue_number,
            decision,
            summary,
            "readiness_no_ci_rework_requested",
            extra_payload={
                "missing_checks": missing_checks,
                "readiness_no_ci_rework_requested_at": requested_at,
            },
            extra_state={
                "readiness_no_ci_rework_requested_at": requested_at,
            },
        )

    def _request_cross_pr_revert_rework(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
        reason: str,
    ) -> dict[str, Any] | None:
        """Route an approved PR whose branch silently reverts a base commit to rework."""
        summary = (
            f"{reason}. Remove the revert commit (or the merge+revert pair) from the PR "
            "history, or add an explicit 'allow-revert: <reason>' line to the PR body if the "
            "revert is intentional. Then push the corrected branch and re-request review."
        )
        return self._route_to_rework(
            pr, issue_number, decision, summary, "cross_pr_revert_rework_requested"
        )

    def _reroute_stranded_request_changes(
        self,
        pr: dict[str, Any],
        issue_number: int,
        decision: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Re-drive an actionable, already-recorded ``request_changes`` verdict
        to ``rework_requested`` when the linked issue's status never reflects it.

        Issue #784 AC-8 (Case 2). ``record_review`` durably decides and
        persists the rework-vs-escalate outcome (``decision["escalated"]``,
        computed against ``max_rework_cycles`` and persisted to
        ``request_changes_count`` BEFORE any GitHub label mutation --
        ``record_review`` ~9355-9396) and applies the matching issue-status
        transition in that same call. If that label transition silently
        failed, or the issue status was later clobbered by an independent
        bug (e.g. issue #789's reconcile one-way "closed" gate), the issue
        is stranded: a real, actionable verdict sits on disk with nothing
        routing it to a rework worker (``dispatch_rework`` only ever selects
        issues already at ``status == "rework_requested"``).

        This never re-decides escalation -- the caller only invokes it when
        ``decision.get("escalated")`` is falsy, i.e. record_review already
        decided this verdict is within the rework-cycle budget -- it only
        re-applies that SAME target via the SAME generic entry point
        (``_route_to_rework``) that every other "discovered late, needs
        rework" lane in this file uses (cross-PR-revert, merge-conflict,
        check-failure).

        Idempotent: guarded by ``_REWORK_ALREADY_ROUTED_STATUSES`` -- the
        exact status set ``merge_ready``'s cross-PR-revert gate uses -- so a
        second pass over unchanged state (issue already ``rework_requested``,
        or otherwise mid-flight/escalated/blocked) is a no-op. This is also
        why the fix lives here rather than in ``reconcile.py``: routing to
        rework can dispatch a worker, and reconcile's repair pass must never
        synthesize ``rework_requested`` (reconcile.py's own invariant) --
        only a dispatch-context caller may complete this transition.

        Issue #1123: the restorer must never re-activate a CLOSED GitHub
        issue. Issue state is the source of truth (state-in-labels
        invariant), and reconcile's ``state_active_status_issue_closed``
        owns the terminal "closed" status for an issue GitHub reports as
        CLOSED. Without this guard the restorer flips the status back to
        ``rework_requested`` every pass, the no-op rework cap escalates it,
        and reconcile flips it back to "closed" -- a perpetual three-lane
        loop. A closed issue's open PR surfaces once as drift via
        reconcile's ``state_active_status_issue_closed`` for human
        adjudication instead of re-entering the rework state machine. If
        the issue fetch itself fails (transient GitHubError, missing from
        the snapshot), defer to the next pass rather than re-activating
        state that may belong to a closed issue -- the stranded repair is
        a best-effort lane, not a correctness-critical one.

        Idempotency (review rework): the closed-issue skip must fire once
        per stranded PR, not on every ``review_queue()`` pass. ``"closed"``
        cannot be added to ``_REWORK_ALREADY_ROUTED_STATUSES`` because the
        #789 repair path depends on the restorer re-activating an issue
        whose status was clobbered to ``"closed"`` by a reconcile bug while
        the issue is still OPEN on GitHub -- a shared early-return on
        ``"closed"`` would suppress that repair. Instead a per-issue
        ``stranded_skip_closed`` marker in ``state["issues"][n]`` records
        that the restorer has already confirmed the issue is CLOSED and
        skipped. The marker is checked only when ``status == "closed"`` so
        the #789 path (status ``"closed"`` but issue OPEN, marker absent)
        still fetches and re-activates. When the skip fires for an issue
        whose status is not yet ``"closed"`` (e.g. ``"reviewing"``), the
        restorer converges the status to ``"closed"`` and strips active
        labels -- mirroring reconcile's ``state_active_status_issue_closed``
        -- so the next pass sees ``status == "closed"`` + marker set and
        short-circuits without a ``gh.issue_view()`` call or a duplicate
        event. Reconcile preserves unknown keys in issue entries (spread
        copy), so the marker survives reconcile sweeps; if reconcile
        normalizes the status away from ``"closed"`` (issue re-opened),
        the marker check no longer applies and the restorer re-evaluates.
        """
        state = load_state_locked(self.paths.state_file)
        issue_entry = state.get("issues", {}).get(str(issue_number), {})
        issue_status = issue_entry.get("status")
        if issue_status in _REWORK_ALREADY_ROUTED_STATUSES:
            return None
        # Local idempotency guard for the closed-issue skip (see docstring):
        # once the restorer has confirmed a CLOSED issue and recorded the
        # marker, short-circuit without re-fetching or re-emitting. Gated on
        # status == "closed" so the #789 repair (status clobbered to "closed"
        # for an OPEN issue, marker absent) still proceeds.
        if issue_status == "closed" and issue_entry.get("stranded_skip_closed"):
            return None
        try:
            issue = self.gh.issue_view(issue_number)
        except Exception:
            logging.getLogger(__name__).warning(
                "stranded_request_changes restorer for issue %s deferred "
                "(GitHub issue fetch failed); will retry next pass",
                issue_number,
                exc_info=True,
            )
            return None
        if str(issue.get("state") or "OPEN").upper() == "CLOSED":
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                issues = state.setdefault("issues", {})
                issue_entry = issues.get(str(issue_number), {})
                issue_entry["stranded_skip_closed"] = True
                if issue_entry.get("status") != "closed":
                    issue_entry["status"] = "closed"
                issues[str(issue_number)] = issue_entry
                state = self._record_event(
                    state,
                    "stranded_request_changes_skipped_issue_closed",
                    {
                        "pr_number": int(pr["number"]),
                        "issue_number": issue_number,
                        "head_sha": pr.get("headRefOid"),
                    },
                )
                save_state(self.paths.state_file, state)
            # Strip active labels from the closed issue, mirroring
            # reconcile's state_active_status_issue_closed: setting
            # status to "closed" here would prevent that drift kind from
            # firing (it requires status in ACTIVE_STATE_STATUSES), so the
            # restorer must do the label cleanup itself to avoid leaving
            # active labels on a finalized issue.
            active_labels = label_names(issue) & self.config.labels.active
            for label in sorted(active_labels):
                self.gh.remove_issue_label(issue_number, label)
            return None
        return self._route_to_rework(
            pr,
            issue_number,
            decision,
            decision.get("summary") or "",
            "stranded_request_changes_rework_requested",
        )

    def _merge_train_head(self, prs: list[dict[str, Any]] | None = None) -> int | None:
        """Return the PR number of the head of the merge-train queue, or None.

        The head is the earliest approved-pending-ship PR (same-repo, matching
        the configured branch prefix) ordered by reviewed_at (falling back to
        updatedAt), then by PR number for determinism.
        """
        candidates = self._merge_train_candidates(prs=prs)
        return candidates[0][1] if candidates else None

    def _merge_train_candidates(
        self,
        prs: list[dict[str, Any]] | None = None,
        exclude_pr_number: int | None = None,
    ) -> list[tuple[str, int, dict[str, Any], dict[str, Any], str]]:
        """Return approved-pending-ship candidates sorted by approval time.

        Each tuple contains (sort_key, pr_number, pr, decision, head_ref).
        """
        if prs is None:
            prs = self.gh.pr_list()

        branch_prefix = self.config.dispatch.branch_prefix
        # Aviator MergeQueue handoff (task #10): a PR already parked in
        # Aviator's queue (state status "mergequeue") must never occupy
        # charlie's merge-train head — Aviator now owns serialization for it.
        # Without this exclusion the parked PR keeps winning "earliest
        # reviewed" on every poll until GitHub reports it merged, so under
        # front_of_train no other approved PR is ever attempted while Aviator
        # is still processing it. Reading state is only necessary when the
        # mergequeue handoff feature is actually configured.
        state_prs = (
            load_state_locked(self.paths.state_file).get("prs", {})
            if self.config.auto_merge.mergequeue_label
            else {}
        )
        candidates: list[tuple[str, int, dict[str, Any], dict[str, Any], str]] = []
        for pr in prs:
            pr_number = int(pr.get("number", 0))
            if pr_number == exclude_pr_number:
                continue
            if pr.get("isCrossRepository"):
                continue
            head = str(pr.get("headRefName") or "")
            if not head.startswith(branch_prefix):
                continue
            if (state_prs.get(str(pr_number)) or {}).get("status") == "mergequeue":
                continue
            decision = self._review_decision(pr_number)
            if decision.get("decision") != "approved":
                continue
            reviewed_head_sha = decision.get("reviewed_head_sha")
            live_head_sha = pr.get("headRefOid")
            if reviewed_head_sha is None or live_head_sha != reviewed_head_sha:
                continue
            reviewed_at = decision.get("reviewed_at") or pr.get("updatedAt") or ""
            candidates.append((str(reviewed_at), pr_number, pr, decision, head))

        candidates.sort(key=lambda item: (item[0], item[1]))
        return candidates

    def _is_stale_ci_request_changes(self, pr_number: int, decision: dict[str, Any]) -> bool:
        """True when ``decision`` is a request_changes verdict whose only
        findings cite required checks that are all green on the live head
        (issue #1111 staleness predicate, network half).

        The pure text-shape check (``required_check_citation_names``) runs
        first so ``gh pr checks`` is only fetched for the small set of
        verdicts that could possibly be stale. Checks-unavailable (``None``)
        fails closed to False — the verdict keeps its normal lifecycle.
        """
        required = self.config.auto_merge.required_checks
        if not required:
            return False
        if required_check_citation_names(decision, required) is None:
            return False
        checks = self.gh.pr_checks(pr_number)
        if checks is None:
            return False
        return is_stale_ci_verdict(decision, summarize_checks(checks, required))

    def _check_carry_forward(self, pr_number: int, decision: dict[str, Any]) -> CarryForwardCheck:
        """Determine whether ``decision``'s verdict can carry forward to the
        PR's live head, and via which tier (issues #411/#412, #414).

        Tier 1 (fast path): the live diff's stable patch-id equals the
        recorded ``reviewed_patch_id``. Issue #1187: ``git patch-id --stable``
        strips leading whitespace from ``+``/``-`` content lines, so two
        diffs that differ ONLY in indentation depth produce the identical
        patch-id — and in an indentation-sensitive language (Python) an
        indentation-only change can alter control flow (e.g. moving a
        ``return`` into or out of an ``if`` block). A tier-1 patch-id match
        alone is therefore NOT sufficient to carry forward a verdict: when
        a tier-2 line-content signature (which preserves whitespace verbatim)
        was recorded at review time, it is also validated and must match.
        If the tier-2 signatures differ — a whitespace-only change that
        patch-id collapsed — the check fails closed to stale rather than
        carrying forward an approved verdict across a semantically
        different, unreviewed head. Decisions that predate tier-2 (no
        signature stored) have no tier-2 baseline to consult and preserve
        #412's original patch-id-only carry-forward behavior. The tier-2
        binary eligibility gate does NOT apply here: patch-id already
        proved binary content identity, and tier-2 is consulted only for
        its text-line view, which is unaffected by binary payloads.

        Tier 2 (line-content, issue #414): patch-ids differ — which happens
        on every ordinary main advance, since ``git patch-id --stable``
        hashes hunk-boundary context and the merge-base moves whenever main
        does — but the ordered ``+``/``-`` line stream and changed-file set
        recorded at review time are identical to the live diff's. Reordered,
        added, removed, or altered lines, or a changed file set, are real
        content changes and do NOT carry forward. Tier 2 is INELIGIBLE
        whenever either side's diff touched a binary file: a binary payload
        emits no ``+``/``-`` lines, so the signature is blind to it — two
        diffs with genuinely different binary content at the same path
        would otherwise compare equal (review follow-up on issue #414).

        Fails closed (``tier=None``) on any missing data, diff-fetch
        failure, or binary content: a decision recorded before tier-2
        existed (no signature stored), a PR whose diff cannot be fetched,
        a binary file on either side, or a genuine content difference all
        report "cannot carry forward" — never carry forward on
        uncertainty. Tier 2 is pure string parsing of the diff text already
        fetched for tier 1 — it needs no additional git/gh calls and so has
        no failure mode of its own beyond that shared fetch.

        Eligibility for BOTH tiers is gated on ``reviewed_patch_id`` being
        recorded at all (matching #412's original behavior exactly): a
        "blocked" verdict, or any other decision that never computed one,
        has no baseline to compare against, full stop. A pure-rename or
        mode-only diff also has an empty ``reviewed_patch_id`` (no ``@@``
        hunk) despite having a valid tier-2 signature on file — that
        specific case is intentionally left conservative (stays stale)
        rather than gating on the signature fields' presence instead, which
        was tried and reverted: ``record_review`` unconditionally records a
        (possibly trivially-empty) signature for every approved/
        request_changes decision, so gating on "signature present" instead
        of "patch-id present" made an unrelated placeholder/no-op diff look
        like a valid tier-2 baseline and wrongly carried forward verdicts
        whose head had genuinely moved to unrelated content. Tracked as a
        narrow follow-up, not fixed here.
        """
        live_diff = self.gh.pr_diff(pr_number) or ""
        if not live_diff:
            return CarryForwardCheck(None, "", DiffContentSignature((), frozenset()))

        live_patch_id = _calculate_patch_id(live_diff)
        live_signature = _diff_content_signature(live_diff)

        reviewed_patch_id = decision.get("reviewed_patch_id") or ""
        if not reviewed_patch_id:
            # No baseline recorded at all (e.g. a "blocked" verdict never
            # computes a patch-id) — nothing to compare against.
            return CarryForwardCheck(None, live_patch_id, live_signature)

        if live_patch_id and live_patch_id == reviewed_patch_id:
            # Issue #1187: ``git patch-id --stable`` strips leading
            # whitespace from ``+``/``-`` content lines, so two diffs that
            # differ only in indentation depth produce the identical
            # patch-id. In an indentation-sensitive language (Python), an
            # indentation-only change can alter control flow. A patch-id
            # match alone must not carry forward a verdict: validate the
            # tier-2 line-content signature (which preserves whitespace
            # verbatim) when one was recorded. The tier-2 binary gate does
            # NOT apply here — patch-id already proved binary content
            # identity, and tier-2 is consulted only for its text-line view.
            reviewed_changed_lines = decision.get("reviewed_changed_lines")
            reviewed_changed_files = decision.get("reviewed_changed_files")
            if reviewed_changed_lines is None or reviewed_changed_files is None:
                # Decision predates tier-2 (no signature recorded) —
                # patch-id is the only available signal; preserve #412's
                # original carry-forward behavior for legacy decisions.
                return CarryForwardCheck("patch-id", live_patch_id, live_signature)
            lines_match = tuple(reviewed_changed_lines) == live_signature.changed_lines
            files_match = frozenset(reviewed_changed_files) == live_signature.changed_files
            if lines_match and files_match:
                return CarryForwardCheck("patch-id", live_patch_id, live_signature)
            # Patch-id matched but tier-2 signatures differ — a
            # whitespace-only change that patch-id collapsed (issue #1187).
            # Fail closed to stale rather than carrying forward an approved
            # verdict across a semantically different, unreviewed head.
            return CarryForwardCheck(None, live_patch_id, live_signature)

        reviewed_changed_lines = decision.get("reviewed_changed_lines")
        reviewed_changed_files = decision.get("reviewed_changed_files")
        if reviewed_changed_lines is None or reviewed_changed_files is None:
            # Decision predates tier-2 (no signature recorded) — cannot
            # establish content identity; fail closed to stale.
            return CarryForwardCheck(None, live_patch_id, live_signature)

        if decision.get("reviewed_has_binary") or live_signature.has_binary:
            # A binary payload emits no +/- content lines, so the signature
            # cannot see it — never rely on its silence for content it
            # never observed (issue #414 review follow-up).
            return CarryForwardCheck(None, live_patch_id, live_signature)

        lines_match = tuple(reviewed_changed_lines) == live_signature.changed_lines
        files_match = frozenset(reviewed_changed_files) == live_signature.changed_files
        if lines_match and files_match:
            return CarryForwardCheck("line-content", live_patch_id, live_signature)

        return CarryForwardCheck(None, live_patch_id, live_signature)

    def _update_approval_head(
        self,
        pr_number: int,
        decision: dict[str, Any],
        new_head: str,
        old_head: str | None = None,
        *,
        issue_number: int | None = None,
        tier: str = "verified-sync",
        new_patch_id: str | None = None,
        new_signature: DiffContentSignature | None = None,
    ) -> bool:
        """Persist an updated review head for a PR whose branch was synced.

        Keeps the verdict valid when the branch was base-updated or rebased
        without content changes. Updates both review-decision.json and
        state.json, appending the old head to ``carried_forward_from`` for audit.

        ``tier`` records which mechanism justified the update, for audit:
        ``"patch-id"``/``"line-content"`` from :meth:`_check_carry_forward`
        (issues #412/#414), or the default ``"verified-sync"`` for the
        structurally-verified (``_verify_synced_head``) front-of-train/
        broadcast sync callers, which never compared patch-ids at all.

        When ``new_patch_id``/``new_signature`` are supplied — they are
        already computed as part of the tier check that led here — they
        replace the stored baseline so ``reviewed_head_sha`` and the
        patch-id/content-signature fields always describe the SAME head
        consistently. Leaving a patch-id recorded against a stale head would
        pointlessly defeat that head's own future tier-1 fast path: patch-id
        is unstable across every main advance, not just the one just
        carried past.

        A carry-forward event is recorded here, inside the locked section
        that already persists the transition, so every call site is
        instrumented by construction — a new caller cannot forget it
        (issue #638). The event kind is tier-dependent so the three
        mechanisms (``verdict_carried_forward_clean_rebase`` for patch-id,
        ``verdict_carried_forward_line_content`` for line-content, and
        ``verdict_carried_forward_verified_sync`` for the structurally-
        verified sync that never compared patch-ids) stay separately
        auditable in the events log. Callers that previously recorded the
        event themselves must NOT do so anymore, or the transition would be
        double-counted.

        Issue #1038: ``decision`` is the caller's copy, read before one or
        more network round-trips (``pr_update_branch``, ``_verify_synced_head``,
        ``_check_carry_forward``'s diff fetch). This used to write the whole
        of ``review-decision.json`` from that copy, outside any lock, so a
        verdict recorded on disk during the round-trips (e.g. an operator's
        ``record_review`` landing a fresh ``request_changes``) was silently
        replaced by the stale copy and re-pinned to the new head — an
        approval could be resurrected over a contemporaneous rejection,
        authorizing a merge that should not happen.

        Now the on-disk decision is re-read inside the same ``state_lock``
        that guards the ``state.json`` half of this transition (previously
        the decision-file write sat entirely outside that lock), and the
        write is refused unless the on-disk verdict's identity — its
        ``decision`` value, plus ``reviewed_head_sha`` matching ``old_head``
        when the caller supplied one — still matches what the caller
        observed. Only the fields this function owns (``reviewed_head_sha``,
        ``carry_forward_tier``, the patch-id/signature fields,
        ``carried_forward_from``) are patched onto the on-disk copy;
        ``decision``, ``summary``, and ``required_changes`` always come from
        disk, never from the caller's stale parameter — this is a
        read-modify-write, never a whole-dict replace.

        Returns True if the carry-forward was applied, False if it was
        skipped because the on-disk verdict had already changed underneath
        it (an event is still recorded in that case so the skip is
        greppable rather than silent).
        """
        decision_path = self.paths.prs / f"pr-{pr_number}" / "review-decision.json"
        expected_decision_value = decision.get("decision")

        with state_lock(self.paths.state_file):
            current_decision = self._review_decision(pr_number)
            decision_changed = current_decision.get("decision") != expected_decision_value
            head_changed = (
                old_head is not None and current_decision.get("reviewed_head_sha") != old_head
            )
            if decision_changed or head_changed:
                state = load_state(self.paths.state_file)
                state = self._record_event(
                    state,
                    "verdict_carry_forward_skipped_stale",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "expected_decision": expected_decision_value,
                        "expected_reviewed_head_sha": old_head,
                        "on_disk_decision": current_decision.get("decision"),
                        "on_disk_reviewed_head_sha": current_decision.get("reviewed_head_sha"),
                        "attempted_new_head_sha": new_head,
                        "carry_forward_tier": tier,
                    },
                    level="warning",
                )
                save_state(self.paths.state_file, state)
                return False

            updated_decision = dict(current_decision)
            updated_decision["reviewed_head_sha"] = new_head
            updated_decision["carry_forward_tier"] = tier
            # Issue #1265: carry-forward always stamps "carried_forward",
            # unconditionally overwriting whatever provenance the verdict
            # being carried had -- this write's own mechanism IS the
            # provenance of the resulting (still-valid) verdict, regardless
            # of how the original decision was produced.
            updated_decision["verdict_provenance"] = "carried_forward"
            if new_patch_id is not None:
                updated_decision["reviewed_patch_id"] = new_patch_id
            if new_signature is not None:
                updated_decision["reviewed_changed_lines"] = list(new_signature.changed_lines)
                updated_decision["reviewed_changed_files"] = sorted(new_signature.changed_files)
                updated_decision["reviewed_has_binary"] = new_signature.has_binary
            carried_forward: list[str] = list(updated_decision.get("carried_forward_from", []))
            if old_head is not None and old_head != new_head and old_head not in carried_forward:
                carried_forward.append(old_head)
            updated_decision["carried_forward_from"] = carried_forward
            # Single writer (issue #1362 Stage 2): archive_round=False -- a
            # carry-forward is a mechanical head-rebind, not a new reviewer
            # verdict, even though it changes reviewed_head_sha (one of
            # _ROUND_COMPARE_KEYS). Routing it through the default round-mint
            # logic would archive a content-free duplicate "round" (see
            # record_decision's archive_round docstring). head_sha=None:
            # reviewed_head_sha is already set to new_head above.
            record_decision(decision_path.parent, updated_decision, None, archive_round=False)

            if tier == "patch-id":
                event_kind = "verdict_carried_forward_clean_rebase"
            elif tier == "line-content":
                event_kind = "verdict_carried_forward_line_content"
            else:
                event_kind = "verdict_carried_forward_verified_sync"

            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "decision": pr_state.get("decision")
                or updated_decision.get("decision")
                or "approved",
                "status": pr_state.get("status") or updated_decision.get("decision") or "approved",
                "reviewed_head_sha": new_head,
                "reviewed_patch_id": new_patch_id
                if new_patch_id is not None
                else (
                    pr_state.get("reviewed_patch_id")
                    or updated_decision.get("reviewed_patch_id")
                    or ""
                ),
                "carry_forward_tier": tier,
                "carried_forward_from": carried_forward,
            }
            state = self._record_event(
                state,
                event_kind,
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "old_reviewed_head_sha": old_head,
                    "new_head_sha": new_head,
                    "patch_id": new_patch_id,
                    "carry_forward_tier": tier,
                    "carried_forward_from": carried_forward,
                    "verdict_provenance": "carried_forward",
                },
            )
            save_state(self.paths.state_file, state)
        return True

    def _verify_synced_head(self, pr_number: int, old_head_sha: str | None) -> str | None:
        """Verify that the new head of a PR is a valid base-sync merge commit.

        After ``gh pr update-branch`` advances the PR head, we must not bless the
        new SHA until we confirm it is a GitHub-generated merge commit (web-flow)
        whose parents include the previously approved head. This closes the
        approval-integrity TOCTOU: a racing push to the PR branch could otherwise
        be mistaken for a base update and auto-merged without review.

        ``old_head_sha`` must be a real SHA the caller observed before the sync
        attempt. A ``None``/falsy value means the caller never had a valid
        pre-sync head to verify against, so verification cannot succeed;
        return early rather than falling through to the parent-SHA check below,
        where ``None not in parent_shas`` would otherwise be vacuously true for
        any two-parent web-flow merge commit and mask this as a normal miss.
        """
        if not old_head_sha:
            return None
        pr = self.gh.pr_view(pr_number)
        if not pr:
            return None
        new_head_sha = pr.get("headRefOid")
        if not new_head_sha:
            return None
        if new_head_sha == old_head_sha:
            return new_head_sha

        commit_result = self.gh.commit(new_head_sha)
        if isinstance(commit_result, GitHubRunResult):
            commit = (
                commit_result.value
                if commit_result.ok and isinstance(commit_result.value, dict)
                else None
            )
        elif isinstance(commit_result, dict):
            commit = commit_result
        else:
            commit = None
        if not commit:
            return None

        parents = commit.get("parents") or []
        if len(parents) != 2:
            return None
        parent_shas = [str(p.get("sha")) for p in parents if isinstance(p, dict)]
        if old_head_sha not in parent_shas:
            return None

        committer = commit.get("committer") or {}
        if not isinstance(committer, dict):
            committer = {}
        commit_committer = commit.get("commit", {}).get("committer") or {}
        if not isinstance(commit_committer, dict):
            commit_committer = {}
        committer_login = committer.get("login")
        committer_name = commit_committer.get("name")
        # Both identity signals must match a GitHub-generated merge. The git
        # metadata name is pusher-settable, and the account login can be
        # spoofed via the committer email, so accepting either alone would let
        # a crafted racing push get blessed as a base sync. Fail closed.
        if committer_login != "web-flow" or committer_name != "GitHub":
            return None

        return new_head_sha

    def _should_update_pr_branch(
        self,
        pr: dict[str, Any],
        base_current: bool | None | _BaseCurrentUnset = _BASE_CURRENT_UNSET,
    ) -> bool:
        """Return True if the PR branch should be synced against its base.

        When a ``base_current`` signal is supplied, it is authoritative:
        ``True`` means the branch is already up-to-date and no sync is needed;
        ``False`` means the branch is stale and should be synced; ``None`` means
        the compare API is unavailable, so fail-closed and do not sync.

        If no ``base_current`` signal is supplied, fall back to the legacy
        mergeStateStatus heuristic for backward compatibility.
        """
        if isinstance(base_current, _BaseCurrentUnset):
            status = str(pr.get("mergeStateStatus") or "").upper()
            return status not in {"CLEAN", "UNSTABLE", "HAS_HOOKS"}
        return base_current is False

    def _is_base_current(self, pr: dict[str, Any]) -> bool | None:
        """Return True if the PR's merge-base is the current tip of its base.

        Uses the GitHub compare API to derive ancestry rather than timestamps
        or mergeStateStatus, which can lag. Returns ``None`` when the comparison
        cannot be completed so callers can decide how to fail-safe.
        """
        base_ref = pr.get("baseRefName") or self.config.runners.default_branch
        head_sha = pr.get("headRefOid")
        if not base_ref or not head_sha:
            return None
        comparison = self.gh.compare(base_ref, head_sha)
        if not comparison:
            return None
        base_commit = comparison.get("base_commit")
        merge_base_commit = comparison.get("merge_base_commit")
        if not isinstance(base_commit, dict) or not isinstance(merge_base_commit, dict):
            return None
        base_sha = base_commit.get("sha")
        merge_base_sha = merge_base_commit.get("sha")
        if not base_sha or not merge_base_sha:
            return None
        return bool(base_sha == merge_base_sha)

    def _is_base_currency_gated(self, base_ref: str) -> bool:
        """Return whether ``merge_ready`` must refuse to merge a stale-base PR.

        This is the *merge gate* policy. It differs deliberately from
        ``_is_base_freshness_required`` (the *broadcast sweep* policy) and the
        difference is the entire point of issue #875.

        Issue #812 made base-freshness policy protection-derived, so that a
        repo with ``required_status_checks.strict: false`` would not burn CI
        re-running every open PR against a base GitHub does not require it to
        be current with. That reasoning is correct for the broadcast sweep,
        which writes to *N* open PRs per merge.

        Applying it to the merge gate too was the defect. This repo runs
        ``strict: false`` (a deliberate capacity decision -- two self-hosted
        runners cannot sustain strict mode), so the gate derived "currency not
        required" and disabled *itself*. ``_is_base_current`` was still correct
        and still failed closed; it was simply never reached. An approved PR
        whose base had advanced merged without its merged tree ever being
        tested, which is how ``main`` went red (both parents green, merge
        untested -- the same class as #853 x #865).

        So protection may *raise* the requirement, never *lower* it below what
        the operator asked for:

            gated = require_current_base OR protection_strict

        - ``strict: true`` + ``require_current_base=False`` -> gated (unchanged
          from #812: protection-derived enforcement still works for operators
          who opted out in config).
        - ``strict: false`` + ``require_current_base=True`` -> gated. **This is
          the #875 fix.** Previously ungated.
        - protection unreadable -> falls through to
          ``_is_base_freshness_required``'s fail-closed contract, which returns
          ``require_current_base``.

        Cost: one ``pr_update_branch`` + one CI cycle for the single PR that is
        actually merging, not N cycles across every open PR -- the broadcast
        sweep keeps calling ``_is_base_freshness_required`` and keeps #812's
        saving. The real cost is serialization: each merge staleness-invalidates
        the next PR in the lane, which must then rebase and wait for CI before
        it can land. That is the intended trade -- a slower lane against a lane
        that merges untested trees.

        Scope limit: this gate cannot retract a PR already handed to Aviator
        MergeQueue (``already_in_mergequeue`` suppresses the write, and the
        deferral does not remove the label), and it cannot stop a human
        pressing merge in the GitHub UI. It prevents the *initial* handoff of a
        stale PR, which is the path the orchestrator controls.
        """
        if self.config.auto_merge.require_current_base:
            return True
        return self._is_base_freshness_required(base_ref)

    def _is_base_freshness_required(self, base_ref: str) -> bool:
        """Return whether base currency is actually required for ``base_ref``.

        Derives base-freshness policy from GitHub branch protection
        (``required_status_checks.strict``) instead of trusting the
        hardcoded ``auto_merge.require_current_base`` config constant
        (issue #812). A repo whose protection sets ``strict: false`` does
        not require branches to be current with their base before merging,
        so forcing ``pr_update_branch`` on every open PR and deferring
        merges on staleness is pure CI-capacity waste with zero
        mergeability benefit.

        The read is cached per orchestrator pass by
        ``GitHub.branch_protection`` (cleared each pass by
        ``_loop_body``'s ``invalidate_list_cache()`` call), so PRs sharing a
        base ref within one pass cost exactly one API call in total.

        FAILS CLOSED: this is the single most important safety property of
        the derivation. If the protection read raises, returns an error
        value (``None``), 404s, is rate-limited, or
        ``required_status_checks.strict`` is absent or not a bool for any
        reason, this falls back to ``auto_merge.require_current_base``
        (default ``True``) rather than treating the failure as "no
        freshness required". An API hiccup must never silently disable base
        checking.
        """
        try:
            protection = self.gh.branch_protection(base_ref)
        except Exception:
            import logging

            logging.getLogger(__name__).warning(
                "branch_protection(%s) raised; failing closed to "
                "auto_merge.require_current_base=%s",
                base_ref,
                self.config.auto_merge.require_current_base,
                exc_info=True,
            )
            return self.config.auto_merge.require_current_base
        if isinstance(protection, dict):
            required_status_checks = protection.get("required_status_checks")
            if isinstance(required_status_checks, dict):
                strict = required_status_checks.get("strict")
                if isinstance(strict, bool):
                    return strict
        return self.config.auto_merge.require_current_base

    def _record_review_or_error(
        self,
        review_result: CommandResult,
        errors: list[dict[str, Any]],
        reviews: list[dict[str, Any]],
    ) -> bool:
        """Append a review result to reviews or errors if checks are unavailable.

        Returns True if the caller should continue to the next PR (the unavailable
        case has already been recorded as an error).
        """
        if review_result.data.get("checks_unavailable"):
            errors.append({"pr": review_result.data.get("pr"), "error": review_result.message})
            return True
        reviews.append(review_result.data)
        return False

    def _record_merge_or_error(
        self,
        merge_result: CommandResult,
        errors: list[dict[str, Any]],
        merges: list[dict[str, Any]],
    ) -> None:
        """Append a merge_ready result to merges or errors if a gh check failed."""
        if merge_result.data.get("checks_unavailable") or merge_result.data.get(
            "merge_hold_check_unavailable"
        ):
            errors.append({"pr": merge_result.data.get("pr"), "error": merge_result.message})
        else:
            merges.append(merge_result.data)

    def _mark_foreign_issue_ref(self, pr_number: int, issue_number: int, reason: str) -> bool:
        """Durably park a PR whose linked issue does not exist in this repo.

        A PR opened against the wrong fleet repo (e.g. its branch references
        another repo's issue number) can never be processed here: every pass
        would re-derive the same issue number and re-fail the same GitHub
        lookup forever. Persist a ``foreign_issue_ref`` marker in the PR's
        state entry so subsequent passes skip it with zero GitHub calls.

        Returns True only on the first marking for this (pr, issue) pair so
        the caller can emit a one-shot attention event.
        """
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            marker = pr_state.get("foreign_issue_ref") or {}
            if marker.get("issue") == issue_number:
                return False
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "foreign_issue_ref": {
                    "issue": issue_number,
                    "detected_at": utc_now(),
                    "reason": reason,
                },
            }
            save_state(self.paths.state_file, state)
        return True

    @_guard_state_lock
    def loop(
        self,
        limit: int | None = None,
        *,
        merge: bool | None = None,
        now: datetime | None = None,
    ) -> CommandResult:
        # ``now`` (issue #822, extended #828) is this pass's injectable clock.
        # ``_loop_body`` forwards it, unresolved, to every cadence-gated lane
        # that samples wall-clock time: dead-session throttle classification
        # (``_classify_dead_sessions_and_update_throttle_state``), the
        # stalled-session reaper (``_detect_and_handle_stalled_sessions``),
        # and the quota-probe/worktree-reclaim/drift-reconcile schedulers
        # (``_maybe_probe_quota_recovery``, ``_maybe_reclaim_worktrees``,
        # ``_maybe_reconcile_drift``). Each callee independently defaults to
        # ``datetime.now(UTC)`` when it receives None, so production behavior
        # is byte-identical when this argument is omitted (as all current
        # production callers do); tests can freeze one ``now`` and assert
        # exact equality instead of a wall-clock-tolerance proximity check.
        return self._loop_impl(limit, merge=merge, now=now)

    def _loop_impl(
        self, limit: int | None, *, merge: bool | None, now: datetime | None = None
    ) -> CommandResult:
        # Issue #1363: preflight gate. Runs BEFORE `loop_started` is recorded
        # -- a fatal host-precondition failure (disk_floor, venv_identity)
        # must refuse the pass with zero partial work, not half-run it and
        # fail midway with a generic error. Non-fatal failures (clock_sanity,
        # config_freshness) emit a warning event and the pass proceeds
        # unmodified -- on a healthy host this adds no event at all (AC3).
        preflight_result = run_preflight(
            PreflightPaths(
                repo_root=self.repo_root,
                state_dir=self.paths.root,
                # venv_identity must anchor on the orchestrator's OWN
                # checkout (the code/venv this process is actually running),
                # never on `self.repo_root` -- that is the *target* repo this
                # particular pass processes, which varies per registered
                # repo even though every one of them runs from the same
                # single orchestrator install. See PreflightPaths.
                # orchestrator_root's docstring for why conflating the two
                # would make venv_identity fatally misfire on every repo
                # other than the orchestrator's own.
                orchestrator_root=orchestrator_root(),
            ),
            self.config.runtime.preflight,
            now=now,
            config_sources=self.config.sources,
            known_config_mtimes=self._preflight_config_mtimes,
        )
        for check in preflight_result.non_fatal_failures:
            kind = (
                "preflight_config_stale"
                if check.name == "config_freshness"
                else "preflight_warning"
            )
            log_event(
                self.paths.state_file,
                kind,
                {"check": check.name, "detail": check.detail},
                repo=self.repo_root.name,
                level="warning",
            )
        if not preflight_result.ok:
            fatal_check = preflight_result.fatal_failures[0]
            emit_preflight_refusal(self.paths.state_file, fatal_check, repo=self.repo_root.name)
            return CommandResult(
                False,
                f"preflight refused pass: {fatal_check.name}: {fatal_check.detail}",
                {
                    "pass_skipped": True,
                    "reason": "preflight_refused",
                    "check": fatal_check.name,
                    "detail": fatal_check.detail,
                },
            )

        # merge=False runs the full pass (intake, dispatch, reviews, readiness
        # evaluation + labels) but skips the actual `gh pr merge` — for
        # operators sequencing same-surface PR cascades by hand, where the
        # pr_list (newest-first) merge order would land PRs in the wrong order.
        loop_start = time.monotonic()
        with correlation_context() as cid:
            start_ts = utc_now()
            log_event(
                self.paths.state_file,
                "loop_started",
                {"limit": limit, "merge": merge},
                repo=self.repo_root.name,
                correlation_id=cid,
            )
            record_loop_pass(self.paths.state_file, cid, start_ts)
            # Issue #1083: snapshot the ``agent:human-needed`` sink before the
            # pass mutates anything, so arrivals (after - before) and the
            # post-pass population are a census diff, not an event-kind
            # allow-list that would have to be maintained in lockstep with
            # every new escalation call site. Read-only; ``load_state_locked``
            # (not raw ``load_state``) so the snapshot holds the advisory lock
            # -- the lint guard in ``test_no_unlocked_load_state_in_production_code``
            # flags any bare ``load_state`` outside a ``state_lock`` context.
            sink_before = sink_census(load_state_locked(self.paths.state_file))
            result = self._loop_body(limit, merge=merge, now=now)
            elapsed = time.monotonic() - loop_start
            sink_after = sink_census(load_state_locked(self.paths.state_file))
            sink_arrivals = len(sink_after - sink_before)
            sink_population = len(sink_after)
            # Sweep clears are the one signal that cannot be derived from the
            # census diff: a departure may be an operator ``unescalate``, a
            # merge, or a close, none of which are sweep drainage.
            # ``deescalation_cleared`` has a single emitter
            # (``_deescalate_mechanical_issue``) and shares this pass's
            # correlation ID, so a count by (kind, correlation_id) is the
            # exact sweep-clear count with no allow-list to drift. Queried
            # before ``loop_completed`` is emitted so this event is not
            # self-counted.
            sink_clears = len(
                query_events(
                    self.paths.state_file,
                    kind="deescalation_cleared",
                    correlation_id=cid,
                )
            )
            # Issue #1383: reset the cross-pass infra_blocked window when a
            # pass reviews at least one PR and finds none infra-blocked --
            # the fleet-wide infra condition has cleared, so the
            # consecutive-pass counter starts fresh next time. Queried by
            # this pass's correlation ID (same pattern as sink_clears
            # above) so the count is exact for this pass with no
            # allow-list to drift.
            #
            # Round-2 #1383 review: the reset must NOT fire merely because
            # zero ``check_infra_blocked`` events were emitted -- that is
            # also true when the pass reviewed no PRs at all (empty queue,
            # ``limit=0`` with no candidates, ...). Resetting on an
            # idle pass during a live outage silently clears
            # ``consecutive_passes``/``last_escalation`` and can prevent
            # the AC3 persistence escalation from ever firing. Gate on
            # ``reviews`` (PRs actually reviewed this pass) being
            # non-empty so the reset means "we looked and the coast was
            # clear", not "we didn't look".
            infra_blocked_this_pass = len(
                query_events(
                    self.paths.state_file,
                    kind="check_infra_blocked",
                    correlation_id=cid,
                )
            )
            reviewed_this_pass = len(result.data.get("reviews", []))
            if reviewed_this_pass > 0 and infra_blocked_this_pass == 0:
                repo_key = str(self.repo_root)
                window = _infra_blocked_window.get(repo_key)
                if window is not None and window.get("consecutive_passes", 0) > 0:
                    _infra_blocked_window[repo_key] = {
                        "consecutive_passes": 0,
                        "last_escalation": None,
                        "last_pass_cid": None,
                    }
            # Issue #1314 item 3: operator-queue depth gauge. Emitted after
            # ``_loop_body`` so the gauge reflects post-pass state (the
            # de-escalation sweep inside ``_loop_body`` may have cleared some
            # issues), and before ``loop_completed`` so the gauge event is
            # not self-counted by any post-pass event query. Shares this
            # pass's correlation ID so the depth reading is attributable to
            # the same pass as the sink census above.
            self._maybe_emit_operator_queue_depth()
            log_event(
                self.paths.state_file,
                "loop_completed",
                {
                    "ok": result.ok,
                    "message": result.message,
                    "elapsed_seconds": round(elapsed, 2),
                    "error_count": len(result.data.get("errors", [])),
                    # Issue #933: the count alone made "loop completed with 1 PR
                    # error(s)" undiagnosable — two independent sessions misread a
                    # 21-pass ok=False streak as healthy because no stored artifact
                    # named the PR. Bounded; see summarize_loop_errors.
                    **summarize_loop_errors(result.data.get("errors", [])),
                    # Issue #1083: autonomy is never reported without its drop
                    # rate. ``sink_arrivals`` is the first-class failure metric
                    # (issues dropped to a human this pass); ``sink_clears`` is
                    # the automated drainage; ``sink_population`` is the
                    # point-in-time census of parked work. A rise in arrivals
                    # without a matching rise in clears is the signature of a
                    # growing sink, and the ratio of clears to population is
                    # the drainage rate #1093's mirror-clear should move.
                    "sink_population": sink_population,
                    "sink_arrivals": sink_arrivals,
                    "sink_clears": sink_clears,
                },
                repo=self.repo_root.name,
                correlation_id=cid,
            )
            record_loop_pass(
                self.paths.state_file,
                cid,
                start_ts,
                completed_at=utc_now(),
                ok=result.ok,
                elapsed_seconds=round(elapsed, 2),
                error_count=len(result.data.get("errors", [])),
                merge_count=len(result.data.get("merges", [])),
                review_count=len(result.data.get("reviews", [])),
                sink_population=sink_population,
                sink_arrivals=sink_arrivals,
                sink_clears=sink_clears,
            )
            return result

    def _maybe_probe_quota_recovery(self, *, now: datetime | None = None) -> None:
        """Flat-interval Haiku probe for early quota/rate-limit throttle recovery.

        Runs every loop pass but is a near-no-op unless a throttle that a
        green ambient-CLI probe could actually clear is currently active
        (``is_quota_probe_actionable``) -- an operator switching to a
        different subscription account can make a provider's quota recover
        well before a blanket cooldown (e.g. the 24h
        ``_DEFAULT_QUOTA_COOLDOWN_HOURS`` window) elapses, and there was
        previously no way to detect that early. Deliberately a *flat*
        ``quota_probe.interval_minutes`` schedule (not exponential backoff
        like ``reviewer_quota.probe_after``): the user asked for a fixed
        15-minute recheck, not a growing wait.

        The gate is narrower than "any throttle indicator" -- a devin/api
        adapter throttle or a provider_auth cooldown would survive
        ``clear_quota_throttles`` untouched even on a green probe (see that
        function), so arming/probing for one would just burn Haiku sessions
        every interval for no possible benefit. Because of this, a green
        probe reaching the success branch below is guaranteed to have
        something to clear -- no post-hoc check needed there.

        Two-phase lock pattern so the (possibly tens-of-seconds) subprocess
        call in ``run_quota_probe`` never holds ``state_lock`` and blocks
        every other state read/writer in the process:
          1. Under the lock: decide whether to probe at all, and if not,
             arm/disarm/return without calling out to the CLI.
          2. Outside the lock: run the actual probe subprocess.
          3. Under the lock again: re-read state (it may have changed while
             unlocked) and apply the outcome.

        ``now`` (issue #828) is the injectable clock for this whole method:
        both internal ``datetime.now(UTC)`` samples below (the first-arm
        branch and the red-probe reschedule branch) resolve from the same
        seeded instant instead of each independently racing the wall clock.
        Defaults to ``datetime.now(UTC)`` when omitted, so production
        behavior is byte-identical; tests can freeze it and assert exact
        equality on the scheduled ``next_probe_at`` instead of a
        wall-clock-tolerance proximity check.
        """
        if not self.config.quota_probe.enabled:
            return

        resolved_now = now if now is not None else datetime.now(UTC)
        state_file = self.paths.state_file
        with state_lock(state_file):
            state = load_state(state_file)
            if not is_quota_probe_actionable(state):
                if is_quota_probe_armed(state):
                    state = disarm_quota_probe(state)
                    save_state(state_file, state)
                return
            if not is_quota_probe_armed(state):
                next_probe_at = (
                    (resolved_now + timedelta(minutes=self.config.quota_probe.interval_minutes))
                    .replace(microsecond=0)
                    .isoformat()
                    .replace("+00:00", "Z")
                )
                state = arm_quota_probe(state, next_probe_at)
                save_state(state_file, state)
                return
            if not is_quota_probe_due(state):
                return

        probe_ok = run_quota_probe(repo_root=self.repo_root, config=self.config)

        with state_lock(state_file):
            state = load_state(state_file)
            if not is_quota_probe_actionable(state):
                # Cleared or became non-actionable while the probe ran unlocked.
                state = disarm_quota_probe(state)
                save_state(state_file, state)
                return
            if probe_ok:
                state = clear_quota_throttles(state)
                state = disarm_quota_probe(state)
                state = self._record_event(state, "quota_probe_succeeded", {})
            else:
                next_probe_at = (
                    (resolved_now + timedelta(minutes=self.config.quota_probe.interval_minutes))
                    .replace(microsecond=0)
                    .isoformat()
                    .replace("+00:00", "Z")
                )
                state = arm_quota_probe(state, next_probe_at)
                # Share the failure with dispatch_reviews's probe_mode gate:
                # a red flat probe confirmed the window is still closed, so
                # also bump reviewer_quota.probe_after (when the reviewer
                # quota is exhausted) to stop dispatch_reviews from
                # independently launching a real reviewer session into the
                # same window on this or a nearby pass (issue #663).
                state = defer_reviewer_probe_after(state, next_probe_at)
                state = self._record_event(state, "quota_probe_failed", {})
            save_state(state_file, state)

    def _maybe_reclaim_worktrees(self, *, now: datetime | None = None) -> dict[str, Any] | None:
        """Cadence-gated merged-PR worktree reclamation on the fleet pass.

        Runs ``clean_worktrees`` -- the same junction-safe, merge-gated,
        liveness-gated sweep behind ``charlie worktree-clean`` -- on a flat
        ``worktree_reclamation.interval_minutes`` schedule. Before this call
        site the sweep only ran when an operator remembered the standalone
        subcommand, so worktrees for merged PRs accumulated indefinitely
        (issue #636: 77 of 81 dead on the host this was measured on).

        Two-phase lock pattern (same shape as ``_maybe_probe_quota_recovery``):
        the schedule is advanced under the lock and the sweep itself runs
        outside it, because ``clean_worktrees`` makes a live ``gh pr view`` call
        per candidate worktree and must not hold ``state_lock`` while it does --
        holding the lock across a per-candidate GitHub fan-out would block every
        other state reader/writer in the process for the sweep's duration.

        ``dry_run`` is threaded honestly: a ``--dry-run`` fleet pass runs the
        sweep in preview mode, which removes nothing (the preview-vs-act class
        tracked in #614-#619). A ``worktrees_reclaimed`` event is always emitted
        when the sweep runs, so a maintenance action that left no trace is
        indistinguishable from one that never ran (lesson from #595/#621).
        The event payload carries a bounded ``skipped_examples`` list (each
        entry's own ``reason`` string) alongside the exact ``skipped_count``,
        plus ``worktrees_registered``/``worktrees_out_of_scope`` -- so a
        worktree stuck for days can be diagnosed from events.db alone,
        without catching the sweep live (issue #1012).

        The cadence schedule itself is advanced regardless of ``dry_run``.
        This is deliberate, not an instance of the #614-#619 class:
        ``clean_worktrees`` makes its live ``gh pr view`` call per candidate
        unconditionally -- ``dry_run`` only gates the final ``git worktree
        remove`` -- so the GitHub-quota cost this interval exists to bound is
        identical in preview and live mode. Not advancing the schedule under
        ``dry_run`` would let a repeated preview pass re-run the full
        per-candidate fan-out every time, defeating the cadence gate.

        Returns a small summary dict when the sweep ran (for the loop result's
        ``data``), or ``None`` when reclamation is disabled or not due this
        pass.

        ``now`` (issue #828) is the injectable clock used to compute
        ``next_run_at`` below, BEFORE the ``clean_worktrees`` call's live
        ``gh pr view`` fan-out. Defaults to ``datetime.now(UTC)`` when
        omitted, so production behavior is byte-identical; tests can freeze
        it and assert exact equality on the scheduled ``next_run_at`` instead
        of a wall-clock-tolerance proximity check that would otherwise race
        the fan-out's own duration.
        """
        if not self.config.worktree_reclamation.enabled:
            return None
        resolved_now = now if now is not None else datetime.now(UTC)
        state_file = self.paths.state_file
        with state_lock(state_file):
            state = load_state(state_file)
            if not is_worktree_reclamation_due(state):
                return None
            # Advance the schedule BEFORE running the sweep so a concurrent
            # pass (or a sweep that takes longer than one poll interval) cannot
            # double-fire. The next run is interval_minutes away regardless of
            # how long the sweep itself takes.
            next_run_at = (
                (
                    resolved_now
                    + timedelta(minutes=self.config.worktree_reclamation.interval_minutes)
                )
                .replace(microsecond=0)
                .isoformat()
                .replace("+00:00", "Z")
            )
            state = schedule_worktree_reclamation(state, next_run_at)
            save_state(state_file, state)

        # Use the same resolved worktrees root dispatch and `charlie
        # worktree-clean` use (self._layout.worktrees, from
        # paths.resolved_layout) rather than re-deriving the
        # claude_code.worktrees_dir/runtime.state_dir sentinel logic inline --
        # that duplication across call sites is the exact shape of bug
        # layout.py's module docstring documents as a past production
        # incident (create and sweep sides silently disagreeing on the root).
        state = load_state_locked(state_file)
        result = clean_worktrees(
            self.repo_root,
            self._layout.worktrees,
            state,
            self.config,
            self.gh,
            dry_run=self.dry_run,
        )
        orphans = result.data.get("orphans", {})
        skipped_full = result.data.get("skipped", [])
        summary = {
            "dry_run": self.dry_run,
            "ok": result.ok,
            "removed": len(result.data.get("removed", [])),
            "planned": len(result.data.get("planned", [])),
            "skipped_count": len(skipped_full),
            "failed": len(result.data.get("failed", [])),
            "orphans_removed": len(orphans.get("removed", [])),
            "orphans_planned": len(orphans.get("planned", [])),
            "orphans_failed": len(orphans.get("failed", [])),
            "message": result.message,
            # issue #1012: clean_worktrees computes a distinct `reason` per
            # skipped worktree (at least nine distinct strings across the
            # merged/closed-unmerged/liveness gates), but until this fix only
            # `skipped_count` reached this durable payload -- "11 skipped" with
            # no way to tell which reason, or whether a specific stuck
            # worktree was even a candidate. Truncated to
            # `_MAX_SKIPPED_WORKTREE_EXAMPLES` so a standing backlog can't
            # re-emit the full list into events.db every interval;
            # `skipped_count` above is still the exact, untruncated count.
            "skipped_examples": skipped_full[:_MAX_SKIPPED_WORKTREE_EXAMPLES],
            # Distinguishes "never a candidate" (outside worktrees_dir or off
            # the dispatch branch prefix -- an operator-created worktree, for
            # instance) from "considered and skipped": neither was
            # observable from this event before.
            "worktrees_registered": result.data.get("worktrees_registered", 0),
            "worktrees_out_of_scope": result.data.get("worktrees_out_of_scope", 0),
        }
        with state_lock(state_file):
            state = load_state(state_file)
            state = self._record_event(state, "worktrees_reclaimed", summary)
            save_state(state_file, state)
        return summary

    def _maybe_reconcile_drift(self, *, now: datetime | None = None) -> None:
        """Periodic in-loop repair of GitHub label / state.json divergence.

        merge-lane-recovery plan §6-B / D-8. ``OrchestratorApp.reconcile()``
        (``detect_drift`` + ``apply_fixes``) was previously reachable only
        via the operator-invoked ``charlie mop-up --fix`` CLI command
        (``cli.py``'s ``mop-up`` handler) -- the fleet has never run its own
        repair. This wires it into the loop on a fixed cadence so a
        divergence like a failed escalation label write (the PRIMARY defect:
        ``status`` flips to ``escalated`` but the paired ``human_needed``
        label transition silently fails, leaving a stale ``needs-rework``
        label on a dead issue forever) is corrected automatically instead of
        only when an operator remembers to intervene.

        This method is wiring only -- it does not reimplement drift
        detection or repair. ``self._reconcile_locked(fix=True)`` owns that (and
        already threads ``state_path`` so ``apply_fixes`` emits one
        ``"reconcile"`` event per repaired drift item for free -- see
        ``reconcile.py``). It also owns the safety invariant this
        workstream exists to preserve: an open escalated issue's
        ``status`` is never rewritten (D-2), and reconcile never rewrites
        ``status`` to an active dispatch/rework value. Any status writes
        it does make are to terminal or passive values (``closed``,
        ``merged``, ``open_passive``) or to clear a stale/missing key;
        a closed-while-escalated issue is finalized to ``closed`` like
        any other, but no escalated issue is ever re-entered into the
        machine. This method does not touch ``status``.

        Calls with ``skip_dead_session_sweep=True``: this pass already ran
        the loop's own stall/dead lanes (``_detect_and_handle_stalled_sessions``
        / ``_classify_dead_sessions_and_update_throttle_state``) earlier in
        ``_loop_body``, with grace-period semantics
        (``max_inconclusive_probe_deferrals``) that reconcile.py's own
        dead-session sweep predates and does not implement. Without this,
        reconcile would re-scan the same sessions a few calls later and
        unconditionally reap any not-alive one, silently defeating that
        grace period every time this pass runs. See ``detect_drift``'s
        docstring in ``reconcile.py`` for the full rationale. Launch-stalled
        detection and live-session tracking (the other two things gated on
        ``repo_root`` in ``detect_drift``) are unaffected -- they have no
        counterpart in the loop's own lanes and keep running.

        Calls ``_reconcile_locked`` directly, NOT ``reconcile()`` -- this is
        the whole point of the D-8a split and reverting it silently disables
        this entire method. ``reconcile()`` acquires ``supervisor.lock``
        before doing anything else, and every production caller of ``loop()``
        already holds that exact lock for the full duration of the call:
        ``cli.py``'s ``bash-rats`` handler, ``fleet_dispatch.py``, and
        ``supervise.py`` (which holds it across *every* pass of its
        ``while True``). Byte-range locks taken via ``msvcrt.locking`` with
        ``LK_NBLCK`` are per-handle and non-reentrant *even within a single
        process* -- ``file_lock.py`` keeps no reentrancy bookkeeping -- so a
        second acquisition from inside the same process fails exactly like a
        foreign process's would. Going through ``reconcile()`` here therefore
        always took the ``supervisor_lock_held`` early return and never ran.

        Two-phase lock pattern, mirroring ``_maybe_probe_quota_recovery``:
        ``_reconcile_locked`` acquires ``state_lock`` itself internally to
        run drift detection/repair, and ``state_lock`` wraps a non-reentrant
        advisory file lock (a plain per-path ``threading.Lock``, not an
        ``RLock``) -- calling it while this method already held the same lock
        would deadlock. So:
          1. Under our own (short) lock: decide whether reconcile is due at
             all. If not, return without calling out.
          2. Outside any lock held by this method: call
             ``self._reconcile_locked(fix=True)``. This may still defer (the
             existing GraphQL rate-limit check) -- that path is preserved.
             It can no longer report ``supervisor_lock_held``, because it
             never attempts that acquisition; the lock is already held by
             ``loop()``'s caller, which is the precondition this method
             relies on rather than something it works around.
          3. Under our own (short) lock again: persist the next-due
             timestamp and emit exactly one summary event for this pass,
             shaped by the outcome (completed / deferred / failed) so a
             deferred or failed pass is distinguishable from a silent
             no-op rather than failing silently (D-8, B-AC3).

        The call is wrapped in exception containment, and that containment is
        load-bearing rather than defensive habit: ``supervise.py``'s
        ``except Exception`` sits *outside* its ``while True``, so a single
        uncaught exception from here terminates the whole daemon rather than
        one pass. ``_fetch_prs``/``_fetch_issues`` reach GitHub via
        ``gh.run(..., json_output=True)`` with ``allow_failure=False``, which
        *raises* ``GitHubError``/``GitHubNotFoundError`` once retries are
        exhausted -- so without this, a GitHub outage is a live daemon-kill
        path. A failed pass re-arms the timer like any other outcome, so a
        persistent failure degrades to one logged error per interval instead
        of a hot loop.

        ``now`` (issue #828) is the injectable clock used to compute
        ``next_reconcile_at`` below, BEFORE ``self._reconcile_locked(...)``
        acquires ``state_lock`` and does its own (potentially slow) drift
        detection/repair. Defaults to ``datetime.now(UTC)`` when omitted, so
        production behavior is byte-identical; tests can freeze it and
        assert exact equality on the scheduled ``next_reconcile_at`` instead
        of a wall-clock-tolerance proximity check that would otherwise race
        the reconcile call's own duration.
        """
        if not self.config.reconcile_pass.enabled:
            return

        resolved_now = now if now is not None else datetime.now(UTC)
        state_file = self.paths.state_file
        with state_lock(state_file):
            state = load_state(state_file)
            if not is_reconcile_due(state):
                return

        next_reconcile_at = (
            (resolved_now + timedelta(minutes=self.config.reconcile_pass.interval_minutes))
            .replace(microsecond=0)
            .isoformat()
            .replace("+00:00", "Z")
        )

        # D-8a: _reconcile_locked, never reconcile(). See this method's
        # docstring -- reconcile() would re-acquire the supervisor lock that
        # loop()'s caller already holds and silently no-op every pass.
        try:
            result = self._reconcile_locked(
                fix=True,
                skip_dead_session_sweep=True,
                dry_run=self.dry_run,
            )
        except Exception as exc:  # noqa: BLE001 - containment is deliberate; see docstring
            with state_lock(state_file):
                state = load_state(state_file)
                state = arm_reconcile_pass(state, next_reconcile_at)
                state = self._record_event(
                    state,
                    "reconcile_pass_failed",
                    {"error": f"{type(exc).__name__}: {exc}"},
                )
                save_state(state_file, state)
            return

        with state_lock(state_file):
            state = load_state(state_file)
            state = arm_reconcile_pass(state, next_reconcile_at)
            data = result.data
            if data.get("pass_skipped"):
                state = self._record_event(
                    state,
                    "reconcile_pass_skipped",
                    {"reason": data.get("reason")},
                )
            elif data.get("deferred"):
                if not data.get("reconcile_pass_event_recorded"):
                    state = self._record_event(
                        state,
                        "reconcile_pass_deferred",
                        {
                            "deferred_reason": data.get("deferred_reason"),
                            "graphql_remaining": data.get("graphql_remaining"),
                            "graphql_reset": data.get("graphql_reset"),
                            "graphql_threshold": data.get("graphql_threshold"),
                        },
                    )
            else:
                drift_before = data.get("drift_before", 0)
                drift_after = data.get("drift_after", 0)
                state = self._record_event(
                    state,
                    "reconcile_pass_completed",
                    {
                        "ok": result.ok,
                        "drift_detected": drift_before,
                        "drift_fixed": drift_before - drift_after,
                        "drift_remaining": drift_after,
                    },
                )
            save_state(state_file, state)

    def _maybe_reclaim_superseded_main_ci(self) -> None:
        """Cancel superseded, not-yet-started ``main`` CI runs every pass (#863, #815).

        ``main_ci_reclaim.reclaim_superseded_main_ci_runs`` owns the actual
        detection/cancellation logic and its safety invariant (never a
        started run, never main's current tip, only strict ancestors of
        tip) -- see that module's docstring. This method is wiring only.

        Deliberately has NO cadence gate, unlike ``_maybe_reconcile_drift``
        and ``_maybe_probe_quota_recovery`` above: running on every pass is
        the mechanism that closes #815 (the reaper workflow gets only one
        scheduling chance per main push and can permanently lose the race to
        the stale run starting first). Since this lane needs no runner --
        just a local ``git fetch`` plus a couple of cheap ``gh api`` calls --
        running it unconditionally on every pass gives a superseded run
        repeated chances to be reclaimed across passes, which a runner-bound
        workflow retry could never provide regardless of how often it were
        scheduled.

        ``self.config.runners.default_branch`` is reused rather than adding
        a second ``default_branch`` knob on ``MainCiReclaimConfig`` --
        "what is this repo's default branch" is one fact, not one per
        feature, and a second copy would only risk drifting out of sync with
        the first.

        Event policy (issue tracker: "signal without a consumer" is this
        repo's #1 recurring defect class, so this is deliberate rather than
        an oversight): unlike ``_maybe_reconcile_drift``, which emits one
        summary event on every call because its cadence is bounded to once
        per ``interval_minutes``, this method has no cadence gate and the
        overwhelming majority of passes will find zero candidates -- writing
        a ``main_ci_reclaim_completed`` event every single pass would add
        events.db volume with zero diagnostic value and crowd the capped
        200-entry ``state.json`` ring. So a durable event is written only
        when there is something worth a durable record: an actual
        cancellation (``main_ci_reclaim_cancelled``) or a pass-level failure
        (``main_ci_reclaim_failed``). Both are consumed the same way
        ``reconcile_pass_*`` events already are: ``query_events``/
        ``event_counts_by_kind`` for structured aggregation, and
        ``events_by_correlation_id`` to reconstruct a specific pass. The
        zero-candidate case still gets an immediate, cheap consumer via
        ``logger.debug`` below -- proof-of-life without a durable write.

        Wrapped in exception containment for the same reason as every other
        ``_maybe_*`` lane in this method: ``supervise.py``'s
        ``except Exception`` sits outside its ``while True``, so one
        uncaught exception here would kill the whole daemon rather than one
        pass.
        """
        if not self.config.main_ci_reclaim.enabled:
            return

        import logging

        logger = logging.getLogger(__name__)
        state_file = self.paths.state_file
        try:
            result = reclaim_superseded_main_ci_runs(
                self.gh,
                self.repo_root,
                default_branch=self.config.runners.default_branch,
                workflow_filename=self.config.main_ci_reclaim.workflow_filename,
            )
        except Exception as exc:  # noqa: BLE001 - containment is deliberate; see docstring
            with state_lock(state_file):
                state = load_state(state_file)
                state = self._record_event(
                    state,
                    "main_ci_reclaim_failed",
                    {"error": f"{type(exc).__name__}: {exc}"},
                )
                save_state(state_file, state)
            logger.warning("main_ci_reclaim pass raised an exception", exc_info=True)
            return

        if not result.ok:
            with state_lock(state_file):
                state = load_state(state_file)
                state = self._record_event(
                    state, "main_ci_reclaim_failed", {"error": result.error}
                )
                save_state(state_file, state)
            logger.warning("main_ci_reclaim pass failed: %s", result.error)
            return

        if not result.cancelled:
            logger.debug(
                "main_ci_reclaim: no superseded main CI runs to reclaim this pass "
                "(tip=%s, checked=%d)",
                result.tip_sha,
                result.candidates_checked,
            )
            return

        with state_lock(state_file):
            state = load_state(state_file)
            state = self._record_event(
                state,
                "main_ci_reclaim_cancelled",
                {
                    "tip_sha": result.tip_sha,
                    "cancelled_run_ids": [run.run_id for run in result.cancelled],
                    "candidates_checked": result.candidates_checked,
                    "skipped_not_ancestor": result.skipped_not_ancestor,
                    "skipped_started_before_cancel": result.skipped_started_before_cancel,
                    "cancel_errors": list(result.cancel_errors),
                },
            )
            save_state(state_file, state)
        for run in result.cancelled:
            logger.info(
                "main_ci_reclaim: cancelled superseded main CI run %s "
                "(sha %s, was %s, created %s)",
                run.run_id,
                run.head_sha,
                run.status_before_cancel,
                run.created_at,
            )

    def _deescalate_mechanical_issue(self, issue_number: int) -> dict[str, Any]:
        """Re-evaluate one ``mechanical`` escalation and clear it if safe.

        Called only from ``_maybe_deescalate_mechanical`` for issues whose
        snapshot already matched the selection query (``status in
        ("escalated", "blocked")`` and ``reason_class == "mechanical"``).
        Every check here is re-run against FRESH state/GitHub data -- the
        snapshot may be stale by the time this runs (a concurrent
        ``charlie unescalate``, a re-escalation with a new reason, or a
        parallel loop lane already touched the entry).

        Always returns a dict, never ``None``. Returns
        ``{"skipped": "<reason>", "issue_number": ...}`` when the issue was
        left escalated -- the entry no longer qualifies, a worker is still
        live, no open PR is bound to the issue, or the fresh
        mergeable/janitor check failed (this is the expected, common
        outcome; the reason string is what the caller histograms into
        ``deescalation_pass_completed``, see ``_deescalation_skip``). Returns
        ``{"cap_exhausted": True, ...}`` the first time
        ``auto_deescalation_count`` has already reached
        ``config.deescalation.max_auto_deescalations``. Returns
        ``{"cleared": True, ...}`` after a successful auto-de-escalation.

        Issue #783 hazard (a) -- oscillation guard: ``auto_deescalation_count``
        is incremented here on every clear and is NEVER reset by this
        method -- only a human-invoked ``charlie unescalate`` resets it (see
        ``_UNESCALATE_ISSUE_RESET_FIELDS``). Once the count reaches
        ``max_auto_deescalations`` (default 2), this method permanently
        stops clearing that issue and instead emits
        ``deescalation_cap_exhausted`` exactly once (guarded by the
        ``deescalation_cap_notified_at`` marker, also reset only by
        ``unescalate()``). The issue stays on ``agent:human-needed`` --  this
        is a diagnosable terminal state (the event names the exhausted
        count), not a silent re-creation of the one-way door under a new
        name: a human is still required to re-arm it, exactly once more
        than before.

        Issue #783 hazard (b) -- unbounded paid-session loop: this method
        resets ONLY the per-mechanism attempt/cap counter that gates the
        CLEARED ``escalation_reason`` (see
        ``_REWORK_BUDGET_RESET_BY_ESCALATION_REASON``), and only once per
        escalation episode (tracked via ``rework_budget_reset_for_terminal_since``).
        It does NOT reset the other lanes' counters, nor the cross-lane
        bookkeeping that a full ``charlie unescalate`` clears
        (``redispatch_at``, ``review_dispatch_attempt_count``, etc.). If the
        same mechanical condition recurs after a clear, the lane's counter
        has been zeroed so the cap re-trips only after a fresh
        ``max_attempts``/``max_rework_cycles`` worth of completed-but-still-
        failing cycles, which re-escalates the issue through one of the
        S1-S14 call sites and re-enters this same accounting. That recurrence
        also consumes one more slot of ``auto_deescalation_count``, so the
        two counters compound: the mechanism-specific cap bounds how fast a
        single recurring failure can re-escalate, and
        ``auto_deescalation_count``'s cap independently bounds how many times
        this sweep will ever clear the SAME issue. The per-episode counter
        reset cannot unbound the loop because ``auto_deescalation_count``
        still caps total clears -- the sweep cannot re-dispatch a paid worker
        session more than ``max_auto_deescalations`` times for one recurring
        failure before falling permanently back to human review.

        A pre-PR dispatch failure (e.g. ``dispatch_failed_cap_exceeded`` --
        the launch never produced a PR at all) has no artifact AC3's
        "mergeable AND janitor_ok" can be checked against, so it is left
        untouched here (skip reason ``no_open_pr``) rather than guessed at; a
        human still recovers it via ``charlie unescalate --issue``.
        """
        # Issue #1327: under dry-run the paired GitHub label transition is
        # already gated at the sink, so the state.json write that records the
        # clear must be suppressed in lockstep -- otherwise a single dry-run
        # pass leaves state.json reporting the issue de-escalated while GitHub
        # still shows the ``escalated`` label. Returning a skip (rather than
        # proceeding and letting ``self.write_gate`` suppress each write)
        # also avoids pointless GitHub reads and a misleading ``cleared``
        # return value that would diverge from the (unwritten) state. The
        # write-gate routing below is the structural backstop for any future
        # caller that bypasses this guard.
        if self.dry_run:
            return _deescalation_skip("dry_run", issue_number)
        state = load_state_locked(self.paths.state_file)
        issue_key = str(issue_number)
        issue_entry = state.get("issues", {}).get(issue_key, {})
        if not isinstance(issue_entry, dict):
            return _deescalation_skip("invalid_issue_entry", issue_number)
        if issue_entry.get("status") not in ("escalated", "blocked"):
            # already resolved by something else since the snapshot
            return _deescalation_skip("not_escalated", issue_number)
        if issue_entry.get("reason_class") != "mechanical":
            # fail closed: judgment (or re-classified) since the snapshot
            return _deescalation_skip("not_mechanical", issue_number)

        max_auto = self.config.deescalation.max_auto_deescalations
        auto_count = int(issue_entry.get("auto_deescalation_count", 0) or 0)
        if auto_count >= max_auto:
            if issue_entry.get("deescalation_cap_notified_at"):
                # already reported once; do not re-notify every pass
                return _deescalation_skip("cap_already_notified", issue_number)
            with state_lock(self.paths.state_file):
                fresh_state = load_state(self.paths.state_file)
                fresh_entry = fresh_state["issues"].get(issue_key, {})
                if not isinstance(fresh_entry, dict) or fresh_entry.get(
                    "deescalation_cap_notified_at"
                ):
                    return _deescalation_skip("cap_notify_raced", issue_number)
                fresh_state["issues"][issue_key] = {
                    **fresh_entry,
                    "number": issue_number,
                    "deescalation_cap_notified_at": utc_now(),
                }
                fresh_state = self.write_gate.record_event(
                    fresh_state,
                    "deescalation_cap_exhausted",
                    {
                        "issue_number": issue_number,
                        "auto_deescalation_count": auto_count,
                        "max_auto_deescalations": max_auto,
                    },
                )
                self.write_gate.save_state(fresh_state)
            # Issue #1266: the auto-clearing sweep has given up on this
            # mechanical escalation -- move it off operator_queue onto
            # human_needed so a human actually sees it (operator_queue is
            # meant to be a self-clearing holding area, not a place a
            # capped-out issue silently stays forever). The "escalated" edge
            # already does this unconditionally: it adds human_needed and
            # strips every other workflow_labels member, operator_queue
            # included. Best-effort outside the lock, matching every other
            # label transition here -- the label-repair self-heal sweep
            # (_repair_escalated_labels) backstops a failed write, and it
            # correctly re-targets human_needed once reason_class stays
            # "mechanical" but this cap-exhaustion path has already run
            # (repair reads state fresh, not this function's return value).
            self.write_gate.transition(self.gh, self.config.labels, issue_number, "escalated")
            return {"cap_exhausted": True, "issue_number": issue_number}

        pr_number: int | None = None
        for key, entry in state.get("prs", {}).items():
            if (
                isinstance(entry, dict)
                and entry.get("issue_number") == issue_number
                and entry.get("status") not in ("merged", "closed")
                and key.isdigit()
            ):
                pr_number = int(key)
                break
        if pr_number is None:
            return _deescalation_skip("no_open_pr", issue_number)

        from .worker import issue_worker_liveness

        liveness = issue_worker_liveness(
            issue_number, issue_entry, self._layout.sessions_dir, self.config, datetime.now(UTC)
        )
        if liveness.live:
            # a live worker is using this issue; not stuck
            return _deescalation_skip("worker_live", issue_number)

        # Issue #849: a ``worktree_unsafe`` escalation is caused by bytes on
        # disk. Clearing it based on PR-level health (OPEN, not CONFLICTING,
        # janitor_ok) without inspecting the worktree reports success for an
        # operation that changed nothing causal — the next rework dispatch
        # reproduces the escalation deterministically. Re-run the safety
        # check and skip clearing while the worktree still fails it.
        # Issue #807: ``worktree_unsafe`` is split into
        # ``worktree_unsafe_shim_dirt`` and ``worktree_unsafe_local_commits``;
        # both are covered by ``WORKTREE_UNSAFE_KINDS`` so the safety re-check
        # fires for either kind.
        if issue_entry.get("escalation_reason") in WORKTREE_UNSAFE_KINDS:
            unsafe_reason = self._worktree_still_unsafe(issue_number, state)
            if unsafe_reason:
                return _deescalation_skip("worktree_still_unsafe", issue_number)

        pr = self.gh.pr_view(pr_number)
        pr_state_str = str(pr.get("state") or "").upper()
        # Mirror janitor._check_mergeable's own permissive definition of
        # "mergeable" exactly: it fails a PR only on the literal
        # "CONFLICTING" value and treats "UNKNOWN" (the common transient
        # value in the minutes after any push, before GitHub finishes
        # computing mergeability) or a missing field as passing. Requiring
        # an exact "MERGEABLE" match here would be a *stricter*, competing
        # definition of mergeable than the one the janitor gate itself uses
        # -- and would make this sweep silently inert on exactly the
        # freshly-pushed green PRs (#690/#699/#759) it exists to unblock.
        mergeable = str(pr.get("mergeable") or "").upper()
        checks = self.gh.pr_checks(pr_number)
        diff = self.gh.pr_diff(pr_number)
        pr_entry_for_janitor = state.get("prs", {}).get(str(pr_number))
        janitor_verdict = run_janitor(
            pr,
            checks,
            self.config,
            pr_state=pr_entry_for_janitor if isinstance(pr_entry_for_janitor, dict) else None,
            repo_root=self.repo_root,
            pr_diff=diff,
            review_decision=self._review_decision(pr_number),
        )

        with state_lock(self.paths.state_file):
            fresh_state = load_state(self.paths.state_file)
            fresh_pr_entry = fresh_state["prs"].get(str(pr_number))
            if isinstance(fresh_pr_entry, dict):
                # Visibility update mirrors review()'s escalated-PR early
                # return (workflow.py): the cached janitor fields stay fresh
                # even on a pass that does not end up clearing anything.
                fresh_state["prs"][str(pr_number)] = {
                    **fresh_pr_entry,
                    "janitor_ok": janitor_verdict.ok,
                    "janitor_failures": list(janitor_verdict.failures),
                    "is_missing_checks_only_block": janitor_verdict.is_missing_checks_only_block,
                }
            fresh_issue_entry = fresh_state["issues"].get(issue_key)
            if not isinstance(fresh_issue_entry, dict) or (
                fresh_issue_entry.get("status") not in ("escalated", "blocked")
                or fresh_issue_entry.get("reason_class") != "mechanical"
            ):
                # Changed concurrently since the snapshot (human unescalate,
                # re-escalation with a different reason_class, etc.) -- do
                # not act on stale intent.
                self.write_gate.save_state(fresh_state)
                return _deescalation_skip("changed_concurrently", issue_number)

            # Split from a single composite condition purely so each blocking
            # reason is attributable in the histogram -- the three checks below
            # are the same test, in the same order, with the same outcome. The
            # only ``skipped`` reason that means "the sweep works but the PR is
            # not ready" is ``janitor_blocked``; ``pr_not_open`` and
            # ``pr_conflicting`` mean the escalation should never have been a
            # sweep candidate at all.
            if pr_state_str != "OPEN":
                self.write_gate.save_state(fresh_state)
                return _deescalation_skip("pr_not_open", issue_number)
            if mergeable == "CONFLICTING":
                self.write_gate.save_state(fresh_state)
                return _deescalation_skip("pr_conflicting", issue_number)
            if not janitor_verdict.ok:
                self.write_gate.save_state(fresh_state)
                return _deescalation_skip("janitor_blocked", issue_number)

            cleared_condition = fresh_issue_entry.get("escalation_reason")
            cleared_auto_count = auto_count + 1
            # Issue #1093: reset the over-cap rework counter once per
            # escalation episode so the issue gets a fresh rework budget on
            # the first clear after an escalation.  ``terminal_since`` is
            # refreshed on every ``_escalate_issue`` call, so it identifies
            # the current episode; the marker records which episode was
            # last reset.  A re-escalation produces a new ``terminal_since``,
            # so the next clear resets again.  Repeated clears within the
            # same episode (same ``terminal_since``) do not re-reset.
            current_terminal_since = fresh_issue_entry.get("terminal_since")
            budget_reset_needed = (
                "rework_budget_reset_for_terminal_since" not in fresh_issue_entry
                or fresh_issue_entry.get("rework_budget_reset_for_terminal_since")
                != current_terminal_since
            )
            updated_issue_entry = {
                **fresh_issue_entry,
                "number": issue_number,
                "status": PASSIVE_OPEN_STATUS,
                "auto_deescalation_count": cleared_auto_count,
            }
            if budget_reset_needed:
                updated_issue_entry["rework_budget_reset_for_terminal_since"] = (
                    current_terminal_since
                )
            clear_escalation(updated_issue_entry)
            updated_issue_entry.pop("label_error", None)
            fresh_state["issues"][issue_key] = updated_issue_entry
            # Issue #1093: mirror-clear the PR record's escalation fields so
            # the rework router's short-circuit on
            # ``existing_pr_state.get("escalation_reasons_seen")`` (issue
            # #1461: was ``escalation_reason``) no longer fires after the
            # sweep clears the issue.  Also reset the per-mechanism
            # rework counter that ACTUALLY gates the cleared escalation_reason
            # on the open PR once per escalation episode -- resetting only
            # ``request_changes_count`` left the no_op/conflict lanes' real
            # gating counter untouched, so the router re-escalated on the next
            # detection.  See ``_REWORK_BUDGET_RESET_BY_ESCALATION_REASON``.
            clear_escalation_on_issue_prs(fresh_state, issue_number)
            if budget_reset_needed:
                fresh_pr = fresh_state["prs"].get(str(pr_number))
                if isinstance(fresh_pr, dict):
                    reset_spec = self._REWORK_BUDGET_RESET_BY_ESCALATION_REASON.get(
                        cleared_condition
                    )
                    if reset_spec is not None:
                        counter_field, companion_fields = reset_spec
                        fresh_pr[counter_field] = 0
                        for _field in companion_fields:
                            fresh_pr.pop(_field, None)
            fresh_state = self.write_gate.record_event(
                fresh_state,
                "deescalation_cleared",
                {
                    "issue_number": issue_number,
                    "pr_number": pr_number,
                    "reason_class": "mechanical",
                    "cleared_condition": cleared_condition,
                    "pr_mergeable": mergeable,
                    "janitor_ok": janitor_verdict.ok,
                    "auto_deescalation_count": cleared_auto_count,
                    "rework_budget_reset": budget_reset_needed,
                },
            )
            self.write_gate.save_state(fresh_state)

        result = self.write_gate.transition(
            self.gh, self.config.labels, issue_number, "unescalated_pr_open"
        )
        if result.outcome != TransitionOutcome.APPLIED:
            with state_lock(self.paths.state_file):
                fresh_state = load_state(self.paths.state_file)
                entry = fresh_state["issues"].get(issue_key, {})
                fresh_state["issues"][issue_key] = {
                    **(entry if isinstance(entry, dict) else {}),
                    "number": issue_number,
                    "label_error": {
                        "edge": "unescalated_pr_open",
                        "outcome": result.outcome.value,
                        "add_failures": result.add_failures,
                        "remove_failures": result.remove_failures,
                    },
                }
                self.write_gate.save_state(fresh_state)

        return {
            "cleared": True,
            "issue_number": issue_number,
            "pr_number": pr_number,
            "cleared_condition": cleared_condition,
        }

    def _backfill_missing_reason_classes(self, state: dict[str, Any]) -> dict[str, Any]:
        """One-way migration that gives legacy escalations a ``reason_class`` (issue #797).

        Escalations created before the ``reason_class`` field shipped carry no
        ``reason_class`` at all, so the de-escalation sweep cannot see them.
        ``events.db`` retains the original escalation-transition event for most
        of them; for each ``escalated``/``blocked`` issue that still lacks
        ``reason_class``, this helper looks up the most recent such event and
        derives the class from its kind.

        The mapping is deliberately conservative: only kinds that unambiguously
        indicate a process failure are mapped to ``"mechanical"``. Kinds in
        ``DELIBERATELY_UNCLASSIFIED_ESCALATION_EVENT_KINDS`` (e.g.
        ``janitor_rework_escalated``, a deliberately-preserved forensic record)
        are left untouched, so they stay terminal. No event, or an unknown
        kind, also stays fail-closed.

        Backfilling only writes ``reason_class``. It does not clear the
        escalation, does not reset ``auto_deescalation_count`` or any
        per-mechanism attempt counter, and emits exactly one
        ``deescalation_reason_class_backfilled`` event per issue so the
        migration is auditable. It is idempotent: once ``reason_class`` is
        present the issue is skipped.
        """
        all_source_kinds: frozenset[str] = (
            frozenset(ESCALATION_REASON_CLASS_BY_EVENT_KIND)
            | DELIBERATELY_UNCLASSIFIED_ESCALATION_EVENT_KINDS
        )
        for issue_key, issue in list(state.get("issues", {}).items()):
            if not isinstance(issue, dict):
                continue
            if issue.get("status") not in ("escalated", "blocked"):
                continue
            if "reason_class" in issue:
                continue
            if not issue_key.isdigit():
                continue
            issue_number = int(issue_key)

            events = query_events(
                self.paths.state_file,
                issue_number=issue_number,
            )
            escalation_events = [e for e in events if e["kind"] in all_source_kinds]
            if not escalation_events:
                continue
            latest = escalation_events[-1]
            reason_class = ESCALATION_REASON_CLASS_BY_EVENT_KIND.get(latest["kind"])
            if reason_class is None:
                continue

            issue = {
                **issue,
                "number": issue_number,
                "reason_class": reason_class,
            }
            state = {
                **state,
                "issues": {**state.get("issues", {}), issue_key: issue},
            }
            state = self.write_gate.record_event(
                state,
                "deescalation_reason_class_backfilled",
                {
                    "issue_number": issue_number,
                    "from_event_kind": latest["kind"],
                    "from_event_ts": latest["ts"],
                    "reason_class": reason_class,
                },
            )
        return state

    def _maybe_deescalate_mechanical(self) -> None:
        """Periodic sweep that re-evaluates ``mechanical`` escalations (issue #783).

        Escalation to ``agent:human-needed`` was a one-way door: four
        ``labels.py`` edges (``escalated``, ``blocked``, ``redispatch_escalated``,
        ``merged_pr_mention_flagged``) add the label; nothing in the automated
        loop ever removed it. All recovery went through the operator-invoked
        ``charlie unescalate`` command -- including for PRs whose underlying
        artifact was already fine (pushed, open, CI green, ``janitor_ok``) and
        whose escalation was purely a process failure (e.g. a rework worker's
        session dying -- ``session_failed_escalated``), not a human decision.

        This method is the automated re-entry point for exactly that
        process-failure class. It is scoped narrowly by construction:

        - Issues whose entry carries ``reason_class == "mechanical"`` --
          written atomically alongside every ``status -> escalated/blocked``
          transition at its call site (S1-S14 in the issue #783 implementation)
          -- are considered directly. ``judgment`` escalations stay terminal.
          A PRE-EXISTING escalation with no recorded ``reason_class`` (every
          escalation before issue #783 shipped) is first backfilled from its
          most recent escalation-transition event in ``events.db`` (issue #797):
          only kinds that unambiguously denote a process failure become
          ``mechanical``; ambiguous or unknown kinds, and issues with no event,
          stay fail-closed and invisible to the selection query.
        - Clearing additionally requires a live, freshly-fetched PR that is
          still OPEN, does not report ``mergeable == "CONFLICTING"`` (mirrors
          ``janitor._check_mergeable``'s own permissive definition exactly --
          a transient ``"UNKNOWN"`` value is not a conflict), and passes a
          freshly-computed ``run_janitor().ok`` -- reason-clearing alone
          (e.g. simply having a ``reason_class``) is never sufficient. See
          ``_deescalate_mechanical_issue`` for the full per-issue algorithm
          and this issue's two required hazard analyses (oscillation guard /
          unbounded-loop guard), both enforced there via
          ``auto_deescalation_count`` and by never resetting the original
          per-mechanism attempt counters.

        Two-phase lock pattern, mirroring ``_maybe_reconcile_drift``:
          1. Under our own (short) lock: decide whether this sweep is due at
             all, and take a snapshot of candidate issue numbers. If not
             due, return without calling out to GitHub.
          2. Outside any lock held by this method: process each candidate
             (``_deescalate_mechanical_issue`` acquires its own locks as
             needed, mirroring ``unescalate()``'s snapshot-then-reapply
             pattern so a slow ``gh`` call never holds the file lock).
          3. Under our own (short) lock again: persist the next-due
             timestamp and emit exactly one summary event for this pass.

        Wrapped in exception containment per-issue (one issue's failure must
        not sink the whole pass) AND around the snapshot/scheduling itself
        (mirroring ``_maybe_reconcile_drift``'s docstring: ``supervise.py``'s
        daemon loop has no outer per-pass exception boundary of its own, so
        an uncaught exception here would kill the daemon, not just this
        pass).
        """
        if not self.config.deescalation.enabled:
            return

        state_file = self.paths.state_file
        with state_lock(state_file):
            state = load_state(state_file)
            if not is_deescalation_due(state):
                return
            state = self._backfill_missing_reason_classes(state)
            self.write_gate.save_state(state)
            candidates = sorted(
                int(num)
                for num, entry in state.get("issues", {}).items()
                if isinstance(entry, dict)
                and entry.get("status") in ("escalated", "blocked")
                and entry.get("reason_class") == "mechanical"
                and str(num).isdigit()
            )

        next_deescalation_at = (
            (datetime.now(UTC) + timedelta(minutes=self.config.deescalation.interval_minutes))
            .replace(microsecond=0)
            .isoformat()
            .replace("+00:00", "Z")
        )

        cleared: list[dict[str, Any]] = []
        cap_exhausted: list[int] = []
        errors: list[dict[str, Any]] = []
        skipped: Counter[str] = Counter()
        for issue_number in candidates:
            try:
                outcome = self._deescalate_mechanical_issue(issue_number)
            except Exception as exc:  # noqa: BLE001 - containment is deliberate; see docstring
                errors.append(
                    {"issue_number": issue_number, "error": f"{type(exc).__name__}: {exc}"}
                )
                continue
            if outcome.get("cap_exhausted"):
                cap_exhausted.append(issue_number)
            elif outcome.get("cleared"):
                cleared.append(outcome)
            else:
                # ``unknown`` is unreachable via ``_deescalation_skip`` (which
                # always sets a reason); it exists so a future outcome shape
                # that is neither cleared nor cap-exhausted still lands in the
                # histogram as a countable bucket instead of vanishing.
                skipped[str(outcome.get("skipped") or "unknown")] += 1

        with state_lock(state_file):
            state = load_state(state_file)
            state = arm_deescalation_pass(state, next_deescalation_at)
            state = self.write_gate.record_event(
                state,
                "deescalation_pass_completed",
                {
                    "candidates": len(candidates),
                    "cleared": cleared,
                    "cap_exhausted": cap_exhausted,
                    # Attribution for the difference between ``candidates`` and
                    # everything else in this payload. Before issue #1090 that
                    # difference was silent: a sweep that considered 29 issues
                    # and cleared none emitted the same event as a sweep with
                    # no candidates at all, so "the sweep is inert" and "the
                    # sweep ran and every PR was legitimately blocked" were
                    # indistinguishable from events.db alone. Sorted for a
                    # stable diff across passes.
                    "skipped": dict(sorted(skipped.items())),
                    "errors": errors,
                },
            )
            self.write_gate.save_state(state)

    def _maybe_emit_operator_queue_depth(self) -> None:
        """Emit the ``operator_queue_depth`` gauge event when depth exceeds threshold.

        Issue #1314 item 3. The operator-queue depth gauge makes a silently
        growing queue of mechanical escalations visible in ``events.db``
        rather than only via GitHub label queries. The gauge is checked
        every loop pass (or on the dedicated
        ``operator_queue_review_interval_minutes`` cadence if configured),
        and the ``operator_queue_depth`` warning event is emitted only when
        the depth exceeds the configured ``operator_queue_depth_threshold``
        -- the same "checked every pass, emitted only when the condition
        holds" pattern ``dispatch_stale`` uses.

        The consumer is ``heartbeat_check.py``'s ``check_warning_events``,
        which buckets the kind (registered in
        ``EXPECTED_OPERATIONAL_KINDS``) into a summarized count so a
        chronically deep queue does not drown out genuinely rare warnings.
        That bucketing wiring lands in the same PR as the signal, per the
        signal-without-a-consumer rule.

        Threshold 0 disables the alert entirely (no event emitted regardless
        of depth), preserving the pre-feature silent-queue behavior for
        fleets that have not yet opted in.

        ``dry_run`` short-circuits the entire gauge before any lock or state
        read: the gauge emits a warning event and persists the
        ``next_operator_queue_review_at`` arm timestamp via a raw
        ``save_state`` (outside WriteGate), so running it under
        ``dry_run=True`` would both leak an ``operator_queue_depth`` row into
        ``events.db`` and mutate ``state.json`` -- violating the C1.2
        "byte-identical to a pass that never ran" dry-run invariant
        (``test_loop_wrapper_telemetry_is_the_only_delta_under_dry_run_true``
        pins that invariant; its fixture has zero escalated issues, so it
        only exercises the depth<=threshold early return and would not catch
        a deep-queue dry-run leak on its own). The guard is at the top rather
        than after the threshold check so a dry-run pass pays neither the
        lock acquisition nor the state load.
        """
        if self.dry_run:
            return
        threshold = self.config.deescalation.operator_queue_depth_threshold
        if threshold <= 0:
            return

        state_file = self.paths.state_file
        review_interval = self.config.deescalation.operator_queue_review_interval_minutes
        with state_lock(state_file):
            state = load_state(state_file)
            if review_interval > 0 and not is_operator_queue_review_due(state):
                return
            depth_set = operator_queue_depth(state)
            depth = len(depth_set)
            if depth <= threshold:
                return
            next_review_at = (
                (datetime.now(UTC) + timedelta(minutes=review_interval))
                .replace(microsecond=0)
                .isoformat()
                .replace("+00:00", "Z")
            )
            state = arm_operator_queue_review(state, next_review_at)
            state = self._record_event(
                state,
                "operator_queue_depth",
                {
                    "depth": depth,
                    "threshold": threshold,
                    "issue_numbers": sorted(depth_set),
                },
            )
            save_state(state_file, state)

    def _loop_body(
        self, limit: int | None, *, merge: bool | None, now: datetime | None = None
    ) -> CommandResult:
        # Every pass must observe a fresh GitHub snapshot. The list cache
        # dedupes calls within one pass, but a long-running supervisor
        # (charlie fleet supervise) reuses this app -- and therefore one
        # GitHub instance -- across many passes; without this, issues filed
        # or PRs opened after the first pass stay invisible until the daemon
        # restarts (observed live: intake frozen at a stale issue set for the
        # daemon's entire lifetime).
        self.gh.invalidate_list_cache()
        sessions_dir = self._layout.sessions_dir
        # Issue #646: the worker census now logs from inside dispatch() itself
        # (the one chokepoint every dispatch path funnels through, including
        # standalone `work`/`fleet work` which never reach this method) --
        # see dispatch()'s docstring. Not re-logged here to avoid a duplicate
        # census line within the same pass.
        # Unconditional sweep: reap stalled/orphaned sessions even when this pass
        # has zero ready/rework candidates and never reaches dispatch()'s reaper call.
        # The result is handed down to dispatch_rework()/dispatch() below so the
        # sweep runs exactly once per pass — it is the sole writer of Signal-1's
        # inconclusive-probe deferral counter, and re-running it inside each
        # dispatch lane advanced the counter up to 3x per pass, collapsing the
        # max_inconclusive_probe_deferrals "N passes of grace" into a single pass
        # (issue #343 Finding 2).
        # now=now (issue #828): forward this pass's clock so the reaper's
        # rate-limit-defer classification shares one sample with the other
        # cadence-gated lanes below instead of re-sampling independently.
        loop_stalled_entries = _detect_and_handle_stalled_sessions(
            sessions_dir,
            self.paths.state_file,
            self.config,
            write_gate=self.write_gate,
            now=now,
        )
        intake = self.intake()
        # Share a single wave budget between fresh and rework dispatch
        # Rework-first, then fresh fills the remainder
        # Resolve the effective budget once
        effective_limit = limit if limit is not None else self.config.dispatch.default_limit

        # Apply global concurrency governor cap to the total wave budget
        gov = self._apply_concurrency_governor(effective_limit)
        effective_limit = gov.dispatch_limit

        # Classify dead sessions and update throttle state (production loop path)
        # This detects provider throttling from worker deaths and sets cooldown
        # Also reconciles labels for dead sessions with no open PR (issue #118)
        sessions_dir = self._layout.sessions_dir
        # Issue #343 Finding 2: the stall lane at the top of this method
        # (line ~4100) already ran this pass and is the sole writer of the
        # inconclusive-probe deferral counter for a not-alive worker -- tell
        # this lane not to persist it again on top of that write.
        reaped = _classify_dead_sessions_and_update_throttle_state(
            sessions_dir,
            self.paths.state_file,
            self.gh,
            self.config,
            write_gate=self.write_gate,
            persist_inconclusive_probe_counter=False,
            now=now,
            fleet_dir_override=self.fleet_dir_override,
        )

        # Flat-interval Haiku probe for early quota/rate-limit recovery (see
        # docstring): only does real work when a throttle indicator is active.
        # `now` (issue #828) is this pass's single injected clock, forwarded
        # so the probe's own cadence-scheduling samples stay consistent with
        # the rest of this pass instead of independently racing wall clock.
        self._maybe_probe_quota_recovery(now=now)

        # Periodic in-loop reconcile (merge-lane-recovery §6-B): repairs
        # GitHub label / state.json divergence on a fixed cadence instead of
        # only when an operator runs `charlie mop-up --fix`. Placed before
        # the dispatch calls below so labels it repairs (e.g. a stale
        # `needs-rework` on an issue state already marked `escalated`) are
        # visible to this same pass's dispatch decisions, not just the next.
        self._maybe_reconcile_drift(now=now)

        # Issues #863/#815: reclaim superseded, not-yet-started main CI runs
        # every pass -- no runner needed, so unlike the workflow-based
        # reaper this cannot lose the race for the capacity it exists to
        # free. See _maybe_reclaim_superseded_main_ci's docstring.
        self._maybe_reclaim_superseded_main_ci()

        # Issue #783: periodic re-evaluation of `mechanical` escalations --
        # the only automated re-entry from `agent:human-needed` for pure
        # process failures (a dead rework worker, a redispatch cap, a
        # stalled janitor-gate rework, ...) whose underlying PR artifact has
        # since become mergeable and janitor-clean. `judgment` escalations
        # and any pre-existing escalation with no recorded reason_class are
        # untouched by construction (see _maybe_deescalate_mechanical).
        self._maybe_deescalate_mechanical()

        # Sweep for orphan processes in dead session worktrees (issue #139)
        # This catches detached/daemonized processes that survived session kills
        _sweep_orphan_processes_for_dead_sessions(
            sessions_dir, self.paths.state_file, self.config, write_gate=self.write_gate
        )

        # Detect and handle orphaned workers using state.json PID records (issue #207)
        # This fallback detects dead workers even when session sidecar files are orphaned.
        # Pass the review callback so a head-advanced request_changes finding can be
        # routed to the review-pending path instead of being re-emitted as drift.
        _detect_and_handle_orphaned_workers(
            sessions_dir,
            self.paths.state_file,
            self.config,
            self.gh,
            write_gate=self.write_gate,
            review_callback=self.review,
            fleet_dir_override=self.fleet_dir_override,
        )

        # Detect stalled sessions for notification (read-only, stateful via _build_attention_digest)
        stalled_entries = _detect_stalled_sessions(sessions_dir, self.config)
        health_transitions: dict[int, dict[str, Any]] = {}
        for entry in stalled_entries:
            health_transitions[entry["issue"]] = {
                "adapter_kind": "unknown",  # Will be filled by #165's full supervisor
                "health": entry.get("health", "STALLED"),
                "last_log_line": None,
                "pid": entry.get("pid"),
                "terminal_tool": entry.get("terminal_tool"),
                "terminal_reason": entry.get("terminal_reason"),
            }

        # Issue #706: feed reaped dead-session transitions into the notify
        # digest. ``_detect_stalled_sessions`` is gated on
        # ``watchdog.enabled`` (it returns ``[]`` immediately when watchdog is
        # off), so a deployment that disables watchdog -- e.g. to work around
        # a shim log-mtime blindness, as job-cannon does -- gets zero stalled
        # entries and the notify sink never fires, even though dead workers
        # ARE reaped by ``_classify_dead_sessions_and_update_throttle_state``
        # above (which is NOT watchdog-gated; see issue #1122). Without this,
        # an operator monitoring ``notify/digest.jsonl`` gets zero signal
        # silently -- the exact symptom in #706. ``setdefault`` preserves any
        # stalled transition already recorded for the same issue (the stall
        # lane's post-mortem terminal_tool/terminal_reason are richer than the
        # reaped entry's failure_kind); in practice the two are mutually
        # exclusive (a session is either alive-stalled or dead-reaped, not
        # both), so this only fills in for sessions the watchdog-gated
        # read-only detection skipped.
        for reaped_entry in reaped:
            reaped_issue = reaped_entry.get("issue_number")
            if reaped_issue is None:
                continue
            health_transitions.setdefault(
                reaped_issue,
                {
                    "adapter_kind": reaped_entry.get("adapter_kind", "unknown"),
                    "health": "DEAD",
                    "last_log_line": None,
                    "pid": reaped_entry.get("pid"),
                    "terminal_tool": None,
                    "terminal_reason": reaped_entry.get("failure_kind"),
                },
            )

        # Emit notification digest if there are health transitions
        if health_transitions and self.config.notify.enabled:
            digest = _build_attention_digest(
                self.paths.state_file,
                health_transitions,
                repo=self.repo_root.name,
            )
            if digest:
                emit_digest(self._layout.notify, digest)

        dispatch_rework = self.dispatch_rework(
            effective_limit, stalled_entries=loop_stalled_entries
        )
        rework_count = dispatch_rework.data.get("selected_count", 0)
        fresh_limit = max(0, effective_limit - rework_count)
        dispatch = self.dispatch(fresh_limit, stalled_entries=loop_stalled_entries)

        # Issue #370: launch reviewers for queued PRs. This runs after worker
        # dispatch so a completed worker's review packet can be picked up by the
        # same loop pass only if the reviewer finishes immediately (tests); in
        # production the per-PR merge lane below fires on the next poll.
        # `now` (issue #822/#828) is this pass's injectable clock, threaded
        # through so dispatch_reviews's is_claim_stale checks share the same
        # instant as the rest of this pass instead of resampling.
        dispatch_reviews = self.dispatch_reviews(now=now)

        # Auto-record cross-family verdicts for pending PRs when the
        # cross-family pass is the sole automated review (review_dispatch
        # disabled). Without this, PRs with valid cross-family reports but
        # no recorded verdict pile up in "reviewing" status forever.
        if not self.dry_run:
            self._record_cross_family_verdicts()

        reviews: list[dict[str, Any]] = []
        merges: list[dict[str, Any]] = []
        errors: list[dict[str, Any]] = []

        # Issue #502: post-merge tripwire. Detect any merged worker PR that was
        # not approved by the orchestrator's adversarial review gate.
        #
        # Reuse the merged PR list already fetched by dispatch() to avoid a
        # redundant fetch per loop pass. dispatch() returns an empty list (not
        # the fetched merged PRs) when there are no ready issues, so coerce an
        # empty reuse list back to None — the tripwire must then fetch its own
        # list to stay armed even when the queue is idle (a worker self-merge can
        # land regardless of whether issues are ready).
        #
        # Deliberate trade-off: because empty-means-unknown is indistinguishable
        # from empty-means-no-merged-PRs, an idle queue costs one extra
        # merged_pr_list() call per pass. That is a paginated REST fetch, not a
        # GraphQL check-run walk (merged_pr_list is REST-only by construction —
        # issue #361), so the cost is bounded and does not risk the gateway 502s
        # that motivated #361. Staying armed while idle is worth it: the whole
        # point of the tripwire is to catch merges the orchestrator did not
        # perform, which are exactly the ones that can happen on a quiet pass.
        # Replacing this with an explicit "not fetched" sentinel threaded out of
        # dispatch() would remove the extra call; that is tracked in #446 with
        # the rest of the per-pass fetch consolidation, and is deliberately not
        # done here to keep this security fix narrow.
        merged_prs_for_tripwire: list[dict[str, Any]] | None = dispatch.data.get("merged_prs")
        if not merged_prs_for_tripwire:
            merged_prs_for_tripwire = None
        for unauthorized in self._detect_unauthorized_merges(merged_prs_for_tripwire):
            reviewed_sha = unauthorized.get("reviewed_head_sha")
            live_sha = unauthorized.get("live_head_sha")
            if (
                unauthorized["decision"] == "approved"
                and reviewed_sha is not None
                and live_sha is not None
                and reviewed_sha != live_sha
            ):
                reason = f"approved for head {reviewed_sha!r} but merged head is {live_sha!r}"
            else:
                reason = (
                    f"without an approved review decision (decision={unauthorized['decision']!r})"
                )
            errors.append(
                {
                    "pr": unauthorized["pr"],
                    "issue": unauthorized["issue"],
                    "error": (
                        f"PR #{unauthorized['pr']} ({unauthorized['head']}) is MERGED "
                        f"{reason}; possible worker self-merge"
                    ),
                }
            )

        foreign_transitions: dict[int, dict[str, Any]] = {}
        open_tracked_prs = 0
        skipped_reviews = 0
        prs = self.gh.pr_list()
        # Snapshot for foreign-PR markers only: markers change at most once
        # per PR, so a single point-in-time read at loop start is sufficient.
        state_snapshot = load_state_locked(self.paths.state_file)
        merge_train_head = (
            self._merge_train_head(prs)
            if self.config.auto_merge.update_branch_strategy == "front_of_train"
            else None
        )
        for pr in prs:
            issue_number = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if issue_number is None:
                continue
            pr_number = int(pr["number"])
            parked = (state_snapshot["prs"].get(str(pr_number)) or {}).get(
                "foreign_issue_ref"
            ) or {}
            if parked.get("issue") == issue_number:
                # Foreign/unlinked PR: its claimed issue does not exist in this
                # repo (e.g. opened against the wrong fleet repo). Skip all
                # per-PR work with zero GitHub calls until the marker is
                # cleared or the PR's linked-issue ref changes.
                continue
            # Count every PR with a resolvable linked issue (includes skipped ones)
            open_tracked_prs += 1
            is_merge_head = merge_train_head is None or pr_number == merge_train_head
            # Per-PR isolation: one PR's merge conflict or gh failure must not
            # abort review/merge of every remaining PR in the batch.
            try:
                # Idempotence: if the PR already has an approved decision in
                # state and isn't in a rework/blocked state, skip the expensive
                # review() pass (packet regeneration + label transitions) and
                # go straight to merge_ready. This prevents a second loop() pass
                # from rewriting the review packet or re-firing labels for a PR
                # that's simply waiting on pending checks.
                state = load_state_locked(self.paths.state_file)
                pr_state = state["prs"].get(str(pr_number), {})
                pr_dir_for_decision = self.paths.prs / f"pr-{pr_number}"
                live_head_sha = pr.get("headRefOid")
                # Issue #1362 Stage 1 (#1340 regression): the FILE is
                # authoritative for the decision itself -- state.json's
                # ``decision`` can lag a concurrent void/record_review (the
                # #1340 shape: state still says "approved" at an old head
                # while the file has already been reset to "pending").
                # ``status`` is a distinct workflow-state field, not one of
                # the three decision stores, so it still reads pr_state.
                resolved_decision = review_decision(pr_dir_for_decision, None, live_head_sha)
                # Issue #1362 Stage 3: state.json's decision fields are a
                # declared cache of the file, refreshed here at the start of
                # this PR's evaluation so any OTHER reader of ``state["prs"]``
                # later in this same pass (merge_ready, janitor, the reap
                # sweep, ...) sees a current decision/reviewed_head_sha/
                # decision_path without waiting for one of the four writer-
                # adjacent mirrors. Never touches ``status`` (checked just
                # below), so the already-loaded ``pr_state`` stays valid.
                self._refresh_pr_decision_cache(
                    pr_number,
                    resolved_decision,
                    pr_dir_for_decision / "review-decision.json",
                )
                already_approved = resolved_decision.decision == "approved" and pr_state.get(
                    "status"
                ) not in ("request_changes", "escalated", "blocked")
                if already_approved:
                    # ``resolved_decision.stale`` already encodes exactly the
                    # reviewed-head-vs-live-head comparison ``head_matches``
                    # used to hand-roll.
                    head_matches = not resolved_decision.stale
                    if head_matches and is_merge_head:
                        merge_result = self.merge_ready(
                            pr_number, merge=merge, merge_train_head=merge_train_head
                        )
                        self._record_merge_or_error(merge_result, errors, merges)
                    elif not head_matches:
                        review = self.review(pr_number)
                        if self._record_review_or_error(review, errors, reviews):
                            continue
                        # Issue #1078: if the cross-family review is pending,
                        # review() returned without writing a packet or resetting
                        # the decision. The old head's "approved" decision must
                        # NOT trigger a merge for the new head — skip to the next
                        # PR and let a later pass reap the review and rebuild.
                        if review.data.get("cross_family_pending"):
                            continue
                        post_review_decision = review_decision(
                            pr_dir_for_decision, None, pr.get("headRefOid")
                        )
                        if (
                            post_review_decision.decision == "approved"
                            and not post_review_decision.stale
                            and is_merge_head
                        ):
                            merge_result = self.merge_ready(
                                pr_number, merge=merge, merge_train_head=merge_train_head
                            )
                            self._record_merge_or_error(merge_result, errors, merges)
                else:
                    # Same-head packet skip: if we already have a review packet
                    # for this exact head SHA and no decision has been recorded
                    # yet, skip regenerating the packet. This prevents repeated
                    # supervised passes from re-firing review_started transitions
                    # and regenerating packets every poll cycle while the operator
                    # is still reading. The packet remains current; verdict file
                    # appearance triggers a delta → the merge lane fires normally.
                    #
                    # Issue #592: the prompt template is as load-bearing an
                    # input to the packet as the head SHA. A template edit
                    # must reach static-head PRs, otherwise reviewers keep
                    # receiving a packet rendered from the old template and
                    # fail identically until they escalate. Treat a digest
                    # mismatch as staleness alongside a head mismatch. A
                    # missing digest is a legacy packet (pre-#592); treat it
                    # as current so the upgrade does not force a one-time
                    # fleet-wide regeneration burst -- packets rendered after
                    # this fix always carry the digest.
                    live_head_sha = pr.get("headRefOid")
                    packet_head_sha = self._read_packet_head_oid(pr_number)
                    head_current = (
                        live_head_sha is not None
                        and packet_head_sha is not None
                        and live_head_sha == packet_head_sha
                    )
                    current_template_sha = self._review_template_sha()
                    packet_template_sha = self._read_packet_template_sha(pr_number)
                    template_current = packet_template_sha is None or (
                        packet_template_sha == current_template_sha
                    )
                    # Issue #1081: the cross-family report is a third
                    # load-bearing input to the packet. An unusable one (a
                    # "(UNAVAILABLE)" failure stub, or one carrying no head
                    # SHA) can never yield a verdict, and on a PR whose head
                    # never moves the two checks above skip review() forever --
                    # so the regeneration that _cross_family_for_pr already
                    # performs was unreachable and the PR waited on a human
                    # indefinitely. Regeneration is still bounded per head, but
                    # the bound is claimed by the regenerator itself, not here
                    # -- this call only asks a question (issue #1099).
                    cross_family_current = self._cross_family_report_current(
                        pr=pr, pr_number=pr_number
                    )
                    if head_current and template_current and cross_family_current:
                        # Packet is current — skip regenerating it. The
                        # already_approved branch above is evaluated earlier
                        # in this same pass and may not see a decision file an
                        # operator wrote after that check ran, so the verdict
                        # would otherwise stay invisible until the head moves.
                        # Re-check the decision file here and proceed to merge
                        # on approval, same as the decided path.
                        skipped_reviews += 1
                        packet_skip_decision = review_decision(
                            pr_dir_for_decision, None, pr.get("headRefOid")
                        )
                        if (
                            packet_skip_decision.decision == "approved"
                            and not packet_skip_decision.stale
                            and is_merge_head
                        ):
                            merge_result = self.merge_ready(
                                pr_number, merge=merge, merge_train_head=merge_train_head
                            )
                            self._record_merge_or_error(merge_result, errors, merges)
                    else:
                        # Issue #1338: an escalated PR's packet regeneration is
                        # unreachable -- review() early-returns "escalated;
                        # review skipped" before its regen path -- so the
                        # staleness WARNING below would re-emit an identical
                        # review_packet_template_stale event every pass without
                        # ever converging, and the cross-family regen-budget
                        # charge (attempts_before /
                        # _charge_cross_family_regen_not_reached) would bill a
                        # regen that was deliberately not run. Escalation means
                        # "awaiting a human", and the recovery procedure
                        # (unescalate + why-charlie-hate) already regenerates
                        # the packet with the current template, so skip ONLY
                        # those two meaningless side effects while escalated.
                        #
                        # self.review(pr_number) is still called: its own
                        # _escalation_flags entry gate no-ops packet regen and
                        # label transitions, but it is the ONLY per-pass path
                        # that refreshes janitor_ok/janitor_failures/
                        # ci_run_never_created and runs the #776
                        # merge-conflict/no-op-rework remediation for
                        # judgment-class escalations (PRs #1397/#1443). Skipping
                        # it entirely would reintroduce the exact frozen-
                        # diagnostics staleness class the job-cannon fix
                        # addressed, just via a different trigger. A
                        # non-escalated stale-template PR still regenerates
                        # exactly as today (#592 preserved).
                        issue_state_for_esc = (
                            state.get("issues", {}).get(str(issue_number), {})
                            if issue_number is not None
                            else None
                        )
                        pr_escalated_now, issue_escalated_now = _escalation_flags(
                            pr_state, issue_state_for_esc
                        )
                        escalated_now = pr_escalated_now or issue_escalated_now
                        # Emit a distinct event when regeneration fires
                        # because the template changed while the head stayed
                        # put, so a fleet-wide template edit is visible as a
                        # burst rather than unexplained review churn. Suppressed
                        # while escalated (#1338): the regen is unreachable, so
                        # the WARNING would fire identically every pass without
                        # converging.
                        if head_current and not template_current and not escalated_now:
                            log_event(
                                self.paths.state_file,
                                "review_packet_template_stale",
                                {
                                    "pr_number": pr_number,
                                    "issue_number": issue_number,
                                    "packet_template_sha": packet_template_sha,
                                    "current_template_sha": current_template_sha,
                                },
                                repo=self.repo_root.name,
                            )
                        # Sampled BEFORE review() so the charge below can tell
                        # "the regenerator never ran" from "it ran and failed".
                        # After the fact the two are indistinguishable from the
                        # report alone -- both leave it unusable (issue #1099).
                        # While escalated the charge is skipped (#1338), so the
                        # sample is unused -- fold escalated_now into the
                        # early-zero to avoid a pointless regen-record read.
                        attempts_before = (
                            0
                            if escalated_now or cross_family_current
                            else int(
                                self._cross_family_regen_record(
                                    pr_number=pr_number, head_sha=live_head_sha
                                ).get("attempts")
                                or 0
                            )
                        )
                        review = self.review(pr_number)
                        if (
                            not escalated_now
                            and not cross_family_current
                            and not review.data.get("cross_family_pending")
                        ):
                            # review() has now run for the express purpose of
                            # regenerating this report. If it is still unusable
                            # and no attempt was charged, the regenerator was
                            # never reached (issue #1099). The
                            # ``cross_family_pending`` guard (#1078) excludes
                            # the case where the regenerator WAS reached — it
                            # launched the async review — but the report is not
                            # yet written because the subprocess is still running.
                            # Suppressed while escalated (#1338): review()'s
                            # own entry gate no-ops the regen, so charging a
                            # not-reached regen here would bill work that was
                            # deliberately not run.
                            self._charge_cross_family_regen_not_reached(
                                pr_number=pr_number,
                                issue_number=issue_number,
                                head_sha=live_head_sha,
                                attempts_before=attempts_before,
                            )
                        if self._record_review_or_error(review, errors, reviews):
                            continue
                        # Issue #1078: same guard as the already_approved branch
                        # above — a pending cross-family review means no packet
                        # was written, so any existing decision is stale.
                        if review.data.get("cross_family_pending"):
                            continue
                        decision = self._review_decision(pr_number)
                        if decision.get("decision") == "approved" and is_merge_head:
                            merge_result = self.merge_ready(
                                pr_number, merge=merge, merge_train_head=merge_train_head
                            )
                            self._record_merge_or_error(merge_result, errors, merges)
            except GitHubNotFoundError as exc:
                # Permanent: the PR's claimed issue (or another object it
                # references) does not exist in this repo. Park it durably and
                # alert once instead of failing the pass every 5 minutes
                # forever — retrying can never succeed.
                log_event(
                    self.paths.state_file,
                    # event-consumer: audit-only -- handled inline via _mark_foreign_issue_ref
                    # below (parked durably, alerted once); no separate downstream consumer needed
                    "github_not_found_error",
                    {"pr_number": pr_number, "issue_number": issue_number, "error": str(exc)},
                    repo=self.repo_root.name,
                )
                if self._mark_foreign_issue_ref(pr_number, issue_number, str(exc)):
                    foreign_transitions[pr_number] = {
                        "adapter_kind": "unknown",
                        "health": "FOREIGN_ISSUE_REF",
                        "last_log_line": str(exc),
                        "terminal_reason": (
                            f"linked issue #{issue_number} not found in this repo; "
                            f"PR #{pr_number} parked until the marker is cleared"
                        ),
                    }
            except GitHubError as exc:
                log_event(
                    self.paths.state_file,
                    "github_error",
                    {"pr_number": pr_number, "issue_number": issue_number, "error": str(exc)},
                    repo=self.repo_root.name,
                )
                errors.append({"pr": pr_number, "error": str(exc)})
        warnings: list[str] = []
        merge_alert_transitions: dict[int, dict[str, Any]] = {}
        for merge_entry in merges:
            warning = merge_entry.get("merge_attempt_warning")
            if warning:
                warnings.append(warning)
            if merge_entry.get("merge_attempt_alarm") and merge_entry.get("issue") is not None:
                issue = merge_entry["issue"]
                merge_alert_transitions[issue] = {
                    "adapter_kind": "unknown",
                    "health": "MERGE_BLOCKED",
                    "last_log_line": None,
                    "pid": None,
                    "terminal_tool": None,
                    "terminal_reason": warning,
                }

        # Emit a merge-lane alert digest when a PR crosses the threshold.
        if merge_alert_transitions and self.config.notify.enabled:
            digest = _build_attention_digest(
                self.paths.state_file,
                merge_alert_transitions,
                repo=self.repo_root.name,
                state_field="merge_alert",
            )
            if digest:
                emit_digest(self._layout.notify, digest)

        # One-shot alert for newly parked foreign PRs. Dedupe comes from the
        # durable state marker (_mark_foreign_issue_ref returns True exactly
        # once per (pr, issue) pair), so this digest is built directly rather
        # than through the per-issue health-baseline machinery.
        if foreign_transitions and self.config.notify.enabled:
            emit_digest(
                self._layout.notify,
                AttentionDigest(
                    generated_at=utc_now(),
                    repo=self.repo_root.name,
                    transitions=tuple(
                        AttentionEntry(
                            issue_number=pr_num,
                            adapter_kind=t["adapter_kind"],
                            health=t["health"],
                            previous_health=None,
                            last_log_line=t["last_log_line"],
                            pid=None,
                            terminal_tool=None,
                            terminal_reason=t["terminal_reason"],
                        )
                        for pr_num, t in foreign_transitions.items()
                    ),
                ),
            )

        ok = (
            intake.ok and dispatch.ok and dispatch_rework.ok and dispatch_reviews.ok and not errors
        )
        message = "loop complete"
        if errors:
            message = f"loop completed with {len(errors)} PR error(s)"
        elif not intake.ok:
            message = "loop completed with intake failures"
        elif not dispatch.ok:
            message = dispatch.message
        elif not dispatch_rework.ok:
            message = dispatch_rework.message
        elif not dispatch_reviews.ok:
            message = "loop completed with review dispatch failures"
        data = {
            "intake": intake.data,
            "dispatch": dispatch.data,
            "dispatch_rework": dispatch_rework.data,
            "dispatch_reviews": dispatch_reviews.data,
            "reviews": reviews,
            "merges": merges,
            "errors": errors,
            "warnings": warnings,
            "open_tracked_prs": open_tracked_prs,
            "skipped_reviews": skipped_reviews,
            "reaped": reaped,
        }
        # Propagate concurrency info from dispatch results
        if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
            data.update(gov.report_fields())
        # Prefer the dispatch-scoped governor values (they reflect sidecars
        # written by this pass and the most accurate fleet-wide live count).
        for lane in ("dispatch", "dispatch_rework"):
            for key in (
                "concurrency_limit",
                "live_session_count",
                "available_slots",
                "fleet_concurrency_limit",
                "fleet_live_session_count",
                "open_pr_count",
                "open_pr_max",
            ):
                if key in data[lane]:
                    data[key] = data[lane][key]
        # Cadence-gated merged-PR worktree reclamation (issue #636). Runs at
        # the END of the pass so the per-candidate `gh pr view` fan-out never
        # contends with the dispatch/review/merge lanes for state_lock or
        # GitHub quota during the critical window. Gated by
        # worktree_reclamation.interval_minutes, so it fires at most once per
        # interval regardless of poll frequency or backlog size. `now`
        # (issue #828) is this pass's single injected clock -- see
        # `_loop_body`'s other cadence-gated calls above.
        reclamation = self._maybe_reclaim_worktrees(now=now)
        if reclamation is not None:
            data["worktrees_reclaimed"] = reclamation
        return CommandResult(
            ok,
            message,
            data,
        )

    def dispatch_rework(
        self,
        limit: int | None = None,
        *,
        only_issues: str | None = None,
        stalled_entries: list[dict[str, int]] | None = None,
    ) -> CommandResult:
        """Dispatch rework workers for issues in needs-rework state with open PRs.

        ``stalled_entries``: pass the result of an already-completed
        ``_detect_and_handle_stalled_sessions`` sweep to skip re-running the
        sweep inside this call — same contract as ``dispatch()`` (issue #343
        Finding 2: the sweep writes Signal-1's inconclusive-probe deferral
        counter, so it must run at most once per pass). Standalone callers
        leave this as None and the sweep runs inside this call as before.
        """
        fleet_lock = None
        if self.config.fleet.global_max_concurrent_sessions > 0:
            fleet_lock = try_acquire_fleet_lock(self.fleet_dir_override)
            if fleet_lock is None:
                return CommandResult(
                    True,
                    "rework dispatch deferred: fleet lock held",
                    {
                        "adapter": self.config.devin.adapter,
                        "selected_count": 0,
                        "deferred_reason": "fleet_lock_held",
                    },
                )
        try:
            return self._dispatch_rework_impl(
                limit, only_issues=only_issues, stalled_entries=stalled_entries
            )
        except StateLockBusy:
            return _state_lock_busy_result(
                "rework dispatch deferred: state lock held",
                adapter=self.config.devin.adapter,
                selected_count=0,
                deferred_reason="state_lock_busy",
            )
        finally:
            if fleet_lock is not None:
                fleet_lock.release()

    def _dispatch_rework_impl(
        self,
        limit: int | None = None,
        *,
        only_issues: str | None = None,
        stalled_entries: list[dict[str, int]] | None = None,
    ) -> CommandResult:
        """Dispatch rework workers for issues in needs-rework state with open PRs.

        This is only for non-manual adapters. The manual adapter's human-paste
        path remains intact.

        Candidate selection is STATE-DRIVEN: an issue is a rework candidate iff
        state["issues"][n]["status"] == "rework_requested" and it has an open PR.
        The label is used for display only and never for selection.
        """
        if self.config.devin.adapter == "manual":
            return CommandResult(
                True,
                "rework dispatch skipped for manual adapter",
                {"adapter": "manual", "selected_count": 0},
            )

        sessions_dir = self._layout.sessions_dir
        # Issue #1393: clean up stranded .json.tmp session sidecar files from
        # interrupted atomic writes (e.g. a watchdog kill during a launch-
        # refusal write) before this pass writes new ones.
        cleanup_stale_session_tmp_files(sessions_dir)
        # Unconditional stall reaper call, matching dispatch()'s — previously this
        # only ran when max_concurrent_sessions > 0 via the governor. Skipped
        # only when the caller (loop()) already ran the sweep this pass and
        # handed its result down — see dispatch_rework()'s docstring.
        if stalled_entries is None:
            _detect_and_handle_stalled_sessions(
                sessions_dir,
                self.paths.state_file,
                self.config,
                write_gate=self.write_gate,
            )

        # Note: orphaned-worker detection is intentionally NOT re-run here.
        # loop() already runs _detect_and_handle_orphaned_workers once per pass
        # (with the review callback needed to route head-advanced findings to
        # review). Re-running it here produced duplicate drift events (#457).

        # Load state to find rework_requested issues (state-driven selection)
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)

        operator_claimed = operator_claimed_issues(state)
        operator_claimed_skipped: list[int] = []

        # Build the open-PR index BEFORE any per-issue gh.issue_view() fetch.
        # pr_list() returns only OPEN PRs by contract (--state open), so an
        # issue whose PR is closed-unmerged (or that never had one) is absent
        # from pr_by_issue. Issue #558: without this ordering, the candidate
        # scan below called gh.issue_view() for every rework_requested issue
        # every pass -- including issues whose PR closed-unmerged between
        # reconcile sweeps -- a permanent per-pass GitHub fetch with no
        # terminal exit (the exact slow-cost-spiral shape #556/#558 exist to
        # eliminate). Filtering by open PR first cuts the fetch to genuine
        # candidates only. pr_list() is cached within a pass, so calling it
        # here vs. later is the same GitHub call.
        prs = self.gh.pr_list()
        pr_by_issue: dict[int, dict[str, Any]] = {}
        for pr in prs:
            issue_number = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if issue_number is not None:
                # If multiple PRs link to the same issue, keep the lowest PR number
                if issue_number not in pr_by_issue or int(pr["number"]) < int(
                    pr_by_issue[issue_number]["number"]
                ):
                    pr_by_issue[issue_number] = pr

        # Find issues with rework_requested status. Only fetch the full issue
        # from GitHub for issues that actually have an open PR -- a
        # rework_requested issue with no open PR is not a launch candidate
        # (the PR was closed-unmerged or never existed), so the per-issue
        # gh.issue_view fetch is skipped entirely.
        import logging

        logger = logging.getLogger(__name__)
        rework_issues: list[dict[str, Any]] = []
        failed_issue_fetches: list[tuple[int, Exception]] = []
        for number, entry in state.get("issues", {}).items():
            if not isinstance(entry, dict):
                continue
            if entry.get("status") == "rework_requested":
                issue_number = int(number)
                # Issue #400: operator-claimed issues are not rework-dispatchable.
                if issue_number in operator_claimed:
                    operator_claimed_skipped.append(issue_number)
                    continue
                # Issue #558: skip the gh.issue_view fetch for issues with no
                # open PR -- not a rework candidate, and the fetch is the
                # permanent per-pass cost this gate exists to eliminate.
                if issue_number not in pr_by_issue:
                    continue
                # Fetch the full issue from GitHub to get labels and other metadata
                try:
                    full_issue = self.gh.issue_view(issue_number)
                    rework_issues.append(full_issue)
                except GitHubError as exc:
                    # Skip issues that can't be fetched (deleted, transient
                    # outage, etc.), but record the degradation so a later
                    # stall escalation has a reason (issue #939).
                    failed_issue_fetches.append((issue_number, exc))
                    continue

        if failed_issue_fetches:
            payload = _build_rework_issue_fetch_skip_payload(failed_issue_fetches)
            logger.warning(
                "rework dispatch skipped fetching %d issue(s) this pass: %s",
                len(failed_issue_fetches),
                payload["reason"],
            )
            if not self.dry_run:
                try:
                    with state_lock(self.paths.state_file):
                        event_state = load_state(self.paths.state_file)
                        event_state = self._record_event(
                            event_state,
                            "rework_issue_fetch_skipped",
                            payload,
                        )
                        save_state(self.paths.state_file, event_state)
                except (OSError, ValueError, StateLockBusy) as write_exc:
                    # StateLockBusy is a RuntimeError, so it is not covered by the
                    # two above. Without it here the *diagnostic* write can abort
                    # the pass it was only meant to describe: it would propagate to
                    # dispatch_rework's own `except StateLockBusy`, which defers the
                    # whole call and discards the legitimate candidates already
                    # scanned. #939 asked for observation without a control-flow
                    # change; letting a best-effort write decide the pass outcome
                    # is exactly the control-flow change it ruled out.
                    logger.warning("could not record rework_issue_fetch_skipped: %s", write_exc)

        rework_limit = limit if limit is not None else self.config.dispatch.default_limit

        # Apply global concurrency governor cap
        gov = self._apply_concurrency_governor(rework_limit)
        rework_limit = gov.dispatch_limit

        # Apply provider throttle cooldown check
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            if is_throttled(state):
                throttled_until = state.get("throttled_until")
                # Return immediately with deferral reason
                data = {
                    "adapter": self.config.devin.adapter,
                    "selected_count": 0,
                    "deferred_reason": "provider_throttled",
                    "throttled_until": throttled_until,
                }
                if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                    data.update(gov.report_fields())
                return CommandResult(
                    False,
                    f"rework dispatch deferred: provider throttled until {throttled_until}",
                    data,
                )

        # Dry-run: read-only planning — compute selection and would-be
        # SessionRequests, but skip all state writes, label transitions,
        # escalations, review routing, and worker launches. Mirrors
        # _dispatch_impl's dry-run branch. Without this, the fabricated
        # _dry_run_result objects (adapters.py, ok=True for every request)
        # are consumed as ground truth: issues marked "dispatched" with real
        # dispatched_at, redispatch_at counters advanced, orphan flags
        # cleared, and auto-escalation at the redispatch cap — all on zero
        # actual work (issue #616). The no-op-rework and worker-death
        # escalation paths also write state + transition GitHub labels, and
        # the review-routing path calls self.review() which writes state;
        # all are skipped here.
        if self.dry_run:
            dry_candidates = [
                issue for issue in rework_issues if int(issue["number"]) in pr_by_issue
            ]

            # Head-check filtering (read-only): identify candidates that
            # would be routed to review or escalated, but do NOT perform the
            # routing or escalation — both write state and transition GitHub
            # labels.
            dry_head_check_state = load_state_locked(self.paths.state_file)
            dry_routed_to_review: list[int] = []
            dry_head_indeterminate: list[int] = []
            dry_no_op_rework_escalated: list[int] = []
            dry_worker_death_escalated: list[int] = []
            dry_blocked_environment_escalated: list[int] = []
            dry_filtered_candidates: list[dict[str, Any]] = []
            for issue in dry_candidates:
                issue_number = int(issue["number"])
                pr_data = pr_by_issue[issue_number]
                pr_number = int(pr_data["number"])
                live_head_sha = pr_data.get("headRefOid")
                pr_state = dry_head_check_state.get("prs", {}).get(str(pr_number), {})
                reviewed_head_sha = pr_state.get("reviewed_head_sha")

                # Issue #1393: mirror the live path's blocked-environment cap
                # check (read-only here).
                dry_issue_entry_pre = dry_head_check_state.get("issues", {}).get(
                    str(issue_number), {}
                )
                if isinstance(dry_issue_entry_pre, dict):
                    dry_prior_blocked = _windowed_blocked_environment_at(
                        dry_issue_entry_pre,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    if len(dry_prior_blocked) >= self.config.watchdog.max_auto_redispatch:
                        dry_blocked_environment_escalated.append(issue_number)
                        continue

                if not reviewed_head_sha:
                    dry_filtered_candidates.append(issue)
                    continue
                if not live_head_sha:
                    dry_head_indeterminate.append(issue_number)
                    continue
                if live_head_sha == reviewed_head_sha:
                    issue_entry = dry_head_check_state.get("issues", {}).get(str(issue_number), {})
                    if isinstance(issue_entry, dict):
                        prior_redispatch = _windowed_redispatch_at(
                            issue_entry,
                            window_minutes=self.config.watchdog.redispatch_window_minutes,
                        )
                        prior_deaths = _windowed_worker_death_at(
                            issue_entry,
                            window_minutes=self.config.watchdog.redispatch_window_minutes,
                        )
                        no_op_count = max(0, len(prior_redispatch) - len(prior_deaths))
                        if no_op_count >= self.config.watchdog.max_auto_redispatch:
                            dry_no_op_rework_escalated.append(issue_number)
                            continue
                        if len(prior_deaths) >= self.config.watchdog.max_auto_redispatch:
                            dry_worker_death_escalated.append(issue_number)
                            continue
                    dry_filtered_candidates.append(issue)
                    continue

                reviewed_patch_id = pr_state.get("reviewed_patch_id")
                diff = self.gh.pr_diff(pr_number)
                live_patch_id = _calculate_patch_id(diff) if diff else ""
                if not reviewed_patch_id or not live_patch_id:
                    dry_head_indeterminate.append(issue_number)
                    continue
                if live_patch_id == reviewed_patch_id:
                    dry_filtered_candidates.append(issue)
                    continue
                # Issue #1349: a patch-id-advanced head on a CONFLICTING/DIRTY
                # PR is still a legitimate launch candidate -- the head advance
                # did not resolve the conflict the rework was requested for.
                # Mirror the live path's conflict check (read-only here) via
                # the shared helper so the dry-run report does not misreport
                # these as routed_to_review.
                if self._rework_candidate_conflict_blocked(pr_data, pr_number):
                    dry_filtered_candidates.append(issue)
                    continue
                dry_routed_to_review.append(issue_number)

            dry_candidates = dry_filtered_candidates

            # Apply only_issues filter and concurrency cap (read-only).
            # Issue #1014 (mirroring #1005 in the fresh-dispatch path): compute
            # deferred_by_concurrency uniformly across both the only_issues and
            # automatic branches -- the automatic branch used to unconditionally
            # report [] even when the concurrency governor dropped candidates,
            # making a saturated governor indistinguishable from an empty
            # backlog. Shares the selection helper with the live branch below
            # so the two cannot drift.
            (
                dry_selected,
                dry_deferred_by_concurrency_full,
                dry_deferred_by_concurrency,
                dry_deferred_by_concurrency_count,
            ) = _select_rework_candidates(dry_candidates, rework_limit, only_issues=only_issues)

            # Compute would-be SessionRequests without state mutation, label
            # transitions, or worker launches. Rework-prompt re-rendering
            # (which writes files) is skipped; the existing on-disk prompt
            # is used as-is for the planning report.
            dry_session_requests: list[SessionRequest] = []
            dry_skipped_issue_numbers: list[int] = []
            dry_missing_prompt_failures: dict[int, str] = {}
            dry_adapter_choices: dict[int, AdapterChoice] = {}
            dry_api_enabled = self.config.api_worker.enabled
            dry_routing_inputs = self._routing_inputs() if dry_api_enabled else None
            dry_rescue_issue_numbers: set[int] = set()
            for issue in dry_selected:
                issue_number = int(issue["number"])
                full_issue = self.gh.issue_view(issue_number)
                pr = pr_by_issue[issue_number]
                pr_number = int(pr["number"])
                branch_name = pr.get("headRefName", "")
                rework_prompt_path = self.paths.prs / f"pr-{pr_number}" / "rework-prompt.md"
                if not rework_prompt_path.exists():
                    dry_skipped_issue_numbers.append(issue_number)
                    dry_missing_prompt_failures[issue_number] = (
                        f"missing rework prompt: {rework_prompt_path}"
                    )
                    continue
                pr_state_for_rescue = dry_head_check_state.get("prs", {}).get(str(pr_number), {})
                if pr_state_for_rescue.get("rescue_attempted"):
                    dry_rescue_issue_numbers.add(issue_number)
                else:
                    if dry_api_enabled and dry_routing_inputs is not None:
                        issue_labels = {label["name"] for label in full_issue.get("labels", [])}
                        choice = self._select_adapter_for_issue(
                            rework=True,
                            issue_labels=issue_labels,
                            routing_inputs=dry_routing_inputs,
                        )
                        dry_adapter_choices[issue_number] = choice
                dry_session_requests.append(
                    SessionRequest(
                        issue_number=issue_number,
                        issue_title=str(full_issue.get("title") or ""),
                        prompt_path=rework_prompt_path,
                        branch_name=branch_name,
                        rework=True,
                    )
                )

            data = {
                "adapter": self.config.devin.adapter,
                "selected_count": len(dry_session_requests),
                "attempted_count": len(dry_session_requests),
                "failed_count": 0,
                "failures": _build_failure_map(
                    [],
                    set(),
                    dry_deferred_by_concurrency_full,
                    rework_limit,
                    extra_failures=dry_missing_prompt_failures,
                ),
                "deferred_by_concurrency": dry_deferred_by_concurrency,
                "deferred_by_concurrency_count": dry_deferred_by_concurrency_count,
                "skipped_issue_numbers": sorted(dry_skipped_issue_numbers),
                "sessions": [asdict(request) for request in dry_session_requests],
                "adapter_choices": {
                    str(n): {
                        "kind": c.kind,
                        "provider": c.provider,
                        "reason": c.reason,
                    }
                    for n, c in sorted(dry_adapter_choices.items())
                },
                "dispatch_results": [],
                "routed_to_review": sorted(dry_routed_to_review),
                "skipped_head_indeterminate": sorted(dry_head_indeterminate),
                "operator_claimed_skipped": sorted(operator_claimed_skipped),
                "no_op_rework_escalated": sorted(dry_no_op_rework_escalated),
                "worker_death_escalated": sorted(dry_worker_death_escalated),
                "blocked_environment_escalated": sorted(dry_blocked_environment_escalated),
                "rescue_issue_numbers": sorted(dry_rescue_issue_numbers),
            }
            if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                data.update(gov.report_fields())
            return CommandResult(
                True,
                f"dry-run: would dispatch rework for {len(dry_session_requests)} issue(s)",
                data,
            )

        # pr_list() returns only open PRs by contract (--state open); its field
        # list does not include "state", so no per-PR state check here.
        # rework_issues already contains only issues with an open PR (the
        # fetch loop above skipped issues absent from pr_by_issue), so this
        # filter is now a no-op kept for clarity/defense-in-depth.
        candidates = [issue for issue in rework_issues if int(issue["number"]) in pr_by_issue]

        # Issue #339: a rework worker relaunched onto a PR whose rework was
        # already pushed (PR head moved past the last request_changes verdict)
        # finds nothing to do, idles, and is watchdog-reaped — burning a
        # session and a concurrency slot. Filter those candidates out here,
        # before any dispatch_pending claim, and route them to the review
        # lane instead. A sync-merge-only head advance (patch-id unchanged)
        # is NOT treated as "already reworked" — the same patch still needs a
        # genuine rework cycle, so it remains a legitimate launch candidate.
        head_check_state = load_state_locked(self.paths.state_file)
        routed_to_review: list[int] = []
        head_indeterminate: list[int] = []
        no_op_rework_escalated: list[int] = []
        worker_death_escalated: list[int] = []
        # Issue #1239: issues salvaged out of the death-loop gate (stranded
        # commits pushed) and routed to review instead of escalated.
        salvaged_to_review: list[int] = []
        blocked_environment_escalated: list[int] = []
        filtered_candidates = []
        for issue in candidates:
            issue_number = int(issue["number"])
            pr_data = pr_by_issue[issue_number]
            pr_number = int(pr_data["number"])
            live_head_sha = pr_data.get("headRefOid")
            pr_state = head_check_state.get("prs", {}).get(str(pr_number), {})
            reviewed_head_sha = pr_state.get("reviewed_head_sha")

            # Issue #1393: if the previous dispatch was blocked by a
            # pre-launch environment conflict (e.g. worktree_foreign_writer)
            # and the cap is already exhausted, escalate here instead of
            # attempting another launch that will fail identically.  This
            # is a safety net for when the dispatch failure path's
            # escalation didn't stick (race/crash between the escalation
            # and the state write), parallel to the no_op/death checks
            # below.
            issue_entry_pre = head_check_state.get("issues", {}).get(str(issue_number), {})
            if isinstance(issue_entry_pre, dict):
                prior_blocked = _windowed_blocked_environment_at(
                    issue_entry_pre,
                    window_minutes=self.config.watchdog.redispatch_window_minutes,
                )
                if len(prior_blocked) >= self.config.watchdog.max_auto_redispatch:
                    # Issue #1423: before escalating a stuck blocked-environment
                    # cap, attempt to reap an idle foreign writer from the
                    # worktree. If the writer has gone idle since the last
                    # blocked pass, reaping it clears the path for dispatch
                    # instead of escalating a zombie. The marker is read from
                    # the worktree path derived from the PR's head ref.
                    #
                    # Review finding: bound the number of auto-reaps per issue
                    # before falling back to escalation (see the fresh-dispatch
                    # site for the full rationale). The cap is checked against
                    # the snapshot entry here; the reap timestamp is appended
                    # inside the lock below.
                    max_reaps = self.config.watchdog.max_foreign_writer_reaps
                    prior_reaps = _windowed_foreign_writer_reaps(
                        issue_entry_pre,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    reap_cap_ok = len(prior_reaps) < max_reaps
                    branch_pre = str(pr_data.get("headRefName") or "")
                    if branch_pre and reap_cap_ok:
                        wt_path_pre = worktree_path_for_branch(
                            self.repo_root, branch_pre, self._layout.worktrees
                        )
                        marker_pre = read_worktree_marker(wt_path_pre)
                        # Issue #1443: the reap-candidate guards (operator,
                        # stale-pid, own-live-session) and the pid are enforced
                        # inside ``_reap_idle_foreign_writer`` (single point of
                        # enforcement) so this pre-filter cannot drop one and
                        # reap one of our own idle workers as
                        # ``foreign_writer_reaped``. The pid for the audit event
                        # is read from the marker (same source of truth as the
                        # kill path).
                        if marker_pre is not None and _reap_idle_foreign_writer(
                            wt_path_pre,
                            marker_pre,
                            self.config,
                            sessions_dir,
                            state_file=self.paths.state_file,
                            issue_number=issue_number,
                        ):
                            # Writer reaped: clear the counter so the issue
                            # proceeds as a legitimate candidate, and record
                            # the reap so a persistently-blocked worktree
                            # eventually escalates instead of looping.
                            with state_lock(self.paths.state_file):
                                state = load_state(self.paths.state_file)
                                issue_entry = state["issues"].get(str(issue_number), {})
                                if isinstance(issue_entry, dict):
                                    issue_entry["blocked_environment_at"] = []
                                    existing_reaps = _windowed_foreign_writer_reaps(
                                        issue_entry,
                                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                                    )
                                    issue_entry["foreign_writer_reaps"] = existing_reaps + [
                                        datetime.now(UTC).isoformat().replace("+00:00", "Z")
                                    ]
                                    state["issues"][str(issue_number)] = issue_entry
                                    state = append_event(  # event-consumer: audit-only -- records a pre-escalation foreign-writer reap (issue #1423) already enforced by the blocked_environment_at reset and foreign_writer_reaps counter; consumed by tests/test_charlie_work.py regression tests.
                                        state,
                                        "dispatch_blocked_environment_reaped",
                                        {
                                            "issue_number": issue_number,
                                            "pid": marker_pre.get("pid"),
                                            "blocked_environment_count": len(prior_blocked),
                                            "foreign_writer_reap_count": len(existing_reaps) + 1,
                                        },
                                        state_path=self.paths.state_file,
                                    )
                                    save_state(self.paths.state_file, state)
                            filtered_candidates.append(issue)
                            continue
                    blocked_environment_escalated.append(issue_number)
                    continue

            if not reviewed_head_sha:
                # No recorded request_changes head to compare against —
                # nothing to disambiguate; proceed as a legitimate candidate.
                filtered_candidates.append(issue)
                continue
            if not live_head_sha:
                # Live head cannot be determined — fail closed against a
                # wasted launch, but don't strand the issue: status is left
                # untouched so the next pass retries with fresh PR data.
                head_indeterminate.append(issue_number)
                continue
            if live_head_sha == reviewed_head_sha:
                # Head hasn't moved since request_changes. Check if previous
                # rework attempts for this head already exhausted the
                # redispatch cap — if so, escalate immediately instead of
                # dispatching another worker that will also produce no
                # changes. This is a safety net for cases where the restore
                # path's escalation didn't stick (race/crash between the
                # restore and the state write).
                #
                # Issue #1134: a worker that died before pushing leaves the
                # PR head unchanged, but that is NOT a no-op — the worker
                # may have completed its work and died mid-push with
                # salvageable stranded commits.  The orphan sweep records
                # each death in ``worker_death_at``; here we subtract death
                # redispatches from the total to get the genuine no-op
                # count.  A death-loop still escalates, but with
                # ``worker_death_loop`` (triage: "check the worktree for
                # stranded work") instead of ``no_op_rework_cap_exceeded``
                # (triage: "worker is spinning").
                issue_entry = head_check_state.get("issues", {}).get(str(issue_number), {})
                if isinstance(issue_entry, dict):
                    prior_redispatch = _windowed_redispatch_at(
                        issue_entry,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    prior_deaths = _windowed_worker_death_at(
                        issue_entry,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    no_op_count = max(0, len(prior_redispatch) - len(prior_deaths))
                    if no_op_count >= self.config.watchdog.max_auto_redispatch:
                        no_op_rework_escalated.append(issue_number)
                        continue
                    if len(prior_deaths) >= self.config.watchdog.max_auto_redispatch:
                        # Issue #1239: before escalating a death-loop, attempt
                        # to salvage-push stranded commits from the dead
                        # worker's worktree — the same sanctioned-git path the
                        # fresh-dispatch lane uses (#1248).  A successful push
                        # means the worker completed the rework and died at the
                        # final push step; the PR head moves past the
                        # request_changes verdict and the next pass routes to
                        # review (packet regeneration supersedes the verdict),
                        # so this death does NOT count toward the death-loop
                        # cap.  Only a death that produced NO pushable commit
                        # escalates.  ``salvage_push_stranded_commits`` runs
                        # ls-remote before pushing, never force-pushes, and is
                        # fast-forward only — never trust the sidecar's
                        # ``push_succeeded`` as proof of a push.
                        if self._salvage_rework_stranded_commits(
                            issue_number, pr_data, issue_entry
                        ):
                            salvaged_to_review.append(issue_number)
                            continue
                        worker_death_escalated.append(issue_number)
                        continue
                filtered_candidates.append(issue)
                continue

            # Head moved since the request_changes verdict. Disambiguate a
            # real content push from a sync-merge-only advance using the same
            # patch-id helper the janitor's no-op-rework gate relies on
            # (issue #222).
            reviewed_patch_id = pr_state.get("reviewed_patch_id")
            diff = self.gh.pr_diff(pr_number)
            live_patch_id = _calculate_patch_id(diff) if diff else ""
            if not reviewed_patch_id or not live_patch_id:
                # Can't establish content identity (no recorded baseline, or
                # the diff fetch itself failed) — fail closed rather than
                # guess; retry next pass instead of stranding the issue.
                head_indeterminate.append(issue_number)
                continue
            if live_patch_id == reviewed_patch_id:
                # Sync-merge only: the patch itself is unchanged, so the
                # rework is still genuinely outstanding.
                filtered_candidates.append(issue)
                continue

            # Issue #1349: a patch-id-advanced head does NOT mean the
            # rework was already pushed when the PR is still
            # CONFLICTING/DIRTY. The head advance was sync-merges (or
            # conflict-laden merges) that changed the patch-id without
            # resolving the conflict the rework was requested for --
            # whatever was pushed since the last verdict did NOT resolve
            # the conflict, so the rework is still outstanding. Routing
            # such a PR to review() just bounces off the janitor gate's
            # conflict check back to rework_requested, deadlocking the
            # issue between dispatch_rework and review() forever (the
            # only exit being the #765 stall escalation to a human, not a
            # dispatch). Keep it as a legitimate launch candidate so a
            # conflict-rework worker actually dispatches, subject to
            # max_conflict_rework_attempts via the janitor gate on the
            # next settled head change.
            if self._rework_candidate_conflict_blocked(pr_data, pr_number):
                filtered_candidates.append(issue)
                continue

            routed_to_review.append(issue_number)

        candidates = filtered_candidates
        # A content change was detected above, but review() may itself fail to
        # produce a packet (deterministic janitor gate: conflicting/draft/red
        # CI — see review()'s early-return before any packet/label write).
        # Only issues review() actually routed get reported as routed_to_review;
        # the rest keep their rework_requested status and are retried next pass
        # (issue #339 finding 1: never report a routing that didn't happen —
        # doing so desyncs state.json from GitHub labels/PR state with no
        # automated recovery path).
        confirmed_routed_to_review: list[int] = []
        review_blocked_retry: list[int] = []
        for routed_issue_number in routed_to_review:
            routed_pr_number = int(pr_by_issue[routed_issue_number]["number"])
            reviewed_head_sha_before = (
                head_check_state.get("prs", {})
                .get(str(routed_pr_number), {})
                .get("reviewed_head_sha")
            )
            routed, _review_result = self._route_rework_candidate_to_review(
                routed_issue_number, routed_pr_number, reviewed_head_sha_before
            )
            if routed:
                confirmed_routed_to_review.append(routed_issue_number)
            else:
                review_blocked_retry.append(routed_issue_number)
        routed_to_review = confirmed_routed_to_review

        # Issue #1239: route salvaged death-loop issues to review.  The
        # salvage push already advanced the PR head past the request_changes
        # verdict, so review() generates a fresh packet that supersedes the
        # stale verdict — the same machinery the head-moved branch above uses.
        # A salvage that review() blocks (deterministic janitor gate) stays
        # rework_requested for the next pass, same as a blocked head-moved
        # routing; the death was NOT counted, so the death-loop cap is not
        # consumed.
        salvaged_confirmed: list[int] = []
        salvaged_blocked: list[int] = []
        for salvaged_issue_number in salvaged_to_review:
            salvaged_pr_number = int(pr_by_issue[salvaged_issue_number]["number"])
            reviewed_head_sha_before = (
                head_check_state.get("prs", {})
                .get(str(salvaged_pr_number), {})
                .get("reviewed_head_sha")
            )
            routed, _review_result = self._route_rework_candidate_to_review(
                salvaged_issue_number, salvaged_pr_number, reviewed_head_sha_before
            )
            if routed:
                salvaged_confirmed.append(salvaged_issue_number)
            else:
                salvaged_blocked.append(salvaged_issue_number)
        routed_to_review.extend(salvaged_confirmed)
        review_blocked_retry.extend(salvaged_blocked)

        # Escalate no-op rework issues that have exhausted the redispatch cap
        # without the PR head ever advancing. Each of these would have burned
        # another worker session on an unchanged diff.
        if no_op_rework_escalated:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for issue_number in no_op_rework_escalated:
                    entry = state.get("issues", {}).get(str(issue_number), {})
                    if not isinstance(entry, dict):
                        entry = {}
                    current_status = entry.get("status")
                    if current_status == "escalated":
                        continue
                    redispatch_at = _windowed_redispatch_at(
                        entry,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    ) + [datetime.now(UTC).isoformat().replace("+00:00", "Z")]
                    # Issue #783: no-op rework redispatch cap is a process
                    # failure, not a judgment call -- mechanical.
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="redispatch_cap_exceeded",
                        reason_class="mechanical",
                        issue_extra={
                            "redispatch_at": redispatch_at,
                            "dispatched_at": None,
                        },
                    )
                    state = append_event(
                        state,
                        "session_failed_escalated",
                        {
                            "issue_number": issue_number,
                            "previous_status": "rework_requested",
                            "reason": "no_op_rework_cap_exceeded",
                            "redispatch_count": len(redispatch_at),
                        },
                        state_path=self.paths.state_file,
                    )
                save_state(self.paths.state_file, state)
            for issue_number in no_op_rework_escalated:
                transition(
                    self.gh,
                    self.config.labels,
                    issue_number,
                    _escalation_edge("redispatch_escalated", "mechanical"),
                )

        # Issue #1134: escalate worker-death loops separately from no-op
        # rework loops.  A death loop means the worker keeps dying before
        # pushing — the work may be complete but stranded in the worktree.
        # The operator triage for ``worker_death_loop`` is "check the
        # worktree for stranded commits," not "worker is spinning."
        # Pre-compute stranded-commits counts outside the state lock because
        # the git probe touches the filesystem.
        if worker_death_escalated:
            stranded_counts: dict[int, int | None] = {}
            for issue_number in worker_death_escalated:
                pr_data = pr_by_issue.get(issue_number)
                if pr_data is None:
                    stranded_counts[issue_number] = None
                    continue
                live_head = pr_data.get("headRefOid")
                if not live_head:
                    stranded_counts[issue_number] = None
                    continue
                issue_entry = head_check_state.get("issues", {}).get(str(issue_number), {})
                branch = issue_entry.get("branch_name") if isinstance(issue_entry, dict) else None
                if not branch:
                    stranded_counts[issue_number] = None
                    continue
                wt_path = worktree_path_for_branch(self.repo_root, branch, self._layout.worktrees)
                ahead, _err = worktree_ahead_of_sha(wt_path, live_head)
                stranded_counts[issue_number] = ahead
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for issue_number in worker_death_escalated:
                    entry = state.get("issues", {}).get(str(issue_number), {})
                    if not isinstance(entry, dict):
                        entry = {}
                    current_status = entry.get("status")
                    if current_status == "escalated":
                        continue
                    prior_deaths = _windowed_worker_death_at(
                        entry,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    # Issue #783: worker death loop is a process failure,
                    # not a judgment call -- mechanical.
                    issue_extra: dict[str, Any] = {
                        "worker_death_at": prior_deaths,
                        "dispatched_at": None,
                    }
                    stranded = stranded_counts.get(issue_number)
                    if stranded is not None:
                        issue_extra["stranded_commits"] = stranded
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="worker_death_loop",
                        reason_class="mechanical",
                        issue_extra=issue_extra,
                    )
                    event_payload: dict[str, Any] = {
                        "issue_number": issue_number,
                        "previous_status": "rework_requested",
                        "reason": "worker_death_loop",
                        "worker_death_count": len(prior_deaths),
                    }
                    if stranded is not None:
                        event_payload["stranded_commits"] = stranded
                    state = append_event(
                        state,
                        "session_failed_escalated",
                        event_payload,
                        state_path=self.paths.state_file,
                    )
                save_state(self.paths.state_file, state)
            for issue_number in worker_death_escalated:
                transition(
                    self.gh,
                    self.config.labels,
                    issue_number,
                    _escalation_edge("redispatch_escalated", "mechanical"),
                )

        # Issue #1393: escalate issues whose pre-launch environment has
        # blocked every dispatch attempt (e.g. a stale foreign worktree).
        # The operator triage for ``dispatch_blocked_environment`` is
        # "remove the stale checkout at <path>," not "worker quality cap
        # exceeded."  Parallel to the no_op/death escalation blocks above.
        if blocked_environment_escalated:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for issue_number in blocked_environment_escalated:
                    entry = state.get("issues", {}).get(str(issue_number), {})
                    if not isinstance(entry, dict):
                        entry = {}
                    current_status = entry.get("status")
                    if current_status == "escalated":
                        continue
                    prior_blocked = _windowed_blocked_environment_at(
                        entry,
                        window_minutes=self.config.watchdog.redispatch_window_minutes,
                    )
                    state = _escalate_issue(
                        state,
                        issue_number,
                        reason="dispatch_blocked_environment",
                        reason_class="mechanical",
                        issue_extra={
                            "blocked_environment_at": prior_blocked,
                            "dispatched_at": None,
                        },
                    )
                    state = append_event(
                        state,
                        "session_failed_escalated",
                        {
                            "issue_number": issue_number,
                            "previous_status": "rework_requested",
                            "reason": "dispatch_blocked_environment",
                            "blocked_environment_count": len(prior_blocked),
                        },
                        state_path=self.paths.state_file,
                    )
                save_state(self.paths.state_file, state)
            for issue_number in blocked_environment_escalated:
                transition(
                    self.gh,
                    self.config.labels,
                    issue_number,
                    _escalation_edge("redispatch_escalated", "mechanical"),
                )

        # Issue #1014 (mirroring #1005 in the fresh-dispatch path): compute
        # deferred_by_concurrency uniformly across both the only_issues and
        # automatic branches -- the automatic branch used to unconditionally
        # report [] even when the concurrency governor dropped candidates,
        # making a saturated governor indistinguishable from an empty backlog.
        # Shares the selection helper with the dry-run branch above so the two
        # cannot drift.
        (
            selected,
            deferred_by_concurrency_full,
            deferred_by_concurrency,
            deferred_by_concurrency_count,
        ) = _select_rework_candidates(candidates, rework_limit, only_issues=only_issues)

        if not selected:
            data = {
                "adapter": self.config.devin.adapter,
                "selected_count": 0,
                "failures": _build_failure_map(
                    [], set(), deferred_by_concurrency_full, rework_limit
                ),
                "deferred_by_concurrency": deferred_by_concurrency,
                "deferred_by_concurrency_count": deferred_by_concurrency_count,
                "routed_to_review": sorted(routed_to_review),
                "skipped_head_indeterminate": sorted(head_indeterminate),
                "review_blocked_retry": sorted(review_blocked_retry),
                "operator_claimed_skipped": sorted(operator_claimed_skipped),
                "no_op_rework_escalated": sorted(no_op_rework_escalated),
                "worker_death_escalated": sorted(worker_death_escalated),
                "salvaged_to_review": sorted(salvaged_to_review),
                "blocked_environment_escalated": sorted(blocked_environment_escalated),
            }
            if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                data.update(gov.report_fields())
            return CommandResult(
                True,
                "no rework candidates found",
                data,
            )

        # First lock: claim issues by marking them as dispatch_pending
        selected_issue_numbers: list[int] = []
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            # Filter out issues whose PR is in escalated state (rework cap exhausted)
            selected = [
                issue
                for issue in selected
                if state["prs"]
                .get(str(pr_by_issue[int(issue["number"])]["number"]), {})
                .get("status")
                != "escalated"
            ]
            live_dispatched = set()
            for number, entry in state.get("issues", {}).items():
                if not isinstance(entry, dict):
                    continue
                status = entry.get("status")
                if status == "dispatched":
                    live_dispatched.add(int(number))
                elif status == "dispatch_pending" and not is_claim_stale(
                    entry.get("dispatch_pending_at")
                ):
                    live_dispatched.add(int(number))
            # Filter out already-dispatched issues
            selected = [issue for issue in selected if int(issue["number"]) not in live_dispatched]
            selected_issue_numbers = [int(issue["number"]) for issue in selected]
            # Mark selected issues as "dispatch_pending"
            for issue_number in selected_issue_numbers:
                entry = {
                    **state["issues"].get(str(issue_number), {}),
                    "number": issue_number,
                    "status": "dispatch_pending",
                    "dispatch_pending_at": utc_now(),
                }
                # A fresh dispatch supersedes any previous orphan flag.
                entry.pop("orphan_flagged_at", None)
                entry.pop("orphan_drift_fingerprint", None)
                entry.pop("orphan_drift_at", None)
                state["issues"][str(issue_number)] = entry
            save_state(self.paths.state_file, state)

        if not selected_issue_numbers:
            data = {
                "adapter": self.config.devin.adapter,
                "selected_count": 0,
                "failures": _build_failure_map(
                    [], set(), deferred_by_concurrency_full, rework_limit
                ),
                "deferred_by_concurrency": deferred_by_concurrency,
                "deferred_by_concurrency_count": deferred_by_concurrency_count,
                "routed_to_review": sorted(routed_to_review),
                "skipped_head_indeterminate": sorted(head_indeterminate),
                "review_blocked_retry": sorted(review_blocked_retry),
                "no_op_rework_escalated": sorted(no_op_rework_escalated),
                "worker_death_escalated": sorted(worker_death_escalated),
                "salvaged_to_review": sorted(salvaged_to_review),
                "blocked_environment_escalated": sorted(blocked_environment_escalated),
            }
            if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                data.update(gov.report_fields())
            return CommandResult(
                True,
                "all rework candidates already dispatched",
                data,
            )

        # Representative PR for the aggregate dispatch_rework event. The events table
        # has a single pr_number column, so the first selected issue's open PR is used
        # as the indexed representative (mirroring the singular pr_number in
        # rework_already_pushed).
        first_selected_issue_number = selected_issue_numbers[0]
        first_rework_pr_number = (
            int(pr_by_issue[first_selected_issue_number]["number"])
            if first_selected_issue_number in pr_by_issue
            else None
        )

        # Do all network calls, file writes, and worker launches outside the lock
        session_requests: list[SessionRequest] = []
        full_issues: dict[int, dict[str, Any]] = {}
        skipped_issue_numbers: list[int] = []
        missing_prompt_failures: dict[int, str] = {}
        # Issue #482: per-issue adapter routing for rework. Rework issues
        # route to the api adapter when preflight passes (policy:rework),
        # falling back to the default adapter on any preflight failure.
        # The rework prompt is already on disk (written during the review
        # flow with config.dispatch.rework_template); api_worker.rework_template
        # defaults to the same "rework.md", so no re-render is needed here.
        adapter_choices: dict[int, AdapterChoice] = {}
        api_enabled = self.config.api_worker.enabled
        routing_inputs = self._routing_inputs() if api_enabled else None
        # Rescue tier (issue #555): an issue is rescue-marked when the rescue
        # interception sites (record_review / _route_janitor_gate_failure_to_
        # rework) already stamped `rescue_attempted` on its PR record instead
        # of escalating. Those issues must launch via the claude-code adapter
        # pinned to `rescue.worker_model`, regardless of the primary
        # configured `devin.adapter` — tracked separately here so the SAME
        # candidate-selection/session-request/state-bookkeeping code below
        # handles them, only the final dispatch_sessions() call differs.
        #
        # Always loaded (never gated on self.config.rescue.enabled): routing
        # of a PR that already carries the durable marker must not depend on
        # the current config value. If an operator flips rescue.enabled off
        # while a rescue rework is queued (rework_requested + marker set,
        # worker not yet launched), it must still launch via the rescue
        # adapter/model -- enabled only gates NEW rescue entry at the three
        # cap sites, never routing of an already-marked PR.
        rescue_issue_numbers: set[int] = set()
        rescue_state_snapshot = load_state_locked(self.paths.state_file)
        for issue_number in selected_issue_numbers:
            full_issue = self.gh.issue_view(issue_number)
            full_issues[issue_number] = full_issue
            pr = pr_by_issue[issue_number]
            pr_number = int(pr["number"])
            # Use the existing PR branch instead of creating a new one
            branch_name = pr.get("headRefName", "")
            # Use the rework prompt from the PR directory
            rework_prompt_path = self.paths.prs / f"pr-{pr_number}" / "rework-prompt.md"
            if not rework_prompt_path.exists():
                # Skip if rework prompt doesn't exist — record as rework_requested
                # to release the claim and allow retry (issue #116)
                skipped_issue_numbers.append(issue_number)
                missing_prompt_failures[issue_number] = (
                    f"missing rework prompt: {rework_prompt_path}"
                )
                continue
            # The brief on disk is authoritative and dispatch_rework reads it
            # verbatim, so it must be checked for staleness before dispatch.
            # It can go stale along two independent axes:
            #
            #   1. The verdict content changed under it — an operator
            #      hand-editing review-decision.json is the #510 case, and
            #      issue #632 added the mtime comparison that catches it.
            #   2. The *renderer* changed under an untouched verdict — issue
            #      #800. No timestamp moves, so axis 1's check cannot see it.
            #
            # Axis 2 subsumes axis 1 wherever the dispatch note can be
            # replayed from its sidecar, so the sidecar decides which check
            # runs; see the two branches below.
            decision_path = self.paths.prs / f"pr-{pr_number}" / "review-decision.json"
            note_path = self.paths.prs / f"pr-{pr_number}" / "rework-dispatch-note.txt"
            # The sidecar is what makes re-rendering non-lossy, so an
            # unreadable one is treated exactly like an absent one: fall back
            # to the mtime gate rather than regenerate with an empty note.
            try:
                dispatch_note = (
                    note_path.read_text(encoding="utf-8") if note_path.exists() else None
                )
            except (OSError, UnicodeDecodeError):
                dispatch_note = None
            # A missing verdict is the other way re-rendering could lose
            # information: _render_required_changes_section would fall to its
            # Tier 3 "REVIEWER FINDINGS UNAVAILABLE" placeholder and overwrite
            # a brief that still has real findings in it. Without the verdict
            # there is no way to produce a *better* brief, only a worse one,
            # so leave it alone — same failure direction as the sidecar guard.
            if dispatch_note is not None and decision_path.exists():
                # Issue #800: the mtime comparison above only sees one of the
                # two ways a brief goes stale. It catches *verdict content*
                # drift, but a brief also goes stale when the **renderer**
                # changes underneath an untouched verdict — 35c072d adding
                # tier-2/3 fallbacks to _render_required_changes_section, or
                # #883 rewriting rework.md's fences. Nothing about that makes
                # the verdict newer, so every brief already on disk kept
                # rendering through the old code indefinitely.
                #
                # A template/renderer digest (the #592 approach) would not fix
                # this: #800's own trigger was a change to Python, not to a
                # template. So re-render unconditionally and diff instead —
                # that is axis-agnostic by construction and cannot miss a
                # staleness source nobody has enumerated yet.
                #
                # Writing stays conditional on the content actually differing.
                # An unconditional write would churn the brief mtime that
                # _is_verdict_newer_than_brief reads, on every pass.
                #
                # Reading the brief is new failure surface on a path that
                # previously never opened it, and this loop body has no
                # per-issue exception handling — an unreadable brief would
                # abort the whole pass for every *other* issue too. Treat it
                # as "differs": the note is in hand, so regenerating is both
                # safe and the right repair for an unreadable file.
                try:
                    current_brief: str | None = rework_prompt_path.read_text(encoding="utf-8")
                except (OSError, UnicodeDecodeError):
                    current_brief = None
                expected_brief = _render_rework_prompt(
                    self.paths.state_file,
                    pr,
                    issue_number,
                    dispatch_note,
                    self.config,
                    repo_root=self.repo_root,
                )
                if expected_brief != current_brief:
                    verdict_newer = _is_verdict_newer_than_brief(decision_path, rework_prompt_path)
                    self._write_rework_prompt(pr, issue_number, dispatch_note)
                    log_event(
                        self.paths.state_file,
                        "rework_brief_regenerated",
                        {
                            "pr_number": pr_number,
                            "issue_number": issue_number,
                            # Which axis moved: a newer verdict is the #632
                            # case the mtime gate already covered; anything
                            # else is renderer/template drift (#800), which
                            # was previously undetectable.
                            "reason": "verdict_newer" if verdict_newer else "renderer_drift",
                        },
                        repo=self.repo_root.name,
                    )
            elif _is_verdict_newer_than_brief(decision_path, rework_prompt_path):
                # No usable sidecar: a brief predating #632, whose dispatch note
                # exists only inside the rendered markdown. Re-rendering it
                # would silently drop that note, so the unconditional path
                # above is gated on the inputs being reproducible. Fall back
                # to the mtime gate, which regenerates with an empty note
                # only when a newer verdict makes the findings worth more
                # than the lost prose.
                self._write_rework_prompt(pr, issue_number, "")
            # Rescue tier (issue #555): rescue-marked PRs bypass per-issue
            # adapter routing — they always launch via the claude-code adapter
            # pinned to rescue.worker_model, regardless of the primary
            # configured devin.adapter or api_worker routing preflight.
            pr_state_for_rescue = rescue_state_snapshot.get("prs", {}).get(str(pr_number), {})
            if pr_state_for_rescue.get("rescue_attempted"):
                rescue_issue_numbers.add(issue_number)
            else:
                # Route this non-rescue rework issue through the single
                # enforcement point (issue #482).
                if api_enabled and routing_inputs is not None:
                    issue_labels = {label["name"] for label in full_issue.get("labels", [])}
                    choice = self._select_adapter_for_issue(
                        rework=True,
                        issue_labels=issue_labels,
                        routing_inputs=routing_inputs,
                    )
                    adapter_choices[issue_number] = choice
            session_requests.append(
                SessionRequest(
                    issue_number=issue_number,
                    issue_title=str(full_issue.get("title") or ""),
                    prompt_path=rework_prompt_path,
                    branch_name=branch_name,
                    rework=True,
                )
            )

        if not session_requests:
            # Release the dispatch_pending claims for all skipped issues
            no_session_failure_map = _build_failure_map(
                [],
                set(),
                deferred_by_concurrency_full,
                rework_limit,
                extra_failures=missing_prompt_failures,
            )
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                for issue_number in skipped_issue_numbers:
                    full_issue = full_issues[issue_number]
                    entry = {
                        **state["issues"].get(str(issue_number), {}),
                        "number": issue_number,
                        "title": full_issue.get("title"),
                        "url": full_issue.get("url"),
                        # Issue #116: restore to rework_requested for retry (missing prompt may be transient)
                        "status": "rework_requested",
                        "dispatched_at": None,
                    }
                    entry.pop("dispatch_pending_at", None)
                    entry.pop("label_error", None)
                    state["issues"][str(issue_number)] = entry
                state = append_event(
                    state,
                    "dispatch_rework",
                    {
                        "pr_number": first_rework_pr_number,
                        "issue_numbers": [],
                        "failed_issue_numbers": [],
                        "skipped_issue_numbers": sorted(skipped_issue_numbers),
                        "deferred_by_concurrency": deferred_by_concurrency,
                        "deferred_by_concurrency_count": deferred_by_concurrency_count,
                        "label_errors": [],
                        "operator_claimed_skipped": sorted(operator_claimed_skipped),
                        "failures": no_session_failure_map,
                        # Issue #1014 (mirroring #1005): the capacity axis.
                        # Always present -- gov.report_fields() is safe to call
                        # unclamped -- and explicit about `clamped` so a reader
                        # does not have to redo the arithmetic. `dispatch_limit`
                        # is included explicitly (report_fields() does not carry
                        # it) because it is the only field that reflects a
                        # fleet-cap clamp.
                        "concurrency_governor": {
                            "clamped": gov.clamped,
                            "dispatch_limit": gov.dispatch_limit,
                            **gov.report_fields(),
                        },
                    },
                    state_path=self.paths.state_file,
                )
                save_state(self.paths.state_file, state)
            data = {
                "adapter": self.config.devin.adapter,
                "selected_count": 0,
                "failures": no_session_failure_map,
                "deferred_by_concurrency": deferred_by_concurrency,
                "deferred_by_concurrency_count": deferred_by_concurrency_count,
                "routed_to_review": sorted(routed_to_review),
                "skipped_head_indeterminate": sorted(head_indeterminate),
                "review_blocked_retry": sorted(review_blocked_retry),
                "operator_claimed_skipped": sorted(operator_claimed_skipped),
                "no_op_rework_escalated": sorted(no_op_rework_escalated),
                "worker_death_escalated": sorted(worker_death_escalated),
                "salvaged_to_review": sorted(salvaged_to_review),
                "blocked_environment_escalated": sorted(blocked_environment_escalated),
            }
            if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
                data.update(gov.report_fields())
            return CommandResult(
                True,
                "no valid rework prompts found",
                data,
            )

        manifest_path = self._layout.session_manifest
        results_path = self._layout.session_results
        # Rescue tier (issue #555) + per-issue routing (issue #482): split
        # the batch so rescue-marked issues launch via the claude-code adapter
        # pinned to rescue.worker_model (see _rescue_adapter_settings),
        # while every other candidate is dispatched via the per-issue routing
        # partition (_dispatch_partitioned). Rescue issues bypass routing
        # entirely — they always use the rescue adapter/model. Reuses the
        # same dispatch_sessions()/launch_claude_worker() path for both; the
        # only difference is which AdapterSettings/config is passed in.
        normal_requests = [
            r for r in session_requests if r.issue_number not in rescue_issue_numbers
        ]
        rescue_requests = [r for r in session_requests if r.issue_number in rescue_issue_numbers]
        dispatch_results: list[SessionDispatchResult] = []
        if normal_requests:
            # adapter_choices only contains non-rescue issues (rescue issues
            # were never routed in the loop above), so the partition is
            # correct.
            dispatch_results.extend(self._dispatch_partitioned(normal_requests, adapter_choices))
        if rescue_requests:
            dispatch_results.extend(
                dispatch_sessions(
                    self.repo_root,
                    manifest_path,
                    results_path,
                    self._rescue_adapter_settings(),
                    rescue_requests,
                )
            )
        # When both normal and rescue tiers dispatched, each sub-call's
        # write_session_manifest/write_session_results overwrote the files with
        # only its subset. Rewrite once with the combined batch so the on-disk
        # observability files reflect the full pass. The adapter label is
        # derived from the actual partition (normal routing kinds + the rescue
        # kind "claude-code") via manifest_adapter_label — a homogeneous batch
        # is labeled with its single kind, not the default adapter name
        # (issue #626). When only one tier ran, its sub-call already wrote the
        # correct manifest, so the combined manifest write is skipped (it was
        # redundant and, before #626, used the wrong label).
        if normal_requests and rescue_requests:
            # When api routing is enabled, adapter_choices has an entry for
            # every non-rescue issue. When disabled (adapter_choices empty),
            # all normal issues used the default adapter via the single-group
            # path in _dispatch_partitioned.
            if adapter_choices:
                combined_kinds = {adapter_choices[r.issue_number].kind for r in normal_requests}
            else:
                combined_kinds = {self.config.devin.adapter}
            combined_kinds.add("claude-code")
            write_session_manifest(
                manifest_path, session_requests, adapter=manifest_adapter_label(combined_kinds)
            )
        write_session_results(results_path, dispatch_results)

        successful_issue_numbers = {
            result.issue_number for result in dispatch_results if result.ok
        }
        failed_issue_numbers = {
            result.issue_number for result in dispatch_results if not result.ok
        }

        # Second lock: upgrade claim from dispatch_pending to dispatched/dispatch_failed
        label_errors: list[int] = []
        label_error_failures: dict[int, str] = {}
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            # Record skipped issues (missing rework prompt) as rework_requested
            # This handles the mixed case where some issues have prompts and some don't.
            # Missing rework-prompt.md may be transient (review agent hasn't written it yet),
            # so restore to rework_requested for retry (issue #116).
            for issue_number in skipped_issue_numbers:
                full_issue = full_issues[issue_number]
                entry = {
                    **state["issues"].get(str(issue_number), {}),
                    "number": issue_number,
                    "title": full_issue.get("title"),
                    "url": full_issue.get("url"),
                    "status": "rework_requested",
                    "dispatched_at": None,
                }
                entry.pop("dispatch_pending_at", None)
                entry.pop("label_error", None)
                state["issues"][str(issue_number)] = entry
            for request in session_requests:
                full_issue = full_issues[request.issue_number]
                ok = request.issue_number in successful_issue_numbers
                # Issue #482: record the adapter choice into adapter_history
                # before constructing the entry, so the {**entry} spread below
                # preserves the adapter_history field.
                choice = adapter_choices.get(request.issue_number)
                if choice is not None:
                    state = record_adapter_choice(state, request.issue_number, choice, utc_now())
                entry = {
                    **state["issues"].get(str(request.issue_number), {}),
                    "number": request.issue_number,
                    "title": full_issue.get("title"),
                    "url": full_issue.get("url"),
                    "branch_name": request.branch_name,
                    "prompt_path": str(request.prompt_path),
                    # On failure, restore to rework_requested so the issue can be retried
                    # in the next pass (issue #116). On success, mark as dispatched.
                    "status": "dispatched" if ok else "rework_requested",
                    "dispatched_at": utc_now() if ok else None,
                }
                entry.pop("dispatch_pending_at", None)
                entry.pop("label_error", None)
                # A successful dispatch supersedes any previous orphan flag.
                if ok:
                    entry.pop("orphan_flagged_at", None)
                    entry.pop("orphan_drift_fingerprint", None)
                    entry.pop("orphan_drift_at", None)
                    # Issue #1106: a new rework dispatch supersedes any
                    # prior startup-death classification — the new session
                    # is the one whose outcome the next janitor pass will
                    # attribute, so the stale flag must not survive.
                    dispatched_pr = pr_by_issue.get(request.issue_number)
                    if dispatched_pr is not None:
                        dispatched_pr_number = int(dispatched_pr["number"])
                        pr_state = state.get("prs", {}).get(str(dispatched_pr_number), {})
                        if pr_state:
                            state["prs"][str(dispatched_pr_number)] = {
                                **pr_state,
                                "last_rework_failure_kind": None,
                                "last_rework_was_startup_death": False,
                            }
                # Store worker PID and process start time for state-based liveness detection
                # This allows recovery even when session sidecar files are orphaned (issue #207)
                if ok:
                    result = next(
                        (r for r in dispatch_results if r.issue_number == request.issue_number),
                        None,
                    )
                    if result and result.pid is not None:
                        entry["worker_pid"] = result.pid
                        entry["worker_process_start_time"] = result.process_start_time
                if ok:
                    # Track redispatch count for escalation cap (issue #165)
                    now = datetime.now(UTC)
                    redispatch_at = _windowed_redispatch_at(
                        entry, window_minutes=self.config.watchdog.redispatch_window_minutes
                    ) + [now.isoformat().replace("+00:00", "Z")]
                    if len(redispatch_at) > self.config.watchdog.max_auto_redispatch:
                        # Escalate to human review
                        # Issue #783: rework dispatch redispatch cap is a
                        # process failure, not a judgment call -- mechanical.
                        state = _escalate_issue(
                            state,
                            request.issue_number,
                            reason="redispatch_cap_exceeded",
                            reason_class="mechanical",
                            issue_extra={"redispatch_at": redispatch_at},
                        )
                        entry = state["issues"][str(request.issue_number)]
                        save_state(self.paths.state_file, state)
                        edge = _escalation_edge("redispatch_escalated", "mechanical")
                        result = transition(
                            self.gh,
                            self.config.labels,
                            request.issue_number,
                            edge,
                        )
                        if result.outcome != TransitionOutcome.APPLIED:
                            label_error = {
                                "edge": edge,
                                "outcome": result.outcome.value,
                                "add_failures": result.add_failures,
                                "remove_failures": result.remove_failures,
                            }
                            entry["label_error"] = label_error
                            label_errors.append(request.issue_number)
                            label_error_failures[request.issue_number] = _label_error_reason(
                                label_error
                            )
                            save_state(self.paths.state_file, state)
                        continue
                    else:
                        entry["redispatch_at"] = redispatch_at
                        state["issues"][str(request.issue_number)] = entry
                        save_state(self.paths.state_file, state)
                        result = transition(
                            self.gh,
                            self.config.labels,
                            request.issue_number,
                            "rework_dispatched",
                        )
                        if result.outcome != TransitionOutcome.APPLIED:
                            label_error = {
                                "edge": "rework_dispatched",
                                "outcome": result.outcome.value,
                                "add_failures": result.add_failures,
                                "remove_failures": result.remove_failures,
                            }
                            entry["label_error"] = label_error
                            label_errors.append(request.issue_number)
                            label_error_failures[request.issue_number] = _label_error_reason(
                                label_error
                            )
                            save_state(self.paths.state_file, state)
                else:
                    # Track every rework-dispatch attempt, successful or not,
                    # against the same redispatch window used on the success path.
                    # Failed attempts that repeat without ever succeeding
                    # eventually trip max_auto_redispatch and escalate instead of
                    # looping forever (issue #515).
                    failed_result = next(
                        (r for r in dispatch_results if r.issue_number == request.issue_number),
                        None,
                    )
                    failure_kind = failed_result.failure_kind if failed_result else None
                    now = datetime.now(UTC)
                    # Issue #1393: a pre-launch environment block (e.g.
                    # worktree_foreign_writer) never started a worker session,
                    # so it must NOT count against the redispatch cap (which
                    # measures worker output, not environment hygiene).  Use a
                    # separate blocked_environment_at counter and escalate with
                    # the correct reason + blocking path after the same cap.
                    blocked_environment = (
                        failure_kind in PRE_LAUNCH_BLOCKED_ENVIRONMENT_FAILURE_KINDS
                    )
                    if blocked_environment:
                        blocked_environment_at = _windowed_blocked_environment_at(
                            entry,
                            window_minutes=self.config.watchdog.redispatch_window_minutes,
                        ) + [now.isoformat().replace("+00:00", "Z")]
                        blocking_error = failed_result.error if failed_result else None
                        if len(blocked_environment_at) > self.config.watchdog.max_auto_redispatch:
                            # Issue #1423: before escalating a blocked-environment
                            # cap exhaustion for a foreign writer, attempt to reap
                            # it one more time. A writer that was active on earlier
                            # passes but has since gone idle is reaped here instead
                            # of escalating a zombie to a human. Escalation is
                            # reserved for a writer that is alive *and* active.
                            #
                            # Review finding: bound the number of auto-reaps per
                            # issue before falling back to escalation (see the
                            # fresh-dispatch site for the full rationale).
                            max_reaps = self.config.watchdog.max_foreign_writer_reaps
                            prior_reaps = _windowed_foreign_writer_reaps(
                                entry,
                                window_minutes=self.config.watchdog.redispatch_window_minutes,
                            )
                            if len(prior_reaps) < max_reaps and _try_reap_blocked_foreign_writer(
                                failed_result,
                                self.config,
                                self.paths.state_file,
                                request.issue_number,
                                sessions_dir,
                            ):
                                entry["status"] = "rework_requested"
                                entry["dispatched_at"] = None
                                entry["blocked_environment_at"] = []
                                entry["foreign_writer_reaps"] = prior_reaps + [
                                    now.isoformat().replace("+00:00", "Z")
                                ]
                                state["issues"][str(request.issue_number)] = entry
                                state = append_event(  # event-consumer: audit-only -- records a rework-dispatch foreign-writer reap (issue #1423) already enforced by the blocked_environment_at reset and foreign_writer_reaps counter; consumed by tests/test_charlie_work.py regression tests.
                                    state,
                                    "rework_dispatch_blocked_environment_reaped",
                                    {
                                        "issue_number": request.issue_number,
                                        "failure_kind": failure_kind,
                                        "pid": failed_result.pid if failed_result else None,
                                        "blocked_environment_count": len(blocked_environment_at),
                                        "foreign_writer_reap_count": len(prior_reaps) + 1,
                                    },
                                    state_path=self.paths.state_file,
                                )
                                save_state(self.paths.state_file, state)
                                continue
                            # Escalate with the environment reason and the
                            # blocking path so the operator sees "remove
                            # C:\...\wt", not "worker quality cap exceeded."
                            state = _escalate_issue(
                                state,
                                request.issue_number,
                                reason="dispatch_blocked_environment",
                                reason_class="mechanical",
                                issue_extra={
                                    "blocked_environment_at": blocked_environment_at,
                                    "dispatched_at": None,
                                },
                            )
                            entry = state["issues"][str(request.issue_number)]
                            state = append_event(
                                state,
                                "session_failed_escalated",
                                {
                                    "issue_number": request.issue_number,
                                    "previous_status": "rework_requested",
                                    "reason": "dispatch_blocked_environment",
                                    "failure_kind": failure_kind,
                                    "blocking_error": blocking_error,
                                    "blocked_environment_count": len(blocked_environment_at),
                                },
                                state_path=self.paths.state_file,
                            )
                            save_state(self.paths.state_file, state)
                            edge = _escalation_edge("redispatch_escalated", "mechanical")
                            result = transition(
                                self.gh,
                                self.config.labels,
                                request.issue_number,
                                edge,
                            )
                            if result.outcome != TransitionOutcome.APPLIED:
                                label_error = {
                                    "edge": edge,
                                    "outcome": result.outcome.value,
                                    "add_failures": result.add_failures,
                                    "remove_failures": result.remove_failures,
                                }
                                entry["label_error"] = label_error
                                label_errors.append(request.issue_number)
                                label_error_failures[request.issue_number] = _label_error_reason(
                                    label_error
                                )
                                save_state(self.paths.state_file, state)
                            continue
                        # Cap not exceeded: restore to rework_requested without
                        # incrementing redispatch_at, and emit a distinct event
                        # so the operator can see the environment conflict
                        # before it escalates.
                        entry["status"] = "rework_requested"
                        entry["dispatched_at"] = None
                        entry["blocked_environment_at"] = blocked_environment_at
                        state["issues"][str(request.issue_number)] = entry
                        state = append_event(  # event-consumer: audit-only -- records a pre-launch environment block (issue #1393) already enforced by the blocked_environment_at counter and the dispatch_blocked_environment escalation; consumed by tests/test_charlie_work.py regression tests.
                            state,
                            "rework_dispatch_blocked_environment",
                            {
                                "issue_number": request.issue_number,
                                "failure_kind": failure_kind,
                                "blocking_error": blocking_error,
                                "blocked_environment_count": len(blocked_environment_at),
                            },
                            state_path=self.paths.state_file,
                        )
                        save_state(self.paths.state_file, state)
                        continue
                    redispatch_at = _windowed_redispatch_at(
                        entry, window_minutes=self.config.watchdog.redispatch_window_minutes
                    ) + [now.isoformat().replace("+00:00", "Z")]
                    terminal_failure = failure_kind in DETERMINISTIC_ESCALATION_FAILURE_KINDS
                    # Issue #807: a deterministic judgment failure escalates
                    # immediately but as ``reason_class="judgment"``.
                    deterministic_judgment = (
                        failure_kind in DETERMINISTIC_JUDGMENT_ESCALATION_FAILURE_KINDS
                    )
                    immediate_escalation = terminal_failure or deterministic_judgment
                    if (
                        immediate_escalation
                        or len(redispatch_at) > self.config.watchdog.max_auto_redispatch
                    ):
                        # Escalate to human review
                        reason = (
                            failure_kind if immediate_escalation else "redispatch_cap_exceeded"
                        )
                        # Issue #783: dead worker session / redispatch cap is a
                        # process failure, not a judgment call -- mechanical.
                        # Issue #807: a deterministic judgment failure (genuine
                        # local commits) is a judgment call -- judgment.
                        reason_class = "judgment" if deterministic_judgment else "mechanical"
                        state = _escalate_issue(
                            state,
                            request.issue_number,
                            reason=reason,
                            reason_class=reason_class,
                            issue_extra={
                                "redispatch_at": redispatch_at,
                                "dispatched_at": None,
                            },
                        )
                        entry = state["issues"][str(request.issue_number)]
                        save_state(self.paths.state_file, state)
                        edge = _escalation_edge("redispatch_escalated", reason_class)
                        result = transition(
                            self.gh,
                            self.config.labels,
                            request.issue_number,
                            edge,
                        )
                        if result.outcome != TransitionOutcome.APPLIED:
                            label_error = {
                                "edge": edge,
                                "outcome": result.outcome.value,
                                "add_failures": result.add_failures,
                                "remove_failures": result.remove_failures,
                            }
                            entry["label_error"] = label_error
                            label_errors.append(request.issue_number)
                            label_error_failures[request.issue_number] = _label_error_reason(
                                label_error
                            )
                            save_state(self.paths.state_file, state)
                        continue
                    entry["status"] = "rework_requested"
                    entry["dispatched_at"] = None
                    entry["redispatch_at"] = redispatch_at
                    state["issues"][str(request.issue_number)] = entry
                    save_state(self.paths.state_file, state)
            rework_failure_map = _build_failure_map(
                dispatch_results,
                failed_issue_numbers,
                deferred_by_concurrency_full,
                rework_limit,
                extra_failures={**missing_prompt_failures, **label_error_failures},
            )
            state = append_event(
                state,
                "dispatch_rework",
                {
                    "pr_number": first_rework_pr_number,
                    "issue_numbers": sorted(successful_issue_numbers),
                    "failed_issue_numbers": sorted(failed_issue_numbers),
                    "skipped_issue_numbers": sorted(skipped_issue_numbers),
                    "deferred_by_concurrency": deferred_by_concurrency,
                    "deferred_by_concurrency_count": deferred_by_concurrency_count,
                    "label_errors": sorted(label_errors),
                    "operator_claimed_skipped": sorted(operator_claimed_skipped),
                    "failures": rework_failure_map,
                    # Issue #1014 (mirroring #1005): the capacity axis.
                    # Always present -- gov.report_fields() is safe to call
                    # unclamped -- and explicit about `clamped` so a reader
                    # does not have to redo the arithmetic. `dispatch_limit`
                    # is included explicitly (report_fields() does not carry
                    # it) because it is the only field that reflects a
                    # fleet-cap clamp.
                    "concurrency_governor": {
                        "clamped": gov.clamped,
                        "dispatch_limit": gov.dispatch_limit,
                        **gov.report_fields(),
                    },
                },
                state_path=self.paths.state_file,
            )
            save_state(self.paths.state_file, state)

        result_dicts = [result.to_dict() for result in dispatch_results]
        message = "rework dispatch complete"
        if failed_issue_numbers:
            entries = ", ".join(
                f"#{issue} ({rework_failure_map[issue]})" for issue in sorted(failed_issue_numbers)
            )
            message = f"rework dispatch failures: {entries}"
        if label_errors:
            message += f" (launched but label write failed: {sorted(label_errors)})"
        data = {
            "selected_count": len(successful_issue_numbers),
            "attempted_count": len(session_requests),
            "failed_count": len(failed_issue_numbers),
            "failures": rework_failure_map,
            "deferred_by_concurrency": deferred_by_concurrency,
            "deferred_by_concurrency_count": deferred_by_concurrency_count,
            "label_errors": sorted(label_errors),
            "session_manifest": str(manifest_path),
            "session_results": str(results_path),
            "sessions": [asdict(request) for request in session_requests],
            "dispatch_results": result_dicts,
            "routed_to_review": sorted(routed_to_review),
            "skipped_head_indeterminate": sorted(head_indeterminate),
            "review_blocked_retry": sorted(review_blocked_retry),
            "operator_claimed_skipped": sorted(operator_claimed_skipped),
            "no_op_rework_escalated": sorted(no_op_rework_escalated),
            "salvaged_to_review": sorted(salvaged_to_review),
            "blocked_environment_escalated": sorted(blocked_environment_escalated),
        }
        if gov.enabled or gov.fleet_enabled or gov.open_pr_enabled:
            data.update(gov.report_fields())

        # Emit notification digest if there are health transitions (stalled sessions)
        # This will be enhanced by #165 to include RUNAWAY/DEAD/escalated transitions
        sessions_dir = self._layout.sessions_dir
        stalled_entries = _detect_stalled_sessions(sessions_dir, self.config)
        if stalled_entries and self.config.notify.enabled:
            health_transitions: dict[int, dict[str, Any]] = {}
            for entry in stalled_entries:
                health_transitions[entry["issue"]] = {
                    "adapter_kind": "unknown",  # Will be filled by #165's full supervisor
                    "health": entry.get("health", "STALLED"),
                    "last_log_line": None,
                    "pid": entry.get("pid"),
                    "terminal_tool": entry.get("terminal_tool"),
                    "terminal_reason": entry.get("terminal_reason"),
                }
            digest = _build_attention_digest(
                self.paths.state_file,
                health_transitions,
                repo=self.repo_root.name,
            )
            if digest:
                emit_digest(self._layout.notify, digest)

        return CommandResult(
            not failed_issue_numbers,
            message,
            data,
        )

    def _salvage_rework_stranded_commits(
        self,
        issue_number: int,
        pr_data: dict[str, Any],
        issue_entry: dict[str, Any],
    ) -> bool:
        """Salvage-push stranded commits from a dead rework worker's worktree
        before the death-loop escalation gate fires (issue #1239).

        Returns ``True`` when the push succeeded (stranded commits were
        published); ``False`` for any non-push outcome (no stranded commits,
        divergence, remote-head-not-local, missing worktree/branch, or git
        error).  The caller treats a ``True`` result as "the death produced
        completed work — do NOT count it toward ``worker_death_loop``" and
        routes the issue to review instead of escalating.

        Reuses ``salvage_push_stranded_commits`` — the same sanctioned-git
        primitive the fresh-dispatch salvage lane uses (#1248): ls-remote
        before pushing (never trust the sidecar's ``push_succeeded``), never
        force-push, fast-forward only.  Records a state event so the salvage
        is observable even when the death-loop gate would have escalated.
        """
        live_head = pr_data.get("headRefOid")
        if not live_head:
            return False
        branch = issue_entry.get("branch_name") if isinstance(issue_entry, dict) else None
        if not branch:
            return False
        # Issue #1239 round-3: ``issue_entry`` comes from the
        # ``head_check_state`` snapshot loaded at the top of
        # ``dispatch_rework``'s candidate loop.  Between that snapshot and
        # this call the issue's status may have already moved off
        # ``rework_requested`` (e.g. a concurrent loop pass dispatched it,
        # escalated it, or the issue was closed).  Re-check under the state
        # lock BEFORE any network push — a salvage push to the shared origin
        # remote for an issue that is no longer rework_requested would be an
        # unaudited side effect with no event trail if it succeeded.  Mirrors
        # the precondition added to ``_reap_restore_rework_requested`` (which
        # checks ``status == "dispatched"`` because that lane handles
        # already-dispatched workers); this lane's eligible state is
        # ``rework_requested`` because ``dispatch_rework`` only selects
        # candidates with that status.  The network git push below stays
        # outside any lock; the event-recording state_lock scope further down
        # is still load-bearing (status can move again between this check and
        # that scope).
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            fresh_entry = state["issues"].get(str(issue_number), {})
            if (
                not isinstance(fresh_entry, dict)
                or fresh_entry.get("status") != "rework_requested"
            ):
                return False
        wt_path = worktree_path_for_branch(self.repo_root, branch, self._layout.worktrees)
        result = salvage_push_stranded_commits(
            self.repo_root,
            branch,
            wt_path,
            base_ref=self.config.dispatch.base_ref,
            dry_run=self.write_gate.dry_run,
        )
        if not result.pushed:
            return False
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            state = self.write_gate.append_event(
                state,
                "rework_stranded_commits_salvaged",
                {
                    "issue_number": issue_number,
                    "previous_status": "rework_requested",
                    "new_status": "rework_requested",
                    "reason": "death_loop_salvaged",
                    "commit_count": result.commit_count,
                    "old_remote_sha": result.old_remote_sha,
                    "new_remote_sha": result.new_remote_sha,
                },
            )
            self.write_gate.save_state(state)
        return True

    def _route_rework_candidate_to_review(
        self,
        issue_number: int,
        pr_number: int,
        reviewed_head_sha_before: str | None,
    ) -> tuple[bool, CommandResult]:
        """Route a rework_requested issue back to the review lane instead of
        relaunching a worker onto a PR whose rework was already pushed
        (issue #339): the PR head moved past the last request_changes verdict,
        so the previous worker's output is already live and a relaunch would
        find nothing to do, idle, and get watchdog-reaped.

        Reuses ``review()`` — the review lane's own packet-regeneration entry
        point — instead of duplicating its janitor/test-adequacy gating and
        label-transition logic here.

        Returns a ``(routed, review_result)`` pair. ``routed`` is True only
        when ``review()`` actually produced a fresh, undecided packet against
        the new head. ``review()`` has its own early-returns that leave
        GitHub/labels untouched — most notably the deterministic janitor gate
        (conflicting/draft/red-CI), which returns ``ok=False`` *before*
        writing any packet or firing the ``review_started`` transition, and
        without touching ``reviewed_head_sha``. Flipping the issue's status
        to "reviewing" in that case would desync state.json from GitHub
        reality (labels still say needs-rework, no packet exists) with no
        automated recovery path, since the issue would silently drop out of
        dispatch_rework's own candidate pool forever (issue #339 finding 1).
        So the status flip additionally requires ``review_result.ok`` on top
        of the pre-existing "no fresh decision recorded" check: ``review()``
        can itself invoke ``record_review`` (the test-adequacy hard gate
        re-failing on the new head), which already reconciles the issue's
        status and ``reviewed_head_sha`` — that path returns ``ok=True`` but
        must not be re-flipped here either, so both checks are required.

        When ``routed`` is False, the issue's status is left untouched
        (``rework_requested``), so the next dispatch_rework pass naturally
        retries — the block is often transient (e.g. a merge-train branch
        sync resolving a conflict).
        """
        review_result = self.review(pr_number)
        routed = False
        # review() can now return ok=True for a reason OTHER than "a fresh
        # review packet was produced": the janitor-gate conflict/no-op-rework
        # routing (_route_janitor_gate_failure_to_rework) also returns ok=True
        # when it re-requests rework, with no packet and no review_started
        # transition. That outcome must be treated the same as "review()
        # blocked" here -- the issue stays rework_requested for the next
        # dispatch_rework pass, not flipped to "reviewing" -- otherwise this
        # would desync state.json from GitHub reality exactly the way the
        # ok=False janitor-block case already guards against (issue #339
        # finding 1, see this method's docstring).
        routed_to_rework = bool(review_result.data.get("routed_to_rework"))
        # Issue #558: review() also returns ok=True when it converges a
        # CLOSED-unmerged PR's state entry to "closed" at the janitor gate.
        # The PR is dead, not a fresh-packet candidate, so flipping the issue
        # to "reviewing" here would strand it in an ACTIVE_STATE_STATUS no
        # reconcile rule clears while the GitHub issue stays open (the closed
        # PR still links to the issue, so issue_active_label_no_open_pr does
        # not fire; "reviewing" is a VALID_ISSUE_STATUSES member, so the
        # unknown-status recompute sweep skips it). The issue stays
        # rework_requested and the existing closed-unmerged issue-side
        # handling (closed_unmerged_pr_active_labels) finalizes it.
        closed_unmerged_converged = bool(review_result.data.get("closed_unmerged_converged"))
        # Issue #1078: a pending cross-family review means no packet was written.
        # The issue must NOT be flipped to "reviewing" — it stays
        # "rework_requested" for the next pass, same as the routed/blocked cases.
        cross_family_pending = bool(review_result.data.get("cross_family_pending"))
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            entry = state["issues"].get(str(issue_number), {})
            decision_unchanged = pr_state.get("reviewed_head_sha") == reviewed_head_sha_before
            if (
                review_result.ok
                and not routed_to_rework
                and not closed_unmerged_converged
                and not cross_family_pending
                and decision_unchanged
                and isinstance(entry, dict)
                and entry.get("status") == "rework_requested"
            ):
                state["issues"][str(issue_number)] = {**entry, "status": "reviewing"}
                routed = True
            state = append_event(
                state,
                "rework_already_pushed",
                {
                    "issue_number": issue_number,
                    "pr_number": pr_number,
                    "review_ok": review_result.ok,
                    "routed": routed,
                },
                state_path=self.paths.state_file,
            )
            save_state(self.paths.state_file, state)
        return routed, review_result

    def _merged_pr_referenced_issue_numbers(
        self,
        issues: list[dict[str, Any]],
        merged_prs: list[dict[str, Any]],
    ) -> tuple[set[int], set[int], set[int]]:
        """Return ready issues already covered by a merged PR, split by trust level.

        Returns a ``(bound, mention_only, bound_pr_numbers)`` triple:

        * ``bound`` — ``linked_issue_number`` binds the PR to the issue by a
          hijack-safe signal (same-repo branch-prefix or closing-action verb).
          This is the same trust level issue #220 uses to close issues at
          merge time, so callers MAY treat a bound issue as safe to close here
          too (belt-and-suspenders in case #220's merge-time close hasn't
          landed, e.g. a crash between merge and label transition).
        * ``mention_only`` — the PR merely contains an ``issue #N`` /
          ``issues #N`` text reference (same-repo PRs only — cross-repo
          provenance is never trusted here, and ``isCrossRepository`` only
          describes head-branch provenance, not which repo the *text* refers
          to, so it cannot resolve a cross-repo mention collision either).
          This is advisory only per ``issue_numbers_mentioned_by_pr``'s
          contract: issue #203 never authorized closing an issue on a bare
          mention. Callers MUST exclude these from dispatch and flag them for
          a human — never close the issue or transition it toward "merged".
        * ``bound_pr_numbers`` — the PR numbers that bound to a managed issue.
          Used to finalize state.json ``prs`` entries for externally-merged PRs
          (issue #427: Aviator mergequeue handoff).

        The bound/mention sets are intersected with the supplied issue set so a
        stray mention of an issue not in the dispatch queue does not get
        actioned. ``bound`` takes precedence: an issue bound by one merged PR
        but only mentioned by another is reported solely in ``bound``.
        """
        ready_issue_numbers = {int(issue["number"]) for issue in issues}
        bound: set[int] = set()
        bound_pr_numbers: set[int] = set()
        mention_only: set[int] = set()
        for pr in merged_prs:
            if str(pr.get("state") or "").upper() != "MERGED":
                continue
            issue_number = linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            )
            if issue_number is not None and issue_number in ready_issue_numbers:
                bound.add(issue_number)
                bound_pr_numbers.add(int(pr["number"]))
            # isCrossRepository describes the PR's own head-branch provenance
            # (fork vs. same-repo), not which repo a free-text "#N" refers to.
            # It cannot fully guard a cross-repo mention collision, but it does
            # guard the common case of a fork PR's text being trusted at all.
            if pr.get("isCrossRepository") is False:
                for mentioned in issue_numbers_mentioned_by_pr(pr):
                    if mentioned in ready_issue_numbers:
                        mention_only.add(mentioned)
        mention_only -= bound
        return bound, mention_only, bound_pr_numbers

    def _mention_rearmed_issue_numbers(
        self,
        mention_only: set[int],
        issues: list[dict[str, Any]],
        state: dict[str, Any],
        already_flagged: set[int],
    ) -> tuple[set[int], list[int]]:
        """Issue #1336: which mention-only issues have been re-armed by the
        operator and so must NOT be excluded from dispatch.

        Returns ``(rearmed, newly_detected)``:

        * ``rearmed`` -- the full set whose mention-only exclusion lifts
          (issues carrying the durable ``mention_rearmed_at`` marker plus
          issues whose re-arm is detected this pass).
        * ``newly_detected`` -- the subset of ``rearmed`` the caller should
          persist by stamping ``mention_rearmed_at``. Empty for the dry-run
          path, which never writes state.

        An issue lifts its mention-only exclusion only when it was flagged
        in a PRIOR pass (``already_flagged``) AND either the durable
        ``mention_rearmed_at`` marker is already set, or the operator has
        since removed ``agent:human-needed``. The label is read from the
        already-loaded ``issues`` objects (no new per-pass GitHub API call
        in the candidate filter -- the blast-radius concern the #564
        point-2 comment raised when it documented this as out of scope);
        the durable marker written by the caller means subsequent passes
        key the lift off the state signal alone.

        Safe default preserved (#564 / acceptance criterion 2): an issue
        never flagged, flagged this pass, or flagged and still carrying
        ``agent:human-needed`` stays excluded. ``bound`` exclusions are
        never lifted here -- those PRs genuinely bound to the issue by a
        hijack-safe signal.
        """
        issue_labels_by_number = {int(issue["number"]): label_names(issue) for issue in issues}
        rearmed: set[int] = set()
        newly_detected: list[int] = []
        for issue_number in mention_only:
            # Only issues flagged in a PRIOR pass can be re-armed. Issues
            # flagged this pass just had agent:human-needed applied and
            # must stay excluded; never-flagged issues have no flag to
            # re-arm through.
            if issue_number not in already_flagged:
                continue
            entry = state.get("issues", {}).get(str(issue_number), {})
            if not isinstance(entry, dict):
                continue
            if entry.get("mention_rearmed_at"):
                # Durable re-arm marker from a prior pass -- the lift stays.
                rearmed.add(issue_number)
                continue
            # Flagged before, not yet recorded as re-armed: detect the
            # operator's agent:human-needed removal from the already-loaded
            # issue labels. The caller stamps mention_rearmed_at so future
            # passes key off state, not the label snapshot.
            if self.config.labels.human_needed not in issue_labels_by_number.get(
                issue_number, set()
            ):
                rearmed.add(issue_number)
                newly_detected.append(issue_number)
        return rearmed, newly_detected

    def _stamp_mention_rearm(
        self,
        state: dict[str, Any],
        newly_rearmed: list[int],
    ) -> dict[str, Any]:
        """Issue #1336: durably stamp ``mention_rearmed_at`` and emit the
        ``dispatch_merged_pr_mention_rearmed`` event for issues the operator
        re-armed this pass.

        Routed through WriteGate (Convention A: ``self.write_gate.*``) so the
        R9 shrink-only ratchet on workflow.py's raw-primitive count (issue
        #1264 W6 PR4) is not increased -- the re-arm writes are new territory
        this wave does not convert, and a raw ``append_event``/``save_state``
        pair would trip the ratchet (baseline 266). The existing flag block in
        ``_dispatch_impl`` stays raw (it is part of the ratchet's baseline);
        only the NEW re-arm writes go through the gate.

        Returns ``state`` (possibly updated by ``append_event``). In dry-run
        mode the gate no-ops and ``state`` is returned unchanged -- but this
        method is only called from the non-dry-run dispatch path (the dry-run
        early return precedes it), so the dry-run no-op is defence-in-depth.
        """
        for issue_number in newly_rearmed:
            _ra_key = str(issue_number)
            _ra_entry = state["issues"].get(_ra_key, {})
            state["issues"][_ra_key] = {
                **_ra_entry,
                "number": issue_number,
                "mention_rearmed_at": utc_now(),
            }
        if newly_rearmed:
            state = self.write_gate.append_event(
                state,
                "dispatch_merged_pr_mention_rearmed",
                {"issue_numbers": sorted(newly_rearmed)},
            )
            self.write_gate.save_state(state)
        return state

    def _is_dispatchable(
        self,
        issue: dict[str, Any],
        operator_claimed: set[int] | None = None,
    ) -> bool:
        # Closed issues are never dispatchable, regardless of labels.
        if str(issue.get("state") or "OPEN").upper() != "OPEN":
            return False
        names = label_names(issue)
        if self.config.labels.ready not in names:
            return False
        if names & self.config.labels.terminal:
            return False
        if names & self.config.labels.active:
            return False
        if operator_claimed is None:
            state = load_state_locked(self.paths.state_file)
            operator_claimed = operator_claimed_issues(state)
        return int(issue["number"]) not in operator_claimed

    def _route_phantom_live_worker(
        self,
        state: dict[str, Any],
        request: SessionRequest,
        full_issue: dict[str, Any],
        sessions_dir: Path,
    ) -> tuple[str, str | None, dict[str, Any]]:
        """Route a phantom ``live_worker_redispatch_averted`` result as dead.

        The adapter reported a live worker, but the recorded PID failed the
        OS-level liveness + identity check (issue #523). Remove the stale
        sidecar/marker so the session no longer occupies a concurrency slot,
        then strip active labels and restore ``automated-ready`` so the issue
        is dispatchable again, recording a single
        ``session_failed_relabeled`` attention event.

        This mirrors ``_classify_dead_sessions_and_update_throttle_state``'s
        no-open-PR relabel path. The open-PR/rework-routing case is
        intentionally NOT handled here: a dispatched request's issue can never
        have an open tracked PR, because ``_dispatch_impl`` builds
        ``pr_by_issue`` once and candidate selection excludes every issue in
        it (so ``request.issue_number`` is never in ``pr_by_issue``). A phantom
        worker whose issue later opens a PR is routed to rework by the
        dead-session reaper lane, not by dispatch.

        Issue #1122: before reaping, inspect the worktree using the same
        ``inspect_worktree_state`` single enforcement point the reaper lane
        uses (issue #252). If the worktree is COMPLETED or the worker reported
        a successful push (``.worker-outcome.json`` with
        ``push_succeeded=true``), do NOT reap the sidecar or strip labels --
        leave the sidecar untouched so the reaper lane
        (``_classify_dead_sessions_and_update_throttle_state``) can salvage the
        pushed branch on a subsequent pass. Reaping here would destroy the
        sidecar the reaper lane is keyed off, making salvage impossible and
        escalating review-ready pushed work to a human.

        Returns ``(status, dispatched_at, state)``. The status is
        ``"dispatch_failed"`` so the caller's entry-building frees the slot;
        ``dispatched_at`` is ``None`` because no worker was actually launched.
        """
        issue_number = request.issue_number

        # Issue #1122: inspect the worktree before reaping. A completed or
        # push-succeeded worktree must be left for the reaper lane's salvage
        # path (_attempt_salvage). Reaping the sidecar here would destroy the
        # key the reaper lane iterates over, making salvage impossible.
        # Issue #1130: relax the preserve condition from ``COMPLETED`` to
        # ``ahead_count > 0`` — a worktree with committed-but-unpushed work
        # that also has shim/scaffolding dirt (not in ``injected_paths``)
        # classifies as PARTIAL, not COMPLETED, but the committed work is
        # still salvageable. The reaper lane's salvage condition was relaxed
        # to match (see ``_classify_dead_sessions_and_update_throttle_state``).
        phantom_workers = [w for w in iter_workers(sessions_dir) if w.issue_number == issue_number]
        for w in phantom_workers:
            worktree_path = Path(w.worktree_path)
            inspection = inspect_worktree_state(
                worktree_path,
                self.config.dispatch.base_ref,
                self.config.dispatch.injected_paths,
                self.config.dispatch.materialize_dirs,
            )
            worker_outcome = read_worker_outcome(worktree_path)
            reported_push = (
                isinstance(worker_outcome, dict)
                and worker_outcome.get("push_succeeded") is True
                and worker_outcome.get("pr_created") is False
            )
            if inspection.ahead_count > 0 or reported_push:
                # Preserve the sidecar so the reaper lane can salvage. Do NOT
                # strip labels -- the issue should stay in its active state
                # until salvage moves it to pr_open, preventing re-dispatch
                # into the occupied worktree.
                state = _emit_session_failed_relabeled(
                    state,
                    issue_number=issue_number,
                    reason="phantom_live_worker_completed_work_preserved",
                    failure_kind="live_worker_redispatch_averted",
                    removed_labels=[],
                    added_ready=False,
                    label_write_ok=True,
                    worktree_state=inspection.state.value,
                    reported_push=reported_push,
                    state_path=self.paths.state_file,
                    write_gate=self.write_gate,
                )
                return "dispatch_failed", None, state

        # Reap the stale sidecar and matching worktree writer marker. Reuse
        # WorkerView.reap_sidecar so the adapter-specific path derivation and
        # session-id-gated marker removal stay in one place.
        for w in phantom_workers:
            w.reap_sidecar(sessions_dir)

        # Strip active labels and ensure the ready label is present so the
        # issue becomes dispatchable. This mirrors
        # _classify_dead_sessions_and_update_throttle_state's no-open-PR
        # relabel path, gated on an active label actually being present so a
        # terminal-only issue is never given ``ready`` back spuriously.
        issue_labels = label_names(full_issue)
        active_labels = issue_labels & self.config.labels.active
        if not active_labels:
            state = _emit_session_failed_relabeled(
                state,
                issue_number=issue_number,
                reason="phantom_live_worker_pid_dead",
                failure_kind="live_worker_redispatch_averted",
                removed_labels=[],
                added_ready=False,
                label_write_ok=True,
                state_path=self.paths.state_file,
                write_gate=self.write_gate,
            )
            return "dispatch_failed", None, state

        needs_ready = self.config.labels.ready not in issue_labels
        label_write_ok = True
        for label in sorted(active_labels):
            if not self.gh.remove_issue_label(issue_number, label):
                label_write_ok = False
        if needs_ready:
            if not self.gh.add_issue_label(issue_number, self.config.labels.ready):
                label_write_ok = False
        state = _emit_session_failed_relabeled(
            state,
            issue_number=issue_number,
            reason="phantom_live_worker_pid_dead",
            failure_kind="live_worker_redispatch_averted",
            removed_labels=sorted(active_labels),
            added_ready=needs_ready,
            label_write_ok=label_write_ok,
            state_path=self.paths.state_file,
            write_gate=self.write_gate,
        )
        return "dispatch_failed", None, state

    def _prefetch_blocker_data(self, issues: list[dict[str, Any]]) -> None:
        """Warm the GitHub client's per-pass cache for blocker lookups.

        ``status()`` runs ``_get_open_blockers`` once per ready issue via both
        ``_filter_blocked_issues`` and ``_summarize_issue`` -- and until issue
        #870, each call issued a live, uncached `gh api .../dependencies/
        blocked_by` request plus one live `gh issue view` per declared
        blocker, entirely serially. Measured on the live fleet registry: 62
        ready issues drove 169s of a 184s `fleet status --json` run through
        this exact path, including confirmed duplicate fetches (issues #887/
        #888 each fetched twice; their shared blocker #886 fetched 4 times).

        This method does the equivalent fetching *once* per unique resource
        before any of the unmodified per-issue code below runs:

          1. Fetch all ready issues' GitHub-native dependencies in a single
             batched GraphQL query when the GitHub client supports it. The
             client falls back to per-issue REST calls when the query cannot
             be built (no git remote, no gh auth, etc.).
          2. Union those dependencies with each issue's body-declared
             blockers (pure Python, no I/O) into one deduplicated set of
             blocker issue numbers.
          3. Resolve open/closed state for that whole set in a single
             ``are_issues_open`` call, which itself batches cache misses in
             one GraphQL query when possible (see github.py).

        Both fetch layers cache into ``self.gh._list_cache``, so every
        subsequent call to ``_get_open_blockers`` -- unchanged, still called
        once per issue from two separate call sites -- resolves entirely
        from the warm cache with no further network calls. Structuring it
        this way (fetch each unique resource exactly once, then let the
        existing serial consumers read a warm cache) avoids relying on a
        cache race between concurrent callers to naturally dedupe: nothing
        here fetches the same issue number from two threads at once.

        Must be called once per ``status()`` invocation, before the first
        call to ``_get_open_blockers`` (directly or via
        ``_filter_blocked_issues`` / ``_summarize_issue``). Harmless to skip
        (callers just fall back to the prior, slower, uncached behavior) but
        never harmful to call twice -- the second call is a no-op cache hit.
        """
        issue_numbers = [int(issue["number"]) for issue in issues]
        if not issue_numbers:
            return

        if hasattr(self.gh, "issue_dependencies"):
            try:
                deps_by_number = self.gh.issue_dependencies(issue_numbers)
            except (GitHubError, OSError, ValueError, TypeError):
                # The batch method should fall back internally, but if it
                # raises for any reason, fall back to the per-issue function.
                deps_by_number = {
                    number: get_github_issue_dependencies(self.gh, number)
                    for number in issue_numbers
                }
        else:
            # Test doubles and older GitHub-like objects without the batch method.
            deps_by_number = {
                number: get_github_issue_dependencies(self.gh, number) for number in issue_numbers
            }

        all_blockers: set[int] = set()
        for issue in issues:
            issue_number = int(issue["number"])
            all_blockers.update(parse_blockers(issue.get("body", "")))
            all_blockers.update(deps_by_number.get(issue_number, []))

        if all_blockers:
            self.gh.are_issues_open(sorted(all_blockers))

    def _get_open_blockers(self, issue: dict[str, Any]) -> tuple[list[int], list[int]]:
        """Check if an issue has any open blocker issues.

        Parses the issue body for blocker declarations and checks GitHub's
        native issue dependencies. Returns both declared blockers and open blockers.

        Args:
            issue: The issue dict from GitHub API

        Returns:
            Tuple of (declared_blockers, open_blockers). Both are lists of issue numbers.
            declared_blockers includes all blockers mentioned in the issue body or
            GitHub dependencies. open_blockers is the subset that are currently open.
        """
        return _get_open_blockers_for_issue(self.gh, issue)

    @staticmethod
    def _is_dead_blocker(
        blocker_number: int,
        state: dict[str, Any],
        pr_by_issue: dict[int, dict[str, Any]],
    ) -> bool:
        """True when a blocker issue can never resolve through any automated path.

        Used by dispatch()'s blocked-chain attention check: "dead" means the
        blocker issue itself is escalated, or its tracked open PR's status is
        escalated/janitor_blocked. Pure local-state lookup, no GitHub calls --
        this only names an already-known dead end, it never widens one.

        Issue #1133: ``janitor_blocked`` conflates a durably-stuck population
        (failed checks, merge conflict, body gate, CI-never-created) with a
        transient one -- a brand-new PR whose required checks simply haven't
        reported yet, which self-heals within one CI cycle. The transient
        case is identified structurally by ``is_missing_checks_only_block``
        (the SOLE janitor failure is "Required check(s) missing") combined
        with the absence of a ``ci_run_never_created_head`` marker (which
        would mean CI was confirmed to have never started for this head -- a
        durable condition). Such a PR is NOT dead: it is actively progressing
        and will unblock on the next janitor pass once CI reports. The
        ``escalated`` status stays dead unconditionally.
        """
        issue_entry = state.get("issues", {}).get(str(blocker_number), {})
        if isinstance(issue_entry, dict) and issue_entry.get("status") == "escalated":
            return True
        pr = pr_by_issue.get(blocker_number)
        if pr is not None:
            pr_number = pr.get("number")
            if pr_number is not None:
                pr_state = state.get("prs", {}).get(str(pr_number), {})
                pr_status = pr_state.get("status")
                if pr_status == "escalated":
                    return True
                if pr_status == "janitor_blocked":
                    # Issue #1133: a brand-new PR whose only janitor failure is
                    # "Required check(s) missing" (checks not reported yet) is
                    # transient, not dead -- unless ``ci_run_never_created_head``
                    # is set, which means CI was confirmed to have never started
                    # for this head (the durable population the alert exists for).
                    # Branch on the structured flag, never on failure-message
                    # text (same rule as is_draft_only_block consumers).
                    if pr_state.get("is_missing_checks_only_block") and not pr_state.get(
                        "ci_run_never_created_head"
                    ):
                        return False
                    return True
        return False

    def _filter_blocked_issues(
        self, candidates: list[dict[str, Any]]
    ) -> tuple[list[dict[str, Any]], dict[int, list[int]], dict[int, list[int]]]:
        """Filter out issues with open blockers from the candidate list.

        This is a shared helper used by both dry-run and real dispatch paths
        to ensure single-point-of-enforcement for the dependency gate logic.

        Args:
            candidates: List of candidate issue dicts from GitHub API

        Returns:
            Tuple of (filtered_candidates, blocked_issues, open_blockers_by_issue).
            filtered_candidates is the input list with blocked issues removed.
            blocked_issues maps blocked issue numbers to their full declared
            blocker list (open + closed) -- unchanged, this is the exact
            shape the dispatch_skip_blocked event payload has always used.
            open_blockers_by_issue maps the same issue numbers to only the
            currently-open subset: a closed blocker isn't actually blocking
            anymore, so it must not count when deciding whether every
            blocker of an issue is "dead" (see dispatch()'s blocked-chain
            attention check).
        """
        blocked_issues: dict[int, list[int]] = {}
        open_blockers_by_issue: dict[int, list[int]] = {}
        for issue in candidates:
            issue_number = int(issue["number"])
            declared_blockers, open_blockers = self._get_open_blockers(issue)
            if open_blockers:
                blocked_issues[issue_number] = declared_blockers
                open_blockers_by_issue[issue_number] = open_blockers

        filtered_candidates = [
            issue for issue in candidates if int(issue["number"]) not in blocked_issues
        ]
        return filtered_candidates, blocked_issues, open_blockers_by_issue

    def _sort_by_dependency_depth(self, candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Sort unblocked candidates by out-degree (number of blocked dependents).

        Prioritizes issues that block the most downstream issues, so a wave
        drains the critical path and maximizes unblocking. Issues are sorted
        descending by their count of currently-blocked dependents, with
        creation date (oldest first) as a tiebreaker.

        This metric is computed against the full ready-labeled issue set
        before filtering, not just the unblocked candidates, to capture
        the true unblocking impact of each issue.

        Args:
            candidates: List of unblocked candidate issue dicts from GitHub API

        Returns:
            List of candidates sorted by out-degree (descending), then by creation date.
        """
        if not candidates:
            return []

        # Fetch the full set of ready-labeled issues to compute out-degree
        # We need issues that are blocked (not just candidates) to count dependents
        ready_issues = self.gh.issue_list(
            labels=[self.config.labels.ready],
            state="OPEN",
        )

        # Build reverse-adjacency map: blocker_number -> [dependents that are still blocked]
        blocker_to_dependents: dict[int, list[int]] = {}

        for issue in ready_issues:
            issue_number = int(issue["number"])
            declared_blockers, open_blockers = self._get_open_blockers(issue)

            # Only count dependents that are currently blocked (have open blockers)
            if not open_blockers:
                continue

            for blocker in declared_blockers:
                if blocker not in blocker_to_dependents:
                    blocker_to_dependents[blocker] = []
                blocker_to_dependents[blocker].append(issue_number)

        # Compute out-degree for each candidate (number of blocked dependents)
        out_degree: dict[int, int] = {}
        for issue in candidates:
            issue_number = int(issue["number"])
            out_degree[issue_number] = len(blocker_to_dependents.get(issue_number, []))

        # Sort by out-degree (descending), then by creation date (ascending for oldest-first)
        def sort_key(issue: dict[str, Any]) -> tuple[int, str]:
            issue_number = int(issue["number"])
            # Use negative out_degree for descending sort
            degree = -out_degree.get(issue_number, 0)
            # Parse creation date; if missing, use high sentinel to sort last
            created_at = issue.get("createdAt", "9999-12-31T23:59:59Z")
            return (degree, created_at)

        return sorted(candidates, key=sort_key)

    def _sort_by_dispatch_order(self, candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """Sort candidates by dispatch order (oldest-first or newest-first).

        Uses the createdAt field from GitHub API to sort by creation date.
        Default is oldest-first (ascending), but can be configured to newest-first
        (descending) via dispatch.order config.

        Args:
            candidates: List of candidate issue dicts from GitHub API

        Returns:
            Sorted list of candidates by creation date according to dispatch.order
        """
        if self.config.dispatch.order == "newest":
            # Sort by createdAt descending (newest first)
            return sorted(
                candidates,
                key=lambda issue: issue.get("createdAt", ""),
                reverse=True,
            )
        else:
            # Sort by createdAt ascending (oldest first, default)
            return sorted(
                candidates,
                key=lambda issue: issue.get("createdAt", ""),
                reverse=False,
            )

    def _branch_name(self, issue: dict[str, Any]) -> str:
        return f"{self.config.dispatch.branch_prefix}-{int(issue['number'])}-{slugify(str(issue.get('title') or 'work'))}"

    def _render_issue_comments(self, issue: dict[str, Any]) -> str:
        """Render the ``$issue_comments`` slot for a worker prompt (issue #872).

        The comments are already in hand: every ``_write_worker_prompt`` call
        site sources its issue from ``gh.issue_view``, and ``ISSUE_VIEW_FIELDS``
        has always requested ``comments``. This adds no API call -- the data was
        being fetched and discarded.

        Bodies are defanged here rather than in ``issue_comments`` itself so
        that module stays free of the GitHub layer; the defang is what stops a
        comment's "closes #123" from auto-closing an unrelated issue when a
        worker copies the text into its PR body.
        """
        dispatch = self.config.dispatch
        return render_issue_comments(
            issue.get("comments"),
            included_associations=dispatch.worker_prompt_comment_associations,
            excluded_authors=dispatch.worker_prompt_excluded_comment_authors,
            max_comments=dispatch.worker_prompt_max_comments,
            max_chars=dispatch.worker_prompt_max_comment_chars,
            sanitize=defang_closing_keywords,
        )

    def _build_module_map_value(self, issue_number: int) -> str:
        """Derive the module-map section from the live tree (issue #1444).

        Single point of enforcement for the fail-soft contract: a repo layout
        ``build_module_map`` cannot parse yields an empty string (an omitted
        section) plus a ``worker_module_map_failed`` warning event logged to
        events.db, never a dispatch failure. The worker loses placement
        steering for this one packet; the next packet rebuilds the map against
        the then-current tree.

        ``log_event`` (not ``self._record_event``) is used because
        ``_write_worker_prompt`` runs outside a state-lock context -- the
        caller (``intake`` / ``_dispatch_impl``) gathers network results and
        builds prompts before taking the state lock for label/status writes.
        """
        package_dir = self.repo_root / "src" / "charlie_work"
        src_root = self.repo_root / "src"
        try:
            return build_module_map(package_dir, src_root)
        except (OSError, SyntaxError, ValueError) as exc:
            log_event(
                self.paths.state_file,
                "worker_module_map_failed",
                {
                    "issue_number": issue_number,
                    "error": f"{type(exc).__name__}: {exc}",
                },
                repo=self.repo_root.name,
                level="warning",
            )
            return ""

    def _build_attachment_budget_value(self, issue_number: int) -> str:
        """Derive the attachment-budget dispatch clause (issue #1460).

        Marker-file presence is the ONLY activation switch: a repo that has
        never run `attachment_contracts baseline` (no `.attachment-budgets.json`
        at the repo root) gets an empty clause, silently -- this feature is
        opt-in per repo, not a default every worker prompt must carry.

        When the marker file IS present, its structural validity is checked
        via `baseline.load` (not just existence) before the clause is
        emitted, so a hand-corrupted or tampered baseline never ships
        placement instructions that reference a broken `check-file` command.
        Fail-soft, mirroring `_build_module_map_value`'s contract exactly: a
        `TamperError` yields an empty clause (omitted section) plus a
        `worker_attachment_budget_failed` warning event, never a dispatch
        failure.

        `log_event` (not `self._record_event`) is used for the same reason
        `_build_module_map_value` uses it: `_write_worker_prompt` runs
        outside a state-lock context, so the module-level, lock-free
        primitive is the only one available here.
        """
        marker_path = self.repo_root / attachment_baseline.BASELINE_FILENAME
        if not marker_path.is_file():
            return ""
        try:
            attachment_baseline.load(marker_path)
        except (attachment_baseline.TamperError, OSError, ValueError) as exc:
            # ``TamperError`` covers baseline's own structural checks
            # (schema version, entry shape, duplicate keys); ``ValueError``
            # additionally covers a bare ``json.JSONDecodeError`` (a subclass
            # of ``ValueError``) from genuinely malformed JSON, which
            # ``baseline.loads`` does not wrap into a ``TamperError`` itself.
            # ``OSError`` guards a read race between the ``is_file()`` check
            # above and this read. Mirrors ``hook_entry._resolve_mode``'s
            # except clause for the same reason.
            log_event(
                self.paths.state_file,
                "worker_attachment_budget_failed",
                {
                    "issue_number": issue_number,
                    "error": str(exc),
                },
                repo=self.repo_root.name,
                level="warning",
            )
            return ""
        return _ATTACHMENT_BUDGET_CLAUSE

    def _write_worker_prompt(
        self, issue: dict[str, Any], *, template: str | None = None, dry_run: bool = False
    ) -> Path:
        issue_number = int(issue["number"])
        issue_dir = self.paths.issues / f"issue-{issue_number}"
        prompt_path = issue_dir / "worker-prompt.md"
        prompt = self._render(
            template or self.config.dispatch.worker_template,
            {
                "issue_number": issue_number,
                "issue_title": issue.get("title", ""),
                "issue_url": issue.get("url", ""),
                # The raw body stays available to templates; no shipped one
                # references it since #883, but rendering it bare is a
                # legitimate thing for a template to want.
                "issue_body": issue.get("body", ""),
                # Pre-fenced, not bare: the fence width depends on the body's
                # own backtick runs, so it cannot be written in the template
                # (#883). ``or ""`` guards a null body, which would otherwise
                # reach the regex as None.
                "issue_body_block": fenced_block(str(issue.get("body") or ""), "md"),
                "issue_comments": self._render_issue_comments(issue),
                "branch_name": self._branch_name(issue),
                "worker_model_tier": self.config.dispatch.worker_model_tier,
                # Issue #1444: the module-map section, derived from the live
                # tree at packet build time. Fail-soft: a parse failure yields
                # an empty string (omitted section) plus a
                # ``worker_module_map_failed`` warning event, never a dispatch
                # failure. ``_build_module_map_value`` is the single point of
                # enforcement for that fail-soft contract.
                "module_map": self._build_module_map_value(issue_number),
                # Issue #1460: the attachment-point placement clause, gated
                # solely on `.attachment-budgets.json`'s presence. Fail-soft
                # like module_map: a malformed baseline yields an empty
                # string (omitted clause) plus a
                # ``worker_attachment_budget_failed`` warning event.
                "attachment_budget": self._build_attachment_budget_value(issue_number),
            },
        )
        # Issue #714: enforce the no-merge contract on the *rendered output*
        # so a repo-local flat override that drops $section_no_merge_contract
        # is caught at the dispatch boundary rather than shipping a worker
        # with no instruction against merging/closing/relabeling its own PR.
        assert_no_merge_contract(prompt, context=f"worker prompt for issue #{issue_number}")
        # Issue #715: enforce the conventional-commit title instruction on the
        # *rendered output* so a repo-local flat override that mandates a stale
        # non-conventional-commit title format (e.g. 'Fix #N: ...') is caught
        # at the dispatch boundary rather than shipping a worker whose every PR
        # trips the janitor's _check_title_conventional warning.
        assert_conventional_commit_title(
            prompt, context=f"worker prompt for issue #{issue_number}"
        )
        # Issue #717: enforce the execution-contract escalation trigger on the
        # *rendered output* so a repo-local flat override that drops
        # $section_execution_contract — leaving a blanket "never run the full
        # local suite" prohibition with no carve-out for contract-changing diffs
        # (public function signature/return shape, exception type/message
        # consumed elsewhere, DB schema, or module re-export) — is caught at the
        # dispatch boundary rather than shipping a worker who can change a
        # contract surface and push without ever exercising the wider suite.
        assert_execution_contract(prompt, context=f"worker prompt for issue #{issue_number}")
        # Issue #1010: enforce the widened containment clause on the *rendered
        # output* so a repo-local flat override that drops
        # $section_scope_contract or reverts to the old repo-scoped wording
        # (which does not cover a different repo) is caught at the dispatch
        # boundary rather than shipping a worker with no effective prohibition
        # against editing a sibling repo's checkout.
        assert_containment(prompt, context=f"worker prompt for issue #{issue_number}")
        # Issue #618: the dry-run dispatch branch promises "skip all state
        # writes, label transitions, and file mutations" — mkdir + write_text
        # here would violate that, and for a dead-worker recovery candidate
        # (previous status "dispatched", same branch) would silently overwrite
        # the prompt a crashed worker was launched with, destroying the
        # forensic record the preview was meant to inspect. The assertions
        # above are validation on the rendered text, not file mutations, so
        # they stay — a broken template should fail the preview too.
        if not dry_run:
            issue_dir.mkdir(parents=True, exist_ok=True)
            prompt_path.write_text(prompt, encoding="utf-8")
        return prompt_path

    def _write_rework_prompt(
        self, pr: dict[str, Any], issue_number: int | None, dispatch_note: str
    ) -> Path:
        return _write_rework_prompt(
            self.paths.state_file,
            pr,
            issue_number,
            dispatch_note,
            self.config,
            repo_root=self.repo_root,
        )

    def _fetch_commit_retrying(self, sha: str, *, leg: str) -> tuple[dict[str, Any] | None, str]:
        """Thin delegate to ``queue_sync_coverage._fetch_commit_retrying``.

        Kept as a bound method (rather than inlining the free-function call
        at each call site) so any existing or future monkeypatch of
        ``self._fetch_commit_retrying`` keeps working, mirroring
        ``_write_rework_prompt``'s wrapper shape.
        """
        return _fetch_commit_retrying(self.gh, sha, leg=leg)

    def _fetch_compare_retrying(
        self, base: str, head: str, *, leg: str
    ) -> tuple[dict[str, Any] | None, str]:
        """Thin delegate to ``queue_sync_coverage._fetch_compare_retrying``."""
        return _fetch_compare_retrying(self.gh, base, head, leg=leg)

    def _queue_sync_merge_covered(
        self,
        pr: dict[str, Any],
        reviewed_head_sha: str | None,
        live_head_sha: str | None,
    ) -> _QueueSyncCoverageResult:
        """Thin delegate to ``queue_sync_coverage._queue_sync_merge_covered``.

        See that function's docstring for the full four-condition predicate
        (issue #1194) and the retry/indeterminate contract (job-cannon PRs
        #1888, #1916, #1904, #1895).

        ``queue_sync_coverage.py`` is deliberately pure (issue #1264's
        per-module WriteGate raw-primitive-call ratchet -- a new module
        starts at baseline 0, so a raw ``log_event`` call moved there would
        read as new growth even though it was already present, and already
        counted, in this file). This wrapper therefore emits the
        ``unauthorized_merge_queue_sync_covered`` audit event itself on a
        covered result, exactly where that raw call already lived (and was
        already counted) before the extraction.
        """
        queue_bot_login = self.config.auto_merge.queue_bot_login
        result = _queue_sync_merge_covered(
            self.gh,
            queue_bot_login,
            pr,
            reviewed_head_sha,
            live_head_sha,
        )
        if result.covered:
            log_event(
                self.paths.state_file,
                "unauthorized_merge_queue_sync_covered",
                {
                    "pr": pr.get("number"),
                    "reviewed_head_sha": reviewed_head_sha,
                    "live_head_sha": live_head_sha,
                    "sync_parent": result.sync_parent,
                    "pre_merge_base": result.pre_merge_base,
                    "queue_bot_login": queue_bot_login,
                },
            )
        return result

    def _detect_unauthorized_merges(
        self, merged_prs: list[dict[str, Any]] | None = None
    ) -> list[dict[str, Any]]:
        """Scan recently-merged PRs for worker branches whose merged head does not match an approved review decision.

        Workers are forbidden from merging their own PRs (issue #502). This
        post-merge tripwire catches a bypass after it happens: any merged PR
        whose head branch matches the configured worker branch prefix and whose
        head SHA is not covered by an approved ``.var/charlie-work/prs/pr-N/review-decision.json``
        was merged without the orchestrator's adversarial review gate. GitHub
        errors are swallowed so a transient ``gh`` failure cannot crash the
        fleet pass.

        Findings are bounded to merges this control could actually have governed
        — see ``_apply_unauthorized_merge_baseline``, which every return path
        goes through so the bound cannot be bypassed by a future caller.
        """
        candidates: list[dict[str, Any]] = []
        prefix = self.config.dispatch.branch_prefix
        # Capture the review-dispatch gate state at detection time so the finding
        # describes the moment it was made, not the moment it is later read back
        # (issue #975). Config is mutable and unversioned in events.db, so once
        # the operator flips ``enabled`` to True, every historical
        # ``decision: "missing"`` finding becomes permanently ambiguous -- was
        # the gate off (expected steady state) or on (a genuine bypass)? This
        # boolean is the only point where the answer is knowable, and it is a
        # record, not a suppressor: the finding still fires, still pins
        # ok=False, and still requires an explicit ack.
        review_dispatch_enabled = self.config.review_dispatch.enabled
        if merged_prs is None:
            try:
                merged_prs = self.gh.merged_pr_list()
            except GitHubError as exc:
                # No list means nothing observed, not "nothing wrong" — return
                # empty without arming, so a transient gh failure on the very
                # first pass cannot bake an empty baseline and permanently
                # exempt the real history it never saw.
                #
                # This covers every raising failure in merged_pr_list(): gh
                # missing, unparseable JSON, non-zero exit, AND gh exiting 0
                # with empty stdout (the silent-empty case #633 closed —
                # merged_pr_list() now raises GitHubError on a non-list result
                # instead of coercing None to []). The empty-stdout path no
                # longer arms an empty baseline silently; it is reported here
                # as a raising failure and the next pass re-arms from real
                # data.
                #
                # Failing open is correct; failing open *silently* is not. Record
                # that the control did not run (issue #937) — without this the
                # pass reports ok=True and is byte-identical in every stored
                # artifact to a pass where the tripwire ran and found nothing,
                # discarding the very distinction #633 created upstream when it
                # made merged_pr_list() raise instead of coercing to [].
                self._record_unauthorized_merge_skip(exc)
                return []

        for pr in merged_prs:
            if str(pr.get("state") or "").upper() != "MERGED":
                continue
            if pr.get("isCrossRepository") is True:
                continue
            head = str(pr.get("headRefName") or "")
            if not head.startswith(prefix):
                continue
            raw_number = pr.get("number")
            try:
                pr_number = int(raw_number) if raw_number is not None else None
            except (TypeError, ValueError):
                continue
            if pr_number is None:
                continue
            decision = self._review_decision(pr_number)
            decision_value = decision.get("decision")
            reviewed_head_sha = decision.get("reviewed_head_sha")
            live_head_sha = pr.get("headRefOid")
            approved = decision_value == "approved"
            head_matches = (
                reviewed_head_sha is not None
                and live_head_sha is not None
                and reviewed_head_sha == live_head_sha
            )
            # Issue #934: an explicit operator authorization recorded at merge
            # time is as authoritative as an approved review decision. Without
            # this, every legitimate operator merge of a worker PR (stale
            # decision, absent decision, or pending after rebase) becomes a
            # finding that pins ok=False until someone writes a retrospective
            # ack. The override is SHA-bound and reason-bearing — see
            # ``_authorized_override_matches`` — so it does not weaken the
            # control: an unrecorded merge is still a finding, and a rebase
            # after authorization invalidates the override exactly as it
            # invalidates an approved decision.
            override_authorized = _authorized_override_matches(decision, live_head_sha)
            # Issue #1194: an approved decision whose head moved may be an
            # Aviator queue sync-merge of the approved head — structurally a
            # false positive. Recognized only under the fail-closed
            # four-condition predicate in _queue_sync_merge_covered, and
            # evaluated lazily: only for approved decisions with a genuine
            # head mismatch and no override, so the common paths (matching
            # head, unapproved, overridden) never pay its API calls.
            coverage_result = (
                self._queue_sync_merge_covered(pr, reviewed_head_sha, live_head_sha)
                if approved and not head_matches and not override_authorized
                else None
            )
            queue_sync_covered = coverage_result is not None and coverage_result.covered
            if (
                (not approved or not head_matches)
                and not override_authorized
                and not queue_sync_covered
            ):
                issue_number = linked_issue_number(
                    pr,
                    is_cross_repository=pr.get("isCrossRepository"),
                    branch_prefix=prefix,
                )
                candidate: dict[str, Any] = {
                    "pr": pr_number,
                    "issue": issue_number,
                    "head": head,
                    "decision": decision_value,
                    "reviewed_head_sha": reviewed_head_sha,
                    "live_head_sha": live_head_sha,
                    "review_dispatch_enabled": review_dispatch_enabled,
                }
                # coverage_result is only non-None when _queue_sync_merge_covered
                # actually ran (approved + head mismatch + no override) and did
                # not return covered=True -- i.e. exactly the cases this
                # candidate is being appended for. Distinguish "the API never
                # answered" (indeterminate) from "the shape was checked and
                # rejected" (not_covered) in the finding itself, so triage does
                # not have to re-derive it from events.db.
                if coverage_result is not None:
                    if coverage_result.indeterminate:
                        candidate["coverage_check"] = "indeterminate"
                        candidate["coverage_check_error"] = coverage_result.reason
                    else:
                        candidate["coverage_check"] = "not_covered"
                        candidate["coverage_reason"] = coverage_result.reason
                candidates.append(candidate)
        reported = self._apply_unauthorized_merge_baseline(candidates)
        # Announce on the bounded set, never on raw candidates: the arming pass
        # deliberately reports nothing, and an acked finding is deliberately
        # silent. Emitting before the bound would re-introduce exactly the noise
        # the baseline exists to suppress (issue #933).
        self._announce_unauthorized_merges(reported)
        return reported

    def _apply_unauthorized_merge_baseline(
        self, candidates: list[dict[str, Any]]
    ) -> list[dict[str, Any]]:
        """Bound the tripwire to merges it could actually have governed.

        The tripwire asserts a policy — every merged worker PR is covered by an
        ``approved`` decision recorded at its merged head — that this
        repository's history predates. ``merged_pr_list()`` returns the last 500
        closed PRs, and many of those merged before the review gate existed,
        under the #597 hollow-verdict bug, or with no decision file at all.
        Measured against the live repo before this landed, an unbounded first
        pass yields 48 findings.

        Those 48 would append to ``loop()``'s ``errors`` bucket on *every* pass
        — there is no dedupe and the 500-PR window keeps them in scope for a
        very long time — pinning ``ok=False`` permanently and burying any real
        self-merge in constant background noise. That is the same "noise, not
        signal" failure this tripwire exists to prevent, arriving from the other
        direction: a control that can never go quiet is not a control.

        So the first pass *arms* rather than alarms. It records exactly which PRs
        were already merged-and-uncovered, emits them once as an
        ``unauthorized_merge_baseline_armed`` event so the backlog stays
        auditable, and reports nothing. Every later pass reports only merges
        absent from that baseline.

        A second, ongoing dedupe layer handles *post-arming* findings (issue
        #673). The baseline suppresses history once; it cannot suppress a
        genuine bypass that lands after arming, and without an ack mechanism
        such a finding is re-appended to ``errors`` on every single pass for as
        long as it stays inside ``merged_pr_list()``'s 500-PR window — pinning
        ``ok=False`` forever and drowning any new signal in constant noise. That
        is the same "a control that can never go quiet is not a control" failure
        the baseline exists to prevent, arriving from the other direction. So a
        finding that has been explicitly acknowledged via
        ``ack_unauthorized_merge`` (state key ``unauthorized_merge_acknowledged``,
        a ``{pr_number: {acknowledged_at, reason, by}}`` map) is filtered out of
        the reported candidates the same way the baseline filters pre-arming
        history. Acknowledgment is never automatic — it requires an explicit
        ``charlie tripwire ack`` action — or the tripwire would defeat itself.

        Why an explicit set of PR numbers and not a high-water PR number: a
        number watermark also exempts any PR that was already open when the
        control armed but merges afterwards. That is not hypothetical here — at
        arming there were three open worker PRs (#510, #585, #630), every one
        numbered below the highest merged PR (#631), so a number watermark would
        have permanently exempted all three, including the PR that adds this
        tripwire. The set is derived at runtime from live data, never hard-coded,
        and suppresses precisely the merges that already happened.

        Cost, stated plainly: a genuine bypass that lands in the same window as
        the arming pass is baselined rather than reported. It still appears in
        the armed event's PR list, which is why that event carries the full set
        rather than just a count.
        """
        import logging

        logger = logging.getLogger(__name__)
        key = UNAUTHORIZED_MERGE_BASELINE_KEY

        def _suppressed(baseline: Any) -> set[int]:
            if not isinstance(baseline, dict):
                return set()
            raw = baseline.get("pre_existing_prs") or []
            return {int(n) for n in raw if isinstance(n, int) and not isinstance(n, bool)}

        def _acked(ack_map: Any) -> set[int]:
            # The ack set is a JSON object keyed by string PR numbers (JSON keys
            # are always strings). Parse them back to int so the membership test
            # against the int ``c["pr"]`` candidates works.
            if not isinstance(ack_map, dict):
                return set()
            out: set[int] = set()
            for n in ack_map:
                try:
                    out.add(int(n))
                except (TypeError, ValueError):
                    continue
            return out

        state = load_state_locked(self.paths.state_file)
        if isinstance(state.get(key), dict):
            pre_existing = _suppressed(state.get(key))
            acknowledged = _acked(state.get(UNAUTHORIZED_MERGE_ACK_KEY))
            return [
                c
                for c in candidates
                if c["pr"] not in pre_existing and c["pr"] not in acknowledged
            ]

        # ---- arming pass ----
        pre_existing_now = sorted({int(c["pr"]) for c in candidates})

        if self.dry_run:
            # A preview must not write state (issues #609/#613/#621). Report what
            # an armed pass would report — nothing — without persisting, so the
            # preview is both write-free and truthful about post-arm behaviour.
            logger.info(
                "DRY-RUN: unauthorized-merge tripwire would arm with %d pre-existing "
                "uncovered merge(s); not persisting",
                len(pre_existing_now),
            )
            return []

        with state_lock(self.paths.state_file):
            locked = load_state(self.paths.state_file)
            if isinstance(locked.get(key), dict):
                # Another pass armed between the read above and this lock. Its
                # baseline wins, so arming is idempotent and never re-widens.
                pre_existing = _suppressed(locked.get(key))
                acknowledged = _acked(locked.get(UNAUTHORIZED_MERGE_ACK_KEY))
                return [
                    c
                    for c in candidates
                    if c["pr"] not in pre_existing and c["pr"] not in acknowledged
                ]
            locked[key] = {
                "armed_at": utc_now(),
                "pre_existing_prs": pre_existing_now,
            }
            locked = self._record_event(
                locked,
                "unauthorized_merge_baseline_armed",
                {
                    "pre_existing_count": len(pre_existing_now),
                    "pre_existing_prs": pre_existing_now,
                },
            )
            save_state(self.paths.state_file, locked)

        logger.warning(
            "unauthorized-merge tripwire armed: %d pre-existing uncovered merge(s) "
            "recorded as baseline and will not be reported again (%s)",
            len(pre_existing_now),
            ", ".join(f"#{n}" for n in pre_existing_now) or "none",
        )
        return []

    def _record_unauthorized_merge_skip(self, exc: Exception) -> None:
        """Record that the unauthorized-merge tripwire did not run this pass (issue #937).

        ``_detect_unauthorized_merges`` fails open on a ``GitHubError``: it returns
        ``[]`` without arming, which is the right call — an unusable response must
        never bake an empty baseline. But returning ``[]`` silently makes a blinded
        pass byte-identical to a clean one in every stored artifact, discarding the
        distinction ``merged_pr_list`` was deliberately changed to create (#633).

        Unlike ``unauthorized_merge_detected``, this fires **once per pass**, not
        once per PR, and that difference is deliberate rather than an inconsistency.
        A finding is one fact that stays true across passes, so repeating it is
        noise. A skipped check is a *distinct occurrence each time*: two blinded
        passes are two windows in which an unauthorized merge could have landed
        unseen, and collapsing them would destroy exactly the count that makes the
        gap measurable.

        Classified ``warning``, not ``error``: nothing is broken and no finding is
        being suppressed — a control simply did not run. That matches
        ``session_rate_limit_deferred`` / ``review_quota_exhausted`` (handled
        degradations) rather than the error tier, which is reserved for things
        needing triage.

        Best-effort by construction: this is the reporting path for a failure that
        has already happened, so it must never turn a degraded pass into a crashed
        one.
        """
        import logging

        logger = logging.getLogger(__name__)
        reason = str(exc) or exc.__class__.__name__
        logger.warning(
            "unauthorized-merge tripwire did not run this pass: %s "
            "(failing open; no findings will be reported until gh recovers)",
            reason,
        )
        if self.dry_run:
            return
        try:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                state = self._record_event(
                    state,
                    "unauthorized_merge_check_skipped",
                    {"reason": reason, "error_type": exc.__class__.__name__},
                )
                save_state(self.paths.state_file, state)
        except (OSError, ValueError, StateLockBusy) as write_exc:  # pragma: no cover
            # StateLockBusy is a RuntimeError and so escapes the other two. This
            # handler's whole promise is that recording a degraded pass never
            # crashes it; contention on the state lock is the single most likely
            # reason this write fails, so omitting it left the promise unmet in
            # exactly its expected case.
            logger.warning("could not record unauthorized_merge_check_skipped: %s", write_exc)

    def _announce_unauthorized_merges(self, reported: list[dict[str, Any]]) -> None:
        """Emit ``unauthorized_merge_detected`` once per PR, the first time it is reported.

        The acknowledgement of a finding was durably recorded
        (``unauthorized_merge_acknowledged``); the *finding itself* was not. A
        control whose triage is auditable but whose alarm is not is only half a
        control — and it is why a live finding took a source-reading session to
        identify instead of one query (issue #933).

        Fires on the post-baseline, post-ack set — exactly the candidates that
        become ``errors`` entries and pin ``ok=False`` — and is keyed durably in
        ``UNAUTHORIZED_MERGE_DETECTED_KEY`` so a finding that persists for 21
        passes produces one event, not 21. See that constant for why the record
        deliberately does not suppress the finding itself.

        Classified ``error`` by ``instrumentation._classify_level``, which closes
        the second of the two misreads in #933: a session reported "0 errors
        since restart" from ``query_events(level='error')`` while this very
        finding was pinning every pass, because nothing on the finding path ever
        set that level.

        Best-effort by construction: a state failure here must not crash a fleet
        pass on the *reporting* path of a security control. The finding is
        returned to the caller regardless.
        """
        import logging

        if not reported or self.dry_run:
            # dry_run: a preview must not write state (issues #609/#613/#621),
            # matching _apply_unauthorized_merge_baseline's arming path.
            return

        logger = logging.getLogger(__name__)
        key = UNAUTHORIZED_MERGE_DETECTED_KEY
        try:
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                record = state.get(key)
                if not isinstance(record, dict):
                    record = {}
                fresh = [c for c in reported if str(c["pr"]) not in record]
                if not fresh:
                    return
                detected_at = utc_now()
                for candidate in fresh:
                    record[str(candidate["pr"])] = {
                        "detected_at": detected_at,
                        "issue": candidate.get("issue"),
                        "head": candidate.get("head"),
                        "decision": candidate.get("decision"),
                        "reviewed_head_sha": candidate.get("reviewed_head_sha"),
                        "live_head_sha": candidate.get("live_head_sha"),
                        "review_dispatch_enabled": candidate.get("review_dispatch_enabled"),
                        # Issue #1194 retry fix: present only for candidates that
                        # went through _queue_sync_merge_covered (approved +
                        # head-mismatch + no override) and were not covered --
                        # None for every other finding shape (unapproved,
                        # missing decision, ...). See _QueueSyncCoverageResult.
                        "coverage_check": candidate.get("coverage_check"),
                        "coverage_check_error": candidate.get("coverage_check_error"),
                        "coverage_reason": candidate.get("coverage_reason"),
                    }
                state[key] = record
                for candidate in fresh:
                    state = self._record_event(
                        state,
                        "unauthorized_merge_detected",
                        {
                            "pr": candidate["pr"],
                            "issue": candidate.get("issue"),
                            "head": candidate.get("head"),
                            "decision": candidate.get("decision"),
                            "reviewed_head_sha": candidate.get("reviewed_head_sha"),
                            "live_head_sha": candidate.get("live_head_sha"),
                            "review_dispatch_enabled": candidate.get("review_dispatch_enabled"),
                            "coverage_check": candidate.get("coverage_check"),
                            "coverage_check_error": candidate.get("coverage_check_error"),
                            "coverage_reason": candidate.get("coverage_reason"),
                        },
                    )
                save_state(self.paths.state_file, state)
        except (OSError, ValueError) as exc:
            logger.warning("unauthorized-merge detection record not persisted: %s", exc)
            return

        logger.error(
            "unauthorized-merge tripwire: %d new uncovered merge(s) detected (%s); "
            "ack with `charlie tripwire ack <pr> --reason ...` once triaged",
            len(fresh),
            ", ".join(f"#{c['pr']}" for c in fresh),
        )

    def tripwire_status(self) -> CommandResult:
        """Report the live unauthorized-merge tripwire state without re-running detection.

        The consumer for ``unauthorized_merge_detected`` (issue #933) and for
        ``unauthorized_merge_check_skipped`` (issue #940). Reading a finding out of
        ``state.json`` is deliberately cheaper and safer than re-detecting: it needs
        no ``gh`` call, so it works while the API is down and cannot itself arm the
        baseline as a side effect. The skip counts come from ``events.db``, which is
        local SQLite and so preserves that property.

        Pending findings are the ones that are still pinning ``ok=False``:
        detected and not acknowledged.

        The two halves answer different questions and both are needed: ``pending``
        says whether the tripwire *found* anything, ``skipped_count`` says whether it
        *ran*. A pass that failed open reports no findings, so without the second
        number an unrun control is indistinguishable from a clean one.
        """
        state = load_state_locked(self.paths.state_file)

        detected = state.get(UNAUTHORIZED_MERGE_DETECTED_KEY)
        detected = detected if isinstance(detected, dict) else {}
        acked = state.get(UNAUTHORIZED_MERGE_ACK_KEY)
        acked = acked if isinstance(acked, dict) else {}
        baseline = state.get(UNAUTHORIZED_MERGE_BASELINE_KEY)
        baseline = baseline if isinstance(baseline, dict) else {}

        def _as_int(value: Any) -> int | None:
            try:
                return int(value)
            except (TypeError, ValueError):
                return None

        pending: list[dict[str, Any]] = []
        for raw_pr, detail in sorted(detected.items(), key=lambda kv: _as_int(kv[0]) or 0):
            if raw_pr in acked:
                continue
            entry = {"pr": _as_int(raw_pr)}
            if isinstance(detail, dict):
                entry.update(
                    {
                        "detected_at": detail.get("detected_at"),
                        "issue": detail.get("issue"),
                        "head": detail.get("head"),
                        "decision": detail.get("decision"),
                        "review_dispatch_enabled": detail.get("review_dispatch_enabled"),
                    }
                )
            pending.append(entry)

        # How often did the check fail open and not run at all (issue #940)? Without
        # this the command answers "are there findings?" but not "did the control
        # actually look?", and those differ precisely when it matters: a skipped pass
        # reports no findings, so a blinded tripwire and a clean one are identical in
        # every field above.
        #
        # Reading events.db here does not compromise the no-``gh`` property this method
        # is built around -- it is local SQLite, so the command still works during an
        # API outage. That is the point rather than a tolerated cost: a skip is *caused
        # by* a GitHubError, so an operator running this during a gh outage is exactly
        # the person who needs to know the tripwire has stopped looking.
        #
        # Bound the count by ``armed_at`` instead of a fixed lookback: it is real state
        # rather than a constant needing revision, and skips recorded before arming say
        # nothing about the armed control's coverage. ``skipped_window_start`` reports
        # the bound actually used, so a caller never has to guess whether a count is
        # since-arming or all-time.
        armed_at = baseline.get("armed_at")
        skipped_window_start = armed_at if isinstance(armed_at, str) and armed_at else None
        skips = query_events(
            self.paths.state_file,
            kind="unauthorized_merge_check_skipped",
            since=skipped_window_start,
        )
        last_skip = skips[-1] if skips else None
        last_skip_payload = last_skip.get("payload") if isinstance(last_skip, dict) else None
        last_skipped_reason = (
            last_skip_payload.get("reason") if isinstance(last_skip_payload, dict) else None
        )

        if not baseline:
            message = "unauthorized-merge tripwire is NOT ARMED (no baseline recorded yet)"
        elif pending:
            message = (
                f"{len(pending)} pending unauthorized-merge finding(s) pinning ok=False: "
                + ", ".join(f"#{p['pr']}" for p in pending)
            )
        else:
            message = "no pending unauthorized-merge findings"

        if last_skip is not None:
            # Appended rather than substituted: "no pending findings" stays true, and
            # the whole problem is that it reads as "all clear" on its own.
            # Conditioned on ``last_skip`` rather than ``skips`` -- equivalent, since one
            # is the other's last element, but it narrows the subscript below instead of
            # relying on a reader to re-derive that they cannot disagree.
            window = f" since {skipped_window_start}" if skipped_window_start else ""
            message += (
                f" (warning: the check did not run on {len(skips)} pass(es){window}; "
                f"most recent {last_skip['ts']})"
            )

        return CommandResult(
            True,
            message,
            {
                "armed_at": armed_at,
                "baselined_count": len(baseline.get("pre_existing_prs") or []),
                "pending": pending,
                "pending_count": len(pending),
                "acknowledged_count": len(acked),
                "detected_count": len(detected),
                "skipped_count": len(skips),
                "skipped_window_start": skipped_window_start,
                "last_skipped_at": last_skip["ts"] if last_skip else None,
                "last_skipped_reason": last_skipped_reason,
                "state_file": str(self.paths.state_file),
            },
        )

    def ack_unauthorized_merge(
        self, pr_number: int, reason: str, *, by: str | None = None
    ) -> CommandResult:
        """Acknowledge a post-arming unauthorized-merge finding so it stops pinning ok=False.

        The #502 tripwire's pre-arming baseline (``_apply_unauthorized_merge_baseline``)
        suppresses history once. It has no equivalent for *post-arming* findings, so a
        single confirmed, already-actioned bypass is re-detected and re-appended to
        ``loop()``'s ``errors`` bucket on every pass for as long as the merged PR stays
        inside ``merged_pr_list()``'s 500-PR REST window — pinning ``ok=False`` forever
        and drowning any new signal (issue #673).

        This records an explicit acknowledgment in ``state.json`` under
        ``unauthorized_merge_acknowledged`` (a ``{pr_number: {acknowledged_at, reason,
        by}}`` map). The tripwire filters acknowledged PRs out of its reported
        candidates the same way it filters pre-arming history, so the finding keeps its
        bite until acked and then goes quiet, freeing ``ok=False`` / ``errors`` to mean
        "there is something new to look at" again.

        Acknowledgment is never automatic — that would defeat the tripwire. It requires
        this explicit action (exposed as ``charlie tripwire ack``), mirroring how
        ``agent:human-needed`` requires explicit human action to clear. A non-empty
        ``reason`` is mandatory: a tripwire that can be silenced silently is no control.
        Re-acking the same PR updates the record (new reason/by/timestamp) rather than
        duplicating or refusing, so a finding's triage state can be corrected.
        """
        if not reason.strip():
            return CommandResult(
                False,
                "a non-empty --reason is required to acknowledge an unauthorized-merge "
                "finding (a tripwire that can be silenced silently is no control)",
                {"pr": pr_number},
            )

        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            acks = state.get(UNAUTHORIZED_MERGE_ACK_KEY)
            if not isinstance(acks, dict):
                acks = {}
            acks[str(pr_number)] = {
                "acknowledged_at": utc_now(),
                "reason": reason,
                "by": by,
            }
            state[UNAUTHORIZED_MERGE_ACK_KEY] = acks
            # Drop this PR's first-detection record (issue #933). That map exists
            # solely to make `unauthorized_merge_detected` fire once per finding
            # instead of once per pass; an ack ends the finding, so the entry has
            # no remaining job. Clearing it here is what makes the map mean
            # "announced findings still open" rather than "every PR ever found",
            # which keeps it bounded and — the reason this is code and not a
            # comment — makes re-detection after an ack is *withdrawn* announce
            # again. There is no revoke command today; the one revocation on
            # record (2026-08-02, the #895 misrouted acks) was an operator edit.
            # Were the entry left behind, whoever adds that command would inherit
            # a finding that silently re-pins ok=False with no fresh event.
            detected = state.get(UNAUTHORIZED_MERGE_DETECTED_KEY)
            if isinstance(detected, dict) and str(pr_number) in detected:
                state[UNAUTHORIZED_MERGE_DETECTED_KEY] = {
                    key: value for key, value in detected.items() if key != str(pr_number)
                }
            state = self._record_event(
                state,
                "unauthorized_merge_acknowledged",
                {"pr": pr_number, "reason": reason, "by": by},
            )
            save_state(self.paths.state_file, state)

        # Echo the resolved state file (issue #895). An ack is a write to a
        # security control's audit record, and the operator's only evidence of
        # *which repo* received it was previously the exit code. Naming the
        # path makes a misrouted ack visible in the output that reports success.
        return CommandResult(
            True,
            f"acknowledged unauthorized-merge finding for PR #{pr_number} "
            f"in {self.paths.state_file}; it will no longer pin ok=False",
            {
                "pr": pr_number,
                "reason": reason,
                "by": by,
                "state_file": str(self.paths.state_file),
            },
        )

    def _review_decision(self, pr_number: int) -> dict[str, Any]:
        """Read the resolved review decision for ``pr_number`` as a Mapping.

        Issue #1362 Stage 1: resolution order (the flat
        ``review-decision.json`` file first, falling back to the
        highest-numbered ``rounds/round-K/review-decision.json`` when the
        flat file is missing or unparseable) is delegated to
        ``review_decision``'s helpers -- the same ones
        ``rework_prompts._round_history_entries`` now imports rather than
        defining -- so the fallback logic lives in exactly one place
        instead of being re-derived here, fixing all of this method's
        call sites at once (previously this method had no round fallback
        at all; only ``rework_prompts.py`` did).

        Many callers need the FULL recorded payload (``required_changes``,
        ``summary``, ``escalated``, ``authorized_override``, ...) --
        fields ``review_decision.ReviewDecision`` deliberately does not
        carry, since that dataclass is scoped to control-flow
        approved/stale/missing questions only -- so this method keeps
        returning a plain dict rather than the dataclass. A caller that
        only needs "is this approved and fresh" should call
        ``review_decision.review_decision()`` directly instead (see
        ``already_approved`` in ``loop()``).

        A corrupt flat file with no usable round fallback now resolves to
        ``{"decision": "missing"}`` rather than the old ``"invalid"``
        sentinel -- both are already treated as "not a terminal verdict"
        by every caller that branches on decision value, so this collapses
        two fail-safe outcomes into one without changing whether a caller
        treats the PR as reviewed.
        """
        pr_dir = self.paths.prs / f"pr-{pr_number}"
        return resolve_decision_payload(pr_dir)

    def _refresh_pr_decision_cache(
        self, pr_number: int, decision: ReviewDecision, decision_path: Path
    ) -> None:
        """Mirror the file-first decision into ``state["prs"][pr_number]`` (issue #1362 Stage 3).

        ``state.json``'s ``decision``/``reviewed_head_sha``/``decision_path``
        fields are a declared *cache* of the file, refreshed from
        ``review_decision()`` at exactly one boundary: the start of each PR's
        evaluation in ``loop()``'s per-PR dispatch block (this method's only
        call site), plus the four writer-adjacent mirrors that already run
        immediately after a ``record_decision()`` call in the same pass
        (``record_review``, ``_route_to_rework``, ``_update_approval_head``,
        ``merge_ready``'s carry-forward branch, and ``review``'s new-dispatch
        placeholder write) -- those keep a PR whose verdict changed THIS pass
        current without waiting for the NEXT pass's boundary refresh; this
        method covers every OTHER *already-tracked* PR (one already present
        in ``state["prs"]``), so the cache never goes stale between
        verdict-producing passes for a PR this method is willing to touch at
        all -- see the ``pr_key not in state["prs"]`` early-return below for
        the one case (a PR not yet dispatched this pass) that instead waits
        for its normal dispatch path to create the full entry first. See
        ``tests/test_state_decision_cache_enforcement.py`` for the enforcement
        that no other production site may set these keys.

        Skips the write entirely when the cache already agrees with the file
        (the common case: no verdict activity since the last pass), so a
        healthy fleet does not pay a state.json write per tracked PR per pass.
        Uses ``self.write_gate.save_state`` (never the raw ``save_state``
        primitive) so this method is itself WriteGate-exclusive under issue
        #1264's R9 predicate -- it must never gain a second, ungated write.
        """
        decision_path_str = str(decision_path)
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_key = str(pr_number)
            if pr_key not in state["prs"]:
                # No PR-state entry exists yet for this PR (it has not been
                # dispatched/tracked this pass) -- refreshing here would
                # materialize a decision-only partial entry with no
                # status/counters, a state shape the four writer-adjacent
                # mirrors never produce. Let the PR's normal dispatch path
                # create the full entry; the boundary refresh will cover it
                # on a later pass once that entry exists.
                return
            pr_state = state["prs"][pr_key]
            if (
                pr_state.get("decision") == decision.decision
                and pr_state.get("reviewed_head_sha") == decision.reviewed_head_sha
                and pr_state.get("decision_path") == decision_path_str
            ):
                return
            state["prs"][pr_key] = {
                **pr_state,
                "decision": decision.decision,
                "reviewed_head_sha": decision.reviewed_head_sha,
                "decision_path": decision_path_str,
            }
            self.write_gate.save_state(state)

    def _read_packet_head_oid(self, pr_number: int) -> str | None:
        """Return the ``headRefOid`` stored in the existing review packet for
        ``pr_number``, or ``None`` if no packet exists or it cannot be read.

        Used by ``loop()`` to detect same-head PRs whose review packet is already
        current, so repeated supervised passes don't regenerate the packet or
        re-fire ``review_started`` label transitions while the operator is still
        reading the packet.
        """
        pr_json_path = self.paths.prs / f"pr-{pr_number}" / "pr.json"
        if not pr_json_path.exists():
            return None
        try:
            with pr_json_path.open("r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError):
            return None
        if not isinstance(data, dict):
            return None
        value = data.get("headRefOid")
        return str(value) if value is not None else None

    def _read_packet_turn_cap_multiplier(self, pr_number: int) -> int:
        """Return the structure-aware turn-cap multiplier stamped into the
        review packet for ``pr_number`` (issue #1439), or 1 if no packet
        exists, the packet predates the field, or it cannot be read.

        A missing/old packet yielding 1 preserves the pre-#1439 flat
        ``review_max_turns`` budget -- the base cap, no structure bonus.
        """
        pr_json_path = self.paths.prs / f"pr-{pr_number}" / "pr.json"
        if not pr_json_path.exists():
            return 1
        try:
            with pr_json_path.open("r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError):
            return 1
        if not isinstance(data, dict):
            return 1
        value = data.get("review_turn_cap_structure_multiplier", 1)
        if not isinstance(value, int) or isinstance(value, bool):
            return 1
        return max(value, 1)

    def _cross_family_report_current(
        self,
        *,
        pr: dict[str, Any],
        pr_number: int,
    ) -> bool:
        """Return True if the packet's cross-family report needs no regeneration.

        Third staleness input to ``loop()``'s same-head packet skip, alongside
        the packet head SHA and the prompt-template digest (issue #1081).

        ``_cross_family_for_pr`` already refuses to reuse a failure stub or a
        semantically empty report and regenerates instead. That logic was never
        wrong -- it was *unreachable*. Its only caller is ``review()``, and the
        skip bypasses ``review()`` whenever the head and template are
        unchanged, so a PR whose head never moves keeps an unusable report
        forever while ``_record_cross_family_verdicts`` skips it every pass,
        emitting one event and then waiting on a human indefinitely. Asking
        here the *same* question the regenerator asks -- ``report_is_reusable``,
        shared by both -- is what removes the gap. If the skip and the
        regenerator can disagree about whether a report is reusable, that
        disagreement is the stall.

        **This method only asks a question.** It writes no state, escalates
        nothing, and applies no label. It used to do all three, and because it
        runs from ``loop()`` rather than from the regenerator, everything it
        charged was charged by a pass that had not done the work -- issue #1099,
        and the fleet's single largest source of non-autonomy while it lasted.
        Keep any new logic here on the read side.
        """
        cfg = self.config.cross_family
        # Mirror _cross_family_for_pr's own early return. With the pass
        # disabled or on a draft PR it never writes a report at all, so an
        # absent report is the steady state and not staleness. Reporting
        # "stale" here would force review() every pass, forever.
        if not cfg.enabled or pr.get("isDraft"):
            return True
        report_path = self.paths.prs / f"pr-{pr_number}" / "cross-family-review.md"
        text = ""
        if report_path.exists() and report_path.stat().st_size > 0:
            try:
                text = report_path.read_text(encoding="utf-8")
            except OSError:
                text = ""
        if report_is_reusable(text, pr.get("headRefOid")):
            return True
        # Unusable, so the packet is stale and review() must run. Answering that
        # one question is now ALL this method does: the regeneration budget is
        # claimed by the regenerator itself (_cross_family_for_pr), because
        # review() can -- and for a PR with merge conflicts routinely does --
        # return before ever reaching it (issue #1099). A predicate must not
        # mutate state.json, escalate an issue, or apply a GitHub label.
        #
        # The budget read below is not a mutation. Once this head's budget is
        # spent, continuing to report "stale" would re-run the whole review path
        # every pass, forever, for a PR that this pass cannot advance. Parking
        # it is what the pre-#1099 code did on this same condition -- via the
        # claim's return value rather than a read, which is the part that was
        # wrong.
        #
        # TWO budgets park a PR, and they bound different work (issue #1099):
        #
        #   attempts     the model RAN and left an unusable report. Bounds a
        #                600s synchronous call per pass. Terminates by
        #                escalating to a human, from the regenerator itself.
        #   not_reached  review() returned before the regenerator, so the model
        #                never ran. Bounds only the cheap re-entry into
        #                review(). Terminates by parking, with NO escalation.
        #
        # The asymmetry is deliberate. Parking self-heals: the record is keyed
        # by head SHA, so the next push resets both counters and the PR is
        # reconsidered for free. `reason_class="judgment"` does not -- it is
        # excluded from the automatic de-escalation sweep and needs a human. So
        # a wrong park costs some extra cheap passes until the head moves, while
        # a wrong escalation costs a human. The measured cost of getting that
        # backwards is 36 escalated job-cannon issues.
        record = self._cross_family_regen_record(
            pr_number=pr_number, head_sha=pr.get("headRefOid")
        )
        max_attempts = max(0, int(cfg.max_regen_attempts))
        return (
            int(record.get("attempts") or 0) >= max_attempts
            or int(record.get("not_reached") or 0) >= max_attempts
        )

    def _cross_family_regen_record(
        self, *, pr_number: int, head_sha: str | None
    ) -> dict[str, Any]:
        """This head's cross-family regeneration counters.

        Read-only by construction (issue #1099): the authoritative writes happen
        under the state lock in ``_claim_cross_family_regen_attempt`` and
        ``_charge_cross_family_regen_not_reached``, and this snapshot must not
        be mutated. Reads through ``load_state_locked`` per issue #310's single
        point of enforcement rather than a bare ``load_state`` -- a read-only
        caller still takes the lock, and ``tests/test_load_state_locked.py``
        fails the build otherwise.

        Both counters are stored in one head-keyed record and therefore reset
        together: a record left by an earlier head reads as all-zero, matching
        the claim's own reset rule. That shared key is what makes it safe for
        the two budgets to share ``max_regen_attempts`` as their bound rather
        than adding a second config knob.
        """
        state = load_state_locked(self.paths.state_file)
        record = state["prs"].get(str(pr_number), {}).get("cross_family_regen")
        if not isinstance(record, dict) or record.get("head_sha") != head_sha:
            return {"head_sha": head_sha, "attempts": 0, "not_reached": 0}
        return record

    def _charge_cross_family_regen_not_reached(
        self,
        *,
        pr_number: int,
        issue_number: int | None,
        head_sha: str | None,
        attempts_before: int,
    ) -> None:
        """Charge one "review() ran but never reached the regenerator" pass.

        ``loop()`` forced ``review()`` for the express purpose of regenerating an
        unusable cross-family report. If the report is *still* unusable and the
        attempt counter did not move, ``_cross_family_for_pr`` was never reached
        -- ``review()`` returned at the janitor gate thousands of lines earlier,
        which is what a PR with merge conflicts or missing required checks does
        on every pass (issue #1099).

        That re-entry is cheap -- no model call -- but it is not free, and
        nothing else bounds it: the attempts budget cannot, because it is spent
        by the regenerator this path never reaches. So this is its own budget,
        counted in the same head-keyed record and bounded by the same
        ``max_regen_attempts``.

        It terminates by PARKING, never by escalating. The report being unusable
        is observed, but "unusable and unfixable" -- what
        ``cross_family_report_unusable`` claims -- is not: regeneration was
        never tried. Parking states exactly what is known, and unlike a
        ``judgment`` escalation it self-heals when the head moves.

        ``attempts_before`` is the discriminator and must be sampled *before*
        ``review()``. Without it this would also fire for a model that ran and
        failed -- a case the attempts budget already owns and already escalates
        -- and the event's name would be a false claim about a path that was in
        fact reached.
        """
        if self.dry_run:
            return
        max_attempts = max(0, int(self.config.cross_family.max_regen_attempts))
        report_path = self.paths.prs / f"pr-{pr_number}" / "cross-family-review.md"
        text = ""
        if report_path.exists() and report_path.stat().st_size > 0:
            try:
                text = report_path.read_text(encoding="utf-8")
            except OSError:
                text = ""
        if report_is_reusable(text, head_sha):
            return  # regeneration was reached and produced a usable report
        # Pre-check before the write section. Both reads take the lock, but this
        # one releases it before deciding, so the already-charged and
        # regenerator-ran cases skip the write entirely. The counter is
        # re-derived under the lock below; this is a fast path, not the
        # authority.
        seen = self._cross_family_regen_record(pr_number=pr_number, head_sha=head_sha)
        if int(seen.get("attempts") or 0) != attempts_before:
            return  # the regenerator ran; the attempts budget owns this pass
        if int(seen.get("not_reached") or 0) >= max_attempts:
            return
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            current = pr_state.get("cross_family_regen")
            if not isinstance(current, dict) or current.get("head_sha") != head_sha:
                current = {"head_sha": head_sha, "attempts": 0, "not_reached": 0}
            not_reached = int(current.get("not_reached") or 0)
            if not_reached >= max_attempts:
                return
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "cross_family_regen": {**current, "not_reached": not_reached + 1},
            }
            state = self._record_event(
                state,
                "cross_family_regen_not_reached",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "head_sha": head_sha,
                    "attempts": int(current.get("attempts") or 0),
                    "not_reached": not_reached + 1,
                    "max_attempts": max_attempts,
                },
            )
            save_state(self.paths.state_file, state)

    def _claim_cross_family_regen_attempt(
        self,
        *,
        pr_number: int,
        issue_number: int | None,
        head_sha: str | None,
        report_head: str | None,
    ) -> bool:
        """Claim one bounded cross-family regeneration attempt for ``pr_number``.

        Returns True when an attempt was claimed, meaning the caller may run the
        cross-family model. Returns False once the budget for this head is
        spent. Counting is *all* this does: it does not escalate, label, or
        decide anything (issue #1099). The caller is ``_cross_family_for_pr``,
        immediately before ``run_cross_family_review`` -- the operation the
        budget bounds -- so an attempt cannot be charged by a pass that never
        reaches the model.

        The bound is mandatory, not defensive: regeneration runs the
        cross-family model synchronously for up to ``timeout_seconds`` (600s in
        this fleet). Unbounded, a model that is simply down would burn that
        timeout on every pass for this PR and starve the other repo in the
        shared sequential loop (#1078).

        Attempts are counted *per head SHA* and reset when the head moves. A
        head move already forces regeneration through the packet-head check, so
        counting across heads would let a long-lived PR accumulate attempts
        from unrelated pushes and escalate on one that had never actually
        failed.

        Exhaustion is adjudicated by ``_escalate_cross_family_regen_exhausted``
        *after* the model call, because only there is "the report is still
        unusable" an observation rather than an inference.
        """
        max_attempts = max(0, int(self.config.cross_family.max_regen_attempts))
        # --dry-run must not write state.json (review finding on PR #670).
        # Reporting "budget spent" is the non-mutating answer, and it also keeps
        # a dry run from spending a real 600s model call.
        if self.dry_run:
            return False
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            pr_state = state["prs"].get(str(pr_number), {})
            record = pr_state.get("cross_family_regen")
            if not isinstance(record, dict) or record.get("head_sha") != head_sha:
                record = {"head_sha": head_sha, "attempts": 0, "not_reached": 0}
            attempts = int(record.get("attempts") or 0)
            if attempts >= max_attempts:
                return False
            # Spread `record` rather than rebuilding it, so the sibling
            # not-reached counter survives a claim on the same head.
            state["prs"][str(pr_number)] = {
                **pr_state,
                "number": pr_number,
                "cross_family_regen": {**record, "attempts": attempts + 1},
            }
            state = self._record_event(
                state,
                "cross_family_report_regen_forced",
                {
                    "pr_number": pr_number,
                    "issue_number": issue_number,
                    "head_sha": head_sha,
                    "report_head_sha": report_head,
                    "attempt": attempts + 1,
                    "max_attempts": max_attempts,
                },
            )
            save_state(self.paths.state_file, state)
        return True

    def _escalate_cross_family_regen_exhausted(
        self,
        *,
        pr_number: int,
        issue_number: int | None,
        head_sha: str | None,
        report_path: Path,
    ) -> None:
        """Escalate to a human once this head's regeneration budget is spent.

        Called immediately after ``run_cross_family_review`` returns, and a
        no-op unless BOTH conditions hold: the report the model just left behind
        is still unusable, and ``attempts`` has reached ``max_regen_attempts``.

        Both are *observed* here. That placement is the fix for issue #1099 --
        this block used to live in ``_claim_cross_family_regen_attempt``, which
        runs before the model does and is reached from ``loop()``'s staleness
        check by way of ``review()``. On a PR with merge conflicts or missing
        required checks ``review()`` returns at the janitor gate long before the
        regenerator, so the budget was spent, and this escalation fired, against
        a PR whose model had never been invoked once. 36 of 54 escalated
        job-cannon issues carried the resulting ``cross_family_report_unusable``
        for a report that was never actually retried.

        Usability is re-read from disk with ``report_is_reusable`` -- the same
        predicate the reuse check and ``loop()``'s packet skip consult -- rather
        than taken from ``CrossFamilyResult.ok``, so the three cannot disagree
        about what "unusable" means. A model that exits zero having written a
        blocked or empty report is ``ok=True`` and still unusable.

        On exhaustion the issue escalates -- it is never recorded as approved.
        ``max_parse_failures`` deliberately ends in a caveated ``approved``;
        copying that shape here would approve against a head that was never
        positively confirmed, which is exactly the fail-open #1079 closed and
        which ``_note_cross_family_head_indeterminate``'s docstring exists to
        steer a checklist-follower away from.

        The escalation is classified ``judgment`` rather than ``mechanical``
        deliberately. A mechanical escalation is eligible for the automatic
        de-escalation sweep, which would return the issue to ``reviewing`` with
        the report still unusable -- straight back into the indefinite silent
        wait this change exists to make unreachable. Clearing it needs a human
        to decide whether to re-run, switch model, or waive the gate. That cost
        is why the sibling not-reached budget parks instead of escalating; see
        ``_charge_cross_family_regen_not_reached``.
        """
        # --dry-run must not perform state.json writes or live GitHub label
        # mutations (review finding on PR #670). This method owns the only
        # GitHub-reaching path in the regeneration bound, so the gate lives here
        # rather than at the call site.
        if self.dry_run:
            return
        max_attempts = max(0, int(self.config.cross_family.max_regen_attempts))
        text = ""
        if report_path.exists() and report_path.stat().st_size > 0:
            try:
                text = report_path.read_text(encoding="utf-8")
            except OSError:
                text = ""
        if report_is_reusable(text, head_sha):
            return  # regeneration succeeded; nothing is exhausted
        report_head = extract_head_ref_oid(text) if text.strip() else None
        escalated_now = False
        repair_label_edge = False
        with state_lock(self.paths.state_file):
            state = load_state(self.paths.state_file)
            record = state["prs"].get(str(pr_number), {}).get("cross_family_regen")
            if not isinstance(record, dict) or record.get("head_sha") != head_sha:
                record = {"head_sha": head_sha, "attempts": 0, "not_reached": 0}
            attempts = int(record.get("attempts") or 0)
            if attempts < max_attempts:
                return  # budget remains; a later pass may still succeed
            # Budget spent for this head. Escalate exactly once -- the durable
            # flag keeps this to one event per head rather than one per pass,
            # which would flush the capped `events` ring in state.json.
            if record.get("escalated"):
                # Escalated on an earlier pass. Nothing left to claim -- but the
                # label edge below may never have landed, and if it didn't, this
                # early return is what makes that permanent. #586's self-heal
                # sweep would normally repair it; it cannot reach this case (see
                # the comment on the label block), so the retry is decided here.
                repair_label_edge = _escalated_label_needs_repair(
                    state, pr_number=pr_number, issue_number=issue_number
                )
                if not repair_label_edge:
                    return
            else:
                state = _escalate_issue(
                    state,
                    issue_number,
                    reason="cross_family_report_unusable",
                    reason_class="judgment",
                    pr_number=pr_number,
                    pr_extra={
                        "cross_family_regen": {**record, "escalated": True},
                    },
                )
                state = self._record_event(
                    state,
                    "cross_family_report_regen_exhausted",
                    {
                        "pr_number": pr_number,
                        "issue_number": issue_number,
                        "head_sha": head_sha,
                        "report_head_sha": report_head,
                        "attempts": attempts,
                        "max_attempts": max_attempts,
                    },
                )
                save_state(self.paths.state_file, state)
                escalated_now = True

        # Apply the human-needed label edge OUTSIDE the state lock --
        # transition() makes GitHub API calls. _escalate_issue writes state
        # only; without this the PR sits escalated in state.json and invisible
        # on GitHub, which is the exact defect #586 fixed for the sibling call
        # site (pr-lifecycle.md: PRs 548/540/531 live escalated-without-label).
        # This call site owns the retry rather than delegating it to #586's
        # self-heal sweep, and that is deliberate even though #1088 has since
        # made the sweep reachable (`_repair_escalated_labels`, called above
        # dispatch_reviews' `review_dispatch.enabled` early return). The sweep is
        # a NEXT-PASS backstop; applying the edge here makes the escalation
        # visible on GitHub in the same pass that decided it. The two do not
        # fight: label_error is written in the same three-state shape the sweep
        # consumes (dict = failed, None = applied-and-verified, absent = never
        # attempted) and both consult `_escalated_label_needs_repair`, so a
        # success here makes the sweep skip this issue for free.
        #
        # Historical note, because the previous version of this comment said the
        # opposite and was true when written: before #1088 the sweep's input set
        # was built by the dispatch-selection loop *below* that early return, so
        # with review dispatch off -- the configuration both fleets actually run
        # -- it was unreachable, not merely narrow. That is why this site took
        # ownership; #1088 fixed the sweep rather than changing that.
        #
        # The `issue_number is not None` arm is not a defensive nicety: per
        # _escalate_issue's contract the issue may be unresolvable (cross-repo
        # or fork PR), in which case only the PR record was escalated and there
        # is no issue to carry the label. Do not "fix" that by inventing a label
        # target -- the PR record is the surface for that case.
        if (escalated_now or repair_label_edge) and issue_number is not None:
            # Issue #1266: this call site's own _escalate_issue above always
            # passes reason_class="judgment" (an unusable cross-family
            # report is a human product/process decision, never mechanical),
            # so this resolves to the identity "escalated" edge -- routed
            # through the helper anyway for uniformity with every other
            # escalation-label call site.
            edge = _escalation_edge("escalated", "judgment")
            result = transition(self.gh, self.config.labels, int(issue_number), edge)
            label_error: dict[str, Any] | None = None
            if result.outcome != TransitionOutcome.APPLIED:
                label_error = {
                    "edge": edge,
                    "outcome": result.outcome.value,
                    "add_failures": result.add_failures,
                    "remove_failures": result.remove_failures,
                }
            with state_lock(self.paths.state_file):
                state = load_state(self.paths.state_file)
                entry = state["issues"].get(str(issue_number), {})
                state["issues"][str(issue_number)] = {
                    **(entry if isinstance(entry, dict) else {}),
                    "number": int(issue_number),
                    "label_error": label_error,
                }
                save_state(self.paths.state_file, state)

    def _review_template_sha(self) -> str:
        """SHA-256 digest of the resolved review template + referenced section
        partials.

        Captures every input to ``review()``'s prompt render that lives in a
        template file: the ``review.md`` template (package default or repo-local
        override) and every ``worker_sections/*.md`` partial it references. A
        change in any of those files changes this digest, so ``loop()`` can
        treat a digest mismatch as packet staleness alongside a head-SHA
        mismatch (issue #592).
        """
        return prompt_template_digest("review.md", search_dirs=self.prompt_dirs)

    def _read_packet_template_sha(self, pr_number: int) -> str | None:
        """Return the ``prompt_template_sha`` stamped in the existing review
        packet for ``pr_number``, or ``None`` if no packet exists, it cannot
        be read, or it predates issue #592 (when the field started being
        stamped).

        A ``None`` result is a legacy packet, not a staleness signal: callers
        conservatively treat a missing digest as "current" so a one-time
        fleet-wide burst of regenerations is not forced on upgrade. Packets
        rendered after this fix always carry the digest, so every *future*
        template change reaches static-head PRs.
        """
        pr_json_path = self.paths.prs / f"pr-{pr_number}" / "pr.json"
        if not pr_json_path.exists():
            return None
        try:
            with pr_json_path.open("r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, json.JSONDecodeError):
            return None
        if not isinstance(data, dict):
            return None
        value = data.get("prompt_template_sha")
        return str(value) if value is not None else None

    def _packet_template_current(self, pr_number: int) -> bool:
        """True if the packet's stamped template digest matches the current
        review template.

        A packet that predates issue #592 (no ``prompt_template_sha`` field)
        is treated as current so the upgrade does not force a one-time
        fleet-wide regeneration burst; packets rendered after this fix always
        carry the digest, so future template edits are caught.
        """
        packet_template_sha = self._read_packet_template_sha(pr_number)
        if packet_template_sha is None:
            return True
        return packet_template_sha == self._review_template_sha()

    def _read_packet_diff(self, pr_number: int) -> str | None:
        """Return the diff text stored in the existing review packet for
        ``pr_number``, or ``None`` if no packet exists or it cannot be read.

        Mirrors ``_read_packet_head_oid``: keeps ``reviewed_patch_id`` derived
        from the diff the reviewer actually saw rather than a live re-fetch.
        """
        diff_path = self.paths.prs / f"pr-{pr_number}" / "diff.patch"
        if not diff_path.exists():
            return None
        try:
            return diff_path.read_text(encoding="utf-8")
        except OSError:
            return None

    def _check_issue_citations(
        self,
        issue_number: int,
        full_issue: dict[str, Any],
        previous_entries: dict[int, dict[str, Any]],
    ) -> dict[int, tuple[str, list[CitationVerdict]]]:
        """Verify ``path:line`` citations in ``full_issue``'s body (issue #1000).

        Returns ``{issue_number: (fingerprint, drifted_verdicts)}`` when the
        drift fingerprint changed since the last pass (including a change to
        empty when drift resolved), and ``{}`` otherwise -- the caller only
        stamps/emit-vents on a change, so an unchanged-stale issue is not
        re-commented every pass. When drift is newly detected a flag comment is
        posted on the issue (best-effort; a failure is logged and swallowed so
        it can never abort dispatch). The comment is visible to the dispatched
        worker through ``$issue_comments`` (issue #872), which is the point: a
        worker that sees "these line numbers have drifted, grep for the symbol"
        is not silently misled onto unrelated code.

        This is the "cheap check" backstop. It catches coordinate drift
        (file missing / out of range / blank line); it does not catch in-range
        content drift, which the filing convention (``CONTRIBUTING.md``) is the
        durable fix for. See ``citation_check`` for the full rationale.
        """
        body = str(full_issue.get("body") or "")
        if not body.strip():
            return {}
        try:
            verdicts = verify_citations(body, self.repo_root)
        except Exception:
            logging.getLogger(__name__).warning(
                "citation_check failed issue=%d", issue_number, exc_info=True
            )
            return {}
        drifted = drifted_citation_verdicts(verdicts)
        new_fp = citation_drift_fingerprint(verdicts)
        prev_entry = previous_entries.get(issue_number, {})
        prev_fp = prev_entry.get("citation_drift_fingerprint")
        # ``None`` (never stamped) and "" (no drift) both mean "no current drift
        # marker" for the comparison; treat them as equal so the first pass on a
        # clean issue does not stamp an empty fingerprint as a "change".
        if (prev_fp or "") == new_fp:
            return {}
        if new_fp:
            self._post_citation_drift_comment(issue_number, drifted)
        return {issue_number: (new_fp, drifted)}

    def _post_citation_drift_comment(
        self, issue_number: int, drifted: list[CitationVerdict]
    ) -> None:
        """Post a best-effort flag comment listing drifted citations (issue #1000).

        Never raises: a comment-posting failure is logged and swallowed so it
        cannot abort the dispatch pass. The comment is stamped with the current
        ``HEAD`` sha (the commit the check ran against) per the issue's
        recommendation 2, so a reader can tell a drifted citation from one that
        was always wrong.
        """
        head_sha = self._read_head_sha_best_effort()
        lines = [
            f"{ORCHESTRATOR_COMMENT_MARKER}",
            "",
            "## Citation drift detected (issue #1000)",
            "",
            "One or more ``path:line`` citations in this issue no longer match the"
            " working tree. A worker reading the bare line number would land on"
            " unrelated code and may infer the defect was already fixed. **Grep for"
            " the cited symbol or surrounding context instead of trusting the line"
            " number**, and consider re-filing with a symbol citation (see"
            ' ``CONTRIBUTING.md`` -- "Citing code in issues").',
            "",
        ]
        if head_sha:
            lines.append(f"Verified against `HEAD` = `{head_sha}`.")
            lines.append("")
        lines.append("| citation | status |")
        lines.append("|---|---|")
        for v in drifted:
            lines.append(f"| `{v.citation.raw}` | {format_verdict_status_cell(v)} |")
        body = "\n".join(lines)
        issue_dir = self.paths.issues / f"issue-{issue_number}"
        try:
            issue_dir.mkdir(parents=True, exist_ok=True)
            body_path = issue_dir / "citation-drift-comment.md"
            body_path.write_text(body, encoding="utf-8")
            self.gh.issue_comment(issue_number, body_path)
        except Exception:
            logging.getLogger(__name__).warning(
                "citation drift comment post failed issue=%d", issue_number, exc_info=True
            )

    def _read_head_sha_best_effort(self) -> str | None:
        """Return the current ``HEAD`` sha of ``repo_root``, or ``None``."""
        try:
            res = run_captured(
                ["git", "rev-parse", "HEAD"],
                cwd=self.repo_root,
                timeout_seconds=15,
            )
            if not res.ok:
                return None
            return res.stdout.strip() or None
        except Exception:
            return None

    def _comment_pr(self, pr_number: int, summary: str) -> None:
        """Post a comment on ``pr_number``, stamped with the orchestrator's marker.

        The marker is what lets #950's external-findings ingestion recognise this
        comment as its own output rather than a human finding -- author identity
        cannot make that distinction, because the orchestrator posts under a user
        token. Stamping happens here, at the single point every orchestrator
        comment passes through, so no call site can forget it.
        """
        pr_dir = self.paths.prs / f"pr-{pr_number}"
        body_path = pr_dir / "review-comment.md"
        body_path.write_text(f"{ORCHESTRATOR_COMMENT_MARKER}\n{summary}", encoding="utf-8")
        self.gh.pr_comment(pr_number, body_path)

    def _summarize_issue(self, issue: dict[str, Any]) -> dict[str, Any]:
        declared_blockers, open_blockers = self._get_open_blockers(issue)
        return {
            "number": issue.get("number"),
            "title": issue.get("title"),
            "url": issue.get("url"),
            "labels": sorted(label_names(issue)),
            "dispatchable": self._is_dispatchable(issue),
            "dependencies": {
                "declared": declared_blockers,
                "open": open_blockers,
            },
        }

    def _summarize_pr(self, pr: dict[str, Any]) -> dict[str, Any]:
        return {
            "number": pr.get("number"),
            "title": pr.get("title"),
            "url": pr.get("url"),
            "issue_number": linked_issue_number(
                pr,
                is_cross_repository=pr.get("isCrossRepository"),
                branch_prefix=self.config.dispatch.branch_prefix,
            ),
            "head": pr.get("headRefName"),
            "is_draft": pr.get("isDraft"),
            "reviewDecision": pr.get("reviewDecision"),
        }

    def _summarize_worker(self, view, health, probe=None) -> dict[str, Any]:
        """Summarize a worker's state for the status() workers list.

        Args:
            view: WorkerView with worker state
            health: WorkerHealth enum value from classify_worker_health
            probe: Optional ``RealActivityProbe`` from
                ``real_activity_probe_for`` (the same corroboration probe the
                watchdog consults). When supplied, the summary surfaces the
                freshest corroborated activity timestamp/source and whether
                that signal is fresh within ``watchdog.stall_minutes`` -- so an
                alive-but-polling worker (stale sidecar log, fresh sessions.db
                / per-PID log) is visibly distinguishable from a genuinely
                stalled one (issue #1346). ``None`` keeps the legacy shape
                (no corroboration fields) for callers that did not compute a
                probe.

        Returns:
            Dict with worker summary fields for status() JSON output
        """
        from .claude_code import parse_claude_events
        from .post_mortem import RealActivityProbe, _events_path_from_log

        # Resolve repo_key: use view.repo_key if present, otherwise fall back to gh.name_with_owner()
        # This handles both fleet mode (repo_key populated by iter_workers) and single-repo mode
        repo = view.repo_key
        if not repo:
            try:
                repo = self.gh.name_with_owner()
            except GitHubError:
                # If gh fails, use a fallback to avoid breaking status()
                repo = "unknown"

        # Parse tool calls and usage for Claude Code sessions
        tool_calls = None
        tokens = None
        cost_usd = None

        if view.adapter_kind == "claude-code":
            # Canonical derivation (issue #329): supports both plain
            # issue-<n>.claude.log and rework-layout issue-<n>-rework.claude.log,
            # matching the events.jsonl sibling that claude_code actually writes.
            events_path = _events_path_from_log(Path(view.log_path))
            progress = parse_claude_events(events_path)
            if progress is not None:
                tool_calls = progress.tool_call_count
                tokens = progress.tokens
                cost_usd = progress.cost_usd
        # For devin sessions, these fields remain None (no structured stream)

        # Calculate budget remaining (if configured)
        budget_remaining = None
        if tokens is not None and self.config.watchdog.token_budget is not None:
            budget_remaining = max(0, self.config.watchdog.token_budget - tokens)
        elif cost_usd is not None and self.config.watchdog.cost_budget_usd is not None:
            budget_remaining = max(0, self.config.watchdog.cost_budget_usd - cost_usd)

        # Issue #1346: surface the watchdog's corroboration probe so an
        # alive-but-polling worker (stale sidecar log mtime, fresh
        # sessions.db / per-PID log / events.jsonl) is visibly distinguishable
        # from a genuinely stalled one. The probe is the same object
        # ``classify_worker_health`` consulted for ``health`` -- reusing it
        # here means the displayed classification and the displayed
        # corroboration come from one code path, never two. ``probe is None``
        # keeps the legacy shape for callers that did not compute one.
        corroboration_latest_at: str | None = None
        corroboration_latest_source: str | None = None
        corroboration_fresh: bool | None = None
        if isinstance(probe, RealActivityProbe):
            latest_ts = probe.latest_timestamp
            corroboration_latest_at = latest_ts.isoformat() if latest_ts is not None else None
            corroboration_latest_source = probe.latest_source
            corroboration_fresh = probe.is_fresh(self.config.watchdog.stall_minutes)

        return {
            "repo": repo,
            "issue": view.issue_number,
            "adapter": view.adapter_kind,
            "health": health.value,
            "runtime_seconds": view.runtime_seconds(),
            "last_activity_at": view.last_activity_at,
            "last_corroborated_activity_at": corroboration_latest_at,
            "last_corroborated_activity_source": corroboration_latest_source,
            "corroboration_fresh": corroboration_fresh,
            "tool_calls": tool_calls,
            "tokens": tokens,
            "cost_usd": cost_usd,
            "budget_remaining": budget_remaining,
        }

    @staticmethod
    def _write_json(path: Path, value: Any) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp_path = path.with_suffix(path.suffix + ".tmp")
        with tmp_path.open("w", encoding="utf-8") as handle:
            json.dump(value, handle, indent=2, sort_keys=True)
            handle.write("\n")
        tmp_path.replace(path)
